private func macppSurfaceAcknowledgementURL(_ name: String) -> URL {
    let stateHome = ProcessInfo.processInfo.environment["XDG_STATE_HOME"]
        ?? FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(".local/state", isDirectory: true)
            .path
    return URL(fileURLWithPath: stateHome, isDirectory: true)
        .appendingPathComponent("macpp", isDirectory: true)
        .appendingPathComponent(name)
}

private func acknowledgeMacppSurfaceDismissal(_ token: String) {
    let url = macppSurfaceAcknowledgementURL("surface-dismiss.ack")
    // macpp:silent-ok best-effort handshake write; a failed ack just leaves the requester to time out
    try? FileManager.default.createDirectory(
        at: url.deletingLastPathComponent(),
        withIntermediateDirectories: true
    )
    try? Data(token.utf8).write(to: url, options: [.atomic]) // macpp:silent-ok best-effort ack write; requester times out on failure
}

/// The public workspace session notifications cover fast-user switching, while
/// the current-session dictionary also reports the ordinary lock screen. Keep
/// this read optional: older systems can omit the key, in which case the
/// notification observers remain the source of truth.
private func currentNotificationSessionLockState() -> Bool? {
    guard let session = CGSessionCopyCurrentDictionary() as? [String: Any] else { return nil }
    return session["CGSSessionScreenIsLocked"] as? Bool
}

