/// Swift's remainder operator keeps the sign of its left operand. The
/// screensaver preview deliberately uses a deterministic signed hash, so an
/// unchecked `% glyphs.count` can become a negative Array index for perfectly
/// valid Mac++ scene names. Keep this one helper at the preview boundary so
/// every static renderer uses the same safe wrapping rule.
private func macppPositiveModulo(_ value: Int, _ modulus: Int) -> Int {
    guard modulus > 0 else { return 0 }
    let remainder = value % modulus
    return remainder >= 0 ? remainder : remainder + modulus
}

private let macppScreensaverSelectionURL: URL = {
    let configHome = ProcessInfo.processInfo.environment["XDG_CONFIG_HOME"]
        .flatMap { $0.isEmpty ? nil : URL(fileURLWithPath: $0, isDirectory: true) }
        ?? FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(".config", isDirectory: true)
    return configHome
        .appendingPathComponent("macpp", isDirectory: true)
        .appendingPathComponent("screensaver")
}()

private func macppCurrentScreensaverSelection() -> String {
    guard let raw = try? String(contentsOf: macppScreensaverSelectionURL, encoding: .utf8) else {
        return "cmatrix"
    }
    let value = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    return macppScreensaverChoices.contains(where: { $0.selection == value }) ? value : "cmatrix"
}

/// One source of truth for the upper rail's visible rhythm and the workspace
/// popover anchors derived from it. Keeping the interaction geometry tied to
/// these metrics lets the cluster be tightened without reintroducing the
/// bottom-workspace hover drift caused by stale magic numbers.
private enum SideRailGeometry {
    // Top and bottom used to share one `outerVerticalPadding` of 12. They are
    // not the same measurement: the top one is the gap between the screen's
    // physical edge and the Apple button, while the bottom one is what decides
    // how close Power sits to the bottom rim -- and because the middle of the
    // rail is held apart by Spacers, trimming the shared value moved Power
    // *down* every time the logo was moved *up*. Two constants so the two ends
    // can be tuned without arguing with each other.
    //
    // 7 rather than 12. The logo read as sitting too far from the top of the
    // screen, and the padding was only part of why: a 15pt glyph centred in a
    // 34pt frame contributes another ~9.5pt of its own, so the optical gap was
    // ~21pt while the number in the file said 12. Both were trimmed -- see
    // `logoHeight` below -- for a combined lift of about 6.5pt.
    static let outerTopPadding: CGFloat = CaelestiaParityTokens.Padding.large
    static let outerBottomPadding: CGFloat = CaelestiaParityTokens.Padding.large
    static let upperSpacing: CGFloat = CaelestiaParityTokens.Spacing.medium
    // Caelestia's workspace component is a 32pt inner indicator inside the
    // 40pt bar. The outer 60pt envelope supplies the 10pt border reserve.
    static let logoHeight: CGFloat = 30
    static let workspaceButtonSize: CGFloat =
        CaelestiaParityTokens.Sizes.barInnerWidth - CaelestiaParityTokens.Padding.small
    static let workspaceSpacing: CGFloat = CaelestiaParityTokens.Spacing.extraSmall
    static let workspaceVerticalPadding: CGFloat = CaelestiaParityTokens.Padding.extraSmall
    static let workspacePitch: CGFloat = workspaceButtonSize + workspaceSpacing
    static let firstWorkspaceCenterFromTop: CGFloat =
        outerTopPadding + logoHeight + upperSpacing
        + workspaceVerticalPadding + workspaceButtonSize / 2
    static let toolButtonHeight: CGFloat = 30
    static let toolStackVerticalPadding: CGFloat = 3
}

private func macppYabaiExecutableURL() -> URL? {
    MacPlusPlusYabaiConfiguration.executableURL()
}

// WindowServer exposes the active Space as a primitive ID. Use it directly in
// the hot path; keep Yabai's public Space list as a cached ID-to-label/type map
// for the five named Work Spaces and native-fullscreen classification.
private let macppSkyLightHandle: UnsafeMutableRawPointer? = dlopen(
    "/System/Library/PrivateFrameworks/SkyLight.framework/SkyLight",
    RTLD_LAZY
)

private func macppSkyLightSymbol(_ name: String) -> UnsafeMutableRawPointer? {
    guard let handle = macppSkyLightHandle else { return nil }
    return dlsym(handle, name)
}

private func macppActiveSpaceID() -> UInt64? {
    typealias MainConnection = @convention(c) () -> Int32
    typealias ActiveSpace = @convention(c) (Int32) -> UInt64
    guard let mainConnectionSymbol = macppSkyLightSymbol("SLSMainConnectionID"),
          let activeSpaceSymbol = macppSkyLightSymbol("SLSGetActiveSpace") else { return nil }
    let mainConnection = unsafeBitCast(mainConnectionSymbol, to: MainConnection.self)
    let activeSpace = unsafeBitCast(activeSpaceSymbol, to: ActiveSpace.self)
    return activeSpace(mainConnection())
}

private struct MacPlusPlusSpaceIndexEntry {
    let workspaceIndex: Int?
    let isNativeFullscreen: Bool
}

private enum MacPlusPlusSpaceIndexLookup {
    case known(MacPlusPlusSpaceIndexEntry)
    case unknown
    case unavailable
}

private enum MacPlusPlusSpaceIndexCache {
    private static let refreshQueue = DispatchQueue(
        label: "org.macplusplus.macpp.active-space-index-refresh",
        qos: .utility
    )
    private static let lock = NSLock()
    private static let backgroundRefreshInterval: TimeInterval = 15
    private static let unknownRefreshInterval: TimeInterval = 1
    private static var entriesByID: [UInt64: MacPlusPlusSpaceIndexEntry] = [:]
    private static var hasSnapshot = false
    private static var refreshPending = false
    private static var lastRefreshAttempt: CFTimeInterval = 0

    static func lookup(_ activeID: UInt64) -> MacPlusPlusSpaceIndexLookup {
        lock.lock()
        if let entry = entriesByID[activeID] {
            let now = ProcessInfo.processInfo.systemUptime
            let shouldRefresh = !refreshPending
                && now - lastRefreshAttempt >= backgroundRefreshInterval
            if shouldRefresh {
                refreshPending = true
                lastRefreshAttempt = now
            }
            lock.unlock()
            if shouldRefresh { refreshQueue.async { refreshSnapshot() } }
            return .known(entry)
        }

        let now = ProcessInfo.processInfo.systemUptime
        if refreshPending {
            let waitForInitialSnapshot = !hasSnapshot
            lock.unlock()
            if waitForInitialSnapshot {
                // Only startup waits for the first topology read. Known Space
                // changes never wait on this queue or launch another process.
                refreshQueue.sync {}
                return lookup(activeID)
            }
            return .unknown
        }

        let waitForInitialSnapshot = !hasSnapshot
        guard waitForInitialSnapshot || now - lastRefreshAttempt >= unknownRefreshInterval else {
            let snapshotExists = hasSnapshot
            lock.unlock()
            return snapshotExists ? .unknown : .unavailable
        }
        refreshPending = true
        lastRefreshAttempt = now
        lock.unlock()

        if waitForInitialSnapshot {
            refreshQueue.sync { refreshSnapshot() }
            lock.lock()
            let entry = entriesByID[activeID]
            let snapshotExists = hasSnapshot
            lock.unlock()
            if let entry { return .known(entry) }
            return snapshotExists ? .unknown : .unavailable
        }

        // New fullscreen Spaces have new IDs. Refresh their classification in
        // the background, and let callers preserve the last known workspace.
        refreshQueue.async { refreshSnapshot() }
        return .unknown
    }

    private static func refreshSnapshot() {
        let next = loadSnapshot()
        lock.lock()
        if let next {
            entriesByID = next
            hasSnapshot = true
        }
        refreshPending = false
        lock.unlock()
    }

    private static func loadSnapshot() -> [UInt64: MacPlusPlusSpaceIndexEntry]? {
        guard let yabaiExecutable = macppYabaiExecutableURL() else { return nil }
        let raw = capturedCommand(
            yabaiExecutable.path,
            ["-m", "query", "--spaces"],
            timeout: 1.0
        )
        guard let data = raw.data(using: .utf8) else { return nil }
        // macpp:silent-ok malformed yabai topology keeps the cached space index until its next refresh.
        guard let rows = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else {
            return nil
        }

        var entries: [UInt64: MacPlusPlusSpaceIndexEntry] = [:]
        for row in rows {
            guard let id = (row["id"] as? NSNumber)?.uint64Value else { continue }
            let isFullscreen = (row["is-native-fullscreen"] as? Bool) ?? false
            let label = (row["label"] as? String)?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let labeledIndex = label.flatMap { macppWorkspaceLabels.firstIndex(of: $0) }
                .map { $0 + 1 }
            let indexedFallback = (row["index"] as? NSNumber)?.intValue
            let workspaceIndex = isFullscreen
                ? nil
                : (labeledIndex ?? indexedFallback.flatMap {
                    (1...CaelestiaParityTokens.Sizes.workspaceCount).contains($0) ? $0 : nil
                })
            entries[id] = MacPlusPlusSpaceIndexEntry(
                workspaceIndex: workspaceIndex,
                isNativeFullscreen: isFullscreen
            )
        }
        return entries
    }
}

// Retain a bounded JSON fallback for systems where the read-only SkyLight ID
// lookup is unavailable or the topology query has not succeeded yet.
private enum MacPlusPlusActiveSpaceSnapshotCache {
    private static let queue = DispatchQueue(label: "org.macplusplus.macpp.active-space-json-fallback")
    private static let freshness: TimeInterval = 0.10
    private static var cachedAt: CFTimeInterval?
    private static var cachedSpace: [String: Any]?

    static func read(forceRefresh: Bool) -> [String: Any]? {
        queue.sync {
            let now = ProcessInfo.processInfo.systemUptime
            if !forceRefresh,
               let cachedAt,
               now - cachedAt < freshness {
                return cachedSpace
            }
            guard let yabaiExecutable = macppYabaiExecutableURL() else { return nil }
            let raw = capturedCommand(
                yabaiExecutable.path,
                ["-m", "query", "--spaces", "--space"],
                timeout: 1.0
            )
            guard let data = raw.data(using: .utf8) else { return nil }
            // macpp:silent-ok malformed active-space JSON preserves the prior UI state until the next refresh.
            guard let object = try? JSONSerialization.jsonObject(with: data),
                  let space = object as? [String: Any] else { return nil }
            cachedAt = ProcessInfo.processInfo.systemUptime
            cachedSpace = space
            return space
        }
    }
}

private func macppActiveSpaceSnapshot(forceRefresh: Bool = false) -> [String: Any]? {
    MacPlusPlusActiveSpaceSnapshotCache.read(forceRefresh: forceRefresh)
}

private func macppFastFocusedSpaceIndex(forceRefresh: Bool = false) -> Int? {
    if let activeID = macppActiveSpaceID() {
        switch MacPlusPlusSpaceIndexCache.lookup(activeID) {
        case .known(let entry): return entry.workspaceIndex
        case .unknown: return nil
        case .unavailable: break
        }
    }
    guard let space = macppActiveSpaceSnapshot(forceRefresh: forceRefresh) else { return nil }
    if let label = (space["label"] as? String)?
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased(),
       let index = macppWorkspaceLabels.firstIndex(of: label) {
        return index + 1
    }
    guard (space["is-native-fullscreen"] as? Bool) != true,
          let index = (space["index"] as? NSNumber)?.intValue,
          (1...CaelestiaParityTokens.Sizes.workspaceCount).contains(index) else { return nil }
    return index
}

private func macppFastActiveSpaceIsNativeFullscreen(forceRefresh: Bool = false) -> Bool? {
    if let activeID = macppActiveSpaceID() {
        switch MacPlusPlusSpaceIndexCache.lookup(activeID) {
        case .known(let entry): return entry.isNativeFullscreen
        case .unknown: return true
        case .unavailable: break
        }
    }
    guard let space = macppActiveSpaceSnapshot(forceRefresh: forceRefresh),
          let fullscreen = space["is-native-fullscreen"] as? Bool else { return nil }
    return fullscreen
}

@discardableResult
private func runMacPlusPlusYabai(_ arguments: [String], waitUntilExit: Bool = false) -> Bool {
    guard let yabaiExecutable = macppYabaiExecutableURL() else { return false }
    let process = Process()
    let errors = Pipe()
    process.executableURL = yabaiExecutable
    process.arguments = arguments
    process.standardOutput = FileHandle.nullDevice
    process.standardError = errors
    do {
        try process.run()
    } catch {
        MacPlusPlusBoundaryLog.record("yabai could not launch args=\(arguments) error=\(error)")
        return false
    }
    guard waitUntilExit else {
        process.terminationHandler = { finished in
            let detail = String(
                data: errors.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8
            )?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard finished.terminationStatus != 0 else { return }
            MacPlusPlusBoundaryLog.record(
                "yabai failed args=\(arguments) status=\(finished.terminationStatus)"
                    + (detail.isEmpty ? "" : " stderr=\(detail)")
            )
        }
        return true
    }
    let errorData = errors.fileHandleForReading.readDataToEndOfFile()
    process.waitUntilExit()
    guard process.terminationStatus == 0 else {
        let detail = String(data: errorData, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        MacPlusPlusBoundaryLog.record(
            "yabai failed args=\(arguments) status=\(process.terminationStatus)"
                + (detail.isEmpty ? "" : " stderr=\(detail)")
        )
        return false
    }
    return true
}

/// Reads the currently visible yabai space without changing focus. Window
/// transfers are background operations in MacPlusPlus; this lets the move path put
/// the user back on the space they were already looking at if yabai briefly
/// follows the moved window on a particular version/configuration.
private func macppFocusedSpaceLabel() -> String? {
    let pipe = Pipe()
    let process = Process()
    guard let yabaiExecutable = macppYabaiExecutableURL() else { return nil }
    process.executableURL = yabaiExecutable
    process.arguments = ["-m", "query", "--spaces", "--space"]
    process.standardOutput = pipe
    process.standardError = FileHandle.nullDevice
    guard (try? process.run()) != nil else { return nil } // macpp:silent-ok optional yabai is unavailable on first launch; the caller falls back to no focused-space label
    process.waitUntilExit()
    guard let data = try? pipe.fileHandleForReading.readToEnd(), // macpp:silent-ok yabai output is optional; the caller falls back to no focused-space label
          let object = try? JSONSerialization.jsonObject(with: data), // macpp:silent-ok malformed yabai output is treated as unavailable
          let space = object as? [String: Any] else { return nil }
    if let label = space["label"] as? String, !label.isEmpty { return label }
    if let index = space["index"] as? Int {
        return macppWorkspaceLabels.dropFirst(max(0, index - 1)).first
    }
    return nil
}

/// Returns the normal Work-space index currently reported by yabai.
///
/// The active rail dot is a live focus indicator, not part of the slower
/// surface snapshot. Keep this read numeric and authoritative: labels are a
/// user-facing convenience and may be absent while yabai is relabelling the
/// spaces during login or a Dock restart.
private func macppFocusedSpaceIndex(forceRefresh: Bool = false) -> Int? {
    return macppFastFocusedSpaceIndex(forceRefresh: forceRefresh)
}

/// Returns whether the currently focused yabai Space is a native macOS
/// fullscreen Space. The shell deliberately does not join those Spaces, so
/// notifications need a separate auxiliary presentation while one is active.
/// A missing/malformed yabai response is fail-closed: ordinary shell-attached
/// notifications remain the safe fallback instead of creating a floating
/// window unexpectedly.
private func macppActiveSpaceIsNativeFullscreen(forceRefresh: Bool = false) -> Bool {
    let environment = ProcessInfo.processInfo.environment
    if environment["MACPP_SHELL_VISUAL_TEST_SESSION"] == "1",
       environment["MACPP_SHELL_PREVIEW_NOTIFICATION_BUBBLE"] == "1" {
        return true
    }
    return macppFastActiveSpaceIsNativeFullscreen(forceRefresh: forceRefresh) ?? false
}

private func postAppCommandShortcut(_ keyCode: CGKeyCode) {
    guard let source = CGEventSource(stateID: .combinedSessionState),
          let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
          let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false) else {
        MacPlusPlusBoundaryLog.record(
            "app rail could not create command shortcut key=\(keyCode)",
            key: "app-rail-shortcut-\(keyCode)",
            minimumInterval: 60
        )
        return
    }
    keyDown.flags = .maskCommand
    keyUp.flags = .maskCommand
    keyDown.post(tap: .cghidEventTap)
    keyUp.post(tap: .cghidEventTap)
}

// Every rail surface uses the same optical content gutter. Individual
// silhouettes may reserve the attached smoothing band, but their information
// always begins and ends on this shared grid. These aliases keep the older
// layout call sites readable while making the contract live in one token set.
private let railPopoverContentGutter: CGFloat = CaelestiaParityTokens.Popout.contentGutter
private let railPopoverAttachedGutter: CGFloat = CaelestiaParityTokens.Popout.attachedGutter
private let railPopoverVerticalGutter: CGFloat = CaelestiaParityTokens.Popout.verticalGutter
private let railPopoverGroundedBottomGutter: CGFloat =
    CaelestiaParityTokens.Popout.groundedBottomGutter
// This is a content-inset reservation, not the physical curve radius (the
// actual shoulder/notch shape is drawn separately by frameMotion's own
// literal radius values). Shrinking it just lets content sit closer to
// that curve -- it doesn't change the curve's shape. 22 reserved more dead
// space on the attached edge of every side popover than the curve itself
// needed.
private let attachedSurfaceShoulder: CGFloat = CaelestiaParityTokens.Rounding.large
// A named rounding scale, mirroring caelestia's own small/normal/large steps
// (there it's 12/17/25). Corner radii across this file grew organically into
// one-off literals from 2 to 24 with no real system behind them; this gives
// new chrome (and any future cleanup pass over the old literals) a consistent
// small/medium/large/shell scale to draw from instead of picking a fresh
// number every time.
// Internal rather than private: the embedded MacPlusPlusCast build delegates
// `CastRounding` to this scale, the same way `CastMotion` already delegates to
// `ShellMotion`, so Search and the shell chrome it renders inside cannot drift
// onto two different rounding systems.
enum Rounding {
    // Two steps below `small`, added when the 47 off-scale `cornerRadius`
    // literals were catalogued: they run 1 to 20, and eight of them sit at 4-7,
    // which `small` at 8 could not absorb without visibly over-rounding a chip.
    static let hairline: CGFloat = CaelestiaParityTokens.Rounding.extraSmall
    static let extraSmall: CGFloat = CaelestiaParityTokens.Rounding.extraSmall
    static let tight: CGFloat = CaelestiaParityTokens.Rounding.extraSmall
    static let small: CGFloat = CaelestiaParityTokens.Rounding.small
    static let normal: CGFloat = CaelestiaParityTokens.Rounding.medium
    static let large: CGFloat = CaelestiaParityTokens.Rounding.large
    static let largeIncreased: CGFloat = CaelestiaParityTokens.Rounding.largeIncreased
    static let extraLarge: CGFloat = CaelestiaParityTokens.Rounding.extraLarge
    static let extraLargeIncreased: CGFloat = CaelestiaParityTokens.Rounding.extraLargeIncreased
    static let extraExtraLarge: CGFloat = CaelestiaParityTokens.Rounding.extraExtraLarge
    static let shell: CGFloat = CaelestiaParityTokens.Border.rounding
}

// The bottom-rail popouts' card sizing, in one place. First pass at the
// unified card system fixed every header/tile card at 42pt regardless of
// whether its content actually needed two lines -- correct for the
// two-line header (icon, title, subtitle) but needlessly tall for a
// single-line status readout (wifi's network name, battery's percent,
// activeApp's CPU/RAM), and the padding wasn't even between them (10 on
// header/tile cards, 9 on list rows). Two heights instead of one, one
// shared horizontal padding for every card.
private enum PopoverCard {
    /// Two-line header (icon + title + subtitle).
    static let headerHeight: CGFloat = 36
    /// One line of content: a status readout, a list row, a toggle row.
    static let rowHeight: CGFloat = 30
    static let horizontalPadding: CGFloat = 8
    /// The one vertical rhythm used between all cards in a rail popout.
    static let stackSpacing: CGFloat = CaelestiaParityTokens.Popout.rowSpacing
}

/// The shell is intentionally information-dense, but the type hierarchy is
/// still shared by every Nexus page. Keeping these sizes in one place makes a
/// small readability adjustment propagate to Overview, Audio Lab, Media, and
/// Settings together instead of leaving a page with a one-pixel mismatch.
///
/// The previous five steps (17/12/10.5/10/9) were called six times, while the
/// same file carried 261 literal `.system(size:)` values across 30 distinct
/// sizes. Five steps cannot absorb thirty sizes, which is the likeliest reason
/// nobody reached for them. These nine are fitted to the clusters the literals
/// actually formed rather than chosen as a ratio, so a conversion is a lookup
/// instead of a judgement.
///
/// Splitting the old single scale three ways is deliberate. Of those 261
/// declarations only 229 are text at all -- 32 size SF Symbols, which are
/// glyphs rather than type and belong on `ShellIcon` -- and 22 of the remaining
/// text sites are display readouts of 16pt and up, which have nothing to do
/// with a body scale and belong on `ShellDisplay`.
///
/// Every name the old five-step enum defined keeps its exact value, so all six
/// existing call sites render identically -- this commit adds steps, it does not
/// move any. The conversion of the 261 literals is a separate pass, and the
/// mapping it follows is in `docs/design-token-contract.md`.
///
/// Internal rather than private so the embedded MacPlusPlusCast build can
/// delegate `CastTypography` to it, exactly as `CastMotion` delegates to
/// `ShellMotion`.
enum ShellTypography {
    /// 6.5-8pt collapsed. See `preferredDesign` below: at this size the rounded
    /// face is the legibility problem, not the point size.
    static let nano: CGFloat = 8
    /// The 8.5/9 cluster, 55 sites -- the single largest band in the shell.
    static let micro: CGFloat = 9
    static let label: CGFloat = 10
    /// 10.5 carries two unrelated roles at the same size -- the tab strip and
    /// secondary detail copy -- exactly as the previous enum had it. Two names
    /// for one value is not duplication here; it is what lets one of them be
    /// retuned later without dragging the other with it.
    static let navigation: CGFloat = 10.5
    static let body: CGFloat = 10.5
    /// The largest single cluster of literals in the file, 30 of them, and they
    /// are overwhelmingly one thing: the title line of a popover card or a list
    /// row. `popoverCardTitle()` already sets exactly this.
    static let cardTitle: CGFloat = 11
    static let value: CGFloat = 12
    static let title: CGFloat = 13
    static let heading: CGFloat = 15
    static let section: CGFloat = 17

    /// 116 of the 261 declarations sat below 10pt and 84 at 8.5pt or below, and
    /// every one of the file's 274 font declarations asked for `.rounded` --
    /// which ships no small-optical-size variant, so its terminals soften
    /// exactly where a 7.5pt heavy glyph needs definition.
    ///
    /// The obvious fix is to raise the floor, but this shell cannot pay for it:
    /// its surfaces are fixed-size and masked, `topContentHeight` is already
    /// hand-compressed, and 33 `minimumScaleFactor` sites would quietly absorb
    /// an increase and hide whether it even took effect.
    ///
    /// So buy the legibility with the typeface instead of with points. At the
    /// two smallest steps the default SF face has the definition the rounded
    /// one lacks, and it sets slightly *narrower* at the same size -- so this
    /// costs no width in a `lineLimit(1)` row, where a size bump would have.
    static func preferredDesign(for size: CGFloat) -> Font.Design {
        size <= micro ? .default : .rounded
    }

    /// Never set shell type below this. `nano` is the floor, and it is only
    /// legible because `preferredDesign` moves it off the rounded face.
    static let legibilityFloor: CGFloat = nano
}

/// Large numeric readouts -- the clock, the big percentage on a performance
/// card, the standalone BPM. These are 22 of the 229 text sites and they behave
/// nothing like body copy: they are read at a glance, they are always numeric or
/// near-numeric, and each one lives in a card sized around it. They were the
/// long tail that stretched the old scale to 30 values.
///
/// Steps are ~1.15 apart. Snapping is to the nearest step, and the mapping was
/// chosen so nothing grows by more than 1pt.
private enum ShellDisplay {
    static let small: CGFloat = 16
    static let medium: CGFloat = 19
    static let large: CGFloat = 22
    static let xlarge: CGFloat = 25
    static let huge: CGFloat = 29
    static let hero: CGFloat = 40
}

/// SF Symbol point sizes. Separated from `ShellTypography` because a symbol is
/// a glyph on a fixed optical grid, not text: the legibility floor and the
/// `.default`/`.rounded` question below 10pt simply do not apply to it, and
/// mixing the two is what let a 14pt icon and a 14pt heading look like the same
/// decision when they never were.
// Internal so the embedded MacPlusPlusCast build can size its result-row
// symbols from the same scale as the shell chrome they sit beside.
enum ShellIcon {
    /// The rail and popover-row scale: 32 of the shell's icons sit here.
    static let small: CGFloat = 11
    static let medium: CGFloat = 13
    static let large: CGFloat = 15
    static let header: CGFloat = 18
    static let feature: CGFloat = 24
    static let hero: CGFloat = 30
}

/// The shell had no spacing system at all: every integer from 0 to 14 appeared
/// as a `spacing:` value and padding ran 0.4 to 28. 8pt led at 63 uses with 6
/// (26), 7 (26), 9 (24) and 10 (20) crowded around it -- the signature of many
/// separate sessions each independently picking "about eight", not of five
/// deliberate distinctions.
///
/// A 4pt base with 6 retained, because 6 is a real and useful step at this
/// density. `SideRailGeometry` and `PopoverCard` govern their own regions and
/// deliberately do not draw from this scale.
///
/// Snapping is to the nearest step, resolving ties *downward*. That rule is not
/// cosmetic: these surfaces are fixed-height and masked, so a stacked column
/// that rounds 7 up to 8 six times over is 6pt taller with nowhere to put it.
/// Rounding down makes the conversion safe by construction -- only `1 -> 2` and
/// `11 -> 12` grow at all, across 14 of the 276 sites.
private enum Spacing {
    static let none: CGFloat = 0
    static let hairline: CGFloat = 2
    static let tight: CGFloat = 4
    static let snug: CGFloat = 6
    /// The resting value. Where a gap has no reason to be anything else, it is
    /// this one.
    static let base: CGFloat = 8
    static let roomy: CGFloat = 12
    static let loose: CGFloat = 16
    // These aliases mirror the upstream QML names used by the Nexus page
    // hierarchy while retaining the shell's existing local vocabulary.
    static let extraSmall: CGFloat = tight
    static let small: CGFloat = base
    static let medium: CGFloat = roomy
    static let large: CGFloat = loose
    static let largeIncreased: CGFloat = CaelestiaParityTokens.Spacing.largeIncreased
    static let section: CGFloat = 24
}
// Content clears the reverse shoulder before its optical gutter begins. The
// attached edge uses the smoothing band; the opposite edge and both vertical
// edges use the same 12pt content gutter. The vertical inset therefore
// includes the 20pt geometric shoulder plus that 12pt visible gutter: a pill
// cannot be placed in the shoulder and then be clipped flat by the contour.
private let leftPopoverLeadingInset: CGFloat = railPopoverAttachedGutter
private let leftPopoverVerticalInset: CGFloat =
    CaelestiaParityTokens.Border.smoothing + railPopoverVerticalGutter
// The bottom-rail hover popouts follow Caelestia's component width families as
// lower bounds. Network, Bluetooth, Audio, and Battery can contract or grow
// from their actual row text; the bounds keep a short status from becoming a
// cramped pill while still avoiding a fixed empty desktop-side tail.
private let railPopoverCardWidth: CGFloat = CaelestiaParityTokens.Sizes.barNetworkWidth
private let powerTrailingInset: CGFloat =
    railPopoverAttachedGutter
private let edgeControlsWidth: CGFloat = 65
// The edge rail is flush with the monitor boundary. Keep the contour where it
// is, but give the slider column a small outward optical nudge so the controls
// do not look buried in the shell-side gutter.
private let edgeControlsOutsideShift: CGFloat = 4
// The geometric shoulder `ShellSurfaceMorphShape` actually carves out of every
// attached surface, as opposed to `attachedSurfaceShoulder` above, which is the
// smaller *optical* reserve side popovers use because their content may sit a
// little inside the curve's bulge without visibly clipping. Anything that must
// not be cut has to clear the full geometric value.
// Caelestia's BlobGroup uses a 20pt smoothing band at connected joins. The
// previous 28pt shoulder made a side popout read like an oversized rounded
// card with a clipped left edge; the join must be tighter than the shell's
// 25pt rounding so the reverse gutter remains visible.
private let surfaceMorphShoulder: CGFloat = CaelestiaParityTokens.Border.smoothing
private let edgeControlsHeight: CGFloat = 316
// Give the two edge controls a little more usable travel while keeping both
// ends inside the attached surface's reserved shoulder area.
private let edgeLevelControlHeight: CGFloat = 112
// A right-attached contour spends one shoulder at its top and one at its bottom
// exactly like the left-attached popovers do, so the panel's full height is not
// usable layout space. Laying the sliders out against `edgeControlsHeight` put
// their ends outside the mask, where they were silently clipped -- the volume
// and brightness tracks visibly lost their top and bottom caps. Every left
// popover already reserves this through `leftPopoverVerticalInset`; the edge
// controls were the one attached surface that never did.
private let edgeControlsBodyHeight: CGFloat =
    edgeControlsHeight - surfaceMorphShoulder * 2
// Two columns now instead of three (the menu dropped lock/display-off down
// to caelestia's real four session actions) -- narrower so tiles keep a
// similar width/proportion instead of stretching to fill the old 3-wide box.
// This geometry now only serves the legacy centered PowerMenu grid (only
// reachable via the MACPP_SHELL_PREVIEW_EDGE debug hook, not live UI). The
// actual rail-triggered session drawer below has its own, different shape.
private let powerContentWidth: CGFloat = 260
private let powerSurfaceWidth: CGFloat =
    railPopoverContentGutter + powerContentWidth + powerTrailingInset
private let powerContentTopInset: CGFloat = attachedSurfaceShoulder + railPopoverContentGutter
private let powerContentBottomInset: CGFloat = railPopoverContentGutter
private let powerGridRowCount: CGFloat = 3
private let powerGridRowGap: CGFloat = 8
private let powerTileHeight: CGFloat = 58
private let powerContentHeight: CGFloat =
    powerTileHeight * powerGridRowCount + powerGridRowGap * (powerGridRowCount - 1)
private let powerSurfaceHeight: CGFloat =
    powerContentHeight + powerContentTopInset + powerContentBottomInset
// The live session drawer: a right-edge panel with a vertical stack of all
// five actions (one column, five rows) instead of a 2x2 grid, matching
// caelestia's actual session panel. Width/height are independent of the
// legacy PowerMenu geometry above since the row counts differ (4 vs 2).
// Narrow and icon-only rather than wide text rows -- text moved to
// tooltips -- but still wide enough that the occasional shutdown/restart
// confirmation card (which does need to show a couple words) isn't cramped.
// 92 rather than 108. With the buttons now filling their row instead of
// sitting as a fixed square inside it, the drawer no longer needs slack
// around them -- and a narrower panel puts the button's width and height in
// proportion (92 x ~64) instead of a small icon lost in a wide column.
private let sessionDrawerWidth: CGFloat = CaelestiaParityTokens.Sizes.sessionButton
private let sessionRowHeight: CGFloat = CaelestiaParityTokens.Sizes.sessionButton
// 10 rather than 42. The wide gaps were there to give the drawer a tall
// presence, but combined with fixed-size square buttons they produced 358pt
// of column holding 232pt of button -- the buttons read as sparse dots
// rather than a session menu. The drawer keeps a deliberate vertical
// presence through the button height itself now, not through empty space.
private let sessionRowGap: CGFloat = CaelestiaParityTokens.Spacing.medium
// Derived from the action count rather than a literal 4, so adding or removing
// a session command resizes the drawer instead of silently compressing every
// row -- the layout divides this height by `actions.count`.
private let sessionDrawerRowCount: CGFloat = 5
private let sessionDrawerContentHeight: CGFloat =
    sessionRowHeight * sessionDrawerRowCount + sessionRowGap * (sessionDrawerRowCount - 1)
private let sessionDrawerSurfaceWidth: CGFloat =
    railPopoverContentGutter + sessionDrawerWidth + leftPopoverLeadingInset
private let sessionDrawerSurfaceHeight: CGFloat =
    sessionDrawerContentHeight + leftPopoverVerticalInset * 2
private let sidebarWidth: CGFloat = CaelestiaParityTokens.Sizes.sidebarWidth
private let launcherSurfaceWidth: CGFloat = CaelestiaParityTokens.Sizes.launcherItemWidth
private let launcherNexusSurfaceWidth: CGFloat = CaelestiaParityTokens.Sizes.launcherNexusWidth
// Wallpapers share Nexus's broad envelope, but keep the carousel height
// shallow. The outer LauncherView was already 960pt wide; leaving this inner
// surface at the old 600pt Search width made the cards hug the left side and
// left the new wallpaper panel looking unchanged.
private let wallpaperCarouselSurfaceWidth: CGFloat = launcherNexusSurfaceWidth
// BottomMorphShape narrows the attached surface by this amount before its
// lower shoulders round inward. Full-width editor content was therefore
// painted underneath the mask and looked clipped at both sides.
private let launcherSurfaceShoulder: CGFloat = 22
// The shallow bottom carousels share one authored stack: 205pt of cards, dots,
// and padding inside a 248pt surface. Keep the spare space as a modest bottom
// alignment allowance without pushing the card row too far from the top.
private let bottomCarouselOutsideShift: CGFloat = 20
// The top-frame studio carries several terse controls in one row.  Keep it
// wide enough that its labels can use genuinely legible sizes instead of
// shrinking typography to make the old 560pt layout fit.
private let shellStudioWidth: CGFloat = 720
// All four tabs share one content plane so the attached silhouette never
// resizes while a pointer crosses the tab strip. The old 212pt plane was sized
// around Dashboard even though Media, Workspaces and the width-limited gauges
// occupy only 170pt, 176pt and 151pt respectively. A 184pt plane brings those
// pages within 4--16.5pt of the viewport edge; Dashboard is manually tightened
// below so its typography and controls remain at their authored sizes.
private let topContentHeight: CGFloat = 184
// The shell's continuous layers are decorative, not video playback. A 120 Hz
// ceiling keeps motion fluid on the 240 Hz ultrawide while preventing a
// marquee or surface transition from asking WindowServer to composite the
// entire top panel at the display's maximum cadence.
private let shellAnimationFrameRateCap: Float = 120
private func shellAnimationRefreshRate(for screen: NSScreen?) -> Float {
    min(
        shellAnimationFrameRateCap,
        max(60, Float(screen?.maximumFramesPerSecond ?? NSScreen.main?.maximumFramesPerSecond ?? 60))
    )
}
// Preserve the proven 32pt difference between camera-bearing and flat rims.
// Only the shared content plane is 28pt shorter; its 15pt outer tail and both
// rim offsets stay unchanged: 330 -> 302 notched, 298 -> 270 flat/clamshell.
private let notchedTopSurfaceHeight: CGFloat = 302
private let flatTopSurfaceHeight: CGFloat = 270
private func topSurfaceHeight(for topDepth: CGFloat) -> CGFloat {
    topDepth > shellFrame + 0.5 ? notchedTopSurfaceHeight : flatTopSurfaceHeight
}
private func leftAttachmentOrigin(on screen: NSScreen) -> CGFloat {
    // Popouts begin at the rail's inner edge and unfold into the desktop;
    // no hidden stem is composited underneath the physical frame.
    screen.frame.minX + railWidth
}

/// Which applications are currently sending audio to the output device.
///
/// This is the whole question the now-playing indicator needs answered, and
/// macOS answers it directly: CoreAudio keeps a process object per audio
/// client, each of which reports whether it is actively running output and
/// which PID it belongs to. A PID maps straight to an application name.
///
/// Earlier attempts went through the *media metadata* pipeline instead --
/// MediaRemote, track titles, Safari JavaScript -- and inherited all of its
/// failure modes. MediaRemote is entitlement-restricted on current macOS, so
/// anything that was not Spotify (which is read over AppleScript directly)
/// simply never appeared. None of that matters here: an app either has audio
/// running or it does not, whatever it is playing and whether or not it
/// publishes metadata at all.
private enum AudioOutputProcesses {
    struct Snapshot: Sendable {
        let names: Set<String>
        let error: String?
    }

    static func snapshot() -> Snapshot {
        guard #available(macOS 14.2, *) else {
            return Snapshot(names: [], error: "CoreAudio process objects require macOS 14.2")
        }
        var listAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyProcessObjectList,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var dataSize: UInt32 = 0
        let sizeStatus = AudioObjectGetPropertyDataSize(
            AudioObjectID(kAudioObjectSystemObject), &listAddress, 0, nil, &dataSize
        )
        guard sizeStatus == noErr else {
            return Snapshot(names: [], error: "process-list size OSStatus \(sizeStatus)")
        }
        guard dataSize > 0 else { return Snapshot(names: [], error: nil) } // macpp:silent-ok an empty CoreAudio process list is a valid empty snapshot

        let count = Int(dataSize) / MemoryLayout<AudioObjectID>.size
        var objects = [AudioObjectID](repeating: 0, count: count)
        let listStatus = AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &listAddress, 0, nil, &dataSize, &objects
        )
        guard listStatus == noErr else {
            return Snapshot(names: [], error: "process-list read OSStatus \(listStatus)")
        }

        var names: Set<String> = []
        for object in objects {
            var runningAddress = AudioObjectPropertyAddress(
                mSelector: kAudioProcessPropertyIsRunningOutput,
                mScope: kAudioObjectPropertyScopeGlobal,
                mElement: kAudioObjectPropertyElementMain
            )
            var running: UInt32 = 0
            var runningSize = UInt32(MemoryLayout<UInt32>.size)
            guard AudioObjectGetPropertyData(
                object, &runningAddress, 0, nil, &runningSize, &running
            ) == noErr, running != 0 else { continue }

            var pidAddress = AudioObjectPropertyAddress(
                mSelector: kAudioProcessPropertyPID,
                mScope: kAudioObjectPropertyScopeGlobal,
                mElement: kAudioObjectPropertyElementMain
            )
            var pid: pid_t = 0
            var pidSize = UInt32(MemoryLayout<pid_t>.size)
            guard AudioObjectGetPropertyData(
                object, &pidAddress, 0, nil, &pidSize, &pid
            ) == noErr, pid > 0 else { continue }

            guard let application = NSRunningApplication(processIdentifier: pid),
                  let name = application.localizedName, !name.isEmpty else { continue }
            names.insert(name)
        }
        return Snapshot(names: names, error: nil) // macpp:silent-ok the snapshot has no additional error to report
    }
}

/// Which applications are currently downloading a file.
///
/// Every browser writes its in-progress download to a distinctively named
/// placeholder next to the finished file, which gives per-application
/// attribution without inspecting any process: Safari uses `.download`,
/// Chrome `.crdownload`, Firefox `.part`, and so on. A placeholder exists for
/// the whole transfer and its modification date advances as bytes arrive, so a
/// recent mtime is a good "still going" test and a stale one means the
/// download stalled or the app died leaving the file behind.
private enum DownloadActivity {
    /// Placeholder extension -> the application it belongs to.
    private static let owners: [String: String] = [
        "download": "Safari",
        "crdownload": "Google Chrome",
        "part": "Firefox",
        "partial": "Microsoft Edge",
        "opdownload": "Opera"
    ]

    /// How recently a placeholder must have grown to count as active.
    private static let freshness: TimeInterval = 20

    static func runningAppNames() -> Set<String> {
        let manager = FileManager.default
        let home = manager.homeDirectoryForCurrentUser
        // Downloads is where browsers put these by default; Desktop is the
        // other common choice.
        let folders = [
            home.appendingPathComponent("Downloads", isDirectory: true),
            home.appendingPathComponent("Desktop", isDirectory: true)
        ]
        var names: Set<String> = []
        let now = Date()
        for folder in folders {
            guard let entries = try? manager.contentsOfDirectory( // macpp:silent-ok an unreadable optional activity folder contributes no active downloads
                at: folder,
                includingPropertiesForKeys: [.contentModificationDateKey, .isDirectoryKey],
                options: [.skipsHiddenFiles]
            ) else { continue }
            for entry in entries {
                // Safari's placeholder is a *package*, not a plain file, so
                // directories must not be skipped here.
                guard let owner = owners[entry.pathExtension.lowercased()] else { continue }
                let modified = (try? entry.resourceValues(forKeys: [.contentModificationDateKey]))? // macpp:silent-ok a missing mtime makes this optional activity entry stale
                    .contentModificationDate ?? .distantPast
                guard now.timeIntervalSince(modified) < freshness else { continue }
                names.insert(owner)
            }
        }
        return names
    }
}

/// macOS keeps individual AirPlay speakers behind a generic HAL `AirPlay`
/// endpoint.  If a route is surfaced by the system UI but not as a writable
/// AudioDeviceID, this small fallback uses the public Sound Settings pane's
/// accessibility tree to select the exact row.  It is invoked only after the
/// modern and legacy CoreAudio setters fail, so ordinary outputs never open
/// System Settings.
private func macppSelectSystemSoundOutput(named name: String) -> Bool {
    let script = """
    on run argv
        set wanted to item 1 of argv
        set settingsWasRunning to application "System Settings" is running
        tell application "System Settings"
            activate
            reveal anchor "output" of pane id "com.apple.Sound-Settings.extension"
            delay 0.8
            -- The second reveal expands the output list on macOS 26.
            reveal anchor "output" of pane id "com.apple.Sound-Settings.extension"
            delay 0.8
        end tell
        set didSelect to false
        tell application "System Events"
            tell process "System Settings"
                try
                    set deviceList to (every row of outline 1 of scroll area 1 of group 2 of scroll area 1 of group 1 of group 3 of splitter group 1 of group 1 of window "Sound")
                on error
                    try
                        set deviceList to (every row of outline 1 of scroll area 1 of group 2 of scroll area 1 of group 1 of group 2 of splitter group 1 of group 1 of window "Sound")
                    on error
                        set deviceList to {}
                    end try
                end try
                repeat with deviceRow in deviceList
                    try
                        set rowName to (value of static text of (group 1 of UI element 1) of deviceRow) as text
                        if rowName is equal to wanted then
                            set selected of deviceRow to true
                            set didSelect to true
                            exit repeat
                        end if
                    end try
                end repeat
            end tell
        end tell
        if didSelect then delay 0.7
        if not settingsWasRunning then
            tell application "System Settings" to quit
        end if
        return didSelect
    end run
    """
    let process = Process()
    let input = Pipe()
    let output = Pipe()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
    process.arguments = ["-", name]
    process.standardInput = input
    process.standardOutput = output
    process.standardError = FileHandle.nullDevice
    guard (try? process.run()) != nil else { return false } // macpp:silent-ok osascript launch failure is returned to the route selector
    if let data = script.data(using: .utf8) {
        try? input.fileHandleForWriting.write(contentsOf: data) // macpp:silent-ok best-effort AppleScript input; process status remains authoritative
    }
    try? input.fileHandleForWriting.close() // macpp:silent-ok closing an already-closed AppleScript pipe is harmless cleanup
    process.waitUntilExit()
    guard process.terminationStatus == 0 else { return false }
    let result = String(
        data: output.fileHandleForReading.readDataToEndOfFile(),
        encoding: .utf8
    )?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    return result == "true"
}

/// Some displays and AirPlay/HomePod routes deliberately expose no writable
/// volume property through their AudioDeviceID. The system volume command is
/// still the public control path macOS uses for those aggregate outputs.
private func macppSetSystemOutputVolume(_ value: Double) -> Bool {
    let percent = Int((min(1, max(0, value)) * 100).rounded())
    // AppleScript's volume command has presence-only mute parameters: `with
    // output muted` mutes, while `without output muted` explicitly unmutes.
    // Supplying a Boolean after the parameter is a syntax error on current
    // macOS and leaves the output volume untouched.
    let muteClause = percent == 0 ? "with output muted" : "without output muted"
    let process = Process()
    let output = Pipe()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
    process.arguments = [
        "-e",
        "set volume output volume \(percent) \(muteClause)"
    ]
    process.standardOutput = output
    process.standardError = FileHandle.nullDevice
    // macpp:silent-ok osascript may be unavailable during shutdown; the caller reports a failed write.
    guard (try? process.run()) != nil else { return false }
    process.waitUntilExit()
    return process.terminationStatus == 0
}

private func macppReadSystemOutputVolume() -> (volume: Double, muted: Bool)? {
    let process = Process()
    let output = Pipe()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
    process.arguments = ["-e", "get volume settings"]
    process.standardOutput = output
    process.standardError = FileHandle.nullDevice
    // macpp:silent-ok an unavailable osascript reader means the UI keeps its last known route state.
    guard (try? process.run()) != nil else { return nil }
    process.waitUntilExit()
    guard process.terminationStatus == 0,
          let text = String(
              data: output.fileHandleForReading.readDataToEndOfFile(),
              encoding: .utf8
          ) else { return nil }
    let volume = text
        .split(separator: ",")
        .first(where: { $0.contains("output volume:") })
        .flatMap { Int($0.split(separator: ":").last ?? "") }
    let muted = text
        .split(separator: ",")
        .first(where: { $0.contains("output muted:") })
        .map { $0.split(separator: ":").last?.trimmingCharacters(in: .whitespacesAndNewlines) == "true" }
    guard let volume, let muted else { return nil }
    return (Double(volume) / 100, muted)
}

private enum SystemOutputAudio {
    struct Device: Identifiable, Hashable {
        let id: AudioDeviceID
        let name: String
        let uid: String
        let sampleRate: Double
        // AirPlay destinations are discovered through Bonjour and selected
        // through Sound Settings; they do not have independent HAL IDs.
        // Keeping a route key lets duplicate friendly names (two Living Room
        // endpoints) remain distinct in SwiftUI.
        let routeID: String?

        init(
            id: AudioDeviceID,
            name: String,
            uid: String,
            sampleRate: Double,
            routeID: String? = nil
        ) {
            self.id = id
            self.name = name
            self.uid = uid
            self.sampleRate = sampleRate
            self.routeID = routeID
        }

        var identity: String {
            routeID.map { "airplay:\($0)" } ?? "device:\(id)"
        }

        var isAirPlayRoute: Bool { routeID != nil }
    }

    private static var observedDevice: AudioDeviceID?
    private static var deviceListener: AudioObjectPropertyListenerBlock?
    private static var defaultDeviceListener: AudioObjectPropertyListenerBlock?
    private static var observationHandler: (() -> Void)?
    private static let systemVolumeFallbackQueue = DispatchQueue(
        label: "\(macppShellDomain).system-volume-fallback",
        qos: .userInitiated
    )
    private static let systemVolumeFallbackLock = NSLock()
    private static var systemVolumeFallbackGeneration: UInt = 0
    private static var systemVolumeFallbackWorkItem: DispatchWorkItem?

    private static func defaultDevice() -> AudioDeviceID? {
        var address = AudioObjectPropertyAddress(
            // Volume belongs to the default *output* route. The system-sounds
            // route can legitimately be different (for example, AirPlay is
            // the output while a monitor remains the alert route), and using
            // that separate selector made the HomePod slider target the
            // monitor instead of the active speaker.
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var device = AudioDeviceID(0)
        var size = UInt32(MemoryLayout<AudioDeviceID>.size)
        guard AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size, &device) == noErr,
              device != AudioDeviceID(kAudioObjectUnknown) else { return nil }
        return device
    }

    private static func address(
        _ selector: AudioObjectPropertySelector,
        element: UInt32 = kAudioObjectPropertyElementMain
    ) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(
            mSelector: selector,
            mScope: kAudioDevicePropertyScopeOutput,
            mElement: element
        )
    }

    private static let scalarElements: [UInt32] = [
        kAudioObjectPropertyElementMain, UInt32(1), UInt32(2)
    ]

    private static func readScalar(for device: AudioDeviceID) -> Float32? {
        // Read the channel scalars first. The optional device path intentionally writes
        // these properties directly, and some devices leave the virtual-main
        // property unchanged when a channel is changed by another client.
        // Returning the virtual value first made every shell slider look
        // frozen even though the output itself had moved.
        var values: [Float32] = []
        for element in scalarElements {
            var scalarAddress = address(kAudioDevicePropertyVolumeScalar, element: element)
            guard AudioObjectHasProperty(device, &scalarAddress) else { continue }
            var scalar = Float32(0)
            var scalarSize = UInt32(MemoryLayout<Float32>.size)
            if AudioObjectGetPropertyData(device, &scalarAddress, 0, nil, &scalarSize, &scalar) == noErr {
                values.append(scalar)
            }
        }
        if !values.isEmpty {
            return values.reduce(0, +) / Float32(values.count)
        }

        // A few aggregate-only routes expose only the virtual master.
        var virtualAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        var virtualValue = Float32(0)
        var virtualSize = UInt32(MemoryLayout<Float32>.size)
        guard AudioObjectGetPropertyData(device, &virtualAddress, 0, nil, &virtualSize, &virtualValue) == noErr else {
            return nil
        }
        return virtualValue
    }

    static func read() -> (volume: Double, muted: Bool)? {
        guard let device = defaultDevice() else { return nil }
        guard let scalar = readScalar(for: device) else { return nil }

        var muteAddress = address(kAudioDevicePropertyMute)
        var mute = UInt32(0)
        var muteSize = UInt32(MemoryLayout<UInt32>.size)
        if AudioObjectGetPropertyData(device, &muteAddress, 0, nil, &muteSize, &mute) != noErr { mute = 0 }
        return (Double(scalar), mute != 0)
    }

    /// The system command is only needed for aggregate outputs without a
    /// writable HAL scalar. Keep it off the main actor because launching
    /// AppleScript can take a noticeable fraction of a second on a sleeping
    /// or newly-awakened AirPlay route.
    static func readSystemVolume() -> (volume: Double, muted: Bool)? {
        macppReadSystemOutputVolume()
    }

    static func write(_ value: Double) {
        guard let device = defaultDevice() else {
            scheduleSystemVolumeFallback(value)
            return
        }
        var scalar = Float32(min(1, max(0, value)))
        let scalarSize = UInt32(MemoryLayout<Float32>.size)
        var wroteVolume = false
        // Keep both representations in sync. On devices with a virtual
        // master this is normally one successful write plus two harmless
        // no-ops; on USB/monitor routes the channel writes are the usable
        // path. Doing both is what makes a shell-originated drag immediately
        // visible to the device bridge as well.
        var virtualAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        if AudioObjectHasProperty(device, &virtualAddress),
           AudioObjectSetPropertyData(device, &virtualAddress, 0, nil, scalarSize, &scalar) == noErr {
            wroteVolume = true
        }
        for element in scalarElements {
            var scalarAddress = address(kAudioDevicePropertyVolumeScalar, element: element)
            guard AudioObjectHasProperty(device, &scalarAddress) else { continue }
            if AudioObjectSetPropertyData(device, &scalarAddress, 0, nil, scalarSize, &scalar) == noErr {
                wroteVolume = true
            }
        }

        var muteAddress = address(kAudioDevicePropertyMute)
        var mute: UInt32 = scalar <= 0.001 ? 1 : 0
        let muteSize = UInt32(MemoryLayout<UInt32>.size)
        if AudioObjectHasProperty(device, &muteAddress) {
            _ = AudioObjectSetPropertyData(device, &muteAddress, 0, nil, muteSize, &mute)
        }

        if wroteVolume {
            cancelSystemVolumeFallback()
        } else {
            // AirPlay/HomePod aggregates and some monitor outputs have no
            // writable scalar at all. Coalesce a fast scroll gesture into
            // one latest-value command so the fallback remains responsive
            // without spawning an osascript process for every wheel tick.
            scheduleSystemVolumeFallback(value)
        }
    }

    private static func cancelSystemVolumeFallback() {
        systemVolumeFallbackLock.lock()
        systemVolumeFallbackGeneration &+= 1
        systemVolumeFallbackWorkItem?.cancel()
        systemVolumeFallbackWorkItem = nil
        systemVolumeFallbackLock.unlock()
    }

    private static func scheduleSystemVolumeFallback(_ value: Double) {
        systemVolumeFallbackLock.lock()
        systemVolumeFallbackGeneration &+= 1
        let generation = systemVolumeFallbackGeneration
        systemVolumeFallbackWorkItem?.cancel()
        let work = DispatchWorkItem {
            systemVolumeFallbackLock.lock()
            let current = generation == systemVolumeFallbackGeneration
            systemVolumeFallbackLock.unlock()
            guard current else { return }

            _ = macppSetSystemOutputVolume(value)

            systemVolumeFallbackLock.lock()
            if generation == systemVolumeFallbackGeneration {
                systemVolumeFallbackWorkItem = nil
            }
            systemVolumeFallbackLock.unlock()
        }
        systemVolumeFallbackWorkItem = work
        systemVolumeFallbackLock.unlock()
        systemVolumeFallbackQueue.asyncAfter(deadline: .now() + 0.04, execute: work)
    }

    static func observeChanges(_ handler: @escaping () -> Void) {
        observationHandler = handler
        rebindDeviceListener()
        guard defaultDeviceListener == nil else { return }
        let listener: AudioObjectPropertyListenerBlock = { _, _ in
            rebindDeviceListener()
            observationHandler?()
        }
        defaultDeviceListener = listener
        var defaultOutputAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        AudioObjectAddPropertyListenerBlock(
            AudioObjectID(kAudioObjectSystemObject),
            &defaultOutputAddress,
            .main,
            listener
        )
    }

    private static func rebindDeviceListener() {
        let nextDevice = defaultDevice()
        guard nextDevice != observedDevice else { return }

        if let previous = observedDevice, let listener = deviceListener {
            var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
            var muteAddress = address(kAudioDevicePropertyMute)
            AudioObjectRemovePropertyListenerBlock(previous, &volumeAddress, .main, listener)
            AudioObjectRemovePropertyListenerBlock(previous, &muteAddress, .main, listener)
            for element in scalarElements {
                var scalarAddress = address(kAudioDevicePropertyVolumeScalar, element: element)
                AudioObjectRemovePropertyListenerBlock(previous, &scalarAddress, .main, listener)
            }
        }

        observedDevice = nextDevice
        deviceListener = nil
        guard let nextDevice else { return }
        let listener: AudioObjectPropertyListenerBlock = { _, _ in observationHandler?() }
        deviceListener = listener
        var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        var muteAddress = address(kAudioDevicePropertyMute)
        AudioObjectAddPropertyListenerBlock(nextDevice, &volumeAddress, .main, listener)
        AudioObjectAddPropertyListenerBlock(nextDevice, &muteAddress, .main, listener)
        for element in scalarElements {
            var scalarAddress = address(kAudioDevicePropertyVolumeScalar, element: element)
            AudioObjectAddPropertyListenerBlock(nextDevice, &scalarAddress, .main, listener)
        }
    }

    private static func stringProperty(
        _ selector: AudioObjectPropertySelector,
        on object: AudioObjectID
    ) -> String? {
        var address = AudioObjectPropertyAddress(
            mSelector: selector,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var value: Unmanaged<CFString>?
        var size = UInt32(MemoryLayout<Unmanaged<CFString>?>.size)
        guard AudioObjectGetPropertyData(object, &address, 0, nil, &size, &value) == noErr else { return nil }
        return value?.takeUnretainedValue() as String?
    }

    private static func nominalSampleRate(of device: AudioDeviceID) -> Double {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyNominalSampleRate,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var value = Float64(0)
        var size = UInt32(MemoryLayout<Float64>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &value) == noErr else { return 0 }
        return value
    }

    private static func hasOutputStreams(_ device: AudioDeviceID) -> Bool {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyStreams,
            mScope: kAudioDevicePropertyScopeOutput,
            mElement: kAudioObjectPropertyElementMain
        )
        var size: UInt32 = 0
        return AudioObjectGetPropertyDataSize(device, &address, 0, nil, &size) == noErr && size > 0
    }

    private static func isAlive(_ device: AudioDeviceID) -> Bool {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyDeviceIsAlive,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var alive: UInt32 = 0
        var size = UInt32(MemoryLayout<UInt32>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &alive) == noErr else {
            // A few built-in/virtual devices do not expose the liveness
            // property. Their stream list is still the reliable fallback.
            return true
        }
        return alive != 0
    }

    static func outputDevices() -> [Device] {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDevices,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var size: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(
            AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size
        ) == noErr else { return [] }
        let count = Int(size) / MemoryLayout<AudioDeviceID>.size
        guard count > 0 else { return [] }
        var ids = Array(repeating: AudioDeviceID(0), count: count)
        guard AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size, &ids
        ) == noErr else { return [] }
        return ids.compactMap { id in
            guard isAlive(id), hasOutputStreams(id) else { return nil }
            let name = stringProperty(kAudioObjectPropertyName, on: id) ?? "Audio Device"
            let uid = stringProperty(kAudioDevicePropertyDeviceUID, on: id) ?? String(id)
            return Device(id: id, name: name, uid: uid, sampleRate: nominalSampleRate(of: id))
        }
        .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
    }

    /// Bonjour is the discovery channel macOS itself uses for AirPlay
    /// destinations.  CoreAudio intentionally exposes those destinations as
    /// one generic `AirPlay` device, so this read-only browse fills in the
    /// friendly child names that users see in Sound Settings.  It runs only
    /// on the refresh path and is normally called on a utility queue.
    static func airPlayRouteDevices() -> [Device] {
        struct Route {
            let name: String
            let key: String
        }

        func browse(_ service: String) -> [Route] {
            let process = Process()
            let pipe = Pipe()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/dns-sd")
            process.arguments = ["-B", service, "local"]
            process.standardOutput = pipe
            process.standardError = FileHandle.nullDevice
            guard (try? process.run()) != nil else { return [] } // macpp:silent-ok unavailable Bonjour browsing yields no discovered routes

            // dns-sd is intentionally long-lived. A short bounded browse is
            // enough because Bonjour sends the current Add records immediately
            // and keeps the shell from retaining any network process.
            Thread.sleep(forTimeInterval: 0.35)
            process.terminate()
            process.waitUntilExit()
            let text = String(
                data: pipe.fileHandleForReading.readDataToEndOfFile(),
                encoding: .utf8
            ) ?? ""
            let marker = "\(service)."
            return text.split(whereSeparator: { $0.isNewline }).compactMap { rawLine in
                let line = String(rawLine)
                guard line.contains(" Add "),
                      let markerRange = line.range(of: marker) else { return nil }
                let instance = line[markerRange.upperBound...]
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !instance.isEmpty else { return nil }

                // RAOP prefixes the friendly name with a hardware address;
                // the AirPlay service uses the display name directly.
                let friendly: String
                if service == "_raop._tcp", let at = instance.firstIndex(of: "@") {
                    friendly = String(instance[instance.index(after: at)...])
                } else {
                    friendly = instance
                }
                let hostName = Host.current().localizedName ?? ""
                let isLocalReceiver = friendly == hostName
                    || friendly.localizedCaseInsensitiveContains("MacBook Air")
                    || friendly.localizedCaseInsensitiveContains("MacBook Pro")
                guard !isLocalReceiver else { return nil }
                return Route(name: friendly, key: "\(service):\(instance)")
            }
        }

        let airPlay = browse("_airplay._tcp")
        let raop = browse("_raop._tcp")
        // Most modern speakers advertise both services. Treat the friendly
        // `_airplay` record as the canonical route and use RAOP only for a
        // destination that has no corresponding AirPlay record; otherwise a
        // single HomePod/receiver appears twice (or more) in the picker.
        let namedAirPlay = Set(airPlay.map { $0.name.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current) })
        let routes = airPlay + raop.filter { route in
            !namedAirPlay.contains(route.name.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current))
        }
        var seen = Set<String>()
        return routes.enumerated().compactMap { offset, route in
            guard seen.insert(route.key).inserted else { return nil }
            // Reserve an ID range outside normal HAL IDs. The route key is the
            // true identity; this number only keeps existing model bindings
            // source-compatible until the row is handed to the UI-script path.
            let pseudoID = AudioDeviceID(0xF000_0000) &+ AudioDeviceID(offset)
            return Device(
                id: pseudoID,
                name: route.name,
                uid: route.key,
                sampleRate: 0,
                routeID: route.key
            )
        }
        .sorted {
            $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
        }
    }

    static func mergedOutputDevices(
        physical: [Device],
        airPlay: [Device]
    ) -> [Device] {
        let hasNamedRoutes = !airPlay.isEmpty
        let physicalDevices = physical.filter { device in
            let name = device.name.lowercased()
            let genericAirPlay = name == "airplay" || name.contains("airplay device")
            // CoreAudio exposes one generic AirPlay parent alongside the
            // friendly Bonjour destinations. Showing both makes the route
            // count look inflated and presents a parent that cannot be
            // selected independently, so prefer the named live routes.
            return !(hasNamedRoutes && genericAirPlay)
        }
        var seen = Set<String>()
        return (physicalDevices + airPlay)
            .filter { seen.insert($0.identity).inserted }
            .sorted {
                $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
            }
    }

    static func selectedDeviceID() -> AudioDeviceID {
        defaultDevice() ?? AudioDeviceID(kAudioObjectUnknown)
    }

    @discardableResult
    static func selectDevice(_ device: AudioDeviceID) -> Bool {
        guard device != AudioDeviceID(kAudioObjectUnknown) else { return false }

        // macOS 15 introduced the public AudioHardwareSystem API.  It
        // performs the same default-output change as Sound Settings and is
        // more reliable for USB/DisplayPort/AirPlay endpoints than writing
        // the legacy global property directly.  Keep the HAL setter below as
        // a compatibility fallback for older macOS builds and virtual
        // devices that do not surface through the modern wrapper.
        if #available(macOS 15.0, *) {
            do {
                let system = AudioHardwareSystem.shared
                if let modernDevice = try system.devices.first(where: { $0.id == device }) {
                    try system.setDefaultOutputDevice(modernDevice)
                    if selectedDeviceID() == device { return true }
                }
            } catch {
                // Fall through to the legacy property path.
            }
        }
        var selected = device
        let size = UInt32(MemoryLayout<AudioDeviceID>.size)
        var outputAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        let outputStatus = AudioObjectSetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &outputAddress, 0, nil, size, &selected
        )
        var systemAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultSystemOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        _ = AudioObjectSetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &systemAddress, 0, nil, size, &selected
        )
        return outputStatus == noErr
    }

    @discardableResult
    static func selectDevice(_ device: Device) -> Bool {
        // A discovered route has no independent HAL endpoint. Go straight to
        // the named system row rather than writing its pseudo ID into the
        // global default-output property.
        if device.isAirPlayRoute {
            return macppSelectSystemSoundOutput(named: device.name)
        }
        if selectDevice(device.id) { return true }
        // This also covers a future HAL enumeration that gives an AirPlay
        // destination its friendly name (Office/Living Room/etc.) while the
        // parent endpoint remains the only writable CoreAudio object.
        let isAirPlay = device.name.localizedCaseInsensitiveContains("airplay")
            || device.uid.localizedCaseInsensitiveContains("airplay")
            || device.name.localizedCaseInsensitiveContains("living room")
            || device.name.localizedCaseInsensitiveContains("office")
        guard isAirPlay else { return false }
        return macppSelectSystemSoundOutput(named: device.name)
    }

    static func readBalance() -> Double? {
        guard let device = defaultDevice() else { return nil }
        var address = address(kAudioHardwareServiceDeviceProperty_VirtualMainBalance)
        guard AudioObjectHasProperty(device, &address) else { return nil }
        var value = Float32(0.5)
        var size = UInt32(MemoryLayout<Float32>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &value) == noErr else { return nil }
        return Double(value)
    }

    @discardableResult
    static func writeBalance(_ balance: Double) -> Bool {
        guard let device = defaultDevice() else { return false }
        var address = address(kAudioHardwareServiceDeviceProperty_VirtualMainBalance)
        guard AudioObjectHasProperty(device, &address) else { return false }
        var value = Float32(min(1, max(0, balance)))
        let size = UInt32(MemoryLayout<Float32>.size)
        return AudioObjectSetPropertyData(device, &address, 0, nil, size, &value) == noErr
    }
}

// Mirrors SystemOutputAudio exactly, scoped to the input side, so Nexus can
// list and switch microphones the same way it already does output devices.
private enum SystemInputAudio {
    struct Device: Identifiable, Hashable {
        let id: AudioDeviceID
        let name: String
        let uid: String
        let sampleRate: Double
    }

    struct State: Equatable {
        let volume: Double
        let muted: Bool
        let muteAvailable: Bool
    }

    private static var observedDevice: AudioDeviceID?
    private static var deviceListener: AudioObjectPropertyListenerBlock?
    private static var defaultDeviceListener: AudioObjectPropertyListenerBlock?
    private static var observationHandler: (() -> Void)?

    private static func defaultDevice() -> AudioDeviceID? {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultInputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var device = AudioDeviceID(0)
        var size = UInt32(MemoryLayout<AudioDeviceID>.size)
        guard AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size, &device) == noErr,
              device != AudioDeviceID(kAudioObjectUnknown) else { return nil }
        return device
    }

    private static func address(_ selector: AudioObjectPropertySelector) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(
            mSelector: selector,
            mScope: kAudioDevicePropertyScopeInput,
            mElement: kAudioObjectPropertyElementMain
        )
    }

    static func read() -> State? {
        guard let device = defaultDevice() else { return nil }
        var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        var scalar = Float32(0)
        var scalarSize = UInt32(MemoryLayout<Float32>.size)
        // A writable hardware-mute property is independent from input gain.
        // USB microphones commonly expose mute but no virtual-main-volume;
        // treating the missing gain as a failed device hid the useful mute
        // control even though CoreAudio could set it. Gain remains best-effort
        // display metadata while mute decides the feature's availability.
        if AudioObjectGetPropertyData(device, &volumeAddress, 0, nil, &scalarSize, &scalar) != noErr {
            scalar = 0
        }

        var muteAddress = address(kAudioDevicePropertyMute)
        var mute = UInt32(0)
        var muteSize = UInt32(MemoryLayout<UInt32>.size)
        var settable = DarwinBoolean(false)
        let hasMute = AudioObjectHasProperty(device, &muteAddress)
        let muteAvailable = hasMute
            && AudioObjectIsPropertySettable(device, &muteAddress, &settable) == noErr
            && settable.boolValue
        if !hasMute
            || AudioObjectGetPropertyData(device, &muteAddress, 0, nil, &muteSize, &mute) != noErr {
            mute = 0
        }
        return State(volume: Double(scalar), muted: mute != 0, muteAvailable: muteAvailable)
    }

    static func write(_ value: Double) {
        guard let device = defaultDevice() else { return }
        var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        var scalar = Float32(min(1, max(0, value)))
        let scalarSize = UInt32(MemoryLayout<Float32>.size)
        _ = AudioObjectSetPropertyData(device, &volumeAddress, 0, nil, scalarSize, &scalar)
    }

    @discardableResult
    static func writeMute(_ muted: Bool) -> Bool {
        guard let device = defaultDevice() else { return false }
        var muteAddress = address(kAudioDevicePropertyMute)
        var settable = DarwinBoolean(false)
        guard AudioObjectHasProperty(device, &muteAddress),
              AudioObjectIsPropertySettable(device, &muteAddress, &settable) == noErr,
              settable.boolValue else { return false }
        var mute: UInt32 = muted ? 1 : 0
        let muteSize = UInt32(MemoryLayout<UInt32>.size)
        return AudioObjectSetPropertyData(device, &muteAddress, 0, nil, muteSize, &mute) == noErr
    }

    /// Keep the rail indicator authoritative when another application changes
    /// input mute or when macOS switches the default microphone. The device
    /// listener is rebound whenever the default-input property changes; stale
    /// devices are explicitly detached so a later switch cannot leave MacPlusPlus
    /// listening to the microphone that was active only at process startup.
    static func observeChanges(_ handler: @escaping () -> Void) {
        observationHandler = handler
        rebindDeviceListener()
        guard defaultDeviceListener == nil else { return }
        let listener: AudioObjectPropertyListenerBlock = { _, _ in
            rebindDeviceListener()
            observationHandler?()
        }
        defaultDeviceListener = listener
        var defaultInputAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultInputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        AudioObjectAddPropertyListenerBlock(
            AudioObjectID(kAudioObjectSystemObject), &defaultInputAddress, .main, listener
        )
    }

    private static func rebindDeviceListener() {
        let nextDevice = defaultDevice()
        guard nextDevice != observedDevice else { return }
        if let previous = observedDevice, let listener = deviceListener {
            var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
            var muteAddress = address(kAudioDevicePropertyMute)
            AudioObjectRemovePropertyListenerBlock(previous, &volumeAddress, .main, listener)
            AudioObjectRemovePropertyListenerBlock(previous, &muteAddress, .main, listener)
        }
        observedDevice = nextDevice
        deviceListener = nil
        guard let nextDevice else { return }
        let listener: AudioObjectPropertyListenerBlock = { _, _ in observationHandler?() }
        deviceListener = listener
        var volumeAddress = address(kAudioHardwareServiceDeviceProperty_VirtualMainVolume)
        var muteAddress = address(kAudioDevicePropertyMute)
        AudioObjectAddPropertyListenerBlock(nextDevice, &volumeAddress, .main, listener)
        AudioObjectAddPropertyListenerBlock(nextDevice, &muteAddress, .main, listener)
    }

    private static func stringProperty(
        _ selector: AudioObjectPropertySelector,
        on object: AudioObjectID
    ) -> String? {
        var address = AudioObjectPropertyAddress(
            mSelector: selector,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var value: Unmanaged<CFString>?
        var size = UInt32(MemoryLayout<Unmanaged<CFString>?>.size)
        guard AudioObjectGetPropertyData(object, &address, 0, nil, &size, &value) == noErr else { return nil }
        return value?.takeUnretainedValue() as String?
    }

    private static func nominalSampleRate(of device: AudioDeviceID) -> Double {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyNominalSampleRate,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var value = Float64(0)
        var size = UInt32(MemoryLayout<Float64>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &value) == noErr else { return 0 }
        return value
    }

    private static func hasInputStreams(_ device: AudioDeviceID) -> Bool {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyStreams,
            mScope: kAudioDevicePropertyScopeInput,
            mElement: kAudioObjectPropertyElementMain
        )
        var size: UInt32 = 0
        return AudioObjectGetPropertyDataSize(device, &address, 0, nil, &size) == noErr && size > 0
    }

    static func inputDevices() -> [Device] {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDevices,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var size: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(
            AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size
        ) == noErr else { return [] }
        let count = Int(size) / MemoryLayout<AudioDeviceID>.size
        guard count > 0 else { return [] }
        var ids = Array(repeating: AudioDeviceID(0), count: count)
        guard AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size, &ids
        ) == noErr else { return [] }
        return ids.compactMap { id in
            guard hasInputStreams(id) else { return nil }
            let name = stringProperty(kAudioObjectPropertyName, on: id) ?? "Audio Device"
            let uid = stringProperty(kAudioDevicePropertyDeviceUID, on: id) ?? String(id)
            return Device(id: id, name: name, uid: uid, sampleRate: nominalSampleRate(of: id))
        }
        .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
    }

    static func selectedDeviceID() -> AudioDeviceID {
        defaultDevice() ?? AudioDeviceID(kAudioObjectUnknown)
    }

    @discardableResult
    static func selectDevice(_ device: AudioDeviceID) -> Bool {
        guard device != AudioDeviceID(kAudioObjectUnknown) else { return false }
        var selected = device
        let size = UInt32(MemoryLayout<AudioDeviceID>.size)
        var inputAddress = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultInputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        return AudioObjectSetPropertyData(
            AudioObjectID(kAudioObjectSystemObject), &inputAddress, 0, nil, size, &selected
        ) == noErr
    }
}

private struct SystemFocusState: Equatable {
    let enabled: Bool
    let modeIdentifier: String
    let modeName: String
}

/// Focus has a documented mutation surface (the Shortcuts runner) but no
/// public state API on macOS.  Keep the compatibility debt isolated here: the
/// reader only inspects Apple's bounded per-user assertion JSON and never
/// writes the Focus database.  Mutations are delegated to named Set Focus
/// shortcuts by `bin/macpp-focus-control`.
private enum SystemFocus {
    private static let maximumStateBytes = 2 * 1024 * 1024

    private static var assertionsURL: URL {
        if let override = ProcessInfo.processInfo.environment["MACPP_FOCUS_ASSERTIONS_PATH"],
           !override.isEmpty {
            return URL(fileURLWithPath: override)
        }
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/DoNotDisturb/DB/Assertions.json")
    }

    private static var modesURL: URL {
        if let override = ProcessInfo.processInfo.environment["MACPP_FOCUS_MODES_PATH"],
           !override.isEmpty {
            return URL(fileURLWithPath: override)
        }
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/DoNotDisturb/DB/ModeConfigurations.json")
    }

    private static var helperURL: URL? {
        ProcessInfo.processInfo.environment["MACPP_FOCUS_CONTROL_HELPER"]
            .flatMap { $0.isEmpty ? nil : URL(fileURLWithPath: $0) }
    }

    static func read() -> SystemFocusState? {
        guard let assertions = boundedJSONObject(at: assertionsURL) else { return nil }
        let identifiers = activeIdentifiers(in: assertions).sorted()
        let names = boundedJSONObject(at: modesURL).map(modeNames(in:)) ?? [:]
        let identifier = identifiers.first ?? ""
        return SystemFocusState(
            enabled: !identifiers.isEmpty,
            modeIdentifier: identifier,
            modeName: identifier.isEmpty ? "" : (names[identifier] ?? "Do Not Disturb")
        )
    }

    private static func boundedJSONObject(at url: URL) -> Any? {
        do {
            let values = try url.resourceValues(forKeys: [.fileSizeKey])
            guard let size = values.fileSize,
                  size >= 0,
                  size <= maximumStateBytes else { return nil }
            let data = try Data(contentsOf: url, options: [.mappedIfSafe])
            return try JSONSerialization.jsonObject(with: data)
        } catch {
            // Missing permission, a changing file, or malformed private state
            // is represented by the visible STATE UNAVAILABLE UI.
            return nil
        }
    }

    private static func activeIdentifiers(
        in value: Any,
        ancestors: [String] = []
    ) -> Set<String> {
        if ancestors.contains(where: { $0.localizedCaseInsensitiveContains("invalidation") }) {
            return []
        }
        var found: Set<String> = []
        if let dictionary = value as? [String: Any] {
            for (key, child) in dictionary {
                if key == "assertionDetailsModeIdentifier",
                   let identifier = child as? String,
                   !identifier.isEmpty {
                    found.insert(identifier)
                } else {
                    found.formUnion(activeIdentifiers(in: child, ancestors: ancestors + [key]))
                }
            }
        } else if let array = value as? [Any] {
            for child in array {
                found.formUnion(activeIdentifiers(in: child, ancestors: ancestors))
            }
        }
        return found
    }

    private static func modeNames(in value: Any) -> [String: String] {
        var result: [String: String] = [:]
        if let dictionary = value as? [String: Any] {
            if let identifier = dictionary["modeIdentifier"] as? String,
               let name = dictionary["name"] as? String,
               !identifier.isEmpty,
               !name.isEmpty {
                result[identifier] = name
            }
            for child in dictionary.values {
                result.merge(modeNames(in: child)) { current, _ in current }
            }
        } else if let array = value as? [Any] {
            for child in array {
                result.merge(modeNames(in: child)) { current, _ in current }
            }
        }
        return result
    }

    /// Completion is delivered on the main queue.  Output is bounded before
    /// parsing so a broken Shortcuts process cannot make the Shell retain an
    /// unbounded diagnostic stream.
    static func checkAvailability(_ completion: @escaping (Bool) -> Void) {
        runHelper(["check", "--json"]) { success, data in
            guard success else {
                completion(false)
                return
            }
            do {
                let object = try JSONSerialization.jsonObject(with: data) as? [String: Any]
                completion(object?["available"] as? Bool ?? false)
            } catch {
                completion(false)
            }
        }
    }

    static func setEnabled(_ enabled: Bool, completion: @escaping (Bool) -> Void) {
        runHelper(["focus", enabled ? "on" : "off", "--json"]) { success, _ in
            completion(success)
        }
    }

    private static func runHelper(
        _ arguments: [String],
        completion: @escaping (Bool, Data) -> Void
    ) {
        guard let helper = helperURL else {
            DispatchQueue.main.async { completion(false, Data()) }
            return
        }
        DispatchQueue.global(qos: .userInitiated).async {
            let process = Process()
            let output = Pipe()
            process.executableURL = helper
            process.arguments = arguments
            process.standardOutput = output
            process.standardError = FileHandle.nullDevice
            do {
                try process.run()
            } catch {
                DispatchQueue.main.async { completion(false, Data()) }
                return
            }
            process.waitUntilExit()
            let data: Data
            do {
                data = try output.fileHandleForReading.read(upToCount: 16 * 1024) ?? Data()
            } catch {
                DispatchQueue.main.async { completion(false, Data()) }
                return
            }
            DispatchQueue.main.async {
                completion(process.terminationStatus == 0, data)
            }
        }
    }
}

private enum SystemBattery {
    struct State: Sendable {
        let percent: Int
        let externalPower: Bool
        // Minutes until empty (on battery) or until full (while charging).
        // IOPowerSources reports -1 while the estimate isn't ready yet.
        let timeRemainingMinutes: Int?
    }

    struct Health: Sendable {
        let cycleCount: Int
        let healthPercent: Int
        // The system's live draw in milliwatts. On external power this is
        // SystemPowerIn (wall input); on battery it is SystemLoad, with the
        // battery-power telemetry as a fallback. Read from the same ioreg
        // call as cycle count/capacity below rather than a second process
        // spawn -- it just means this lags the same 5s cache the rest of
        // Health does, which is fine for "roughly how much is it pulling"
        // rather than a live meter.
        let systemPowerMilliwatts: Int?
        let adapterWatts: Int?
    }

    private static var cachedHealth: Health?
    private static var cachedHealthExternalPower: Bool?
    private static var lastHealthFetch = Date.distantPast
    private static let healthRefreshInterval: TimeInterval = 5
    private static var cachedHealthPercent: Int?
    private static var lastHealthProfileFetch = Date.distantPast
    private static let healthProfileRefreshInterval: TimeInterval = 60

    static func read() -> State? {
        guard let infoRef = IOPSCopyPowerSourcesInfo() else { return nil }
        let info = infoRef.takeRetainedValue()
        guard let listRef = IOPSCopyPowerSourcesList(info) else { return nil }
        let sources = listRef.takeRetainedValue() as Array
        for source in sources {
            guard let descriptionRef = IOPSGetPowerSourceDescription(info, source) else { continue }
            let description = descriptionRef.takeUnretainedValue() as NSDictionary
            guard (description[kIOPSTypeKey] as? String) == kIOPSInternalBatteryType else { continue }
            let current = (description[kIOPSCurrentCapacityKey] as? NSNumber)?.doubleValue ?? 0
            let maximum = max(1, (description[kIOPSMaxCapacityKey] as? NSNumber)?.doubleValue ?? 100)
            let powerSource = description[kIOPSPowerSourceStateKey] as? String
            let charging = powerSource == kIOPSACPowerValue
            let timeKey = charging ? kIOPSTimeToFullChargeKey : kIOPSTimeToEmptyKey
            let rawMinutes = (description[timeKey] as? NSNumber)?.intValue ?? -1
            return State(
                percent: min(100, max(0, Int((current / maximum * 100).rounded()))),
                externalPower: charging,
                timeRemainingMinutes: rawMinutes > 0 ? rawMinutes : nil
            )
        }
        return nil
    }

    // Cycle count and design-vs-maximum capacity aren't exposed by
    // IOPowerSources at all; ioreg is the standard, no-sudo-required way to
    // read them. This is real per-battery hardware detail the rail's battery
    // popout didn't show before, alongside the plain percentage ring.
    static func health(externalPower: Bool) -> Health? {
        if let cachedHealth,
           cachedHealthExternalPower == externalPower,
           Date().timeIntervalSince(lastHealthFetch) < healthRefreshInterval {
            return cachedHealth
        }
        let pipe = Pipe()
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/sbin/ioreg")
        process.arguments = ["-rc", "AppleSmartBattery"]
        process.standardOutput = pipe
        process.standardError = FileHandle.nullDevice
        guard (try? process.run()) != nil else {
            // Do not carry an AC reading across an unplug event. The caller
            // will retry on the next battery refresh instead of showing the
            // wrong source's draw.
            return cachedHealthExternalPower == externalPower ? cachedHealth : nil
        } // macpp:silent-ok unavailable ioreg keeps the last known health snapshot for the same source
        process.waitUntilExit()
        let output = String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        func extract(_ key: String) -> Int? {
            guard let range = output.range(of: "\"\(key)\" = ") else { return nil }
            let digits = output[range.upperBound...].prefix(while: { $0.isNumber })
            return digits.isEmpty ? nil : Int(digits)
        }
        // Power telemetry lives inside the PowerTelemetryData dict, a single
        // compound property rendered as one line with no spaces around its
        // own inner `=`s -- a different shape from the plain top-level
        // `"Key" = value` properties `extract` above reads, so it needs its
        // own lookup.
        func extractNested(_ key: String) -> Int? {
            guard let range = output.range(of: "\"\(key)\"=") else { return nil }
            var rest = output[range.upperBound...]
            let negative = rest.first == "-"
            if negative { rest = rest.dropFirst() }
            let digits = rest.prefix(while: { $0.isNumber })
            guard !digits.isEmpty, let unsigned = UInt64(digits) else { return nil }
            if negative {
                if unsigned == UInt64(Int.max) + 1 { return Int.min }
                guard unsigned <= UInt64(Int.max) else { return nil }
                return -Int(unsigned)
            }
            if unsigned <= UInt64(Int.max) { return Int(unsigned) }
            // Apple exposes negative battery current/power as an unsigned
            // 64-bit two's-complement value on this Mac, e.g. BatteryPower
            // becomes 18446744073709539121 instead of -12495.
            return Int(Int64(bitPattern: unsigned))
        }
        func tupleValueRange(named name: String) -> Range<String.Index>? {
            guard let declaration = output.range(of: "\"\(name)\" = (") else { return nil }
            var depth = 1
            var index = declaration.upperBound
            while index < output.endIndex {
                switch output[index] {
                case "(": depth += 1
                case ")":
                    depth -= 1
                    if depth == 0 { return declaration.upperBound..<index }
                default: break
                }
                index = output.index(after: index)
            }
            return nil
        }
        let powerOutDetailsRange = tupleValueRange(named: "PowerOutDetails")
        func extractDictionaryValues(_ key: String) -> [Int] {
            let token = "\"\(key)\"="
            var values: [Int] = []
            var remainder = output[...]
            while let range = remainder.range(of: token) {
                // PowerOutDetails contains a nested dictionary, so the
                // delimiter check below alone is not enough to distinguish
                // its peripheral-output Watts from adapter metadata.
                if powerOutDetailsRange?.contains(range.lowerBound) == true {
                    remainder = remainder[range.upperBound...]
                    continue
                }
                // `PowerOutDetails` is rendered as a tuple. Its `Watts`
                // field is USB/device output in milliwatts (the connected
                // keyboard is 1321 here), not the Mac adapter's wattage.
                // Only accept values whose immediate enclosing container is
                // a dictionary, which is the shape used for adapter data.
                var delimiters: [Character] = []
                for character in output[..<range.lowerBound] {
                    switch character {
                    case "{", "(":
                        delimiters.append(character)
                    case "}":
                        if delimiters.last == "{" { delimiters.removeLast() }
                    case ")":
                        if delimiters.last == "(" { delimiters.removeLast() }
                    default:
                        break
                    }
                }
                guard delimiters.last == "{" else {
                    remainder = remainder[range.upperBound...]
                    continue
                }
                var rest = remainder[range.upperBound...]
                let negative = rest.first == "-"
                if negative { rest = rest.dropFirst() }
                let digits = rest.prefix(while: { $0.isNumber })
                if let unsigned = UInt64(digits), unsigned <= UInt64(Int.max) {
                    let value = Int(unsigned)
                    values.append(negative ? -value : value)
                }
                remainder = remainder[range.upperBound...]
            }
            return values
        }

        func readSystemProfilerHealthPercent() -> Int? {
            let healthPipe = Pipe()
            let healthProcess = Process()
            healthProcess.executableURL = URL(fileURLWithPath: "/usr/sbin/system_profiler")
            healthProcess.arguments = ["SPPowerDataType"]
            healthProcess.standardOutput = healthPipe
            healthProcess.standardError = FileHandle.nullDevice
            guard (try? healthProcess.run()) != nil else { return nil } // macpp:silent-ok unavailable system_profiler leaves health unknown
            healthProcess.waitUntilExit()
            guard healthProcess.terminationStatus == 0 else { return nil }
            let profile = String(
                data: healthPipe.fileHandleForReading.readDataToEndOfFile(),
                encoding: .utf8
            ) ?? ""
            for rawLine in profile.split(whereSeparator: \.isNewline) {
                let line = rawLine.trimmingCharacters(in: .whitespacesAndNewlines)
                guard let separator = line.range(of: ":"),
                      line[..<separator.lowerBound]
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                        .localizedCaseInsensitiveCompare("Maximum Capacity") == .orderedSame else {
                    continue
                }
                let value = line[separator.upperBound...]
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                let digits = value.prefix(while: { $0.isNumber })
                if let percent = Int(digits) {
                    return min(100, max(0, percent))
                }
            }
            return nil
        }
        guard let cycleCount = extract("CycleCount"),
              let maxCapacity = extract("MaxCapacity"),
              let designCapacity = extract("DesignCapacity"),
              designCapacity > 0 else {
            return cachedHealthExternalPower == externalPower ? cachedHealth : nil
        }
        let now = Date()
        if cachedHealthPercent == nil
            || now.timeIntervalSince(lastHealthProfileFetch) >= healthProfileRefreshInterval {
            if let percent = readSystemProfilerHealthPercent() {
                cachedHealthPercent = percent
            }
            lastHealthProfileFetch = now
        }
        let fallbackHealthPercent: Int = {
            // AppleRawMaxCapacity/NominalChargeCapacity is the useful ioreg
            // fallback. The top-level MaxCapacity field is a 0–100 present
            // charge value on this Mac, not a capacity in mAh; dividing it by
            // DesignCapacity was the source of the bogus 2% health display.
            if let rawMaxCapacity = extract("AppleRawMaxCapacity"),
               let nominalChargeCapacity = extract("NominalChargeCapacity"),
               nominalChargeCapacity > 0 {
                return min(100, max(0, Int((Double(rawMaxCapacity) / Double(nominalChargeCapacity) * 100).rounded())))
            }
            return min(100, max(0, maxCapacity))
        }()
        let health = Health(
            cycleCount: cycleCount,
            healthPercent: cachedHealthPercent ?? fallbackHealthPercent,
            systemPowerMilliwatts: MacPlusPlusPureLogic.batterySystemPowerMilliwatts(
                externalPower: externalPower,
                wallInput: extractNested("SystemPowerIn"),
                systemLoad: extractNested("SystemLoad"),
                batteryPower: extractNested("BatteryPower")
            ),
            // Never show a battery-side `PowerOutDetails.Watts` value as an
            // adapter rating. It is peripheral output in milliwatts, not
            // incoming adapter power; on battery there is no adapter value.
            adapterWatts: externalPower ? extractDictionaryValues("Watts").max() : nil
        )
        cachedHealth = health
        cachedHealthExternalPower = externalPower
        lastHealthFetch = Date()
        return health
    }
}

private func primaryDisplay() -> NSScreen? {
    // Display Settings places the primary (menu-bar) display at the global
    // origin. NSScreen.main instead follows the active/key window, which made
    // shell surfaces jump to Sidecar or an external monitor during use.
    NSScreen.screens.first(where: { abs($0.frame.minX) < 0.5 && abs($0.frame.minY) < 0.5 })
        ?? NSScreen.screens.first
}

private func isPrimaryDisplay(_ screen: NSScreen) -> Bool {
    guard let primary = primaryDisplay() else { return false }
    return abs(primary.frame.minX - screen.frame.minX) < 0.5
        && abs(primary.frame.minY - screen.frame.minY) < 0.5
        && abs(primary.frame.width - screen.frame.width) < 0.5
        && abs(primary.frame.height - screen.frame.height) < 0.5
}

/// Routed through the same cached measurement `shellTopDepth(on:)` uses.
///
/// These were two independent readings of the same volatile properties, so
/// they could disagree about one display within a single frame -- one layer
/// carving a notch while another drew a flat rim, which is the other way the
/// reverse curves went missing.
private func displayHasCameraHousing(_ screen: NSScreen) -> Bool {
    DisplayHousing.height(for: screen) != nil
}

private func displayIdentifier(_ screen: NSScreen) -> NSNumber {
    screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? NSNumber
        ?? NSNumber(value: Int(screen.frame.minX.rounded()) ^ Int(screen.frame.minY.rounded()))
}

/// Camera-housing height per display, remembered once measured.
///
/// The measurement has to survive moments when macOS cannot answer. Both
/// inputs it depends on are transiently unavailable: `auxiliaryTopLeftArea`
/// is nil while the window server reconfigures, and the previous derivation
/// also used `visibleFrame` -- the menu bar reservation -- which drops to zero
/// whenever the menu bar auto-hides or a fullscreen app owns the display.
/// Either reading zero collapsed the top depth to a plain rim, so the popout
/// silently stopped carving its notch and the reverse curves disappeared until
/// something happened to re-measure. That is the intermittency.
///
/// A camera housing is fixed hardware geometry, so the first successful
/// measurement is authoritative for that display and a later failure to read
/// it means "ask again later", not "this display has no notch".
private enum DisplayHousing {
    private static let lock = NSLock()
    private static var frames: [NSNumber: NSRect] = [:]

    private static func cachedFrame(for key: NSNumber, on screen: NSScreen) -> NSRect? {
        lock.lock()
        let cached = frames[key]
        lock.unlock()
        guard let cached else { return nil }

        // A display can keep its identifier while its global frame changes.
        // Re-anchor the remembered physical opening to the new top edge, but
        // never let an old geometry snapshot become a second floating notch.
        let normalized = CaelestiaParityGeometry.topCameraHousingFrame(
            leftArea: CGRect(
                x: cached.minX - 1,
                y: cached.minY,
                width: 1,
                height: cached.height
            ),
            rightArea: CGRect(
                x: cached.maxX,
                y: cached.minY,
                width: 1,
                height: cached.height
            ),
            screenBounds: screen.frame,
            minimumGap: 0,
            minimumHeight: shellFrame
        )
        guard let normalized else {
            lock.lock(); frames.removeValue(forKey: key); lock.unlock()
            return nil
        }
        let frame: NSRect = normalized
        if frame != cached {
            lock.lock(); frames[key] = frame; lock.unlock()
        }
        return frame
    }

    /// Housing frame, or nil when this display genuinely has none.
    static func frame(for screen: NSScreen) -> NSRect? {
        let key = displayIdentifier(screen)
        let left = screen.auxiliaryTopLeftArea
        let right = screen.auxiliaryTopRightArea
        if let measured = CaelestiaParityGeometry.topCameraHousingFrame(
            leftArea: left,
            rightArea: right,
            screenBounds: screen.frame,
            minimumGap: 40,
            minimumHeight: shellFrame
        ) {
            let frame: NSRect = measured
            lock.lock(); frames[key] = frame; lock.unlock()
            return frame
        }

        // A pair can describe a real-sized housing while its vertical or
        // horizontal origin is transiently inconsistent with the display.
        // Preserve a previously confirmed opening in that case; do not
        // replace it with a panel at the stale coordinate.
        if CaelestiaParityGeometry.cameraHousingFrame(
            leftArea: left,
            rightArea: right,
            minimumGap: 40,
            minimumHeight: shellFrame
        ) != nil {
            return cachedFrame(for: key, on: screen)
        }

        if left != nil, right != nil {
            // A readable but implausible pair is a real answer: this display
            // has no housing. Forget any stale value for it.
            lock.lock(); frames.removeValue(forKey: key); lock.unlock()
            return nil
        }

        // Unreadable right now. Fall back to what this display last reported
        // rather than treating the gap as an absence.
        return cachedFrame(for: key, on: screen)
    }

    static func height(for screen: NSScreen) -> CGFloat? {
        frame(for: screen)?.height
    }
}

private func shellTopDepth(on screen: NSScreen) -> CGFloat {
    // A menu bar alone is not a notch. Plain external and Sidecar displays use
    // the same quiet nine-point rim at both the top and bottom.
    guard let housing = DisplayHousing.height(for: screen) else { return shellFrame }
    // Derived from the housing rather than the menu bar reservation, so it
    // cannot change when the menu bar hides.
    return max(shellFrame, housing + shellFrame)
}

private func shellTopDepth() -> CGFloat {
    guard let screen = primaryDisplay() else { return shellFrame }
    return shellTopDepth(on: screen)
}

// Caelestia's bar clock stacks hour over minute as two plain, unrotated
// digit groups rather than a single sideways-scrolling string.
private func stackedClockParts(_ date: Date) -> (String, String) {
    let parts = Calendar.autoupdatingCurrent.dateComponents([.hour, .minute], from: date)
    return (
        String(format: "%02d", parts.hour ?? 0),
        String(format: "%02d", parts.minute ?? 0)
    )
}

// Caelestia v1 (the revision used by the visual reference) animates shell
// geometry with Qt BezierSpline curves rather than physical springs.  Some of
// those curves contain multiple cubic segments, so SwiftUI's single-cubic
// timingCurve cannot reproduce them.  This evaluator follows the same spline
// format: control1, control2, endpoint for each segment.
private struct CaelestiaBezierSegment {
    let start: CGPoint
    let control1: CGPoint
    let control2: CGPoint
    let end: CGPoint

    func value(atX x: Double) -> Double {
        var lower = 0.0
        var upper = 1.0
        for _ in 0..<18 {
            let t = (lower + upper) * 0.5
            if cubic(start.x, control1.x, control2.x, end.x, t) < x { lower = t }
            else { upper = t }
        }
        let t = (lower + upper) * 0.5
        return cubic(start.y, control1.y, control2.y, end.y, t)
    }

    private func cubic(_ p0: Double, _ p1: Double, _ p2: Double, _ p3: Double, _ t: Double) -> Double {
        let mt = 1 - t
        return mt * mt * mt * p0
            + 3 * mt * mt * t * p1
            + 3 * mt * t * t * p2
            + t * t * t * p3
    }
}

fileprivate enum CaelestiaCurve: Hashable {
    case emphasized, emphasizedAccel, emphasizedDecel
    case standard, standardAccel, standardDecel
    case expressiveFastSpatial, expressiveDefaultSpatial, expressiveSlowSpatial
    case expressiveFastEffects, expressiveDefaultEffects, expressiveSlowEffects

    private var points: [Double] {
        let key: String
        switch self {
        case .emphasized: key = "emphasized"
        case .emphasizedAccel: key = "emphasizedAccel"
        case .emphasizedDecel: key = "emphasizedDecel"
        case .standard: key = "standard"
        case .standardAccel: key = "standardAccel"
        case .standardDecel: key = "standardDecel"
        case .expressiveFastSpatial: key = "expressiveFastSpatial"
        case .expressiveDefaultSpatial: key = "expressiveDefaultSpatial"
        case .expressiveSlowSpatial: key = "expressiveSlowSpatial"
        case .expressiveFastEffects: key = "expressiveFastEffects"
        case .expressiveDefaultEffects: key = "expressiveDefaultEffects"
        case .expressiveSlowEffects: key = "expressiveSlowEffects"
        }
        return CaelestiaParityTokens.Motion.curves[key] ?? [0.2, 0, 0, 1, 1, 1]
    }

    // Rebuilding this array from scratch was previously done on every call,
    // and value(at:) is called every animation frame for every animated
    // property. Cache it once per curve case instead.
    private static var segmentCache: [CaelestiaCurve: [CaelestiaBezierSegment]] = [:]
    // SwiftUI can ask a custom animation for the same curve value many times
    // in one display pass (the shell frame, the popout mask, and each child
    // animation are separate consumers). Solving a cubic with an 18-step
    // binary search for every one of those requests was measurable on the
    // main thread during a fast hover traversal. A small lookup table keeps
    // the authored curve shape while replacing that hot path with one indexed
    // lookup and a linear interpolation.
    private static var valueCache: [CaelestiaCurve: [Double]] = [:]

    private var segments: [CaelestiaBezierSegment] {
        if let cached = Self.segmentCache[self] { return cached }
        var start = CGPoint.zero
        var result: [CaelestiaBezierSegment] = []
        for index in stride(from: 0, to: points.count, by: 6) {
            guard index + 5 < points.count else { break }
            let segment = CaelestiaBezierSegment(
                start: start,
                control1: CGPoint(x: points[index], y: points[index + 1]),
                control2: CGPoint(x: points[index + 2], y: points[index + 3]),
                end: CGPoint(x: points[index + 4], y: points[index + 5])
            )
            result.append(segment)
            start = segment.end
        }
        Self.segmentCache[self] = result
        return result
    }

    func value(at progress: Double) -> Double {
        let x = min(1, max(0, progress))
        let count = 257
        if let cached = Self.valueCache[self], cached.count == count {
            let position = x * Double(count - 1)
            let lower = min(count - 2, max(0, Int(position.rounded(.down))))
            let fraction = position - Double(lower)
            return cached[lower] + (cached[lower + 1] - cached[lower]) * fraction
        }
        guard let segment = segments.first(where: { x <= $0.end.x + 0.000_001 }) ?? segments.last else { return x }
        let value = segment.value(atX: x)
        let samples = (0..<count).map { index -> Double in
            let sampleX = Double(index) / Double(count - 1)
            let sampleSegment = segments.first(where: { sampleX <= $0.end.x + 0.000_001 }) ?? segments.last
            return sampleSegment?.value(atX: sampleX) ?? sampleX
        }
        Self.valueCache[self] = samples
        return value
    }
}

private struct CaelestiaCustomAnimation: CustomAnimation {
    let duration: TimeInterval
    let curve: CaelestiaCurve

    func animate<V: VectorArithmetic>(value: V, time: TimeInterval, context: inout AnimationContext<V>) -> V? {
        guard time < duration else { return nil }
        return value.scaled(by: curve.value(at: time / duration))
    }
}

private extension SwiftUI.Animation {
    static func caelestia(_ duration: TimeInterval, _ curve: CaelestiaCurve) -> SwiftUI.Animation {
        SwiftUI.Animation(CaelestiaCustomAnimation(duration: duration, curve: curve))
    }
}

enum ShellMotion {
    case hover
    case press
    case popout
    case topPopout
    case dismiss
    case sideDismiss
    case topDismiss
    case panelSwitch
    // A reused rail surface can be retargeted while its previous handoff is
    // still in flight. Keep that topology change monotonic: a shared panel
    // must never overshoot the shell rim and briefly expose a disconnected
    // outgoing/incoming seam.
    case handoff
    // The compact notification card can grow by more than eleven times its
    // height when it becomes the full sidebar. The handoff needs enough room
    // to establish the shared shoulder, but a late acceleration makes the
    // lower edge visibly rush during the last third. Keep it on a bounded
    // deceleration profile so the large travel settles continuously.
    case notificationHandoff
    case nexusPageSwitch
    case workspace
    case workspaceIndicator
    case notification
    case drawer
    case contentIn
    case contentOut
    case panelGeometry
    case sidePopout
    case launcherResize
    // The wallpaper carousel's own step. Like launcherResize, this is fired
    // repeatedly and interrupted mid-flight (holding an arrow key, or a
    // continuous trackpad scroll), so it must not use an overshooting curve.
    case carousel
    case valueChange
    case iconOut
    case iconIn
    case palette

    // Caelestia does not give each surface an unrelated hand-tuned curve.
    // Its popout wrapper routes geometry through one expressive spatial token
    // and reserves the shorter effects token for opacity/content changes.
    // Keep the semantic cases above for readable call sites, but collapse them
    // onto that same authoritative vocabulary here.
    private enum Token {
        case fastSpatial
        case defaultSpatial
        case slowSpatial
        case fastEffects
        case defaultEffects
        case slowEffects
        // Every other spatial token is an *expressive* curve, which by design
        // overshoots its target and settles back (control-point y of 1.21 and
        // 1.67 respectively). That reads beautifully for a gesture that fires
        // once. It reads as erratic bouncing for a motion that is re-triggered
        // several times a second and therefore never gets to settle -- each
        // restart re-launches an overshoot from wherever the last one had got
        // to, in whatever direction the value just moved. This token exists
        // for exactly those continuously-retriggered geometry changes: it is
        // still a real caelestia curve (Material `standard`), just a
        // monotonic one that cannot overshoot, so interrupting it mid-flight
        // is visually harmless.
        case retriggerableSpatial
        // A fresh popout is a one-way placement into a hard shell boundary.
        // The expressive spatial curve intentionally rises above 1.0, which
        // makes the contour travel past that boundary and settle back. Keep
        // the same authored spatial duration, but use a bounded curve for the
        // entrance so the card stops exactly at its destination.
        case boundedPopoutSpatial
        // Keep dismissal bounded but slightly shorter so the shell rim
        // reclaims its opening promptly after an attached card leaves.
        case dismissSpatial
        case handoffSpatial
        case notificationHandoffSpatial

        var duration: TimeInterval {
            switch self {
            case .fastSpatial: CaelestiaParityTokens.Motion.fastSpatial
            case .defaultSpatial: CaelestiaParityTokens.Motion.defaultSpatial
            case .slowSpatial: CaelestiaParityTokens.Motion.slowSpatial
            case .fastEffects: CaelestiaParityTokens.Motion.fastEffects
            case .defaultEffects: CaelestiaParityTokens.Motion.defaultEffects
            case .slowEffects: CaelestiaParityTokens.Motion.slowEffects
            case .retriggerableSpatial: 0.28
            case .boundedPopoutSpatial: CaelestiaParityTokens.Motion.defaultSpatial
            case .dismissSpatial: CaelestiaParityTokens.Motion.normal
            case .handoffSpatial: CaelestiaParityTokens.Motion.defaultSpatial
            case .notificationHandoffSpatial: CaelestiaParityTokens.Motion.slowSpatial
            }
        }

        private var curveName: String {
            switch self {
            case .fastSpatial: "expressiveFastSpatial"
            case .defaultSpatial: "expressiveDefaultSpatial"
            case .slowSpatial: "expressiveSlowSpatial"
            case .fastEffects: "expressiveFastEffects"
            case .defaultEffects: "expressiveDefaultEffects"
            case .slowEffects: "expressiveSlowEffects"
            case .retriggerableSpatial: "standard"
            case .boundedPopoutSpatial: "standard"
            case .dismissSpatial: "standard"
            case .handoffSpatial: "standard"
            case .notificationHandoffSpatial: "standard"
            }
        }

        var curve: CaelestiaCurve {
            switch curveName {
            case "expressiveFastSpatial": .expressiveFastSpatial
            case "expressiveDefaultSpatial": .expressiveDefaultSpatial
            case "expressiveSlowSpatial": .expressiveSlowSpatial
            case "expressiveFastEffects": .expressiveFastEffects
            case "expressiveDefaultEffects": .expressiveDefaultEffects
            case "expressiveSlowEffects": .expressiveSlowEffects
            case "standard": .standard
            case "standardAccel": .standardAccel
            case "standardDecel": .standardDecel
            default: .standard
            }
        }

        var appKitTiming: CAMediaTimingFunction {
            let points = CaelestiaParityTokens.Motion.curves[curveName]
                ?? [0.2, 0, 0, 1, 1, 1]
            return CAMediaTimingFunction(
                controlPoints: Float(points[0]), Float(points[1]),
                Float(points[2]), Float(points[3])
            )
        }
    }

    private var token: Token {
        switch self {
        case .press:
            .fastSpatial
        case .hover, .iconOut, .iconIn:
            .fastEffects
        case .contentIn, .contentOut:
            .fastEffects
        case .valueChange:
            .defaultEffects
        // Both of these are re-triggered faster than they can settle -- the
        // launcher's height on every keystroke, the carousel on every step of
        // a held arrow key or continuous scroll -- so neither may use an
        // overshooting curve.
        case .launcherResize, .carousel:
            .retriggerableSpatial
        case .nexusPageSwitch:
            .retriggerableSpatial
        case .handoff:
            .handoffSpatial
        case .notificationHandoff:
            .notificationHandoffSpatial
        case .popout, .topPopout, .sidePopout:
            .boundedPopoutSpatial
        // Physical surfaces stay on bounded splines in both directions. The
        // side-attached family must use the exact same profile for its return
        // trip as for its reveal: its shell-facing reverse shoulder is
        // translated by the AppKit frame, so a different duration would put
        // the curve and the border on separate timelines.
        case .sideDismiss:
            .boundedPopoutSpatial
        // A bottom-attached physical surface must return on the same bounded
        // spline it used to enter on. Nexus is hosted by the bottom launcher,
        // so using the shorter dismissal profile here made its reverse curves
        // finish before the frame and contour had reached the same point.
        case .topDismiss:
            .boundedPopoutSpatial
        // Compact rail dismissals still use the shorter effects-aware profile
        // so their resting rim is reclaimed promptly after the card collapses.
        case .dismiss:
            .dismissSpatial
        case .panelSwitch, .workspace, .notification, .drawer, .panelGeometry:
            .boundedPopoutSpatial
        case .workspaceIndicator:
            .retriggerableSpatial
        case .palette:
            .defaultSpatial
        }
    }

    var duration: TimeInterval {
        token.duration
    }

    var animation: SwiftUI.Animation {
        .caelestia(duration, curve)
    }

    fileprivate var curve: CaelestiaCurve {
        token.curve
    }

    var appKitTiming: CAMediaTimingFunction {
        token.appKitTiming
    }

    static let initialScale: CGFloat = 0.80
    static let initialBlur: CGFloat = 0
    static let stagger: TimeInterval = 0
}

private enum SurfaceAttachment: Equatable {
    case top, left, right, rightSidebar, bottom, bottomLeft, topRight

    var blobAxis: CaelestiaSurfaceMotionAxis {
        switch self {
        case .top: .top
        case .left: .leading
        case .right, .rightSidebar: .trailing
        case .bottom: .bottom
        case .bottomLeft, .topRight: .corner
        }
    }

    var anchor: UnitPoint {
        switch self {
        case .top: .top
        case .left: .leading
        case .right, .rightSidebar: .trailing
        case .bottom: .bottom
        case .bottomLeft: .bottomLeading
        case .topRight: .topTrailing
        }
    }

    var closedOffset: CGSize {
        switch self {
        case .top: CGSize(width: 0, height: -16)
        case .left: CGSize(width: -16, height: 0)
        case .right, .rightSidebar: CGSize(width: 16, height: 0)
        case .bottom: CGSize(width: 0, height: 16)
        case .bottomLeft: CGSize(width: -10, height: 12)
        case .topRight: CGSize(width: 10, height: -12)
        }
    }

    var revealAlignment: Alignment {
        switch self {
        case .top: .top
        case .bottom: .bottom
        case .left: .leading
        case .right, .rightSidebar: .trailing
        case .bottomLeft: .bottomLeading
        case .topRight: .topTrailing
        }
    }
}

private func shellAttachmentRadius(_ attachment: SurfaceAttachment) -> CGFloat {
    switch attachment {
    case .top: 24
    case .right, .rightSidebar: 22
    case .topRight: notificationCornerRadius
    case .left, .bottom, .bottomLeft: 20
    }
}

/// Drives the contour phase that is painted by `Canvas` and by the
/// full-screen shell fill. SwiftUI can interpolate a `Shape` inside an
/// animated view transaction, but a `Canvas` closure only receives a new draw
/// pass when one of its observed values changes. Keeping this phase display
/// linked makes the border, its aperture, and the card fill advance on the
/// same frame as a legacy top/right surface or a newly attached rail card.
///
/// The phase starts from its current presentation value. A hover reversal
/// therefore retargets the existing contour instead of restarting from 0/1
/// and briefly exposing a disconnected shell seam.
private final class CaelestiaSurfacePhaseDriver: NSObject {
    private var displayLink: CADisplayLink?
    private var startValue: CGFloat = 0
    private var targetValue: CGFloat = 0
    private var startedAt: CFTimeInterval = 0
    private var duration: TimeInterval = 0
    private var motion: ShellMotion = .dismiss

    private(set) var value: CGFloat = 0
    var onChange: ((CGFloat) -> Void)?
    private var completion: (() -> Void)?

    deinit {
        displayLink?.invalidate()
    }

    func set(_ value: CGFloat) {
        stop()
        self.value = value
        onChange?(value)
    }

    func animate(
        to target: CGFloat,
        using motion: ShellMotion,
        on screen: NSScreen? = nil,
        completion: (() -> Void)? = nil
    ) {
        stop()
        self.completion = completion
        guard abs(target - value) > 0.000_1 else {
            let finished = self.completion
            set(target)
            finished?()
            return
        }

        startValue = value
        targetValue = target
        startedAt = CACurrentMediaTime()
        duration = max(0.001, motion.duration)
        self.motion = motion

        guard let screen = screen ?? NSScreen.main ?? NSScreen.screens.first else {
            let finished = self.completion
            set(target)
            finished?()
            return
        }
        let link = screen.displayLink(
            target: self,
            selector: #selector(displayLinkFired(_:))
        )
        let refreshRate = shellAnimationRefreshRate(for: screen)
        link.preferredFrameRateRange = CAFrameRateRange(
            minimum: min(60, refreshRate),
            maximum: refreshRate,
            preferred: refreshRate
        )
        link.isPaused = false
        link.add(to: .main, forMode: .common)
        displayLink = link
    }

    private func stop() {
        displayLink?.invalidate()
        displayLink = nil
        completion = nil
    }

    @objc private func displayLinkFired(_ link: CADisplayLink) {
        guard displayLink === link else {
            link.invalidate()
            return
        }
        let elapsed = CACurrentMediaTime() - startedAt
        let finished = elapsed >= duration
        let normalized = finished ? 1 : elapsed / duration
        let eased = motion.curve.value(at: normalized)
        value = startValue + (targetValue - startValue) * CGFloat(eased)
        onChange?(value)
        guard finished else { return }
        // Preserve the callback while the display link is being invalidated;
        // a new target cancels it through `stop()`, but a normal terminal
        // frame must publish its completion after the final value is painted.
        let finishedCallback = completion
        stop()
        value = targetValue
        onChange?(targetValue)
        finishedCallback?()
    }
}

final class SurfaceMotionState: NSObject, ObservableObject {
    let id = UUID()
    @Published var presented = false
    @Published var progress: CGFloat = 0
    /// Directional deformation from the native BlobRect spring. This is kept
    /// separate from `progress`: the authored reveal curve controls where the
    /// wrapper is, while the spring adds the velocity/stretch/settle that
    /// makes an interrupted handoff feel physical.
    @Published var deformation = CaelestiaSurfaceDeformation.identity
    /// The bottom app shelf uses the authored bounded popout curve without
    /// the directional BlobRect spring. On a short horizontal surface the
    /// spring's width/height rebound reads as a visible bounce, while the
    /// same deformation remains useful on the right-edge sliders.
    @Published fileprivate var suppressBottomBlobDeformation = false
    /// A reused popout can change which shell edge it is attached to while
    /// its AppKit frame is travelling to the next target. Keep the old and
    /// new silhouettes alive together for that handoff; otherwise the
    /// shell-wide contour jumps from one topology to the other on the first
    /// frame and the reverse gutter reads as a clipped card.
    @Published fileprivate var attachmentBlend: CGFloat = 1
    @Published fileprivate var morphFromAttachment: SurfaceAttachment?
    /// The outgoing silhouette has its own contact pose. During a bottom-to-side
    /// handoff the incoming `.right` surface is moving upward while the outgoing
    /// `.left` surface may still be flush with the bottom rim. Reusing the
    /// destination fillet for both shapes made the old reverse corner vanish on
    /// the first frame, which is the visual "disconnect" this state is meant to
    /// prevent.
    @Published fileprivate var morphFromTopFillet: CGFloat = 0
    @Published fileprivate var morphFromBottomFillet: CGFloat = 0
    /// Preserve the outgoing surface's actual frame during an attachment
    /// handoff. Reusing the incoming descriptor frame for both silhouettes
    /// stretched the compact notification contour as the sidebar grew, which
    /// produced the visible jump into the shell before the drop completed.
    @Published fileprivate var morphFromFrame: CGRect?
    fileprivate var attachmentTransitionGeneration = 0
    private let blobDriver = CaelestiaBlobMotionDriver()
    private let contourPhaseDriver = CaelestiaSurfacePhaseDriver()
    private let contourBlendDriver = CaelestiaSurfacePhaseDriver()
    // The physical surface and its information are intentionally committed in
    // two phases. The shell frame is already warm, while a newly-created
    // popover NSHostingView can take one compositor turn to paint. Keeping a
    // tiny, generation-guarded content gate prevents that fresh content from
    // flashing above the background on the first frame. This changes ordering
    // only; the existing animation profiles remain authoritative.
    @Published var contentReady = false
    // A continuous phase keeps information rows on the surface's authored
    // timeline. A boolean-only gate still allowed the old 200 ms effects fade
    // to finish while the 500 ms AppKit wrapper was growing underneath it.
    @Published var contentProgress: CGFloat = 0
    // Reused grounded handoffs can replace a short Battery body with the
    // taller Audio body while the AppKit window is still growing. In that
    // one case, progress is already 1, so the normal last-resort reveal would
    // expose destination rows before the moving window has room for them.
    @Published var strictContentGate = false
    // Physical placement is separate from the morph's logical progress. A
    // reused rail panel keeps `progress == 1` while AppKit moves its frame to
    // the next trigger, so the display-link phase is carried here and shared
    // with MotionChild. Fresh surfaces animate this phase with the morph.
    @Published var surfacePlacementProgress: CGFloat = 1
    // The terminal contour value and the terminal painted frame can arrive in
    // the same compositor turn. Do not mount the nested card tree on that
    // turn: wait for the next main-run-loop pass so the completed surface has
    // one stable frame before SwiftUI measures its children.
    @Published var contentPlacementStable = false
    /// Presentation-only copies used by the shell-wide Canvas/fill. These are
    /// updated on display-link ticks rather than only at the endpoints of a
    /// SwiftUI transaction, which is required for continuous legacy borders.
    @Published var contourProgress: CGFloat = 0
    @Published fileprivate var contourAttachmentBlend: CGFloat = 1
    /// During the compact-notification to sidebar handoff, the incoming
    /// sidebar is top-aligned to the compact host for layout stability. This
    /// render-only offset keeps that incoming body at the sidebar's final
    /// top edge while the outgoing compact card remains on its own edge.
    @Published fileprivate var notificationHandoffTopOffset: CGFloat = 0
    /// Once a compact notification has become the sidebar, keep its original
    /// top reverse curve as the persistent anchor. The sidebar must not swap
    /// to a second shoulder on the completion frame after the two bodies have
    /// already visually merged.
    @Published fileprivate var preservesNotificationTopCurve = false
    /// The saved compact curve is expressed in the current sidebar host's
    /// local coordinates. AppKit moves the host's top edge by the display-rim
    /// depth during promotion, so this offset moves from the compact curve's
    /// local position to zero as the sidebar reaches its final frame.
    @Published fileprivate var notificationTopCurveStartOffset: CGFloat = 0
    fileprivate var notificationTopCurveFrame: CGRect?
    fileprivate var contentGeneration = 0
    private var contentPlacementStabilityScheduledGeneration: Int?
    // `MotionChild` reads this instead of a hardcoded curve so a reused
    // popover window's content can fade in on the same curve the window's
    // own frame is actually moving on. See `finishContentTransition` for why
    // that match matters -- a fixed, faster curve here left rows visibly
    // clipped by a still-growing window after they had already reached full
    // opacity.
    @Published var contentAnimation: SwiftUI.Animation = ShellMotion.contentIn.animation

    @discardableResult
    func beginContentTransition() -> Int {
        contentGeneration &+= 1
        contentReady = false
        contentProgress = 0
        contentPlacementStable = false
        contentPlacementStabilityScheduledGeneration = nil
        return contentGeneration
    }

    /// The reveal transaction is queued onto the next main-loop pass so the
    /// hosting view can commit its initial layout first. A close can arrive
    /// during that short window; do not let the stale queued reveal resurrect
    /// a surface that has already begun dismissing.
    fileprivate func isCurrentContentTransition(_ generation: Int) -> Bool {
        generation == contentGeneration
    }

    /// Arm the content tree once both physical phases are inside the safe
    /// placement band. The async hop is intentional: the phase callback also
    /// invalidates the shell-wide contour, and mounting the cards from that
    /// same callback makes SwiftUI measure them against the pre-commit frame.
    fileprivate func noteContentPlacementProgress() {
        let threshold = CaelestiaParityTokens.Popout.contentPlacementThreshold
        guard !contentPlacementStable,
              contourProgress >= threshold,
              surfacePlacementProgress >= threshold else { return }
        let generation = contentGeneration
        guard contentPlacementStabilityScheduledGeneration != generation else { return }
        contentPlacementStabilityScheduledGeneration = generation
        DispatchQueue.main.async { [weak self] in
            guard let self, self.contentGeneration == generation else { return }
            self.contentPlacementStabilityScheduledGeneration = nil
            guard !self.contentPlacementStable,
                  self.contourProgress >= threshold,
                  self.surfacePlacementProgress >= threshold else { return }
            self.contentPlacementStable = true
        }
    }

    func finishContentTransition(_ generation: Int, animation: SwiftUI.Animation = ShellMotion.contentIn.animation) {
        guard generation == contentGeneration else { return }
        // A reused popover window switching to a taller destination kind (a
        // hover pass from Wi-Fi or Audio onto Bluetooth, never a direct open)
        // animates its AppKit frame over `.panelSwitch` (500 ms), and the
        // surface's presentation viewport tracks that *live*, still-growing
        // frame -- see showRailPopover's reuse branch. This fade used to
        // always run on the fixed, faster `contentIn` curve (200 ms)
        // regardless of context, so the content reached full opacity roughly
        // 300 ms before the window finished growing to fit it: fully-colored
        // rows were visibly clipped by the window's own edge for that whole
        // remaining stretch, reading as a card in the wrong color/shade
        // rather than as a window still growing. A fresh popover open never
        // hits this because its AppKit frame is set to the final target size
        // synchronously before any animation starts, so there is nothing to
        // grow into. Passing the frame's own animation through here keeps
        // the two in step; the scalar phase below is what the content modifier
        // reads on every render frame.
        contentAnimation = animation
        if strictContentGate {
            // Rail content is revealed from the same display-linked phase as
            // the surface. A separate SwiftUI opacity clock can land between
            // two AppKit frame samples and expose a newly-sized row tree
            // before its contour/viewport has caught up. This boolean only
            // releases the already-staged tree; MotionChild derives its
            // visible opacity from the physical phase.
            var transaction = Transaction(animation: nil)
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                contentReady = true
                contentProgress = 1
            }
        } else {
            withAnimation(animation) {
                contentReady = true
                contentProgress = 1
            }
        }
    }

    /// Last-resort repair for a content reveal that never landed.
    ///
    /// `contentReady` gates every child through `MotionChild`, and it used to
    /// be driven by exactly one fire-and-forget timer. If anything called
    /// `beginContentTransition()` inside that window -- a conceal, a rebuild,
    /// a second reveal -- the generation advanced, the pending
    /// `finishContentTransition` was silently discarded by its guard, and
    /// nothing rescheduled it. `contentReady` then stayed false for the life
    /// of the surface: the card and its contour still painted (those layers do
    /// not consult it) while every child inside rendered at zero opacity.
    ///
    /// That state was also unrecoverable, because `showTop`/`showRight` return
    /// early when the surface is already considered visible and therefore skip
    /// the `reveal()` that would have restarted the sequence. One dropped
    /// timer blanked the surface until the shell was restarted.
    ///
    /// A presented surface must always end up with visible contents, so this
    /// asserts that invariant directly rather than trusting the handshake.
    func ensureContentReady(_ generation: Int) {
        guard generation == contentGeneration, presented else { return }
        if strictContentGate {
            guard !contentReady || !contentPlacementStable else { return }
            var transaction = Transaction(animation: nil)
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                contentReady = true
                contentProgress = 1
                // The watchdog is deliberately conservative. If a display
                // link was interrupted, this is the last safe release point;
                // the presented surface has had the full authored duration to
                // reach its terminal frame.
                contentPlacementStable = true
            }
        } else {
            guard !contentReady else { return }
            withAnimation(ShellMotion.contentIn.animation) {
                contentReady = true
                contentProgress = 1
            }
        }
    }

    // Existing always-visible surfaces (top bar, right edge, notification
    // cards) use an idempotent repair hook rather than a scheduled generation.
    // Keep that hook, but route it through the same scalar phase.
    func ensureContentReady() {
        guard presented, !contentReady else { return }
        withAnimation(ShellMotion.contentIn.animation) {
            contentReady = true
            contentProgress = 1
        }
    }

    /// Last-resort repair for a visible surface whose presentation clock was
    /// interrupted. The shell-wide fill can survive a display-link restart
    /// while the local contour remains at its seed value; on a reused panel
    /// that leaves an apparently empty Nexus or top bar even though its view
    /// hierarchy is still mounted. Once the surface is still presented and
    /// its generation is current, the only safe state is the settled state.
    func ensurePresentationReady(_ generation: Int) {
        guard generation == contentGeneration, presented else { return }
        let needsContour = contourProgress < 0.999
        let needsPlacement = surfacePlacementProgress < 0.999
        let needsContent = !contentReady || contentProgress < 0.999
            || (strictContentGate && !contentPlacementStable)
        guard needsContour || needsPlacement || needsContent else { return }

        var transaction = Transaction(animation: nil)
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            progress = 1
            surfacePlacementProgress = 1
            // `set` also stops a stalled display link, so a later tick cannot
            // write the old seed phase back over the repaired surface.
            if contourProgress < 0.999 {
                setContourProgress(1)
            }
            contentReady = true
            contentProgress = 1
            contentPlacementStable = true
        }
    }

    // Set when this surface was carried flush into the shell's top / bottom
    // rim because it had too little room left to complete an ordinary corner
    // curve. Drives the reverse fillet at the junction -- see
    // canonicalTopMorphPath's merge comment for the full rationale.
    @Published var mergeTopFillet: CGFloat = 0
    @Published var mergeBottomFillet: CGFloat = 0

    override init() {
        super.init()
        morphFromAttachment = nil
        morphFromFrame = nil
        notificationTopCurveFrame = nil
        blobDriver.onChange = { [weak self] deformation in
            self?.deformation = deformation
        }
        contourPhaseDriver.onChange = { [weak self] value in
            guard let self else { return }
            self.contourProgress = value
            self.noteContentPlacementProgress()
        }
        contourBlendDriver.onChange = { [weak self] value in
            self?.contourAttachmentBlend = value
            // Keep the original field synchronized for any legacy caller that
            // still reads it during a handoff.
            self?.attachmentBlend = value
        }
    }

    func setContourProgress(_ value: CGFloat) {
        contourPhaseDriver.set(value)
        if value < 0.999 {
            contentPlacementStable = false
        }
    }

    func animateContour(to value: CGFloat, using motion: ShellMotion, on screen: NSScreen? = nil) {
        contourPhaseDriver.animate(to: value, using: motion, on: screen) { [weak self] in
            guard let self, value >= 0.999 else { return }
            // Keep the completion as a final nudge for the stable-band
            // scheduler; it must not bypass the placement phase on a reused
            // panel whose AppKit frame is still travelling.
            self.noteContentPlacementProgress()
        }
    }

    func configureBlob(axis: CaelestiaSurfaceMotionAxis, travel: CGFloat) {
        blobDriver.configure(axis: axis, travel: travel)
    }

    fileprivate func setSuppressBottomBlobDeformation(_ enabled: Bool) {
        guard suppressBottomBlobDeformation != enabled else { return }
        suppressBottomBlobDeformation = enabled
        if enabled {
            blobDriver.reset()
        }
    }

    fileprivate func contourDeformation(for attachment: SurfaceAttachment) -> CaelestiaSurfaceDeformation {
        suppressBottomBlobDeformation && attachment == .bottom
            ? .identity
            : deformation
    }

    func sampleBlob(progress: CGFloat) {
        guard !suppressBottomBlobDeformation else { return }
        blobDriver.sample(progress: progress)
    }

    func sampleBlob(position: CGPoint) {
        guard !suppressBottomBlobDeformation else { return }
        blobDriver.sample(position: position)
    }

    /// Starts one generation-guarded topology handoff. The frame animator may
    /// be retargeted repeatedly by live provider updates, so delayed cleanup
    /// must never remove the outgoing layer belonging to a newer handoff.
    @discardableResult
    fileprivate func beginAttachmentTransition(
        from attachment: SurfaceAttachment,
        fromTopFillet: CGFloat,
        fromBottomFillet: CGFloat,
        fromFrame: CGRect? = nil
    ) -> Int {
        // If the pointer retargets the panel before the previous handoff has
        // settled, continue from the displayed blend instead of restarting at
        // zero. Restarting made both silhouettes disappear for a frame and
        // was the source of the intermittent shell disconnect.
        let startingBlend = morphFromAttachment == nil
            ? 0
            : min(1, max(0, contourAttachmentBlend))
        attachmentTransitionGeneration &+= 1
        morphFromAttachment = attachment
        morphFromTopFillet = fromTopFillet
        morphFromBottomFillet = fromBottomFillet
        morphFromFrame = fromFrame
        attachmentBlend = startingBlend
        contourAttachmentBlend = startingBlend
        contourBlendDriver.set(startingBlend)
        contourBlendDriver.animate(to: 1, using: .handoff)
        return attachmentTransitionGeneration
    }

    func finishAttachmentTransition(_ generation: Int) {
        guard generation == attachmentTransitionGeneration else { return }
        morphFromAttachment = nil
        morphFromTopFillet = 0
        morphFromBottomFillet = 0
        morphFromFrame = nil
        attachmentBlend = 1
        contourBlendDriver.set(1)
        contourAttachmentBlend = 1
    }

    func cancelAttachmentTransition() {
        attachmentTransitionGeneration &+= 1
        morphFromAttachment = nil
        morphFromTopFillet = 0
        morphFromBottomFillet = 0
        morphFromFrame = nil
        notificationTopCurveFrame = nil
        preservesNotificationTopCurve = false
        notificationTopCurveStartOffset = 0
        attachmentBlend = 1
        contourBlendDriver.set(1)
        contourAttachmentBlend = 1
    }

    /// Set a handoff blend from the same display-linked sample that moves the
    /// host window. A separate handoff driver is useful for ordinary rail
    /// reuse, but a compact notification dock expanding into the persistent
    /// sidebar needs the contour, frame, and content crossfade to share one
    /// clock or the old top-right shoulder can linger for a frame.
    fileprivate func setAttachmentBlend(_ value: CGFloat) {
        contourBlendDriver.set(min(1, max(0, value)))
    }

    func resetBlob() {
        blobDriver.reset()
    }
}

// Keep the physical silhouette fully opaque for almost all of dismissal, then
// hand it back to the resting frame before the morph reaches its necessarily
// tiny, near-rectangular seed. The last part of the fade reaches zero before
// the display-link can rasterize a one-pixel terminal cap; that cap otherwise
// reads as the little blue endpoint below Nexus while the persistent rim is
// already visible underneath it.
private let surfaceTerminalFadeStart: CGFloat = 0.24
private let surfaceTerminalFadeEnd: CGFloat = 0.08

private func surfaceTerminalOpacity(presented: Bool, progress: CGFloat) -> Double {
    if presented { return 1 }
    let p = max(0, min(1, progress))
    guard p > surfaceTerminalFadeEnd else { return 0 }
    let fade = (p - surfaceTerminalFadeEnd)
        / max(0.000_1, surfaceTerminalFadeStart - surfaceTerminalFadeEnd)
    return Double(min(1, max(0, fade)))
}

// A compact notification is promoted from the top-right corner into the
// persistent sidebar. The body can crossfade over the full spatial handoff,
// but carrying the old outline for that whole interval leaves a small rounded
// rectangle visibly trapped inside the growing sidebar. Let only this
// top-right -> sidebar contour resolve over the first part of the handoff;
// every other attachment morph keeps the shared blend unchanged.
private func notificationHandoffContourBlend(
    raw: CGFloat,
    from: SurfaceAttachment?,
    to: SurfaceAttachment
) -> Double {
    let phase = max(0, min(1, raw))
    guard from == .topRight, to == .rightSidebar else {
        return Double(phase)
    }
    let contourWindow: CGFloat = 0.24
    let localPhase = min(1, phase / contourWindow)
    return CaelestiaCurve.standard.value(at: Double(localPhase))
}

/// Applies the same centered matrix to SwiftUI content that the contour
/// layers apply to their paths. Keeping this as a geometry effect means the
/// child content, its clip, and the full-screen seam stay in the same
/// compositor transform while the BlobRect spring settles.
private struct CaelestiaSurfaceDeformationEffect: GeometryEffect {
    var deformation: CaelestiaSurfaceDeformation

    var animatableData: AnimatablePair<AnimatablePair<CGFloat, CGFloat>, CGFloat> {
        get {
            AnimatablePair(
                AnimatablePair(deformation.m00, deformation.m01),
                deformation.m11
            )
        }
        set {
            deformation.m00 = newValue.first.first
            deformation.m01 = newValue.first.second
            deformation.m11 = newValue.second
        }
    }

    func effectValue(size: CGSize) -> ProjectionTransform {
        ProjectionTransform(
            deformation.affineTransform(
                around: CGPoint(x: size.width / 2, y: size.height / 2)
            )
        )
    }
}

private struct ShellSurfaceDescriptor: Identifiable {
    let id: UUID
    var attachment: SurfaceAttachment
    var frame: CGRect
    var radius: CGFloat
    let motion: SurfaceMotionState
    /// Rim depth of the display this surface is drawn on. See
    /// `ShellDelegate.frameMotion(for:)`.
    var topDepth: CGFloat = shellFrame
}

private final class ShellFrameMotionState: ObservableObject {
    @Published var surfaces: [ShellSurfaceDescriptor] = []
    private var surfaceObservers: [UUID: AnyCancellable] = [:]
    /// Rim depth of the display this state belongs to, stamped onto every
    /// descriptor so the Shape types do not have to guess.
    ///
    /// Only `ShellDelegate.frameMotion(for:)` sets this, and it does so on
    /// every call. Attaching through the bare property instead left it at the
    /// flat-rim default, which drew the top popout's shoulder at the rim and
    /// silently removed its reverse curves -- and only until some unrelated
    /// surface used the accessor and fixed the depth as a side effect. Keeping
    /// the setter private means a surface cannot be attached to a state whose
    /// depth was never established.
    private(set) var topDepth: CGFloat = shellFrame

    func setTopDepth(_ depth: CGFloat) { topDepth = depth }

    func attach(_ motion: SurfaceMotionState, attachment: SurfaceAttachment, frame: CGRect, radius: CGFloat = 20) {
        if surfaceObservers[motion.id] == nil {
            // The contour is drawn by this object, not by the child hosting
            // view. Forward the child's display-linked phase/deformation so a
            // Canvas redraws for every legacy and reused surface frame.
            surfaceObservers[motion.id] = motion.objectWillChange.sink { [weak self] _ in
                self?.objectWillChange.send()
            }
        }
        let descriptor = ShellSurfaceDescriptor(id: motion.id, attachment: attachment, frame: frame, radius: radius, motion: motion, topDepth: topDepth)
        if let index = surfaces.firstIndex(where: { $0.id == motion.id }) { surfaces[index] = descriptor }
        else { surfaces.append(descriptor) }
    }

    func update(_ motion: SurfaceMotionState, frame: CGRect) {
        guard let index = surfaces.firstIndex(where: { $0.id == motion.id }) else { return }
        guard surfaces[index].frame != frame else { return }
        // Frame motion is sampled by an AppKit display link, not by a
        // published property on SurfaceMotionState. Mutating a field inside
        // the descriptor can therefore leave the shell-wide Canvas on its
        // previous frame -- most visible when Search grows into Nexus, or
        // when a legacy top/right panel is resized. Replace the descriptor
        // through the @Published array so fill, contour, and clip all receive
        // the same frame update.
        var updated = surfaces[index]
        updated.frame = frame
        surfaces[index] = updated
    }

    func detach(_ motion: SurfaceMotionState?) {
        guard let motion else { return }
        surfaces.removeAll { $0.id == motion.id }
        surfaceObservers[motion.id]?.cancel()
        surfaceObservers.removeValue(forKey: motion.id)
    }

    func reset() {
        surfaces.removeAll()
        surfaceObservers.values.forEach { $0.cancel() }
        surfaceObservers.removeAll()
    }
}

private struct LivingSurface<Content: View>: View {
    @ObservedObject var state: SurfaceMotionState
    let attachment: SurfaceAttachment
    /// Only consulted for `.top`, the one attachment whose silhouette carves
    /// out the display's rim. Every other attachment builds from depth 0, so
    /// the default is harmless for them.
    var topDepth: CGFloat = shellTopDepth()
    /// Notifications keep their typography and raster icons in an ordinary
    /// compositor layer. The shell contour still clips them to the same
    /// animated path, but the content itself must not be geometrically warped
    /// while the top-right surface is resizing.
    var deformsContent = true
    @ViewBuilder let content: () -> Content

    @ViewBuilder
    private var surfaceContent: some View {
        if deformsContent {
            content()
                .modifier(CaelestiaSurfaceDeformationEffect(deformation: state.deformation))
        } else {
            content()
        }
    }

    var body: some View {
        surfaceContent
            // Reveal and conceal with the physical surface contour itself.
            // A rectangular crop made the final frames of dismissal briefly
            // lose their curved shoulders, most visibly on the bottom-left
            // Power surface.
            // A mask rasterizes the whole content into an intermediate image
            // and then rasterizes the custom contour again. Popouts are small,
            // but this happens on every frame of every hover transition and
            // was the dominant compositor cost when several transitions were
            // interrupted in quick succession. ClipShape uses the same path
            // as a native clip/stencil and keeps the visual silhouette intact.
            .clipShape(ShellSurfaceMorphShape(
                attachment: attachment,
                finalFrame: .zero,
                radius: maskRadius,
                mergeTopFillet: state.mergeTopFillet,
                mergeBottomFillet: state.mergeBottomFillet,
                progress: state.contourProgress,
                topDepth: topDepth,
                contracting: !state.presented,
                omitTopReverseShoulder: state.preservesNotificationTopCurve
                    && attachment == .rightSidebar,
                preservedTopCurveStartY: state.preservesNotificationTopCurve
                    && attachment == .rightSidebar
                    ? state.notificationTopCurveStartOffset
                    : nil
            ))
            .opacity(surfaceTerminalOpacity(presented: state.presented, progress: state.contourProgress))
            .scaleEffect(
                deformsContent && attachment == .left
                    ? ShellMotion.initialScale + (1 - ShellMotion.initialScale) * state.contourProgress
                    : 1,
                anchor: .center
            )
            .allowsHitTesting(state.progress > 0.92)
            .background {
                GeometryReader { geometry in
                    Color.clear
                        .onAppear {
                            state.configureBlob(
                                axis: attachment.blobAxis,
                                travel: max(geometry.size.width, geometry.size.height)
                            )
                            state.sampleBlob(progress: state.progress)
                        }
                        .onChange(of: geometry.size) { _, size in
                            state.configureBlob(
                                axis: attachment.blobAxis,
                                travel: max(size.width, size.height)
                            )
                        }
                }
            }
            .onChange(of: state.progress) { _, progress in
                state.sampleBlob(progress: progress)
            }
            .onChange(of: attachment) { _, next in
                state.configureBlob(axis: next.blobAxis, travel: 400)
            }
            // A reused popout briefly owns two LivingSurface layers while its
            // attachment changes. Resetting the shared BlobRect driver from
            // the outgoing layer's onDisappear zeroed the spring underneath
            // the incoming layer, which is the visible “disconnect” during a
            // reverse handoff. The driver is owned by SurfaceMotionState and
            // is reset when that state is actually retired/deallocated.
    }

    private var maskRadius: CGFloat {
        shellAttachmentRadius(attachment)
    }
}

/// Scales a fixed-size attached surface as one composited unit when the
/// display is genuinely constrained. The identity branch keeps the existing
/// wide-display view tree and measurements untouched.
private struct CaelestiaResponsiveSurface<Content: View>: View {
    let scale: CGFloat
    let authoredSize: CGSize
    @ViewBuilder let content: () -> Content

    @ViewBuilder
    var body: some View {
        if scale >= 0.9999 {
            content()
        } else {
            content()
                .frame(width: authoredSize.width, height: authoredSize.height, alignment: .topLeading)
                .scaleEffect(scale, anchor: .topLeading)
                .frame(
                    width: authoredSize.width * scale,
                    height: authoredSize.height * scale,
                    alignment: .topLeading
                )
                .clipped()
        }
    }
}

private struct MotionChild: ViewModifier {
    @ObservedObject var state: SurfaceMotionState
    let index: Int
    var offset: CGSize = CGSize(width: 0, height: -8)
    var followsSurface = false

    func body(content: Content) -> some View {
        // The physical surface and its content handshake are intentionally
        // separate, but the handshake must never be able to strand a fully
        // opened card at zero opacity. If a rapid hover/reuse transition
        // supersedes the scheduled generation, `progress` still reaches its
        // terminal placement band and is a reliable last-resort reveal
        // signal. This only affects the final placement tail; the
        // A continuous phase prevents rows from reaching full opacity while
        // the surface is still growing. The non-strict fallback keeps legacy
        // long-lived surfaces fail-open, while rail popouts use the gated
        // scalar exclusively.
        // Rail content and the surface are sampled by the same display cycle.
        // Deriving opacity from those phases removes the second SwiftUI
        // animation clock that used to expose an intermediate row tree while
        // the reused AppKit host was still moving.
        let contourProgress = max(0, min(1, state.contourProgress))
        let placementProgress = max(0, min(1, state.surfacePlacementProgress))
        let physicalProgress = min(contourProgress, placementProgress)
        let placementThreshold = CaelestiaParityTokens.Popout.contentPlacementThreshold
        let placementComplete = physicalProgress >= placementThreshold
            && (!state.strictContentGate || state.contentPlacementStable)
        let strictContentProgress: CGFloat = {
            guard state.contentReady, placementComplete else { return 0 }
            // Release the already-staged tree from the guarded placement
            // band. The denominator makes this a short opacity tail instead
            // of an abrupt full-opacity switch at the threshold.
            guard placementThreshold < 0.999 else { return 1 }
            return max(
                0,
                min(
                    1,
                    (physicalProgress - placementThreshold)
                        / max(0.001, 1 - placementThreshold)
                )
            )
        }()
        let requestedContentProgress = state.strictContentGate
            ? strictContentProgress
            : (state.contentReady
                ? max(0, min(1, state.contentProgress))
                : (state.progress >= 0.98 ? 1 : 0))
        // `contentReady` is only the ordering handshake for rail surfaces;
        // their actual reveal is released only after the physical phase above
        // reaches its safe placement band. This makes the visible order invariant:
        // surface/card first, information second, with no nested relayout
        // while the viewport is still extending.
        let contentProgress = requestedContentProgress
        content
            // Match Caelestia's popout Loader: the physical surface follows
            // DefaultSpatial while its contents perform a pure opacity change
            // on DefaultEffects. The parent contour mask keeps those contents
            // inside the unfolding surface, so no scale or late flash is
            // needed here.
            .opacity(contentProgress)
            // The content has its own small hand-off into the surface. Keep
            // that hand-off spatial as well as opaque: a top-bar card should
            // arrive with the attached surface, not fade in already parked at
            // its final position. Reading the physical progress directly is
            // intentional -- adding a second implicit animation here would
            // make interrupted hover/open transitions lag behind the frame.
            .offset(
                x: followsSurface ? offset.width * (1 - state.contourProgress) : 0,
                y: followsSurface ? offset.height * (1 - state.contourProgress) : 0
            )
    }
}

private struct NexusScrollResetModifier: ViewModifier {
    let anchorID: String

    private func reset(_ proxy: ScrollViewProxy) {
        // AppKit-backed ScrollView instances can retain their last content
        // offset across a SwiftUI page replacement. The default anchor only
        // participates in the initial layout and does not repair that reused
        // native scroll view. Run after layout and once more after the
        // AppKit-backed scroll view has accepted its first content size,
        // without an animated jump, so the page title is always wholly inside
        // the viewport.
        let applyReset = {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                proxy.scrollTo(anchorID, anchor: .top)
            }
        }
        DispatchQueue.main.async {
            applyReset()
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
            applyReset()
        }
    }

    func body(content: Content) -> some View {
        ScrollViewReader { proxy in
            content
                .onAppear { reset(proxy) }
                .onChange(of: anchorID) { _, _ in reset(proxy) }
        }
    }
}

private extension View {
    func motionChild(
        _ state: SurfaceMotionState,
        index: Int,
        offset: CGSize = CGSize(width: 0, height: -8),
        followsSurface: Bool = false
    ) -> some View {
        modifier(MotionChild(state: state, index: index, offset: offset, followsSurface: followsSurface))
    }
}

private enum RailPopoverKind: Hashable {
    // Battery is back to having a popout -- it now carries a real Battery
    // Saver toggle, not just a duplicate readout, so it earns the surface.
    // Calendar is also back as a quick hover preview, alongside (not instead
    // of) the full calendar card that still lives in Nexus's overview page.
    case shell, activeApp, media, wifi, bluetooth, audio, battery, calendar, power, appShelf, workspace(Int), runningApp(Int32)
}

/// Caelestia's popout wrapper sizes the outer surface from each component's
/// authored content width, then adds the shared attached/far-edge envelope.
/// The live rail uses the upstream widths as sensible bounds, but status and
/// route cards are allowed to contract or expand around the text they show.
private func railPopoverBaseContentWidth(for kind: RailPopoverKind) -> CGFloat {
    let contentWidth: CGFloat
    switch kind {
    case .shell:
        contentWidth = shellStudioWidth
    case .power:
        contentWidth = sessionDrawerWidth
    case .appShelf:
        // The shelf is sized from the live application count below. This is a
        // compact fallback for the short interval before the first snapshot
        // lands, and keeps the bottom popout from ever becoming a full-width
        // second bar.
        contentWidth = 80
    case .activeApp, .runningApp, .workspace:
        contentWidth = CaelestiaParityTokens.Sizes.barWindowPreview
    case .media, .wifi, .bluetooth, .audio:
        contentWidth = railPopoverCardWidth
    case .battery:
        contentWidth = CaelestiaParityTokens.Sizes.barBatteryWidth
    case .calendar:
        contentWidth = CaelestiaParityTokens.Sizes.barTrayMenuWidth
    }
    return contentWidth
}

private func estimatedRailTextWidth(_ text: String) -> CGFloat {
    let font = NSFont.systemFont(ofSize: ShellTypography.body, weight: .semibold)
    return ceil((text as NSString).size(withAttributes: [.font: font]).width)
}

@MainActor
private func railPopoverContentWidth(
    for kind: RailPopoverKind,
    model: ShellModel?,
    nexus: MacPlusPlusNexusModel?
) -> CGFloat {
    let base = railPopoverBaseContentWidth(for: kind)
    guard let model else { return base }

    func bounded(_ value: CGFloat, minimum: CGFloat, maximum: CGFloat) -> CGFloat {
        min(maximum, max(minimum, value))
    }

    switch kind {
    case .appShelf:
        let count = min(appShelfMaxApplications, max(1, model.appRailApplications.count))
        let itemWidth = CGFloat(count) * appShelfItemWidth
        let gaps = CGFloat(max(0, count - 1)) * appShelfItemSpacing
        return bounded(
            itemWidth + gaps + appShelfHorizontalPadding * 2,
            minimum: 80,
            maximum: CGFloat(appShelfMaxApplications) * appShelfItemWidth
                + CGFloat(appShelfMaxApplications - 1) * appShelfItemSpacing
                + appShelfHorizontalPadding * 2
        )
    case .activeApp:
        let name = estimatedRailTextWidth(model.frontApp.uppercased())
        // Two 30pt metric cards plus their gap are the hard floor. The app
        // title may widen the strip, but an idle Finder card should not keep
        // the 400pt window-preview width just because it can.
        return bounded(max(220, name + 78), minimum: 220, maximum: 320)
    case .runningApp(let pid):
        let name = model.appRailApplications.first(where: { $0.id == pid })?.name ?? "APP CLOSED"
        // Five 30pt actions and their 6pt gaps are the hard floor for a live
        // app card; the name only earns the extra width it actually needs.
        return bounded(max(190, estimatedRailTextWidth(name.uppercased()) + 58), minimum: 190, maximum: 340)
    case .media:
        let title = estimatedRailTextWidth(model.media.title)
        let artist = estimatedRailTextWidth(model.media.artist)
        let album = estimatedRailTextWidth(model.media.album)
        // The artwork is 112pt wide and the transport row is narrower than
        // the metadata column. Keep a practical floor for that composition,
        // then let a long title/artist widen it without a blank tail.
        return bounded(max(300, max(title, max(artist, album)) + 154), minimum: 300, maximum: 400)
    case .calendar:
        // Seven weekday cells plus the grid's internal 4pt gaps need about
        // 250pt. The old 300pt value left a visibly empty desktop-side tail.
        return bounded(260, minimum: 248, maximum: 320)
    case .workspace(let index):
        let names = model.workspaces.first(where: { $0.id == index })?.windows
            .map { [$0.displayName, $0.app] }
            .flatMap { $0 } ?? []
        let widest = names.map(estimatedRailTextWidth).max() ?? 0
        return bounded(max(280, widest + 90), minimum: 280, maximum: 360)
    case .battery:
        let status = model.charging
            ? (model.batteryPercent >= 100
                ? "\(model.batteryPercent)% FULL"
                : "\(model.batteryPercent)% CHARGING")
            : "\(model.batteryPercent)% REMAINING"
        let health = model.batteryHealthPercent.flatMap { percent in
            model.batteryCycleCount.map { "HEALTH \(percent)% · \($0)C" }
        }
        // The exact time string belongs to the view below; this sizing pass
        // only needs the stable AC fallback so the connected state never
        // truncates the health summary.
        let powerState = model.charging ? "AC POWER" : nil
        let powerValues = [
            model.batterySystemPowerWatts.map { String(format: "%.1fW DRAW", $0) },
            model.batteryAdapterWatts.map { String(format: "%.0fW ADAPTER", $0) }
        ].compactMap { $0 }
        let widest = (["BATTERY SAVER", status, health, powerState] + powerValues)
            .compactMap { $0 }
            .map(estimatedRailTextWidth)
            .max() ?? 0
        // The power row has two independently labelled values. Allow that
        // row to determine the width, but keep the battery surface within the
        // same compact rail range as its sibling popouts.
        return bounded(widest + 122, minimum: 240, maximum: max(base, 340))
    case .audio:
        let names = (nexus?.outputDevices.map(\.name) ?? [])
            + (nexus?.inputDevices.map(\.name) ?? [])
        let widest = names.map(estimatedRailTextWidth).max() ?? 0
        return bounded(widest + 170, minimum: 250, maximum: 420)
    case .wifi:
        let names = railWiFiNetworks(from: model.knownNetworks, connected: model.connectedNetwork)
            .map(\.name)
        let widest = names.map(estimatedRailTextWidth).max() ?? 0
        return bounded(widest + 132, minimum: 220, maximum: 380)
    case .bluetooth:
        let names = railBluetoothDevices(from: model.bluetoothDevices)
            .map { estimatedRailTextWidth(compactAudioDeviceName($0.name)) }
        let widest = names.max() ?? 0
        return bounded(widest + 142, minimum: 240, maximum: 380)
    default:
        return base
    }
}

@MainActor
private func caelestiaRailPopoverSurfaceWidth(
    for kind: RailPopoverKind,
    model: ShellModel? = nil,
    nexus: MacPlusPlusNexusModel? = nil
) -> CGFloat {
    let contentWidth = railPopoverContentWidth(for: kind, model: model, nexus: nexus)
    return CaelestiaParityGeometry.popoutEnvelope(
        content: CGSize(width: contentWidth, height: 0),
        attached: kind == .appShelf ? .bottom : .leading
    ).width
}

/// The shell's hover surfaces share one presentation slot. Notifications are
/// the one intentional exception: a newly-arrived notification may be shown
/// over the surface the user is already reading, but a normal bell hover/click
/// participates in the same exclusive slot as every other popout.
private enum ShellPopoverSurface: Equatable {
    case drawer, top, right, power, rail, notification, sidebar, launcher
}

private struct RetiringShellPopover {
    let panel: NSWindow
    let motion: SurfaceMotionState?
    let frameMotion: ShellFrameMotionState?
}

/// Interaction color belongs to the rail on the display being used. Keeping
/// this separate from ShellModel prevents hovering a status glyph on one
/// monitor from lighting the matching glyph on every other monitor.
private final class RailVisualState: ObservableObject {
    @Published var hoveredKind: RailPopoverKind? = nil
    @Published var presentedKind: RailPopoverKind? = nil
}

// A tile replacement follows the physical direction the shared popover is
// travelling. The offset is deliberately small: the panel owns the large
// Caelestia spatial move, while the content only gives the eye a directional
// hand-off instead of sliding a second full card across the surface.
private enum PopoverContentDirection: Equatable {
    case none
    case leading
    case trailing
    case top
    case bottom
}

/// The Space viewer opens from the left rail into the desktop, so its physical
/// and content directions stay explicit: outward means rightward here. Keeping
/// this decision in one place prevents a workspace card from inheriting the
/// opposite direction when another popout was previously open.
private enum SpaceViewerDirection {
    static let attachment: SurfaceAttachment = .left
    static let content: PopoverContentDirection = .trailing
}

private final class RailPopoverState: ObservableObject {
    @Published var kind: RailPopoverKind
    @Published var attachment: SurfaceAttachment
    @Published var contentDirection: PopoverContentDirection = .none
    // The intrinsic destination box stays stable during a handoff. It is the
    // Swift equivalent of the active child's non-animated implicit size.
    @Published var contentSize: CGSize?
    // The lower envelope belongs to the destination layout, not to the live
    // contour sample. Reading mergeBottomFillet directly from popoverBody made
    // the content box gain/lose its lower shoulder as the AppKit frame crossed
    // the smoothing band. On a shrink, that moved the first and last cards
    // while the middle cards happened to retain their own stable bounds.
    @Published var contentBottomGutter: CGFloat?
    // A reused NSHostingView otherwise lets SwiftUI preserve backing layers
    // at the same structural positions when a shorter destination replaces a
    // taller one. The edge cards are the first layers to expose that reuse.
    // Bump this only for a real kind handoff and key the incoming tree as one
    // unit while it is still hidden behind the shared placement gate.
    @Published var contentRevision = 0
    // Keep workspace rows separate from ShellModel.workspaces while a live
    // popover grows. A yabai snapshot can arrive one run-loop turn before
    // AppKit commits the larger frame; rendering the new rows immediately
    // makes SwiftUI lay them out inside the old frame, which is the temporary
    // deformation that hover-out/hover-in used to repair. Commit this staged
    // snapshot only after the host reaches its destination frame.
    @Published var workspaceContentOverride: WorkspaceInfo?
    init(kind: RailPopoverKind, attachment: SurfaceAttachment = .left) {
        self.kind = kind
        self.attachment = attachment
        self.contentSize = nil
        self.contentBottomGutter = nil
        self.workspaceContentOverride = nil
    }

    func transitionAttachment(to next: SurfaceAttachment) {
        attachment = next
    }
}

private struct RailPopoverContentIdentity: Hashable {
    let kind: RailPopoverKind
    let revision: Int
}

/// One physical envelope around every connected rail popout. The edge facing
/// the rail reserves the 20pt smoothing band; the far edge and both
/// perpendicular edges reserve the same 12pt content gutter. Keeping this as
/// one value makes the measured content box, the live viewport, and the final
/// padding agree during both a fresh reveal and a resized handoff.
private struct RailPopoverEnvelope {
    let leading: CGFloat
    let trailing: CGFloat
    let top: CGFloat
    let bottom: CGFloat

    var horizontal: CGFloat { leading + trailing }
    var vertical: CGFloat { top + bottom }
}

private struct RailPopoverLivingSurface<Content: View>: View {
    @ObservedObject var motion: SurfaceMotionState
    @ObservedObject var surface: RailPopoverState
    @ViewBuilder let content: () -> Content

    private var attachment: SurfaceAttachment { surface.attachment }

    var body: some View {
        Group {
            if let from = motion.morphFromAttachment {
                ZStack {
                    LivingSurface(state: motion, attachment: from, deformsContent: false) {
                        content().opacity(1 - motion.contourAttachmentBlend)
                    }
                    LivingSurface(state: motion, attachment: attachment, deformsContent: false) {
                        content().opacity(motion.contourAttachmentBlend)
                    }
                }
            } else {
                LivingSurface(state: motion, attachment: attachment, deformsContent: false) {
                    content()
                }
            }
        }
    }
}

private func wifiNameKey(_ value: String) -> String {
    value
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .precomposedStringWithCanonicalMapping
}

private func wifiNamesEqual(_ lhs: String, _ rhs: String) -> Bool {
    wifiNameKey(lhs) == wifiNameKey(rhs)
}

private struct KnownWiFiNetwork: Identifiable, Hashable, Sendable {
    let name: String
    /// CoreWLAN exposes RSSI for a live scan. Remembered-network state is not
    /// a nearby result, so it is explicitly marked instead of being allowed
    /// to masquerade as one in the rail.
    let signalStrength: Int?
    let secure: Bool?
    let nearby: Bool

    init(
        name: String,
        signalStrength: Int? = nil,
        secure: Bool? = nil,
        nearby: Bool = false
    ) {
        self.name = name
        self.signalStrength = signalStrength
        self.secure = secure
        self.nearby = nearby
    }

    var id: String { name }
}

private struct BluetoothDeviceInfo: Identifiable, Hashable, Sendable {
    let address: String
    let name: String
    let connected: Bool
    let paired: Bool
    let nearby: Bool

    init(
        address: String,
        name: String,
        connected: Bool,
        paired: Bool = false,
        nearby: Bool = false
    ) {
        self.address = address
        self.name = name
        self.connected = connected
        self.paired = paired
        self.nearby = nearby
    }

    var id: String { address }
}

private func bluetoothAddressKey(_ address: String) -> String {
    address.lowercased().replacingOccurrences(of: "-", with: ":")
}

/// Keeps unpaired inquiry results alive while the controller's fast paired
/// snapshot and its slower inquiry take turns completing. The cache is
/// intentionally bounded: a device that is genuinely gone should not remain
/// in the shell forever, but closing the pill must not erase a device that was
/// just discovered.
private let bluetoothNearbyRetention: TimeInterval = 300

private struct BluetoothDiscoveryCache {
    private var lastSeen: [String: Date] = [:]

    mutating func record(_ devices: [BluetoothDeviceInfo], at date: Date) {
        for device in devices where device.nearby && !device.paired {
            lastSeen[bluetoothAddressKey(device.address)] = date
        }
    }

    mutating func retained(
        from devices: [BluetoothDeviceInfo],
        at date: Date
    ) -> [BluetoothDeviceInfo] {
        let cutoff = date.addingTimeInterval(-bluetoothNearbyRetention)
        var retained: [BluetoothDeviceInfo] = []
        var activeKeys = Set<String>()
        for device in devices where device.nearby && !device.paired {
            let key = bluetoothAddressKey(device.address)
            let seenAt = lastSeen[key] ?? date
            guard seenAt >= cutoff else { continue }
            if lastSeen[key] == nil { lastSeen[key] = date }
            activeKeys.insert(key)
            retained.append(device)
        }
        lastSeen = lastSeen.filter { activeKeys.contains($0.key) }
        return retained
    }
}

/// A connect/disconnect the user asked for that the radio has not confirmed yet.
///
/// `IOBluetoothDevice.openConnection()`/`closeConnection()` return once the
/// request is issued, not once the link has settled -- a headset routinely takes
/// two to four seconds. Without this, a single reconcile scheduled shortly after
/// the tap read the *old* link state, overwrote the row the user had just
/// changed, and the card flipped back before flipping forward again on a later
/// refresh. Holding the requested state until the radio agrees (or the deadline
/// passes) keeps one user action to one visible transition.
private struct BluetoothConnectionIntent {
    let connected: Bool
    let deadline: Date
}

/// How long an unconfirmed request keeps its requested state. Long enough for a
/// real link to negotiate, short enough that a request which silently failed
/// cannot pin a wrong row indefinitely.
private let bluetoothIntentTimeout: TimeInterval = 6
/// Reconcile passes after a request, in seconds. The last one falls after
/// `bluetoothIntentTimeout`, so the radio always gets the final word even if it
/// never reaches the requested state.
private let bluetoothSettleSchedule: [TimeInterval] = [0.6, 1.4, 2.6, 4.2, 6.4]
/// Hover re-entry is a presentation event, not a request to start another
/// controller inquiry. Keep a short quiet window for passive refreshes so a
/// pointer grazing the popout boundary cannot queue an aggressive scan loop.
private let bluetoothRefreshCooldown: TimeInterval = 1.5
/// Keep the connectivity tiles warm while the shell is idle. This is long
/// enough not to turn the Bluetooth inquiry into a constant background cost,
/// but short enough that opening a tile normally reads the already-published
/// inventory instead of waiting for its first scan.
private let connectivityBackgroundPollInterval: TimeInterval = 120

private struct AppRailWindowSnapshot: Equatable, Sendable {
    let id: Int
    let pid: Int32
    let appName: String
    let title: String
    let space: Int
    let isMinimized: Bool
    let usesFallbackWindowMetadata: Bool
}

private struct AppRailWindow: Identifiable, Equatable, Sendable {
    let id: Int
    let title: String
    let space: Int
    let isMinimized: Bool

    var displayName: String {
        let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "Untitled Window" : trimmed
    }
}

private struct AppRailApplication: Identifiable, Equatable, Sendable {
    let id: Int32
    let name: String
    let bundleIdentifier: String
    let bundlePath: String
    let windows: [AppRailWindow]

    var allWindowsMinimized: Bool {
        !windows.isEmpty && windows.allSatisfy { $0.isMinimized }
    }

    // A regular app can stay alive after its last window is closed. Keep that
    // process in the shelf, but give it the same subdued treatment as an app
    // whose entire window set is minimized.
    var isShelfDormant: Bool {
        windows.isEmpty || allWindowsMinimized
    }

    var shelfStatusDescription: String {
        if windows.isEmpty { return "running without an open window" }
        if allWindowsMinimized { return "all windows minimized" }
        return "running"
    }

    var supportsNewTab: Bool {
        let identity = "\(bundleIdentifier) \(name)".lowercased()
        return [
            "safari", "google chrome", "arc", "firefox", "brave",
            "microsoft edge", "orion", "terminal"
        ].contains { identity.contains($0) }
    }
}

/// Some windowed applications expose their real top-level window through a
/// helper process instead of a regular application process. Steam is the
/// common example: yabai reports the window under `Steam Helper`, while the
/// user-facing app is `Steam`. Keep the window id for focusing, but attach the
/// dock entry to the owning app so its icon and hide/quit actions are useful.
private func appRailOwnerApplication(for application: NSRunningApplication) -> NSRunningApplication {
    guard application.activationPolicy != .regular else { return application }
    let bundleIdentifier = application.bundleIdentifier?.lowercased() ?? ""
    let name = application.localizedName?.lowercased() ?? ""
    guard bundleIdentifier == "com.valvesoftware.steam.helper" || name == "steam helper" else {
        return application
    }
    return NSWorkspace.shared.runningApplications.first {
        $0.bundleIdentifier?.caseInsensitiveCompare("com.valvesoftware.steam") == .orderedSame
    } ?? application
}

/// The app rail is a dock for user-facing windowed applications, not a second
/// process monitor. Most Mac++ helpers are accessory apps with no normal
/// window, but a few of the audio/lighting and recovery owners do publish one
/// while they start or fail over. Filter them by bundle identity here so a
/// helper cannot appear merely because its window happens to satisfy yabai's
/// normal-window test.
private func appRailIsInternalApplication(_ application: NSRunningApplication) -> Bool {
    let bundleIdentifier = application.bundleIdentifier?.lowercased() ?? ""
    if bundleIdentifier.hasPrefix("org.macplusplus.macpp") ||
        bundleIdentifier == "org.macplusplus.audio-visualizer" ||
        bundleIdentifier == "org.macplusplus.input-helper" {
        return true
    }

    // Keep a name fallback for an app launched from an unsigned/legacy build
    // whose bundle identifier is temporarily unavailable to NSWorkspace.
    let name = (application.localizedName ?? "")
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased()
    return name.contains("mac++") || name.contains("macplusplus")
}

private let appRailTileSize: CGFloat = 22
private let appRailImageSize: CGFloat = 15
private let appRailStackSpacing: CGFloat = 3
// The ticker is an independent AppKit panel. Its visible lower edge sits well
// below the SwiftUI lane that reserves it, so the dock needs an optical
// correction before it can be centered against the visible calendar below.
private let appRailCalendarClearance: CGFloat = 60
private let appRailTickerPanelOffset: CGFloat = 100
private let appRailOpticalOffset = appRailTickerPanelOffset / 2
private let appRailVisibleCount = 6

// The app shelf is deliberately a single compact row. It is not a second
// launcher or a process monitor: windowed entries come from the same live
// snapshot that powers the running-app actions, while regular apps that have
// no open window remain available as subdued shelf entries.
private let appShelfMaxApplications = 8
// Equal circular hit areas keep the shelf from reading as a row of miniature
// macOS app tiles. The image is slightly smaller than the hit circle so the
// selected state can breathe without growing a square outline around it.
private let appShelfItemWidth: CGFloat = 40
private let appShelfItemHeight: CGFloat = 40
private let appShelfItemSpacing: CGFloat = 6
// The outer popover envelope owns the base horizontal gutter. The mirrored
// contour consumes additional optical room at the two side shoulders, so the
// shelf gets a 12pt inner inset to make its visible side gaps match the top.
private let appShelfHorizontalPadding: CGFloat = 14
// The bottom morph already contributes a broad free-edge shoulder above the
// row. Keep only a small 6pt content inset there so the top gap has a little
// visible side gaps after the contour's rounded shoulders are painted.
private let appShelfTopGutter: CGFloat = 6
// Keep the icon row close to the lower rim too. The outer reverse curve still
// owns its full smoothing band; this only reduces the shelf's content inset.
private let appShelfBottomGutter: CGFloat = 4
private let appShelfContentHeight: CGFloat = appShelfItemHeight
private let appShelfTriggerHeight: CGFloat = 12

private struct WorkspaceWindow: Identifiable, Equatable, Sendable {
    let id: Int
    let app: String
    let title: String

    var displayName: String {
        let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? app : trimmed
    }
}

private struct WorkspaceInfo: Identifiable, Equatable, Sendable {
    let id: Int
    /// A five-slot rail is part of the visual contract, but a slot must not
    /// be treated as a real yabai space until the provider has published it.
    let available: Bool
    var name: String
    var apps: [String]
    var windows: [WorkspaceWindow]

    init(
        id: Int,
        name: String,
        apps: [String] = [],
        windows: [WorkspaceWindow] = [],
        available: Bool = true
    ) {
        self.id = id
        self.available = available
        self.name = name
        self.apps = apps
        self.windows = windows
    }
}

// Caelestia's dashboard carries a real Weather tab (and a compact weather
// readout inside its Dash tab). Open-Meteo is used rather than a keyed
// service so this needs no account, no secret to keep out of the repo, and
// no per-user setup -- it takes a coordinate and returns current conditions
// plus a daily min/max.
private struct WeatherSnapshot: Equatable, Sendable {
    var temperature: Double = 0
    var apparent: Double = 0
    var high: Double = 0
    var low: Double = 0
    var humidity: Int = 0
    var windSpeed: Double = 0
    var code: Int = -1
    var place: String = ""
    var isDay: Bool = true
    var loaded: Bool = false

    // WMO weather interpretation codes, which is what Open-Meteo reports.
    // Grouped the same way caelestia groups them for its own icon mapping.
    var summary: String {
        switch code {
        case 0: return isDay ? "CLEAR" : "CLEAR NIGHT"
        case 1, 2: return "PARTLY CLOUDY"
        case 3: return "OVERCAST"
        case 45, 48: return "FOG"
        case 51, 53, 55, 56, 57: return "DRIZZLE"
        case 61, 63, 65, 66, 67: return "RAIN"
        case 71, 73, 75, 77: return "SNOW"
        case 80, 81, 82: return "SHOWERS"
        case 85, 86: return "SNOW SHOWERS"
        case 95, 96, 99: return "THUNDERSTORM"
        default: return "—"
        }
    }

    var symbol: String {
        switch code {
        case 0: return isDay ? "sun.max.fill" : "moon.stars.fill"
        case 1, 2: return isDay ? "cloud.sun.fill" : "cloud.moon.fill"
        case 3: return "cloud.fill"
        case 45, 48: return "cloud.fog.fill"
        case 51, 53, 55, 56, 57: return "cloud.drizzle.fill"
        case 61, 63, 65, 66, 67: return "cloud.rain.fill"
        case 71, 73, 75, 77: return "cloud.snow.fill"
        case 80, 81, 82: return "cloud.heavyrain.fill"
        case 85, 86: return "cloud.snow.fill"
        case 95, 96, 99: return "cloud.bolt.rain.fill"
        default: return "thermometer.medium"
        }
    }
}

/// Request a real Core Location fix for weather while retaining the IP lookup
/// as a privacy-friendly fallback when permission is unavailable. The former
/// path only read `CLLocationManager.location` after asking for permission and
/// never requested a fix, so a fresh login could remain on the IP fallback.
private final class WeatherLocationProvider: NSObject, CLLocationManagerDelegate {
    private let manager = CLLocationManager()
    var onCoordinate: ((Double, Double) -> Void)?
    var onAuthorizationChange: (() -> Void)?

    override init() {
        super.init()
        manager.delegate = self
        manager.desiredAccuracy = kCLLocationAccuracyKilometer
        manager.distanceFilter = 1000
    }

    func start() {
        manager.requestWhenInUseAuthorization()
        requestIfAuthorized()
    }

    func requestLocation() {
        requestIfAuthorized()
    }

    private func requestIfAuthorized() {
        switch manager.authorizationStatus {
        case .authorizedAlways, .authorizedWhenInUse:
            manager.requestLocation()
        default:
            break
        }
    }

    func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        requestIfAuthorized()
        onAuthorizationChange?()
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let location = locations.last, location.horizontalAccuracy >= 0 else { return }
        onCoordinate?(location.coordinate.latitude, location.coordinate.longitude)
    }

    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        // The weather fetch keeps its IP-derived fallback on denied or failed
        // fixes; a transient location error must not clear a valid card.
    }
}

private func workspacePopoverHeight(windowCount: Int) -> CGFloat {
    // The header badge counts unique apps, but the preview rows represent
    // individual windows. Size from the same bounded row count the view
    // renders so the AppKit panel cannot clip a window or leave a blank band.
    let visibleRowCount = max(1, min(4, windowCount))
    return 75 + leftPopoverVerticalInset * 2
        + CGFloat(visibleRowCount - 1) * 36
}

private func compactAudioDeviceName(_ rawName: String) -> String {
    rawName.trimmingCharacters(in: .whitespacesAndNewlines)
}

/// The complete paired and nearby device inventory is sorted by connection
/// state and name. The view uses a bounded scroll viewport without dropping
/// devices from the list.
private func railBluetoothDevices(from devices: [BluetoothDeviceInfo]) -> [BluetoothDeviceInfo] {
    devices.sorted { lhs, rhs in
        if lhs.connected != rhs.connected { return lhs.connected && !rhs.connected }
        if lhs.nearby != rhs.nearby { return lhs.nearby && !rhs.nearby }
        if lhs.paired != rhs.paired { return lhs.paired && !rhs.paired }
        return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
    }
}

private func blueutilExecutablePath() -> String? {
    [
        "/opt/homebrew/bin/blueutil",
        "/usr/local/bin/blueutil"
    ].first(where: { FileManager.default.isExecutableFile(atPath: $0) })
}

private func blueutilJSONDevices(
    arguments: [String],
    nearby: Bool,
    timeout: TimeInterval
) -> [BluetoothDeviceInfo] {
    guard let executable = blueutilExecutablePath() else { return [] }
    let output = capturedCommand(
        executable,
        arguments + ["--format", "json"],
        timeout: timeout
    )
    guard let data = output.data(using: .utf8),
          let object = try? JSONSerialization.jsonObject(with: data), // macpp:silent-ok malformed blueutil JSON yields no Bluetooth devices
          let rows = object as? [[String: Any]] else { return [] }

    return rows.compactMap { row in
        guard let rawAddress = row["address"] as? String else { return nil }
        let address = rawAddress.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !address.isEmpty else { return nil }
        let rawName = (row["name"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return BluetoothDeviceInfo(
            address: address,
            name: rawName.isEmpty ? "BLUETOOTH DEVICE" : rawName,
            connected: (row["connected"] as? Bool) ?? false,
            paired: nearby ? ((row["paired"] as? Bool) ?? false) : true,
            nearby: nearby
        )
    }
}

/// blueutil's inquiry is the macOS equivalent of Caelestia's live Bluetooth
/// model: it asks the controller for devices currently in range instead of
/// reading only the paired/recent device registry. It is optional so the
/// shell still has a native IOBluetooth fallback on machines without the
/// Homebrew utility.
private func blueutilNearbyDevices(duration: TimeInterval = 4) -> [BluetoothDeviceInfo] {
    let seconds = max(2, min(10, Int(duration.rounded())))
    return blueutilJSONDevices(
        arguments: ["--inquiry", String(seconds)],
        nearby: true,
        timeout: TimeInterval(seconds) + 4
    )
}

/// The native bridge is normally the fastest paired/recent snapshot, but its
/// Obj-C collection can briefly be empty while the Bluetooth controller is
/// waking. Keep the paired registry as a second fast source so a shell reload
/// never turns a known inventory into a blank card just because discovery has
/// not completed yet.
private func blueutilPairedDevices() -> [BluetoothDeviceInfo] {
    blueutilJSONDevices(
        arguments: ["--paired"],
        nearby: false,
        timeout: 4
    )
}

private func mergeBluetoothDevices(
    _ base: [BluetoothDeviceInfo],
    _ nearby: [BluetoothDeviceInfo]
) -> [BluetoothDeviceInfo] {
    var merged: [String: BluetoothDeviceInfo] = [:]

    func insert(_ item: BluetoothDeviceInfo) {
        let key = bluetoothAddressKey(item.address)
        guard let existing = merged[key] else {
            merged[key] = item
            return
        }
        let existingName = existing.name.trimmingCharacters(in: .whitespacesAndNewlines)
        let itemName = item.name.trimmingCharacters(in: .whitespacesAndNewlines)
        let name = existingName.isEmpty || existingName == "BLUETOOTH DEVICE"
            ? (itemName.isEmpty ? existing.name : item.name)
            : existing.name
        merged[key] = BluetoothDeviceInfo(
            address: existing.address,
            name: name,
            connected: existing.connected || item.connected,
            paired: existing.paired || item.paired,
            nearby: existing.nearby || item.nearby
        )
    }

    base.forEach(insert)
    nearby.forEach(insert)
    return Array(merged.values)
}

/// Execute a blueutil transport operation without putting a pairing prompt or
/// a potentially slow controller handshake on the shell's main actor.
private func runBlueutil(_ arguments: [String], timeout: TimeInterval = 10) -> Bool {
    guard let executable = blueutilExecutablePath() else { return false }
    return runBoundedShellCommand(executable, arguments, timeout: timeout).succeeded
}

// Keep the popout from growing past the useful desktop envelope, but do not
// confuse the viewport budget with the inventory size. Rows beyond this
// number remain available through the ScrollView in the Bluetooth body.
private let bluetoothRailVisibleRowLimit = 6

private func bluetoothDeviceListHeight(deviceCount: Int) -> CGFloat {
    let visibleRows = max(1, min(bluetoothRailVisibleRowLimit, deviceCount))
    return CGFloat(visibleRows) * PopoverCard.rowHeight
        + CGFloat(max(0, visibleRows - 1)) * PopoverCard.stackSpacing
}

private func bluetoothPopoverHeight(deviceCount: Int) -> CGFloat {
    let rows = bluetoothDeviceListHeight(deviceCount: deviceCount)
    // Preserve the previous Bluetooth headroom while keeping the newer
    // compact viewport. The reused panel follows an overshooting handoff
    // curve; giving only the row stack this small buffer prevents the last
    // device row from becoming the edge layer during the settle-back.
    let bufferedRows = rows * 1.05
    // Header, count line, and device stack, with the same 8pt rhythm as the
    // QML ColumnLayout. Settings is an icon in the header, not a full row.
    let contentHeight = PopoverCard.headerHeight
        + 18
        + bufferedRows
        + CGFloat(2) * PopoverCard.stackSpacing
    return contentHeight + leftPopoverVerticalInset * 2
}

private let wifiPopoverRowSpacing: CGFloat = PopoverCard.stackSpacing
/// Caelestia sorts access points with the active network first. Rail popouts
/// use the default eight-row limit; Nexus passes `nil` so its scrollable page
/// can expose the complete live inventory. A live CoreWLAN scan supplies
/// strength/security metadata; preferred-network and diagnostics fallbacks
/// remain valid rows without metadata. Include a known current SSID when a
/// permission-limited scan omits it, so the active connection does not
/// disappear between refreshes.
private func railWiFiNetworks(
    from networks: [KnownWiFiNetwork],
    connected: String,
    limit: Int? = 8
) -> [KnownWiFiNetwork] {
    var bestByName: [String: KnownWiFiNetwork] = [:]
    let connectedKey = wifiNameKey(connected)
    // Only entries produced by a live scan belong in this list. Cached and
    // preferred profiles remain useful for connection fallback, but showing
    // them beside nearby APs made a stale remembered-network list look like a
    // hardware scan.
    for network in networks where network.nearby && !wifiNameKey(network.name).isEmpty {
        let key = wifiNameKey(network.name)
        guard let existing = bestByName[key] else {
            bestByName[key] = network
            continue
        }
        // A name can occur on multiple bands/BSSIDs. Retain the strongest
        // live result while preserving a metadata-bearing entry when one of
        // the fallbacks supplied only the SSID.
        let existingStrength = existing.signalStrength ?? Int.min
        let candidateStrength = network.signalStrength ?? Int.min
        if candidateStrength > existingStrength
            || (existing.signalStrength == nil && network.signalStrength != nil) {
            bestByName[key] = network
        }
    }
    if !connectedKey.isEmpty && bestByName[connectedKey] == nil {
        bestByName[connectedKey] = KnownWiFiNetwork(name: connected)
    }
    let sorted = bestByName.values.sorted { lhs, rhs in
        let leftActive = wifiNamesEqual(lhs.name, connected)
        let rightActive = wifiNamesEqual(rhs.name, connected)
        if leftActive != rightActive { return leftActive && !rightActive }
        if lhs.signalStrength != rhs.signalStrength {
            return (lhs.signalStrength ?? Int.min) > (rhs.signalStrength ?? Int.min)
        }
        return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
    }
    guard let limit else { return sorted }
    return Array(sorted.prefix(max(0, limit)))
}

/// CoreWLAN's synchronous inventory call belongs on the utility worker: the
/// scan can take long enough to block a render frame if it runs on the shell's
/// main actor. Keep this small helper free of UI state so the caller can union
/// several radio frames without freezing popout animation.
private func scanCoreWiFi(interfaceName: String) -> (networks: [KnownWiFiNetwork], succeeded: Bool, failure: String, ssid: String) {
    let client = CWWiFiClient.shared()
    let interface = client.interface(withName: interfaceName) ?? client.interface()
    guard let interface else {
        return ([], false, "interface unavailable", "")
    }
    do {
        let scanned = try interface.scanForNetworks(withSSID: nil)
        var strongestByName: [String: KnownWiFiNetwork] = [:]
        for network in scanned {
            guard let name = network.ssid, !name.isEmpty else { continue }
            let candidate = KnownWiFiNetwork(
                name: name,
                signalStrength: network.rssiValue,
                // CWNetwork exposes SSID/RSSI but not a portable security flag
                // on current macOS. Leave it unknown rather than labelling an
                // open AP as protected.
                secure: nil,
                nearby: true
            )
            if let existing = strongestByName[name],
               (existing.signalStrength ?? Int.min) >= (candidate.signalStrength ?? Int.min) {
                continue
            }
            strongestByName[name] = candidate
        }
        let networks = strongestByName.values.sorted {
            if $0.signalStrength != $1.signalStrength {
                return ($0.signalStrength ?? Int.min) > ($1.signalStrength ?? Int.min)
            }
            return $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
        }
        return (networks, true, "", interface.ssid() ?? "")
    } catch {
        return ([], false, String(describing: error), interface.ssid() ?? "")
    }
}

/// Read the associated SSID independently of the nearby scan. On current
/// macOS, a successful CoreWLAN scan can return a full AP inventory while its
/// scan result's `ssid()` field is empty; treating that field as the only
/// current-network source makes the active row disappear even though the Mac
/// is connected.
private func currentCoreWiFiSSID(interfaceName: String) -> String {
    let client = CWWiFiClient.shared()
    let interface = client.interface(withName: interfaceName) ?? client.interface()
    return interface?.ssid() ?? ""
}

/// Tahoe can expose the associated SSID through `ipconfig getsummary` after
/// its Wi-Fi-info visibility setting has been enabled. Prefer this live link
/// summary over remembered profiles; it is the same interface-specific source
/// a user can inspect from Terminal and it remains empty when macOS still
/// redacts the value.
private func ipconfigCurrentWiFiSSID(interfaceName: String) -> String {
    let output = capturedCommand(
        "/usr/sbin/ipconfig",
        ["getsummary", interfaceName],
        timeout: 2
    )
    for rawLine in output.split(whereSeparator: \.isNewline) {
        let line = String(rawLine)
        guard let separator = line.firstIndex(of: ":") else { continue }
        let key = line[..<separator].trimmingCharacters(in: .whitespacesAndNewlines)
        guard key.localizedCaseInsensitiveCompare("SSID") == .orderedSame else { continue }
        let value = line[line.index(after: separator)...]
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let lowered = value.lowercased()
        guard !value.isEmpty,
              value != "<redacted>",
              !lowered.contains("not associated"),
              !lowered.contains("unknown") else { continue }
        return value
    }
    return ""
}

/// `networksetup -getairportnetwork` can report "not associated" while the
/// Wi-Fi interface still owns the live default route. That is the privacy-
/// redacted state on newer macOS builds: the transport is connected, but the
/// SSID is withheld from the process. `scutil --nwi` is the authoritative
/// transport-side fallback because it reports whether this exact interface is
/// currently reachable without guessing a network name.
private func wifiInterfaceIsReachable(_ interfaceName: String, from output: String) -> Bool {
    let prefix = interfaceName.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !prefix.isEmpty else { return false }
    var inInterfaceBlock = false
    for rawLine in output.split(whereSeparator: \.isNewline) {
        let line = String(rawLine)
        let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            if inInterfaceBlock { return false }
            continue
        }
        if trimmed.range(of: "^\(NSRegularExpression.escapedPattern(for: prefix))\\s*:", options: .regularExpression) != nil {
            inInterfaceBlock = true
            continue
        }
        guard inInterfaceBlock else { continue }
        // The next top-level interface begins at the same indentation as the
        // one we matched. Treat it as a boundary rather than borrowing its
        // reachability state.
        if !line.hasPrefix(" ") || line.range(of: #"^\s+[A-Za-z0-9._-]+\s+:\s+flags"#, options: .regularExpression) != nil {
            return false
        }
        if trimmed.localizedCaseInsensitiveContains("(not reachable)") {
            return false
        }
        if trimmed.localizedCaseInsensitiveContains("(reachable)") {
            return true
        }
    }
    return false
}

private func wifiAvailableNetworkCount(
    from networks: [KnownWiFiNetwork],
    connected: String
) -> Int {
    var names = Set(networks.filter(\.nearby).map { wifiNameKey($0.name) })
    let connectedKey = wifiNameKey(connected)
    if !connectedKey.isEmpty { names.insert(connectedKey) }
    return names.count
}

private func bundledWiFiScannerPath() -> String? {
    guard let url = Bundle.main.url(forResource: "macpp-wifi-scan", withExtension: "py"),
          FileManager.default.isReadableFile(atPath: url.path) else { return nil }
    return url.path
}

/// Run the Apple CoreWLAN scanner outside the hardened SwiftUI process. The
/// helper is not a remembered-network reader: it asks the controller for the
/// live BSSID inventory and returns the strongest result for each SSID.
private func scanAppleWiFiCLI(interfaceName: String) -> (
    networks: [KnownWiFiNetwork],
    succeeded: Bool,
    failure: String,
    ssid: String
) {
    guard let executable = bundledWiFiScannerPath() else {
        return ([], false, "scanner unavailable", "")
    }
    guard FileManager.default.isExecutableFile(atPath: "/usr/bin/python3") else {
        return ([], false, "system Python unavailable", "")
    }
    let output = capturedCommand(
        "/usr/bin/python3",
        [executable, "--interface", interfaceName],
        timeout: 20
    )
    guard let data = output.data(using: .utf8),
          let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { // macpp:silent-ok malformed Wi-Fi helper output is surfaced as an invalid scanner response
        return ([], false, "invalid scanner response", "")
    }
    let currentSSID = (object["ssid"] as? String) ?? ""
    let succeeded = (object["ok"] as? Bool) ?? false
    let failure = (object["error"] as? String) ?? ""
    let networks = (object["networks"] as? [[String: Any]] ?? []).compactMap { row -> KnownWiFiNetwork? in
        guard let name = row["ssid"] as? String, !name.isEmpty else { return nil }
        let rssi = (row["rssi"] as? NSNumber)?.intValue
        return KnownWiFiNetwork(
            name: name,
            signalStrength: rssi,
            secure: nil,
            nearby: true
        )
    }
    return (networks, succeeded, failure, currentSSID)
}

/// `wdutil info` is useful for the currently associated link, but Apple does
/// not expose a nearby-network scan through that command. On newer macOS it
/// also requires an already-authorized `sudo` session and may redact SSIDs.
/// Try it opportunistically for the current SSID only; never block a scan or
/// prompt for a password from a hover surface.
private func wdutilCurrentSSID(from output: String) -> String {
    for rawLine in output.split(separator: "\n") {
        let line = String(rawLine)
        guard let separator = line.firstIndex(of: ":") else { continue }
        let key = line[..<separator].trimmingCharacters(in: .whitespacesAndNewlines)
        guard key.localizedCaseInsensitiveCompare("SSID") == .orderedSame else { continue }
        let value = line[line.index(after: separator)...]
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let lowered = value.lowercased()
        if !value.isEmpty, value != "<redacted>", !lowered.contains("not associated") {
            return value
        }
    }
    return ""
}

private func wifiPopoverHeight(
    networkCount: Int,
    hasVPN: Bool,
    hasHiddenConnection: Bool = false
) -> CGFloat {
    let visibleRows = max(1, min(8, networkCount))
    let rows = CGFloat(visibleRows) * PopoverCard.rowHeight
        + CGFloat(max(0, visibleRows - 1)) * wifiPopoverRowSpacing
    let hiddenConnectionHeight = hasHiddenConnection ? PopoverCard.rowHeight : 0
    let vpnHeight = hasVPN ? PopoverCard.rowHeight : 0
    let itemCount = (hasVPN ? 3 : 2) + (hasHiddenConnection ? 1 : 0)
    // Header, optional redacted active-network row, network stack, and
    // optional VPN row. Rescan is an icon in the header, so the
    // surface does not carry a redundant action row.
    let contentHeight = PopoverCard.headerHeight
        + hiddenConnectionHeight
        + rows
        + vpnHeight
        + CGFloat(itemCount - 1) * PopoverCard.stackSpacing
    return contentHeight + leftPopoverVerticalInset * 2
}

/// Battery uses a 36pt status tile, a 34pt power telemetry row, and a 30pt
/// saver row. The explicit rhythm keeps the AppKit host and the SwiftUI stack
/// on the same geometry during a live power-source update.
private let batteryPopoverContentHeight: CGFloat = 154

/// The audio popout owns its full route inventory. Unlike Wi-Fi, its rows are
/// the primary content rather than an optional nearby-network list, so the
/// AppKit host must grow with every rendered route instead of sizing for a
/// capped prefix and hiding the tail inside the ScrollView.
private let audioPopoverRowSpacing: CGFloat = 6

private func audioPopoverRowCount(_ count: Int) -> Int {
    max(1, count)
}

private func audioPopoverContentHeight(outputCount: Int, inputCount: Int) -> CGFloat {
    let header: CGFloat = PopoverCard.rowHeight
    let sectionLabel: CGFloat = 16
    let outputRows = CGFloat(audioPopoverRowCount(outputCount)) * PopoverCard.rowHeight
        + CGFloat(max(0, audioPopoverRowCount(outputCount) - 1)) * audioPopoverRowSpacing
    let inputRows = CGFloat(audioPopoverRowCount(inputCount)) * PopoverCard.rowHeight
        + CGFloat(max(0, audioPopoverRowCount(inputCount) - 1)) * audioPopoverRowSpacing
    // CaelestiaDivider is one point high and the view adds the same 2pt
    // vertical padding above and below it. Omitting that padding makes the
    // last input/state row begin below the host's measured bottom edge.
    let separator: CGFloat = 1 + Spacing.hairline * 2
    let stateRow: CGFloat = PopoverCard.rowHeight
    let itemCount = 7 // header, two labels, two lists, separator, state row
    return header
        + sectionLabel
        + outputRows
        + separator
        + sectionLabel
        + inputRows
        + stateRow
        + CGFloat(itemCount - 1) * PopoverCard.stackSpacing
}

/// 126pt media row with a 112pt picture-in-picture preview, followed by a
/// 16pt progress row and 38pt transport row. The primary transport button is
/// 38pt tall, so the row must reserve its full height or the shared popover
/// clip trims its lower edge by a pixel or two.
private let mediaArtworkSize: CGFloat = 112
private let mediaArtworkRowHeight: CGFloat = 126
private let mediaPopoverContentHeight: CGFloat = 196
// The active-app card sits immediately above the media lane on compact
// displays. Keep a small collision buffer so two left-rail surfaces never
// animate through one another's reverse shoulders.
private let railPopoverCrowdedHandoffClearance: CGFloat = 18

private func calendarPopoverHeight(for now: Date) -> CGFloat {
    // A static height budgeted for the worst case (6 day rows) left a
    // visible gutter under 5-row months -- most months, most of the time.
    // Mirror MiniCalendarCard's own row-count math here instead, so the
    // popout always shrink-wraps to whichever month is actually showing.
    let calendar = Calendar.current
    let range = calendar.range(of: .day, in: .month, for: now) ?? 1..<2
    let first = calendar.date(from: calendar.dateComponents([.year, .month], from: now)) ?? now
    let leading = (calendar.component(.weekday, from: first) - calendar.firstWeekday + 7) % 7
    let rows = max(1, Int(ceil(Double(leading + range.count) / 7.0)))
    // 36pt header card (matching every sibling popout's header), the
    // weekday row (~14) and day grid (19pt cells, 4pt spacing) inside their
    // own card with 8pt of padding top and bottom, separated by
    // MiniCalendarCard's own 8pt VStack gaps (2 gaps here).
    let headerHeight: CGFloat = 36
    let weekdayRowHeight: CGFloat = 14
    let gridCardPadding: CGFloat = 16
    let gridHeight = CGFloat(rows) * 19 + CGFloat(max(0, rows - 1)) * 4
    return headerHeight + weekdayRowHeight + gridHeight + gridCardPadding + 16 + leftPopoverVerticalInset * 2
}

private func appRailPopoverHeight(for application: AppRailApplication?) -> CGFloat {
    // App tiles use the same compact header + symbol action row as the active
    // app popout. Window names and per-window resource detail belong in the
    // full Work/Nexus views; repeating them here made the rail card tall and
    // visually unlike the small app-dock popout in the shell.
    return activeAppPopoverContentHeight + leftPopoverVerticalInset * 2
}

// The frontmost-app surface is intentionally a compact command strip. Its
// identity header and one icon-only action row keep the top rail useful
// without repeating the resource metrics already shown in Dashboard.
private let activeAppPopoverContentHeight: CGFloat = 74

private struct PerformanceSample: Equatable, Sendable {
    var cpuUse = 0.0
    var gpuUse = 0.0
    var ramUse = 0.0
    var diskUse = 0.0
    var cpuTemp: Double?
    var gpuTemp: Double?
}

/// Format every live utilization surface from the same bounded value.
///
/// Nexus used truncation while the top popout rounded its gauge value. That
/// was only a one-point discrepancy at the boundary, but a shared formatter
/// keeps the two surfaces visibly tied to the same reading and gives future
/// cards one source of display truth.
private func performancePercent(_ value: Double) -> Int {
    Int((min(1, max(0, value)) * 100).rounded())
}

/// Local process data shape for Shell performance rows. No account or network
/// service is involved in collecting the public overview metrics.
private struct LocalProcessSample: Codable, Sendable {
    let pid: Int
    let name: String
    let cpu: Double
    let memory: Double
}

/// A foreground application is rarely one process on macOS. Electron and
/// WebKit apps put their renderer, GPU, network, and service processes beside
/// the app process, so a single PID makes the active-app card look falsely
/// quiet. This sampler stays local
/// to the card: it is only started while the card/dashboard is visible and
/// reads one compact `ps` table per second.
private struct MacPlusPlusProcessResourceRow {
    let pid: pid_t
    let parentPID: pid_t
    let cpuPercent: Double
    let residentBytes: UInt64
    let commandLine: String
}

private func macppProcessResourceRows() -> [pid_t: MacPlusPlusProcessResourceRow] {
    let process = Process()
    let output = Pipe()
    process.executableURL = URL(fileURLWithPath: "/bin/ps")
    process.arguments = ["-axo", "pid=,ppid=,%cpu=,rss=,command="]
    process.standardOutput = output
    process.standardError = FileHandle.nullDevice
    do {
        try process.run()
    } catch {
        MacPlusPlusBoundaryLog.record(
            "Active-app resource probe could not start ps: \(error)",
            key: "active-app-resource-probe",
            minimumInterval: 60
        )
        return [:]
    }
    // Drain the pipe before waiting for the child.  The complete process table
    // can exceed the pipe buffer; waiting first deadlocks `ps`, which left the
    // active-window card stuck at its initial zero CPU/RAM values.
    let data = output.fileHandleForReading.readDataToEndOfFile()
    process.waitUntilExit()

    let raw = String(
        data: data,
        encoding: .utf8
    ) ?? ""
    var rows: [pid_t: MacPlusPlusProcessResourceRow] = [:]
    for line in raw.split(separator: "\n", omittingEmptySubsequences: true) {
        let fields = line.split(
            maxSplits: 4,
            omittingEmptySubsequences: true,
            whereSeparator: { $0 == " " || $0 == "\t" }
        )
        guard fields.count == 5,
              let pidValue = Int32(fields[0]),
              let parentPIDValue = Int32(fields[1]),
              let cpu = Double(fields[2]),
              let residentKB = UInt64(fields[3]) else { continue }
        rows[pid_t(pidValue)] = MacPlusPlusProcessResourceRow(
            pid: pid_t(pidValue),
            parentPID: pid_t(parentPIDValue),
            cpuPercent: max(0, cpu),
            residentBytes: residentKB.multipliedReportingOverflow(by: 1024).overflow
                ? UInt64.max
                : residentKB * 1024,
            commandLine: String(fields[4])
        )
    }
    return rows
}

private func macppAppResourceSnapshot(
    pid: pid_t,
    bundlePath: String
) -> (cpuPercent: Double, residentBytes: UInt64)? {
    let rows = macppProcessResourceRows()
    guard !rows.isEmpty else { return nil }

    var included: Set<pid_t> = []
    if rows[pid] != nil { included.insert(pid) }
    let normalizedBundlePath = bundlePath.hasSuffix("/")
        ? String(bundlePath.dropLast())
        : bundlePath
    if !normalizedBundlePath.isEmpty {
        for row in rows.values where
            row.commandLine == normalizedBundlePath
            || row.commandLine.hasPrefix(normalizedBundlePath + "/") {
            included.insert(row.pid)
        }
    }

    // Include descendants even when WebKit/Electron has placed a helper
    // outside the app bundle. Repeat to cover grandchildren and short-lived
    // service chains without ever crossing into an unrelated process tree.
    var changed = true
    while changed {
        changed = false
        for row in rows.values where
            !included.contains(row.pid) && included.contains(row.parentPID) {
            included.insert(row.pid)
            changed = true
        }
    }
    guard !included.isEmpty else { return nil }

    let appRows = rows.values.filter { included.contains($0.pid) }
    let cpu = appRows.reduce(0.0) { $0 + $1.cpuPercent }
    let memory = appRows.reduce(UInt64(0)) { total, row in
        let (sum, overflow) = total.addingReportingOverflow(row.residentBytes)
        return overflow ? UInt64.max : sum
    }
    return (min(999, max(0, cpu)), memory)
}

/// Point-size multiplier for a transport glyph.
///
/// `gobackward.15` and `goforward.15` carry a numeral inside the arc, so at a
/// given point size their arrow is drawn considerably smaller than a solid
/// `backward.fill` triangle in order to make room for it. Set to the same
/// size they read as noticeably smaller than the buttons either side of them.
/// Scaling here rather than at each call site means every seek control in the
/// shell stays consistent, including any added later.
private func mediaGlyphScale(_ symbol: String) -> CGFloat {
    symbol.hasPrefix("goforward") || symbol.hasPrefix("gobackward") ? 1.22 : 1
}

/// Kept deliberately in step with the canonical media lists in the wallpaper
/// engine. When the shell's list was narrower, a wallpaper the engine happily
/// rendered was invisible to the carousel and got no poster.
private let macppWallpaperVideoExtensions = ["mp4", "mov", "m4v", "avi", "mpg", "mpeg", "3gp"]
private let macppWallpaperImageExtensions = ["jpg", "jpeg", "png", "heic", "webp", "tif", "tiff"]
private let macppWallpaperMediaExtensions = macppWallpaperVideoExtensions + macppWallpaperImageExtensions
private let macppWallpaperCatalogChangedNotification = Notification.Name("org.macplusplus.macpp-wallpaper.catalog-changed")
private let macppWallpaperFramingChangedNotification = Notification.Name("org.macplusplus.macpp-wallpaper.framing-changed")

private enum WallpaperPaletteExtractor {
    private static func clamp(_ value: CGFloat, _ lower: CGFloat, _ upper: CGFloat) -> CGFloat {
        min(upper, max(lower, value))
    }

    private static func relativeLuminance(_ color: NSColor) -> CGFloat {
        let rgb = color.usingColorSpace(.sRGB) ?? .black
        func linear(_ value: CGFloat) -> CGFloat {
            let value = Double(value)
            return CGFloat(value <= 0.04045
                ? value / 12.92
                : Foundation.pow((value + 0.055) / 1.055, 2.4))
        }
        return 0.2126 * linear(rgb.redComponent)
            + 0.7152 * linear(rgb.greenComponent)
            + 0.0722 * linear(rgb.blueComponent)
    }

    private static func hueDistance(_ lhs: CGFloat, _ rhs: CGFloat) -> CGFloat {
        let distance = abs(lhs - rhs)
        return min(distance, 1 - distance)
    }

    private static func image(for url: URL) async -> NSImage? {
        let ext = url.pathExtension.lowercased()
        if macppWallpaperVideoExtensions.contains(ext) {
            let asset = AVURLAsset(url: url)
            let generator = AVAssetImageGenerator(asset: asset)
            generator.appliesPreferredTrackTransform = true
            generator.requestedTimeToleranceBefore = CMTime(seconds: 0.25, preferredTimescale: 600)
            generator.requestedTimeToleranceAfter = CMTime(seconds: 0.25, preferredTimescale: 600)
            // Only average colours are wanted from this frame, so there is no
            // reason to decode a 4K one. Downsampling first is both much faster
            // and slightly more robust, since it averages out sensor and
            // compression noise before the sampling below ever sees it.
            generator.maximumSize = CGSize(width: 512, height: 512)
            guard let image = try? await generator.image( // macpp:silent-ok an unavailable video frame leaves the colour sample empty
                at: CMTime(seconds: 0.5, preferredTimescale: 600)
            ).image else { return nil }
            return NSImage(cgImage: image, size: .zero)
        }
        return NSImage(contentsOf: url)
    }

    static func extractHexColors(from url: URL) async -> [String: String] {
        guard let image = await image(for: url),
              let data = image.tiffRepresentation,
              let bitmap = NSBitmapImageRep(data: data),
              bitmap.pixelsWide > 0, bitmap.pixelsHigh > 0 else { return [:] }

        struct Sample {
            let color: NSColor
            let luminance: CGFloat
            let saturation: CGFloat
            let brightness: CGFloat
            let hue: CGFloat?
        }
        let stride = max(1, min(bitmap.pixelsWide, bitmap.pixelsHigh) / 52)
        var samples: [Sample] = []
        for y in Swift.stride(from: stride / 2, to: bitmap.pixelsHigh, by: stride) {
            for x in Swift.stride(from: stride / 2, to: bitmap.pixelsWide, by: stride) {
                guard let raw = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.sRGB), raw.alphaComponent > 0.55 else { continue }
                let maximum = max(raw.redComponent, raw.greenComponent, raw.blueComponent)
                let minimum = min(raw.redComponent, raw.greenComponent, raw.blueComponent)
                let luminance = raw.redComponent * 0.2126 + raw.greenComponent * 0.7152 + raw.blueComponent * 0.0722
                var hue: CGFloat = 0
                var hsbSaturation: CGFloat = 0
                var brightness = maximum
                var alpha: CGFloat = 0
                raw.getHue(&hue, saturation: &hsbSaturation, brightness: &brightness, alpha: &alpha)
                samples.append(Sample(
                    color: raw,
                    luminance: luminance,
                    saturation: hsbSaturation > 0 ? hsbSaturation : maximum - minimum,
                    brightness: brightness,
                    hue: hsbSaturation > 0 ? hue : nil
                ))
            }
        }
        guard samples.count > 12 else { return [:] }
        let ordered = samples.sorted { $0.luminance < $1.luminance }
        func percentile(_ value: Double) -> NSColor {
            ordered[min(ordered.count - 1, max(0, Int(Double(ordered.count - 1) * value)))].color
        }
        let frameColor = percentile(0.15)
        let panelColor = percentile(0.055)
        let backgroundLuminance = relativeLuminance(frameColor) * 0.42
            + relativeLuminance(panelColor) * 0.58

        // Pick a hue cluster by population, not one maximally saturated
        // pixel. That keeps a broad crimson subject red when a small orange
        // highlight is also present in the frame.
        let hueBinCount = 36
        var hueWeights = Array(repeating: CGFloat(0), count: hueBinCount)
        for sample in samples {
            guard let hue = sample.hue, sample.saturation >= 0.18,
                  sample.brightness >= 0.10 else { continue }
            let midtone = 0.56 + 0.44 * (1 - min(1, abs(sample.brightness - 0.54) / 0.54))
            let chroma = CGFloat(Foundation.pow(Double(sample.saturation), 1.55))
            let redBias: CGFloat = (hue >= 0.96 || hue <= 0.045) ? 1.18 : 1.0
            let bin = min(hueBinCount - 1, max(0, Int(hue * CGFloat(hueBinCount))))
            hueWeights[bin] += chroma * midtone * redBias
        }

        let smoothedHueWeights = (0..<hueBinCount).map { index -> CGFloat in
            let previous = hueWeights[(index + hueBinCount - 1) % hueBinCount]
            let current = hueWeights[index]
            let next = hueWeights[(index + 1) % hueBinCount]
            return previous * 0.18 + current * 0.64 + next * 0.18
        }

        let accent: NSColor
        if let dominantBin = smoothedHueWeights.indices.max(by: {
            smoothedHueWeights[$0] < smoothedHueWeights[$1]
        }), smoothedHueWeights[dominantBin] > 0 {
            let dominantHue = (CGFloat(dominantBin) + 0.5) / CGFloat(hueBinCount)
            var hueX: CGFloat = 0
            var hueY: CGFloat = 0
            var totalWeight: CGFloat = 0
            var weightedSaturation: CGFloat = 0
            var weightedBrightness: CGFloat = 0

            for sample in samples {
                guard let hue = sample.hue,
                      hueDistance(hue, dominantHue) <= 2.25 / CGFloat(hueBinCount),
                      sample.saturation >= 0.18 else { continue }
                let midtone = 0.56 + 0.44 * (1 - min(1, abs(sample.brightness - 0.54) / 0.54))
                let chroma = CGFloat(Foundation.pow(Double(sample.saturation), 1.35))
                let redBias: CGFloat = (hue >= 0.96 || hue <= 0.045) ? 1.18 : 1.0
                let weight = chroma * midtone * redBias
                let angle = hue * 2 * .pi
                hueX += CGFloat(cos(Double(angle))) * weight
                hueY += CGFloat(sin(Double(angle))) * weight
                weightedSaturation += sample.saturation * weight
                weightedBrightness += sample.brightness * weight
                totalWeight += weight
            }

            if totalWeight > 0 {
                var normalizedHue = CGFloat(Foundation.atan2(Double(hueY), Double(hueX)) / (2 * .pi))
                if normalizedHue < 0 { normalizedHue += 1 }
                let saturation = clamp((weightedSaturation / totalWeight) * 1.12, 0.58, 0.96)
                let measuredBrightness = weightedBrightness / totalWeight
                let targetBrightness: CGFloat = backgroundLuminance > 0.58 ? 0.62 : 0.80
                let brightness = clamp(measuredBrightness * 0.72 + targetBrightness * 0.28, 0.56, 0.90)
                accent = NSColor(
                    calibratedHue: normalizedHue,
                    saturation: saturation,
                    brightness: brightness,
                    alpha: 1
                )
            } else {
                accent = percentile(0.72)
            }
        } else {
            accent = percentile(0.72)
        }

        // Choose text from contrast against the actual surfaces the shell
        // presents, rather than a weighted average that can hide a bright
        // frame inside a darker wallpaper sample.  The old average chose
        // white for a mid-light blue wallpaper: it looked fine over the dark
        // panel percentile, then disappeared against the frame and its
        // raised navigation tiles.  A foreground has to survive both ends.
        let darkText = NSColor(calibratedWhite: 0.10, alpha: 1)
        let lightText = NSColor(calibratedWhite: 0.96, alpha: 1)
        let sampledSurfaces = [frameColor, panelColor]
        func minimumContrast(_ foreground: NSColor) -> CGFloat {
            sampledSurfaces.map { background in
                let high = max(relativeLuminance(foreground), relativeLuminance(background))
                let low = min(relativeLuminance(foreground), relativeLuminance(background))
                return (high + 0.05) / (low + 0.05)
            }.min() ?? 0
        }
        let darkContrast = minimumContrast(darkText)
        let lightContrast = minimumContrast(lightText)
        let textColor = darkContrast >= lightContrast ? darkText : lightText
        return [
            PaletteRole.frame.rawValue: frameColor.macppHex,
            PaletteRole.panel.rawValue: panelColor.macppHex,
            PaletteRole.text.rawValue: textColor.macppHex,
            PaletteRole.accent.rawValue: accent.macppHex
        ]
    }
}

private struct ShellGeneratedWallpaperPalette: Codable {
    let path: String
    let sourceSize: Int64
    let sourceModified: TimeInterval
    let frame: String
    let panel: String
    let text: String
    let accent: String
}

private enum ShellGeneratedWallpaperPaletteStore {
    private static let root = URL(fileURLWithPath: NSHomeDirectory())
        .appendingPathComponent("Library/Application Support/MacPlusPlus", isDirectory: true)
    private static let legacyURL = root.appendingPathComponent("selected-wallpaper-palette.json")
    private static let cacheDirectory = root.appendingPathComponent("WallpaperPalettes", isDirectory: true)

    /// Use a filesystem-safe, deterministic key without adding a crypto
    /// dependency to the shell target.  The full source path is still stored
    /// in the value and its size/mtime are checked on load, so a collision can
    /// only cause a harmless cache miss.
    private static func cacheURL(for path: URL) -> URL {
        let encoded = Data(path.standardizedFileURL.path.utf8).base64EncodedString()
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "=", with: "")
        return cacheDirectory.appendingPathComponent(encoded).appendingPathExtension("json")
    }

    @discardableResult
    static func save(path: URL, colors: [String: String]) -> ShellGeneratedWallpaperPalette? {
        let standardized = path.standardizedFileURL
        guard let frame = colors["frame"], let panel = colors["panel"],
              let text = colors["text"], let accent = colors["accent"] else {
            MacPlusPlusBoundaryLog.record("generated wallpaper palette is missing a required colour role")
            return nil
        }
        do {
            let attributes = try FileManager.default.attributesOfItem(atPath: standardized.path)
            let value = ShellGeneratedWallpaperPalette(
                path: standardized.path,
                sourceSize: (attributes[.size] as? NSNumber)?.int64Value ?? 0,
                sourceModified: (attributes[.modificationDate] as? Date)?.timeIntervalSince1970 ?? 0,
                frame: frame, panel: panel, text: text, accent: accent
            )
            try FileManager.default.createDirectory(
                at: cacheDirectory, withIntermediateDirectories: true
            )
            let data = try JSONEncoder().encode(value)
            try data.write(to: cacheURL(for: standardized), options: .atomic)
            // Keep this compatibility file for older helpers, but it is only
            // the currently selected wallpaper.  The per-source cache above
            // is what prevents switching back to an older video from having
            // to sample it again.
            try data.write(to: legacyURL, options: .atomic)
            return value
        } catch {
            MacPlusPlusBoundaryLog.record(
                "generated wallpaper palette could not persist for \(standardized.path): \(error)"
            )
            return nil
        }
    }

    static func load(path: URL) -> ShellGeneratedWallpaperPalette? {
        let data = (try? Data(contentsOf: cacheURL(for: path))) // macpp:silent-ok a missing generated-palette cache falls through to the legacy cache
            ?? (try? Data(contentsOf: legacyURL)) // macpp:silent-ok a missing legacy cache is an expected first-run fallback
        guard let data,
              let value = try? JSONDecoder().decode(ShellGeneratedWallpaperPalette.self, from: data), // macpp:silent-ok malformed palette metadata is ignored in favor of live generation
              value.path == path.standardizedFileURL.path else { return nil }
        let attributes = try? FileManager.default.attributesOfItem(atPath: value.path) // macpp:silent-ok a disappeared wallpaper simply has no valid metadata
        let size = (attributes?[.size] as? NSNumber)?.int64Value ?? value.sourceSize
        let modified = (attributes?[.modificationDate] as? Date)?.timeIntervalSince1970 ?? value.sourceModified
        guard size == value.sourceSize, abs(modified - value.sourceModified) < 0.5 else { return nil }
        return value
    }

    static func remove(path: URL) {
        let standardized = path.standardizedFileURL
        do {
            let cache = cacheURL(for: standardized)
            if FileManager.default.fileExists(atPath: cache.path) {
                try FileManager.default.removeItem(at: cache)
            }
        } catch {
            MacPlusPlusBoundaryLog.record(
                "generated wallpaper palette cache cleanup failed for \(standardized.path): \(error)"
            )
        }
        // macpp:silent-ok a missing or malformed legacy palette is an expected migration fallback.
        guard let data = try? Data(contentsOf: legacyURL),
              // macpp:silent-ok a missing or malformed legacy palette is an expected migration fallback.
              let value = try? JSONDecoder().decode(ShellGeneratedWallpaperPalette.self, from: data),
              value.path == standardized.path else { return }
        do {
            if FileManager.default.fileExists(atPath: legacyURL.path) {
                try FileManager.default.removeItem(at: legacyURL)
            }
        } catch {
            MacPlusPlusBoundaryLog.record(
                "generated wallpaper palette legacy cleanup failed for \(standardized.path): \(error)"
            )
        }
    }

    static func clear() {
        // macpp:silent-ok A missing compatibility cache is the expected clean state.
        try? FileManager.default.removeItem(at: legacyURL)
    }
}



private func capturedCommand(
    _ executable: String,
    _ arguments: [String],
    timeout: TimeInterval = 3.0
) -> String {
    let result = runBoundedShellCommand(executable, arguments, timeout: timeout)
    return result.succeeded ? result.output : ""
}

private enum PowerCommand: String {
    case lock, softOverlay, logout, sleep, displayOff, shutdown, restart, screensaver
}

private enum PaletteRole: String, CaseIterable, Identifiable {
    case frame, panel, text, accent
    var id: String { rawValue }
}

private struct PaletteTokens {
    let frame: Color
    let panel: Color
    let text: Color
    let accent: Color

    var isLight: Bool {
        let color = NSColor(frame).usingColorSpace(.sRGB) ?? .black
        return color.redComponent * 0.2126 + color.greenComponent * 0.7152 + color.blueComponent * 0.0722 > 0.68
    }

    var seam: Color {
        let frameColor = NSColor(frame).usingColorSpace(.sRGB) ?? .black
        let accentColor = NSColor(accent).usingColorSpace(.sRGB) ?? .white
        let amount: CGFloat = 0.28
        return Color(nsColor: NSColor(
            srgbRed: frameColor.redComponent * (1 - amount) + accentColor.redComponent * amount,
            green: frameColor.greenComponent * (1 - amount) + accentColor.greenComponent * amount,
            blue: frameColor.blueComponent * (1 - amount) + accentColor.blueComponent * amount,
            alpha: 1
        ))
    }
}

private func defaultPaletteHex(_ role: PaletteRole) -> String {
    let preset = MacPlusPlusPaletteCatalog.defaultPreset
    switch role {
    case .frame: return preset.frame
    case .panel: return preset.panel
    case .text: return preset.text
    case .accent: return preset.accent
    }
}

private extension NSColor {
    convenience init?(macppHex: String) {
        let raw = macppHex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        guard raw.count == 6, let value = UInt64(raw, radix: 16) else { return nil }
        self.init(
            srgbRed: CGFloat((value >> 16) & 0xff) / 255,
            green: CGFloat((value >> 8) & 0xff) / 255,
            blue: CGFloat(value & 0xff) / 255,
            alpha: 1
        )
    }

    var macppHex: String {
        guard let rgb = usingColorSpace(.sRGB) else { return "FFFFFF" }
        return String(
            format: "%02X%02X%02X",
            Int((rgb.redComponent * 255).rounded()),
            Int((rgb.greenComponent * 255).rounded()),
            Int((rgb.blueComponent * 255).rounded())
        )
    }
}

private enum ShellPalette: String, CaseIterable, Identifiable {
    case midnight, darkSky, graphite, frost, ember, violet, obsidian, white, custom

    /// The only built-in profiles shown as dedicated palette choices.  The
    /// older names remain valid in the state files and mode scripts so an
    /// existing installation can be opened safely, but they are treated as
    /// wallpaper-backed extras rather than a second palette system.
    static let dedicatedPalettes: [ShellPalette] = MacPlusPlusPaletteCatalog.dedicatedNames
        .compactMap(ShellPalette.init(rawValue:))

    var id: String { rawValue }
    var shortTitle: String { String(title.prefix(3)) }
    var title: String {
        switch self {
        case .midnight: "MIDNIGHT"
        case .darkSky: "DARK SKY"
        case .graphite: "GRAPHITE"
        case .frost: "FROST"
        case .ember: "EMBER"
        case .violet: "VIOLET"
        case .obsidian: "OBSIDIAN"
        case .white: "WHITE"
        case .custom: "CUSTOM"
        }
    }
    var tokens: PaletteTokens {
        if self == .custom {
            let defaults = UserDefaults.standard
            func color(_ role: PaletteRole, fallback: String) -> Color {
                Color(nsColor: NSColor(macppHex: defaults.string(forKey: "shellCustom.\(role.rawValue)") ?? fallback) ?? .white)
            }
            return PaletteTokens(
                frame: color(.frame, fallback: defaultPaletteHex(.frame)),
                panel: color(.panel, fallback: defaultPaletteHex(.panel)),
                text: color(.text, fallback: defaultPaletteHex(.text)),
                accent: color(.accent, fallback: defaultPaletteHex(.accent))
            )
        }
        let preset = MacPlusPlusPaletteCatalog.preset(named: rawValue)
            ?? MacPlusPlusPaletteCatalog.defaultPreset
        return PaletteTokens(
            frame: Color(nsColor: NSColor(macppHex: preset.frame) ?? .black),
            panel: Color(nsColor: NSColor(macppHex: preset.panel) ?? .black),
            text: Color(nsColor: NSColor(macppHex: preset.text) ?? .white),
            accent: Color(nsColor: NSColor(macppHex: preset.accent) ?? .systemBlue)
        )
    }
    var swatch: Color { tokens.accent }
    static var current: ShellPalette {
        ShellPalette(rawValue: UserDefaults.standard.string(forKey: "shellPalette") ?? "") ?? .midnight
    }
}

private enum MacPlusPlusNonworkWallpaperMode: String {
    case game
    case performance
}

private enum MacPlusPlusNonworkWallpaperTarget: String, CaseIterable, Identifiable, Equatable {
    case game
    case performance
    case both

    var id: String { rawValue }
    var label: String {
        switch self {
        case .game: "GAME"
        case .performance: "PERF"
        case .both: "BOTH"
        }
    }

    var title: String {
        switch self {
        case .game: "Game"
        case .performance: "Performance"
        case .both: "Both"
        }
    }

    var modes: [MacPlusPlusNonworkWallpaperMode] {
        switch self {
        case .game: [.game]
        case .performance: [.performance]
        case .both: [.game, .performance]
        }
    }
}

private enum Theme {
    private static var tokens: PaletteTokens { ShellPalette.current.tokens }
    private static func solidMix(_ base: Color, _ overlay: Color, amount: CGFloat) -> Color {
        let baseColor = NSColor(base).usingColorSpace(.sRGB) ?? .black
        let overlayColor = NSColor(overlay).usingColorSpace(.sRGB) ?? .black
        let t = max(0, min(1, amount))
        return Color(nsColor: NSColor(
            srgbRed: baseColor.redComponent * (1 - t) + overlayColor.redComponent * t,
            green: baseColor.greenComponent * (1 - t) + overlayColor.greenComponent * t,
            blue: baseColor.blueComponent * (1 - t) + overlayColor.blueComponent * t,
            alpha: 1
        ))
    }
    // RGB-ratio blending (solidMix) mixes a fixed fraction of accent into
    // frame -- that fraction has to be hand-tuned per use, and because
    // accents differ wildly in their own brightness/saturation (Graphite's
    // AEB7C8 is nearly desaturated by design, Ember's FF927C is vivid), one
    // fixed ratio looks great on the palette it was tuned against and
    // washed-out or too strong on the rest. accentTintedFrame instead reads
    // the accent's actual hue+saturation and simply lifts/drops brightness
    // relative to frame's own brightness -- so every palette keeps its own
    // real colour identity (Graphite/Obsidian stay subtly neutral, since
    // that's genuinely how desaturated their accents are) while still
    // guaranteeing the same visible lightness step against the rail
    // background on every palette, since that step is computed from frame's
    // own brightness rather than assumed from a flat RGB percentage.
    // saturationScale lets a caller dial back how much of the accent's own
    // saturation actually reaches the result. White's accent (7899C8) isn't
    // desaturated the way Graphite/Obsidian's accents genuinely are -- it
    // carries a real, moderate blue saturation -- so at full strength White's
    // pills/sliders read as distinctly "blue" rather than the muted, papery
    // "dirty grey" the rest of White's chrome uses. Dark palettes want their
    // full accent hue (that's the whole point of this formula existing), but
    // White wants only a whisper of it -- hence the two call sites below pass
    // a much lower scale specifically for the isLight branch.
    private static func accentTintedFrame(brightnessDelta: CGFloat, saturationScale: CGFloat = 1) -> Color {
        let frameColor = NSColor(tokens.frame).usingColorSpace(.sRGB) ?? .black
        let accentColor = NSColor(tokens.accent).usingColorSpace(.sRGB) ?? .black
        var h: CGFloat = 0, s: CGFloat = 0, ab: CGFloat = 0, aa: CGFloat = 0
        accentColor.getHue(&h, saturation: &s, brightness: &ab, alpha: &aa)
        var fh: CGFloat = 0, fs: CGFloat = 0, fb: CGFloat = 0, fa: CGFloat = 0
        frameColor.getHue(&fh, saturation: &fs, brightness: &fb, alpha: &fa)
        let brightness = min(1, max(0, fb + brightnessDelta))
        let saturation = max(0, min(1, s * saturationScale))
        return Color(nsColor: NSColor(hue: h, saturation: saturation, brightness: brightness, alpha: 1))
    }
    // WCAG relative luminance. Lives beside the colours it constrains rather
    // than only inside `tests/test-palette-contrast`, so the shipping tokens and
    // the validator that guards them are computed from the same expression.
    private static func relativeLuminance(_ color: NSColor) -> CGFloat {
        // `NSColor(Color(...))` can retain a calibrated or tagged AppKit
        // representation even when the caller already asked for sRGB. Read
        // the converted value here too; calling redComponent on the wrapper
        // itself raises an AppKit exception for some wallpaper-derived colors.
        let rgb = color.usingColorSpace(.sRGB) ?? .black
        func channel(_ value: CGFloat) -> CGFloat {
            value <= 0.03928 ? value / 12.92 : pow((value + 0.055) / 1.055, 2.4)
        }
        return 0.2126 * channel(rgb.redComponent)
            + 0.7152 * channel(rgb.greenComponent)
            + 0.0722 * channel(rgb.blueComponent)
    }
    private static func contrastRatio(_ first: NSColor, _ second: NSColor) -> CGFloat {
        let firstLuminance = relativeLuminance(first)
        let secondLuminance = relativeLuminance(second)
        let high = max(firstLuminance, secondLuminance)
        let low = min(firstLuminance, secondLuminance)
        return (high + 0.05) / (low + 0.05)
    }
    private static func worstContrast(
        _ foreground: NSColor,
        against backgrounds: [NSColor]
    ) -> CGFloat {
        backgrounds.map { contrastRatio(foreground, $0) }.min() ?? 0
    }
    /// Pick a foreground that survives every surface in a shared component.
    /// Wallpaper-derived tokens are intentionally expressive, so a generated
    /// text colour is only a preference: when it falls below the relevant
    /// floor, use the higher-contrast black/white role instead of letting a
    /// light accent and a light text token disappear into one another.
    static func readableForeground(
        over backgrounds: [Color],
        preferred: Color? = nil,
        minimumContrast: CGFloat = 3.0
    ) -> Color {
        let resolvedBackgrounds = backgrounds.compactMap {
            NSColor($0).usingColorSpace(.sRGB)
        }
        guard !resolvedBackgrounds.isEmpty else { return preferred ?? .white }

        if let preferred,
           let resolvedPreferred = NSColor(preferred).usingColorSpace(.sRGB),
           worstContrast(resolvedPreferred, against: resolvedBackgrounds) >= minimumContrast {
            return preferred
        }

        let candidates: [NSColor] = [.black, .white]
        let readable = candidates.max {
            worstContrast($0, against: resolvedBackgrounds)
                < worstContrast($1, against: resolvedBackgrounds)
        } ?? .white
        return Color(nsColor: readable)
    }
    /// Preserve a wallpaper accent's hue while moving its brightness only as
    /// far as needed for a 3:1 non-text affordance floor.  This is deliberately
    /// sampled in HSB instead of using the light/dark palette classification:
    /// a generated wallpaper can be visually light without being near-white.
    private static func accentWithContrast(
        over backgrounds: [Color],
        minimumContrast: CGFloat
    ) -> Color {
        let source = NSColor(tokens.accent).usingColorSpace(.sRGB) ?? .systemBlue
        let resolvedBackgrounds = backgrounds.compactMap {
            NSColor($0).usingColorSpace(.sRGB)
        }
        guard !resolvedBackgrounds.isEmpty else { return tokens.accent }
        let sourceContrast = worstContrast(source, against: resolvedBackgrounds)
        guard sourceContrast < minimumContrast else { return tokens.accent }

        var hue: CGFloat = 0
        var saturation: CGFloat = 0
        var brightness: CGFloat = 0
        var alpha: CGFloat = 0
        source.getHue(&hue, saturation: &saturation, brightness: &brightness, alpha: &alpha)

        var best = source
        var bestContrast = sourceContrast
        var closestDistance = CGFloat.greatestFiniteMagnitude
        let sampleCount = 96
        for index in 0...sampleCount {
            let candidateBrightness = CGFloat(index) / CGFloat(sampleCount)
            let candidate = NSColor(
                hue: hue,
                saturation: saturation,
                brightness: candidateBrightness,
                alpha: 1
            )
            let candidateContrast = worstContrast(candidate, against: resolvedBackgrounds)
            if candidateContrast > bestContrast {
                best = candidate
                bestContrast = candidateContrast
            }
            guard candidateContrast >= minimumContrast else { continue }
            let distance = abs(candidateBrightness - brightness)
            if distance < closestDistance {
                best = candidate
                closestDistance = distance
            }
        }
        return Color(nsColor: best)
    }
    // Structural colour has three levels only: the shell, an ordinary card, and
    // an elevated card nested on top of something else. The previous pass made
    // `group`, `card`, and `tile` three separate shades, but many of their call
    // sites are sibling cards. That made Wi-Fi, Battery, and other popouts look
    // like a stack of unrelated panels instead of one coherent surface system.
    //
    // Solve the two card surfaces against the shell itself rather than blending
    // inside the palette's panel/frame gap. Contrast ratio carries a +0.05 term,
    // so a fixed brightness delta buys very different separation on near-black
    // and lighter palettes. Bisection gives every palette the same measured
    // step while preserving the frame's hue and saturation.
    //
    // Hue and saturation come from the base surface, not the accent. Elevation is
    // structure, so a raised card should read as more of the surface it sits on.
    // `layerSelected` is the one exception: it keeps the accent hue because it
    // represents state rather than a fourth structural depth.
    private static func contrastStepped(
        from base: Color, ratio: CGFloat, hueSource: Color? = nil, saturationScale: CGFloat = 1
    ) -> Color {
        let baseColor = NSColor(base).usingColorSpace(.sRGB) ?? .black
        let colorSource = NSColor(hueSource ?? base).usingColorSpace(.sRGB) ?? .black
        var h: CGFloat = 0, s: CGFloat = 0, v: CGFloat = 0, a: CGFloat = 0
        colorSource.getHue(&h, saturation: &s, brightness: &v, alpha: &a)
        let saturation = max(0, min(1, s * saturationScale))
        let baseLuminance = relativeLuminance(baseColor)
        // Dark palettes step up from their base; light palettes have no
        // headroom above theirs, so they step down.
        let target = isLight
            ? (baseLuminance + 0.05) / ratio - 0.05
            : (baseLuminance + 0.05) * ratio - 0.05
        func shade(_ brightness: CGFloat) -> NSColor {
            NSColor(hue: h, saturation: saturation, brightness: brightness, alpha: 1)
        }
        guard target > 0 else { return Color(nsColor: shade(0)) }
        var low: CGFloat = 0
        var high: CGFloat = 1
        // 18 halvings resolve brightness far finer than the 8-bit channel the
        // result lands in. This runs inside a SwiftUI body, so it stays bounded
        // rather than iterating to an epsilon.
        for _ in 0..<18 {
            let mid = (low + high) / 2
            let candidate = shade(mid).usingColorSpace(.sRGB) ?? .black
            if relativeLuminance(candidate) < target { low = mid } else { high = mid }
        }
        return Color(nsColor: shade((low + high) / 2))
    }
    // The contrast each card tier is guaranteed to hold against `frame`, rather
    // than the mix fraction it used to be handed. Ordinary cards target 1.21:1
    // and elevated cards target 1.331:1, leaving one clear 1.10:1 step between
    // them. `selected` sits at 1.53:1 because it is a semantic state, not a
    // structural depth.
    private enum Elevation {
        static let card: CGFloat = 1.21
        static let tile: CGFloat = 1.331
        static let selected: CGFloat = 1.53
        // Keep structural surfaces close to the shell's own colour identity.
        static let saturationScale: CGFloat = 0.85
    }
    // Dark-palette lift and light-palette (White) drop used to live inline
    // as a single `isLight ? lightValue : darkValue` ternary at each call
    // site. That reads fine, but it means a request about one mode ("make
    // Midnight darker") and a request about the other ("White is too dark
    // now") both land on the same expression, so a fix aimed at one branch
    // is one edit away from nudging the other by accident -- which is
    // exactly what happened to White here. Pulling each mode's numbers out
    // into their own named, separately-commented constant makes the two
    // tuning passes genuinely independent: a White-only complaint only ever
    // touches the `light...` constants below, a dark-palette-only complaint
    // only ever touches the `dark...` ones.
    private enum PillTuning {
        // How far *above* frame's own HSB brightness each dark-palette
        // element sits. Small on purpose -- dark palettes (Midnight
        // especially) read as too bright even at moderate lifts, since the
        // frame token there is already near-black and any fixed lift is a
        // large jump in relative terms.
        // 0.10 rather than 0.06. At 0.06 the pill cleared `frame` by only
        // 1.11:1 on Midnight and 1.12:1 on Game -- the two palettes whose frame
        // token is darkest, and so the two where a fixed brightness delta buys
        // the least contrast. 0.10 brings both to 1.20:1 and lands the rest of
        // the dark set at 1.34-1.58:1, alongside White's existing 1.58:1.
        static let darkRailPillLift: CGFloat = 0.10
        static let darkSliderTrackLift: CGFloat = 0.08
        static let darkSliderHeadLift: CGFloat = 0.20
        // How far *below* frame's own HSB brightness each light-palette
        // (White) element sits. Kept modest -- White's frame token is
        // already near-white, so even a small drop reads as a clear, legible
        // step without crossing into looking like a dark-mode element stuck
        // in the light theme.
        static let lightRailPillDrop: CGFloat = 0.12
        static let lightSliderTrackDrop: CGFloat = 0.07
        static let lightSliderHeadDrop: CGFloat = 0.20
        // White's own accent (7899C8) is a real, moderately saturated blue --
        // unlike Graphite/Obsidian, whose accents are near-neutral on their
        // own. Passed straight through at saturationScale 1, White's pills
        // and sliders read as distinctly blue instead of the muted, papery
        // "dirty grey" the rest of White's surfaces use. This scale keeps
        // just enough of the hue to feel intentional without it reading as
        // a colour swatch.
        static let lightSaturationScale: CGFloat = 0.35
    }
    // A custom wallpaper can produce an accent that is beautiful beside the
    // image but too close to the generated frame for tiny symbols, strokes,
    // and compact buttons. Built-in palettes keep their authored accent; the
    // custom role is nudged along its own hue until it clears the UI floor.
    static var accent: Color {
        guard ShellPalette.current == .custom else { return tokens.accent }
        return accentWithContrast(
            over: [shellSurface, cardSurface],
            minimumContrast: 3.0
        )
    }
    // Caelestia's own active-workspace indicator is a solid, fully opaque
    // accent capsule with the digit itself recoloured to sit on top of it
    // (a Colouriser swap to m3onPrimary), not a translucent tint behind
    // text that's just gotten brighter. onAccent picks a legible black or
    // white for that digit based on the accent's own luminance, so it works
    // whether the palette's accent is a light icy blue or a deep violet.
    static var onAccent: Color {
        let c = NSColor(accent).usingColorSpace(.sRGB) ?? .black
        let luminance = relativeLuminance(c)
        // Choose the actual higher-contrast foreground instead of using an
        // encoded-RGB threshold. That threshold picked white for Game even
        // though black is 6.03:1 against its red accent and white is only
        // 3.48:1; the WCAG luminance comparison also remains correct for
        // generated wallpaper accents that do not resemble a preset.
        let darkContrast = (luminance + 0.05) / 0.05
        let lightContrast = 1.05 / (luminance + 0.05)
        return darkContrast >= lightContrast ? .black : .white
    }
    // A single stored `text` token cannot know that Nexus places the same copy
    // over the shell, a raised card, and a selected navigation surface. Keep
    // the palette token when it clears all three; otherwise use the stronger
    // black/white role with the best worst-case contrast. This is what keeps a
    // mid-light wallpaper from producing white-on-blue symbols and labels.
    static var bright: Color {
        readableForeground(
            over: [shellSurface, nexusCardSurface, layerSelected],
            preferred: tokens.text,
            minimumContrast: 4.5
        )
    }
    // Secondary copy keeps the same resolved foreground so it cannot switch
    // back to the low-contrast wallpaper token just because it is muted.
    static var muted: Color { bright.opacity(0.72) }
    // The "live / active / now-playing" indicator colour: status dots, the
    // audio visualiser's accent bars, NOW PLAYING labels, the quick-control
    // pip. This was simply `tokens.text`, which reads correctly on the dark
    // palettes (where text is near-white, so an indicator built from it looks
    // genuinely lit) but inverts on White, where text is a near-black blue
    // and every one of those indicators rendered as a dark navy dot -- the
    // exact opposite of "illuminated", and the single biggest source of stray
    // dark blue on the White palette. On light palettes it now derives from
    // the accent, deepened just enough to hold contrast against the near-white
    // frame without ever approaching navy-black.
    // 0.16 deepens the accent just enough to clear the near-white frame
    // (contrast 3.4, comfortably above the 3.0 floor for a non-text UI
    // element) while staying a clearly mid-tone denim rather than sliding
    // toward the dark navy this pass exists to eliminate.
    static var mint: Color {
        isLight ? solidMix(tokens.accent, tokens.text, amount: 0.16) : tokens.text
    }
    // "Ice" is the illuminated/active UI color, not a text color. On dark
    // palettes the bright copy provides that highlight; on White it must use
    // the blue accent or active arcs/buttons acquire stray black segments.
    // `ice` is an affordance colour -- active arcs, live buttons, the enabled
    // state of a toggle -- so on a light palette it has to clear the 3.0:1 WCAG
    // floor for non-text UI, exactly as `mint` above already does. Returning the
    // raw accent on White measured 2.63:1 against White's frame and failed it.
    //
    // Deepened by 0.10 rather than `mint`'s 0.16: that reaches 3.08:1, which
    // clears the floor while staying visibly lighter and bluer than `mint`'s
    // 3.40:1. The two tokens sit side by side (the Nexus gauges use `mint` for
    // GPU and `ice` for MEM), so collapsing them onto one deepening would have
    // fixed the contrast by deleting the distinction.
    static var ice: Color {
        isLight ? solidMix(tokens.accent, tokens.text, amount: 0.10) : tokens.text
    }
    static var surface: Color { tokens.panel }
    // Caelestia's sidebar has two adjacent surfaces: the BlobRect backing
    // (`m3surface`) and the nested notification `StyledRect`
    // (`m3surfaceContainerLow`). Keep that small elevation step here instead
    // of reusing the much stronger ordinary-card colour, so the inner rounded
    // card remains visible without turning the whole drawer blue.
    static var surfaceContainerLow: Color {
        contrastStepped(
            from: surface,
            ratio: 1.14,
            hueSource: surface,
            saturationScale: Elevation.saturationScale
        )
    }
    static var shellSurface: Color { tokens.frame }
    static var cardSurface: Color {
        contrastStepped(from: shellSurface, ratio: Elevation.card, saturationScale: Elevation.saturationScale)
    }
    static var elevatedSurface: Color {
        contrastStepped(from: shellSurface, ratio: Elevation.tile, saturationScale: Elevation.saturationScale)
    }
    // Legacy names remain available to the existing call sites, but they now
    // describe the same intentional hierarchy: shell, card, elevated card.
    static var surfaceRaised: Color { elevatedSurface }
    static var tile: Color { elevatedSurface }
    static var frame: Color { shellSurface }
    // `group` and `card` are sibling-card spellings kept for source stability;
    // both render the one ordinary card surface. `tile` is reserved for a
    // genuinely nested/elevated surface.
    static var layerGroup: Color { cardSurface }
    static var layerCard: Color { cardSurface }
    // railPill used to mix frame toward text/bright, which are both
    // low-saturation structural tokens on almost every palette, so the
    // blend converged on the same neutral grey regardless of palette. It
    // now reads the accent's real hue+saturation and lifts brightness
    // relative to frame, so Ember genuinely reads warm, Frost cool, Violet
    // purple, Midnight blue -- and Graphite/Obsidian, whose accents really
    // are near-neutral by design, correctly stay subtle rather than being
    // forced into a false colour.
    static var railPill: Color {
        accentTintedFrame(
            brightnessDelta: isLight ? -PillTuning.lightRailPillDrop : PillTuning.darkRailPillLift,
            saturationScale: isLight ? PillTuning.lightSaturationScale : 1
        )
    }
    static var layerTile: Color { elevatedSurface }
    // The volume/brightness edge slider used Theme.muted.opacity(0.14) for
    // its track and Theme.tile (the elevated surface) for its head. Both lean on the
    // assumption that "muted"/"frame" already sit lighter than whatever's
    // behind them -- true on dark palettes, but on White the frame token IS
    // nearly white already, so the head became a white pill on a white
    // background, and the track's faint dark tint at 14% opacity all but
    // disappeared over light wallpaper. Track and head now both derive from
    // the same accent-hue/frame-brightness formula as railPill, at
    // progressively larger brightness steps so the head still reads as the
    // brightest, most "grabbable" element of the three on every palette.
    static var sliderTrack: Color {
        accentTintedFrame(
            brightnessDelta: isLight ? -PillTuning.lightSliderTrackDrop : PillTuning.darkSliderTrackLift,
            saturationScale: isLight ? PillTuning.lightSaturationScale : 1
        )
    }
    // The head used to be a third fixed brightness delta from `frame`, tuned so
    // that it cleared `frame` -- but nothing in that arrangement constrained it
    // against the *track*, which is the shape it actually sits on. It measured
    // 1.28:1 over its own track on Midnight and 1.37:1 on White, so the comment
    // above ("the brightest, most grabbable element of the three") described an
    // intent the numbers did not carry: at 1.3 the two shapes read as one.
    //
    // Solve it against the track instead. The head inherits the track's hue and
    // saturation -- it is the same material, lit -- and only its brightness is
    // resolved, to a fixed 1.90:1 over whatever the track came out as on this
    // palette. A single delta cannot do this: the deltas the nine palettes need
    // to reach 1.90 span 0.26 to 0.38.
    static var sliderHead: Color {
        contrastStepped(from: sliderTrack, ratio: SliderTuning.headOverTrack)
    }
    private enum SliderTuning {
        // Far enough apart that the head is unambiguously a separate object at
        // a glance, while staying inside the track's own hue so the control
        // still reads as one component rather than a dot parked on a bar.
        static let headOverTrack: CGFloat = 1.90
        // A generated wallpaper palette can carry a very saturated accent from
        // one vivid image. The edge controls should inherit that hue without
        // becoming a neon strip against the wallpaper itself.
        static let wallpaperSaturationScale: CGFloat = 0.62
        // Keep the active edge fill visibly lighter than its track without
        // turning a wallpaper-derived accent into a white strip.
        static let wallpaperFillLift: CGFloat = 0.07
        // Light palettes have no room to lift a fill above the frame. Blend
        // the high end back toward that frame instead, so the high-value end
        // is still visibly lighter than the low end while retaining the
        // palette's hue rather than switching to plain white.
        static let lightFillFrameMix: CGFloat = 0.70
    }
    // Wallpaper-derived accents can be much more saturated than the authored
    // palettes. Keep the edge control in the same material family, but soften
    // only this narrow control rather than changing every progress bar and
    // toggle that uses the shared slider tokens.
    static var edgeSliderTrack: Color {
        guard ShellPalette.current == .custom else { return sliderTrack }
        return accentTintedFrame(
            brightnessDelta: isLight ? -PillTuning.lightSliderTrackDrop : PillTuning.darkSliderTrackLift,
            saturationScale: isLight ? PillTuning.lightSaturationScale : SliderTuning.wallpaperSaturationScale
        )
    }
    static var edgeSliderHead: Color {
        guard ShellPalette.current == .custom else { return sliderHead }
        return contrastStepped(from: edgeSliderTrack, ratio: SliderTuning.headOverTrack)
    }
    static var edgeSliderFillColors: [Color] {
        // The edge control grows upward from the bottom, so the gradient's
        // first stop is always the high-value/light end and its second stop is
        // the low-value/darker end. The view below keeps these stops anchored
        // to the full track instead of remapping them to the current fill.
        [edgeSliderFillHigh, edgeSliderFillLow]
    }
    static var edgeSliderFillHigh: Color {
        guard ShellPalette.current == .custom else { return levelHigh }
        guard isLight else { return edgeSliderHead }
        return solidMix(edgeSliderFillLow, shellSurface, amount: SliderTuning.lightFillFrameMix)
    }
    static var edgeSliderFillLow: Color {
        guard ShellPalette.current == .custom else { return levelLow }
        return accentTintedFrame(
            brightnessDelta: isLight
                ? -(PillTuning.lightSliderTrackDrop * 0.55)
                : PillTuning.darkSliderTrackLift + SliderTuning.wallpaperFillLift,
            saturationScale: isLight
                ? PillTuning.lightSaturationScale
                : SliderTuning.wallpaperSaturationScale
        )
    }
    // Selection is the one elevation tier that keeps the accent's hue: it marks
    // a state rather than a depth, so it should read as "chosen", not merely as
    // "higher". It still takes a guaranteed brightness step past `layerTile`,
    // because Graphite's and Obsidian's accents are deliberately near-neutral
    // and a hue-only difference would vanish on exactly those two palettes.
    static var layerSelected: Color {
        contrastStepped(
            from: shellSurface,
            ratio: Elevation.selected,
            hueSource: tokens.accent,
            // White's accent is a genuinely saturated blue, unlike Graphite's
            // and Obsidian's; the same scale the pills use keeps a selected row
            // on White papery rather than turning it into a colour swatch.
            saturationScale: isLight ? PillTuning.lightSaturationScale : 1
        )
    }
    // Nexus navigation rows use a light/dark surface derived from the shell,
    // not a fixed black/white theme. Resolve the semi-opaque row against the
    // shell and make the icon role independently readable on the raised
    // selection tile. Small symbols get a 3:1 floor; text above uses `bright`.
    static var nexusCardSurface: Color {
        solidMix(shellSurface, cardSurface, amount: 0.54)
    }
    static var nexusIconForeground: Color {
        readableForeground(
            over: [layerSelected],
            preferred: bright,
            minimumContrast: 3.0
        )
    }
    // `edge` is structural -- hairline separators and one card stroke, always
    // further faded by a 0.16-0.55 opacity at the call site. It is decoration
    // rather than an affordance, so unlike `ice` above it is deliberately *not*
    // held to 3.0:1, and the eight dark palettes keep their hand-tuned strength
    // unchanged.
    //
    // White is still wrong, though, and for a reason worth naming: at 1.76:1 it
    // was an opacity wash of a colour that already failed at full strength, so
    // the separators there were faint for the same underlying reason the buttons
    // were. It now uses the same deepened accent `ice` does, at full opacity, so
    // the call-site fades start from a colour with real density instead of
    // spending their whole budget getting to visible.
    static var edge: Color {
        isLight ? solidMix(tokens.accent, tokens.text, amount: 0.10) : tokens.accent.opacity(0.62)
    }
    static var isLight: Bool { tokens.isLight }
    // White is already separated by its opaque surfaces and blue contour.
    // Any drop shadow on that palette reads as dirty grey banding—especially
    // around the circular performance cards—so only dark palettes use depth.
    static var shadow: Color { isLight ? .clear : Color.black.opacity(0.18) }
    // Higher physical levels must always read as brighter. White uses dark
    // copy, so text cannot also be the high end of the brightness gradient.
    static var levelHigh: Color {
        // `levelLow` is the accent on built-in palettes. On a light palette
        // the old high stop mixed toward dark copy, which made higher physical
        // levels darker than lower ones. Blend it toward the light frame so
        // the visual ramp and the control's numeric direction agree.
        isLight
            ? solidMix(tokens.accent, tokens.frame, amount: SliderTuning.lightFillFrameMix)
            : tokens.text
    }
    static var levelLow: Color { tokens.accent }
    // Pre-compose the seam against the frame into one opaque colour. A
    // translucent stroke changes tint where curve antialiasing overlaps the
    // wallpaper instead of the frame, which reads as a subtle colour mismatch
    // even when both adjoining surfaces use the same fill.
    static var seam: Color { tokens.seam }
}

// One shared material opacity keeps the monitor frame, rail, launcher, Nexus,
// and attached popouts visually continuous while allowing the wallpaper to
// remain visible underneath. Geometry and motion stay entirely independent.
private let shellMaterialOpacity: Double = 1.0

// Every physical monitor-frame and attachment contour uses this single token.
// Card borders inside a panel remain intentionally subtler; they are not part
// of the shell silhouette and therefore do not participate in seam joining.
private enum ShellContourStyle {
    // Trial: use the same two-point contour on the resting rim and every
    // animated popout so the shared shell language is easy to compare at
    // native zoom. Butt caps still keep open reverse-curve endpoints from
    // growing beyond this width.
    static let width: CGFloat = 2
    // Preserve the proven contour geometry, but let the shell read as one
    // continuous material instead of an outlined collection of windows.
    static var color: Color { .clear }
    static var stroke: StrokeStyle {
        StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round)
    }
}

// MacPlusPlusCast is compiled both as a standalone non-work-mode app and as part of the
// Work Mode shell. The embedded build must use the shell's live palette—not a
// second hard-coded approximation—or its bottom join becomes visible.
func embeddedShellFrameColor() -> Color { Theme.frame.opacity(shellMaterialOpacity) }
func embeddedShellSeamColor() -> Color { .clear }
func embeddedShellSeamWidth() -> CGFloat { ShellContourStyle.width }
func embeddedShellTextColor() -> Color { Theme.bright }
func embeddedShellMutedTextColor() -> Color { Theme.muted }
func embeddedShellAccentColor() -> Color { Theme.accent }
func embeddedShellPanelColor() -> Color { Theme.surface.opacity(shellMaterialOpacity) }
func embeddedShellTileColor() -> Color { Theme.tile.opacity(shellMaterialOpacity) }


private struct Glass: ViewModifier {
    var radius: CGFloat = Rounding.large
    func body(content: Content) -> some View {
        content
            .background(Theme.surface.opacity(shellMaterialOpacity))
            .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
            .shadow(color: Theme.shadow, radius: Theme.isLight ? 8 : 14, y: Theme.isLight ? 2 : 6)
    }
}

private struct LayeredPanel: ViewModifier {
    var radius: CGFloat = 16
    @AppStorage("shellPalette") private var paletteRaw = ShellPalette.midnight.rawValue

    func body(content: Content) -> some View {
        let tokens = (ShellPalette(rawValue: paletteRaw) ?? .midnight).tokens
        let shape = RoundedRectangle(cornerRadius: radius, style: .continuous)
        content
            .background {
            // This modifier is used for authored cards (Dashboard, Media,
            // lyrics, and gauges), not for the outer shell. Give every one of
            // those cards the same opaque fill. The old panel opacity and
            // accent/text gradient made identical cards change shade with the
            // wallpaper underneath and with an arbitrary `strength` argument.
            shape
                .fill(Theme.cardSurface)
                .overlay {
                    shape
                        .stroke(tokens.seam.opacity(tokens.isLight ? 0.24 : 0.20), lineWidth: 0.65)
                        .padding(0.4)
                }
            }
            // A background shape does not clip the view it is attached to.
            // Clip the authored content as well so a nested Color, image, or
            // platform view cannot paint square corners over the shared card.
            .clipShape(shape)
    }
}

private extension View {
    func layeredPanel(radius: CGFloat = 16) -> some View {
        modifier(LayeredPanel(radius: radius))
    }
}

private extension View { func glass(_ radius: CGFloat = Rounding.large) -> some View { modifier(Glass(radius: radius)) } }

private struct MicroButtonStyle: ButtonStyle {
    @Environment(\.isEnabled) private var isEnabled

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .scaleEffect(isEnabled && configuration.isPressed ? 0.96 : 1)
            .brightness(isEnabled && configuration.isPressed ? 0.06 : 0)
            .saturation(isEnabled ? 1 : 0.35)
            .opacity(isEnabled ? (configuration.isPressed ? 0.86 : 1) : 0.55)
            .background(
                Theme.bright.opacity(isEnabled && configuration.isPressed ? 0.10 : 0),
                in: RoundedRectangle(cornerRadius: Rounding.small, style: .continuous)
            )
            .animation(ShellMotion.contentIn.animation, value: configuration.isPressed)
            .animation(ShellMotion.contentIn.animation, value: isEnabled)
    }
}

// AppKit's `.switch` toggle draws its own off-state track from the system
// appearance, not from the shell's palette. On the White palette that track is
// a light grey sitting on an almost-white card, which makes an off switch
// effectively invisible -- the same white-on-white failure the volume sliders
// had before they were given real tokens. Nothing about the native control is
// palette-aware, so it is replaced outright rather than tinted: the track uses
// the same sliderTrack token (a guaranteed lightness step away from frame on
// every palette) when off and the accent when on, and the knob uses onAccent
// while on -- which is chosen from the accent's own luminance -- so it is
// legible against both states on every palette.
private struct ShellSwitchToggleStyle: ToggleStyle {
    var compact = false

    func makeBody(configuration: Configuration) -> some View {
        let width: CGFloat = compact ? 30 : 36
        let height: CGFloat = compact ? 17 : 20
        let inset: CGFloat = 2
        let knob = height - inset * 2
        // spacing 0, and no Spacer inserted here: every existing call site
        // already positions its own label (either an HStack with a Spacer
        // before a labelsHidden toggle, or a label that ends in a Spacer), so
        // adding spacing here would double the gap on some and add a stray one
        // on the empty-label cases.
        // A real Button gives the complete styled Toggle one native focus and
        // keyboard activation target. The previous knob-only tap gesture left
        // a labelled row looking clickable while Return, Space and VoiceOver
        // could not operate it. Keep one action owner here so a pointer press
        // cannot also fall through to a second gesture and toggle twice.
        return Button {
            configuration.isOn.toggle()
        } label: {
            HStack(spacing: Spacing.none) {
                configuration.label
                Capsule()
                    .fill(configuration.isOn ? Theme.accent : Theme.sliderTrack)
                    .overlay(Capsule().stroke(Theme.seam.opacity(0.45), lineWidth: 0.8))
                    .frame(width: width, height: height)
                    .overlay(alignment: configuration.isOn ? .trailing : .leading) {
                        Circle()
                            .fill(configuration.isOn ? Theme.onAccent : Theme.bright)
                            .frame(width: knob, height: knob)
                            .padding(.horizontal, inset)
                    }
            }
            .contentShape(Rectangle())
            .animation(ShellMotion.contentIn.animation, value: configuration.isOn)
        }
        .buttonStyle(.plain)
        .accessibilityElement(children: .combine)
        .accessibilityAddTraits(.isToggle)
        .accessibilityValue(configuration.isOn ? "On" : "Off")
    }
}

private struct MediaCircleButtonStyle: ButtonStyle {
    @Environment(\.isEnabled) private var isEnabled

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .scaleEffect(isEnabled && configuration.isPressed ? 0.88 : 1)
            .brightness(isEnabled && configuration.isPressed ? 0.10 : 0)
            .saturation(isEnabled ? 1 : 0.35)
            .opacity(isEnabled ? (configuration.isPressed ? 0.82 : 1) : 0.38)
            // ShellMotion.press exists specifically for this -- a scale-down
            // squish -- and its fastSpatial curve overshoots past 1.0 before
            // settling (that's the actual bounce caelestia's press feedback
            // has), but it sat completely unused while this button style ran
            // its own flat, un-bouncy 0.075s ease-out instead.
            .animation(ShellMotion.press.animation, value: configuration.isPressed)
            .animation(ShellMotion.contentIn.animation, value: isEnabled)
    }
}

// mergeTrailingFillet / mergeLeadingFillet implement Caelestia's behaviour for
// a popout that runs out of room before its free corner can complete a proper
// curve: rather than leaving a too-small gap (or a visibly clipped corner)
// between the surface and the physical rim it is approaching, the surface is
// carried flush INTO that rim so the two read as one continuous mass, and the
// junction where the surface's free edge meets the rim is finished with a
// reverse (concave) fillet -- the same inner-corner language the shell frame
// already uses where the rail meets the top rim, and the mirror image of the
// reverse curves this path already draws where the surface meets its
// attachment edge.
//
// Geometry note: a concave fillet ADDS material at the corner, so it needs
// room *outside* the body's own free edge to flare into. The caller therefore
// sizes the surface `fillet` larger on the free-edge axis and this function
// keeps the body edge inset by that amount -- exactly the reservation pattern
// `attachedSurfaceShoulder` already uses for the attachment curves. Both
// default to 0, so every existing call site draws precisely as before.
private func canonicalTopMorphPath(
    in rect: CGRect,
    depth requestedDepth: CGFloat,
    shoulder requestedShoulder: CGFloat,
    bodyRadius requestedRadius: CGFloat,
    outlineOnly: Bool,
    omitTrailingAttachmentShoulder: Bool = false,
    mergeTrailingFillet: CGFloat = 0,
    mergeLeadingFillet: CGFloat = 0
) -> Path {
        guard rect.width > 0, rect.height > 0 else { return Path() }
        let shoulderLimit = max(0, (rect.width - 2) / 4)
        let s = min(requestedShoulder, shoulderLimit)
        // Leave a fractional body below the physical rim even on the first
        // animated frame. Clamping the depth to the entire temporary wrapper
        // height briefly reduced the morph to a square strip while it opened.
        let depth = min(max(0, requestedDepth), max(0, rect.height - 0.75))
        let bodyHeight = max(0, rect.height - depth)
        // This is Caelestia's `flatten` rule.  The horizontal rounding stays
        // constant while its vertical component collapses to half of the
        // animated wrapper height.  It prevents oversized corner wings from
        // crossing the physical rim during the first and last frames.
        let shoulderY = min(s, bodyHeight / 2)
        // A merged end reaches the rim across the surface's full extent, so it
        // spends no shoulder inset there -- the shoulder exists to blend a
        // narrow body into a wider attachment strip, and a merged end has no
        // such step to blend. Reserve the fillet on the free edge itself;
        // this is the same reservation used by the ordinary lower corner,
        // which makes the merged path a literal rotation of that curve.
        let mergeLimit = max(0, (rect.width - 2) / 4)
        let trailingFillet = min(max(0, mergeTrailingFillet), mergeLimit)
        let leadingFillet = min(max(0, mergeLeadingFillet), mergeLimit)
        let mergesTrailing = trailingFillet > 0.000_1
        let mergesLeading = leadingFillet > 0.000_1
        let flare = max(trailingFillet, leadingFillet)
        // The lower merge is the ordinary lower corner rotated into the
        // left-attached surface. Its body edge must therefore remain on the
        // actual free edge; reserving `leadingFillet` here created an extra
        // horizontal jog before the curve (the visible bump in the lower
        // gutter). The curve itself owns the smoothing band and terminates
        // exactly one fillet inside that edge. Keep the older inset behavior
        // for the other merge direction until it reaches its own dedicated
        // rim primitive.
        let bodyMaxY = mergesLeading && !mergesTrailing
            ? rect.maxY
            : rect.maxY - flare
        let trailingInset = mergesTrailing ? 0 : s
        let leadingInset = mergesLeading ? 0 : s
        let b = min(requestedRadius, max(0, (rect.width - trailingInset - leadingInset) / 2))
        let bodyY = min(b, bodyHeight / 2)
        var path = Path()
        if outlineOnly {
            path.move(to: CGPoint(x: rect.maxX, y: depth))
        } else {
        path.move(to: CGPoint(x: 0, y: 0))
        path.addLine(to: CGPoint(x: rect.maxX, y: 0))
        path.addLine(to: CGPoint(x: rect.maxX, y: depth))
        }
        guard bodyHeight > 0.000_1 else {
            if !outlineOnly { path.closeSubpath() }
            return path
        }
        if mergesTrailing {
            // Carry the surface flush along the rim, then rotate the regular
            // lower corner into the merged shoulder. The endpoint remains on
            // the destination box, so the full-screen contour and the AppKit
            // host share the same final pixel instead of drawing a floating
            // extension beyond the panel.
            path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
            path.addQuadCurve(
                to: CGPoint(x: rect.maxX - trailingFillet, y: bodyMaxY),
                control: CGPoint(x: rect.maxX - trailingFillet, y: rect.maxY)
            )
        } else {
            path.addQuadCurve(to: CGPoint(x: rect.maxX - s, y: depth + shoulderY), control: CGPoint(x: rect.maxX - s, y: depth))
            path.addLine(to: CGPoint(x: rect.maxX - s, y: bodyMaxY - bodyY))
            path.addQuadCurve(to: CGPoint(x: rect.maxX - s - b, y: bodyMaxY), control: CGPoint(x: rect.maxX - s, y: bodyMaxY))
        }
        if mergesLeading {
            // Rotate the ordinary lower-left corner into the bottom-right
            // reverse gutter. The important distinction from the old failed
            // flip is that the body's free edge stays at `rect.maxY`; the
            // rotated arc travels OUTWARD from that edge into the shell rim.
            // In the `.left` transform, canonical `(f, maxY)` is the screen
            // point `(maxY, height - f)` and canonical `(0, maxY + f)` is
            // `(maxY + f, height)`. That is the quarter turn the Caelestia
            // union produces, rather than an inset card corner.
            //
            // Use the same circular-cubic approximation as the shell frame.
            // The quadratic used here previously put its control point at the
            // corner, so it was visibly flatter and read as a loose smooth
            // connection instead of a tangent reverse fillet.
            let arcControl = leadingFillet * 0.552_284_749_830_793_6
            path.addLine(to: CGPoint(x: leadingFillet, y: bodyMaxY))
            path.addCurve(
                to: CGPoint(x: 0, y: rect.maxY + leadingFillet),
                control1: CGPoint(
                    x: leadingFillet - arcControl,
                    y: rect.maxY
                ),
                control2: CGPoint(
                    x: 0,
                    y: rect.maxY + leadingFillet - arcControl
                )
            )
            // The full-screen fill/contour layer owns the outward half of the
            // arc. The local hosting panel clips at its original envelope,
            // which is intentional: content still sees the unchanged gutter
            // while the shared shell layer paints the rim bridge outside it.
            // The fill still needs the attachment edge to close its opaque
            // body; the contour does not. Leaving this line in the outline
            // would redraw the entire shell bottom beneath the card.
            if !outlineOnly {
                path.addLine(to: CGPoint(x: 0, y: depth))
            }
        } else {
            path.addLine(to: CGPoint(x: s + b, y: bodyMaxY))
            path.addQuadCurve(to: CGPoint(x: s, y: bodyMaxY - bodyY), control: CGPoint(x: s, y: bodyMaxY))
            path.addLine(to: CGPoint(x: s, y: depth + shoulderY))
            if !(outlineOnly && omitTrailingAttachmentShoulder) {
                path.addQuadCurve(to: CGPoint(x: 0, y: depth), control: CGPoint(x: s, y: depth))
            }
        }
        if !outlineOnly { path.closeSubpath() }
        return path
}

private struct TopMorphShape: Shape {
    var shoulder: CGFloat = surfaceMorphShoulder
    var bottomRadius: CGFloat = 22
    /// Defaults to the primary display so existing call sites are unchanged;
    /// anything drawn on a known screen should pass that screen's depth.
    var topDepth: CGFloat = shellTopDepth()
    func path(in rect: CGRect) -> Path {
        canonicalTopMorphPath(in: rect, depth: topDepth, shoulder: shoulder, bodyRadius: bottomRadius, outlineOnly: false)
    }
}

private struct RightMorphShape: Shape {
    var radius: CGFloat = 20
    func path(in rect: CGRect) -> Path {
        let base = CGRect(x: 0, y: 0, width: rect.height, height: rect.width)
        return canonicalTopMorphPath(in: base, depth: shellFrame, shoulder: surfaceMorphShoulder, bodyRadius: radius, outlineOnly: false)
            .applying(CGAffineTransform(a: 0, b: 1, c: -1, d: 0, tx: rect.width, ty: 0))
    }
}

private struct RightSidebarMorphShape: Shape {
    var radius: CGFloat = 22
    func path(in rect: CGRect) -> Path {
        _ = radius
        return rightSidebarMorphPath(in: rect, outlineOnly: false)
    }
}

/// The notification drawer is a full-height shell union rather than a
/// rotated card. Its fill occupies the host rectangle, while its contour is
/// only the shell-facing edge. The upper reverse curve is kept inside the
/// host's clip so AppKit cannot turn it into a hard corner; the lower shoulder
/// still resolves outward into the shell rim. Keeping the stroke open prevents
/// an artificial horizontal line from appearing across the drawer near either
/// rim.
private func rightSidebarMorphPath(
    in rect: CGRect,
    outlineOnly: Bool,
    omitTopShoulder: Bool = false,
    preservedTopCurveStartY: CGFloat? = nil
) -> Path {
    guard rect.width > 0, rect.height > 0 else { return Path() }
    let shoulder = min(
        surfaceMorphShoulder,
        max(0, rect.height / 2),
        max(0, rect.width / 2)
    )
    guard shoulder > 0.000_1 else {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
        if outlineOnly {
            var edge = Path()
            edge.move(to: CGPoint(x: rect.minX, y: rect.minY))
            edge.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
            return edge
        }
        path.closeSubpath()
        return path
    }
    // The regular sidebar and the promoted sidebar use one upper geometry.
    // During promotion only its local y-origin moves back toward the panel's
    // top; that is the saved compact curve's screen-space anchor.
    let requestedCurveStartY = omitTopShoulder
        ? (preservedTopCurveStartY ?? rect.minY)
        : rect.minY
    let curveStartY = min(
        max(rect.minY, requestedCurveStartY),
        max(rect.minY, rect.maxY - shoulder - notificationTopShoulder)
    )
    let curveShoulder = min(
        notificationTopShoulder,
        max(0, rect.maxX - rect.minX),
        max(0, rect.maxY - curveStartY - shoulder)
    )
    let curveEndX = rect.minX + curveShoulder
    let curveEndY = curveStartY + curveShoulder

    if outlineOnly {
        var edge = Path()
        edge.move(to: CGPoint(x: rect.minX, y: curveStartY))
        edge.addQuadCurve(
            to: CGPoint(x: curveEndX, y: curveEndY),
            control: CGPoint(x: curveEndX, y: curveStartY)
        )
        edge.addLine(to: CGPoint(x: curveEndX, y: rect.maxY - shoulder))
        // Reuse the exact reverse-shoulder quadratic used by the upper edge,
        // mirrored into the footer. The old bespoke cubic stretched past the
        // panel envelope and made the lower seam read as a second curve.
        edge.addQuadCurve(
            to: CGPoint(x: rect.minX, y: rect.maxY),
            control: CGPoint(x: curveEndX, y: rect.maxY)
        )
        return edge
    }

    // ContentWindow.qml does not paint the sidebar's reverse shoulder as a
    // second floating outline. Its PanelBg participates in the same material
    // union as the shell frame, so use the exact same upper/lower edge for the
    // fill and the clip.
    var fill = Path()
    fill.move(to: CGPoint(x: rect.minX, y: curveStartY))
    fill.addQuadCurve(
        to: CGPoint(x: curveEndX, y: curveEndY),
        control: CGPoint(x: curveEndX, y: curveStartY)
    )
    fill.addLine(to: CGPoint(x: curveEndX, y: rect.maxY - shoulder))
    fill.addQuadCurve(
        to: CGPoint(x: rect.minX, y: rect.maxY),
        // Keep the fill on that exact mirrored segment so the fill and open
        // contour cannot diverge at the lower shoulder.
        control: CGPoint(x: curveEndX, y: rect.maxY)
    )
    fill.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
    fill.addLine(to: CGPoint(x: rect.maxX, y: curveStartY))
    fill.addLine(to: CGPoint(x: rect.minX, y: curveStartY))
    fill.closeSubpath()
    return fill
}

private struct LeftMorphShape: Shape {
    var radius: CGFloat = 20
    func path(in rect: CGRect) -> Path {
        let base = CGRect(x: 0, y: 0, width: rect.height, height: rect.width)
        return canonicalTopMorphPath(in: base, depth: leftAttachmentDepth, shoulder: surfaceMorphShoulder, bodyRadius: radius, outlineOnly: false)
            .applying(CGAffineTransform(a: 0, b: -1, c: 1, d: 0, tx: 0, ty: rect.height))
    }
}

// A single continuous surface that grows out of the left rail and then
// resolves into the bottom frame.  Its two shoulders use the same depth,
// radius and quadratic curve language as the canonical edge morph above.
private func bottomLeftMorphPath(
    in rect: CGRect,
    radius requestedRadius: CGFloat,
    outlineOnly: Bool,
    omitTrailingAttachmentShoulder: Bool = false
) -> Path {
    guard rect.width > 0, rect.height > 0 else { return Path() }
    let depth = min(leftAttachmentDepth, max(0, rect.height - 10))
    // The utility surface now unfolds horizontally from the rail. Its curves
    // therefore need to collapse proportionally at narrow intermediate widths
    // instead of enforcing a six-point minimum that folds over itself.
    let shoulder = min(22, max(0, (rect.width - 40) * 0.16))
    let radius = min(requestedRadius, max(0, rect.width * 0.24))
    let flatten = min(1, rect.height / max(1, shoulder * 2 + radius))
    let shoulderY = shoulder * flatten
    let radiusY = radius * flatten
    let bodyRight = rect.maxX - shoulder
    var path = Path()

    if outlineOnly {
        path.move(to: CGPoint(x: depth, y: rect.minY))
    } else {
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        path.addLine(to: CGPoint(x: depth, y: rect.minY))
    }
    path.addQuadCurve(
        to: CGPoint(x: depth + shoulder, y: rect.minY + shoulderY),
        control: CGPoint(x: depth, y: rect.minY + shoulderY)
    )
    path.addLine(to: CGPoint(x: bodyRight - radius, y: rect.minY + shoulderY))
    path.addQuadCurve(
        to: CGPoint(x: bodyRight, y: rect.minY + shoulderY + radiusY),
        control: CGPoint(x: bodyRight, y: rect.minY + shoulderY)
    )
    path.addLine(to: CGPoint(x: bodyRight, y: rect.maxY - depth - shoulderY))
    if !(outlineOnly && omitTrailingAttachmentShoulder) {
        path.addQuadCurve(
            to: CGPoint(x: rect.maxX, y: rect.maxY - depth),
            control: CGPoint(x: bodyRight, y: rect.maxY - depth)
        )
    }
    if !outlineOnly {
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
        path.closeSubpath()
    }
    return path
}

private struct BottomLeftMorphShape: Shape {
    var radius: CGFloat = 20
    func path(in rect: CGRect) -> Path {
        bottomLeftMorphPath(in: rect, radius: radius, outlineOnly: false)
    }
}

// The top-right notification joins rims with different depths: the display's
// measured top rim and the fixed right frame. Rotating the bottom-left path
// loses both measurements, hiding the top curve in the rim and burying the
// side curve in the screen border. Keep its contour explicit instead.
private func topRightNotificationMorphPath(
    in rect: CGRect,
    topDepth requestedTopDepth: CGFloat,
    rightDepth requestedRightDepth: CGFloat,
    topShoulder requestedTopShoulder: CGFloat = notificationTopShoulder,
    sideShoulder requestedSideShoulder: CGFloat = notificationSideShoulder,
    radius requestedRadius: CGFloat = notificationCornerRadius,
    outlineOnly: Bool,
    omitTopReverseShoulder: Bool = false,
    topReverseCurveOnly: Bool = false
) -> Path {
    guard rect.width > 0, rect.height > 0 else { return Path() }

    let topDepth = min(max(0, requestedTopDepth), max(0, rect.height - 0.75))
    let rightDepth = min(max(0, requestedRightDepth), max(0, rect.width - 0.75))
    let bodyHeight = max(0, rect.height - topDepth)
    let interiorWidth = max(0, rect.width - rightDepth)
    let widthLimit = interiorWidth / 3
    let topShoulder = min(requestedTopShoulder, bodyHeight / 2, widthLimit)
    let sideShoulder = min(requestedSideShoulder, bodyHeight / 2, widthLimit)
    let innerRight = rect.maxX - rightDepth
    let bottomY = rect.maxY - sideShoulder
    let sideStartX = max(topShoulder, innerRight - sideShoulder)
    let verticalRoom = max(0, bottomY - (topDepth + topShoulder))
    let horizontalRoom = max(0, sideStartX - topShoulder)
    let radius = min(requestedRadius, verticalRoom, horizontalRoom / 2)

    var path = Path()
    if omitTopReverseShoulder {
        // The explicit compact curve is retained by the shell-wide contour;
        // continue the outgoing edge from its endpoint so the same stroke is
        // never painted twice during the crossfade.
        path.move(to: CGPoint(x: topShoulder, y: topDepth + topShoulder))
    } else {
        path.move(to: CGPoint(x: rect.minX, y: topDepth))
        path.addQuadCurve(
            to: CGPoint(x: topShoulder, y: topDepth + topShoulder),
            control: CGPoint(x: topShoulder, y: topDepth)
        )
    }
    if topReverseCurveOnly {
        return path
    }
    path.addLine(to: CGPoint(x: topShoulder, y: bottomY - radius))
    path.addQuadCurve(
        to: CGPoint(x: topShoulder + radius, y: bottomY),
        control: CGPoint(x: topShoulder, y: bottomY)
    )
    path.addLine(to: CGPoint(x: sideStartX, y: bottomY))
    path.addQuadCurve(
        to: CGPoint(x: innerRight, y: rect.maxY),
        control: CGPoint(x: innerRight, y: bottomY)
    )

    if !outlineOnly {
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.minX, y: rect.minY))
        path.closeSubpath()
    }
    return path
}

private struct TopRightMorphShape: Shape {
    let topDepth: CGFloat
    var radius: CGFloat = notificationCornerRadius
    func path(in rect: CGRect) -> Path {
        topRightNotificationMorphPath(
            in: rect,
            topDepth: topDepth,
            rightDepth: shellFrame,
            radius: radius,
            outlineOnly: false
        )
    }
}

/// The compact notification owns its own envelope while it is a standalone
/// popout. During promotion the shell-wide surface owns that envelope instead;
/// keeping the compact content rectangular prevents a second reverse shoulder
/// from being composited inside the growing sidebar.
private struct NotificationCaptureMockupClipShape: InsettableShape {
    let topDepth: CGFloat
    let drawsSurface: Bool
    var insetAmount: CGFloat = 0

    func inset(by amount: CGFloat) -> NotificationCaptureMockupClipShape {
        var copy = self
        copy.insetAmount += max(0, amount)
        return copy
    }

    func path(in rect: CGRect) -> Path {
        let rect = rect.insetBy(dx: insetAmount, dy: insetAmount)
        guard drawsSurface else {
            var path = Path()
            path.addRect(rect)
            return path
        }
        return TopRightMorphShape(topDepth: topDepth).path(in: rect)
    }
}

private extension View {
    func attachedTop(_ radius: CGFloat = 24, motion: SurfaceMotionState) -> some View {
        let shape = TopMorphShape(shoulder: surfaceMorphShoulder, bottomRadius: radius)
        return clipShape(shape)
    }
    func attachedRight(_ radius: CGFloat = 22, motion: SurfaceMotionState) -> some View {
        let shape = RightMorphShape(radius: radius)
        return clipShape(shape)
    }
    func attachedLeft(_ radius: CGFloat = 20, motion: SurfaceMotionState) -> some View {
        let shape = LeftMorphShape(radius: radius)
        return clipShape(shape)
    }
    func attachedBottomLeft(_ radius: CGFloat = 20, motion: SurfaceMotionState) -> some View {
        let shape = BottomLeftMorphShape(radius: radius)
        return clipShape(shape)
    }
}

private let shellInnerRadius: CGFloat = 20

private func shellInnerRect(in rect: CGRect, topDepth: CGFloat = shellTopDepth()) -> CGRect {
    CGRect(
        x: railWidth,
        y: topDepth,
        width: max(0, rect.width - railWidth - shellFrame),
        height: max(0, rect.height - topDepth - shellFrame)
    )
}

// A single circular-cubic contour is shared by both the frame aperture and
// its visible stroke. SwiftUI's separate continuous RoundedRectangle layers
// rasterized the straight-to-curve join on different pixels, producing the
// tiny square notch visible at every corner.
private func shellInnerContourPath(
    in rect: CGRect,
    radius requestedRadius: CGFloat = shellInnerRadius,
    topDepth: CGFloat = shellTopDepth(),
    omitBottom: Bool = false
) -> Path {
    guard rect.width > 0, rect.height > 0 else { return Path() }
    let rect = shellInnerRect(in: rect, topDepth: topDepth)
    let radius = min(requestedRadius, rect.width / 2, rect.height / 2)
    let kappa: CGFloat = 0.552_284_749_830_793_6
    let control = radius * kappa
    var path = Path()
    path.move(to: CGPoint(x: rect.minX + radius, y: rect.minY))
    path.addLine(to: CGPoint(x: rect.maxX - radius, y: rect.minY))
    path.addCurve(
        to: CGPoint(x: rect.maxX, y: rect.minY + radius),
        control1: CGPoint(x: rect.maxX - radius + control, y: rect.minY),
        control2: CGPoint(x: rect.maxX, y: rect.minY + radius - control)
    )
    path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY - radius))
    path.addCurve(
        to: CGPoint(x: rect.maxX - radius, y: rect.maxY),
        control1: CGPoint(x: rect.maxX, y: rect.maxY - radius + control),
        control2: CGPoint(x: rect.maxX - radius + control, y: rect.maxY)
    )
    // A bottom-connected surface owns this rim while it is open. Keep the
    // lower corner curves (they are still part of the shell silhouette), but
    // make the straight section a separate subpath so it cannot remain as a
    // bright line after the surface's reverse fillet has reached the rim.
    if omitBottom {
        path.move(to: CGPoint(x: rect.minX + radius, y: rect.maxY))
    } else {
        path.addLine(to: CGPoint(x: rect.minX + radius, y: rect.maxY))
    }
    path.addCurve(
        to: CGPoint(x: rect.minX, y: rect.maxY - radius),
        control1: CGPoint(x: rect.minX + radius - control, y: rect.maxY),
        control2: CGPoint(x: rect.minX, y: rect.maxY - radius + control)
    )
    path.addLine(to: CGPoint(x: rect.minX, y: rect.minY + radius))
    path.addCurve(
        to: CGPoint(x: rect.minX + radius, y: rect.minY),
        control1: CGPoint(x: rect.minX, y: rect.minY + radius - control),
        control2: CGPoint(x: rect.minX + radius - control, y: rect.minY)
    )
    path.closeSubpath()
    return path
}

private struct UnifiedShellFrame: Shape {
    let topDepth: CGFloat
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.addRect(rect)
        // The fill aperture and visible contour are the same exact path.
        // Window breathing room is supplied by yabai; insetting this aperture
        // created a second, parallel frame boundary four points inside it.
        path.addPath(shellInnerContourPath(in: rect, topDepth: topDepth))
        return path
    }
}

private struct ShellInnerContour: Shape {
    let topDepth: CGFloat
    var omitBottom = false
    func path(in rect: CGRect) -> Path {
        shellInnerContourPath(in: rect, topDepth: topDepth, omitBottom: omitBottom)
    }
}

// All expanding shell material is painted in the same full-screen layer as
// the monitor frame.  Caelestia does this in a single Qt Shape; reproducing
// that architecture removes window-to-window antialias seams entirely.
private func shellSurfaceCurrentFrame(
    attachment: SurfaceAttachment,
    finalFrame: CGRect,
    progress: CGFloat,
    topDepth: CGFloat = shellTopDepth(),
    contracting: Bool = false
) -> CGRect {
    let p = max(0, min(1, progress))
    func seededExtent(_ full: CGFloat, _ seed: CGFloat) -> CGFloat {
        let extent = max(0, full)
        if contracting { return extent * p }
        let start = min(extent, max(0, seed))
        return start + (extent - start) * p
    }
    switch attachment {
    case .top:
        let seedWidth = min(finalFrame.width, 209)
        let width = seededExtent(finalFrame.width, seedWidth)
        let rimDepth = min(topDepth, finalFrame.height)
        let bodySeed = min(1, max(0, finalFrame.height - rimDepth))
        let height = rimDepth + bodySeed
            + max(0, finalFrame.height - rimDepth - bodySeed) * p
        return CGRect(
            x: finalFrame.midX - width / 2, y: finalFrame.minY,
            width: width, height: height
        )
    case .bottom:
        let seedWidth = min(finalFrame.width, 120)
        let width = seededExtent(finalFrame.width, seedWidth)
        let height = finalFrame.height * p
        return CGRect(
            x: finalFrame.midX - width / 2, y: finalFrame.maxY - height,
            width: width, height: height
        )
    case .left:
        // The complete left rail intentionally keeps the original linear
        // reveal. Its edge is the handoff surface for the bar, so a seeded
        // width makes it feel like the other three sides and causes the card
        // to appear before its rail contact is established. The dual-edge
        // `.bottomLeft` utility remains separate below.
        return CGRect(
            x: finalFrame.minX, y: finalFrame.minY,
            width: finalFrame.width * p,
            height: finalFrame.height
        )
    case .right:
        let rimDepth = min(shellFrame, finalFrame.width)
        let bodySeed = min(1, max(0, finalFrame.width - rimDepth))
        let width = rimDepth + bodySeed
            + max(0, finalFrame.width - rimDepth - bodySeed) * p
        let seedHeight = min(finalFrame.height, 70)
        let height = seedHeight + (finalFrame.height - seedHeight) * p
        return CGRect(
            x: finalFrame.maxX - width, y: finalFrame.midY - height / 2,
            width: width, height: height
        )
    case .rightSidebar:
        // The notification center is full-height, but its presentation still
        // follows the same edge-owned reveal as the bottom-left utility: the
        // host stays at its destination and the shared silhouette grows from
        // the shell-facing edge. Translating a complete sidebar from outside
        // the display made the reverse shoulders exist at full size before
        // the card had arrived, which is a different animation clock from
        // every other attached surface.
        let width = finalFrame.width * p
        guard width > 0.000_1 else { return .zero }
        return CGRect(
            x: finalFrame.maxX - width, y: finalFrame.minY,
            width: width, height: finalFrame.height
        )
    case .topRight:
        // Unfold diagonally from the physical screen corner. The seed is no
        // larger than the two resting rims; both axes then resolve on the
        // same progress token so neither attachment appears to lead.
        let seedWidth = min(finalFrame.width, shellFrame + 1)
        let seedHeight = min(finalFrame.height, topDepth + 1)
        let width = seededExtent(finalFrame.width, seedWidth)
        let height = seededExtent(finalFrame.height, seedHeight)
        return CGRect(
            x: finalFrame.maxX - width, y: finalFrame.minY,
            width: width, height: height
        )
    case .bottomLeft:
        return CGRect(
            x: finalFrame.minX, y: finalFrame.minY,
            width: finalFrame.width * p, height: finalFrame.height
        )
    }
}

private struct ShellSurfaceMorphShape: Shape {
    let attachment: SurfaceAttachment
    let finalFrame: CGRect
    let radius: CGFloat
    var outlineOnly = false
    var omitTrailingAttachmentShoulder = false
    // Non-zero when this surface reached the shell's top / bottom rim and was
    // merged into it (see canonicalTopMorphPath's merge comment). In the
    // rotated base space used by `.left`, base-trailing is the screen's top
    // and base-leading is the screen's bottom.
    var mergeTopFillet: CGFloat = 0
    var mergeBottomFillet: CGFloat = 0
    var progress: CGFloat
    var deformation: CaelestiaSurfaceDeformation = .identity
    /// Rim depth of the display this surface belongs to.
    var topDepth: CGFloat = shellTopDepth()
    /// Reveals keep their small Caelestia seed so the attachment is established
    /// immediately. Dismissals collapse every seeded axis back to zero instead
    /// of leaving a terminal cap behind after the persistent shell rim returns.
    var contracting = false
    /// A top-right notification handoff keeps the compact card's reverse top
    /// curve as the visual anchor. These options are presentation-only and
    /// are used by the shell-wide contour while the two attachments overlap.
    var omitTopReverseShoulder = false
    var topReverseCurveOnly = false
    /// Local y-coordinate of the compact curve's start when the incoming
    /// right-sidebar fill/clip must preserve it during promotion.
    var preservedTopCurveStartY: CGFloat?

    var animatableData: AnimatablePair<AnimatablePair<CGFloat, CGFloat>, CGFloat> {
        get { AnimatablePair(AnimatablePair(progress, mergeTopFillet), mergeBottomFillet) }
        set {
            progress = newValue.first.first
            mergeTopFillet = newValue.first.second
            mergeBottomFillet = newValue.second
        }
    }

    func path(in rect: CGRect) -> Path {
        let p = max(0, progress)
        guard p > 0.000_1 else { return Path() }
        // LivingSurface uses the local shape form with a zero finalFrame so
        // it can be used as a native clip shape instead of a content-sized
        // raster mask. In that form the proposed shape rect is the final
        // destination size.
        let destination = finalFrame.width > 0 && finalFrame.height > 0
            ? finalFrame
            : CGRect(origin: .zero, size: rect.size)
        let current = shellSurfaceCurrentFrame(
            attachment: attachment, finalFrame: destination, progress: p,
            topDepth: topDepth, contracting: contracting
        )
        guard current.width > 0.5, current.height > 0.5 else { return Path() }

        let local = CGRect(origin: .zero, size: current.size)
        var localPath: Path
        switch attachment {
        case .top:
            localPath = canonicalTopMorphPath(
                in: local, depth: topDepth, shoulder: surfaceMorphShoulder,
                bodyRadius: radius, outlineOnly: outlineOnly
            )
        case .bottom:
            localPath = canonicalTopMorphPath(
                in: local, depth: 0, shoulder: surfaceMorphShoulder,
                bodyRadius: radius, outlineOnly: outlineOnly
            ).applying(CGAffineTransform(a: 1, b: 0, c: 0, d: -1, tx: 0, ty: local.height))
        case .left:
            let base = CGRect(x: 0, y: 0, width: local.height, height: local.width)
            localPath = canonicalTopMorphPath(
                in: base, depth: 0, shoulder: surfaceMorphShoulder,
                bodyRadius: radius,
                outlineOnly: outlineOnly,
                omitTrailingAttachmentShoulder: omitTrailingAttachmentShoulder,
                // The rotation maps base x=maxX to the screen's top and base
                // x=0 to the screen's bottom, so the trailing/leading fillets
                // are the top/bottom merges respectively.
                mergeTrailingFillet: mergeTopFillet,
                mergeLeadingFillet: mergeBottomFillet
            ).applying(CGAffineTransform(a: 0, b: -1, c: 1, d: 0, tx: 0, ty: local.height))
        case .right:
            let base = CGRect(x: 0, y: 0, width: local.height, height: local.width)
            localPath = canonicalTopMorphPath(
                in: base, depth: shellFrame, shoulder: surfaceMorphShoulder,
                bodyRadius: radius, outlineOnly: outlineOnly
            ).applying(CGAffineTransform(a: 0, b: 1, c: -1, d: 0, tx: local.width, ty: 0))
        case .rightSidebar:
            // The sidebar uses the mirror orientation of the compact right
            // surface, but only its shell-facing edge is stroked. The fill is
            // persistent across the whole host rect so the top/bottom rim is
            // covered before the AppKit host starts travelling.
            localPath = rightSidebarMorphPath(
                in: local,
                outlineOnly: outlineOnly,
                omitTopShoulder: omitTopReverseShoulder,
                preservedTopCurveStartY: preservedTopCurveStartY
            )
        case .topRight:
            localPath = topRightNotificationMorphPath(
                in: local,
                topDepth: topDepth,
                rightDepth: shellFrame,
                radius: radius,
                outlineOnly: outlineOnly,
                omitTopReverseShoulder: omitTopReverseShoulder,
                topReverseCurveOnly: topReverseCurveOnly
            )
        case .bottomLeft:
            localPath = bottomLeftMorphPath(
                in: local,
                radius: radius,
                outlineOnly: outlineOnly,
                omitTrailingAttachmentShoulder: omitTrailingAttachmentShoulder
            )
        }
        let translated = localPath.applying(
            CGAffineTransform(translationX: current.minX, y: current.minY)
        )
        // The rail-attached shoulder and reverse rim fillet are authored shell
        // geometry, not part of the elastic body. Applying the BlobRect
        // velocity matrix to the whole `.left` path made their vertical legs
        // compress on the first reveal frame and expand as the spring
        // returned to identity, even though the `merge*Fillet` value was
        // already at its final 20pt length. Keep the complete rail contour
        // exact; free-standing side surfaces retain the directional
        // deformation, while the top-right notification contour is also
        // shell-owned so its border cannot bow into the frame.
        let preservesRailContour = attachment == .left || attachment == .rightSidebar
            || attachment == .topRight
            || mergeTopFillet > 0.0001
            || mergeBottomFillet > 0.0001
        let contourDeformation = preservesRailContour
            ? CaelestiaSurfaceDeformation.identity
            : deformation
        return translated.applying(
            contourDeformation.affineTransform(around: CGPoint(x: current.midX, y: current.midY))
        )
    }
}

private struct ShellContourInterval {
    let start: CGFloat
    let end: CGFloat
}

private func appendShellContourInterval(
    _ intervals: inout [ShellContourInterval],
    start: CGFloat,
    end: CGFloat,
    lowerBound: CGFloat,
    upperBound: CGFloat
) {
    let clippedStart = max(lowerBound, min(upperBound, start))
    let clippedEnd = max(lowerBound, min(upperBound, end))
    guard clippedEnd - clippedStart > 0.25 else { return }
    intervals.append(ShellContourInterval(start: clippedStart, end: clippedEnd))
}

private func appendShellContourHorizontalSegments(
    _ path: inout Path,
    y: CGFloat,
    start: CGFloat,
    end: CGFloat,
    excluding rawExclusions: [ShellContourInterval]
) {
    guard end - start > 0.25 else { return }
    let exclusions = rawExclusions
        .compactMap { exclusion -> ShellContourInterval? in
            let lower = max(start, min(end, exclusion.start))
            let upper = max(start, min(end, exclusion.end))
            guard upper - lower > 0.25 else { return nil }
            return ShellContourInterval(start: lower, end: upper)
        }
        .sorted { $0.start < $1.start }
    var cursor = start
    for exclusion in exclusions {
        if exclusion.start - cursor > 0.25 {
            path.move(to: CGPoint(x: cursor, y: y))
            path.addLine(to: CGPoint(x: exclusion.start, y: y))
        }
        cursor = max(cursor, exclusion.end)
    }
    if end - cursor > 0.25 {
        path.move(to: CGPoint(x: cursor, y: y))
        path.addLine(to: CGPoint(x: end, y: y))
    }
}

private func appendShellContourVerticalSegments(
    _ path: inout Path,
    x: CGFloat,
    start: CGFloat,
    end: CGFloat,
    excluding rawExclusions: [ShellContourInterval]
) {
    guard end - start > 0.25 else { return }
    let exclusions = rawExclusions
        .compactMap { exclusion -> ShellContourInterval? in
            let lower = max(start, min(end, exclusion.start))
            let upper = max(start, min(end, exclusion.end))
            guard upper - lower > 0.25 else { return nil }
            return ShellContourInterval(start: lower, end: upper)
        }
        .sorted { $0.start < $1.start }
    var cursor = start
    for exclusion in exclusions {
        if exclusion.start - cursor > 0.25 {
            path.move(to: CGPoint(x: x, y: cursor))
            path.addLine(to: CGPoint(x: x, y: exclusion.start))
        }
        cursor = max(cursor, exclusion.end)
    }
    if end - cursor > 0.25 {
        path.move(to: CGPoint(x: x, y: cursor))
        path.addLine(to: CGPoint(x: x, y: end))
    }
}

private struct ShellContourOpening {
    let attachment: SurfaceAttachment
    let finalFrame: CGRect
    let progress: CGFloat
    let deformation: CaelestiaSurfaceDeformation
    let topDepth: CGFloat
    let topFillet: CGFloat
    let bottomFillet: CGFloat
    let contracting: Bool

    var currentFrame: CGRect {
        shellSurfaceCurrentFrame(
            attachment: attachment,
            finalFrame: finalFrame,
            progress: progress,
            topDepth: topDepth,
            contracting: contracting
        )
    }
}

private func shellContourOpenings(for descriptor: ShellSurfaceDescriptor) -> [ShellContourOpening] {
    let motion = descriptor.motion
    let contourProgress = motion.contourProgress
    guard contourProgress > 0.000_1 else { return [] }
    // Dismissal hands the physical surface back to the resting frame during
    // its terminal opacity band. Release the border opening at that same
    // point, so the persistent contour is already underneath the receding
    // fill. Keeping it suppressed until progress reaches zero exposed the
    // plain frame colour for a few frames before the border was repainted.
    guard surfaceTerminalOpacity(presented: motion.presented, progress: contourProgress) >= 0.999 else {
        return []
    }
    var result = [ShellContourOpening(
        attachment: descriptor.attachment,
        finalFrame: descriptor.frame,
        progress: contourProgress,
        deformation: motion.deformation,
        topDepth: descriptor.topDepth,
        topFillet: motion.mergeTopFillet,
        bottomFillet: motion.mergeBottomFillet,
        contracting: !motion.presented
    )]
    if let outgoing = motion.morphFromAttachment {
        result.append(ShellContourOpening(
            attachment: outgoing,
            finalFrame: motion.morphFromFrame ?? descriptor.frame,
            progress: contourProgress,
            deformation: motion.deformation,
            topDepth: descriptor.topDepth,
            topFillet: motion.morphFromTopFillet,
            bottomFillet: motion.morphFromBottomFillet,
            contracting: !motion.presented
        ))
    }
    return result
}

private func shellRestingContourSegmentsPath(
    in rect: CGRect,
    topDepth: CGFloat,
    openings: [ShellContourOpening]
) -> Path {
    let inner = shellInnerRect(in: rect, topDepth: topDepth)
    guard inner.width > 0, inner.height > 0 else { return Path() }
    let radius = min(shellInnerRadius, inner.width / 2, inner.height / 2)
    let control = radius * 0.552_284_749_830_793_6
    var topExclusions = [ShellContourInterval]()
    var rightExclusions = [ShellContourInterval]()
    var bottomExclusions = [ShellContourInterval]()
    var leftExclusions = [ShellContourInterval]()
    var ownsTopLeft = false
    var ownsTopRight = false
    var ownsBottomRight = false
    var ownsBottomLeft = false

    for opening in openings {
        let current = opening.currentFrame
        guard current.width > 0.5, current.height > 0.5 else { continue }
        let touchesTop = current.minY <= inner.minY + 1
        let touchesBottom = current.maxY >= inner.maxY - 1
        let touchesLeft = current.minX <= inner.minX + 1
        let touchesRight = current.maxX >= inner.maxX - 1
        switch opening.attachment {
        case .top:
            appendShellContourInterval(
                &topExclusions, start: current.minX, end: current.maxX,
                lowerBound: inner.minX + radius, upperBound: inner.maxX - radius
            )
            if touchesLeft { ownsTopLeft = true }
            if touchesRight { ownsTopRight = true }
        case .bottom:
            appendShellContourInterval(
                &bottomExclusions, start: current.minX, end: current.maxX,
                lowerBound: inner.minX + radius, upperBound: inner.maxX - radius
            )
            if touchesLeft { ownsBottomLeft = true }
            if touchesRight { ownsBottomRight = true }
        case .left:
            appendShellContourInterval(
                &leftExclusions, start: current.minY, end: current.maxY,
                lowerBound: inner.minY + radius, upperBound: inner.maxY - radius
            )
            if touchesTop {
                ownsTopLeft = true
                appendShellContourInterval(
                    &topExclusions,
                    start: inner.minX,
                    end: current.maxX + max(0, opening.topFillet),
                    lowerBound: inner.minX + radius,
                    upperBound: inner.maxX - radius
                )
            }
            // A grounded left popout owns the lower shell corner as soon as
            // its reverse fillet reaches the rim, not only after the panel's
            // rectangular frame is within one point of it. During a calendar
            // -> Wi-Fi handoff the panel travels into the smoothing band
            // first; waiting for `touchesBottom` left the persistent corner
            // painted underneath the arriving curve for the last few frames.
            let bottomBridgeReachesRim = current.maxY + max(0, opening.bottomFillet)
                >= inner.maxY - 0.5
            if bottomBridgeReachesRim {
                ownsBottomLeft = true
                // The lower contour is removed through the outward-rotated
                // regular fillet's endpoint. The full-screen surface layer
                // owns the arc outside the panel envelope, so the shell
                // segment must begin after that same endpoint or a duplicate
                // line will show underneath the bridge.
                appendShellContourInterval(
                    &bottomExclusions,
                    start: inner.minX,
                    end: current.maxX + max(0, opening.bottomFillet),
                    lowerBound: inner.minX + radius,
                    upperBound: inner.maxX - radius
                )
            }
        case .right:
            // A right-attached sidebar can keep its full-height descriptor
            // alive while it is translating in from beyond the display. Do
            // not release the resting right rim merely because the hidden
            // frame's far edge is past it; the surface has to overlap the
            // rim before it owns that contour.
            guard current.minX <= inner.maxX + 1,
                  current.maxX >= inner.maxX - 1 else { break }
            appendShellContourInterval(
                &rightExclusions, start: current.minY, end: current.maxY,
                lowerBound: inner.minY + radius, upperBound: inner.maxY - radius
            )
            if touchesTop { ownsTopRight = true }
            if touchesBottom { ownsBottomRight = true }
        case .rightSidebar:
            // The sidebar covers the shell's top and bottom rims across its
            // body. Leave the rim visible only until the matching quarter
            // curve begins at the drawer's shell-facing edge; otherwise the
            // persistent shell stroke shows through as a second horizontal
            // line inside the panel.
            // During dismissal the panel's host can already be outside the
            // shell while this reverse shoulder still projects back into it.
            // Test the shoulder endpoint, not just the host's leading edge,
            // so the resting rim is not restored underneath a departing
            // curve. The shell-facing shoulder stays coupled to the live
            // expanding frame, keeping the last painted curve outside the
            // resting rim before the descriptor is detached.
            guard current.minX - surfaceMorphShoulder <= inner.maxX + 1,
                  current.maxX >= inner.maxX - 1 else { break }
            appendShellContourInterval(
                &rightExclusions, start: current.minY, end: current.maxY,
                lowerBound: inner.minY + radius, upperBound: inner.maxY - radius
            )
            if touchesTop {
                ownsTopRight = true
                appendShellContourInterval(
                    &topExclusions,
                    // The sidebar path starts its upper reverse curve at
                    // `current.minX`. Removing the rim an entire shoulder
                    // earlier leaves a gap between the resting top line and
                    // that curve; the lower shoulder is different because
                    // its endpoint genuinely projects outward.
                    start: current.minX,
                    end: current.maxX,
                    lowerBound: inner.minX + radius,
                    upperBound: inner.maxX - radius
                )
            }
            if touchesBottom {
                ownsBottomRight = true
                appendShellContourInterval(
                    &bottomExclusions,
                    // The footer now ends at the sidebar's own shell-facing
                    // edge, matching the mirrored upper shoulder. Remove
                    // the resting rim from that exact endpoint so the old
                    // stretched arc cannot remain underneath it.
                    start: current.minX,
                    end: current.maxX,
                    lowerBound: inner.minX + radius,
                    upperBound: inner.maxX - radius
                )
            }
        case .topRight:
            appendShellContourInterval(
                &topExclusions, start: current.minX, end: current.maxX,
                lowerBound: inner.minX + radius, upperBound: inner.maxX - radius
            )
            appendShellContourInterval(
                &rightExclusions, start: current.minY, end: current.maxY,
                lowerBound: inner.minY + radius, upperBound: inner.maxY - radius
            )
            if touchesTop && touchesRight { ownsTopRight = true }
        case .bottomLeft:
            appendShellContourInterval(
                &leftExclusions, start: current.minY, end: current.maxY,
                lowerBound: inner.minY + radius, upperBound: inner.maxY - radius
            )
            appendShellContourInterval(
                &bottomExclusions, start: current.minX, end: current.maxX,
                lowerBound: inner.minX + radius, upperBound: inner.maxX - radius
            )
            if touchesTop && touchesLeft { ownsTopLeft = true }
            if touchesBottom && touchesLeft { ownsBottomLeft = true }
        }
    }

    var path = Path()
    appendShellContourHorizontalSegments(
        &path, y: inner.minY, start: inner.minX + radius,
        end: inner.maxX - radius, excluding: topExclusions
    )
    if !ownsTopRight {
        path.move(to: CGPoint(x: inner.maxX - radius, y: inner.minY))
        path.addCurve(
            to: CGPoint(x: inner.maxX, y: inner.minY + radius),
            control1: CGPoint(x: inner.maxX - radius + control, y: inner.minY),
            control2: CGPoint(x: inner.maxX, y: inner.minY + radius - control)
        )
    }
    appendShellContourVerticalSegments(
        &path, x: inner.maxX, start: inner.minY + radius,
        end: inner.maxY - radius, excluding: rightExclusions
    )
    if !ownsBottomRight {
        path.move(to: CGPoint(x: inner.maxX, y: inner.maxY - radius))
        path.addCurve(
            to: CGPoint(x: inner.maxX - radius, y: inner.maxY),
            control1: CGPoint(x: inner.maxX, y: inner.maxY - radius + control),
            control2: CGPoint(x: inner.maxX - radius + control, y: inner.maxY)
        )
    }
    appendShellContourHorizontalSegments(
        &path, y: inner.maxY, start: inner.minX + radius,
        end: inner.maxX - radius, excluding: bottomExclusions
    )
    if !ownsBottomLeft {
        path.move(to: CGPoint(x: inner.minX + radius, y: inner.maxY))
        path.addCurve(
            to: CGPoint(x: inner.minX, y: inner.maxY - radius),
            control1: CGPoint(x: inner.minX + radius - control, y: inner.maxY),
            control2: CGPoint(x: inner.minX, y: inner.maxY - radius + control)
        )
    }
    appendShellContourVerticalSegments(
        &path, x: inner.minX, start: inner.minY + radius,
        end: inner.maxY - radius, excluding: leftExclusions
    )
    if !ownsTopLeft {
        path.move(to: CGPoint(x: inner.minX, y: inner.minY + radius))
        path.addCurve(
            to: CGPoint(x: inner.minX + radius, y: inner.minY),
            control1: CGPoint(x: inner.minX, y: inner.minY + radius - control),
            control2: CGPoint(x: inner.minX + radius - control, y: inner.minY)
        )
    }
    return path
}

private struct ShellContourCanvas: View {
    @ObservedObject var motion: ShellFrameMotionState
    let contourColor: Color
    let topDepth: CGFloat
    let rendersPrimaryAttachments: Bool

    var body: some View {
        GeometryReader { geometry in
            Canvas { context, size in
                let bounds = CGRect(origin: .zero, size: size)
                let allDescriptors = rendersPrimaryAttachments ? motion.surfaces : []
                let openings = allDescriptors.flatMap(shellContourOpenings(for:))
                let descriptors = allDescriptors
                let resting = shellRestingContourSegmentsPath(
                    in: bounds,
                    topDepth: topDepth,
                    openings: openings
                )
                // Keep the resting rim and the animated reverse curves in one
                // drawing surface. This was the stable contour path before
                // the persistent-fill overpaint experiment; it gives the
                // junctions one antialias owner instead of leaving a raster
                // gap between two separately composited layers.
                context.stroke(resting, with: .color(contourColor), style: ShellContourStyle.stroke)
                guard rendersPrimaryAttachments else { return }
                for descriptor in descriptors {
                    let motion = descriptor.motion
                    let terminalOpacity = surfaceTerminalOpacity(
                        presented: motion.presented,
                        progress: motion.contourProgress
                    )
                    let blend = notificationHandoffContourBlend(
                        raw: motion.contourAttachmentBlend,
                        from: motion.morphFromAttachment,
                        to: descriptor.attachment
                    )
                    let keepsCompactTopCurve = (
                        motion.preservesNotificationTopCurve
                            || motion.morphFromAttachment == .topRight
                    ) && descriptor.attachment == .rightSidebar
                    let preservedTopCurveStartY = keepsCompactTopCurve
                        ? motion.notificationTopCurveStartOffset
                        : nil
                    if let outgoing = motion.morphFromAttachment {
                        let outgoingPath = ShellSurfaceMorphShape(
                            attachment: outgoing,
                            // The outgoing compact contour keeps its own
                            // frame while the incoming sidebar grows. Using
                            // descriptor.frame here stretches that old
                            // top-right border across the sidebar and is the
                            // one-frame jump into the shell seen at handoff.
                            finalFrame: motion.morphFromFrame ?? descriptor.frame,
                            radius: descriptor.radius,
                            outlineOnly: true,
                            // A side-attached surface owns its lower
                            // attachment shoulder. Suppressing it here leaves
                            // the shell's straight inner rail seam visible
                            // below media/calendar/active-app surfaces even
                            // though the local surface shape already carries
                            // the matching curve. Bottom-left remains the
                            // special composite surface whose contour owns a
                            // different seam.
                            omitTrailingAttachmentShoulder: outgoing == .bottomLeft,
                            mergeTopFillet: motion.morphFromTopFillet,
                            mergeBottomFillet: motion.morphFromBottomFillet,
                            progress: motion.contourProgress,
                            deformation: motion.contourDeformation(for: outgoing),
                            topDepth: descriptor.topDepth,
                            contracting: !motion.presented,
                            // Keep the outgoing compact curve in this path
                            // too. The incoming sidebar carries the exact
                            // same screen-space curve below, so the two
                            // contours can crossfade without a separate
                            // floating curve layer.
                            omitTopReverseShoulder: false,
                            preservedTopCurveStartY: nil
                        ).path(in: bounds)
                        context.stroke(
                            outgoingPath,
                            with: .color(contourColor.opacity(terminalOpacity * (1 - blend))),
                            style: ShellContourStyle.stroke
                        )
                    }
                    let incomingPath = ShellSurfaceMorphShape(
                        attachment: descriptor.attachment,
                        finalFrame: descriptor.frame,
                        radius: descriptor.radius,
                        outlineOnly: true,
                        // Keep the full lower side-attachment arc in the
                        // shared contour. `.left` maps the canonical trailing
                        // shoulder to the screen's lower junction; omitting
                        // it makes the shell border continue straight past
                        // the popout's bottom edge.
                        omitTrailingAttachmentShoulder: descriptor.attachment == .bottomLeft,
                        mergeTopFillet: motion.mergeTopFillet,
                        mergeBottomFillet: motion.mergeBottomFillet,
                        progress: motion.contourProgress,
                        deformation: motion.contourDeformation(for: descriptor.attachment),
                        topDepth: descriptor.topDepth,
                        contracting: !motion.presented,
                        omitTopReverseShoulder: keepsCompactTopCurve,
                        preservedTopCurveStartY: preservedTopCurveStartY
                    ).path(in: bounds)
                    context.stroke(
                        incomingPath,
                        with: .color(contourColor.opacity(terminalOpacity * blend)),
                        style: ShellContourStyle.stroke
                    )
                }
            }
        }
    }
}

// Opaque shell material is deliberately separate from the contour. Content
// panels may sit above this layer without ever clipping or recolouring a seam.
private struct ShellSurfaceFillLayer: View {
    let descriptor: ShellSurfaceDescriptor
    let frameColor: Color
    @ObservedObject var motion: SurfaceMotionState

    init(descriptor: ShellSurfaceDescriptor, frameColor: Color) {
        self.descriptor = descriptor
        self.frameColor = frameColor
        self.motion = descriptor.motion
    }

    var body: some View {
        let terminalOpacity = surfaceTerminalOpacity(
            presented: motion.presented,
            progress: motion.contourProgress
        )
        let blend = notificationHandoffContourBlend(
            raw: motion.contourAttachmentBlend,
            from: motion.morphFromAttachment,
            to: descriptor.attachment
        )
        let keepsCompactTopCurve = (
            motion.preservesNotificationTopCurve
                || motion.morphFromAttachment == .topRight
        ) && descriptor.attachment == .rightSidebar
        let preservedTopCurveStartY = keepsCompactTopCurve
            ? motion.notificationTopCurveStartOffset
            : nil
        return ZStack {
            if let from = motion.morphFromAttachment {
                ShellSurfaceMorphShape(
                    attachment: from,
                    finalFrame: motion.morphFromFrame ?? descriptor.frame,
                    radius: descriptor.radius,
                    mergeTopFillet: motion.morphFromTopFillet,
                    mergeBottomFillet: motion.morphFromBottomFillet,
                    progress: motion.contourProgress,
                    deformation: motion.contourDeformation(for: from),
                    topDepth: descriptor.topDepth,
                    contracting: !motion.presented
                )
                .fill(frameColor)
                .opacity(terminalOpacity * (1 - blend))
            }
            // The opaque fill is what actually makes a merged surface read as
            // continuous with the rim, so it has to use the same merged
            // silhouette the content mask does -- otherwise the fill would
            // still round away from the rim underneath a merged mask.
            ShellSurfaceMorphShape(
                attachment: descriptor.attachment,
                finalFrame: descriptor.frame,
                radius: descriptor.radius,
                mergeTopFillet: motion.mergeTopFillet,
                mergeBottomFillet: motion.mergeBottomFillet,
                progress: motion.contourProgress,
                deformation: motion.contourDeformation(for: descriptor.attachment),
                topDepth: descriptor.topDepth,
                contracting: !motion.presented,
                omitTopReverseShoulder: keepsCompactTopCurve,
                preservedTopCurveStartY: preservedTopCurveStartY
            )
            .fill(frameColor)
            .opacity(terminalOpacity * blend)
        }
    }
}

private struct ShellFrameFillOverlay: View {
    @ObservedObject var palette: ShellPalettePresentation
    @ObservedObject var motion: ShellFrameMotionState
    let topDepth: CGFloat
    let rendersPrimaryAttachments: Bool
    var body: some View {
        let frameColor = palette.palette.tokens.frame
        GeometryReader { _ in
            ZStack {
                UnifiedShellFrame(topDepth: topDepth)
                    .fill(
                        frameColor.opacity(shellMaterialOpacity),
                        style: FillStyle(eoFill: true)
                    )
                if rendersPrimaryAttachments {
                    ForEach(motion.surfaces) { descriptor in
                        ShellSurfaceFillLayer(
                            descriptor: descriptor,
                            frameColor: frameColor.opacity(shellMaterialOpacity)
                        )
                    }
                }
            }
            .compositingGroup()
        }
        .ignoresSafeArea()
        .animation(ShellMotion.palette.animation, value: palette.palette)
    }
}

private struct ShellFrameContourOverlay: View {
    @ObservedObject var palette: ShellPalettePresentation
    @ObservedObject var motion: ShellFrameMotionState
    @ObservedObject var border: ShellBorderPresentation
    let topDepth: CGFloat
    let rendersPrimaryAttachments: Bool
    var body: some View {
        Group {
            if border.enabled {
                let contourColor = palette.palette.tokens.accent.opacity(0.88)
                ShellContourCanvas(
                    motion: motion,
                    contourColor: contourColor,
                    topDepth: topDepth,
                    rendersPrimaryAttachments: rendersPrimaryAttachments
                )
            } else {
                Color.clear
            }
        }
        .ignoresSafeArea()
        .animation(ShellMotion.palette.animation, value: palette.palette)
    }
}

private struct MediaNextItem: Equatable {
    var title: String
    var artist: String
    var album: String
    var kind: String
    var url: String

    init(title: String, artist: String, album: String, kind: String, url: String = "") {
        self.title = title
        self.artist = artist
        self.album = album
        self.kind = kind
        self.url = url
    }
}

private typealias SpotifyNextTrack = MediaNextItem

private enum CinemaPresentation: String, CaseIterable, Sendable {
    case fit, wide, scope, fill, stretch

    var title: String {
        switch self {
        case .fit: return "FIT"
        case .wide: return "WIDE"
        case .scope: return "CINEMASCOPE"
        case .fill: return "FILL"
        case .stretch: return "STRETCH"
        }
    }

    var next: CinemaPresentation {
        let values = Self.allCases
        guard let index = values.firstIndex(of: self) else { return .wide }
        return values[(index + 1) % values.count]
    }
}

private struct CinemaCommandResult: Sendable {
    let ok: Bool
    let enabled: Bool
    let presentation: CinemaPresentation?
    let opaque: Bool
    let reason: String
    let detail: String

    static func decode(_ raw: String) -> CinemaCommandResult {
        guard let data = raw.data(using: .utf8), data.count <= 16 * 1_024,
              // macpp:silent-ok an unavailable helper payload is handled as an invalid response.
              let payload = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return CinemaCommandResult(
                ok: false, enabled: false, presentation: nil, opaque: false,
                reason: "invalid-helper-response", detail: "Cinema helper returned no usable state"
            )
        }
        let presentation = (payload["presentation"] as? String).flatMap(CinemaPresentation.init(rawValue:))
        return CinemaCommandResult(
            ok: payload["ok"] as? Bool ?? false,
            enabled: payload["enabled"] as? Bool ?? false,
            presentation: presentation,
            opaque: payload["opaque"] as? Bool ?? false,
            reason: (payload["reason"] as? String ?? "cinema-command-failed").prefix(120).description,
            detail: (payload["detail"] as? String ?? "").prefix(240).description
        )
    }
}

private func runCinemaCommand(_ action: String) -> CinemaCommandResult {
    _ = action
    return CinemaCommandResult(
        ok: false,
        enabled: false,
        presentation: nil,
        opaque: false,
        reason: "not-in-public-profile",
        detail: "Cinema automation is not included in this public profile"
    )
}

private struct MediaState: Equatable {
    var title = ""
    var artist = ""
    var album = ""
    var artworkURL = ""
    // Spotify rewrites one fixed file URL for every track.  A separate
    // revision prevents the artwork loader from mistaking a new cover for a
    // cache hit merely because the path stayed the same.
    var artworkRevision = ""
    var source = ""
    var device = ""
    var upNext: MediaNextItem? = nil
    var transcriptURL = ""
    var mediaURL = ""
    var playing = false
    var progress = 0.0
    var position = 0.0
    var duration = 0.0
    var durationKnown = false
    var isLive = false
}

/// The media producer intentionally stays provider-neutral.  The companion
/// surface still needs one small amount of provider knowledge: Spotify owns
/// the authenticated queue, while browser/non-Spotify playback can only use
/// metadata, captions, or a lyrics search as a fallback.
private enum MediaProvider: Equatable {
    case spotify
    case youtube
    case other

    static func resolve(_ media: MediaState) -> MediaProvider {
        let identity = "\(media.mediaURL) \(media.source) \(media.device)".lowercased()
        if identity.contains("spotify") { return .spotify }
        if identity.contains("youtube.com") || identity.contains("youtu.be") {
            return .youtube
        }
        return .other
    }

    var cacheKey: String {
        switch self {
        case .spotify: return "spotify"
        case .youtube: return "youtube"
        case .other: return "other"
        }
    }

    var label: String {
        switch self {
        case .spotify: return "SPOTIFY"
        case .youtube: return "YOUTUBE"
        case .other: return "MEDIA"
        }
    }
}

private enum SpotifyQueueStatus: Equatable {
    case unavailable
    case needsClientID
    case disconnected
    case authorizing
    case loading
    case ready
    case empty
    case error
}

/// Public builds keep provider-neutral media controls but omit account linking
/// and authenticated queue reads. This coordinator preserves the Shell's view
/// model contract without account authorization or token persistence.
@MainActor
private final class SpotifyQueueCoordinator {
    private(set) var status: SpotifyQueueStatus = .unavailable
    var onStatus: ((SpotifyQueueStatus) -> Void)?
    var onTrack: ((SpotifyNextTrack?) -> Void)?

    func refresh(for media: MediaState, force: Bool = false) {
        _ = media
        _ = force
        onTrack?(nil)
        setUnavailable()
    }

    private func setUnavailable() {
        guard status != .unavailable else { return }
        status = .unavailable
        onStatus?(.unavailable)
    }
}

private enum DisplayBrightness {
    typealias Getter = @convention(c) (CGDirectDisplayID, UnsafeMutablePointer<Float>) -> Int32
    typealias Setter = @convention(c) (CGDirectDisplayID, Float) -> Int32
    private static let handle = dlopen("/System/Library/PrivateFrameworks/DisplayServices.framework/DisplayServices", RTLD_NOW)
    private static let getter = handle.flatMap { dlsym($0, "DisplayServicesGetBrightness") }.map { unsafeBitCast($0, to: Getter.self) }
    private static let setter = handle.flatMap { dlsym($0, "DisplayServicesSetBrightness") }.map { unsafeBitCast($0, to: Setter.self) }
    static func read() -> Double? {
        guard let getter else { return nil }
        var value: Float = 0
        return getter(CGMainDisplayID(), &value) == 0 ? Double(value) : nil
    }
    static func write(_ value: Double) {
        _ = setter?(CGMainDisplayID(), Float(min(1, max(0, value))))
    }
}

private enum StorageCapacity {
    struct Snapshot {
        let usedFraction: Double
        let availableBytes: Int64
    }

    static func read() -> Snapshot? {
        let home = URL(fileURLWithPath: NSHomeDirectory(), isDirectory: true)
        let keys: Set<URLResourceKey> = [
            .volumeTotalCapacityKey,
            .volumeAvailableCapacityForImportantUsageKey,
            .volumeAvailableCapacityKey
        ]
        guard let values = try? home.resourceValues(forKeys: keys) else { return nil } // macpp:silent-ok unavailable volume statistics leave disk usage unknown
        let total = Int64(values.volumeTotalCapacity ?? 0)
        let available = values.volumeAvailableCapacityForImportantUsage
            ?? Int64(values.volumeAvailableCapacity ?? 0)
        guard total > 0, available >= 0 else { return nil }
        let fraction = 1 - (Double(min(total, available)) / Double(total))
        return Snapshot(usedFraction: min(1, max(0, fraction)), availableBytes: available)
    }
}

private struct SurfaceSnapshot: Sendable {
    var brightness: Double?
    var wifiOn = false
    var batteryPercent = 0
    var charging = false
    var cpu = "—"
    var memory = "—"
    var diskUsed = 0
    var performance = PerformanceSample()
    var processes: [LocalProcessSample] = []
    var workspaces: [WorkspaceInfo] = []
    var themeName = "MIDNIGHT BLUE"
    var topProcess = "—"

    static func capture() -> SurfaceSnapshot {

        let wifiEnabled = UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi")
        let wifiText = wifiEnabled ? command("networksetup -getairportpower en0") : "off"
        let batteryState = SystemBattery.read()
        let logicalCores = max(1, Int(command("sysctl -n hw.logicalcpu")) ?? 1)
        let cpuCommand = "ps -A -o %cpu= 2>/dev/null | awk -v c=\"\(logicalCores)\" '{s += $1} END {if (c < 1) c=1; printf \"%.2f\", s/(100*c)}'"
        let memoryCommand = "memory_pressure -Q 2>/dev/null | awk '/free percentage/ {gsub(/%/,\"\",$5); printf \"%.4f\", (100-$5)/100; exit}'"
        let cpuUse = Double(command(cpuCommand)) ?? 0
        let ramUse = Double(command(memoryCommand)) ?? 0
        let disk = Int(((StorageCapacity.read()?.usedFraction ?? 0) * 100).rounded())
        let metrics = PerformanceSample(
            cpuUse: min(1, max(0, cpuUse)),
            gpuUse: 0,
            ramUse: min(1, max(0, ramUse)),
            diskUse: Double(disk) / 100,
            cpuTemp: nil,
            gpuTemp: nil
        )
        let processes: [LocalProcessSample] = []
        let topProcess = command("ps -Ao %cpu=,comm= | sort -nr | head -1 | sed 's#^.*/##' | awk '{$1=$1;print}'")
        let workspaceData = workspaceSnapshot()
        let theme = ShellPalette.current.title
        return SurfaceSnapshot(
            brightness: DisplayBrightness.read(),
            wifiOn: wifiText.localizedCaseInsensitiveContains("on"),
            batteryPercent: batteryState?.percent ?? 0,
            charging: batteryState?.externalPower ?? false,
            cpu: "\(Int((metrics.cpuUse * 100).rounded()))%",
            memory: "\(Int((metrics.ramUse * 100).rounded()))%",
            diskUsed: disk,
            performance: metrics,
            processes: processes,
            workspaces: workspaceData,
            themeName: theme,
            topProcess: topProcess.isEmpty ? "—" : topProcess
        )
    }
    /// Also called on its own, far more often than a full snapshot, so the
    /// now-playing indicator follows a window moved between spaces promptly.
    static func workspaceSnapshot() -> [WorkspaceInfo] {
        guard let spaces = yabaiJSONArray(["-m", "query", "--spaces"], context: "spaces"),
              let windows = yabaiJSONArray(["-m", "query", "--windows"], context: "windows") else {
            return []
        }
        let names = macppWorkspaceNames
        let actual = spaces.prefix(CaelestiaParityTokens.Sizes.workspaceCount).enumerated().map { offset, space in
            let index = (space["index"] as? NSNumber)?.intValue ?? offset + 1
            let label = ((space["label"] as? String)?.isEmpty == false ? space["label"] as? String : nil)?.uppercased() ?? names[min(offset, names.count - 1)]
            let workspaceWindows = windows.compactMap { window -> WorkspaceWindow? in
                guard (window["space"] as? NSNumber)?.intValue == index,
                      let windowID = (window["id"] as? NSNumber)?.intValue,
                      let app = window["app"] as? String, !app.isEmpty else { return nil }
                return WorkspaceWindow(
                    id: windowID,
                    app: app,
                    title: (window["title"] as? String) ?? ""
                )
            }
            let apps = workspaceWindows.map(\.app).reduce(into: [String]()) { result, app in
                if !result.contains(app) { result.append(app) }
            }
            // Deliberately not truncated here. Every display site already
            // applies its own `.prefix` for layout, but this list is also what
            // the now-playing check searches -- so capping it at four meant a
            // fifth app in a busy space was invisible to that check and could
            // never light the indicator, no matter how correct the audio
            // detection was.
            return WorkspaceInfo(
                id: index,
                name: label,
                apps: apps,
                windows: workspaceWindows,
                available: true
            )
        }
        // Keep five stable workspace affordances visible. A Mac can be
        // configured with fewer yabai spaces, so retain the same rail rhythm
        // and make unavailable slots explicit until the provider publishes a
        // matching space.
        let actualByID = Dictionary(uniqueKeysWithValues: actual.map { ($0.id, $0) })
        return (1...CaelestiaParityTokens.Sizes.workspaceCount).map { index in
            actualByID[index] ?? WorkspaceInfo(
                id: index,
                name: names[index - 1],
                apps: [],
                windows: [],
                available: false
            )
        }
    }

    /// The app rail is deliberately narrower than the workspace inventory:
    /// it accepts standard, AX-backed windows plus a tightly-scoped fallback
    /// for real root windows from apps such as Steam whose helper process does
    /// not publish AX role metadata.
    static func appRailWindowSnapshot() -> [AppRailWindowSnapshot] {
        guard let windows = yabaiJSONArray(["-m", "query", "--windows"], context: "app-rail-windows") else {
            return []
        }
        return windows.compactMap { window in
            let role = window["role"] as? String ?? ""
            let subrole = window["subrole"] as? String ?? ""
            let hasAXReference = (window["has-ax-reference"] as? NSNumber)?.boolValue ?? false
            let title = window["title"] as? String ?? ""
            let isMinimized = (window["is-minimized"] as? NSNumber)?.boolValue ?? false
            let frame = window["frame"] as? [String: Any]
            let frameWidth = (frame?["w"] as? NSNumber)?.doubleValue ?? 0
            let frameHeight = (frame?["h"] as? NSNumber)?.doubleValue ?? 0
            let hasStandardAXMetadata = role == "AXWindow"
                && subrole == "AXStandardWindow"
                && hasAXReference
            // A minimized sheet/dialog can be the only remaining window for
            // an app. Keep it in the inventory even though its subrole is not
            // AXStandardWindow; the app-level process merge below handles the
            // no-window case separately.
            let hasMinimizedAXMetadata = role == "AXWindow"
                && hasAXReference
                && isMinimized
            let isRootWindow = (window["root-window"] as? NSNumber)?.boolValue ?? false
            let isNormalWindow = (window["layer"] as? String ?? "") == "normal"
                && (window["level"] as? NSNumber)?.intValue == 0
            let usesFallbackWindowMetadata = role.isEmpty
                && subrole.isEmpty
                && isRootWindow
                && isNormalWindow
                && frameWidth > 0
                && frameHeight > 0
                && !title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            guard hasStandardAXMetadata || hasMinimizedAXMetadata || usesFallbackWindowMetadata,
                  let id = (window["id"] as? NSNumber)?.intValue,
                  let pid = (window["pid"] as? NSNumber)?.int32Value,
                  let appName = window["app"] as? String,
                  !appName.isEmpty else { return nil }
            return AppRailWindowSnapshot(
                id: id,
                pid: pid,
                appName: appName,
                title: title,
                space: (window["space"] as? NSNumber)?.intValue ?? 0,
                isMinimized: isMinimized,
                usesFallbackWindowMetadata: usesFallbackWindowMetadata
            )
        }
    }

    private static func yabaiJSONArray(
        _ arguments: [String],
        context: String
    ) -> [[String: Any]]? {
        let process = Process()
        let output = Pipe()
        let errors = Pipe()
        guard let yabaiExecutable = macppYabaiExecutableURL() else { return nil }
        process.executableURL = yabaiExecutable
        process.arguments = arguments
        process.standardOutput = output
        process.standardError = errors
        do {
            try process.run()
        } catch {
            MacPlusPlusBoundaryLog.record(
                "workspace \(context) query could not launch: \(error)",
                key: "workspace-query-\(context)",
                minimumInterval: 60
            )
            return nil
        }
        let data = output.fileHandleForReading.readDataToEndOfFile()
        let errorData = errors.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        guard process.terminationStatus == 0 else {
            let detail = String(data: errorData, encoding: .utf8)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            MacPlusPlusBoundaryLog.record(
                "workspace \(context) query failed status=\(process.terminationStatus)"
                    + (detail.isEmpty ? "" : " stderr=\(detail)"),
                key: "workspace-query-\(context)",
                minimumInterval: 60
            )
            return nil
        }
        do {
            guard let value = try JSONSerialization.jsonObject(with: data) as? [[String: Any]] else {
                throw NSError(
                    domain: "MacPlusPlusShell.Workspace",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "top-level JSON is not an array"]
                )
            }
            return value
        } catch {
            MacPlusPlusBoundaryLog.record(
                "workspace \(context) query returned invalid JSON: \(error)",
                key: "workspace-query-\(context)",
                minimumInterval: 60
            )
            return nil
        }
    }
    private static func command(_ command: String) -> String {
        let pipe = Pipe(); let process = Process()
        process.executableURL = URL(fileURLWithPath: "/bin/zsh"); process.arguments = ["-lc", command]
        process.standardOutput = pipe; process.standardError = FileHandle.nullDevice
        guard (try? process.run()) != nil else { return "" } // macpp:silent-ok optional command failure returns an empty value to its caller
        process.waitUntilExit()
        return String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    }
}

@MainActor final class ShellBorderPresentation: ObservableObject {
    @Published var enabled: Bool

    init(enabled: Bool) {
        self.enabled = enabled
    }
}

@MainActor private final class ShellPalettePresentation: ObservableObject {
    @Published var palette: ShellPalette

    init(_ palette: ShellPalette = .current) {
        self.palette = palette
    }
}

/// A detached, Sendable copy of one shared-memory audio frame. The shell used
/// to open/mmap/decode the 16 KB transport on the main actor every 100 ms. A
/// transient producer restart or a contended seqlock could then hold up the
/// same run loop that draws the visualizer and makes the bars appear frozen.
private struct ShellAudioFrame: Sendable {
    let available: Bool
    let producerLive: Bool
    let active: Bool
    let tempoLive: Bool
    let bpm: Int
    let candidates: [Double]

    static let unavailable = ShellAudioFrame(
        available: false,
        producerLive: false,
        active: false,
        tempoLive: false,
        bpm: 0,
        candidates: []
    )
}

private func captureShellAudioFrame() -> ShellAudioFrame {
    guard let json = MacPlusPlusAudioSharedMemory.shared.readJSON() else {
        return .unavailable
    }

    let published = (json["timestamp"] as? NSNumber)?.doubleValue ?? 0
    let age = Date().timeIntervalSince1970 - published
    let producerLive = published > 0 && age >= -1 && age < 2.5
    let signal = (json["signal"] as? NSNumber)?.doubleValue ?? 0
    let hardware: [Double] = {
        if let values = json["spectrum_hardware"] as? [Double] { return values }
        if let values = json["spectrum_hardware"] as? [NSNumber] { return values.map(\.doubleValue) }
        return []
    }()
    let hardwarePeak = hardware.max() ?? 0
    // The hardware FFT is the signal used by the lighting consumers. The
    // older `signal` scalar is intentionally conservative and can remain
    // below its threshold for quiet material even while the normalized bands
    // are moving, which made the shell report an idle feed and flatten its
    // visualizer. Treat either the producer's active bit or a real hardware
    // band as evidence of live audio.
    let active = producerLive
        && ((json["active"] as? NSNumber)?.boolValue == true
            || signal > 0.008
            || hardwarePeak > 0.008)
    // Prefer the hardware spectrum when it contains real energy. During a
    // tap reattach there can be a fresh frame whose hardware array is still
    // all zero while the compact/smoothed stream has already recovered; using
    // that zero-filled array as an unconditional preference made the Shell
    // and desktop layer look frozen even though the producer was live.
    let fallbackKeys = ["spectrum_smooth", "spectrum", "bars", "bands", "levels"]
    let preferredKeys = hardwarePeak > 0.0005
        ? ["spectrum_hardware"] + fallbackKeys
        : fallbackKeys + ["spectrum_hardware"]
    let candidates: [Double] = preferredKeys.compactMap { key in
        if let values = json[key] as? [Double] { return values }
        if let values = json[key] as? [NSNumber] { return values.map(\.doubleValue) }
        return nil
    }.first ?? []
    let tempoLive = producerLive && (json["tempo_live"] as? NSNumber)?.boolValue == true
    let bpm = (json["display_bpm"] as? NSNumber)?.intValue
        ?? (json["bpm"] as? NSNumber)?.intValue ?? 0

    return ShellAudioFrame(
        available: true,
        producerLive: producerLive,
        active: active,
        tempoLive: tempoLive,
        bpm: bpm,
        candidates: candidates
    )
}

private func macppSystemUptimeText() -> String {
    let seconds = max(0, Int(ProcessInfo.processInfo.systemUptime))
    return "\(seconds / 3600)H \((seconds % 3600) / 60)M"
}

