        let version = ProcessInfo.processInfo.operatingSystemVersion
        // macOS marketing names track the major version from 11 onward.
        let names: [Int: String] = [
            11: "Big Sur", 12: "Monterey", 13: "Ventura", 14: "Sonoma",
            15: "Sequoia", 16: "Tahoe", 26: "Tahoe"
        ]
        let number = version.minorVersion == 0
            ? "\(version.majorVersion)"
            : "\(version.majorVersion).\(version.minorVersion)"
        if let name = names[version.majorVersion] { return "\(name) \(number)" }
        return "macOS \(number)"
