    init(liveData: Bool = true) {
        spotifyNextTrack = nil
        spotifyQueueStatus = spotifyQueueCoordinator.status
        spotifyQueueCoordinator.onTrack = { [weak self] next in
            self?.spotifyNextTrack = next
        }
        spotifyQueueCoordinator.onStatus = { [weak self] status in
            self?.spotifyQueueStatus = status
        }
        if liveData {
            // The last-known SSID is only a reconnect hint. It is not live
            // association state: route(8) can continue to report en0 after a
            // disconnect, and displaying this cache before the radio confirms
            // it made the popout claim the Mac was connected to a stale AP.
            connectedNetwork = ""
            wifiConnected = false
            // Do not seed the nearby list from cached or preferred networks:
            // those are remembered profiles, not radios currently in range.
            knownNetworks = []
            locationProvider.onCoordinate = { [weak self] latitude, longitude in
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.weatherLatitude = latitude
                    self.weatherLongitude = longitude
                    // Replace an IP-derived first reading as soon as a real
                    // Core Location fix arrives, without starting another
                    // request loop from inside the delegate callback.
                    self.refreshWeather(force: true, requestLocation: false)
                }
            }
            locationProvider.onAuthorizationChange = { [weak self] in
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    // CoreWLAN may expose the current SSID before macOS has
                    // granted location-backed nearby-name access. Re-run the
                    // live scan when that authorization transition completes
                    // instead of leaving the card with a single remembered
                    // connection forever.
                    self.lastConnectivityRefresh = .distantPast
                    self.refreshConnectivity(force: true, includeNearbyInventory: true)
                }
            }
            loadProfilePhoto()
            // Re-apply the saved palette to both peripheral drivers after a
            // login or shell restart; Work Mode's baseline must not overwrite
            // the user's selected profile.
            companionLyrics.setEnabled(!batterySaverEnabled)
            applyCMatrixScreensaverPauseState()
            // The activation observer only fires when another app activates
            // after the shell starts.  On a fresh login the current app may
            // already be frontmost, leaving the dashboard's ACTIVE WINDOW
            // card with its default PID and zero CPU/RAM values forever.
            refreshFrontApp()
            refreshAppRailApplications(force: true)
            refresh(); scheduleTimer(interval: preferredTimerInterval()); scheduleOutputAudioPoll(); scheduleWorkspaceFocusPoll()
            refreshCinemaStatus(force: true)
            SystemOutputAudio.observeChanges { [weak self] in
                Task { @MainActor in self?.refreshOutputAudio() }
            }
            SystemInputAudio.observeChanges { [weak self] in
                Task { @MainActor in self?.refreshInputAudio() }
            }
            refreshFocusAvailability(force: true)
            let activationObserver = NSWorkspace.shared.notificationCenter.addObserver(
                forName: NSWorkspace.didActivateApplicationNotification,
                object: nil,
                queue: .main
            ) { [weak self] note in
                guard let application = note.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication else { return }
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.updateFrontApp(application)
                    // Cinema can be changed by the CLI/Raycast while Shell
                    // remains alive. App activation is a natural, bounded
                    // reconciliation point and this call is internally
                    // throttled so ordinary app switching stays cheap.
                    self.refreshCinemaStatus()
                    // An app activation is also the common path for a new
                    // window appearing in the visible space. Refresh the
                    // compact workspace manager immediately so an open rail
                    // popover can resize from the new snapshot instead of
                    // waiting for its five-second background poll.
                    self.refreshWorkspaceApps()
                    self.refreshAppRailApplications(force: true)
                    // Activation is delivered before many applications finish
                    // publishing their first window. A single immediate
                    // query can therefore see the old list and never receive
                    // another activation event, leaving the open popover
                    // compressed until hover recreates it. Keep a short,
                    // bounded settle ladder instead of relying on a later
                    // hover or the five-second idle refresh. The later two
                    // samples matter for Electron/WebKit apps whose first
                    // window is published after the process activation
                    // notification. The generation fence in
                    // `refreshWorkspaceApps()` makes the overlapping reads
                    // last-writer-safe.
                    for delay in [0.15, 0.35, 0.75, 1.35, 2.25] {
                        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                            self?.refreshWorkspaceApps()
                            self?.refreshAppRailApplications(force: true)
                        }
                    }
                }
            }
            workspaceObservers.append(activationObserver)
            Task { @MainActor [weak self] in self?.refreshSurface() }
            // Radio inventories are user-started from the Network and Devices
            // pages. Opening the Shell does not scan nearby networks/devices.
        }
    }
    deinit {
        timer?.invalidate(); surfaceTimer?.invalidate(); frontAppResourceTimer?.invalidate(); workspaceFocusPollTimer?.invalidate(); outputAudioPollTimer?.invalidate()
        frontAppResourceWarmupTask?.cancel()
        connectivityRefreshTask?.cancel(); bluetoothRefreshTask?.cancel(); wifiToggleTask?.cancel()
        weatherTask?.cancel(); workspaceAppsRefreshTask?.cancel(); workspaceFocusRefreshTask?.cancel()
        surfaceRefreshWorkItem?.cancel()
        workspaceObservers.forEach { NSWorkspace.shared.notificationCenter.removeObserver($0) }
    }
    private func scheduleTimer(interval: TimeInterval) {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: interval, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                let savedBatteryMode = UserDefaults.standard.bool(forKey: "macppBatterySaver")
                if savedBatteryMode != self.batterySaverEnabled {
                    self.setBatterySaver(savedBatteryMode, persist: false)
                }
                self.audioTick += 1
                self.requestAudioSample()
                if self.audioWasActive && self.reactiveRequested { self.phase += 0.85 }
                // Idle/Battery timers already *are* the metadata cadence, so
                // run on every one of their ticks. Rechecking for a strict
                // 1.000s elapsed interval made normal timer jitter skip every
                // other callback (about 1.05s, then 1.95s). Only the 0.1s
                // reactive visualizer path needs this one-second throttle.
                if interval >= 1.0 || Date().timeIntervalSince(self.lastMetadataRefresh) >= 1 {
                    self.lastMetadataRefresh = Date()
                    let current = Date()
                    if Calendar.current.component(.minute, from: current) != Calendar.current.component(.minute, from: self.now) {
                        var transaction = Transaction()
                        transaction.disablesAnimations = true
                        withTransaction(transaction) { self.now = current }
                    }
                    self.readMedia()
                    self.spotifyQueueCoordinator.refresh(for: self.media)
                    // Which apps are producing audio changes the moment
                    // playback starts or stops, so it belongs on the one
                    // second cadence rather than in refreshSurface -- which at
                    // rest runs only every five minutes, so the indicator was
                    // reading a set sampled long before you pressed play.
                    // This is two CoreAudio property reads per audio client
                    // and spawns nothing.
                    self.readAudioOutputApps()
                    self.readDownloadingApps()
                    self.writeNowPlayingDebug()
                    // NSWorkspace's active-space notification is normally
                    // immediate, but it can be dropped while WindowServer or
                    // yabai is restarting. Reconcile the one-field focus
                    // state on the normal metadata cadence as a cheap
                    // backstop. The active dot must not wait for the five-
                    // minute full surface snapshot.
                    self.refreshWorkspace()
                    // Space membership changes only when a window is moved,
                    // but it was riding the same five minute refresh -- so
                    // moving an app to another space left the indicator on the
                    // old one until that elapsed. Cheaper than a full surface
                    // refresh: two yabai queries, no CPU/RAM/brightness probes.
                    if !self.batterySaverEnabled,
                       Date().timeIntervalSince(self.lastWorkspaceAppsRefresh) >= 5 {
                        self.lastWorkspaceAppsRefresh = Date()
                        self.refreshWorkspaceApps()
                    }
                    // The compact app rail needs to notice a newly-opened or
                    // closed real window quickly, but its single yabai query is
                    // still throttled internally to keep the idle shell cheap.
                    if !self.batterySaverEnabled { self.refreshAppRailApplications() }
                    // Battery percentage changes slowly, but SystemPowerIn is
                    // the live wall draw shown in the battery popout. Keep
                    // that readout fresh without waiting for the slower
                    // metadata cadence used by the rest of the shell.
                    if Date().timeIntervalSince(self.lastBatteryRefresh) >= 5 {
                        self.lastBatteryRefresh = Date()
                        self.readBattery()
                    }
                    if Date().timeIntervalSince(self.lastSystemRefresh) >= 60 {
                        self.lastSystemRefresh = Date()
                        self.readSystem()
                    }
                    let now = Date()
                    if now.timeIntervalSince(self.lastConnectivityBackgroundPoll) >= connectivityBackgroundPollInterval {
                        self.lastConnectivityBackgroundPoll = now
                        self.refreshConnectivity(force: true)
                    }
                    // Heavy CPU/RAM/yabai probes stay live while a surface is
                    // visible.  At rest, a five-minute status refresh is enough
                    // for battery/workspace state and avoids periodic CPU spikes.
                    if !self.batterySaverEnabled,
                       Date().timeIntervalSince(self.lastSurfaceRefresh) >= 300 { self.refreshSurface() }
                }
            }
        }
        // Reactive audio is sampled on a 100 ms cadence. Letting the run loop
        // coalesce that timer by 15 ms made the visual frame arrive on
        // different sides of a 240 Hz refresh boundary, which read as a tiny
        // hitch even though the animation curve was unchanged. Keep the idle
        // timer coalescing, but make the live cadence tight.
        timer?.tolerance = interval <= 0.2 ? 0.005 : interval * 0.15
        if let timer { RunLoop.main.add(timer, forMode: .common) }
    }

    /// CoreAudio listeners cover ordinary hardware/app changes, but a route
    /// hand-off can replace the selected device before the old device's
    /// listener is detached. Keep a small fallback poll so a keyboard key,
    /// hardware key event, monitor knob, or another app always reaches every
    /// slider even across that hand-off. The read is two HAL property reads;
    /// the model only publishes when the value actually changed.
    private func scheduleOutputAudioPoll() {
        outputAudioPollTimer?.invalidate()
        let timer = Timer(timeInterval: 0.20, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.refreshOutputAudio() }
        }
        timer.tolerance = 0.03
        RunLoop.main.add(timer, forMode: .common)
        outputAudioPollTimer = timer
    }

    /// Space-change notifications are the fast path, but WindowServer can
    /// occasionally omit one while yabai or the Dock is restarting. Keep the
    /// fallback short enough that the rail never feels a beat behind, while
    /// using only the single focused-space query rather than the full surface
    /// snapshot.
    private func scheduleWorkspaceFocusPoll() {
        workspaceFocusPollTimer?.invalidate()
        let timer = Timer(timeInterval: 0.12, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.refreshWorkspace() }
        }
        timer.tolerance = 0.015
        RunLoop.main.add(timer, forMode: .common)
        workspaceFocusPollTimer = timer
    }

    private func requestOutputAudioFallbackRead() {
        let now = Date()
        guard !outputAudioFallbackReadInFlight,
              now.timeIntervalSince(lastOutputAudioFallbackRead) >= 0.8 else { return }
        outputAudioFallbackReadInFlight = true
        lastOutputAudioFallbackRead = now
        Task.detached(priority: .utility) {
            let state = SystemOutputAudio.readSystemVolume()
            await MainActor.run { [weak self] in
                guard let self else { return }
                self.outputAudioFallbackReadInFlight = false
                guard let state else { return }
                let nextVolume = min(1, max(0, state.volume))
                if abs(self.volume - nextVolume) > 0.0001 { self.volume = nextVolume }
                if self.muted != state.muted { self.muted = state.muted }
            }
        }
    }
    func refresh() {
        readMedia()
        // Keep the queue coordinator's eight-second throttle intact. This
        // refresh is also used by visible-surface redraws, which can happen
        // every couple of seconds and must not turn into API polling.
        spotifyQueueCoordinator.refresh(for: media)
        requestAudioSample(); readSystem(); readAudioOutputApps()
    }

    /// Just the space -> apps mapping, without the rest of the surface probe.
    func refreshWorkspaceApps() {
        guard workspaceAppsRefreshTask == nil else {
            // Detached Process reads cannot be interrupted reliably when the
            // caller's Task is cancelled. Keep one read in flight and fold
            // later requests into one follow-up instead of launching a pile
            // of yabai queries during a Space transition.
            workspaceAppsRefreshPending = true
            return
        }
        workspaceRefreshGeneration &+= 1
        let generation = workspaceRefreshGeneration
        workspaceAppsRefreshTask = Task { [weak self] in
            let spaces = await Task.detached(priority: .utility) {
                SurfaceSnapshot.workspaceSnapshot()
            }.value
            guard let self, !Task.isCancelled,
                  generation == self.workspaceRefreshGeneration else { return }
            self.workspaceAppsRefreshTask = nil
            if !spaces.isEmpty, spaces != self.workspaces {
                // The rail popover's AppKit host is resized from this same
                // model update. Animating the row insertion inside the old
                // frame made SwiftUI compress the list while the host was
                // catching up, which is the deformation seen when a window
                // opens under an already visible workspace list. Publish the
                // snapshot atomically; the host resize observer supplies the
                // only geometry transition.
                self.workspaces = spaces
            }
            if self.workspaceAppsRefreshPending {
                self.workspaceAppsRefreshPending = false
                self.refreshWorkspaceApps()
            }
        }
    }

    /// Refresh the compact app rail from live window rows plus regular running
    /// applications. Background-only helpers therefore never become icons,
    /// while an app with minimized windows or no open window remains reachable.
    func refreshAppRailApplications(force: Bool = false) {
        guard appRailRefreshEnabled else { return }
        let now = Date()
        guard force || now.timeIntervalSince(lastAppRailRefresh) >= 2 else { return }
        lastAppRailRefresh = now
        appRailRefreshGeneration &+= 1
        let generation = appRailRefreshGeneration
        Task { [weak self] in
            let snapshots = await Task.detached(priority: .utility) {
                SurfaceSnapshot.appRailWindowSnapshot()
            }.value
            guard let self, self.appRailRefreshEnabled, generation == self.appRailRefreshGeneration else { return }

            let grouped = Dictionary(grouping: snapshots) { snapshot in
                guard let rawApplication = NSRunningApplication(processIdentifier: snapshot.pid) else {
                    return snapshot.pid
                }
                return appRailOwnerApplication(for: rawApplication).processIdentifier
            }
            let windowedApplications = grouped.compactMap { pid, rows -> AppRailApplication? in
                guard let application = NSRunningApplication(processIdentifier: pid),
                      !application.isTerminated,
                      !appRailIsInternalApplication(application),
                      (application.activationPolicy == .regular
                        || rows.contains(where: \.usesFallbackWindowMetadata)) else { return nil }
                let bundleIdentifier = application.bundleIdentifier ?? ""
                let windows = rows
                    .sorted { $0.id < $1.id }
                    .map {
                        AppRailWindow(
                            id: $0.id,
                            title: $0.title,
                            space: $0.space,
                            isMinimized: $0.isMinimized
                        )
                    }
                guard !windows.isEmpty else { return nil }
                return AppRailApplication(
                    id: pid,
                    name: application.localizedName ?? rows[0].appName,
                    bundleIdentifier: bundleIdentifier,
                    bundlePath: application.bundleURL?.path ?? "",
                    windows: windows
                )
            }
            let windowedPIDs = Set(windowedApplications.map(\.id))
            let windowlessApplications = NSWorkspace.shared.runningApplications.compactMap { application -> AppRailApplication? in
                guard application.activationPolicy == .regular,
                      !application.isTerminated,
                      !windowedPIDs.contains(application.processIdentifier),
                      !appRailIsInternalApplication(application),
                      let name = application.localizedName?.trimmingCharacters(in: .whitespacesAndNewlines),
                      !name.isEmpty else { return nil }
                let hasApplicationIdentity = !(application.bundleIdentifier ?? "").isEmpty
                    || application.bundleURL?.pathExtension.caseInsensitiveCompare("app") == .orderedSame
                guard hasApplicationIdentity else { return nil }
                return AppRailApplication(
                    id: application.processIdentifier,
                    name: name,
                    bundleIdentifier: application.bundleIdentifier ?? "",
                    bundlePath: application.bundleURL?.path ?? "",
                    windows: []
                )
            }
            let applications = (windowedApplications + windowlessApplications).sorted {
                if $0.isShelfDormant != $1.isShelfDormant {
                    return !$0.isShelfDormant
                }
                let nameOrder = $0.name.localizedCaseInsensitiveCompare($1.name)
                if nameOrder != .orderedSame { return nameOrder == .orderedAscending }
                if $0.bundleIdentifier != $1.bundleIdentifier {
                    return $0.bundleIdentifier.localizedCaseInsensitiveCompare($1.bundleIdentifier) == .orderedAscending
                }
                return $0.id < $1.id
            }

            guard self.appRailApplications != applications else { return }
            // Running-application popovers can be opened while the snapshot
            // is changing. Keep their source list updates smooth without
            // animating the surrounding media lane.
            withAnimation(ShellMotion.contentIn.animation) {
                self.appRailApplications = applications
            }
        }
    }

    private func readDownloadingApps() {
        let names = DownloadActivity.runningAppNames()
        guard names != downloadingApps else { return }
        withAnimation(ShellMotion.contentIn.animation) { downloadingApps = names }
    }

    /// Dumps every input the indicators depend on, so a failure can be
    /// attributed to a layer instead of guessed at.
    ///
    /// This has cost several rounds of blind fixes: the answer depends on the
    /// producer, CoreAudio, and yabai agreeing, and from the outside a wrong
    /// icon looks identical whichever one is wrong. Written every tick to
    /// /tmp/macpp-nowplaying-debug.json.
    private func writeNowPlayingDebug() {
        // On by default because this is what finally made the media pipeline
        // debuggable, and it is one small file write per second. Turn it off
        // with:
        //   defaults write <shell-domain> macppNowPlayingDebug -bool false
        if UserDefaults.standard.object(forKey: "macppNowPlayingDebug") != nil,
           !UserDefaults.standard.bool(forKey: "macppNowPlayingDebug") {
            return
        }
        var spaces: [[String: Any]] = []
        for space in workspaces {
            spaces.append([
                "id": space.id,
                "name": space.name,
                "apps": space.apps,
                "playing": space.apps.filter { isNowPlayingApp($0) },
                "downloading": space.apps.filter { isDownloadingApp($0) }
            ])
        }
        let payload: [String: Any] = [
            "producer": [
                "source": media.source,
                "device": media.device,
                "title": media.title,
                "playing": media.playing,
                "position": media.position,
                "duration": media.duration
            ],
            "coreaudio_running_output": Array(audioOutputApps).sorted(),
            "coreaudio_capability": audioOutputCapability,
            "downloading": Array(downloadingApps).sorted(),
            "resolved_owner": reportedMediaOwner,
            "last_media_command": lastMediaCommand,
            "workspaces": spaces,
            "updated_at": Date().timeIntervalSince1970
        ]
        guard let data = try? JSONSerialization.data( // macpp:silent-ok debug payload serialization is optional and has no UI-side fallback
            withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]
        ) else { return }
        try? data.write(to: URL(fileURLWithPath: "/tmp/macpp-nowplaying-debug.json"), options: .atomic) // macpp:silent-ok debug persistence is best effort
    }

    /// Whether `app` has a download in flight. Same shape as
    /// `isNowPlayingApp(_:)` so the two indicators behave identically.
    func isDownloadingApp(_ app: String) -> Bool {
        let target = Self.mediaMatchToken(app)
        guard !target.isEmpty else { return false }
        return downloadingApps.contains { Self.mediaMatchToken($0) == target }
    }

    /// Refreshed on the ordinary shell tick. CoreAudio exposes one process
    /// object per client, so the full scan can touch dozens of objects. Keep
    /// that work off the main actor: cards only need the result, while an
    /// animation needs the main actor available for its next display frame.
    private func readAudioOutputApps() {
        guard !audioOutputReadInFlight else { return }
        audioOutputReadInFlight = true
        Task { @MainActor [weak self] in
            let snapshot = await Task.detached(priority: .utility) {
                AudioOutputProcesses.snapshot()
            }.value
            guard let self else { return }
            self.audioOutputReadInFlight = false
            self.applyAudioOutputSnapshot(snapshot)
        }
    }

    private func applyAudioOutputSnapshot(_ snapshot: AudioOutputProcesses.Snapshot) {
        if let error = snapshot.error {
            audioOutputCapability = "degraded: \(error)"
            MacPlusPlusBoundaryLog.record(
                "CoreAudio output-owner probe failed: \(error)",
                key: "coreaudio-output-owner",
                minimumInterval: 60
            )
            // A transient route rebuild should not make every now-playing
            // marker blink off.  Retain the last good owner set briefly, then
            // clear it rather than presenting stale attribution indefinitely.
            guard Date().timeIntervalSince(lastAudioOutputSuccess) >= 5 else { return }
        } else {
            audioOutputCapability = "present"
            lastAudioOutputSuccess = Date()
        }
        let names = snapshot.error == nil ? snapshot.names : []
        guard names != audioOutputApps else { return }
        // Animated so the indicator fades rather than popping when playback
        // starts or stops.
        withAnimation(ShellMotion.contentIn.animation) { audioOutputApps = names }
    }
    func refreshSurface() {
        guard !batterySaverEnabled else { return }
        guard !surfaceRefreshRunning else {
            surfaceRefreshPending = true
            return
        }
        refresh()
        refreshFrontApp()
        // Rate-limited to 15 minutes internally, so calling it from the
        // surface refresh just means "whenever the dashboard is being looked
        // at, make sure the reading isn't stale" -- it does not add a network
        // request per tick. Sitting under the batterySaver guard above also
        // means Battery Saver suspends weather polling along with every other
        // background probe, which is the whole point of that mode.
        refreshWeather()
        let generation = surfaceRefreshGeneration
        surfaceRefreshRunning = true
        Task { [weak self] in
            let snapshot = await Task.detached(priority: .utility) { SurfaceSnapshot.capture() }.value
            guard let self else { return }
            guard self.surfaceRefreshGeneration == generation else {
                // Do not publish an old presentation's answer. Visibility
                // changes advance this generation, so a result captured for a
                // panel that closed or reopened is still rejected. A
                // generation-valid hidden result is the startup/idle warm-up:
                // committing it keeps Dashboard's first slide from also being
                // the bars' first sample and restores the intended five-minute
                // hidden refresh cadence by advancing lastSurfaceRefresh.
                self.surfaceRefreshRunning = false
                self.surfaceRefreshPending = false
                if self.surfaceVisible { self.refreshSurface() }
                return
            }
            if let value = snapshot.brightness { self.brightness = value }
            self.wifiOn = snapshot.wifiOn
            self.batteryPercent = snapshot.batteryPercent
            self.battery = "\(snapshot.batteryPercent)%"
            self.charging = snapshot.charging
            self.cpu = snapshot.cpu; self.memory = snapshot.memory; self.diskUsed = snapshot.diskUsed
            self.performance = snapshot.performance
            self.performanceProcesses = snapshot.processes
            if !snapshot.workspaces.isEmpty { self.workspaces = snapshot.workspaces }
            self.themeName = snapshot.themeName; self.topProcess = snapshot.topProcess
            // `currentWorkspace` has its own live focus read and generation
            // fence. Never let this slower, full-surface snapshot overwrite a
            // newer active-space result with the space that was visible when
            // the probe started.
            self.surfaceRevision &+= 1
            self.lastSurfaceRefresh = Date()
            self.surfaceRefreshRunning = false
            let refreshAgain = self.surfaceRefreshPending && self.surfaceVisible
            self.surfaceRefreshPending = false
            if refreshAgain {
                self.refreshSurface()
            }
        }
    }

    /// Coalesce a burst of tab changes into one surface probe after the
    /// pointer has settled. The page transition stays immediate; only the
    /// expensive system/media/workspace snapshot waits for a quiet moment.
    func scheduleSurfaceRefresh(after delay: TimeInterval = 0.24) {
        surfaceRefreshWorkItem?.cancel()
        surfaceRefreshWorkItem = nil
        surfaceRefreshRequestGeneration &+= 1
        let generation = surfaceRefreshRequestGeneration
        guard surfaceVisible, !batterySaverEnabled else { return }
        let work = DispatchWorkItem { [weak self] in
            guard let self,
                  self.surfaceVisible,
                  !self.batterySaverEnabled,
                  self.surfaceRefreshRequestGeneration == generation else { return }
            self.surfaceRefreshWorkItem = nil
            self.refreshSurface()
        }
        surfaceRefreshWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + max(0.05, delay), execute: work)
    }

    /// Change the top-bar page from every input path through one gate. The
    /// pointer monitor and the SwiftUI hover handlers used to duplicate this
    /// logic, which also meant one path could forget to debounce its probe.
    func selectTopTab(_ index: Int) {
        guard (0..<4).contains(index), topTab != index else { return }
        // Keep the destination in the model and let NotchPopout animate its
        // single shared strip. Every selection, including a fast hover pass,
        // follows the same spatial curve so the outgoing and incoming cards
        // never snap independently or leave the animation missing.
        topTab = index
        setReactive(index == 1)
        setFrontAppResourceSampling(topSurfaceVisible && index == 0)
        scheduleSurfaceRefresh()
    }

    /// Normal media/now-playing state follows the producer at a one-second
    /// cadence. Battery Saver deliberately halves that rate, while an open
    /// reactive audio surface keeps the short cadence through quiet phrases
    /// and brief transport misses so it can recover without a visible stall.
    private func preferredTimerInterval() -> TimeInterval {
        if batterySaverEnabled { return 2.0 }
        // Keep the reactive reader at its short cadence even during a quiet
        // phrase or a brief transport miss. Waiting for `audioWasActive` to
        // become true again made recovery depend on the one-second idle tick,
        // which is exactly the pause users perceived as a frozen visualizer.
        return reactiveRequested ? 0.1 : 1.0
    }
    func setSurfaceVisible(_ visible: Bool, refreshInterval: TimeInterval = 1.0) {
        surfaceRefreshWorkItem?.cancel()
        surfaceRefreshWorkItem = nil
        surfaceRefreshRequestGeneration &+= 1
        if surfaceVisible != visible {
            surfaceRefreshGeneration &+= 1
            if !visible { surfaceRefreshPending = false }
        }
        surfaceVisible = visible
        surfaceRefreshInterval = max(1.0, refreshInterval)
        surfaceTimer?.invalidate(); surfaceTimer = nil
        guard visible, !batterySaverEnabled else { return }
        refreshSurface()
        surfaceTimer = Timer.scheduledTimer(withTimeInterval: surfaceRefreshInterval, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                // A close can race a queued timer delivery. Never allow a
                // stale surface timer to keep hidden gauges/layouts updating.
                guard self.surfaceVisible else {
                    self.surfaceTimer?.invalidate()
                    self.surfaceTimer = nil
                    return
                }
                self.refreshSurface()
            }
        }
        surfaceTimer?.tolerance = 0.12
    }
    func setReactive(_ enabled: Bool) {
        reactiveRequested = enabled
        // Start a detached read immediately. The first frame no longer waits
        // for the next main-run-loop timer delivery, and a slow/contended
        // shared-memory read cannot block the surface opening animation.
        if enabled && !batterySaverEnabled { requestAudioSample() }
        scheduleTimer(interval: preferredTimerInterval())
    }
    func setBatterySaver(_ enabled: Bool, persist: Bool = true) {
        guard batterySaverEnabled != enabled || persist else { return }
        batterySaverEnabled = enabled
        if persist {
            UserDefaults.standard.set(enabled, forKey: "macppBatterySaver")
            UserDefaults.standard.synchronize()
        }
        companionLyrics.setEnabled(!enabled)
        surfaceTimer?.invalidate()
        surfaceTimer = nil
        scheduleTimer(interval: preferredTimerInterval())
        if !enabled {
            if !media.title.isEmpty { companionLyrics.refresh(for: media, force: true) }
            if surfaceVisible { setSurfaceVisible(true, refreshInterval: surfaceRefreshInterval) }
        }
    }
    func setCMatrixScreensaverPaused(_ paused: Bool, persist: Bool = true) {
        guard cmatrixScreensaverPaused != paused || persist else { return }
        cmatrixScreensaverPaused = paused
        if persist {
            UserDefaults.standard.set(paused, forKey: "macppCMatrixScreensaverPaused")
            UserDefaults.standard.synchronize()
        }
        applyCMatrixScreensaverPauseState()
    }
    private func applyCMatrixScreensaverPauseState() {
        // Public builds have no background screen-saver watcher to pause or
        // start. Keep the preference local to the in-app preview controls.
    }
    func refreshScreensaverSelection() {
        let current = macppCurrentScreensaverSelection()
        if selectedScreensaver != current {
            selectedScreensaver = current
        }
    }
    func setScreensaver(_ selection: String) {
        guard macppScreensaverChoices.contains(where: { $0.selection == selection }) else { return }
        selectedScreensaver = selection
        UserDefaults.standard.set(selection, forKey: "org.macplusplus.setup.screensaver")
    }
    func startScreensaver(_ selection: String? = nil) {
        let requested = selection ?? selectedScreensaver
        guard macppScreensaverChoices.contains(where: { $0.selection == requested }) else { return }
        selectedScreensaver = requested
        UserDefaults.standard.set(requested, forKey: "org.macplusplus.setup.screensaver")
    }
    func setVolume(_ value: Double) {
        volume = min(1, max(0, value))
        muted = volume <= 0.001
        SystemOutputAudio.write(volume)
    }
    func toggleMute() {
        if muted || volume <= 0.001 {
            let restored = UserDefaults.standard.double(forKey: "macpp.lastAudibleVolume")
            setVolume(restored > 0.02 ? restored : 0.5)
        } else {
            UserDefaults.standard.set(volume, forKey: "macpp.lastAudibleVolume")
            setVolume(0)
        }
    }
    func setBrightness(_ value: Double) {
        brightness = min(1, max(0, value))
        DisplayBrightness.write(brightness)
    }
    func setPalette(_ palette: ShellPalette) {
        let selectedWallpaperOverride = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/MacPlusPlus/selected-wallpaper")
        // Palette notifications are mirrored by the wallpaper engine and by
        // MacPlusPlusCast.  Both can echo a committed choice back to the shell.  A
        // same-palette request must be a true no-op; otherwise every echo
        // commits only shell-owned preferences and a
        // distributed notification again.  That feedback loop was the source
        // of the runaway preference churn that could pin the Mac at high CPU.
        if palette != .custom,
           selectedPalette == palette,
           !FileManager.default.fileExists(atPath: selectedWallpaperOverride.path) {
            onPaletteChanged?()
            return
        }
        // A palette card owns the wallpaper for that palette.  Clear any
        // previously selected standalone video before announcing the palette
        // change, otherwise the wallpaper renderer would keep showing the
        // old extra video while the shell itself had already moved on.
        var previousOverrideData: Data?
        if FileManager.default.fileExists(atPath: selectedWallpaperOverride.path) {
            do {
                previousOverrideData = try Data(contentsOf: selectedWallpaperOverride)
                try FileManager.default.removeItem(at: selectedWallpaperOverride)
            } catch {
                MacPlusPlusBoundaryLog.record(
                    "palette \(palette.rawValue) could not clear wallpaper override: \(error)"
                )
                return
            }
        } else {
            previousOverrideData = nil
        }
        let sharedPaletteDirectory = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Palettes", isDirectory: true)
        do {
            try FileManager.default.createDirectory(
                at: sharedPaletteDirectory, withIntermediateDirectories: true
            )
            try Data(palette.rawValue.utf8).write(
                to: sharedPaletteDirectory.appendingPathComponent("selected-palette"),
                options: .atomic
            )
        } catch {
            if let previousOverrideData {
                do {
                    try previousOverrideData.write(to: selectedWallpaperOverride, options: .atomic)
                } catch {
                    MacPlusPlusBoundaryLog.record(
                        "palette rollback could not restore wallpaper override: \(error)"
                    )
                }
            }
            MacPlusPlusBoundaryLog.record(
                "palette \(palette.rawValue) could not persist shared selection: \(error)"
            )
            return
        }
        ShellGeneratedWallpaperPaletteStore.clear()
        UserDefaults.standard.removeObject(forKey: "macppWallpaperBasePalette")
        // Every screen-sized frame overlay observes this lightweight palette
        // object directly. Publishing it in the same animation transaction as
        // the content prevents Nexus, the rail, and the physical monitor
        // contour from changing on separate frames.
        withAnimation(ShellMotion.palette.animation) {
            // @AppStorage-backed panels must receive the preference inside the
            // same transaction as the shared frame presentation. Otherwise the
            // panel can recolour one frame before the monitor contour.
            UserDefaults.standard.set(palette.rawValue, forKey: "shellPalette")
            selectedPalette = palette
            palettePresentation.palette = palette
            companionRevision += 1
        }
        UserDefaults.standard.synchronize()
        // Preset wallpaper changes used to reach the renderer only through its
        // one-second preferences poll, while custom videos were announced
        // immediately. That made the two carousel paths feel unrelated and
        // gave preset switches a random delay. Publish the committed preset
        // now; the poll remains a recovery path if a notification is missed.
        if palette != .custom {
            DistributedNotificationCenter.default().postNotificationName(
                Notification.Name("org.macplusplus.macpp-wallpaper.palette"),
                object: nil,
                userInfo: ["name": palette.rawValue],
                deliverImmediately: true
            )
        }
        onPaletteChanged?()
    }

    /// Apply one of the additional videos in the wallpaper library without
    /// changing the active colour palette.  The wallpaper engine already
    /// understands this notification; keeping the override in one small file
    /// also means the selection survives closing and reopening the carousel.
    func applyWallpaperOverride(
        _ url: URL,
        crop: MacPlusPlusWallpaperCropSelection? = nil
    ) {
        let root = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/MacPlusPlus", isDirectory: true)
        let overrideURL = root.appendingPathComponent("selected-wallpaper")
        guard FileManager.default.fileExists(atPath: url.path) else { return }
        let normalized = url.standardizedFileURL
        if let crop {
            do {
                try MacPlusPlusWallpaperFramingStore.save(crop, for: normalized.path)
            } catch {
                MacPlusPlusBoundaryLog.record(
                    "wallpaper framing could not persist \(normalized.path): \(error)"
                )
                return
            }
        }
        if selectedPalette == .custom,
           let existing = try? String(contentsOf: overrideURL, encoding: .utf8), // macpp:silent-ok an absent wallpaper override means no duplicate-selection shortcut
           URL(fileURLWithPath: existing.trimmingCharacters(in: .whitespacesAndNewlines)).standardizedFileURL == normalized {
            // The carousel, the engine, and the top MacPlusPlus button can all
            // deliver the same selection.  Do not restart the decoder or
            // palette extraction when the selected source is unchanged.
            if crop != nil {
                DistributedNotificationCenter.default().postNotificationName(
                    Notification.Name("org.macplusplus.macpp-wallpaper.palette"),
                    object: nil,
                    userInfo: [
                        "name": selectedPalette.rawValue,
                        "wallpaper": normalized.path,
                        "framingChanged": true
                    ],
                    deliverImmediately: true
                )
            }
            return
        }
        if selectedPalette != .custom,
           UserDefaults.standard.string(forKey: "macppWallpaperBasePalette") == nil {
            UserDefaults.standard.set(selectedPalette.rawValue, forKey: "macppWallpaperBasePalette")
        }
        do {
            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
            try normalized.path.write(to: overrideURL, atomically: true, encoding: .utf8)
        } catch {
            MacPlusPlusBoundaryLog.record(
                "wallpaper override could not persist \(normalized.path): \(error)"
            )
            return
        }
        DistributedNotificationCenter.default().postNotificationName(
            Notification.Name("org.macplusplus.macpp-wallpaper.palette"),
            object: nil,
            userInfo: [
                "name": selectedPalette.rawValue,
                "wallpaper": normalized.path
            ],
            deliverImmediately: true
        )

        // The wallpaper engine creates a poster on its utility queue too, but
        // the shell cannot depend on that process being ready (a newly opened
        // carousel may be the first consumer). Decode one representative frame
        // here and persist the exact same four tokens for every MacPlusPlus surface.
        if let cached = ShellGeneratedWallpaperPaletteStore.load(path: normalized) {
            applyGeneratedWallpaperPalette([
                "frame": cached.frame, "panel": cached.panel,
                "text": cached.text, "accent": cached.accent
            ], for: normalized)
        } else {
            Task { [weak self] in
                let extracted = await Task.detached(priority: .utility) {
                    await WallpaperPaletteExtractor.extractHexColors(from: normalized)
                }.value
                guard extracted.count == PaletteRole.allCases.count else { return }
                await MainActor.run {
                    self?.applyGeneratedWallpaperPalette(extracted, for: normalized)
                }
            }
        }
    }

    /// Save a focal point without replacing the selected wallpaper. The
    /// source remains untouched; only the renderer's per-source framing
    /// sidecar changes. Notify the engine only when this is the wallpaper
    /// currently on the desktop so editing a neighbouring card is inert until
    /// that card is selected.
    @discardableResult
    func saveWallpaperFraming(
        _ selection: MacPlusPlusWallpaperCropSelection,
        for url: URL
    ) -> Bool {
        let normalized = url.standardizedFileURL
        guard FileManager.default.fileExists(atPath: normalized.path) else { return false }
        do {
            try MacPlusPlusWallpaperFramingStore.save(selection, for: normalized.path)
        } catch {
            MacPlusPlusBoundaryLog.record(
                "wallpaper framing could not persist \(normalized.path): \(error)"
            )
            return false
        }
        NotificationCenter.default.post(
            name: macppWallpaperFramingChangedNotification,
            object: nil,
            userInfo: ["path": normalized.path]
        )

        guard currentWallpaperURL()?.standardizedFileURL == normalized else { return true }
        var userInfo: [String: Any] = [
            "name": selectedPalette.rawValue,
            "wallpaper": normalized.path,
            "framingChanged": true
        ]
        if selectedPalette == .custom,
           let generated = ShellGeneratedWallpaperPaletteStore.load(path: normalized) {
            userInfo["frame"] = generated.frame
            userInfo["panel"] = generated.panel
            userInfo["text"] = generated.text
            userInfo["accent"] = generated.accent
        }
        DistributedNotificationCenter.default().postNotificationName(
            Notification.Name("org.macplusplus.macpp-wallpaper.palette"),
            object: nil,
            userInfo: userInfo,
            deliverImmediately: true
        )
        return true
    }

    /// Remove a managed custom wallpaper from the shared library. Curated
    /// bundle media and legacy sources are deliberately outside the allowed
    /// directory, so the little delete affordance can never remove them.
    @discardableResult
    func deleteMacPlusPlusWallpaper(_ url: URL) -> Bool {
        let normalized = url.standardizedFileURL
        let folder = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/MacPlusPlus/Wallpapers",
                isDirectory: true
            )
            .standardizedFileURL
        guard normalized.deletingLastPathComponent() == folder,
              // macpp:silent-ok a disappeared wallpaper is not deletable.
              let values = try? normalized.resourceValues(forKeys: [.isRegularFileKey]),
              values.isRegularFile == true else { return false }

        let selectedOverride = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent(
                "Library/Application Support/MacPlusPlus/selected-wallpaper"
            )
        let selectedPath: String?
        do {
            selectedPath = try String(contentsOf: selectedOverride, encoding: .utf8)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        } catch {
            selectedPath = nil
        }
        let isActive = selectedPath.map {
            URL(fileURLWithPath: $0).standardizedFileURL == normalized
        } ?? false
        var previousOverrideData: Data?
        do {
            if isActive {
                previousOverrideData = try Data(contentsOf: selectedOverride)
                try FileManager.default.removeItem(at: selectedOverride)
            } else {
                previousOverrideData = nil
            }
            try FileManager.default.removeItem(at: normalized)
            do {
                try MacPlusPlusWallpaperFramingStore.reset(for: normalized.path)
            } catch {
                MacPlusPlusBoundaryLog.record(
                    "wallpaper framing sidecar cleanup failed for \(normalized.path): \(error)"
                )
            }
            ShellGeneratedWallpaperPaletteStore.remove(path: normalized)
        } catch {
            if let previousOverrideData {
                do {
                    try previousOverrideData.write(to: selectedOverride, options: .atomic)
                } catch {
                    MacPlusPlusBoundaryLog.record(
                        "wallpaper override rollback failed for \(normalized.path): \(error)"
                    )
                }
            }
            MacPlusPlusBoundaryLog.record(
                "wallpaper could not be deleted \(normalized.path): \(error)"
            )
            return false
        }

        let catalogInfo: [AnyHashable: Any] = ["path": normalized.path]
        NotificationCenter.default.post(
            name: macppWallpaperCatalogChangedNotification,
            object: nil,
            userInfo: catalogInfo
        )
        DistributedNotificationCenter.default().postNotificationName(
            macppWallpaperCatalogChangedNotification,
            object: nil,
            userInfo: catalogInfo,
            deliverImmediately: true
        )
        if isActive {
            let storedBase = UserDefaults.standard.string(forKey: "macppWallpaperBasePalette")
            let fallback = storedBase
                .flatMap(ShellPalette.init(rawValue:))
                .flatMap { $0 == .custom ? nil : $0 }
                ?? .midnight
            setPalette(fallback)
        }
        return true
    }

    func currentWallpaperURL() -> URL? {
        let root = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/MacPlusPlus",
                isDirectory: true
            )
        let override = root.appendingPathComponent("selected-wallpaper")
        if selectedPalette == .custom,
           // macpp:silent-ok an absent override means the selected preset supplies the wallpaper.
           let raw = try? String(contentsOf: override, encoding: .utf8) {
            let path = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !path.isEmpty, FileManager.default.fileExists(atPath: path) else { return nil }
            return URL(fileURLWithPath: path).standardizedFileURL
        }
        let presetsURL = root.appendingPathComponent("Presets.json")
        // macpp:silent-ok missing or malformed preset metadata has no current wallpaper path.
        guard let data = try? Data(contentsOf: presetsURL),
              // macpp:silent-ok missing or malformed preset metadata has no current wallpaper path.
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let profiles = json["profiles"] as? [String: Any],
              let profile = profiles[selectedPalette.rawValue] as? [String: Any],
              let raw = profile["wallpaper"] as? String,
              !raw.isEmpty else { return nil }
        let path: String
        if raw.hasPrefix("bundle://") {
            path = FileManager.default.homeDirectoryForCurrentUser
                .appendingPathComponent(
                    "Applications/Mac++ Wallpaper.app/Contents/Resources",
                    isDirectory: true
                )
                .appendingPathComponent(String(raw.dropFirst("bundle://".count))).path
        } else {
            path = (raw as NSString).expandingTildeInPath
        }
        guard FileManager.default.fileExists(atPath: path) else { return nil }
        return URL(fileURLWithPath: path).standardizedFileURL
    }

    /// Commits a palette derived from the selected wallpaper's pixels. This
    /// deliberately does not call setPalette(.custom): that method owns the
    /// hand-authored palette/wallpaper relationship and would clear the very
    /// video override we are trying to theme.
    func applyGeneratedWallpaperPalette(_ colors: [String: String], for url: URL) {
        let overrideURL = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/MacPlusPlus/selected-wallpaper")
        guard let saved = try? String(contentsOf: overrideURL, encoding: .utf8), // macpp:silent-ok absent generated-palette state is an expected no-op
              FileManager.default.fileExists(atPath: url.path),
              URL(fileURLWithPath: saved.trimmingCharacters(in: .whitespacesAndNewlines)).standardizedFileURL
                == url.standardizedFileURL else { return }
        guard PaletteRole.allCases.allSatisfy({ colors[$0.rawValue] != nil }) else { return }
        let alreadyMatches = ShellPalette.current == .custom
            && PaletteRole.allCases.allSatisfy {
                UserDefaults.standard.string(forKey: "shellCustom.\($0.rawValue)")?.uppercased()
                    == colors[$0.rawValue]?.uppercased()
            }
        guard !alreadyMatches else { return }

        if selectedPalette != .custom,
           UserDefaults.standard.string(forKey: "macppWallpaperBasePalette") == nil {
            UserDefaults.standard.set(selectedPalette.rawValue, forKey: "macppWallpaperBasePalette")
        }
        for role in PaletteRole.allCases {
            if let value = colors[role.rawValue] {
                UserDefaults.standard.set(value, forKey: "shellCustom.\(role.rawValue)")
            }
        }
        _ = ShellGeneratedWallpaperPaletteStore.save(path: url, colors: colors)
        withAnimation(ShellMotion.palette.animation) {
            UserDefaults.standard.set(ShellPalette.custom.rawValue, forKey: "shellPalette")
            selectedPalette = .custom
            palettePresentation.palette = .custom
            companionRevision += 1
        }
        UserDefaults.standard.synchronize()
        onPaletteChanged?()
        DistributedNotificationCenter.default().postNotificationName(
            Notification.Name("org.macplusplus.macpp-wallpaper.palette"),
            object: nil,
            userInfo: [
                "name": "custom",
                "wallpaper": url.standardizedFileURL.path,
                "frame": colors[PaletteRole.frame.rawValue] ?? defaultPaletteHex(.frame),
                "panel": colors[PaletteRole.panel.rawValue] ?? defaultPaletteHex(.panel),
                "text": colors[PaletteRole.text.rawValue] ?? defaultPaletteHex(.text),
                "accent": colors[PaletteRole.accent.rawValue] ?? defaultPaletteHex(.accent)
            ],
            deliverImmediately: true
        )
    }

    func customColor(_ role: PaletteRole) -> Color {
        let fallback = defaultPaletteHex(role)
        return Color(nsColor: NSColor(macppHex: UserDefaults.standard.string(forKey: "shellCustom.\(role.rawValue)") ?? fallback) ?? .white)
    }

    func setCustomColor(_ role: PaletteRole, color: Color) {
        UserDefaults.standard.set(NSColor(color).macppHex, forKey: "shellCustom.\(role.rawValue)")
        setPalette(.custom)
        objectWillChange.send()
    }

    func chooseMacPlusPlusWallpaper() {
        // This is a cross-process command surface, so the distributed bus is
        // the canonical route. Posting locally as well delivered the same click
        // twice to ShellDelegate and restarted the morph halfway through.
        DistributedNotificationCenter.default().postNotificationName(
            Notification.Name("\(macppShellDomain).show-wallpapers"),
            object: nil,
            userInfo: nil,
            deliverImmediately: true
        )
    }

    private func nonworkWallpaperStateURL(for mode: MacPlusPlusNonworkWallpaperMode) -> URL {
        FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/MacPlusPlus/Nonwork",
                isDirectory: true
            )
            .appendingPathComponent("\(mode.rawValue)-wallpaper", isDirectory: false)
    }

    func nonworkWallpaperURL(for mode: MacPlusPlusNonworkWallpaperMode) -> URL? {
        let stateURL = nonworkWallpaperStateURL(for: mode)
        // macpp:silent-ok absent per-mode wallpaper state is the expected first-run fallback
        guard let raw = try? String(contentsOf: stateURL, encoding: .utf8) else { return nil }
        let path = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !path.isEmpty else { return nil }
        let expanded = (path as NSString).expandingTildeInPath
        let normalized = URL(fileURLWithPath: expanded).standardizedFileURL
        guard macppWallpaperImageExtensions.contains(normalized.pathExtension.lowercased()),
              FileManager.default.fileExists(atPath: normalized.path) else { return nil }
        return normalized
    }

    func nonworkWallpaperName(for mode: MacPlusPlusNonworkWallpaperMode) -> String {
        guard let url = nonworkWallpaperURL(for: mode) else { return "DEFAULT" }
        let stem = url.deletingPathExtension().lastPathComponent
            .replacingOccurrences(of: "-", with: " ")
            .replacingOccurrences(of: "_", with: " ")
        return String(stem.uppercased().prefix(28))
    }

    func nonworkWallpaperName(for target: MacPlusPlusNonworkWallpaperTarget) -> String {
        let names = target.modes.map { nonworkWallpaperName(for: $0) }
        guard target == .both else { return names[0] }
        let uniqueNames = Set(names)
        return uniqueNames.count == 1 ? names[0] : "MIXED"
    }

    @discardableResult
    func setNonworkWallpaper(
        _ mode: MacPlusPlusNonworkWallpaperMode,
        url: URL
    ) -> Bool {
        let normalized = url.standardizedFileURL
        guard normalized.isFileURL,
              macppWallpaperImageExtensions.contains(normalized.pathExtension.lowercased()),
              FileManager.default.fileExists(atPath: normalized.path) else { return false }
        let stateURL = nonworkWallpaperStateURL(for: mode)
        do {
            try FileManager.default.createDirectory(
                at: stateURL.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            try Data(normalized.path.utf8).write(to: stateURL, options: [.atomic])
        } catch {
            MacPlusPlusBoundaryLog.record(
                "\(mode.rawValue) wallpaper could not persist \(normalized.path): \(error)"
            )
            return false
        }
        nonworkWallpaperRevision &+= 1
        return true
    }

    @discardableResult
    func setNonworkWallpaper(
        _ target: MacPlusPlusNonworkWallpaperTarget,
        url: URL
    ) -> Bool {
        target.modes.allSatisfy { setNonworkWallpaper($0, url: url) }
    }

    func chooseNonworkWallpaper(_ target: MacPlusPlusNonworkWallpaperTarget) {
        let panel = NSOpenPanel()
        panel.title = "Set \(target.title) wallpaper"
        panel.prompt = "Choose"
        panel.allowedContentTypes = [.image]
            + macppWallpaperImageExtensions.compactMap { UTType(filenameExtension: $0) }
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.begin { [weak self] response in
            guard response == .OK, let source = panel.url else { return }
            Task { @MainActor [weak self] in
                guard let self,
                      let managedURL = self.installMacPlusPlusWallpaperMedia(from: source),
                      self.setNonworkWallpaper(target, url: managedURL) else {
                    NSSound.beep()
                    return
                }
            }
        }
    }

    /// Present the same importer from every wallpaper surface. The embedded
    /// selector and the standalone drawer both write to the shared managed
    /// folder, so importing through either entry point must immediately make
    /// the new card available to both consumers.
    func chooseMacPlusPlusWallpaperMedia() {
        let panel = NSOpenPanel()
        panel.title = "Add a MacPlusPlus wallpaper"
        panel.prompt = "Add"
        panel.message = "Videos and images are added to the shared wallpaper library and receive an automatic palette."
        panel.allowedContentTypes = [.movie, .quickTimeMovie, .mpeg4Movie, .image]
            + macppWallpaperMediaExtensions.compactMap { UTType(filenameExtension: $0) }
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.begin { [weak self] response in
            guard response == .OK, let source = panel.url else { return }
            Task { @MainActor [weak self] in
                guard let self,
                      let target = self.installMacPlusPlusWallpaperMedia(from: source) else { return }
                self.applyWallpaperOverride(target)
            }
        }
    }

    func chooseMediaCompanion() {
        let panel = NSOpenPanel()
        panel.title = "Choose media companion"
        panel.prompt = "Use Companion"
        panel.allowedContentTypes = [.image, .gif]
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.begin { [weak self] response in
            guard response == .OK, let source = panel.url else { return }
            Task { @MainActor [weak self] in self?.installMediaCompanion(from: source) }
        }
    }

    func installMediaCompanion(from source: URL) {
        let manager = FileManager.default
        let root = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("Library/Application Support/MacPlusPlus/Assets", isDirectory: true)
        try? manager.createDirectory(at: root, withIntermediateDirectories: true) // macpp:silent-ok media companion caching is optional after the source is selected
        for name in ["media-companion.gif", "media-companion.png", "media-companion.jpg", "media-companion.jpeg"] {
            try? manager.removeItem(at: root.appendingPathComponent(name)) // macpp:silent-ok removing an absent companion is idempotent cleanup
        }
        let ext = ["gif", "png", "jpg", "jpeg"].contains(source.pathExtension.lowercased()) ? source.pathExtension.lowercased() : "png"
        let target = root.appendingPathComponent("media-companion.\(ext)")
        do {
            try manager.copyItem(at: source, to: target)
            companionRevision += 1
        } catch { NSSound.beep() }
    }

    /// Copy a video or still into the shared wallpaper library used by Mac++ Shell,
    /// Nexus, MacPlusPlusCast, and the standalone Mac++ Wallpaper drawer.  Returning
    /// the managed URL lets the caller select it immediately without having
    /// to rediscover a path through a second catalog.
    @discardableResult
    fileprivate func installMacPlusPlusWallpaperMedia(from source: URL) -> URL? {
        let extensionName = source.pathExtension.lowercased()
        guard macppWallpaperMediaExtensions.contains(extensionName) else {
            NSSound.beep()
            return nil
        }
        let manager = FileManager.default
        let folder = manager.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Wallpapers", isDirectory: true)
        do {
            try manager.createDirectory(at: folder, withIntermediateDirectories: true)
            let rawStem = source.deletingPathExtension().lastPathComponent
            let stem = rawStem
                .replacingOccurrences(of: "[^A-Za-z0-9._-]+", with: "-", options: .regularExpression)
                .trimmingCharacters(in: CharacterSet(charactersIn: ".-"))
            let safeStem = stem.isEmpty ? "wallpaper" : String(stem.prefix(80))
            let sourcePath = source.standardizedFileURL.path
            var target = folder.appendingPathComponent("\(safeStem).\(extensionName)")
            var suffix = 2
            while manager.fileExists(atPath: target.path), target.standardizedFileURL.path != sourcePath {
                target = folder.appendingPathComponent("\(safeStem)-\(suffix).\(extensionName)")
                suffix += 1
            }
            if target.standardizedFileURL.path != sourcePath {
                // The collision loop deliberately chooses a destination that
                // does not exist. Removing it unconditionally made every new
                // import fail with "file not found" before the copy ran.
                // Existing names have already been moved to a suffixed target;
                // copy directly into the unused destination.
                try manager.copyItem(at: source, to: target)
            }
            // Prepare the native lock-screen representation in the background
            // without selecting it. Still images are converted into a short,
            // cacheable loop by the lock-screen helper. Selection remains centralized in
            // applyWallpaperOverride/macpp-accent, so importing a file can
            // never change the active desktop or start a second transition.
            let catalogInfo: [AnyHashable: Any] = ["path": target.path]
            NotificationCenter.default.post(
                name: macppWallpaperCatalogChangedNotification,
                object: nil,
                userInfo: catalogInfo
            )
            DistributedNotificationCenter.default().postNotificationName(
                macppWallpaperCatalogChangedNotification,
                object: nil,
                userInfo: catalogInfo,
                deliverImmediately: true
            )
            return target.standardizedFileURL
        } catch {
            NSSound.beep()
            return nil
        }
    }

    private func restoreGeneratedWallpaperPaletteIfNeeded() {
        let overrideURL = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/MacPlusPlus/selected-wallpaper")
        guard let saved = try? String(contentsOf: overrideURL, encoding: .utf8), // macpp:silent-ok absent generated-palette state is an expected no-op
              !saved.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let savedURL = URL(fileURLWithPath: saved.trimmingCharacters(in: .whitespacesAndNewlines))
        guard FileManager.default.fileExists(atPath: savedURL.path),
              let generated = ShellGeneratedWallpaperPaletteStore.load(path: savedURL) else { return }
        for role in PaletteRole.allCases {
            let value: String
            switch role {
            case .frame: value = generated.frame
            case .panel: value = generated.panel
            case .text: value = generated.text
            case .accent: value = generated.accent
            }
            UserDefaults.standard.set(value, forKey: "shellCustom.\(role.rawValue)")
        }
        if selectedPalette != .custom,
           UserDefaults.standard.string(forKey: "macppWallpaperBasePalette") == nil {
            UserDefaults.standard.set(selectedPalette.rawValue, forKey: "macppWallpaperBasePalette")
        }
        UserDefaults.standard.set(ShellPalette.custom.rawValue, forKey: "shellPalette")
        selectedPalette = .custom
        palettePresentation.palette = .custom
        companionRevision += 1
    }

    private func refreshOutputAudio() {
        guard let audio = SystemOutputAudio.read() else {
            requestOutputAudioFallbackRead()
            return
        }
        let selectedDeviceID = SystemOutputAudio.selectedDeviceID()
        if let previousDeviceID = lastOutputDeviceID,
           previousDeviceID != selectedDeviceID {
            let name = SystemOutputAudio.outputDevices()
                .first(where: { $0.id == selectedDeviceID })?.name ?? "New audio output"
            onStateToast?(MacPlusPlusStateToast(
                title: "Audio Output",
                detail: name,
                symbol: "hifispeaker.fill"
            ))
        }
        lastOutputDeviceID = selectedDeviceID
        let nextVolume = min(1, max(0, audio.volume))
        // Hardware keys and other clients can legitimately move volume by
        // less than two percent. The old epsilon made the slider visibly
        // skip those small changes, even though CoreAudio had reported them.
        if abs(volume - nextVolume) > 0.0001 { volume = nextVolume }
        if muted != audio.muted { muted = audio.muted }
    }

    private func refreshInputAudio() {
        guard let audio = SystemInputAudio.read() else {
            microphoneMuteAvailable = false
            return
        }
        let selectedDeviceID = SystemInputAudio.selectedDeviceID()
        let deviceChanged = lastInputDeviceID != nil && lastInputDeviceID != selectedDeviceID
        let muteChanged = microphoneStateInitialized && microphoneMuted != audio.muted
        microphoneMuteAvailable = audio.muteAvailable
        microphoneMuted = audio.muted
        if deviceChanged {
            let name = SystemInputAudio.inputDevices()
                .first(where: { $0.id == selectedDeviceID })?.name ?? "New microphone"
            onStateToast?(MacPlusPlusStateToast(
                title: "Microphone Input",
                detail: name,
                symbol: "mic.fill"
            ))
        } else if muteChanged {
            onStateToast?(MacPlusPlusStateToast(
                title: audio.muted ? "Microphone Muted" : "Microphone Live",
                detail: audio.muted ? "Input audio is blocked" : "Input audio is available",
                symbol: audio.muted ? "mic.slash.fill" : "mic.fill"
            ))
        }
        lastInputDeviceID = selectedDeviceID
        microphoneStateInitialized = true
    }

    func toggleMicrophoneMute() {
        guard microphoneMuteAvailable else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Microphone Control Unavailable",
                detail: "The current input does not expose hardware mute",
                symbol: "exclamationmark.triangle.fill"
            ))
            return
        }
        guard SystemInputAudio.writeMute(!microphoneMuted) else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Microphone Mute Failed",
                detail: "CoreAudio rejected the input change",
                symbol: "exclamationmark.triangle.fill",
                critical: true
            ))
            return
        }
        // Reconcile immediately. The HAL listener normally delivers the same
        // read a moment later, but this keeps the button authoritative even if
        // a third-party device omits property-change notifications.
        refreshInputAudio()
    }

    private func refreshFocusState() {
        guard let state = SystemFocus.read() else {
            focusStateAvailable = false
            return
        }
        let changed = focusStateInitialized && focusEnabled != state.enabled
        focusStateAvailable = true
        focusEnabled = state.enabled
        focusName = state.modeName.isEmpty ? "DO NOT DISTURB" : state.modeName.uppercased()
        if changed {
            onStateToast?(MacPlusPlusStateToast(
                title: state.enabled ? "Focus Enabled" : "Focus Disabled",
                detail: state.enabled ? focusName.capitalized : "Notifications are available",
                symbol: state.enabled ? "moon.fill" : "moon"
            ))
        }
        focusStateInitialized = true
    }

    private func refreshFocusAvailability(force: Bool = false) {
        guard !focusAvailabilityInFlight else { return }
        guard force || Date().timeIntervalSince(lastFocusAvailabilityRefresh) >= 60 else { return }
        focusAvailabilityInFlight = true
        lastFocusAvailabilityRefresh = Date()
        SystemFocus.checkAvailability { [weak self] available in
            guard let self else { return }
            self.focusControlAvailable = available
            self.focusAvailabilityInFlight = false
        }
    }

    func toggleFocus() {
        guard !focusMutationInFlight else { return }
        if !focusControlAvailable {
            refreshFocusAvailability(force: true)
            onStateToast?(MacPlusPlusStateToast(
                title: "Focus Setup Needed",
                detail: "Create MacPlusPlus Focus On / Off in Shortcuts",
                symbol: "moon.badge.exclamationmark"
            ))
            return
        }
        guard focusStateAvailable else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Focus State Unavailable",
                detail: "MacPlusPlus cannot safely determine the current Focus mode",
                symbol: "moon.badge.exclamationmark"
            ))
            return
        }
        let requestedState = !focusEnabled
        focusMutationInFlight = true
        SystemFocus.setEnabled(requestedState) { [weak self] success in
            guard let self else { return }
            self.focusMutationInFlight = false
            guard success else {
                self.focusControlAvailable = false
                self.onStateToast?(MacPlusPlusStateToast(
                    title: "Focus Change Failed",
                    detail: "The Apple Shortcut did not complete",
                    symbol: "exclamationmark.triangle.fill",
                    critical: true
                ))
                return
            }
            // Shortcuts returns when its action completes, but the assertion
            // file can land on a later user-session queue. Reconcile now and
            // twice more without optimistic state, so the rail never claims a
            // mode macOS has not actually enabled.
            self.refreshFocusState()
            for delay in [0.45, 1.25] {
                DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                    self?.refreshFocusState()
                }
            }
        }
    }
    func connectSpotifyQueue() {
spotifyNextTrack = nil
        spotifyQueueStatus = .unavailable
        onStateToast?(MacPlusPlusStateToast(
            title: "Spotify Queue",
            detail: "Account authorization is not included in the public profile; media controls still work.",
            symbol: "music.note"
        ))
    }

    func mediaAction(_ action: String) {
        let provider: String = {
            if preferredMediaSource == "spotify" { return "spotify" }
            if isSpotifyMedia(media) { return "spotify" }
            if MacPlusPlusPureLogic.mediaOwnerMatches(
                application: "Safari",
                source: media.source,
                device: media.device
            ) { return "safari" }
            if MacPlusPlusPureLogic.mediaOwnerMatches(
                application: "Browser",
                source: media.source,
                device: media.device
            ) { return "browser" }
            return "active"
        }()
        guard MacPlusPlusMediaControl.launch(action, provider: provider) else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Media Control Unavailable",
                detail: "The public helper is missing or the selected action is unsupported.",
                symbol: "exclamationmark.triangle"
            ))
            return
        }
        if action == "playpause" {
            withAnimation(ShellMotion.contentIn.animation) { media.playing.toggle() }
            optimisticPlaybackState = media.playing
            optimisticPlaybackUntil = Date().addingTimeInterval(1.15)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.80) { [weak self] in self?.readMedia() }
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.30) { [weak self] in self?.readMedia() }
        }
    }

    func toggleCinemaMode() {
        guard cinemaPresentation != nil || safariCinemaAvailable else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Cinema Mode",
                detail: "Play a video in Safari before entering Cinema",
                symbol: "rectangle.inset.filled"
            ))
            return
        }
        // Resume the authored preference when entering; the helper's generic
        // `toggle` defaults to WIDE and otherwise discarded the visible saved
        // FIT/SCOPE/FILL choice. The active recovery session remains the
        // authority for deciding when to restore.
        performCinemaAction(cinemaPresentation == nil ? preferredCinemaPresentation.rawValue : "off")
    }

    /// Option-clicking the existing Cinema control applies the next authored
    /// presentation without introducing an AppKit Menu inside the shell's
    /// borderless screen-saver-level panel.
    func cycleCinemaMode() {
        guard cinemaPresentation != nil || safariCinemaAvailable else {
            toggleCinemaMode()
            return
        }
        let next = (cinemaPresentation ?? preferredCinemaPresentation).next
        preferredCinemaPresentation = next
        UserDefaults.standard.set(next.rawValue, forKey: cinemaPresentationPreferenceKey)
        performCinemaAction(next.rawValue)
    }

    func refreshCinemaStatus(force: Bool = false) {
        guard !cinemaMutationInFlight else { return }
        let now = Date()
        guard force || now.timeIntervalSince(lastCinemaStatusRefresh) >= 3 else { return }
        guard !cinemaStatusReadInFlight else {
            // A forced reconciliation (currently the mutation-failure path)
            // must run after the older status helper drains. Ordinary app-
            // activation refreshes can share the answer already in flight.
            if force { cinemaStatusRefreshPending = true }
            return
        }
        lastCinemaStatusRefresh = now
        cinemaStatusReadInFlight = true
        cinemaStatusRefreshGeneration &+= 1
        let generation = cinemaStatusRefreshGeneration
        Task { [weak self] in
            let result = await Task.detached(priority: .utility) {
                runCinemaCommand("status")
            }.value
            guard let self else { return }
            self.cinemaStatusReadInFlight = false
            if self.cinemaStatusRefreshGeneration == generation,
               !self.cinemaMutationInFlight,
               result.ok {
                self.cinemaPresentation = result.enabled ? result.presentation : nil
            }
            if self.cinemaStatusRefreshPending, !self.cinemaMutationInFlight {
                self.cinemaStatusRefreshPending = false
                self.refreshCinemaStatus(force: true)
            }
        }
    }

    private func performCinemaAction(_ action: String) {
        guard !cinemaMutationInFlight else { return }
        // A mutation result is authoritative. Fence any status answer that
        // was captured before this request and discard its queued refresh;
        // the failure path below schedules a fresh reconciliation if needed.
        cinemaStatusRefreshGeneration &+= 1
        cinemaStatusRefreshPending = false
        cinemaMutationInFlight = true
        let restoring = action == "off" || (action == "toggle" && cinemaPresentation != nil)
        let requested = CinemaPresentation(rawValue: action) ?? preferredCinemaPresentation
        cinemaOperationLabel = restoring ? "RESTORING CINEMA" : "APPLYING CINEMA \(requested.title)"
        Task { [weak self] in
            let result = await Task.detached(priority: .userInitiated) {
                runCinemaCommand(action)
            }.value
            guard let self else { return }
            self.cinemaMutationInFlight = false
            self.cinemaOperationLabel = ""
            self.lastCinemaStatusRefresh = Date()
            guard result.ok else {
                let detail: String
                switch result.reason {
                case "no-visible-html5-video": detail = "No playable video was found in the Safari tab"
                case "yabai-opacity-failed", "yabai-window-query-failed", "safari-window-not-managed-by-yabai":
                    detail = "Safari could not be made opaque through yabai"
                case "safari-automation-error", "osascript-failed":
                    detail = "MacPlusPlus could not control the active Safari tab"
                case "cinema-restore-incomplete": detail = "Cinema could not completely restore the Safari window"
                default: detail = result.detail.isEmpty ? "Cinema could not change presentation" : result.detail
                }
                self.onStateToast?(MacPlusPlusStateToast(
                    title: "Cinema Mode Failed",
                    detail: detail,
                    symbol: "exclamationmark.triangle.fill",
                    critical: true
                ))
                self.refreshCinemaStatus(force: true)
                return
            }

            if result.enabled, let presentation = result.presentation {
                self.cinemaPresentation = presentation
                self.preferredCinemaPresentation = presentation
                UserDefaults.standard.set(presentation.rawValue, forKey: cinemaPresentationPreferenceKey)
                self.onStateToast?(MacPlusPlusStateToast(
                    title: "Cinema · \(presentation.title)",
                    detail: result.opaque ? "Safari video is fully opaque" : "Safari video presentation enabled",
                    symbol: "rectangle.inset.filled"
                ))
            } else {
                self.cinemaPresentation = nil
                self.onStateToast?(MacPlusPlusStateToast(
                    title: "Cinema Off",
                    detail: "Safari window restored",
                    symbol: "rectangle.inset.filled"
                ))
            }
        }
    }

    func selectMediaSource(_ source: String) {
        let normalized = ["automatic", "spotify", "system"].contains(source) ? source : "automatic"
        guard preferredMediaSource != normalized else { return }
        preferredMediaSource = normalized
        UserDefaults.standard.set(normalized, forKey: "macppMediaSource")

        // This is a display preference, not a transport command. When Safari
        // and Spotify are both active, choosing one from the top-bar menu must
        // not stop the other player; it only changes which cached producer is
        // shown in the shell.
        if normalized == "spotify" {
            if let fallback = spotifyMediaFallback { media = fallback }
        } else if normalized == "system" {
            if let fallback = systemMediaFallback { media = fallback }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { [weak self] in self?.readMedia() }
    }
    func setShellBorderEnabled(_ enabled: Bool) {
        guard shellBorderEnabled != enabled else { return }
        shellBorderEnabled = enabled
        borderPresentation.enabled = enabled
        UserDefaults.standard.set(enabled, forKey: shellBorderPreferenceKey)
    }
    func toggleAppDock() {
#if MACPP_CAELESTIA_SHELL
        // Shelf visibility is owned by ShellDelegate, which can distinguish a
        // hover preview from an explicitly pinned toggle.
        refreshAppRailApplications(force: true)
        return
#else
        appDockVisible.toggle()
        UserDefaults.standard.set(appDockVisible, forKey: appDockVisibilityPreferenceKey)
        if appDockVisible {
            refreshAppRailApplications(force: true)
        }
#endif
    }
    /// All radio mutations share one busy boundary. Re-entry from another
    /// surface cannot race a connect against a power-off or disconnect.
    private func performWiFiAction(_ operation: @escaping @Sendable (String) throws -> Void) {
        guard !wifiActionPending else { return }
        wifiActionPending = true
        connectivityMutationGeneration &+= 1
        let interface = wifiInterface
        wifiToggleTask = Task { [weak self] in
            let failure = await Task.detached(priority: .userInitiated) { () -> String? in
                do {
                    try operation(interface)
                    return nil
                } catch {
                    MacPlusPlusBoundaryLog.record("Wi-Fi action failed: \(error)")
                    return error.localizedDescription
                }
            }.value
            guard let self, !Task.isCancelled else { return }
            self.wifiActionPending = false
            self.wifiToggleTask = nil
            // Reject any read that began while the radio was changing too.
            self.connectivityMutationGeneration &+= 1
            self.suppressWiFiSSIDFallback = false
            if let failure {
                self.onStateToast?(MacPlusPlusStateToast(
                    title: "Wi-Fi", detail: failure, symbol: "wifi.exclamationmark"
                ))
            }
            self.refreshConnectivity(force: true)
        }
    }

    func toggleWiFi() {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi") else {
            onStateToast?(MacPlusPlusStateToast(
                title: "Wi-Fi Controls Off",
                detail: "Enable Wi-Fi controls in Setup Manager to use these actions.",
                symbol: "wifi.slash"
            ))
            return
        }
        guard !wifiActionPending else { return }
        let enabled = !wifiOn
        wifiOn = enabled
        if !enabled {
            wifiConnected = false
            connectedNetwork = ""
        }
        performWiFiAction { name in
            guard let interface = CWWiFiClient.shared().interface(withName: name) else {
                throw NSError(domain: "MacPlusPlusWiFi", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Wi-Fi is unavailable"])
            }
            try interface.setPower(enabled)
        }
    }
    func refreshWiFiNetworks() {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi") else {
            knownNetworks = []
            wifiScanning = false
            wifiScanStatus = "DISABLED IN SETUP"
            return
        }
        let nearbyScanEnabled = UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi-nearby-scan")
        if nearbyScanEnabled && UserDefaults.standard.bool(forKey: "org.macplusplus.setup.location") {
            locationProvider.start()
        }
        refreshConnectivity(force: true, includeNearbyInventory: nearbyScanEnabled)
    }
    func refreshBluetoothDevices(force: Bool = false) {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.bluetooth") else {
            bluetoothDevices = []
            bluetoothScanning = false
            return
        }
        let now = Date()
        if bluetoothRefreshTask != nil {
            // Only an explicit refresh button or a post-toggle settle pass
            // should request another scan after the current inquiry. Hover
            // callbacks are passive and must not create a self-sustaining
            // chain of blueutil inquiries.
            if force { bluetoothRefreshPending = true }
            return
        }
        guard force || now.timeIntervalSince(lastBluetoothRefresh) >= bluetoothRefreshCooldown else {
            return
        }
        lastBluetoothRefresh = now
        bluetoothScanning = true
        bluetoothRefreshTask = Task { [weak self] in
            let devices = await Task.detached(priority: .utility) { () -> [BluetoothDeviceInfo] in
                // Both lists are optional `[Any]` values from the Obj-C bridge,
                // not optional `[IOBluetoothDevice]` arrays. Collect the native
                // paired/recent inventory first, then merge blueutil's
                // controller inquiry below for devices that are nearby but
                // have never been paired with this Mac.
                let paired = (IOBluetoothDevice.pairedDevices() ?? [])
                    .compactMap { $0 as? IOBluetoothDevice }
                let recent = (IOBluetoothDevice.recentDevices(20) ?? [])
                    .compactMap { $0 as? IOBluetoothDevice }
                let pairedAddresses = Set(paired.compactMap(\.addressString))
                var seen = Set<String>()
                let native: [BluetoothDeviceInfo] = (paired + recent).compactMap { device in
                    guard let address = device.addressString, !address.isEmpty else { return nil }
                    guard seen.insert(address).inserted else { return nil }
                    let name = (device.name?.isEmpty == false ? device.name : nil) ?? "BLUETOOTH DEVICE"
                    return BluetoothDeviceInfo(
                        address: address,
                        name: name,
                        connected: device.isConnected(),
                        paired: pairedAddresses.contains(address)
                    )
                }
                // `pairedDevices()` is normally reliable, but the bridge can
                // return an empty collection during controller wake. The
                // blueutil registry is a fast, read-only fallback and does
                // not require waiting for the nearby inquiry below.
                return mergeBluetoothDevices(native, blueutilPairedDevices())
            }.value
            guard let self, !Task.isCancelled else { return }
            // Publish the fast paired/recent inventory before the optional
            // blueutil inquiry completes. This gives a freshly reloaded shell
            // useful Bluetooth rows immediately; the nearby pass below then
            // enriches the same list instead of leaving the card empty during
            // the controller's several-second inquiry.
            let retained = self.bluetoothDiscoveryCache.retained(
                from: self.bluetoothDevices,
                at: Date()
            )
            let initial = self.applyBluetoothIntents(
                to: mergeBluetoothDevices(retained, devices)
            )
            if (!initial.isEmpty || self.bluetoothDevices.isEmpty),
               self.bluetoothDevices != initial {
                self.bluetoothDevices = initial
            }
            // The nearby pass still waits for the controller inquiry to
            // finish before merging, so one complete result updates the list
            // atomically. The fast snapshot above is only an additive warm
            // start; a transient all-empty final merge still cannot erase a
            // useful inventory.
            let nearby = await Task.detached(priority: .utility) {
                blueutilNearbyDevices()
            }.value
            guard !Task.isCancelled else { return }
            // A transient all-empty read must not erase the last useful
            // inventory. An actually empty starting list still clears as
            // normal, so a machine with no devices does not get a stale row.
            let discoveryDate = Date()
            self.bluetoothDiscoveryCache.record(nearby, at: discoveryDate)
            let retainedAfterInquiry = self.bluetoothDiscoveryCache.retained(
                from: self.bluetoothDevices,
                at: discoveryDate
            )
            let merged = self.applyBluetoothIntents(
                to: mergeBluetoothDevices(
                    retainedAfterInquiry,
                    mergeBluetoothDevices(devices, nearby)
                )
            )
            if (!merged.isEmpty || self.bluetoothDevices.isEmpty),
               self.bluetoothDevices != merged {
                self.bluetoothDevices = merged
            }
            self.bluetoothScanning = false
            self.bluetoothRefreshTask = nil
            if self.bluetoothRefreshPending {
                self.bluetoothRefreshPending = false
                self.refreshBluetoothDevices(force: true)
            }
        }
    }
    /// Connected devices sort first, then alphabetically. Every path that
    /// publishes `bluetoothDevices` goes through this, so the row order can
    /// never depend on which path produced the list.
    private func sortedBluetooth(_ devices: [BluetoothDeviceInfo]) -> [BluetoothDeviceInfo] {
        devices.sorted {
            if $0.connected != $1.connected { return $0.connected && !$1.connected }
            if $0.nearby != $1.nearby { return $0.nearby && !$1.nearby }
            if $0.paired != $1.paired { return $0.paired && !$1.paired }
            return $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
        }
    }

    /// Overlay unconfirmed requests on a fresh radio read, dropping each one as
    /// soon as the radio reports the requested state or the request times out.
    ///
    /// Only ever called with a hardware read. Applying it to the optimistic list
    /// would immediately see the requested state already present and clear the
    /// intent that is supposed to protect it.
    private func applyBluetoothIntents(to devices: [BluetoothDeviceInfo]) -> [BluetoothDeviceInfo] {
        guard !bluetoothConnectionIntents.isEmpty else { return sortedBluetooth(devices) }
        let now = Date()
        var resolved = devices
        for index in resolved.indices {
            let address = resolved[index].address
            guard let intent = bluetoothConnectionIntents[address] else { continue }
            if !bluetoothActionsPending.contains(address),
               (resolved[index].connected == intent.connected || intent.deadline <= now) {
                bluetoothConnectionIntents[address] = nil
                continue
            }
            resolved[index] = BluetoothDeviceInfo(
                address: address,
                name: resolved[index].name,
                connected: intent.connected,
                paired: resolved[index].paired,
                nearby: resolved[index].nearby
            )
        }
        // Forget requests for devices macOS no longer reports at all, so an
        // unpaired device cannot keep an entry alive for the whole session.
        let known = Set(resolved.map(\.address))
        bluetoothConnectionIntents = bluetoothConnectionIntents.filter {
            bluetoothActionsPending.contains($0.key) || (known.contains($0.key) && $0.value.deadline > now)
        }
        return sortedBluetooth(resolved)
    }

    /// Method rather than a direct subscript write so the request can be
    /// dropped from a plain main-queue closure, matching how the surrounding
    /// IOBluetooth work already hops back.
    func clearBluetoothIntent(for address: String) {
        bluetoothConnectionIntents[address] = nil
    }

    func toggleBluetooth(_ item: BluetoothDeviceInfo) {
        let address = item.address
        guard bluetoothActionsPending.insert(address).inserted else { return }
        let disconnect = item.connected
        let requested = !item.connected
        bluetoothConnectionIntents[address] = BluetoothConnectionIntent(
            connected: requested,
            deadline: Date().addingTimeInterval(bluetoothIntentTimeout)
        )
        // Show the requested state immediately, and reorder now rather than on
        // the first reconcile -- one move, caused by the tap the user just made,
        // instead of a row that jumps a second later on its own.
        bluetoothDevices = sortedBluetooth(bluetoothDevices.map {
            $0.id == item.id
                ? BluetoothDeviceInfo(
                    address: $0.address,
                    name: $0.name,
                    connected: requested,
                    paired: $0.paired,
                    nearby: $0.nearby
                )
                : $0
        })
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let succeeded: Bool
            if blueutilExecutablePath() != nil {
                let paired = item.paired || disconnect || runBlueutil(["--pair", address], timeout: 12)
                succeeded = paired && runBlueutil([disconnect ? "--disconnect" : "--connect", address], timeout: 10)
            } else if let device = IOBluetoothDevice(addressString: address) {
                succeeded = (disconnect ? device.closeConnection() : device.openConnection()) == kIOReturnSuccess
            } else {
                succeeded = false
            }
            DispatchQueue.main.async {
                guard let self else { return }
                self.bluetoothActionsPending.remove(address)
                self.clearBluetoothIntent(for: address)
                if succeeded {
                    self.bluetoothConnectionIntents[address] = BluetoothConnectionIntent(
                        connected: requested, deadline: Date().addingTimeInterval(bluetoothIntentTimeout)
                    )
                } else {
                    // Restore the last observed state instead of keeping a
                    // failed request selected for the entire settle interval.
                    self.bluetoothDevices = self.sortedBluetooth(self.bluetoothDevices.map {
                        $0.id == item.id ? item : $0
                    })
                    MacPlusPlusBoundaryLog.record("Bluetooth connection action failed")
                    self.onStateToast?(MacPlusPlusStateToast(
                        title: "Bluetooth", detail: "Could not \(disconnect ? "disconnect" : "connect") \(item.name)",
                        symbol: "exclamationmark.circle"
                    ))
                }
                for delay in bluetoothSettleSchedule {
                    DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                        self?.refreshBluetoothDevices(force: true)
                    }
                }
            }
        }
    }
    // Weather changes on the order of tens of minutes, and this is a
    // third-party public endpoint, so it is polled far more slowly than
    // anything sampled locally -- every 15 minutes, and never on the 2s
    // refresh tick that drives the local telemetry.
    func refreshWeather(force: Bool = false, requestLocation: Bool = true) {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.location") else {
            weatherTask?.cancel()
            weatherTask = nil
            weather = WeatherSnapshot()
            return
        }
        if weatherTask != nil {
            guard force else { return }
            weatherTask?.cancel()
        }
        let now = Date()
        guard force || (now.timeIntervalSince(lastWeatherRefresh) >= 900 && now >= weatherRetryAfter) else { return }
        if requestLocation { locationProvider.requestLocation() }
        let latitude = weatherLatitude
        let longitude = weatherLongitude
        weatherGeneration &+= 1
        let generation = weatherGeneration
        weatherTask = Task { [weak self] in
            // URLSession suspends here rather than blocking the shell's main
            // actor. A generation boundary prevents an older IP fallback or
            // cancelled coordinate request from overwriting the newest card.
            guard let snapshot = await Self.fetchWeather(latitude: latitude, longitude: longitude) else {
                guard let self, self.weatherGeneration == generation else { return }
                self.weatherRetryAfter = Date().addingTimeInterval(60)
                self.weatherTask = nil
                return
            }
            guard let self, !Task.isCancelled, self.weatherGeneration == generation else { return }
            if self.weather != snapshot {
                withAnimation(ShellMotion.contentIn.animation) { self.weather = snapshot }
            }
            // Only a successful response starts the normal 15-minute window;
            // failures retry after a short bounded backoff instead of making
            // the card stale for the full polling interval.
            self.lastWeatherRefresh = Date()
            self.weatherRetryAfter = .distantPast
            self.weatherTask = nil
        }
    }

    private static func fetchWeather(latitude requested: Double?, longitude requestedLongitude: Double?) async -> WeatherSnapshot? {
        let latitude = requested
        let longitude = requestedLongitude
        let place = ""
        guard let latitude, let longitude,
              latitude.isFinite, longitude.isFinite,
              (-90...90).contains(latitude), (-180...180).contains(longitude)
        else { return nil }
        var components = URLComponents(string: "https://api.open-meteo.com/v1/forecast")
        components?.queryItems = [
            URLQueryItem(name: "latitude", value: String(format: "%.3f", latitude)),
            URLQueryItem(name: "longitude", value: String(format: "%.3f", longitude)),
            URLQueryItem(name: "current", value: "temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,weather_code,is_day"),
            URLQueryItem(name: "daily", value: "temperature_2m_max,temperature_2m_min"),
            URLQueryItem(name: "timezone", value: "auto"),
            URLQueryItem(name: "forecast_days", value: "1")
        ]
        guard let url = components?.url else { return nil }
        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            guard (response as? HTTPURLResponse)?.statusCode == 200,
                  let object = try JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let current = object["current"] as? [String: Any],
                  let daily = object["daily"] as? [String: Any],
                  let temperature = current["temperature_2m"] as? NSNumber,
                  let apparent = current["apparent_temperature"] as? NSNumber,
                  let humidity = current["relative_humidity_2m"] as? NSNumber,
                  let windSpeed = current["wind_speed_10m"] as? NSNumber,
                  let code = current["weather_code"] as? NSNumber,
                  let isDay = current["is_day"] as? NSNumber,
                  let highValues = daily["temperature_2m_max"] as? [Any],
                  let high = highValues.first as? NSNumber,
                  let lowValues = daily["temperature_2m_min"] as? [Any],
                  let low = lowValues.first as? NSNumber
            else { return nil }
            return WeatherSnapshot(
                temperature: temperature.doubleValue,
                apparent: apparent.doubleValue,
                high: high.doubleValue,
                low: low.doubleValue,
                humidity: humidity.intValue,
                windSpeed: windSpeed.doubleValue,
                code: code.intValue,
                place: place.uppercased(),
                isDay: isDay.intValue == 1,
                loaded: true
            )
        } catch {
            return nil
        }
    }
    func refreshConnectivity(
        force: Bool = false,
        includeNearbyInventory: Bool = false
    ) {
        let wifiControlsEnabled = UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi")
        let allowNearbyScan = wifiControlsEnabled
            && UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi-nearby-scan")
        let includeNearbyInventory = includeNearbyInventory && allowNearbyScan
        if connectivityRefreshTask != nil {
            connectivityRefreshPending = connectivityRefreshPending || force
            connectivityNearbyRefreshPending = connectivityNearbyRefreshPending || includeNearbyInventory
            return
        }
        guard force || Date().timeIntervalSince(lastConnectivityRefresh) >= 10 else { return }
        lastConnectivityRefresh = Date()
        wifiScanning = includeNearbyInventory
        if includeNearbyInventory { wifiScanStatus = "SCANNING" }
        let mutationGeneration = connectivityMutationGeneration
        let shouldScanNearby = includeNearbyInventory
        connectivityRefreshTask = Task { [weak self] in
            let result = await Task.detached(priority: .utility) { () async -> ([KnownWiFiNetwork], String, String, Bool, String, Bool, Bool, String) in
                if !wifiControlsEnabled {
                    let vpnRaw = capturedCommand("/usr/sbin/scutil", ["--nc", "list"])
                    let lines = vpnRaw.split(separator: "\n").map(String.init).filter {
                        $0.localizedCaseInsensitiveContains("VPN:")
                    }
                    let line = lines.first ?? ""
                    let quoted = line.split(separator: "\"")
                    let vpn = quoted.count > 1 ? String(quoted[1]) : ""
                    let vpnIsConnected = line.range(
                        of: #"\(Connected\)"#,
                        options: [.regularExpression, .caseInsensitive]
                    ) != nil
                    return ([], "", vpn, vpnIsConnected, "—", false, false, "DISABLED IN SETUP")
                }
                let hardwareLines = capturedCommand("/usr/sbin/networksetup", ["-listallhardwareports"])
                    .split(separator: "\n").map(String.init)
                var wifiDevice = "en0"
                for index in hardwareLines.indices where hardwareLines[index].localizedCaseInsensitiveContains("Hardware Port: Wi-Fi") {
                    let next = hardwareLines.index(after: index)
                    if next < hardwareLines.endIndex,
                       let deviceRange = hardwareLines[next].range(of: "Device:") {
                        let candidate = hardwareLines[next][deviceRange.upperBound...]
                            .trimmingCharacters(in: .whitespacesAndNewlines)
                        if !candidate.isEmpty { wifiDevice = candidate }
                    }
                    break
                }
                var scannedNetworks = [KnownWiFiNetwork]()
                var scanSucceeded = false
                var scanFailure = ""
                // Read association independently from the scan. CoreWLAN can
                // return nearby APs while leaving the scan object's `ssid()`
                // empty, so this must happen even when the helper finds a
                // non-empty inventory and the retry path is skipped.
                var coreWiFiSSID = currentCoreWiFiSSID(interfaceName: wifiDevice)
                // Prefer the client's current interface, then the hardware
                // port resolved above. The named lookup can be nil during a
                // Wi-Fi wake even though the shared client already exposes
                // the live controller; silently treating that as an empty
                // scan was why this card could report zero networks while
                // macOS still had radio results.
                if shouldScanNearby {
                    var strongestByName: [String: KnownWiFiNetwork] = [:]
                    // The hardened app can see only the associated AP on this
                    // macOS build. Start with the isolated Apple CLI helper;
                    // retain the in-process framework as a fallback for older
                    // systems or an app bundle that has not installed the
                    // helper resource yet.
                    let helperScan = scanAppleWiFiCLI(interfaceName: wifiDevice)
                    scanSucceeded = helperScan.succeeded
                    scanFailure = helperScan.failure
                    if coreWiFiSSID.isEmpty { coreWiFiSSID = helperScan.ssid }
                    for network in helperScan.networks {
                        strongestByName[network.name] = network
                    }
                    if helperScan.networks.isEmpty {
                        // The first CoreWLAN result after wake/authorization
                        // can be only the associated AP. Keep the radio open
                        // for two short follow-up frames and union every
                        // result; this is the difference between showing one
                        // remembered network and showing the nearby inventory
                        // the phone can see.
                        for attempt in 0..<3 {
                            let scan = scanCoreWiFi(interfaceName: wifiDevice)
                            scanSucceeded = scanSucceeded || scan.succeeded
                            if !scan.failure.isEmpty { scanFailure = scan.failure }
                            if coreWiFiSSID.isEmpty { coreWiFiSSID = scan.ssid }
                            for network in scan.networks {
                                if let existing = strongestByName[network.name],
                                   (existing.signalStrength ?? Int.min) >= (network.signalStrength ?? Int.min) {
                                    continue
                                }
                                strongestByName[network.name] = network
                            }
                            if attempt < 2 {
                                // This is an async suspension, not a blocking
                                // sleep, so the detached worker does not pin a
                                // thread while airportd updates its scan cache.
                                try? await Task.sleep(for: .milliseconds(attempt == 0 ? 250 : 500)) // macpp:silent-ok cancellation stops the bounded Wi-Fi retry loop
                            }
                        }
                    }
                    scannedNetworks = strongestByName.values.sorted {
                        if $0.signalStrength != $1.signalStrength {
                            return ($0.signalStrength ?? Int.min) > ($1.signalStrength ?? Int.min)
                        }
                        return $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
                    }
                }
                if shouldScanNearby && scannedNetworks.isEmpty {
                    let airport = "/System/Library/PrivateFrameworks/Apple80211.framework/Versions/Current/Resources/airport"
                    if FileManager.default.isExecutableFile(atPath: airport) {
                        let scan = capturedCommand(airport, ["-s"])
                        for line in scan.split(separator: "\n").dropFirst() {
                            let row = String(line)
                            guard let bssid = row.range(
                                of: #"([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}"#,
                                options: .regularExpression
                            ) else { continue }
                            let name = row[..<bssid.lowerBound].trimmingCharacters(in: .whitespacesAndNewlines)
                            if !name.isEmpty, !scannedNetworks.contains(where: { $0.name == name }) {
                                scannedNetworks.append(KnownWiFiNetwork(name: name, nearby: true))
                            }
                        }
                    }
                }
                let networkLine = capturedCommand("/usr/sbin/networksetup", ["-getairportnetwork", wifiDevice])
                let networkPrefix = "Current Wi-Fi Network:"
                let trimmedNetworkLine = networkLine.trimmingCharacters(in: .whitespacesAndNewlines)
                let networkPrefixRange = trimmedNetworkLine.range(
                    of: networkPrefix,
                    options: [.caseInsensitive, .anchored]
                )
                let commandSSID = networkPrefixRange.map {
                    String(trimmedNetworkLine[$0.upperBound...])
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                } ?? ""
                func usableSSID(_ value: String) -> String {
                    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
                    let lowered = trimmed.lowercased()
                    guard !trimmed.isEmpty,
                          trimmed != "<redacted>",
                          !lowered.contains("not associated"),
                          !lowered.contains("ssid hidden"),
                          lowered != "unknown" else { return "" }
                    return trimmed
                }

                let wdutilSSID = ""
                let networkInfo = capturedCommand(
                    "/usr/sbin/scutil",
                    ["--nwi"],
                    timeout: 2
                )
                let interfaceReachable = wifiInterfaceIsReachable(wifiDevice, from: networkInfo)
                // `wdutil` and `system_profiler` are not reliable nearby
                // scanners on current macOS: the former reports only the
                // associated link and the latter can block behind a large,
                // privacy-redacted diagnostics payload. CoreWLAN's scan is
                // the live controller API; keep its result even when the
                // current SSID is the only visible AP and finish the hover
                // refresh promptly instead of displaying a stale spinner.
                let ipconfigSSID = ipconfigCurrentWiFiSSID(interfaceName: wifiDevice)
                let current = [ipconfigSSID, commandSSID, coreWiFiSSID, wdutilSSID]
                    .map(usableSSID)
                    .first(where: { !$0.isEmpty }) ?? ""
                let loweredNetworkLine = trimmedNetworkLine.lowercased()
                let explicitlyNotAssociated = loweredNetworkLine.contains("not associated")
                    || loweredNetworkLine.contains("not connected")
                // A valid `Current Wi-Fi Network:` response is the
                // association boundary. route(8) is intentionally not used:
                // it can keep en0 as the default interface after
                // disassociation and would resurrect a stale connected state.
                let networksetupReportsAssociation = networkPrefixRange != nil
                    && !explicitlyNotAssociated
                    && !loweredNetworkLine.contains("unknown")
                    && (!usableSSID(commandSSID).isEmpty
                        || commandSSID.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "<redacted>")
                let powerOutput = capturedCommand(
                    "/usr/sbin/networksetup",
                    ["-getairportpower", wifiDevice]
                )
                let powerOn = powerOutput.localizedCaseInsensitiveContains("on")
                let radioOff = powerOutput.localizedCaseInsensitiveContains("off")
                // On privacy-redacted macOS, networksetup can say "not
                // associated" while the Wi-Fi interface still owns the live
                // IPv4 route. Keep the indicator tied to transport
                // reachability in that case; the SSID can remain hidden.
                let connected = !radioOff && (
                    !current.isEmpty
                        || networksetupReportsAssociation
                        || interfaceReachable
                )
                let vpnRaw = capturedCommand("/usr/sbin/scutil", ["--nc", "list"])
                let lines = vpnRaw.split(separator: "\n").map(String.init).filter {
                    $0.localizedCaseInsensitiveContains("VPN:")
                }
                let line = lines.first ?? ""
                let quoted = line.split(separator: "\"")
                let vpn = quoted.count > 1 ? String(quoted[1]) : ""
                let vpnIsConnected = line.range(
                    of: #"\(Connected\)"#,
                    options: [.regularExpression, .caseInsensitive]
                ) != nil
                // Preserve a bounded full scan inventory for the count line;
                // `railWiFiNetworks` applies Caelestia's eight-row visual bound
                // at presentation time.
                let scanStatus: String
                if !shouldScanNearby {
                    scanStatus = "IDLE"
                } else if !scannedNetworks.isEmpty {
                    scanStatus = String(format: "FOUND %d", scannedNetworks.count)
                } else if scanSucceeded {
                    scanStatus = "SCAN COMPLETE • NO SSIDS"
                } else if !scanFailure.isEmpty {
                    scanStatus = "SCAN UNAVAILABLE"
                } else {
                    scanStatus = "SCAN UNAVAILABLE"
                }
                return (Array(scannedNetworks.prefix(64)), current, vpn, vpnIsConnected, wifiDevice, connected, powerOn, scanStatus)
            }.value
            guard let self, !Task.isCancelled else { return }
            if mutationGeneration == self.connectivityMutationGeneration, !self.wifiActionPending {
                // A status-only poll has no nearby inventory. Keep the last
                // scan visible when a connect/power action reconciles state.
                if shouldScanNearby {
                    self.knownNetworks = result.0
                    self.wifiScanStatus = result.7
                    if !result.0.isEmpty {
                        UserDefaults.standard.set(result.0.map(\.name), forKey: "cachedWiFiNetworks")
                    }
                } else if !wifiControlsEnabled {
                    self.knownNetworks = []
                    self.wifiScanStatus = result.7
                    UserDefaults.standard.removeObject(forKey: "cachedWiFiNetworks")
                    UserDefaults.standard.removeObject(forKey: "lastKnownWiFiSSID")
                }
                self.wifiConnected = result.5
                if result.5, !self.suppressWiFiSSIDFallback {
                    // Keep a previously confirmed name visible when the
                    // next privacy-redacted poll returns only transport
                    // reachability. A blank response is not a new SSID.
                    let displayedSSID = result.1.isEmpty
                        ? self.connectedNetwork
                        : result.1
                    self.connectedNetwork = displayedSSID
                    if !displayedSSID.isEmpty {
                        UserDefaults.standard.set(displayedSSID, forKey: "lastKnownWiFiSSID")
                    }
                } else {
                    // Never show the reconnect cache as if it were the live
                    // association. Keep it only while the radio still says it
                    // is connected but the SSID is privacy-redacted, so a
                    // later successful read can refresh it without a stale
                    // row surviving a real disconnection.
                    self.connectedNetwork = ""
                    if !result.5 { UserDefaults.standard.removeObject(forKey: "lastKnownWiFiSSID") }
                }
                self.vpnName = result.2; self.vpnConnected = result.3
                self.wifiInterface = result.4
                self.wifiOn = result.6
            }
            self.wifiScanning = false
            self.connectivityRefreshTask = nil
            if self.connectivityRefreshPending {
                let includeNearbyInventory = self.connectivityNearbyRefreshPending
                self.connectivityRefreshPending = false
                self.connectivityNearbyRefreshPending = false
                self.refreshConnectivity(force: true, includeNearbyInventory: includeNearbyInventory)
            }
        }
    }
    func connectWiFi(_ network: KnownWiFiNetwork) {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi"),
              wifiOn, !wifiActionPending else { return }
        // networksetup uses saved credentials. Unknown secured networks need
        // the native password flow; never mark a network connected on launch.
        performWiFiAction { interface in
            let result = runBoundedShellCommand(
                "/usr/sbin/networksetup", ["-setairportnetwork", interface, network.name], timeout: 15
            )
            // networksetup can print an association error and still exit 0.
            // Successful association is silent; SSIDs may be privacy-redacted.
            guard result.succeeded, result.output.isEmpty else {
                throw NSError(domain: "MacPlusPlusWiFi", code: 2,
                              userInfo: [NSLocalizedDescriptionKey:
                                "Could not connect. Check Wi-Fi settings."])
            }
            UserDefaults.standard.set(network.name, forKey: "lastKnownWiFiSSID")
        }
    }
    func disconnectWiFi() {
        guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.wifi"),
              wifiOn, !wifiActionPending else { return }
        wifiConnected = false
        connectedNetwork = ""
        UserDefaults.standard.removeObject(forKey: "lastKnownWiFiSSID")
        performWiFiAction { name in
            guard let interface = CWWiFiClient.shared().interface(withName: name) else {
                throw NSError(domain: "MacPlusPlusWiFi", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Wi-Fi is unavailable"])
            }
            interface.disassociate()
        }
    }
    func toggleVPN() {
        guard !vpnName.isEmpty else { return }
        connectivityMutationGeneration &+= 1
        let escaped = vpnName.replacingOccurrences(of: "'", with: "'\\''")
        run("/usr/sbin/scutil --nc \(vpnConnected ? "stop" : "start") '\(escaped)'")
        // Do not optimistically flip the switch; the next status read is the
        // only trustworthy state for a connection transition.
        lastConnectivityRefresh = .distantPast
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) { [weak self] in self?.refreshConnectivity(force: true) }
    }
    func focusSpace(_ index: Int) {
        guard (1...CaelestiaParityTokens.Sizes.workspaceCount).contains(index) else { return }
        guard workspaces.first(where: { $0.id == index })?.available == true else { return }
        // The rail can receive the same logical request from a click, a
        // scroll tail, and a helper app during the same WindowServer handoff.
        // Keep only a short same-target gate here: yabai queries can wait on
        // WindowServer, so the main-actor action path must never perform one.
        let now = Date()
        if lastWorkspaceFocusIndex == index,
           now.timeIntervalSince(lastWorkspaceFocusRequestAt) < 0.32 {
            return
        }
        lastWorkspaceFocusIndex = index
        lastWorkspaceFocusRequestAt = now
        currentWorkspace = index
        _ = runMacPlusPlusYabai(["-m", "space", "--focus", macppWorkspaceLabels[index - 1]])
    }

    private func requestWindowlessApplicationReopen(_ application: AppRailApplication) {
        guard !application.bundlePath.isEmpty,
              FileManager.default.fileExists(atPath: application.bundlePath) else { return }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        configuration.createsNewApplicationInstance = false
        // Launch Services sends the app's normal reopen event here. Some apps
        // handle that by creating their last document window; the New Window
        // shortcut below is the fallback for apps that only respond to it.
        NSWorkspace.shared.openApplication(
            at: URL(fileURLWithPath: application.bundlePath),
            configuration: configuration,
            completionHandler: nil
        )
    }

    func focusApp(_ application: AppRailApplication, windowID: Int? = nil) {
        guard let running = NSRunningApplication(processIdentifier: application.id),
              !running.isTerminated else { return }
        if application.windows.isEmpty {
            // Activation alone cannot create a window after the user closed
            // the app's last document. Reopen through Launch Services first,
            // then use the app's normal New Window command as a fallback.
            requestWindowlessApplicationReopen(application)
            sendAppShortcut(application, keyCode: CGKeyCode(kVK_ANSI_N))
            return
        }

        let targetWindowID = windowID
            ?? application.windows.first(where: { !$0.isMinimized })?.id
            ?? application.windows.first?.id
        running.activate(options: [.activateAllWindows])
        if let targetWindowID {
            if application.windows.first(where: { $0.id == targetWindowID })?.isMinimized == true {
                // NSRunningApplication.activate does not reliably deminiaturize
                // yabai-managed windows, especially when the app owns several
                // spaces. Restore the exact target before asking yabai to focus it.
                _ = runMacPlusPlusYabai(
                    ["-m", "window", String(targetWindowID), "--deminimize"],
                    waitUntilExit: true
                )
            }
            _ = runMacPlusPlusYabai(["-m", "window", String(targetWindowID), "--focus"])
        } else {
            running.activate(options: [.activateAllWindows])
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            self?.refreshAppRailApplications(force: true)
        }
    }

    func hideApp(_ application: AppRailApplication) {
        guard let running = NSRunningApplication(processIdentifier: application.id),
              !running.isTerminated else { return }
        running.hide()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            self?.refreshAppRailApplications(force: true)
        }
    }

    func quitApp(_ application: AppRailApplication, force: Bool = false) {
        guard let running = NSRunningApplication(processIdentifier: application.id),
              !running.isTerminated else { return }
        if force {
            running.forceTerminate()
        } else {
            running.terminate()
        }
        for delay in [0.25, 0.8, 1.5] {
            DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                self?.refreshAppRailApplications(force: true)
            }
        }
    }

    func openNewWindow(for application: AppRailApplication) {
        sendAppShortcut(application, keyCode: CGKeyCode(kVK_ANSI_N))
    }

    func openNewTab(for application: AppRailApplication) {
        guard application.supportsNewTab else { return }
        sendAppShortcut(application, keyCode: CGKeyCode(kVK_ANSI_T))
    }

    private func sendAppShortcut(_ application: AppRailApplication, keyCode: CGKeyCode) {
        guard let running = NSRunningApplication(processIdentifier: application.id),
              !running.isTerminated else { return }
        running.activate(options: [.activateAllWindows])
        // Give WindowServer one turn to make the target app key before posting
        // the command. This keeps the action attached to the selected app
        // instead of the nonactivating Shell panel that contains the button.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) {
            guard !running.isTerminated else { return }
            postAppCommandShortcut(keyCode)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
            self?.refreshAppRailApplications(force: true)
        }
    }

    func beginWindowDrag(_ windowID: Int) {
        guard windowID > 0 else { return }
        activeWindowDragID = windowID
        macppWindowDragLog("begin id=\(windowID)")
        onWindowDragStart?(windowID)
    }
    func clearWindowDrag() {
        activeWindowDragID = nil
        workspaceDropTarget = nil
    }

    func moveWindow(_ windowID: Int, toSpace target: Int) {
        guard windowID > 0, (1...CaelestiaParityTokens.Sizes.workspaceCount).contains(target) else { return }
        guard workspaces.first(where: { $0.id == target })?.available == true else { return }
        let labels = macppWorkspaceLabels
        // Launch yabai directly with argv rather than sending the move through
        // a shell command. This dispatches the summon immediately when the
        // drag destination releases, and keeps the window id/space label as
        // typed arguments at the yabai boundary.
        let label = labels[target - 1]
        macppWindowDragLog("move id=\(windowID) target=\(label)")
        activeWindowDragID = nil
        workspaceDropTarget = nil
        onWindowDragEnd?()

        // Run the move as a short ordered transaction off the shell's main
        // actor. Moving a window should be non-activating: the old path
        // explicitly focused the destination space and then the moved window,
        // which made the whole screen jump away from the user's current tab.
        // Capture the visible space first so yabai's own automatic follow
        // behaviour (which varies slightly by layout/configuration) can be
        // neutralised without ever focusing the moved window.
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let origin = macppFocusedSpaceLabel()
            let moved = runMacPlusPlusYabai(
                ["-m", "window", String(windowID), "--space", label], waitUntilExit: true
            )
            if moved, let origin {
                _ = runMacPlusPlusYabai(["-m", "space", "--focus", origin], waitUntilExit: true)
            }
            DispatchQueue.main.async { [weak self] in
                self?.refreshWorkspaceApps()
            }
        }
    }
    func acceptWindowDrop(_ providers: [NSItemProvider], toSpace target: Int) -> Bool {
        guard let provider = providers.first else {
            // A native top-panel destination can complete a drag even when
            // AppKit hands its pasteboard to us after the provider array has
            // already been released. The source ID is still authoritative
            // because MacPlusPlus created the drag itself.
            if let windowID = activeWindowDragID {
                macppWindowDragLog("swift-drop no-provider fallback id=\(windowID) target=\(target)")
                moveWindow(windowID, toSpace: target)
                return true
            }
            return false
        }
        macppWindowDragLog("swift-drop target=\(target) types=\(provider.registeredTypeIdentifiers.joined(separator: ","))")

        // SwiftUI's NSItemProvider can advertise public.utf8-plain-text,
        // public.plain-text, or public.text depending on the macOS release.
        // Asking for only public.text made the drop look accepted while the
        // completion handler never received a value. Try every text
        // representation, and consume the first valid MacPlusPlus payload exactly
        // once. This is deliberately provider-only: no delayed mouse-up or
        // second click is required to commit the move.
        let advertisedTypes = provider.registeredTypeIdentifiers.filter { identifier in
            guard let type = UTType(identifier) else { return false }
            return type.conforms(to: .text)
        }
        let candidateTypes = advertisedTypes.isEmpty ? [
            UTType.utf8PlainText.identifier,
            UTType.plainText.identifier,
            UTType.text.identifier
        ] : advertisedTypes
        let lock = NSLock()
        var consumed = false
        let finish: (String?) -> Void = { [weak self] raw in
            guard let raw,
                  raw.hasPrefix("macpp-window:"),
                  let windowID = Int(raw.dropFirst("macpp-window:".count)) else { return }
            lock.lock()
            guard !consumed else { lock.unlock(); return }
            consumed = true
            lock.unlock()
            macppWindowDragLog("swift-drop payload id=\(windowID) target=\(target)")
            Task { @MainActor in
                self?.workspaceDropTarget = nil
                self?.onWindowDragEnd?()
                self?.moveWindow(windowID, toSpace: target)
            }
        }
        for typeIdentifier in candidateTypes {
            provider.loadItem(forTypeIdentifier: typeIdentifier, options: nil) { item, _ in
                let raw: String? = {
                    if let text = item as? String { return text }
                    if let text = item as? NSString { return text as String }
                    if let data = item as? Data { return String(data: data, encoding: .utf8) }
                    if let data = item as? NSData { return String(data: data as Data, encoding: .utf8) }
                    return nil
                }()
                finish(raw)
            }
        }
        return true
    }
    func refreshWorkspace(forceRefresh: Bool = false) {
        guard workspaceFocusRefreshTask == nil else {
            workspaceFocusRefreshPending = true
            workspaceFocusRefreshForcePending = workspaceFocusRefreshForcePending || forceRefresh
            return
        }
        workspaceFocusRefreshGeneration &+= 1
        let generation = workspaceFocusRefreshGeneration
        workspaceFocusRefreshTask = Task { [weak self] in
            let next = await Task.detached(priority: .utility) { () -> Int? in
                macppFocusedSpaceIndex(forceRefresh: forceRefresh)
            }.value
            guard !Task.isCancelled, let self,
                  self.workspaceFocusRefreshGeneration == generation else { return }
            guard let next else {
                self.workspaceFocusRefreshTask = nil
                self.refreshPendingWorkspaceFocusIfNeeded()
                return
            }
            // A Space-change notification can arrive while a fallback query
            // is finishing. Do not animate its potentially stale answer and
            // then move the indicator again; let the queued forced snapshot
            // commit the destination once.
            if self.workspaceFocusRefreshForcePending {
                self.workspaceFocusRefreshTask = nil
                self.refreshPendingWorkspaceFocusIfNeeded()
                return
            }
            if self.currentWorkspace != next {
                withAnimation(ShellMotion.workspaceIndicator.animation) { self.currentWorkspace = next }
            }
            self.workspaceFocusRefreshTask = nil
            self.refreshPendingWorkspaceFocusIfNeeded()
        }
    }
    private func refreshPendingWorkspaceFocusIfNeeded() {
        guard workspaceFocusRefreshPending else { return }
        let forceRefresh = workspaceFocusRefreshForcePending
        workspaceFocusRefreshPending = false
        workspaceFocusRefreshForcePending = false
        refreshWorkspace(forceRefresh: forceRefresh)
    }
    func openURL(_ raw: String) { if let url = URL(string: raw) { NSWorkspace.shared.open(url) } }
    func openWiFiSettings() { openURL("x-apple.systempreferences:com.apple.wifi-settings-extension") }
    func openSoftLockOverlay() {
        onStateToast?(MacPlusPlusStateToast(
            title: "Soft Lock Not Included",
            detail: "This public profile only offers the native macOS Lock Screen action",
            symbol: "lock"
        ))
    }
    func lockScreen() {
        let lockSession = "/System/Library/CoreServices/Menu Extras/User.menu/Contents/Resources/CGSession"
        _ = runBoundedShellCommand(lockSession, ["-suspend"], timeout: 3)
    }
    func performPower(_ command: PowerCommand) {
        switch command {
        case .screensaver:
            let url = URL(fileURLWithPath: "/System/Library/CoreServices/ScreenSaverEngine.app")
            NSWorkspace.shared.openApplication(at: url, configuration: .init())
        case .lock: lockScreen()
        case .softOverlay: openSoftLockOverlay()
        case .logout:
            // The old primary attempt sent a raw AppleEvent straight to
            // "loginwindow" (aevtrlgo/aevtslep/aevtshut/aevtrrst). osascript
            // returns exit code 0 for that even when loginwindow silently
            // ignores it, so the `||` fallback never ran and the button
            // quietly did nothing. System Events' documented verbs are the
            // reliable path -- use them directly instead of as a fallback.
            run("/usr/bin/osascript -e 'tell application \"System Events\" to log out'")
        case .sleep:
            // pmset needs no Automation permission and reliably sleeps the
            // machine, unlike the old loginwindow AppleEvent trick.
            run("/usr/bin/pmset sleepnow")
        case .displayOff:
            run("/usr/bin/pmset displaysleepnow")
        case .shutdown:
            run("/usr/bin/osascript -e 'tell application \"System Events\" to shut down'")
        case .restart:
            run("/usr/bin/osascript -e 'tell application \"System Events\" to restart'")
        }
    }
    func openNotifications() {
        // Menu extras are user-reorderable, so this looks the clock up by its
        // accessibility identifier rather than by position.
        //
        // Two things made the previous version fail invisibly. It ran through
        // `run(_:)`, which is `try? process.run()` with no pipes -- so a
        // refused Automation/Accessibility permission, a renamed identifier or
        // a missing process all produced exactly the same silent no-op. And it
        // had a single strategy: if `com.apple.menuextra.clock` ever stops
        // matching, there was nothing else to try. This version falls back to
        // the rightmost menu extra (which is where the clock lives) and writes
        // the outcome to a log, so a future break is diagnosable instead of
        // just "the button stopped working".
        let script = """
        on run
          tell application "System Events"
            if not (exists process "ControlCenter") then return "no-controlcenter"
            tell process "ControlCenter"
              try
                click (first menu bar item of menu bar 1 whose value of attribute "AXIdentifier" is "com.apple.menuextra.clock")
                return "ok-identifier"
              end try
              try
                click (last menu bar item of menu bar 1)
                return "ok-last"
              end try
            end tell
          end tell
          return "failed"
        end run
        """
        DispatchQueue.global(qos: .userInitiated).async {
            let process = Process()
            let output = Pipe(), errors = Pipe()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
            process.arguments = ["-e", script]
            process.standardOutput = output
            process.standardError = errors
            guard (try? process.run()) != nil else { return } // macpp:silent-ok unavailable osascript cannot provide a notification dismissal status
            let result = String(data: output.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let failure = String(data: errors.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            process.waitUntilExit()
            let status = result.trimmingCharacters(in: .whitespacesAndNewlines)
            guard status != "ok-identifier", status != "ok-last" else { return }
            let log = FileManager.default.homeDirectoryForCurrentUser
                .appendingPathComponent("Library/Logs/macpp-notifications.log")
            let entry = "[\(Date())] status=\(status.isEmpty ? "(none)" : status) "
                + "stderr=\(failure.trimmingCharacters(in: .whitespacesAndNewlines))\n"
            if let data = entry.data(using: .utf8) {
                if let handle = try? FileHandle(forWritingTo: log) { // macpp:silent-ok notification diagnostics are best effort and do not affect dismissal
                    handle.seekToEndOfFile(); handle.write(data); try? handle.close() // macpp:silent-ok closing the diagnostic file is best effort
                } else {
                    try? data.write(to: log) // macpp:silent-ok notification diagnostics are best effort
                }
            }
        }
    }

    @discardableResult
    private func run(_ command: String) -> Bool {
        let executable = command.split(whereSeparator: \.isWhitespace).first.map(String.init) ?? "unknown"
        return launchMacPlusPlusShellCommand(
            command, context: "shell:\((executable as NSString).lastPathComponent)"
        )
    }
    private func isSpotifyMedia(_ state: MediaState) -> Bool {
        MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Spotify",
            source: state.source,
            device: state.device
        )
    }
    /// Whether the current source is browser media, which has no track list.
    ///
    /// The side buttons still do something useful there -- they seek -- but
    /// labelling that with next/previous-track glyphs promises a behaviour the
    /// page cannot deliver, so the controls say what they actually do.
    var mediaSeeksInsteadOfSkipping: Bool {
        MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Safari",
            source: media.source,
            device: media.device
        ) || MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Browser",
            source: media.source,
            device: media.device
        )
    }

    /// The page helper is intentionally Safari-only. Generic browser media may
    /// still use seek transport, but must not mutate an unrelated Safari tab.
    var safariCinemaAvailable: Bool {
        MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Safari",
            source: media.source,
            device: media.device
        )
    }

    /// Cinema mutates a Safari page and its window, so its controls must not
    /// survive a media-source handoff to Spotify.  The explicit preference is
    /// included because the media card can temporarily show the cached
    /// Spotify source before the producer fields catch up.
    var cinemaControlAvailable: Bool {
        guard preferredMediaSource != "spotify", !isSpotifyMedia(media) else { return false }
        return safariCinemaAvailable || cinemaPresentation != nil
    }

    var cinemaControlHelp: String {
        if cinemaMutationInFlight { return cinemaOperationLabel }
        if let active = cinemaPresentation {
            return "Cinema \(active.title) is active · click to restore · Option-click for \(active.next.title)"
        }
        return "Start Cinema \(preferredCinemaPresentation.title) · Option-click for \(preferredCinemaPresentation.next.title)"
    }

    /// The specific owner identities retained for the now-playing debug file.
    /// Empty when the producer has no opinion.
    private var reportedMediaOwner: String {
        MacPlusPlusPureLogic.mediaOwnerDescription(source: media.source, device: media.device)
    }

    /// Whether `app` is the one currently producing audio.
    ///
    /// Ordering matters here, and I had it backwards. CoreAudio's
    /// `IsRunningOutput` only means a process *holds* output IO -- Spotify
    /// keeps its audio unit alive while paused, so it sits in that set forever
    /// and claimed the indicator while something else was actually playing.
    /// It cannot distinguish playing from merely-open, because CoreAudio
    /// exposes no per-process output level.
    ///
    /// The producer can: it reads Spotify's transport over AppleScript and
    /// Safari's over its own JavaScript, so for the app it reports on it knows
    /// genuinely whether audio is advancing. That makes it the authority, and
    /// CoreAudio the fallback for apps it cannot see at all -- a game, VLC,
    /// anything without a scripting interface.
    func isNowPlayingApp(_ app: String) -> Bool {
        let target = Self.mediaMatchToken(app)
        guard !target.isEmpty else { return false }
        // 1. The producer named this app and says it is playing.
        if MacPlusPlusPureLogic.mediaOwnerMatches(
            application: app,
            source: media.source,
            device: media.device
        ) { return media.playing }

        // 2. The producer named a *different* app. Trust it: it has real
        //    transport state and CoreAudio does not, so a second app merely
        //    holding the device must not also light up.
        if MacPlusPlusPureLogic.hasSpecificMediaOwner(
            source: media.source,
            device: media.device
        ), media.playing { return false }

        // 3. The producer has no opinion. Fall back to who holds output IO,
        //    which is the best available signal for apps it cannot inspect.
        //
        // Browser/Electron output runs in helpers such as "Safari Graphics and
        // Media" or "Discord Helper".  MacPlusPlusPureLogic permits those through a
        // small named prefix table; unknown apps remain exact matches so
        // "Music" cannot accidentally claim a process called "MusicBox".
        return audioOutputApps.contains { candidate in
            MacPlusPlusPureLogic.audioProcessMatches(application: app, process: candidate)
        }
    }

    /// Lowercased and stripped of everything but letters and digits, so
    /// "Google Chrome" and "google chrome" compare equal.
    private static func mediaMatchToken(_ value: String) -> String {
        MacPlusPlusPureLogic.mediaToken(value)
    }

    private func cacheSpotifyMedia(_ candidate: MediaState) -> MediaState {
        var cached = candidate
        // Queue context belongs to the provider that supplied it. Never let a
        // Safari/YouTube item or caption URL follow a Spotify handoff.
        cached.upNext = nil
        cached.transcriptURL = ""
        // Spotify's AppleScript metadata has reliable timing but no artwork.
        // Retain the last cover instead of letting a browser handoff erase it.
        if cached.artworkURL.isEmpty, let previous = spotifyMediaFallback {
            cached.artworkURL = previous.artworkURL
            cached.artworkRevision = previous.artworkRevision
        }
        spotifyMediaFallback = cached
        return cached
    }

    private func clearStaleMedia() {
        let now = Date()
        if media.playing && now.timeIntervalSince(lastValidMediaRefresh) < 4 {
            return
        }
        if let fallback = pausedSpotifyFallback(), media != fallback {
            media = fallback
        } else if media != MediaState() {
            media = MediaState()
        }
        pendingMediaClearSince = nil
    }

    private func pausedSpotifyFallback() -> MediaState? {
        guard Date().timeIntervalSince(lastValidMediaRefresh) < Self.mediaFallbackMaxAge else {
            return nil
        }
        guard var fallback = spotifyMediaFallback else { return nil }
        // If another provider took ownership, Spotify was implicitly paused.
        // Freeze the saved position and present a resume button on return.
        fallback.playing = false
        fallback.progress = fallback.duration > 0
            ? min(1, max(0, fallback.position / fallback.duration))
            : fallback.progress
        spotifyMediaFallback = fallback
        return fallback
    }

    private static func mediaNextItem(from value: Any?) -> MediaNextItem? {
        guard let item = value as? [String: Any],
              let title = (item["title"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines),
              !title.isEmpty else { return nil }
        let artist = (item["artist"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let album = (item["album"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let kind = (item["kind"] as? String ?? "UP NEXT").trimmingCharacters(in: .whitespacesAndNewlines)
        let url = (item["url"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return MediaNextItem(title: title, artist: artist, album: album, kind: kind, url: url)
    }

    private func readMedia() {
        guard let data = FileManager.default.contents(atPath: mediaPath),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { // macpp:silent-ok a transient media read leaves the previous UI state intact
            // The producer refreshes once per second. A transient read failure
            // must not tear the rail title down between two valid samples.
            clearStaleMedia()
            return
        }
        let rawTitle = (json["track"] ?? json["title"]) as? String ?? ""
        let rawArtist = (json["artist"] ?? json["source"]) as? String ?? ""
        let title = rawTitle
        let artist = rawArtist == "none" ? "" : rawArtist
        let album = json["album"] as? String ?? ""
        let artwork = json["artwork_url"] as? String ?? ""
        let source = json["source"] as? String ?? ""
        let device = json["device"] as? String ?? ""
        let upNext = Self.mediaNextItem(from: json["up_next"])
        let transcriptURL = (json["transcript_url"] as? String ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let mediaURL = (json["track_id"] as? String ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let handoffGraceActive = (json["handoff_grace"] as? Bool) ?? false
        let state = (json["state"] as? String)?.lowercased()
        let playing = (json["playing"] as? Bool) ?? (state == "playing")
        let rawPosition = (json["position"] as? NSNumber)?.doubleValue ?? 0
        let rawDuration = (json["duration"] as? NSNumber)?.doubleValue ?? 0
        let producerMarkedDurationKnown = (json["duration_known"] as? Bool)
        let producerMarkedLive = (json["is_live"] as? Bool) ?? false
        let durationValueIsPlausible = rawDuration.isFinite
            && rawDuration > 0
            && rawDuration <= Self.mediaMaximumDuration
        let durationKnown = durationValueIsPlausible
            && (producerMarkedDurationKnown ?? true)
            && !producerMarkedLive
        let duration = durationKnown ? rawDuration : 0
        let sampledPosition = rawPosition.isFinite
            && rawPosition >= 0
            && rawPosition <= Self.mediaMaximumPosition
            ? rawPosition
            : 0
        let isLive = producerMarkedLive
            || (!durationKnown
                && source.lowercased() == "safari"
                && (!rawDuration.isFinite || rawDuration > Self.mediaMaximumDuration))
        let now = Date()
        let updatedAt = (json["updated_at"] as? NSNumber)?.doubleValue ?? now.timeIntervalSince1970
        let snapshotAge = max(0, now.timeIntervalSince1970 - updatedAt)
        if snapshotAge > Self.mediaSnapshotMaxAge {
            // A syntactically valid JSON file can outlive the watcher after a
            // launchd/Automation failure. Treat its last frame like a read
            // failure instead of continually presenting stale playback.
            clearStaleMedia()
            return
        }
        let sampleAge = playing ? min(2.5, snapshotAge) : 0
        let position = duration > 0 ? min(duration, sampledPosition + sampleAge) : sampledPosition
        let liveProgress = duration > 0 ? min(1, max(0, position / duration)) : 0
        let artworkRevision: String = {
            let metadata = "\(title)|\(artist)|\(album)"
            guard let url = URL(string: artwork), url.isFileURL,
                  let attributes = try? FileManager.default.attributesOfItem(atPath: url.path) else { // macpp:silent-ok missing artwork metadata falls back to the track identity
                return metadata
            }
            let modified = (attributes[.modificationDate] as? Date)?.timeIntervalSinceReferenceDate ?? 0
            let bytes = (attributes[.size] as? NSNumber)?.int64Value ?? 0
            return "\(metadata)|\(modified)|\(bytes)"
        }()
        var next = MediaState(title: title, artist: artist, album: album, artworkURL: artwork,
                              artworkRevision: artworkRevision, source: source, device: device,
                              upNext: upNext, transcriptURL: transcriptURL, mediaURL: mediaURL,
                              playing: playing, progress: liveProgress,
                              position: position, duration: duration,
                              durationKnown: durationKnown, isLive: isLive)
        if let optimisticPlaybackState, Date() < optimisticPlaybackUntil {
            next.playing = optimisticPlaybackState
        } else if optimisticPlaybackState != nil {
            self.optimisticPlaybackState = nil
        }
        let hasTitle = !title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        if hasTitle && isSpotifyMedia(next) {
            next = cacheSpotifyMedia(next)
            lastValidMediaRefresh = Date()
            pendingMediaClearSince = nil
        } else if playing && hasTitle {
            systemMediaFallback = next
            lastValidMediaRefresh = Date()
            pendingMediaClearSince = nil
            // Non-Spotify playback owns the card while it is active. A
            // producer-marked Safari grace frame is handled immediately below.
        } else if handoffGraceActive && hasTitle {
            // The producer owns a short Safari -> Spotify grace window. Keep
            // the paused Safari card visible during that window instead of
            // applying the old immediate local fallback below.
            systemMediaFallback = next
            lastValidMediaRefresh = Date()
            pendingMediaClearSince = nil
        } else if let fallback = pausedSpotifyFallback() {
            next = fallback
            pendingMediaClearSince = nil
        } else if media.playing && !media.title.isEmpty {
            // Spotify and MPNowPlayingInfoCenter occasionally publish one or
            // two empty frames while handing off tracks. Keep the existing
            // title until the empty state has remained stable long enough to
            // be intentional.
            if pendingMediaClearSince == nil { pendingMediaClearSince = Date() }
            if Date().timeIntervalSince(pendingMediaClearSince ?? Date()) < 3 { return }
            pendingMediaClearSince = nil
        }

        switch preferredMediaSource {
        case "spotify":
            if !isSpotifyMedia(next), let fallback = spotifyMediaFallback { next = fallback }
        case "system":
            // A persisted source choice must not turn a valid live producer
            // frame into an empty card just because the selected source is
            // currently unavailable.  After a Shell restart the system
            // fallback is commonly rebuilt a moment after the shared media
            // producer has already published Spotify, so keep that valid
            // Spotify frame until a real system source is available.
            if isSpotifyMedia(next), let fallback = systemMediaFallback {
                next = fallback
            }
        default:
            break
        }
        // Metadata and progress are sampled independently. Publishing them in
        // a global layout animation made artwork/title layers briefly rebuild
        // on every progress tick. Individual controls own their transitions.
        if media != next { media = next }
    }
    // `tempo_live` is computed by the helper at publish time and already folds
    // in confidence and a recent beat. The one thing it cannot account for is
    // its own process dying -- the last frame could still contain true tempo
    // metadata. The timestamp check in captureShellAudioFrame is therefore the
    // authority for whether this value is current.
    private func readTempo(live: Bool, value: Int) {
        if live, value > 0 {
            if bpm != value { bpm = value }
            if !bpmLive { bpmLive = true }
            lastTempoLock = Date()
            return
        }
        if bpmLive { bpmLive = false }
        // Holding the last value indefinitely is what produced a badge stuck
        // on one number forever: between tracks that reads as "paused", but
        // with a dead producer it is simply wrong and never recovers. After a
        // short grace period the reading is dropped entirely.
        if bpm != 0, Date().timeIntervalSince(lastTempoLock) > 12 { bpm = 0 }
    }

    private func requestAudioSample() {
        guard !audioReadInFlight else { return }
        audioReadInFlight = true
        Task { [weak self] in
            let frame = await Task.detached(priority: .userInitiated) {
                captureShellAudioFrame()
            }.value
            guard let self else { return }
            self.audioReadInFlight = false
            self.applyAudioFrame(frame)
        }
    }

    private func applyAudioFrame(_ frame: ShellAudioFrame) {
        readTempo(live: frame.available && frame.tempoLive, value: frame.bpm)
        audioWasActive = frame.active
        guard reactiveRequested else { return }

        let now = Date()
        guard frame.available && frame.producerLive else {
            // A seqlock retry or a producer restart is not a zero-energy audio
            // frame. Hold the last valid bars through a short gap, then decay
            // them gradually. This prevents one dropped shared-memory read
            // from looking like a frozen/reset visualizer while still making a
            // genuinely dead producer settle to the idle floor.
            let elapsed = lastAudioFrameAt == .distantPast
                ? 1.0
                : now.timeIntervalSince(lastAudioFrameAt)
            guard elapsed > 0.28 else { return }
            let idle = Array(repeating: 0.025, count: 42)
            let decay = min(0.34, max(0.06, 0.04 + elapsed * 0.08))
            let decayed = zip(levels, idle).map { current, target in
                current + (target - current) * decay
            }
            if zip(levels, decayed).contains(where: { abs($0 - $1) > 0.001 }) {
                levels = decayed
            }
            return
        }
        lastAudioFrameAt = now
        let candidates = frame.candidates
        guard !candidates.isEmpty else { return }
        // The capture helper publishes about eighteen spectrum frames per
        // second into shared memory. Interpolate its smaller band set across
        // the complete ring instead of repeating bins, then remove the
        // measured noise floor and use a gentle response curve that preserves
        // quiet detail without clipping ordinary peaks at full height.
        let interpolated = (0..<42).map { index -> Double in
            guard candidates.count > 1 else { return candidates[0] }
            let position = Double(index) * Double(candidates.count - 1) / 41.0
            let lower = Int(position.rounded(.down))
            let upper = min(candidates.count - 1, lower + 1)
            let fraction = position - Double(lower)
            return candidates[lower] * (1 - fraction) + candidates[upper] * fraction
        }
        let shaped = interpolated.map { sample -> Double in
            let normalized = max(0, min(1, (sample - 0.035) / 0.70))
            return max(0.025, pow(normalized, 0.72))
        }
        let spatiallySmoothed = shaped.indices.map { index -> Double in
            let previous = shaped[max(0, index - 1)]
            let current = shaped[index]
            let next = shaped[min(shaped.count - 1, index + 1)]
            return previous * 0.18 + current * 0.64 + next * 0.18
        }
        let smoothed = zip(levels, spatiallySmoothed).map { current, target in
            let response = target > current ? 0.72 : 0.26
            return current + (target - current) * response
        }
        // Per-bar scalar animations in SpectrumRing/ReactiveAlbumDisc fill
        // the 100 ms producer cadence. Keeping this assignment unanimated
        // avoids stacking an array-level animation on every incoming frame.
        if zip(levels, smoothed).contains(where: { abs($0 - $1) > 0.001 }) {
            levels = smoothed
        }
    }
    private func readSystem() {
        refreshOutputAudio()
        refreshInputAudio()
        refreshFocusState()
        refreshFocusAvailability()
        readBattery()
        let seconds = Int(ProcessInfo.processInfo.systemUptime)
        let nextUptime = "\(seconds / 3600)H \((seconds % 3600) / 60)M"
        if uptime != nextUptime { uptime = nextUptime }
        if let capacity = StorageCapacity.read() {
            let nextStorage = "\(capacity.availableBytes / 1_000_000_000) GB FREE"
            if storage != nextStorage { storage = nextStorage }
        }
    }
    private func refreshFrontApp() {
        guard let application = NSWorkspace.shared.frontmostApplication,
              application.bundleIdentifier != macppShellBundleIdentifier else { return }
        updateFrontApp(application)
    }
    private func updateFrontApp(_ application: NSRunningApplication) {
        guard application.bundleIdentifier != macppShellBundleIdentifier else { return }
        let name = application.localizedName ?? "Finder"
        if frontApp != name { frontApp = name }
        if let url = application.bundleURL {
            frontAppIcon = NSWorkspace.shared.icon(forFile: url.path)
            frontAppBundlePath = url.standardizedFileURL.path
        } else {
            frontAppBundlePath = ""
        }
        let pid = application.processIdentifier
        if frontAppPID != pid {
            frontAppPID = pid
            frontAppCPUPercent = 0
            frontAppMemoryBytes = 0
            frontAppUsageBaseline = nil
            if frontAppResourceSampling { refreshFrontAppResources() }
        }
    }

    func setFrontAppResourceSampling(_ enabled: Bool) {
        if frontAppResourceSampling == enabled {
            // A top-level panel can briefly become the frontmost application
            // while it is being presented.  In that window the shell is
            // deliberately ignored by refreshFrontApp(), so recover the
            // identity as soon as the dashboard asks for its live metrics.
            if enabled, frontAppPID == 0 {
                refreshFrontApp()
                refreshFrontAppResources()
            }
            return
        }
        frontAppResourceSampling = enabled
        frontAppResourceTimer?.invalidate()
        frontAppResourceTimer = nil
        frontAppResourceWarmupTask?.cancel()
        frontAppResourceWarmupTask = nil
        frontAppUsageBaseline = nil
        guard enabled else { return }
        refreshFrontApp()
        refreshFrontAppResources()
        frontAppResourceWarmupTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(250)) // macpp:silent-ok cancellation aborts the optional resource warmup
            guard !Task.isCancelled, let self, self.frontAppResourceSampling else { return }
            self.refreshFrontAppResources()
            self.frontAppResourceWarmupTask = nil
        }
        let timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.refreshFrontAppResources() }
        }
        timer.tolerance = 0.08
        RunLoop.main.add(timer, forMode: .common)
        frontAppResourceTimer = timer
    }

    private func refreshFrontAppResources() {
        var pid = frontAppPID
        if pid <= 0 {
            // A panel can briefly make Mac++ Shell the frontmost application
            // while the dashboard is being presented. Retry the non-shell
            // identity once before publishing the sentinel zero values.
            refreshFrontApp()
            pid = frontAppPID
            if pid <= 0 {
                frontAppCPUPercent = 0
                frontAppMemoryBytes = 0
                frontAppUsageBaseline = nil
                return
            }
        }

        // Sum the app process and its helper tree. The canonical dashboard
        // producer intentionally exposes individual processes for the
        // performance page; the active-app card needs the opposite view: one
        // application total. RSS is read directly instead of reconstructing
        // it from rounded `%mem`, which matters for smaller apps.
        if let aggregate = macppAppResourceSnapshot(
            pid: pid,
            bundlePath: frontAppBundlePath
        ) {
            frontAppCPUPercent = aggregate.cpuPercent
            frontAppMemoryBytes = aggregate.residentBytes
            frontAppUsageBaseline = nil
            return
        }

        // Prefer the same `ps` sample that powers the shared dashboard when
        // the active process is present in the canonical ranked set.  This
        // makes the per-app card agree with the Shell performance surfaces instead of
        // comparing a task-time delta against a process-list percentage.
        // Keep the task-info sampler as a fallback for a foreground process
        // that is outside the compact producer payload.
        if let sample = performanceProcesses.first(where: { $0.pid == Int(pid) }) {
            frontAppCPUPercent = max(0, sample.cpu)
            let totalMemory = Double(ProcessInfo.processInfo.physicalMemory)
            frontAppMemoryBytes = UInt64(max(0, min(totalMemory, sample.memory / 100 * totalMemory)))
            frontAppUsageBaseline = nil
            return
        }
        var info = proc_taskinfo()
        let bytes = proc_pidinfo(
            pid,
            PROC_PIDTASKINFO,
            0,
            &info,
            Int32(MemoryLayout<proc_taskinfo>.size)
        )
        guard bytes == MemoryLayout<proc_taskinfo>.size else {
            frontAppCPUPercent = 0
            frontAppMemoryBytes = 0
            frontAppUsageBaseline = nil
            return
        }
        frontAppMemoryBytes = info.pti_resident_size
        let total = info.pti_total_user &+ info.pti_total_system
        let timestamp = CACurrentMediaTime()
        if let baseline = frontAppUsageBaseline,
           baseline.pid == pid,
           timestamp > baseline.timestamp,
           total >= baseline.totalNanoseconds {
            let elapsedNanoseconds = (timestamp - baseline.timestamp) * 1_000_000_000
            let usedNanoseconds = Double(total - baseline.totalNanoseconds)
            frontAppCPUPercent = min(999, max(0, usedNanoseconds / elapsedNanoseconds * 100))
        } else {
            frontAppCPUPercent = 0
        }
        frontAppUsageBaseline = (pid, total, timestamp)
    }
    private func readBattery() {
        guard let state = SystemBattery.read() else { return }
        let previousCharging = charging
        if batteryPercent != state.percent { batteryPercent = state.percent; battery = "\(state.percent)%" }
        if charging != state.externalPower { charging = state.externalPower }
        if batteryTimeRemainingMinutes != state.timeRemainingMinutes { batteryTimeRemainingMinutes = state.timeRemainingMinutes }
        if let health = SystemBattery.health(externalPower: state.externalPower) {
            if batteryHealthPercent != health.healthPercent { batteryHealthPercent = health.healthPercent }
            if batteryCycleCount != health.cycleCount { batteryCycleCount = health.cycleCount }
            let watts = health.systemPowerMilliwatts.map { Double($0) / 1000 }
            if batterySystemPowerWatts != watts { batterySystemPowerWatts = watts }
            let adapterWatts = health.adapterWatts.map(Double.init)
            if batteryAdapterWatts != adapterWatts { batteryAdapterWatts = adapterWatts }
        }
        if batteryStateInitialized, previousCharging != state.externalPower {
            onStateToast?(MacPlusPlusStateToast(
                title: state.externalPower ? "Power Connected" : "On Battery",
                detail: state.externalPower
                    ? "Charging at \(state.percent)%"
                    : "\(state.percent)% remaining",
                symbol: state.externalPower ? "bolt.fill" : "battery.75percent"
            ))
        }
        batteryStateInitialized = true
        checkLowBatteryAlerts(percent: state.percent, charging: state.externalPower)
    }

    // A low battery needs a glanceable warning even when its detail popout is
    // closed. Route it through MacPlusPlus's independent state surface at 25% and
    // again at 5%, without reintroducing a stock banner.
    private func checkLowBatteryAlerts(percent: Int, charging: Bool) {
        if charging || percent > 25 {
            lowBatteryAlertedThreshold = nil
            return
        }
        let threshold = percent <= 5 ? 5 : 25
        guard lowBatteryAlertedThreshold != threshold, percent <= threshold else { return }
        lowBatteryAlertedThreshold = threshold
        onStateToast?(MacPlusPlusStateToast(
            title: threshold == 5 ? "Battery Critically Low" : "Battery Low",
            detail: "\(percent)% remaining\(threshold == 5 ? " — plug in now" : "")",
            symbol: threshold == 5 ? "exclamationmark.triangle.fill" : "battery.25percent",
            critical: threshold == 5,
            duration: threshold == 5 ? 6 : 4
        ))
    }
    @discardableResult
    func open(_ target: String) -> Bool {
        if target == "MacPlusPlusCast" {
            DistributedNotificationCenter.default().postNotificationName(
                NSNotification.Name("\(macppShellDomain).show-launcher"), object: nil, userInfo: nil, deliverImmediately: true
            )
            return true
        }
        else {
            let candidates = ["/Applications/\(target).app", "/System/Applications/\(target).app", NSHomeDirectory() + "/Applications/\(target).app"]
            if let path = candidates.first(where: FileManager.default.fileExists(atPath:)) {
                NSWorkspace.shared.openApplication(at: URL(fileURLWithPath: path), configuration: .init())
                return true
            }
        }
        onStateToast?(MacPlusPlusStateToast(
            title: "App Unavailable",
            detail: "\(target) could not be found in Applications",
            symbol: "questionmark.app"
        ))
        return false
    }

    var mediaOwnerApplication: String? {
        guard !media.title.isEmpty else { return nil }
        if isSpotifyMedia(media) { return "Spotify" }
        if MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Safari", source: media.source, device: media.device
        ) { return "Safari" }
        if MacPlusPlusPureLogic.mediaOwnerMatches(
            application: "Browser", source: media.source, device: media.device
        ) { return "Mac++ Browser" }
        return nil
    }

    var volumeSymbol: String {
        if muted || volume <= 0.001 { return "speaker.slash.fill" }
        if volume < 0.34 { return "speaker.wave.1.fill" }
        if volume < 0.67 { return "speaker.wave.2.fill" }
        return "speaker.wave.3.fill"
    }
    var batterySymbol: String {
        if batteryPercent < 25 { return "battery.0percent" }
        if batteryPercent < 50 { return "battery.25percent" }
        if batteryPercent < 75 { return "battery.50percent" }
        if batteryPercent < 100 { return "battery.75percent" }
        return "battery.100percent"
    }

    var batteryAnimationKey: Int {
        min(4, max(0, batteryPercent / 25)) + (charging ? 10 : 0)
    }
}

private struct BatteryGlyph: View {
    @ObservedObject var model: ShellModel
    var size: CGFloat = 15
    var interactionTint: Color?
    @State private var displayedPercent: Int
    @State private var displayedCharging: Bool
    @State private var glyphScale: CGFloat = 1
    @State private var generation = 0

    init(model: ShellModel, size: CGFloat = 15, interactionTint: Color? = nil) {
        self.model = model
        self.size = size
        self.interactionTint = interactionTint
        _displayedPercent = State(initialValue: model.batteryPercent)
        _displayedCharging = State(initialValue: model.charging)
    }

    var body: some View {
        let width = size * 1.52
        let height = size * 0.72
        let inset = max(1.7, size * 0.14)
        let level = CGFloat(min(100, max(0, displayedPercent))) / 100
        // This is the one place that actually decides the glyph's color --
        // it draws its own stroke/fill directly rather than reading
        // foregroundStyle, so this threshold is the real source of truth
        // (a foregroundStyle modifier at the call site used to shadow this
        // and do nothing). Lowered from 15% to 10% so red only shows up
        // when the battery is genuinely low, not just moderately so.
        // Theme.ice is deliberately the *accent* color on light palettes
        // (needed elsewhere for active toggles/arcs), which is exactly why
        // this glyph rendered blue in White mode even at a normal charge --
        // a plain status glyph should match its neighboring wifi/bluetooth/
        // audio icons (Theme.muted) instead of borrowing the accent color.
        // Preserve the semantic low-battery warning above interaction color;
        // every ordinary state follows the same active/hover/rest tint as the
        // neighbouring Wi-Fi, Bluetooth, and Audio glyphs.
        let color = displayedPercent <= 10 ? Color.red : (interactionTint ?? Theme.muted)

        ZStack(alignment: .leading) {
            RoundedRectangle(cornerRadius: height * 0.25, style: .continuous)
                .stroke(color, lineWidth: max(1.25, size * 0.095))
                .frame(width: width, height: height)
            RoundedRectangle(cornerRadius: max(1, height * 0.13), style: .continuous)
                .fill(color)
                .frame(
                    width: max(0, (width - inset * 2) * level),
                    height: height - inset * 2
                )
                .offset(x: inset)
            Capsule()
                .fill(color)
                .frame(width: max(1.4, size * 0.11), height: height * 0.43)
                .offset(x: width + max(1, size * 0.07))
            if displayedCharging {
                Image(systemName: "bolt.fill")
                    .font(.system(size: size * 0.39, weight: .heavy, design: .rounded))
                    .foregroundStyle(Theme.frame)
                    .frame(width: width, height: height)
            }
        }
        .frame(width: width + max(2.5, size * 0.18), height: height)
        .scaleEffect(glyphScale)
        .animation(ShellMotion.valueChange.animation, value: displayedPercent)
        .onChange(of: model.batteryPercent) { _, value in
            displayedPercent = value
        }
        .onChange(of: model.charging) { _, _ in replaceGlyph() }
        .accessibilityLabel(model.charging ? "Battery \(model.batteryPercent) percent, connected to power" : "Battery \(model.batteryPercent) percent")
    }

    private func replaceGlyph() {
        generation += 1
        let current = generation
        withAnimation(ShellMotion.iconOut.animation) { glyphScale = 0 }
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.iconOut.duration) {
            guard current == generation else { return }
            displayedPercent = model.batteryPercent
            displayedCharging = model.charging
            withAnimation(ShellMotion.iconIn.animation) { glyphScale = 1 }
        }
    }
}

// MaterialIcon/StyledText in Caelestia swaps changing glyphs by scaling the
// old glyph to zero, performing an atomic text replacement, then scaling the
// new glyph back in. SF Symbol replacement effects use a different motion
// model, so dynamic shell status icons share this explicit primitive.
private struct CaelestiaSymbol: View {
    let name: String
    var size: CGFloat = 15
    var weight: Font.Weight = .semibold
    @State private var displayedName: String
    @State private var glyphScale: CGFloat = 1
    @State private var generation = 0

    init(_ name: String, size: CGFloat = 15, weight: Font.Weight = .semibold) {
        self.name = name
        self.size = size
        self.weight = weight
        _displayedName = State(initialValue: name)
    }

    var body: some View {
        Image(systemName: displayedName)
            .font(.system(size: size, weight: weight))
            .scaleEffect(glyphScale)
            .onChange(of: name) { _, next in replace(with: next) }
    }

    private func replace(with next: String) {
        guard next != displayedName else { return }
        generation += 1
        let current = generation
        withAnimation(ShellMotion.iconOut.animation) { glyphScale = 0 }
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.iconOut.duration) {
            guard current == generation else { return }
            displayedName = next
            withAnimation(ShellMotion.iconIn.animation) { glyphScale = 1 }
        }
    }
}

// SF Symbols intentionally does not ship a Bluetooth logo. Drawing the
// canonical bind-rune keeps it crisp at rail size and avoids substituting a
// radio/antenna glyph, which describes the wrong control.
private struct BluetoothMarkShape: Shape {
    func path(in rect: CGRect) -> Path {
        let point: (CGFloat, CGFloat) -> CGPoint = { x, y in
            CGPoint(x: rect.minX + rect.width * x, y: rect.minY + rect.height * y)
        }
        var path = Path()
        path.move(to: point(0.44, 0.03))
        path.addLine(to: point(0.44, 0.97))
        path.move(to: point(0.44, 0.03))
        path.addLine(to: point(0.84, 0.29))
        path.addLine(to: point(0.16, 0.75))
        path.move(to: point(0.16, 0.25))
        path.addLine(to: point(0.84, 0.71))
        path.addLine(to: point(0.44, 0.97))
        return path
    }
}

private struct BluetoothMark: View {
    let color: Color
    var size: CGFloat = 15

    var body: some View {
        BluetoothMarkShape()
            .stroke(color, style: StrokeStyle(lineWidth: max(1.35, size * 0.115), lineCap: .round, lineJoin: .round))
            .frame(width: size * 0.68, height: size)
            .accessibilityLabel("Bluetooth")
    }
}

private struct RailButton: View {
    let symbol: String; let active: Bool; let action: () -> Void
    @State private var hovered = false
    var body: some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                .frame(width: 34, height: SideRailGeometry.toolButtonHeight)
                // Rail tools use the shell's ordinary glyph language: accent
                // for the open surface, bright on hover, and no nested tile.
                .foregroundStyle(active ? Theme.accent : (hovered ? Theme.bright : Theme.muted))
                .contentShape(Rectangle())
        }.buttonStyle(MicroButtonStyle()).onHover { hovered = $0 }
            .animation(ShellMotion.hover.animation, value: hovered)
            .animation(ShellMotion.panelSwitch.animation, value: active)
    }
}

private struct RailClockFace: View, Equatable {
    let date: Date
    let palette: ShellPalette
    let paletteRevision: Int
    let hovered: Bool
    let active: Bool

    var body: some View {
        let clock = stackedClockParts(date)
        return VStack(spacing: Spacing.none) {
            Text(clock.0)
                .font(.system(size: ShellTypography.title, weight: .heavy, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(active ? Theme.accent : Theme.bright)
            Text(clock.1)
                .font(.system(size: ShellTypography.title, weight: .heavy, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(active ? Theme.accent : (hovered ? Theme.bright : Theme.muted))
        }
        .frame(width: 34, height: 34)
        .contentShape(Rectangle())
        // Minute replacement remains static, but interaction tint gets the
        // same authored effects/spatial tokens as every other rail glyph.
        .animation(nil, value: date)
        .animation(nil, value: paletteRevision)
        .animation(ShellMotion.hover.animation, value: hovered)
        .animation(ShellMotion.panelSwitch.animation, value: active)
    }
}

/// The large clock inside the top dashboard is deliberately a leaf view.
/// `NotchPopout` observes the whole shell model, so formatting these strings
/// directly in `dateCard` rebuilt them for unrelated media, telemetry, and
/// hover updates. Equatable isolation keeps that work on the minute/theme
/// cadence while leaving the enclosing card free to inherit the surface's
/// content-reveal transaction.
private struct TopBarClockFace: View, Equatable {
    let date: Date
    let palette: ShellPalette
    let paletteRevision: Int

    var body: some View {
        VStack(spacing: Spacing.hairline) {
            Text(date.formatted(date: .omitted, time: .shortened))
                .font(.system(size: ShellDisplay.huge, weight: .medium, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(Theme.bright)
                .lineLimit(1).minimumScaleFactor(0.7)
            Text(date.formatted(.dateTime.weekday(.wide).month(.abbreviated).day()))
                .font(.system(size: ShellTypography.cardTitle, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.muted).lineLimit(1).minimumScaleFactor(0.7)
        }
    }
}

private func drawerHeight(_ page: Int) -> CGFloat {
    switch page { case 0: 286; case 2: 310; case 3: 244; case 4: 228; default: 230 }
}

private struct MarqueeText: View {
    let text: String

    var body: some View {
        // The old SwiftUI offset animation invalidated the entire drawer
        // view graph on every animation frame. When the drawer stayed alive
        // behind a popout that became a continuous main-thread layout loop,
        // which was misdiagnosed as a GPU-heavy card. Reuse the existing
        // AppKit/CALayer marquee: Core Animation moves native text layers
        // without asking SwiftUI to lay out the drawer at 120 Hz.
        let hasTitle = !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        return SeamlessMarquee(
            // Keep the compact Drawer media strip moving even for a short
            // title. The side-rail ticker already repeats its source text;
            // using the same prepared sequence here avoids a static title in
            // one surface and a live ticker in the next.
            text: hasTitle ? loopingMediaText(text, viewport: 150) : text,
            fontSize: 15,
            speed: 18,
            active: hasTitle,
            wrapGap: false
        )
        .clipped()
        .id(text)
    }
}

private func loopingMediaText(_ rawTitle: String, viewport: CGFloat) -> String {
    let title = rawTitle.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !title.isEmpty else { return "" }
    let separator = "   •   "
    let estimatedUnitWidth = max(28, CGFloat(title.count) * 7.6 + 28)
    let repetitions = max(2, min(16, Int(ceil(viewport / estimatedUnitWidth)) + 1))
    // End the tile with the same separator that joins each title. The old
    // marquee added a second, separate gap at the copy boundary, so a short
    // title looked continuous for a few repeats and then hit a conspicuous
    // empty trough before the next copy entered.
    return Array(repeating: title, count: repetitions).joined(separator: separator) + separator
}

/// A short title should be a label, not a ticker full of copies of itself.
/// Only titles that can actually outrun their viewport need the moving
/// marquee; long titles use SeamlessMarquee's two-copy wrap mode so the
/// handoff between copies is continuous instead of leaving a blank trough.
private func mediaTitleNeedsScroll(_ rawTitle: String, viewport: CGFloat) -> Bool {
    let title = rawTitle.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !title.isEmpty, viewport > 0 else { return false }
    return CGFloat(title.count) * 7.6 + 12 > viewport
}

/// Album metadata is useful until it merely repeats the title or artist that
/// is already visible beside it. Compact media cards have no room for that
/// third line, and showing it twice makes the card read like duplicated data.
private func distinctMediaAlbum(_ rawAlbum: String, title rawTitle: String, artist rawArtist: String) -> String? {
    let album = rawAlbum.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !album.isEmpty else { return nil }
    let title = rawTitle.trimmingCharacters(in: .whitespacesAndNewlines)
    let artist = rawArtist.trimmingCharacters(in: .whitespacesAndNewlines)
    guard album.localizedCaseInsensitiveCompare(title) != .orderedSame,
          album.localizedCaseInsensitiveCompare(artist) != .orderedSame else { return nil }
    return album
}

private final class MarqueeLayerView: NSView {
    private let movingLayer = CALayer()
    private let first = CATextLayer()
    private let second = CATextLayer()
    private var displayScale: CGFloat = 1
    private var configuredText = ""
    private var configuredSize: CGFloat = 0
    private var configuredSpeed: CGFloat = 0
    private var configuredVertical = false
    private var configuredActive = true
    private var configuredWrapGap = false
    private var cycle: CGFloat = 1
    private var textWidth: CGFloat = 1
    private var lastLayoutSize = CGSize.zero

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        layer?.masksToBounds = true
        layer?.addSublayer(movingLayer)
        // The parent layer is translated every frame. Rasterizing that whole
        // subtree turns the rotated glyphs into one filtered bitmap, which is
        // especially soft on the rail's 1x external display. CATextLayer is
        // already a retained, GPU-composited text primitive; keep it live so
        // the compositor samples the glyph layers at their native scale.
        movingLayer.shouldRasterize = false
        movingLayer.drawsAsynchronously = false
        movingLayer.addSublayer(first)
        movingLayer.addSublayer(second)
        [first, second].forEach {
            $0.alignmentMode = .left
            $0.truncationMode = .none
        }
        updateDisplayScale()
    }
    required init?(coder: NSCoder) { nil }

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        updateDisplayScale()
    }

    override func viewDidChangeBackingProperties() {
        super.viewDidChangeBackingProperties()
        updateDisplayScale()
    }

    private func updateDisplayScale() {
        let scale = max(
            1,
            window?.backingScaleFactor
                ?? window?.screen?.backingScaleFactor
                ?? NSScreen.main?.backingScaleFactor
                ?? 1
        )
        guard scale != displayScale || layer?.contentsScale != scale else { return }
        displayScale = scale
        layer?.contentsScale = scale
        movingLayer.contentsScale = scale
        movingLayer.rasterizationScale = scale
        [first, second].forEach { $0.contentsScale = scale }
    }

    func applyTheme() {
        let color = NSColor(Theme.bright).usingColorSpace(.sRGB) ?? .labelColor
        first.foregroundColor = color.cgColor
        second.foregroundColor = color.cgColor
    }

    override func layout() {
        super.layout()
        updateDisplayScale()
        guard bounds.size != lastLayoutSize, !configuredText.isEmpty else { return }
        layoutLayers(restart: true)
    }

    func configure(text: String, fontSize: CGFloat, speed: CGFloat, vertical: Bool, active: Bool, wrapGap: Bool = false) {
        applyTheme()
        guard text != configuredText || fontSize != configuredSize || speed != configuredSpeed || vertical != configuredVertical || active != configuredActive || wrapGap != configuredWrapGap else { return }
        configuredText = text; configuredSize = fontSize; configuredSpeed = speed; configuredVertical = vertical; configuredActive = active; configuredWrapGap = wrapGap
        // The marquee scrolls song titles, which is prose, not tabular data --
        // and it is the one label in the shell where a monospaced face was
        // most obviously wrong, since every proportional glyph got padded to
        // the width of an M. Matches the rounded system face the SwiftUI side
        // now uses; NSFontDescriptor is how you reach that design from AppKit.
        let baseFont = NSFont.systemFont(ofSize: fontSize, weight: .semibold)
        let font = NSFont(
            descriptor: baseFont.fontDescriptor.withDesign(.rounded) ?? baseFont.fontDescriptor,
            size: fontSize
        ) ?? baseFont
        let displayText = wrapGap ? text + "   •" : text
        textWidth = max(1, (displayText as NSString).size(withAttributes: [.font: font]).width)
        // Repeated media text already carries its trailing separator. Tiling
        // the two copies directly keeps the inter-title spacing identical at
        // the seam instead of adding another 28pt blank gap there.
        cycle = wrapGap ? textWidth + 28 : textWidth
        for textLayer in [first, second] {
            textLayer.string = displayText
            // Bridged to CTFont explicitly. CATextLayer.font accepts a
            // CTFont/CGFont reference *or* a font-name string, and the system
            // fonts -- especially the rounded design -- have private,
            // dot-prefixed PostScript names (".AppleSystemUIFontRounded-...")
            // that CoreText will not resolve by name. Left to resolve by name
            // it silently falls back to Helvetica, which is both the wrong
            // face and a different width from the one measured above with the
            // real font -- so the scroll cycle and the gap between the two
            // copies were computed against a font that was never drawn.
            textLayer.font = font as CTFont
            textLayer.fontSize = fontSize
        }
        layoutLayers(restart: true)
    }

    private func layoutLayers(restart: Bool) {
        lastLayoutSize = bounds.size
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        if configuredVertical {
            second.isHidden = false
            movingLayer.frame = bounds
            for (index, textLayer) in [first, second].enumerated() {
                textLayer.bounds = CGRect(x: 0, y: 0, width: textWidth, height: configuredSize + 4)
                // The enclosing panel is already snapped to the display grid.
                // Preserve the natural centre of the 27pt viewport here: at
                // 1x its 13.5pt centre pairs with the 15pt rotated text
                // thickness so the text edges, rather than the layer centre,
                // land on whole pixels. Snapping this local centre to 14pt
                // would undo the panel correction and soften the glyphs again.
                let alignedPositionY = ((textWidth / 2 + CGFloat(index) * cycle) * displayScale).rounded() / displayScale
                textLayer.position = CGPoint(x: bounds.midX, y: alignedPositionY)
                textLayer.setAffineTransform(CGAffineTransform(rotationAngle: .pi / 2))
            }
        } else {
            let height = max(18, bounds.height)
            first.setAffineTransform(.identity)
            second.setAffineTransform(.identity)
            if configuredWrapGap {
                // Tile two copies with a fixed gap. The previous one-copy
                // implementation left a blank trough at every reset, which
                // made long top-bar titles appear to jump or stop in both the
                // Dashboard card and the full Media tab.
                cycle = textWidth + 28
                movingLayer.frame = CGRect(x: 0, y: 0, width: cycle * 2, height: height)
                first.frame = CGRect(x: 0, y: (height - configuredSize) / 2 - 1, width: textWidth, height: configuredSize + 4)
                second.frame = CGRect(x: cycle, y: (height - configuredSize) / 2 - 1, width: textWidth, height: configuredSize + 4)
                second.isHidden = false
            } else {
                movingLayer.frame = CGRect(x: 0, y: 0, width: cycle * 2, height: height)
                first.frame = CGRect(x: 0, y: (height - configuredSize) / 2 - 1, width: textWidth, height: configuredSize + 4)
                // A static short title is a label, not a tiled texture. The
                // second copy used to remain visible even after the caller
                // correctly disabled scrolling, so a title wider than half
                // the viewport appeared twice back-to-back with no separator.
                // Vertical tickers still need two copies to loop.
                second.frame = CGRect(x: cycle, y: (height - configuredSize) / 2 - 1, width: textWidth, height: configuredSize + 4)
                second.isHidden = !configuredActive
                if !configuredActive {
                    movingLayer.frame = CGRect(x: 0, y: 0, width: textWidth, height: height)
                }
            }
        }
        movingLayer.setAffineTransform(.identity)
        movingLayer.removeAnimation(forKey: "macpp.marquee")
        CATransaction.commit()
        guard restart, configuredActive, configuredSpeed > 0, cycle > 1 else { return }
        let keyPath = configuredVertical ? "transform.translation.y" : "transform.translation.x"
        let animation = CABasicAnimation(keyPath: keyPath)
        animation.fromValue = 0
        animation.toValue = -cycle
        animation.duration = CFTimeInterval(cycle / configuredSpeed)
        animation.repeatCount = .infinity
        animation.timingFunction = CAMediaTimingFunction(name: .linear)
        // The marquee is continuous motion, so keep it at the shell's 120 Hz
        // ceiling. This remains native on ordinary 60/120 Hz panels, while a
        // 240 Hz display no longer makes the entire top surface redraw at its
        // maximum cadence for a small text scroll.
        let refreshRate = shellAnimationRefreshRate(for: window?.screen)
        animation.preferredFrameRateRange = CAFrameRateRange(
            minimum: min(60, refreshRate),
            maximum: refreshRate,
            preferred: refreshRate
        )
        animation.isRemovedOnCompletion = false
        movingLayer.add(animation, forKey: "macpp.marquee")
    }

    func revealFromEdge(duration: CFTimeInterval = 0.24) {
        guard let hostLayer = layer, bounds.width > 0, bounds.height > 0 else { return }
        let mask = CAShapeLayer()
        mask.frame = bounds
        mask.backgroundColor = NSColor.black.cgColor
        let full = CGPath(rect: bounds, transform: nil)
        let edge = CGPath(
            rect: CGRect(x: bounds.minX, y: bounds.minY, width: bounds.width, height: 0.5),
            transform: nil
        )
        mask.path = full
        hostLayer.mask = mask
        let reveal = CABasicAnimation(keyPath: "path")
        reveal.fromValue = edge
        reveal.toValue = full
        reveal.duration = duration
        reveal.timingFunction = CAMediaTimingFunction(controlPoints: 0.16, 1.0, 0.3, 1.0)
        mask.add(reveal, forKey: "macpp.marquee.edge-reveal")
        DispatchQueue.main.asyncAfter(deadline: .now() + duration) { [weak self, weak mask] in
            guard let self, let mask, let currentMask = self.layer?.mask, currentMask === mask else { return }
            self.layer?.mask = nil
        }
    }
}

private final class MarqueePillView: NSView {
    let marquee = MarqueeLayerView(frame: .zero)
    private let inner = CALayer()

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        layer?.cornerRadius = 14
        layer?.cornerCurve = .continuous
        layer?.masksToBounds = true
        layer?.borderWidth = 0
        inner.cornerRadius = 11
        inner.cornerCurve = .continuous
        layer?.addSublayer(inner)
        addSubview(marquee)
        applyTheme()
    }

    required init?(coder: NSCoder) { nil }

    func applyTheme() {
        layer?.backgroundColor = NSColor(Theme.surfaceRaised).withAlphaComponent(shellMaterialOpacity).cgColor
        layer?.borderColor = NSColor.clear.cgColor
        inner.backgroundColor = NSColor(Theme.bright).withAlphaComponent(Theme.isLight ? 0.035 : 0.018).cgColor
        marquee.applyTheme()
    }

    override func layout() {
        super.layout()
        inner.frame = bounds.insetBy(dx: 2.5, dy: 2.5)
        marquee.frame = bounds.insetBy(dx: 6, dy: 10)
    }
}

private struct SeamlessMarquee: NSViewRepresentable {
    let text: String
    var fontSize: CGFloat = 10
    var speed: CGFloat = 20
    var vertical = false
    var active = true
    var wrapGap = false
    func makeNSView(context: Context) -> MarqueeLayerView { MarqueeLayerView(frame: .zero) }
    func updateNSView(_ view: MarqueeLayerView, context: Context) {
        view.configure(text: text, fontSize: fontSize, speed: speed, vertical: vertical, active: active, wrapGap: wrapGap)
    }
}

// MARK: - Lightweight state toasts

/// Short-lived system state, distinct from captured application
/// notifications. A toast never enters Notification Center, never changes the
/// selected sidebar tab, and never dismisses a launcher/popout that is already
/// open. Keeping that ownership separate is what lets a route or battery
/// change remain useful without interrupting the surface the user is using.
private struct MacPlusPlusStateToast: Equatable, Identifiable {
    let id = UUID()
    let title: String
    let detail: String
    let symbol: String
    let critical: Bool
    let duration: TimeInterval

    init(
        title: String,
        detail: String,
        symbol: String,
        critical: Bool = false,
        duration: TimeInterval = 4.2
    ) {
        self.title = String(title.prefix(80))
        self.detail = String(detail.prefix(140))
        self.symbol = symbol.isEmpty ? "info.circle.fill" : String(symbol.prefix(80))
        self.critical = critical
        self.duration = min(8, max(1.2, duration))
    }
}

@MainActor private final class MacPlusPlusStateToastPresentation: ObservableObject {
    @Published var event: MacPlusPlusStateToast
    init(event: MacPlusPlusStateToast) { self.event = event }
}

private struct MacPlusPlusStateToastView: View {
    @ObservedObject var presentation: MacPlusPlusStateToastPresentation
    @ObservedObject var motion: SurfaceMotionState

    var body: some View {
        let event = presentation.event
        HStack(spacing: Spacing.base) {
            ZStack {
                Circle()
                    .fill((event.critical ? Color.red : Theme.accent).opacity(0.16))
                Image(systemName: event.symbol)
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(event.critical ? Color.red : Theme.accent)
            }
            .frame(width: 32, height: 32)

            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(event.title.uppercased())
                    .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .lineLimit(1)
                Text(event.detail)
                    .font(.system(size: ShellTypography.body, weight: .medium, design: .rounded))
                    .foregroundStyle(Theme.muted)
                    .lineLimit(2)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(.horizontal, Spacing.roomy)
        .frame(width: 316, height: 62)
        .layeredPanel(radius: Rounding.large)
        .background(Theme.frame.opacity(shellMaterialOpacity), in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                .stroke(Theme.seam.opacity(0.34), lineWidth: 0.65)
        }
        .id(event.id)
        .opacity(motion.contentReady ? Double(motion.progress) : 0)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(event.title). \(event.detail)")
    }
}

// MARK: - Notification capture UI and normalized queue

/// Mirrors the normalized envelope from docs/notification-capture-mockup.md.
/// The independent adapter supplies live values in memory; samples remain only
/// for explicitly gated visual-QA sessions.
private struct NotificationCaptureFixture: Identifiable, Equatable {
    let id: String
    /// Payload fingerprint supplied by the capture helper. Consumption is
    /// keyed by both ID and revision so a newly-updated notification cannot be
    /// mistaken for an older version the user already cleared.
    let revision: String
    let appBundleID: String
    let appName: String
    let icon: String
    let title: String
    let subtitle: String
    let body: String
    let timestamp: Date
    let destination: String
    let actions: [String]
    let sensitive: Bool
    let source: String

    static func samples() -> [NotificationCaptureFixture] { [] }
}

@MainActor private final class NotificationCaptureMockupQueue: ObservableObject {
    @Published private(set) var events: [NotificationCaptureFixture] = []

    func reset() {
        events = NotificationCaptureFixture.samples()
    }

    func ensureFixtures() {
        if events.isEmpty { reset() }
    }

    @discardableResult
    func enqueue(_ event: NotificationCaptureFixture) -> [NotificationCaptureFixture] {
        // A real test event should not be buried beneath design fixtures.
        if event.source != "fixture" {
            events.removeAll { $0.source == "fixture" }
        }
        events.removeAll { $0.id == event.id }
        events.insert(event, at: 0)
        guard events.count > 12 else { return [] }
        let evicted = Array(events.suffix(from: 12))
        events.removeLast(events.count - 12)
        return evicted
    }

    func remove(id: String, revision: String) {
        events.removeAll { $0.id == id && $0.revision == revision }
    }

    func clear() {
        events.removeAll()
    }
}

@MainActor private final class NotificationCaptureSurfaceState: ObservableObject {
    @Published var frameHeight: CGFloat
    @Published var redactsContent: Bool
    /// The compact surface owns this presentation-only state. The queue still
    /// retains every captured event; this merely controls how many are exposed
    /// before the user asks for the full notification center.
    @Published var previewExpanded = false
    init(frameHeight: CGFloat, redactsContent: Bool) {
        self.frameHeight = frameHeight
        self.redactsContent = redactsContent
    }
}

/// Separators are part of the shell's rounded visual language too. A one-point
/// Capsule avoids the square end-caps that a Rectangle leaves on HiDPI and
/// keeps dividers visually consistent with the surrounding cards.
private struct CaelestiaDivider: View {
    var opacity: Double = 0.24

    var body: some View {
        Capsule(style: .continuous)
            .fill(Theme.seam.opacity(opacity))
            .frame(height: 1)
            .accessibilityHidden(true)
    }
}

private struct NotificationStackHeightPreferenceKey: PreferenceKey {
    static var defaultValue: CGFloat = 0
    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
        value = max(value, nextValue())
    }
}

private struct NotificationCaptureMockupView: View {
    @ObservedObject var queue: NotificationCaptureMockupQueue
    @ObservedObject var motion: SurfaceMotionState
    @ObservedObject var surface: NotificationCaptureSurfaceState
    @State private var relativeNow = Date()
    @State private var hoveredEventID: String?
    @State private var dragDistance: CGFloat = 0
    let topDepth: CGFloat
    let openEvent: (NotificationCaptureFixture) -> Void
    let clearEvent: (NotificationCaptureFixture) -> Void
    let stackHeightChanged: (CGFloat) -> Void
    let hoverChanged: (Bool) -> Void
    let dragDown: () -> Void
    /// The compact card normally paints its own top-right envelope. The
    /// promotion view disables that layer because the shared shell contour is
    /// the only surface that should be moving during the handoff.
    var drawsSurface = true
    /// Fullscreen keeps its fixed-height bubble and shows the whole queue;
    /// only the attached compact card uses the hover preview behavior.
    var allowsHoverPreview = true
    var allowsDragToExpand = true
    /// The handoff can opt into the expanded sidebar's content box so a
    /// crossfaded card keeps one horizontal anchor. Standalone notifications
    /// retain their top-right-specific values above.
    var contentLeadingInset: CGFloat = notificationContentLeadingInset
    var contentTrailingInset: CGFloat = notificationContentTrailingInset
    /// The panel frame already accounts for the display rim. Only surfaces
    /// with an authored header (the fullscreen bubble) or an in-flight
    /// handoff should reserve extra content space here; the ordinary compact
    /// notification must start at the shared popout gutter on a notched
    /// display, otherwise the rim depth is counted twice.
    var contentTopInset: CGFloat = 0

    private var displayedEvents: [NotificationCaptureFixture] {
        guard allowsHoverPreview else { return queue.events }
        let limit = surface.previewExpanded ? notificationPreviewEventLimit : 1
        return Array(queue.events.prefix(limit))
    }

    var body: some View {
        let contentWidth = notificationCaptureMockupWidth
            - contentLeadingInset
            - contentTrailingInset
        let viewportHeight = max(
            1,
            surface.frameHeight
                - contentTopInset
                - notificationContentTopGutter
                - notificationContentBottomInset
        )

        ScrollView(.vertical, showsIndicators: false) {
            VStack(spacing: CaelestiaParityTokens.Spacing.medium) {
                ForEach(Array(displayedEvents.enumerated()), id: \.element.id) { index, event in
                    notification(event)
                        .id(event.id)
                        // Use the same per-card reveal as the bottom-left
                        // utility grid. The stack itself stays stable while
                        // each card follows the surface content handshake.
                        .motionChild(
                            motion,
                            index: index + 1,
                            offset: CGSize(width: -8, height: 6)
                        )
                }
            }
            .frame(width: contentWidth)
            .fixedSize(horizontal: false, vertical: true)
            // Queue delivery should not animate the whole list. Card
            // presentation still animates through MotionChild because this
            // value-specific rule only applies when the queue changes.
            .animation(nil, value: queue.events)
            .animation(nil, value: surface.previewExpanded)
            .background {
                GeometryReader { geometry in
                    Color.clear.preference(
                        key: NotificationStackHeightPreferenceKey.self,
                        value: geometry.size.height
                    )
                }
            }
        }
        .frame(width: contentWidth, height: viewportHeight, alignment: .top)
        .scrollBounceBehavior(.basedOnSize)
        // The surface remains visible as its cards arrive. Applying one
        // opacity to the whole stack made notification content fade as a
        // single block instead of matching the bottom-left cards.
        .padding(.leading, contentLeadingInset)
        .padding(.trailing, contentTrailingInset)
        .padding(.top, contentTopInset + notificationContentTopGutter)
        .padding(.bottom, notificationContentBottomInset)
        .frame(
            width: notificationCaptureMockupWidth,
            height: surface.frameHeight,
            alignment: .topLeading
        )
        // In the standalone state this stack supplies the compact surface.
        // During promotion it is content only; painting this shape there too
        // creates the second reverse curve visible inside the expanding host.
        .background {
            if drawsSurface {
                Theme.frame.opacity(shellMaterialOpacity)
            }
        }
        .clipShape(
            NotificationCaptureMockupClipShape(
                topDepth: topDepth,
                drawsSurface: drawsSurface
            )
        )
        .contentShape(
            NotificationCaptureMockupClipShape(
                topDepth: topDepth,
                drawsSurface: drawsSurface
            )
        )
        .onHover { inside in
            if allowsHoverPreview {
                surface.previewExpanded = inside && !queue.events.isEmpty
            }
            hoverChanged(inside)
        }
        .simultaneousGesture(
            DragGesture(minimumDistance: 12)
                .onChanged { value in
                    guard allowsDragToExpand else { return }
                    let vertical = value.translation.height
                    let horizontal = abs(value.translation.width)
                    guard vertical > 0, vertical > horizontal * 1.15 else { return }
                    dragDistance = max(dragDistance, vertical)
                }
                .onEnded { value in
                    defer { dragDistance = 0 }
                    guard allowsDragToExpand else { return }
                    let vertical = max(dragDistance, value.translation.height)
                    let horizontal = abs(value.translation.width)
                    guard vertical >= notificationCompactDragThreshold,
                          vertical > horizontal * 1.15 else { return }
                    dragDown()
                }
        )
        .onPreferenceChange(NotificationStackHeightPreferenceKey.self) { height in
            guard height > 0.5 else { return }
            stackHeightChanged(ceil(height))
        }
        .onReceive(Timer.publish(every: 15, on: .main, in: .common).autoconnect()) {
            relativeNow = $0
        }
    }

    private func notification(_ event: NotificationCaptureFixture) -> some View {
        ZStack(alignment: .topTrailing) {
            Button { openEvent(event) } label: {
                HStack(alignment: .top, spacing: CaelestiaParityTokens.Spacing.medium) {
                    Group {
                        if let icon = appIcon(for: event.appBundleID) {
                            Image(nsImage: icon)
                                .resizable()
                                .interpolation(.high)
                                .scaledToFit()
                        } else {
                            ZStack {
                                RoundedRectangle(cornerRadius: Rounding.small, style: .continuous)
                                    .fill(Theme.accent.opacity(0.16))
                                Image(systemName: event.icon)
                                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                                    .foregroundStyle(Theme.accent)
                            }
                        }
                    }
                    .frame(
                        width: CaelestiaParityTokens.Sizes.notificationImage,
                        height: CaelestiaParityTokens.Sizes.notificationImage
                    )
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.small, style: .continuous))

                    VStack(alignment: .leading, spacing: Spacing.hairline) {
                        HStack(spacing: Spacing.tight) {
                            Text(event.appName.uppercased())
                                .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.bright)
                                .lineLimit(1)
                            Spacer(minLength: 6)
                            Text(relativeTime(event.timestamp))
                                .font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                                .foregroundStyle(Theme.muted)
                                .monospacedDigit()
                        }
                        // Reserve the tiny close affordance's corner so it
                        // never covers the timestamp when the card is hovered.
                        .padding(.trailing, Spacing.section)

                        Text(surface.redactsContent ? "Notification" : event.title)
                            .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                            .foregroundStyle(Theme.bright)
                            .fixedSize(horizontal: false, vertical: true)
                        Text(
                            surface.redactsContent
                                ? "Preview hidden while this Mac is locked."
                                : event.body
                        )
                            .font(.system(size: ShellTypography.label, weight: .medium, design: .rounded))
                            .foregroundStyle(Theme.muted)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
                .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
                .padding(.vertical, CaelestiaParityTokens.Padding.large)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(Theme.layerCard, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .overlay {
                    RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                        .stroke(Theme.seam.opacity(0.30), lineWidth: 0.55)
                }
                .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
            }
            .buttonStyle(.plain)
            .help("Open \(event.appName)")
            .accessibilityAction(named: "Clear notification") {
                clearEvent(event)
            }

            if hoveredEventID == event.id {
                Button {
                    hoveredEventID = nil
                    clearEvent(event)
                } label: {
                    Image(systemName: "xmark")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                        .frame(
                            width: notificationDismissButtonSize,
                            height: notificationDismissButtonSize
                        )
                        .background(Theme.layerTile.opacity(0.88), in: Circle())
                        .overlay {
                            Circle()
                                .stroke(Theme.seam.opacity(0.30), lineWidth: 0.55)
                        }
                        .contentShape(Circle())
                }
                .buttonStyle(.plain)
                .padding(.top, Spacing.small)
                .padding(.trailing, Spacing.small)
                .help("Clear notification")
                .accessibilityLabel("Clear \(event.appName) notification")
                .transition(.opacity.combined(with: .scale(scale: 0.9)))
            }
        }
        .onHover { inside in
            if inside {
                hoveredEventID = event.id
            } else if hoveredEventID == event.id {
                hoveredEventID = nil
            }
        }
        .animation(ShellMotion.contentIn.animation, value: hoveredEventID == event.id)
    }

    private func appIcon(for bundleID: String) -> NSImage? {
        guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else { return nil }
        let icon = NSWorkspace.shared.icon(forFile: url.path)
        icon.size = NSSize(width: 64, height: 64)
        return icon
    }

    private func relativeTime(_ timestamp: Date) -> String {
        let seconds = max(0, Int(relativeNow.timeIntervalSince(timestamp)))
        if seconds < 45 { return "NOW" }
        if seconds < 60 * 60 { return "\(max(1, seconds / 60))M" }
        return "\(max(1, seconds / 3600))H"
    }
}

/// A native fullscreen Space has no visible shell rim to attach the live
/// notification stack to. This is intentionally a separate, small bubble:
/// it reuses the notification cards and queue, but owns only its own rounded
/// envelope and auxiliary fullscreen membership. The normal shell contour is
/// never asked to follow this window.
private struct NotificationFullscreenBubbleView: View {
    @ObservedObject var queue: NotificationCaptureMockupQueue
    @ObservedObject var motion: SurfaceMotionState
    @ObservedObject var surface: NotificationCaptureSurfaceState
    let openEvent: (NotificationCaptureFixture) -> Void
    let clearEvent: (NotificationCaptureFixture) -> Void
    let close: () -> Void
    let hoverChanged: (Bool) -> Void

    var body: some View {
        ZStack(alignment: .topTrailing) {
            NotificationCaptureMockupView(
                queue: queue,
                motion: motion,
                surface: surface,
                topDepth: notificationFullscreenBubbleHeaderHeight,
                openEvent: openEvent,
                clearEvent: clearEvent,
                stackHeightChanged: { _ in },
                hoverChanged: hoverChanged,
                dragDown: {},
                drawsSurface: false,
                allowsHoverPreview: false,
                allowsDragToExpand: false,
                contentLeadingInset: CaelestiaParityTokens.Padding.medium,
                contentTrailingInset: CaelestiaParityTokens.Padding.medium,
                contentTopInset: notificationFullscreenBubbleHeaderHeight
            )

            HStack(spacing: CaelestiaParityTokens.Spacing.small) {
                Label("NOTIFICATIONS", systemImage: "bell.badge")
                    .font(.system(size: CaelestiaParityTokens.Font.small, weight: .bold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                Spacer(minLength: 0)
                Text("\(queue.events.count)")
                    .font(.system(size: CaelestiaParityTokens.Font.smaller, weight: .semibold, design: .rounded))
                    .monospacedDigit()
                    .foregroundStyle(Theme.muted)
                Button(action: close) {
                    Image(systemName: "xmark")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(
                            width: CaelestiaParityTokens.Sizes.notificationBadge,
                            height: CaelestiaParityTokens.Sizes.notificationBadge
                        )
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(Theme.muted)
                .help("Close notifications")
            }
            .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
            .frame(height: notificationFullscreenBubbleHeaderHeight, alignment: .center)
        }
        .frame(width: notificationCaptureMockupWidth, height: surface.frameHeight)
        .background(
            Theme.frame.opacity(shellMaterialOpacity),
            in: RoundedRectangle(cornerRadius: notificationCornerRadius, style: .continuous)
        )
        .overlay {
            RoundedRectangle(cornerRadius: notificationCornerRadius, style: .continuous)
                .stroke(
                    Theme.accent.opacity(0.88),
                    style: ShellContourStyle.stroke
                )
        }
        .shadow(color: .black.opacity(0.28), radius: 18, y: 8)
        .clipShape(RoundedRectangle(cornerRadius: notificationCornerRadius, style: .continuous))
    }
}

/// The compact notification is the visual anchor for a promotion into the
/// full notification center. Reveal the incoming sidebar from its top edge so
/// the header and rows arrive in reading order while the host is still
/// growing. The shell-owned contour remains visible above this content mask
/// throughout the handoff.
private struct NotificationSidebarTopRevealShape: Shape {
    var progress: CGFloat

    var animatableData: CGFloat {
        get { progress }
        set { progress = newValue }
    }

    func path(in rect: CGRect) -> Path {
        let phase = min(1, max(0, progress))
        return Path(
            CGRect(
                x: rect.minX,
                y: rect.minY,
                width: rect.width,
                height: max(0, rect.height * phase)
            )
        )
    }
}

/// Keeps a compact notification surface alive while it grows into the
/// persistent notification center. The AppKit host is reused by the caller;
/// this view only stages the two bodies inside that one host so the user's eye
/// sees an expansion rather than a close followed by a new panel.
private struct NotificationSidebarExpansionView: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var queue: NotificationCaptureMockupQueue
    @ObservedObject var motion: SurfaceMotionState
    @ObservedObject var compactSurface: NotificationCaptureSurfaceState
    let topDepth: CGFloat
    let close: () -> Void
    let openEvent: (NotificationCaptureFixture) -> Void
    let clearEvent: (NotificationCaptureFixture) -> Void
    let clearAll: () -> Void
    let hoverChanged: (Bool) -> Void

    var body: some View {
        // This is the same handoff scalar used by RailPopoverLivingSurface.
        // The host frame, shell contour, and the two bodies must not each own
        // a separate animation clock: even a one-frame difference leaves the
        // old top-right shoulder visible after the compact card has gone.
        let phase = min(1, max(0, motion.contourAttachmentBlend))
        // The contour needs the first part of the handoff to establish the
        // shared upper shoulder. Keep the compact body intact for that same
        // band, then let the larger center take over in reading order instead
        // of crossfading two independently positioned card stacks at once.
        // Ease this local reveal too: a linear body phase paired with a
        // non-linear host made the card stack appear to pause and then catch
        // up during the lower half of the expansion.
        let bodyPhase: CGFloat = {
            let localPhase = max(
                0,
                min(
                    1,
                    (phase - notificationHandoffBodyStart)
                        / max(0.001, 1 - notificationHandoffBodyStart)
                )
            )
            return CGFloat(CaelestiaCurve.standard.value(at: Double(localPhase)))
        }()
        ZStack(alignment: .topTrailing) {
            NotificationCaptureMockupView(
                queue: queue,
                motion: motion,
                surface: compactSurface,
                topDepth: topDepth,
                openEvent: openEvent,
                clearEvent: clearEvent,
                stackHeightChanged: { _ in },
                hoverChanged: { _ in },
                dragDown: {},
                drawsSurface: false,
                allowsDragToExpand: false,
                contentLeadingInset: notificationHandoffContentLeadingInset,
                contentTrailingInset: notificationHandoffContentTrailingInset,
                contentTopInset: topDepth
            )
            // AppKit keeps the expanded tree pinned to its destination size
            // while the panel grows downward. The panel's top edge moves by
            // the display-rim depth; counter-offset the compact content so
            // its existing upper curve stays on the same screen row instead
            // of jumping with the newly mounted sidebar.
            .offset(y: motion.notificationHandoffTopOffset - topDepth)
            .opacity(1 - bodyPhase)

            CaelestiaSidebarView(
                model: model,
                queue: queue,
                motion: motion,
                close: close,
                openEvent: openEvent,
                clearEvent: clearEvent,
                clearAll: clearAll,
                hoverChanged: hoverChanged
            )
            .offset(
                y: motion.notificationHandoffTopOffset
                    + (1 - bodyPhase) * notificationHandoffBodySlide
            )
            // The top-anchored reveal and small settling offset keep the
            // expanded heading from blooming out of the middle of the compact
            // card while the host is still moving. At the end of the same
            // display-linked phase the mask opens fully and the sidebar owns
            // the whole body.
            .clipShape(NotificationSidebarTopRevealShape(progress: bodyPhase))
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)
        // The display link already supplies the only animation clock. Without
        // this transaction guard SwiftUI can add an implicit opacity/layout
        // animation on top of the AppKit frame and make the two silhouettes
        // arrive a frame apart.
        .transaction { transaction in
            transaction.animation = nil
        }
    }
}

/// The persistent notification center is a large right-attached surface. Its
/// outer reverse shoulders are supplied by `LivingSurface(.rightSidebar)` and
/// the shell-wide frame overlay. Inside that union, Caelestia still has a
/// distinct rounded `StyledRect` for the notification dock; omitting that
/// layer makes the upper shoulder look like a bare line and leaves the drawer
/// reading as a plain rectangle. The host and
/// dock intentionally share the same palette-aware frame token as ordinary
/// attached popouts: the rounded layer defines the envelope, not a black band.
private struct CaelestiaSidebarView: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var queue: NotificationCaptureMockupQueue
    @ObservedObject var motion: SurfaceMotionState
    let close: () -> Void
    let openEvent: (NotificationCaptureFixture) -> Void
    let clearEvent: (NotificationCaptureFixture) -> Void
    let clearAll: () -> Void
    let hoverChanged: (Bool) -> Void

    var body: some View {
        let contentCardTopInset = max(
            0,
            CaelestiaParityTokens.Padding.large - CaelestiaParityTokens.Border.minimumThickness
        )

        ZStack(alignment: .topLeading) {
            // Wrapper.qml gives Content.qml the same top envelope as its
            // loader margin minus the shell border. The host surface owns the
            // reverse shoulders, while this rounded layer owns the body that
            // continues between them and reaches the bottom edge. Both use
            // the popout's palette-aware shell frame so the envelope reads as
            // one surface.
            RoundedRectangle(
                cornerRadius: CaelestiaParityTokens.Rounding.large,
                style: .continuous
            )
            .fill(Theme.frame.opacity(shellMaterialOpacity))
            .padding(.top, contentCardTopInset)

            VStack(alignment: .leading, spacing: 0) {
                // Notifications and utilities are separate upstream modules.
                // Keeping the notification region in its own flexible stack
                // also anchors Clear All above the utility section instead of
                // letting it cover the bottom row of controls.
                ZStack(alignment: .bottomTrailing) {
                    VStack(alignment: .leading, spacing: CaelestiaParityTokens.Spacing.small) {
                        HStack(spacing: CaelestiaParityTokens.Spacing.small) {
                            Label("NOTIFICATIONS", systemImage: "bell.badge")
                                .font(.system(size: CaelestiaParityTokens.Font.normal, weight: .bold, design: .rounded))
                                .foregroundStyle(Theme.bright)
                            Spacer(minLength: 0)
                            Text("\(queue.events.count)")
                                .font(.system(size: CaelestiaParityTokens.Font.smaller, weight: .semibold, design: .rounded))
                                .monospacedDigit()
                                .foregroundStyle(Theme.muted)
                            Button(action: close) {
                                Image(systemName: "xmark")
                                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                                    .frame(width: CaelestiaParityTokens.Sizes.notificationBadge, height: CaelestiaParityTokens.Sizes.notificationBadge)
                                    .contentShape(Circle())
                            }
                            .buttonStyle(MicroButtonStyle())
                            .foregroundStyle(Theme.muted)
                            .help("Close sidebar")
                        }
                        .motionChild(motion, index: 1, offset: CGSize(width: 10, height: 0))

                        CaelestiaDivider(opacity: 0.35)
                            .motionChild(motion, index: 2, offset: CGSize(width: 10, height: 0))

                        Group {
                            if queue.events.isEmpty {
                                VStack(spacing: CaelestiaParityTokens.Spacing.small) {
                                    Image(systemName: "bell.slash")
                                        .font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                                        .foregroundStyle(Theme.muted)
                                }
                                .frame(maxWidth: .infinity, maxHeight: .infinity)
                            } else {
                                ScrollView(.vertical, showsIndicators: false) {
                                    // The expanded drawer is already capped at
                                    // the small notification ledger's 12-event
                                    // limit. Use a realized stack here so the
                                    // AppKit clip can reveal the same card tree
                                    // on every frame instead of LazyVStack
                                    // creating rows as the viewport grows.
                                    VStack(alignment: .leading, spacing: CaelestiaParityTokens.Spacing.extraSmall) {
                                        ForEach(Array(queue.events.enumerated()), id: \.element.id) { index, event in
                                            sidebarNotification(event)
                                                // Expanded notification cards
                                                // use the same content phase as
                                                // the compact cards and the
                                                // bottom-left utility tiles.
                                                .motionChild(
                                                    motion,
                                                    index: index + 3,
                                                    offset: CGSize(width: -8, height: 6)
                                                )
                                        }
                                    }
                                    .frame(maxWidth: .infinity, alignment: .leading)
                                    // Queue delivery and sidebar placement are
                                    // independent updates. Keep a newly
                                    // delivered notification from getting its
                                    // own insertion animation inside the drawer.
                                    .animation(nil, value: queue.events)
                                }
                                .scrollBounceBehavior(.basedOnSize)
                            }
                        }
                        .frame(maxHeight: .infinity)
                        .motionChild(motion, index: 3, offset: CGSize(width: 12, height: 0))

                    }
                    .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
                    .padding(.top, contentCardTopInset + CaelestiaParityTokens.Padding.medium)
                    .padding(.bottom, CaelestiaParityTokens.Padding.extraLarge)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)

                    if !queue.events.isEmpty {
                        Button(action: clearAll) {
                            Label("Clear all", systemImage: "trash")
                                .font(.system(size: CaelestiaParityTokens.Font.small, weight: .semibold, design: .rounded))
                                .labelStyle(.titleAndIcon)
                                .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
                                .frame(height: 30)
                        }
                        .buttonStyle(MicroButtonStyle())
                        .foregroundStyle(Theme.bright)
                        .background(Theme.layerTile, in: Capsule(style: .continuous))
                        .overlay(Capsule(style: .continuous).stroke(Theme.seam.opacity(0.34), lineWidth: 0.6))
                        // Keep the action aligned to the notification region's
                        // lower edge; the full inset made it float above the
                        // utility section by one extra gutter.
                        .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
                        .padding(.bottom, 0)
                        .help("Clear all notifications")
                        .motionChild(motion, index: 4, offset: CGSize(width: 0, height: 6))
                    }
                }
                .frame(maxHeight: .infinity)

                // The shared right-sidebar contour is already the shell-facing
                // edge of Wrapper.qml's content envelope. Content.qml's
                // NotifDock contributes the intended 12pt optical inset. The
                // utilities continue directly on the same shell surface so
                // there is no extra separator line in the compact host.
                CaelestiaSidebarUtilitiesView(model: model)
                    .padding(.horizontal, CaelestiaParityTokens.Padding.medium)
                    .padding(.top, CaelestiaParityTokens.Padding.medium)
                    .padding(.bottom, CaelestiaParityTokens.Padding.medium)
            }
            // The sidebar's shell-facing edge spends the first
            // `surfaceMorphShoulder` points turning out of the top rim. The
            // old zero inset put the header/card content on that exact clip
            // boundary, so the first icon and its text lost the optical
            // gutter. Reserve the geometric shoulder, then retain the normal
            // 12 pt section padding used inside the notification region.
            .padding(.leading, surfaceMorphShoulder)
            .padding(.trailing, CaelestiaParityTokens.Padding.extraSmall)
            .frame(width: sidebarWidth, alignment: .leading)
            .frame(maxHeight: .infinity)
        }
        .frame(width: sidebarWidth)
        .frame(maxHeight: .infinity)
        // ContentWindow.qml keeps the BlobRect `PanelBg` behind the nested
        // Content.qml StyledRect. Preserve both geometry layers, but use one
        // shared palette-aware shell frame: the inner layer is a shape envelope
        // rather than a contrasting black panel. `LivingSurface` clips both
        // layers to the shared silhouette, so the backing cannot introduce a
        // second outer border.
        .background(Theme.frame.opacity(shellMaterialOpacity))
        .contentShape(RightSidebarMorphShape(radius: shellAttachmentRadius(.rightSidebar)))
        .onHover(perform: hoverChanged)
    }

    private func sidebarNotification(_ event: NotificationCaptureFixture) -> some View {
        HStack(alignment: .top, spacing: CaelestiaParityTokens.Spacing.small) {
            Group {
                if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: event.appBundleID) {
                    Image(nsImage: NSWorkspace.shared.icon(forFile: url.path))
                        .resizable()
                        .interpolation(.high)
                        .scaledToFit()
                } else {
                    Image(systemName: event.icon)
                        .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.accent)
                }
            }
            .frame(width: 36, height: 36)
            .clipShape(RoundedRectangle(cornerRadius: Rounding.small, style: .continuous))

            VStack(alignment: .leading, spacing: 2) {
                HStack(spacing: CaelestiaParityTokens.Spacing.small) {
                    Text(event.appName.uppercased())
                        .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(1)
                    Spacer(minLength: 0)
                    Button { clearEvent(event) } label: {
                        Image(systemName: "xmark")
                            .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                            .foregroundStyle(Theme.muted)
                            .frame(width: 28, height: 28)
                    }
                    .buttonStyle(.plain)
                    .help("Clear notification")
                    .accessibilityLabel("Clear \(event.appName) notification")
                }
                Text(event.sensitive ? "Notification" : event.title)
                    .font(.system(size: CaelestiaParityTokens.Font.smaller, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .lineLimit(2)
                Text(event.sensitive ? "Preview hidden while this Mac is locked." : event.body)
                    .font(.system(size: CaelestiaParityTokens.Font.small, weight: .medium, design: .rounded))
                    .foregroundStyle(Theme.muted)
                    .lineLimit(3)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(CaelestiaParityTokens.Padding.small)
        .background(Theme.layerCard, in: RoundedRectangle(cornerRadius: CaelestiaParityTokens.Rounding.large, style: .continuous))
        .contentShape(RoundedRectangle(cornerRadius: CaelestiaParityTokens.Rounding.large, style: .continuous))
        .onTapGesture { openEvent(event) }
        .accessibilityLabel("\(event.appName): \(event.title)")
        .accessibilityHint("Open notification")
        .accessibilityAction(named: "Open notification") { openEvent(event) }
    }

}

/// The upstream notification dock does not own these controls; its sibling
/// `utilities` module does. This compact version uses only capabilities the
/// macOS model can actually mutate today. Bluetooth remains in its dedicated
/// device popout because this shell does not expose a reliable adapter-power
/// API, and a device connection is not the same thing as the radio toggle in
/// Caelestia's QML.
private struct CaelestiaSidebarUtilitiesView: View {
    @ObservedObject var model: ShellModel

    var body: some View {
        VStack(alignment: .leading, spacing: CaelestiaParityTokens.Spacing.medium) {
            Text("QUICK TOGGLES")
                .font(.system(size: CaelestiaParityTokens.Font.small, weight: .bold, design: .rounded))
                .foregroundStyle(Theme.muted)

            LazyVGrid(
                columns: Array(repeating: GridItem(.flexible(), spacing: CaelestiaParityTokens.Spacing.small), count: 4),
                spacing: CaelestiaParityTokens.Spacing.small
            ) {
                utilityButton(
                    title: "Wi-Fi",
                    symbol: model.wifiOn ? "wifi" : "wifi.slash",
                    active: model.wifiOn,
                    enabled: !model.wifiActionPending,
                    action: model.toggleWiFi
                )
                utilityButton(
                    title: "Focus",
                    symbol: model.focusEnabled ? "moon.fill" : "moon",
                    active: model.focusEnabled,
                    enabled: !model.focusMutationInFlight,
                    action: model.toggleFocus
                )
                utilityButton(
                    title: "Microphone",
                    symbol: model.microphoneMuted ? "mic.slash.fill" : "mic.fill",
                    active: !model.microphoneMuted,
                    enabled: model.microphoneMuteAvailable,
                    action: model.toggleMicrophoneMute
                )
                utilityButton(
                    title: "Settings",
                    symbol: "gearshape",
                    active: false,
                    action: { model.openURL("x-apple.systempreferences:") }
                )
            }
        }
        .padding(CaelestiaParityTokens.Padding.medium)
        .background(
            Theme.frame,
            in: RoundedRectangle(cornerRadius: CaelestiaParityTokens.Rounding.large, style: .continuous)
        )
    }

    private func utilityButton(
        title: String,
        symbol: String,
        active: Bool,
        enabled: Bool = true,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                .foregroundStyle(active ? Theme.ice : Theme.muted)
                .frame(maxWidth: .infinity)
                .frame(height: 38)
                .background(
                    Theme.layerCard,
                    in: RoundedRectangle(cornerRadius: CaelestiaParityTokens.Rounding.medium, style: .continuous)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: CaelestiaParityTokens.Rounding.medium, style: .continuous)
                        .stroke(Theme.seam.opacity(0.30), lineWidth: 0.7)
                )
        }
        .buttonStyle(MicroButtonStyle())
        .disabled(!enabled)
        .help(title)
        .accessibilityLabel(title)
        .accessibilityValue(active ? "On" : "Off")
    }
}

// END MARK: Notification capture UI mockup

private struct SideRail: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var visualState: RailVisualState
    @State private var hoveredIndex: Int?
    @State private var hoverTask: Task<Void, Never>?
    @State private var dropTargetWorkspace: Int?
    @State private var logoHovered = false
    @Namespace private var workspaceIndicator
    let onSelect: (Int) -> Void
    let onPower: () -> Void
    let onOpenNexus: () -> Void
    /// An intentional click owns Search and its keyboard focus. Hover has a
    /// separate passive Search preview so passing over the rail cannot
    /// activate Mac++, erase an in-progress query, or redirect typing from
    /// another app.
    var onOpenSearch: () -> Void = {}
    var onPreviewSearch: () -> Void = {}
    var onNexusHoverEnd: () -> Void = {}
    var onNotificationHover: (Bool) -> Void = { _ in }
    let onPopover: (RailPopoverKind?) -> Void
    let tools = [
        (1, "magnifyingglass", "Launcher"), (2, "waveform", "Media"),
        (3, "chart.bar.fill", "Performance"),
        (4, "bell", "Notifications")
    ]

    private func hoverIntent(
        _ inside: Bool,
        delay: Duration = .milliseconds(110),
        enter: @escaping @MainActor () -> Void,
        exit: @escaping @MainActor () -> Void = {}
    ) {
        hoverTask?.cancel()
        if inside {
            hoverTask = Task { @MainActor in
                try? await Task.sleep(for: delay) // macpp:silent-ok cancellation aborts the delayed hover action
                guard !Task.isCancelled else { return }
                enter()
            }
        } else {
            hoverTask = nil
            exit()
        }
    }

    private func hoverPopover(_ kind: RailPopoverKind, inside: Bool) {
        // SwiftUI can deliver a neighbouring button's exit after its enter
        // when the pointer crosses this tightly packed rail. Because all
        // hover previews share one intent task, accepting that stale exit
        // would cancel the new button's delayed open and schedule a close for
        // the card that just opened. The result is the "opens once, then only
        // works after leaving the rail" failure seen on the five workspaces.
        // An exit may cancel the task only while it still owns the current
        // hover; a delayed enter likewise has to re-check ownership before it
        // presents anything.
        if !inside,
           let hoveredKind = visualState.hoveredKind,
           hoveredKind != kind {
            return
        }
        setGlyphHover(kind, inside: inside)
        hoverIntent(
            inside,
            enter: {
                guard visualState.hoveredKind == kind else { return }
                onPopover(kind)
            },
            exit: {
                guard visualState.hoveredKind == nil else { return }
                onPopover(nil)
            }
        )
    }

    private func setGlyphHover(_ kind: RailPopoverKind, inside: Bool) {
        if inside {
            visualState.hoveredKind = kind
        } else if visualState.hoveredKind == kind {
            visualState.hoveredKind = nil
        }
    }

    private func glyphColor(for kind: RailPopoverKind) -> Color {
        if visualState.presentedKind == kind { return Theme.accent }
        if visualState.hoveredKind == kind { return Theme.bright }
        return Theme.muted
    }

    private func mediaLaneHeight(for availableHeight: CGFloat) -> CGFloat {
        CaelestiaParityGeometry.DisplayMetrics.mediaLaneHeight(for: availableHeight)
    }

    private func railContentScale(for availableHeight: CGFloat) -> CGFloat {
        CaelestiaParityGeometry.DisplayMetrics.railContentScale(for: availableHeight)
    }

    var body: some View {
        GeometryReader { geometry in
        let adaptiveMediaLaneHeight = mediaLaneHeight(for: geometry.size.height)
        let adaptiveRailScale = railContentScale(for: geometry.size.height)
        let railLayoutHeight = max(
            geometry.size.height,
            CaelestiaParityGeometry.DisplayMetrics.railMinimumContentHeight
        )
        // Keep the upper modules on one deliberate rhythm. Their individual
        // capsules establish hierarchy; the shared spacing keeps them reading
        // as one compact control cluster rather than a trail of loose icons.
        VStack(spacing: SideRailGeometry.upperSpacing) {
            // The rail logo is the direct Nexus entry point. The old path
            // opened a wide shell-controls popout first, which added an
            // unnecessary layer before reaching the actual dashboard.
            Button { onOpenNexus() } label: {
                // Caelestia's own OsIcon (the logo/distro-icon button this
                // stands in for) is a bare icon with no background pill at
                // all -- no StyledRect wrapper, just the glyph. Workspaces
                // and StatusIcons are real caelestia StyledRect/
                // StyledClippingRect pills, but this one isn't.
                Image(systemName: "apple.logo").font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded))
                    .foregroundStyle(logoHovered ? Theme.bright : Theme.ice)
                    .frame(width: 39, height: SideRailGeometry.logoHeight).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .onHover { logoHovered = $0 }
            .animation(ShellMotion.hover.animation, value: logoHovered)
            .help("Open Nexus")
            VStack(spacing: SideRailGeometry.workspaceSpacing) {
                ForEach(1...CaelestiaParityTokens.Sizes.workspaceCount, id: \.self) { workspace in
                    let popoverKind = RailPopoverKind.workspace(workspace)
                    let workspaceHovered = visualState.hoveredKind == popoverKind
                    let workspacePresented = visualState.presentedKind == popoverKind
                    let workspaceInfo = model.workspaces.first(where: { $0.id == workspace })
                    let workspaceAvailable = workspaceInfo?.available == true
                    let workspaceOccupied = workspaceAvailable && (
                        workspaceInfo?.windows.isEmpty == false || workspaceInfo?.apps.isEmpty == false
                    )
                    Button {
                        guard workspaceAvailable else { return }
                        model.focusSpace(workspace)
                    } label: {
                        ZStack {
                            if workspaceAvailable && model.currentWorkspace == workspace {
                                // Caelestia's active indicator is a scaled
                                // shape inside the 40pt workspace capsule.
                                // Keep the active/occupied hierarchy instead
                                // of turning every workspace into a numbered
                                // button: empty is a small dot, occupied is a
                                // small square, and active is the largest dot.
                                Circle()
                                    .fill(Theme.accent)
                                    .frame(width: SideRailGeometry.workspaceButtonSize * 2 / 3,
                                           height: SideRailGeometry.workspaceButtonSize * 2 / 3)
                                    .matchedGeometryEffect(id: "workspace-indicator", in: workspaceIndicator)
                            } else if workspaceOccupied {
                                RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous)
                                    .fill(workspacePresented || workspaceHovered ? Theme.bright : Theme.muted)
                                    .frame(width: SideRailGeometry.workspaceButtonSize / 3,
                                           height: SideRailGeometry.workspaceButtonSize / 3)
                            } else {
                                Circle()
                                    .fill((workspacePresented || workspaceHovered ? Theme.bright : Theme.muted).opacity(0.72))
                                    .frame(width: SideRailGeometry.workspaceButtonSize / 4,
                                           height: SideRailGeometry.workspaceButtonSize / 4)
                            }
                            // Keep the drop affordance inside the existing
                            // hit target so it never changes the rail's
                            // layout. The ring grows around the indicator
                            // only while a window is being dragged over it.
                            if dropTargetWorkspace == workspace {
                                Circle()
                                    .stroke(Theme.accent, lineWidth: 1.25)
                                    .scaleEffect(1.22)
                                    .opacity(0.92)
                            }
                        }
                        .frame(
                            width: SideRailGeometry.workspaceButtonSize,
                            height: SideRailGeometry.workspaceButtonSize
                        )
                        // The visible workspace mark is intentionally tiny;
                        // make the whole authored button frame the hover/click
                        // target so moving between adjacent spaces does not
                        // depend on landing directly on the dot or square.
                        .contentShape(Rectangle())
                        .animation(ShellMotion.workspace.animation, value: dropTargetWorkspace == workspace)
                        .animation(ShellMotion.hover.animation, value: workspaceHovered)
                        .animation(ShellMotion.panelSwitch.animation, value: workspacePresented)
                    }
                    .buttonStyle(.plain)
                    .disabled(!workspaceAvailable)
                    .opacity(workspaceAvailable ? 1 : 0.52)
                    .onDrop(of: [UTType.text.identifier], isTargeted: Binding(
                        get: { dropTargetWorkspace == workspace },
                        set: { isTargeted in
                            if isTargeted {
                                dropTargetWorkspace = workspace
                            } else if dropTargetWorkspace == workspace {
                                dropTargetWorkspace = nil
                            }
                        }
                    )) { providers in
                        guard workspaceAvailable else { return false }
                        return model.acceptWindowDrop(providers, toSpace: workspace)
                    }
                    .onHover { inside in
                        guard workspaceAvailable else { return }
                        hoverPopover(.workspace(workspace), inside: inside)
                    }
                    .help(workspaceAvailable
                        ? "Workspace \(workspace) • drop a window here to move it"
                        : "Workspace \(workspace) is not available")
                }
            }
            .padding(.vertical, SideRailGeometry.workspaceVerticalPadding)
            .frame(width: 39)
            .railLayer()
            // Belt-and-suspenders against the pill background sticking to
            // whatever palette was active when this subview was first built.
            // Explicitly keying this on the palette forces SwiftUI to treat
            // each palette as a distinct identity for this pill, so it can't
            // silently keep rendering with a stale captured color.
            .id(model.selectedPalette.rawValue)
            .animation(ShellMotion.workspaceIndicator.animation, value: model.currentWorkspace)
            VStack(spacing: 0) {
                ForEach(tools, id: \.0) { tool in
                    RailButton(symbol: tool.1, active: tool.0 == model.selectedTab) {
                        if tool.0 == 1 {
                            // A click converts any pending/visible passive
                            // preview into an intentional, focused Search.
                            // Cancel the delayed hover task first so it cannot
                            // fire after Search has already taken ownership.
                            hoverTask?.cancel()
                            hoverTask = nil
                            if hoveredIndex == tool.0 { hoveredIndex = nil }
                            onOpenSearch()
                            return
                        }
                        if tool.0 == 4 {
                            // Cancel only the delayed open. Preserve the real
                            // hover flag so the physical exit is still
                            // delivered after this click; clearing it here
                            // stranded the now-pinned stack open indefinitely.
                            hoverTask?.cancel()
                            hoverTask = nil
                        }
                        model.selectedTab = tool.0; onSelect(tool.0)
                    }.onHover { inside in
                        if tool.0 == 4 {
                            if inside {
                                hoveredIndex = tool.0
                                hoverIntent(true, enter: {
                                    guard hoveredIndex == tool.0 else { return }
                                    onNotificationHover(true)
                                })
                            } else {
                                // Always release the delegate's bell-hover
                                // flag. Entering a neighbouring tool can
                                // change hoveredIndex before AppKit delivers
                                // this exit, but the notification surface must
                                // still learn that the bell was left.
                                if hoveredIndex == tool.0 {
                                    hoveredIndex = nil
                                    hoverTask?.cancel(); hoverTask = nil
                                }
                                onNotificationHover(false)
                            }
                            return
                        }
                        // Search hover shows the same launcher in a passive,
                        // non-key state. The click path below still promotes
                        // it to focused Search, so hover discovery never
                        // steals keyboard focus or changes an in-progress
                        // query, and it cannot unexpectedly open Nexus.
                        //
                        // Media and Performance keep their authored hover
                        // popouts: those glyphs open what they depict.
                        if [1, 2, 3].contains(tool.0) {
                            if inside {
                                hoveredIndex = tool.0
                                hoverIntent(true, enter: {
                                    guard hoveredIndex == tool.0 else { return }
                                    if tool.0 == 1 {
                                        onPreviewSearch()
                                    } else {
                                        model.selectedTab = tool.0
                                        onSelect(tool.0)
                                    }
                                })
                            } else if hoveredIndex == tool.0 {
                                hoveredIndex = nil
                                hoverTask?.cancel(); hoverTask = nil
                            }
                            // The pointer can enter the next rail button
                            // before AppKit delivers this exit, which changes
                            // hoveredIndex first. Search's hover preview still
                            // needs its grace-period close in that case.
                            if !inside, tool.0 == 1 { onNexusHoverEnd() }
                        }
                    }
                    .help(tool.0 == 1 ? "Click for Search · hover to preview Search" : tool.2)
                    .accessibilityLabel(tool.0 == 1 ? "Search" : tool.2)
                    .accessibilityHint(tool.0 == 1
                        ? "Click to open focused Search. Hover previews Search without moving keyboard focus."
                        : "Open \(tool.2)")
                }
                Capsule(style: .continuous)
                    .fill(Theme.seam.opacity(0.55))
                    .frame(width: 18, height: 1)
                    .padding(.vertical, 3)
                Image(nsImage: model.frontAppIcon)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: 21, height: 21)
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous))
                    .overlay {
                        RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous)
                            .stroke(
                                visualState.presentedKind == .activeApp
                                    ? Theme.accent
                                    : (visualState.hoveredKind == .activeApp ? Theme.bright : Theme.seam.opacity(0.5)),
                                lineWidth: 0.75
                            )
                    }
                    .frame(width: 34, height: SideRailGeometry.toolButtonHeight)
                    .contentShape(Rectangle())
                    .onHover { inside in hoverPopover(.activeApp, inside: inside) }
                    .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .activeApp)
                    .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .activeApp)
                    .help(model.frontApp)
            }
            .padding(.vertical, SideRailGeometry.toolStackVerticalPadding)
            .frame(width: 39)
            .railLayer()
            // The module's capsule uses palette-derived material; refresh its
            // identity with the other rail pills when the palette changes.
            .id(model.selectedPalette.rawValue)
            Spacer(minLength: 8)
            ZStack {
                if !model.media.title.isEmpty {
                    // The rotated ticker remains the glance-level resting
                    // state, while this same reserved lane is its hit target.
                    Color.clear.frame(width: 30, height: adaptiveMediaLaneHeight)
                        .contentShape(Rectangle())
                        .onHover { inside in hoverPopover(.media, inside: inside) }
                        .help("Now playing: \(model.media.title)")
                        .transition(.opacity.combined(with: .scale(scale: ShellMotion.initialScale)))
                }
            }
            .frame(width: 39, height: adaptiveMediaLaneHeight)
            .animation(ShellMotion.panelSwitch.animation, value: adaptiveMediaLaneHeight)
            // The copied Caelestia rail intentionally keeps app navigation out
            // of this crowded lane. Active apps live in the transient,
            // display-wide bottom shelf instead of reserving rail height.
            // Fixed-size block, not flexible: this whole group is pinned to
            // the bottom of the rail by the Spacers above it. Using
            // Spacer(minLength:) *inside* it as well made it compete with
            // those outer Spacers for the same slack, which is what pushed
            // the clock out of view and left the cluster floating too high.
            // Plain fixed padding keeps its total height constant instead.
            VStack(spacing: 3) {
                // Caelestia's clock is two stacked, unrotated digit groups
                // (hour over minute), not a single sideways-scrolling label.
                Button { onOpenNexus() } label: {
                    // monospacedDigit, not a fully monospaced face: the rail
                    // is narrow enough that a proportional "1" would visibly
                    // shift the clock every time the minute rolled past one,
                    // but only the digits need fixed advance widths -- the
                    // rest of the shell keeps the rounded face.
                    RailClockFace(
                        date: model.now,
                        palette: model.selectedPalette,
                        paletteRevision: model.companionRevision,
                        hovered: visualState.hoveredKind == .calendar,
                        active: visualState.presentedKind == .calendar
                    )
                    .equatable()
                    // valueChange, not panelSwitch. panelSwitch is a 0.50s
                    // *overshooting* spatial curve meant for swapping one
                    // surface for another; driving a digit roll with it made
                    // the clock wobble past its value and settle back. Every
                    // other numeric readout in the shell uses valueChange.
                    // Minute changes stay static inside the rail. Animating
                    // this value in the same render transaction as a top-card
                    // switch made the digits inherit the panel replacement and
                    // briefly draw in the wrong geometry.
                }
                .buttonStyle(.plain)
                .onHover { setGlyphHover(.calendar, inside: $0) }
                .help("Open Nexus (calendar & overview)")
                    .padding(.bottom, 4)
                // Real caelestia's StatusIcons is its own single StyledRect
                // holding every status indicator -- network, bluetooth,
                // audio, battery -- as one grouped column with one shared
                // background. Clock and Power are separate bar components
                // with no shared pill of their own, so only this cluster
                // gets a background; the clock button and power button
                // above/below it render as plain icons, not part of a pill.
                // Icons trimmed down from 39x27 -- that read as clunky,
                // oversized tiles next to caelestia's much smaller glyphs.
                VStack(spacing: 1) {
                    Button { onPopover(.wifi) } label: {
                        CaelestiaSymbol(model.wifiOn ? "wifi" : "wifi.slash", size: 15)
                            .foregroundStyle(glyphColor(for: .wifi)).frame(width: 34, height: 24).contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .onHover { setGlyphHover(.wifi, inside: $0) }
                    .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .wifi)
                    .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .wifi)
                    .help("Wi-Fi networks")
                    Button { onPopover(.bluetooth) } label: {
                        // Rest is quiet like its Wi-Fi/audio neighbours;
                        // hover and the presented device card supply the
                        // shared bright/accent interaction tint.
                        BluetoothMark(color: glyphColor(for: .bluetooth), size: 16)
                            .frame(width: 34, height: 24).contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .onHover { setGlyphHover(.bluetooth, inside: $0) }
                    .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .bluetooth)
                    .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .bluetooth)
                    .help("Bluetooth devices")
                    Button { onPopover(.audio) } label: {
                        CaelestiaSymbol(model.volumeSymbol, size: 15)
                            .foregroundStyle(glyphColor(for: .audio)).frame(width: 34, height: 24).contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .onHover { setGlyphHover(.audio, inside: $0) }
                    .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .audio)
                    .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .audio)
                    .help("Audio: routing")
                    // Focus and microphone mute deliberately do NOT live here.
                    // Every other row in this pill is a single full-width 34pt
                    // status glyph; splitting one row into two 17pt halves gave
                    // the cluster a ragged, cramped row that read as a layout
                    // fault rather than a control, and neither toggle is a
                    // *status* the way Wi-Fi, Bluetooth, audio and battery are.
                    // Both remain one click away in the audio popout below and
                    // in Nexus' Audio Lab, which is where stateful toggles that
                    // need a label belong.
                    //
                    // Battery gets its popout back, with a real reason to
                    // open one this time: a Battery Saver (power-saving)
                    // toggle, not just a detail readout. BatteryGlyph still
                    // draws its own stroke/fill color internally rather than
                    // inheriting foregroundStyle, so pass the interaction
                    // tint explicitly while preserving its critical red.
                    Button { onPopover(.battery) } label: {
                        BatteryGlyph(model: model, size: 13, interactionTint: glyphColor(for: .battery))
                            .frame(width: 34, height: 24).contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .onHover { setGlyphHover(.battery, inside: $0) }
                    .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .battery)
                    .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .battery)
                    .help("\(model.batteryPercent)% \(model.charging ? "(charging)" : "battery")")
                }
                .padding(.vertical, 3)
                .railLayer()
                // Same belt-and-suspenders fix as the workspace pill above --
                // this is the one the White-mode-leftover screenshot showed:
                // the pill background stuck to its previous palette's color
                // instead of picking up the new one.
                .id(model.selectedPalette.rawValue)
                // Kept close to the pill instead of the wider separation
                // tried earlier -- caelestia's own power button sits right
                // under the status cluster with only a hairline of space.
                Button { onPower() } label: {
                    Image(systemName: "power").font(.system(size: ShellIcon.large, weight: .bold, design: .rounded))
                        .foregroundStyle(glyphColor(for: .power))
                        .frame(width: 34, height: 27).contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .onHover { setGlyphHover(.power, inside: $0) }
                .animation(ShellMotion.hover.animation, value: visualState.hoveredKind == .power)
                .animation(ShellMotion.panelSwitch.animation, value: visualState.presentedKind == .power)
                .help("Power menu")
                    .padding(.top, 6)
            }
            // This whole block is bottom-pinned by the Spacers further up
            // the rail, so its own bottom padding is what actually controls
            // how close Power sits to the true bottom edge -- growing the
            // gap *above* Power (the padding on the button itself, above)
            // only pushes the pill further up, not Power further down.
            // Trimming the padding after it is what moves it down.
            .padding(.top, 5)
            .frame(width: 39)
        }.padding(.top, SideRailGeometry.outerTopPadding)
            .padding(.bottom, SideRailGeometry.outerBottomPadding)
            .frame(width: railWidth, height: railLayoutHeight)
            // Preserve the authored rail exactly while it fits. On a very
            // short built-in display, the media lane has already yielded; this
            // final uniform reduction keeps the workspace/status/power group
            // inside the screen instead of letting the bottom controls clip.
            .scaleEffect(adaptiveRailScale, anchor: .bottom)
            .frame(width: railWidth, height: geometry.size.height, alignment: .bottom)
            // The persistent inner contour is centered on the rail's trailing
            // edge. The rail window sits above that frame layer, so a full
            // background here used to cover half of the 2pt stroke only on the
            // left side. Keep the window and hit area at the full rail width,
            // but stop its opaque background at the contour's inner edge.
            .background(alignment: .leading) {
                Theme.frame.opacity(shellMaterialOpacity)
                    .frame(width: max(0, railWidth - ShellContourStyle.width / 2))
            }
        }
        .frame(width: railWidth)
        .onDisappear {
            hoverTask?.cancel()
            hoverTask = nil
            hoveredIndex = nil
            dropTargetWorkspace = nil
            visualState.hoveredKind = nil
            onNotificationHover(false)
            onNexusHoverEnd()
            onPopover(nil)
        }
    }

}

private extension View {
    func railLayer() -> some View {
        background {
            // The rail's own chrome is Theme.frame, so any fill mixed *from*
            // frame (like layerCard) barely separates from it. railPill mixes
            // frame toward accent instead, which gives a real tinted
            // capsule that stays visible on every palette, including Midnight
            // Blue, without touching layerCard/layerGroup used elsewhere.
            // A fixed cornerRadius RoundedRectangle only fully rounds when
            // the radius reaches half the shortest side -- on a narrow,
            // tall rail pill that left the top/bottom flattened instead of
            // reading as a true capsule. Capsule() always resolves its
            // curve from the view's own size, so the ends stay fully round
            // no matter how tall the stack of icons inside makes the pill.
            Capsule(style: .continuous)
                .fill(Theme.railPill)
        }
        // This background is plain and static -- no SurfaceMotionState, no
        // LivingSurface mask, nothing animated -- so a stroke here carries
        // none of the border-vs-motion-timing risk the popout surfaces do.
        // A hairline seam gives the pill a real edge instead of leaning on
        // fill contrast alone.
        .overlay {
            Capsule(style: .continuous)
                .stroke(Theme.seam.opacity(0.3), lineWidth: 0.75)
        }
    }
}

