                    .frame(width: 8, height: 8)
                Text(palette.shortTitle)
                    .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                    .lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
            }
            .foregroundStyle(selected ? Theme.bright : Theme.muted)
            .padding(.horizontal, Spacing.tight)
            .frame(minWidth: 38)
            .frame(height: 30)
            .background(selected ? Theme.tile : Color.clear, in: Capsule())
        }
        .buttonStyle(MicroButtonStyle())
    }
}

private struct MacPlusPlusTimedLyric: Identifiable, Equatable {
    let id = UUID()
    let time: Double
    let text: String
}

private struct MacPlusPlusNexusConfiguration: Codable, Equatable {
    var captureDirectory = "~/Pictures/Screenshots"
    var screenshotFormat = "png"
    var includeCursor = false
    var recordMicrophone = false
    var lyricsEnabled = true
    var idleSuspendEnabled = true
    var softLockAfterScreensaverEnabled = false
    var utilities = ["capture", "audio", "lyrics", "appearance"]

    private enum CodingKeys: String, CodingKey {
        case captureDirectory
        case screenshotFormat
        case includeCursor
        case recordMicrophone
        case lyricsEnabled
        case idleSuspendEnabled
        case softLockAfterScreensaverEnabled
        case utilities
    }

    init() {}

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        captureDirectory = try container.decodeIfPresent(String.self, forKey: .captureDirectory)
            ?? "~/Pictures/Screenshots"
        screenshotFormat = try container.decodeIfPresent(String.self, forKey: .screenshotFormat)
            ?? "png"
        includeCursor = try container.decodeIfPresent(Bool.self, forKey: .includeCursor) ?? false
        recordMicrophone = try container.decodeIfPresent(Bool.self, forKey: .recordMicrophone) ?? false
        lyricsEnabled = try container.decodeIfPresent(Bool.self, forKey: .lyricsEnabled) ?? true
        // Older Nexus files predate the idle chain toggle. Preserve their
        // existing policy until the user explicitly changes this switch.
        idleSuspendEnabled = try container.decodeIfPresent(Bool.self, forKey: .idleSuspendEnabled) ?? true
        // This is a new opt-in path. Missing keys stay off so upgrading the
        // shell cannot silently replace the existing native lock action.
        softLockAfterScreensaverEnabled = try container.decodeIfPresent(
            Bool.self,
            forKey: .softLockAfterScreensaverEnabled
        ) ?? false
        utilities = try container.decodeIfPresent([String].self, forKey: .utilities)
            ?? ["capture", "audio", "lyrics", "appearance"]
    }

    static let `default` = MacPlusPlusNexusConfiguration()
}

/// A deliberately small, value-typed row for Observatory.  It is populated
/// from read-only process checks. Failed services remain visible without
/// being restarted by the dashboard.
private struct MacPlusPlusObservatoryRuntimeRow: Identifiable, Equatable, Sendable {
    let id: String
    let title: String
    let detail: String
    let healthy: Bool
    let symbol: String
}

// MACPP_OBSERVATORY_RUNTIME_PROBE_BEGIN
/// One direct owner query produces no stdout at all, so the process cannot
/// deadlock behind a full pipe. The deadline is an additional fail-open bound:
/// a damaged process table or executable can make one row stale, but it can
/// never retain Observatory's utility task indefinitely.
private enum MacPlusPlusObservatoryRuntimeOwnerProbe {
    static func commandSucceeds(
        executable: String,
        arguments: [String],
        timeout: TimeInterval
    ) -> Bool {
        let process = Process()
        let exited = DispatchSemaphore(value: 0)
        process.executableURL = URL(fileURLWithPath: executable)
        process.arguments = arguments
        process.standardOutput = FileHandle.nullDevice
        process.standardError = FileHandle.nullDevice
        process.terminationHandler = { _ in exited.signal() }
        do {
            try process.run()
        } catch {
            return false
        }

        guard exited.wait(timeout: .now() + timeout) == .success else {
            if process.isRunning { process.terminate() }
            if exited.wait(timeout: .now() + 0.10) == .timedOut, process.isRunning {
                _ = Darwin.kill(process.processIdentifier, SIGKILL)
                _ = exited.wait(timeout: .now() + 0.10)
            }
            return false
        }
        return process.terminationStatus == 0
    }

    static func isRunning(pattern: String) -> Bool {
        // `-q` is the important ownership boundary: pgrep returns only an exit
        // status. `-a` includes Mac++ Shell itself when it is the probe's parent;
        // pgrep otherwise excludes all ancestors from full-command matching.
        // `-i` preserves the former localized-case-insensitive substring check.
        commandSucceeds(
            executable: "/usr/bin/pgrep",
            arguments: ["-a", "-i", "-q", "-f", pattern],
            timeout: 0.35
        )
    }
}
// MACPP_OBSERVATORY_RUNTIME_PROBE_END

private struct MacPlusPlusObservatoryRuntimeOwnerCheck: Sendable {
    let title: String
    let pattern: String
    let symbol: String
}

private let macppObservatoryRuntimeOwnerChecks: [MacPlusPlusObservatoryRuntimeOwnerCheck] = [
    MacPlusPlusObservatoryRuntimeOwnerCheck(
        // `pgrep -f` treats its pattern as an extended regular expression;
        // the literal plus signs must be escaped or the probe reports a
        // running Mac++ Shell as invalid/not running.
        title: "MACPP SHELL", pattern: "Mac\\+\\+ Shell", symbol: "app"
    ),
    MacPlusPlusObservatoryRuntimeOwnerCheck(
        title: "AUDIO FEED", pattern: "Mac\\+\\+ Audio Puller", symbol: "waveform.path.ecg"
    ),
]

private struct MacPlusPlusObservatoryCapabilityRow: Identifiable, Equatable, Sendable {
    let id: String
    let title: String
    let evidence: String
    let status: String
    let healthy: Bool
    let required: Bool
    let symbol: String
}

private struct MacPlusPlusMetricsTrendPoint: Identifiable, Equatable, Sendable {
