@MainActor private final class MacPlusPlusNexusModel: ObservableObject {
    /// The ten bands are an octave apart and each peaking filter runs at Q=1,
    /// so every one is about 1.4 octaves wide and neighbours overlap heavily.
    /// Their boosts therefore compound: the resulting curve looks very little
    /// like the list of per-band numbers, which is why these used to be
    /// subtly wrong in ways that were hard to hear as any one thing.
    ///
    /// Rather than being hand-picked, each of these is now a least-squares fit
    /// of the *cascaded* response to an explicit target shape, computed against
    /// the same biquad formula MacPlusPlusEQ uses. Every one lands within 0.8 dB of
    /// its intended curve across 20 Hz-20 kHz.
    enum EQPreset: String, CaseIterable, Identifiable {
        case flat, warm, clarity, bass, hardcore, vocals, night
        var id: String { rawValue }
        var title: String { rawValue.uppercased() }
        var gains: [Double] {
            MacPlusPlusPureLogic.eqPresetGains(named: rawValue)
                ?? Array(repeating: 0, count: 10)
        }
    }

    enum Page: String, CaseIterable, Identifiable {
        // Keep the upstream Nexus destinations as first-class pages. The
        // Mac++ dashboard, media, and system tools remain available as a
        // small extension group at the end rather than defining the shell's
        // primary navigation language.
        case setup, settings, network, devices, audio, updates, capture, apps, observatory, language, about
        case overview, media, system
        var id: String { rawValue }
        var title: String {
            switch self {
            case .setup: return "SETUP MANAGER"
            case .settings: return "WALLPAPER & STYLE"
            case .network: return "NETWORK"
            case .devices: return "BLUETOOTH & DEVICES"
            case .audio: return "AUDIO"
            case .updates: return "UPDATES"
            case .capture: return "PANELS"
            case .apps: return "APPS"
            case .observatory: return "SERVICES"
            case .language: return "LANGUAGE & REGION"
            case .about: return "ABOUT"
            case .overview: return "OVERVIEW"
            case .media: return "MEDIA"
            case .system: return "SYSTEM"
            }
        }
        var displayTitle: String {
            switch self {
            case .setup: return "Setup Manager"
            case .settings: return "Wallpaper & style"
            case .network: return "Network"
            case .devices: return "Bluetooth & devices"
            case .audio: return "Audio"
            case .updates: return "Updates"
            case .capture: return "Panels"
            case .apps: return "Apps"
            case .observatory: return "Services"
            case .language: return "Language & region"
            case .about: return "About"
            case .overview: return "Overview"
            case .media: return "Media"
            case .system: return "System"
            }
        }
        var symbol: String {
            switch self {
            case .setup: return "checklist"
            case .settings: return "paintpalette"
            case .network: return "wifi"
            case .devices: return "dot.radiowaves.left.and.right"
            case .audio: return "speaker.wave.2.fill"
            case .updates: return "arrow.triangle.2.circlepath"
            case .capture: return "rectangle.3.group"
            case .apps: return "square.grid.2x2"
            case .observatory: return "wrench.and.screwdriver"
            case .language: return "globe"
            case .about: return "info.circle"
            case .overview: return "chart.bar.xaxis"
            case .media: return "music.note.list"
            case .system: return "gearshape.2"
            }
        }
    }

    // Nexus page changes are explicit: navigation requires a click or a
    // keyboard command. Pointer hover only provides visual feedback and must
    // not silently move the dashboard to another page.
    @Published var page: Page = .settings

    @Published var configuration: MacPlusPlusNexusConfiguration
    @Published var softLockConfiguration = MacPlusPlusSoftLockConfiguration.load()
    @Published var softLockResetStatus = ""
    @Published var status = "READY"
    // Media owns its own feedback. A configuration save, capture, route
    // change, or runtime repair must never leak into the lyrics surface just
    // because those operations share the Nexus model.
    @Published var lyricsStatus = "PLAY SOMETHING"
    @Published var lyrics = ""
    @Published var syncedLyrics: [MacPlusPlusTimedLyric] = []
    @Published var lyricsLoading = false
    @Published var outputDevices: [SystemOutputAudio.Device] = []
    @Published var selectedOutputDeviceID = AudioDeviceID(kAudioObjectUnknown)
    @Published var selectedOutputRouteID: String? = nil
    @Published var outputBalance = 0.5
    @Published var balanceAvailable = false
    @Published var inputDevices: [SystemInputAudio.Device] = []
    @Published var selectedInputDeviceID = AudioDeviceID(kAudioObjectUnknown)
    @Published var eqEnabled = false
    @Published var eqBands: [Double] = Array(repeating: 0, count: 10)
    @Published var eqPreamp = 0.0
    @Published var eqPreset: EQPreset = .flat
    @Published var eqState = "BYPASSED"
    @Published var eqDetail = "Direct system output"
    @Published var topProcesses: [String] = []
    @Published var runtimeRows: [MacPlusPlusObservatoryRuntimeRow] = []
    @Published var capabilityRows: [MacPlusPlusObservatoryCapabilityRow] = []
    @Published var capabilitiesHealthy = false
    @Published var capabilityStatus = "CHECKING"
    @Published var repairingRuntime = false
    @Published var metricsTrend: [MacPlusPlusMetricsTrendPoint] = []
    @Published var metricsHistoryStatus = "COLLECTING"
    @Published var screenTimeEntries: [MacPlusPlusScreenTimeEntry] = []
    @Published var screenTimeStatus = "COLLECTING"
    @Published var desktopLayerEnabled = false
    @Published var desktopCenterClockEnabled = false
    @Published var desktopVisualizerEnabled = true
    @Published var desktopVisualizerStyle = "bars"
    @Published var desktopLayerMode = "panel"
    @Published var desktopLayerStatus = "CHECKING"
    @Published var networkInterface = "—"
    @Published var networkName = "OFFLINE"
    @Published var networkDown = "0 KB/s"
    @Published var networkUp = "0 KB/s"
    @Published var networkLatency = "—"
    @Published var speedTestRunning = false
    @Published var speedTestDownload = "—"
    @Published var speedTestUpload = "—"
    @Published var speedTestLatency = "—"
    @Published var speedTestLastRun = "NOT TESTED"
    private var lastLyricsKey = ""
    private var lyricsTask: Task<Void, Never>?
    private var lyricsGeneration = 0
    private var eqStateTimer: Timer?
    private var telemetryTimer: Timer?
    private var telemetryTask: Task<Void, Never>?
    private var telemetryGeneration = 0
    private var nexusVisible = false
    private var telemetryPage: Page = .overview
    private var capabilityRefreshInFlight = false
    private var lastCapabilityRefresh = Date.distantPast
    private var metricsHistoryRefreshInFlight = false
    private var lastMetricsHistoryRefresh = Date.distantPast
    private var screenTimeRefreshInFlight = false
    private var lastScreenTimeRefresh = Date.distantPast
    private var runtimeRefreshInFlight = false
    private var lastNetworkBytes: (received: UInt64, sent: UInt64, date: Date)?
    private var audioRefreshGeneration = 0
    private var softLockResetTask: Task<Void, Never>?
    // The last AirPlay routes a Bonjour browse actually found. See
    // `refreshAudio` for why this is kept instead of starting each refresh
    // from an empty list.
    private var lastKnownAirPlayRoutes: [SystemOutputAudio.Device] = []
    private static var configurationURL: URL {
        FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus", isDirectory: true)
            .appendingPathComponent("nexus.json")
    }

