    private static let desktopVisualizerStyles: Set<String> = [
        "bars", "bars-compact", "bars-tall", "ring", "ring-color", "grid"
    ]
    private static let desktopLayerModes: Set<String> = ["panel", "fullDesktop"]

    init() {
        if let data = try? Data(contentsOf: Self.configurationURL), // macpp:silent-ok absent configuration uses defaults below
           let decoded = try? JSONDecoder().decode(MacPlusPlusNexusConfiguration.self, from: data) { // macpp:silent-ok malformed configuration uses defaults below
            configuration = decoded
            // Re-save through the current Codable shape so preferences from
            // retired experiments (hot corners, display profiles, reminders,
            // adaptive brightness, and the shader layer) disappear from the
            // live file instead of lingering as dead configuration forever.
            save()
        } else {
            configuration = .default
            save()
        }
        let retiredDefaults = UserDefaults.standard
        for key in [
            "macppBreakRemindersEnabled",
            "macppAdaptiveBrightnessEnabled",
            "macppCursorStyle"
        ] {
            retiredDefaults.removeObject(forKey: key)
        }
        retiredDefaults.synchronize()
        // Migrate the retired capture folder so existing installations follow
        // the single Screenshots library used by Finder and the sorter.
        if configuration.captureDirectory == "~/Pictures/MacPlusPlus Captures" {
            configuration.captureDirectory = "~/Pictures/Screenshots"
            save()
        }
        loadEQ()
        loadScreenTimeSnapshot()
        refreshAudio()
        refreshDesktopLayer()
    }

    var selectedOutputDevice: SystemOutputAudio.Device? {
        if let selectedOutputRouteID {
            return outputDevices.first { $0.routeID == selectedOutputRouteID }
        }
        return outputDevices.first { !$0.isAirPlayRoute && $0.id == selectedOutputDeviceID }
    }

    func isSelectedOutputDevice(_ device: SystemOutputAudio.Device) -> Bool {
        if let selectedOutputRouteID {
            return device.routeID == selectedOutputRouteID
        }
        return !device.isAirPlayRoute && device.id == selectedOutputDeviceID
    }
    var selectedInputDevice: SystemInputAudio.Device? {
        inputDevices.first { $0.id == selectedInputDeviceID }
    }

    func refreshAudio() {
        audioRefreshGeneration &+= 1
        let refreshGeneration = audioRefreshGeneration
        let physicalOutputs = SystemOutputAudio.outputDevices()
        // Merge against the AirPlay routes the last browse actually found,
        // not an empty list. `airPlayRouteDevices()` runs two sequential
        // `dns-sd -B` probes at 0.35s each -- a real ~0.7s, not a flaky
        // occasional stall -- so writing bare `physicalOutputs` here dropped
        // every AirPlay route, including whichever one was selected, for
        // that whole window on every single refresh. The popout opens on a
        // refresh, so a route that was the current output (its ROUTE card
        // highlighted) visibly lost that highlight the instant the popout
        // appeared and only regained it once the fresh browse landed --
        // read as the card flickering between colours. Seeding the
        // synchronous update with the previous browse's routes keeps the
        // selected route's card in place across that gap.
        outputDevices = SystemOutputAudio.mergedOutputDevices(
            physical: physicalOutputs,
            airPlay: lastKnownAirPlayRoutes
        )
        selectedOutputDeviceID = SystemOutputAudio.selectedDeviceID()
        // Bonjour discovery is intentionally off the main actor so refreshing
        // the Nexus audio page never waits on a network browse. The physical
        // devices render immediately; AirPlay child rows arrive a moment
        // later and retain their stable route keys across refreshes.
        DispatchQueue.global(qos: .utility).async { [weak self] in
            let routes = SystemOutputAudio.airPlayRouteDevices()
            DispatchQueue.main.async {
                guard let self, self.audioRefreshGeneration == refreshGeneration else { return }
                self.lastKnownAirPlayRoutes = routes
                self.outputDevices = SystemOutputAudio.mergedOutputDevices(
                    physical: physicalOutputs,
                    airPlay: routes
                )
            }
        }
        if let balance = SystemOutputAudio.readBalance() {
            outputBalance = balance
            balanceAvailable = true
        } else {
            outputBalance = 0.5
            balanceAvailable = false
        }
        inputDevices = SystemInputAudio.inputDevices()
        selectedInputDeviceID = SystemInputAudio.selectedDeviceID()
    }

