        desktopLayerEnabled = true
        desktopVisualizerEnabled = true
        desktopVisualizerStyle = Self.desktopVisualizerStyles.contains(scene.visualizerStyle)
            ? scene.visualizerStyle
            : "bars"
        desktopLayerMode = Self.desktopLayerModes.contains(scene.mode) ? scene.mode : "fullDesktop"
        applyDesktopLayerSettings()
    }

    func selectOutputDevice(_ device: SystemOutputAudio.Device) {
        let resumeEQ = eqEnabled
        if resumeEQ { writeEQControl(enabled: false) }

        // Selecting an AirPlay child may need to wake Sound Settings and walk
        // its accessibility hierarchy. Keep that work off the main actor so
        // the shell never appears frozen while the route connects.
        if device.isAirPlayRoute {
            status = "ROUTING…"
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                let selected = SystemOutputAudio.selectDevice(device)
                DispatchQueue.main.async {
                    guard let self else { return }
                    guard selected else {
                        self.status = "OUTPUT FAILED"
                        if resumeEQ { self.writeEQControl(enabled: true) }
                        return
                    }
                    self.selectedOutputRouteID = device.routeID
                    self.selectedOutputDeviceID = AudioDeviceID(kAudioObjectUnknown)
                    self.status = "OUTPUT SWITCHED"
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
                        self?.refreshAudio()
                        if resumeEQ { self?.writeEQControl(enabled: true) }
                    }
                }
            }
            return
        }

        guard SystemOutputAudio.selectDevice(device) else {
            status = "OUTPUT FAILED"
            if resumeEQ { writeEQControl(enabled: true) }
            return
        }
        if device.isAirPlayRoute {
            selectedOutputRouteID = device.routeID
            selectedOutputDeviceID = AudioDeviceID(kAudioObjectUnknown)
        } else {
            selectedOutputRouteID = nil
            selectedOutputDeviceID = device.id
        }
        status = "OUTPUT SWITCHED"
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
            self?.refreshAudio()
            if resumeEQ { self?.writeEQControl(enabled: true) }
        }
    }

    func selectInputDevice(_ device: SystemInputAudio.Device) {
        guard SystemInputAudio.selectDevice(device.id) else {
            status = "INPUT FAILED"
            return
        }
        selectedInputDeviceID = device.id
        status = "INPUT SWITCHED"
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in self?.refreshAudio() }
    }

    // The compact rail audio popout has no room for the full horizontal
    // device-capsule row Nexus uses, so it cycles through the same device
    // lists one tap at a time instead.
    func cycleOutputDevice() {
        let physical = outputDevices.filter { !$0.isAirPlayRoute }
        guard physical.count > 1 else { return }
        let currentIndex = physical.firstIndex { $0.id == selectedOutputDeviceID } ?? -1
        let next = physical[(currentIndex + 1) % physical.count]
        selectOutputDevice(next)
    }
    func cycleInputDevice() {
        guard inputDevices.count > 1 else { return }
        let currentIndex = inputDevices.firstIndex { $0.id == selectedInputDeviceID } ?? -1
        let next = inputDevices[(currentIndex + 1) % inputDevices.count]
        selectInputDevice(next)
    }

    func setOutputBalance(_ value: Double) {
        outputBalance = min(1, max(0, value))
        if !SystemOutputAudio.writeBalance(outputBalance) {
            status = "BALANCE UNSUPPORTED"
        }
    }

