    /// Pointer movement updates only the in-memory draft. The previous path
    /// atomically rewrote two JSON files and posted a distributed notification
    /// for every drag sample, which could stall the compositor under a fast
    /// gesture. Commit once on release instead.
    func previewEQBand(_ index: Int, gain: Double) {
        guard eqBands.indices.contains(index) else { return }
        eqBands[index] = min(12, max(-12, gain))
        eqPreset = .flat
    }

    func setEQPreamp(_ value: Double) {
_ = value
    }

    func previewEQPreamp(_ value: Double) {
        eqPreamp = min(6, max(-12, value))
    }

    func applyEQPreset(_ preset: EQPreset) {
_ = preset
    }

    private var telemetryPageNeedsDashboardData: Bool {
        telemetryPage == .overview || telemetryPage == .observatory
    }

    func setPage(_ page: Page) {
        let changed = telemetryPage != page
        telemetryPage = page
        if page == .settings { refreshDesktopLayer() }
        guard changed, nexusVisible else { return }
        stopLiveUpdates()
        stopEQStateUpdates()
        startLiveUpdates()
        startEQStateUpdates()
    }

    func setVisible(_ visible: Bool) {
        nexusVisible = visible
        stopLiveUpdates()
        stopEQStateUpdates()
        guard visible else { return }
        if telemetryPage == .settings { refreshDesktopLayer() }
        startLiveUpdates()
        startEQStateUpdates()
    }

    /// Keep expensive external probes on the pages that display them. The
    /// old Nexus-wide timer continued launching system-stats, ping, yabai,
    /// and LaunchAgent probes while the user was reading Audio, Tools, or
    /// Settings, which made page transitions compete with SwiftUI layout.
    private func startLiveUpdates() {
        guard nexusVisible, telemetryPageNeedsDashboardData else { return }
        if telemetryPageNeedsDashboardData {
            refreshTelemetry()
            refreshRuntime()
        }
        telemetryTimer = Timer.scheduledTimer(withTimeInterval: 3.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                guard let self, self.nexusVisible else { return }
                if self.telemetryPageNeedsDashboardData {
                    self.refreshTelemetry()
                    self.refreshRuntime()
                }
            }
        }
        telemetryTimer?.tolerance = 0.25
        if let telemetryTimer { RunLoop.main.add(telemetryTimer, forMode: .common) }
    }

    private func stopLiveUpdates() {
        telemetryTimer?.invalidate()
        telemetryTimer = nil
        telemetryTask?.cancel()
        telemetryTask = nil
        telemetryGeneration &+= 1
    }

    private func startEQStateUpdates() {
        guard nexusVisible, telemetryPage == .audio else { return }
        refreshEQState()
        eqStateTimer = Timer.scheduledTimer(withTimeInterval: 0.7, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.refreshEQState() }
        }
        eqStateTimer?.tolerance = 0.25
        if let eqStateTimer { RunLoop.main.add(eqStateTimer, forMode: .common) }
    }

    private func stopEQStateUpdates() {
        eqStateTimer?.invalidate()
        eqStateTimer = nil
    }

