    private static func rate(_ bytes: UInt64, elapsed: TimeInterval) -> String {
        let value = Double(bytes) / elapsed
        if value >= 1_000_000 { return String(format: "%.1f MB/s", value / 1_000_000) }
        if value < 1_000 { return String(format: "%.0f B/s", value) }
        return String(format: "%.0f KB/s", value / 1_000)
    }

    func runNetworkSpeedTest() {
        guard !speedTestRunning else { return }
        speedTestRunning = true

        Task {
            let result = await Task.detached(priority: .utility) { () -> (Bool, String, String, String) in
                let process = Process()
                let output = Pipe()
                let errors = Pipe()
                process.executableURL = URL(fileURLWithPath: "/usr/bin/networkQuality")
                process.arguments = ["-s", "-M", "15", "-c"]
                process.standardOutput = output
                process.standardError = errors

                do {
                    try process.run()
                    let data = output.fileHandleForReading.readDataToEndOfFile()
                    process.waitUntilExit()
                    guard process.terminationStatus == 0,
                          let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                        return (false, "—", "—", "—")
                    }

                    func number(_ key: String) -> Double? {
                        (json[key] as? NSNumber)?.doubleValue
                    }
                    func speed(_ bitsPerSecond: Double?) -> String {
                        guard let bitsPerSecond else { return "—" }
                        return bitsPerSecond >= 100_000_000
                            ? String(format: "%.0f Mbps", bitsPerSecond / 1_000_000)
                            : String(format: "%.1f Mbps", bitsPerSecond / 1_000_000)
                    }
                    let latency = number("base_rtt").map { String(format: "%.0f ms", $0) } ?? "—"
                    return (
                        true,
                        speed(number("dl_throughput")),
                        speed(number("ul_throughput")),
                        latency
                    )
                } catch {
                    return (false, "—", "—", "—")
                }
            }.value

            speedTestRunning = false
            if result.0 {
                speedTestDownload = result.1
                speedTestUpload = result.2
                speedTestLatency = result.3
                speedTestLastRun = DateFormatter.localizedString(
                    from: Date(),
                    dateStyle: .none,
                    timeStyle: .short
                ).uppercased()
            } else {
                speedTestLastRun = "TEST FAILED"
            }
        }
    }

