    func save() {
        do {
            try FileManager.default.createDirectory(
                at: Self.configurationURL.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            let data = try JSONEncoder.pretty.encode(configuration)
            try data.write(to: Self.configurationURL, options: .atomic)
            status = "SAVED"
        } catch {
            status = "SAVE FAILED"
            MacPlusPlusBoundaryLog.record("Nexus configuration write failed: \(error)")
        }
    }

    func updateSoftLockConfiguration(
        _ update: (inout MacPlusPlusSoftLockConfiguration) -> Void
    ) {
        var next = softLockConfiguration
        update(&next)
        guard next != softLockConfiguration else { return }
        guard MacPlusPlusSoftLockConfiguration.save(next) else {
            softLockResetStatus = "LOCK SCREEN SETTINGS COULD NOT SAVE"
            return
        }
        softLockConfiguration = next
        DistributedNotificationCenter.default().postNotificationName(
            MacPlusPlusSoftLockConfiguration.didChangeNotification,
            object: nil,
            userInfo: nil,
            deliverImmediately: true
        )
    }

    func resetSoftLockPasscode() {
        guard softLockResetTask == nil else { return }
        softLockResetStatus = "RESETTING…"
        softLockResetTask = Task { [weak self] in
            let succeeded = await Task.detached(priority: .userInitiated) {
                MacPlusPlusSoftLockPasscodeBridge.reset()
            }.value
            guard let self else { return }
            softLockResetStatus = succeeded
                ? "PASSCODE CLEARED • SET UP NEXT TIME"
                : "RESET FAILED • BUILD SOFT LOCK FIRST"
            softLockResetTask = nil
        }
    }

    func reloadConfiguration() {
        guard let data = try? Data(contentsOf: Self.configurationURL), // macpp:silent-ok absent configuration is reported as invalid
              let decoded = try? JSONDecoder().decode(MacPlusPlusNexusConfiguration.self, from: data) else { // macpp:silent-ok malformed configuration is reported as invalid
            status = "CONFIG INVALID"
            return
        }
        configuration = decoded
        status = "CONFIG LOADED"
    }

    func revealConfiguration() {
        NSWorkspace.shared.activateFileViewerSelecting([Self.configurationURL])
    }

    func revealCaptureDirectory() {
        let path = NSString(string: configuration.captureDirectory).expandingTildeInPath
        try? FileManager.default.createDirectory(atPath: path, withIntermediateDirectories: true) // macpp:silent-ok capture-directory creation failure is surfaced by the open action
        NSWorkspace.shared.open(URL(fileURLWithPath: path, isDirectory: true))
        status = "CAPTURES OPEN"
    }

    func capture(_ mode: String) {
        let folder = NSString(string: configuration.captureDirectory).expandingTildeInPath
        try? FileManager.default.createDirectory(atPath: folder, withIntermediateDirectories: true) // macpp:silent-ok capture-directory creation failure is surfaced by the capture status
        let stamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "-")
        let file = "\(folder)/MacPlusPlus-\(stamp).\(configuration.screenshotFormat)"
        var args = ["-x"]
        if configuration.includeCursor { args.append("-C") }
        switch mode {
        case "window": args += ["-i", "-J", "window", "-t", configuration.screenshotFormat, file]
        case "area": args += ["-i", "-J", "selection", "-t", configuration.screenshotFormat, file]
        case "record":
            args = ["-i", "-J", "video", "-v", "-k"]
            if configuration.recordMicrophone { args.append("-g") }
            args.append(file.replacingOccurrences(of: ".\(configuration.screenshotFormat)", with: ".mov"))
        default: args += ["-m", "-t", configuration.screenshotFormat, file]
        }
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
        process.arguments = args
        do {
            try process.run()
            status = mode == "record" ? "RECORDER OPEN" : "CAPTURE READY"
        } catch { status = "CAPTURE FAILED" }
    }

    func refreshLyrics(for media: MediaState) {
        guard configuration.lyricsEnabled, !media.title.isEmpty, !media.artist.isEmpty else {
            lyricsTask?.cancel()
            lyricsTask = nil
            lyricsGeneration &+= 1
            lastLyricsKey = ""
            lyricsLoading = false
            lyrics = ""
            syncedLyrics = []
            lyricsStatus = configuration.lyricsEnabled ? "PLAY SOMETHING" : "LYRICS DISABLED"
            return
        }
        let key = "\(media.title)|\(media.artist)|\(media.album)|\(Int(media.duration))"
        guard key != lastLyricsKey else { return }
        lyricsTask?.cancel()
        lyricsGeneration &+= 1
        let generation = lyricsGeneration
        lastLyricsKey = key
        lyricsLoading = true
        lyricsStatus = "FINDING LYRICS"
        lyricsTask = Task { [weak self] in
            var components = URLComponents()
            components.scheme = "https"
            components.host = "lrclib.net"
            components.path = "/api/get"
            components.queryItems = [
                URLQueryItem(name: "track_name", value: media.title),
                URLQueryItem(name: "artist_name", value: media.artist),
                URLQueryItem(name: "album_name", value: media.album),
                URLQueryItem(name: "duration", value: String(Int(media.duration.rounded())))
            ]
            guard let requestURL = components.url else {
                guard let self, self.lyricsGeneration == generation else { return }
                self.lyricsStatus = "LYRICS SERVICE UNAVAILABLE"
                self.lyricsLoading = false
                self.lyricsTask = nil
                return
            }
            var request = URLRequest(url: requestURL)
            request.setValue("MacPlusPlusShell/1.0 (personal macOS shell)", forHTTPHeaderField: "User-Agent")
            do {
                let (data, response) = try await URLSession.shared.data(for: request)
                guard (response as? HTTPURLResponse)?.statusCode == 200,
                      let payload = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { throw URLError(.badServerResponse) }
                let plain = payload["plainLyrics"] as? String
                let synced = payload["syncedLyrics"] as? String
                guard let self, !Task.isCancelled,
                      self.configuration.lyricsEnabled,
                      self.lyricsGeneration == generation,
                      self.lastLyricsKey == key else { return }
                self.syncedLyrics = Self.timedLyrics(from: synced ?? "")
                self.lyrics = plain?.isEmpty == false ? plain! : self.syncedLyrics.map(\.text).joined(separator: "\n")
                self.lyricsStatus = self.lyrics.isEmpty ? "NO LYRICS" : "LYRICS READY"
            } catch {
                guard let self, !Task.isCancelled,
                      self.configuration.lyricsEnabled,
                      self.lyricsGeneration == generation,
                      self.lastLyricsKey == key else { return }
                self.lyrics = ""
                self.syncedLyrics = []
                self.lyricsStatus = "NO LYRICS FOUND"
            }
            guard let self, self.lyricsGeneration == generation else { return }
            self.lyricsLoading = false
            self.lyricsTask = nil
        }
    }

    func setLyricsEnabled(_ enabled: Bool, for media: MediaState) {
        guard configuration.lyricsEnabled != enabled else { return }
        configuration.lyricsEnabled = enabled
        save()
        if enabled {
            lastLyricsKey = ""
            refreshLyrics(for: media)
        } else {
            refreshLyrics(for: MediaState())
        }
    }

    func forceRefreshLyrics(for media: MediaState) {
        lastLyricsKey = ""
        refreshLyrics(for: media)
    }

    private static func plainLyrics(from synced: String) -> String {
        synced.split(separator: "\n").map { line in
            String(line).replacingOccurrences(of: #"^\[[0-9:.]+\]\s*"#, with: "", options: .regularExpression)
        }.joined(separator: "\n")
    }

    private static func timedLyrics(from synced: String) -> [MacPlusPlusTimedLyric] {
        synced.split(separator: "\n").compactMap { rawLine in
            let line = String(rawLine)
            guard let close = line.firstIndex(of: "]"), line.first == "[" else { return nil }
            let timestamp = String(line[line.index(after: line.startIndex)..<close])
            let parts = timestamp.split(separator: ":")
            guard parts.count == 2, let minutes = Double(parts[0]), let seconds = Double(parts[1]) else { return nil }
            let text = line[line.index(after: close)...].trimmingCharacters(in: .whitespaces)
            guard !text.isEmpty else { return nil }
            return MacPlusPlusTimedLyric(time: minutes * 60 + seconds, text: text)
        }
    }
}

private extension JSONEncoder {
    static var pretty: JSONEncoder {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        return encoder
    }
}

/// Renders a poster from the same focal point that the wallpaper engine uses
/// for the desktop.  `scaledToFill()` alone always centers the source, which
/// made a library card disagree with the wallpaper immediately after its
/// frame was edited.
private struct MacPlusPlusWallpaperFramedImage: View {
    let image: NSImage
    let selection: MacPlusPlusWallpaperCropSelection

    var body: some View {
        GeometryReader { geometry in
            let viewportWidth = max(geometry.size.width, 1)
            let viewportHeight = max(geometry.size.height, 1)
            let sourceWidth = max(image.size.width, 1)
            let sourceHeight = max(image.size.height, 1)
            let cropGeometry = MacPlusPlusWallpaperCropGeometry(
                sourceAspect: Double(sourceWidth / sourceHeight),
                viewportAspect: Double(viewportWidth / viewportHeight)
            )
            let imageSize = CGSize(
                width: viewportWidth / CGFloat(cropGeometry.visibleSourceWidth),
                height: viewportHeight / CGFloat(cropGeometry.visibleSourceHeight)
            )
            let cropOrigin = cropGeometry.cropOrigin(for: selection)

            Image(nsImage: image)
                .resizable()
                .scaledToFill()
                .frame(width: imageSize.width, height: imageSize.height, alignment: .topLeading)
                .offset(
                    x: -CGFloat(cropOrigin.x) * imageSize.width,
                    y: -CGFloat(cropOrigin.y) * imageSize.height
                )
        }
        .clipped()
    }
}

private final class MacPlusPlusWallpaperPreviewNSView: NSView {
    private let playerLayer = AVPlayerLayer()
    private let imageView = NSImageView()
    private var player: AVQueuePlayer?
    private var looper: AVPlayerLooper?
    private var representedURL: URL?
    private var sourceAspect: CGFloat = 16.0 / 9.0
    private var framing = MacPlusPlusWallpaperCropSelection()

    override var isFlipped: Bool { true }

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        layer?.masksToBounds = true
        layer?.isGeometryFlipped = true
        playerLayer.videoGravity = .resize
        layer?.addSublayer(playerLayer)
        imageView.imageScaling = .scaleProportionallyUpOrDown
        imageView.wantsLayer = true
        imageView.layer?.masksToBounds = true
        addSubview(imageView)
    }

    required init?(coder: NSCoder) { nil }

    override func layout() {
        super.layout()
        imageView.frame = bounds
        updatePlayerFrame()
    }

    private func releasePlayer() {
        player?.pause()
        playerLayer.player = nil
        looper = nil
        player = nil
    }

    private func updatePlayerFrame() {
        guard !playerLayer.isHidden, bounds.width > 0, bounds.height > 0 else { return }
        let cropGeometry = MacPlusPlusWallpaperCropGeometry(
            sourceAspect: Double(max(sourceAspect, 0.25)),
            viewportAspect: Double(max(bounds.width / bounds.height, 0.25))
        )
        let imageSize = CGSize(
            width: bounds.width / CGFloat(cropGeometry.visibleSourceWidth),
            height: bounds.height / CGFloat(cropGeometry.visibleSourceHeight)
        )
        let cropOrigin = cropGeometry.cropOrigin(for: framing)
        let frame = CGRect(
            x: -CGFloat(cropOrigin.x) * imageSize.width,
            y: -CGFloat(cropOrigin.y) * imageSize.height,
            width: imageSize.width,
            height: imageSize.height
        )
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        playerLayer.frame = frame
        CATransaction.commit()
    }

    func configure(
        url: URL?,
        active: Bool,
        framing: MacPlusPlusWallpaperCropSelection,
        sourceAspect: CGFloat?
    ) {
        if representedURL != url {
            releasePlayer()
            representedURL = url
            imageView.image = nil
            self.sourceAspect = 16.0 / 9.0
        }
        self.framing = framing
        if let sourceAspect, sourceAspect.isFinite, sourceAspect > 0 {
            self.sourceAspect = sourceAspect
        }
        guard active, let url else {
            releasePlayer()
            playerLayer.isHidden = true
            imageView.isHidden = true
            return
        }
        if !macppWallpaperVideoExtensions.contains(url.pathExtension.lowercased()) {
            releasePlayer()
            playerLayer.isHidden = true
            imageView.isHidden = false
            if imageView.image == nil { imageView.image = NSImage(contentsOf: url) }
            return
        }
        imageView.isHidden = true
        playerLayer.isHidden = false
        if player == nil {
            let queue = AVQueuePlayer()
            queue.isMuted = true
            queue.actionAtItemEnd = .none
            player = queue
            looper = AVPlayerLooper(player: queue, templateItem: AVPlayerItem(url: url))
            playerLayer.player = queue
        }
        updatePlayerFrame()
        player?.play()
    }

    deinit { releasePlayer() }
}

private struct MacPlusPlusWallpaperPreview: NSViewRepresentable {
    let url: URL?
    let active: Bool
    let framing: MacPlusPlusWallpaperCropSelection
    let sourceAspect: CGFloat?

    func makeNSView(context: Context) -> MacPlusPlusWallpaperPreviewNSView {
        let view = MacPlusPlusWallpaperPreviewNSView()
        view.configure(url: url, active: active, framing: framing, sourceAspect: sourceAspect)
        return view
    }

    func updateNSView(_ nsView: MacPlusPlusWallpaperPreviewNSView, context: Context) {
        nsView.configure(url: url, active: active, framing: framing, sourceAspect: sourceAspect)
    }
}

private final class MacPlusPlusWallpaperScrollMonitorNSView: NSView {
    var onStep: (Int) -> Void = { _ in }
    private var eventMonitor: Any?
    private var scrollRemainder: CGFloat = 0
    private var lastStepTime: TimeInterval = 0
    private var gestureStepCount = 0
    private var trackingGesture = false

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        removeEventMonitor()
        installKeyMonitor()
        guard window != nil else { return }
        eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { [weak self] event in
            guard let self, let window = self.window, event.window === window else { return event }
            let location = self.convert(event.locationInWindow, from: nil)
            guard self.bounds.contains(location) else { return event }

            // A trackpad can deliver a long tail of momentum events after the
            // pointer has left the switcher.  Those events used to keep
            // selecting cards (and launching a lock-screen conversion) long
            // after the user released the gesture.  Treat the gesture end as
            // a hard transaction boundary and cap a single momentum burst.
            if event.phase == .ended || event.momentumPhase == .ended {
                self.scrollRemainder = 0
                self.gestureStepCount = 0
                self.trackingGesture = false
                return event
            }
            // Wallpaper selection is an expensive, shell-wide commit rather
            // than a cheap visual-only scroll. Ignore the inertial tail after
            // finger-up; the deliberate drag and arrow paths remain smooth,
            // while a single gesture can no longer keep selecting wallpapers
            // after the user has stopped interacting.
            if !event.momentumPhase.isEmpty { return event }

            let horizontal = CGFloat(event.scrollingDeltaX)
            let shiftedVertical = event.modifierFlags.contains(.shift)
                ? CGFloat(event.scrollingDeltaY)
                : 0
            var delta = abs(horizontal) > 0.1 ? horizontal : shiftedVertical
            guard abs(delta) > 0.1 else { return event }

            if event.phase == .began {
                self.scrollRemainder = 0
                self.gestureStepCount = 0
                self.trackingGesture = true
            }
            // A mouse wheel reports small line-based deltas. Scale those to
            // one deliberate carousel step while leaving trackpad movement
            // proportional and momentum-aware.
            if !event.hasPreciseScrollingDeltas {
                delta *= 14
            }
            self.scrollRemainder += delta

            let threshold: CGFloat = 32
            let now = ProcessInfo.processInfo.systemUptime
            if self.trackingGesture, self.gestureStepCount >= 12 {
                self.scrollRemainder = 0
                return event
            }
            guard abs(self.scrollRemainder) >= threshold,
                  now - self.lastStepTime >= 0.18 else { return event }

            let step = self.scrollRemainder > 0 ? 1 : -1
            self.scrollRemainder -= CGFloat(step) * threshold
            self.lastStepTime = now
            if self.trackingGesture { self.gestureStepCount += 1 }
            self.onStep(step)
            return event
        }
    }

    // Arrow keys drive the same discrete step the scroll wheel does. This is
    // a second monitor rather than another `matching:` case on the first
    // because a key event has no cursor position to hit-test against -- the
    // window simply has to be the carousel's own -- so the two share no
    // filtering logic. Left/right are the carousel's own axis; up/down are
    // accepted too, since a vertical list of wallpapers is the equally
    // natural mental model and nothing else in this surface consumes them.
    private var keyMonitor: Any?

    private func installKeyMonitor() {
        removeKeyMonitor()
        guard window != nil else { return }
        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self, let window = self.window, event.window === window else { return event }
            switch event.keyCode {
            case 123, 126: self.onStep(-1); return nil   // left, up
            case 124, 125: self.onStep(1); return nil    // right, down
            default: return event
            }
        }
    }

    private func removeKeyMonitor() {
        if let keyMonitor {
            NSEvent.removeMonitor(keyMonitor)
            self.keyMonitor = nil
        }
    }

    deinit {
        removeEventMonitor()
        removeKeyMonitor()
    }

    private func removeEventMonitor() {
        if let eventMonitor {
            NSEvent.removeMonitor(eventMonitor)
            self.eventMonitor = nil
        }
    }
}

private struct MacPlusPlusWallpaperScrollMonitor: NSViewRepresentable {
    let onStep: (Int) -> Void

    func makeNSView(context: Context) -> MacPlusPlusWallpaperScrollMonitorNSView {
        let view = MacPlusPlusWallpaperScrollMonitorNSView()
        view.onStep = onStep
        return view
    }

    func updateNSView(_ nsView: MacPlusPlusWallpaperScrollMonitorNSView, context: Context) {
        nsView.onStep = onStep
    }
}

private struct MacPlusPlusWallpaperCropPreview: View {
    let url: URL?
    let sourceSize: CGSize
    @Binding var selection: MacPlusPlusWallpaperCropSelection
    @GestureState private var dragTranslation = CGSize.zero

    var body: some View {
        GeometryReader { geometry in
            let viewportWidth = max(geometry.size.width, 1)
            let viewportHeight = max(geometry.size.height, 1)
            let sourceWidth = max(sourceSize.width, 1)
            let sourceHeight = max(sourceSize.height, 1)
            let cropGeometry = MacPlusPlusWallpaperCropGeometry(
                sourceAspect: Double(sourceWidth / sourceHeight),
                viewportAspect: Double(viewportWidth / viewportHeight)
            )
            let imageSize = CGSize(
                width: viewportWidth / CGFloat(cropGeometry.visibleSourceWidth),
                height: viewportHeight / CGFloat(cropGeometry.visibleSourceHeight)
            )
            let travelX = max(0, imageSize.width - viewportWidth)
            let travelY = max(0, imageSize.height - viewportHeight)
            let cropOrigin = cropGeometry.cropOrigin(for: selection)
            let baseOffset = CGSize(
                width: -CGFloat(cropOrigin.x) * imageSize.width,
                height: -CGFloat(cropOrigin.y) * imageSize.height
            )
            let imageOffset = CGSize(
                width: min(
                    max(baseOffset.width + dragTranslation.width, -travelX),
                    0
                ),
                height: min(
                    max(baseOffset.height + dragTranslation.height, -travelY),
                    0
                )
            )

            ZStack(alignment: .topLeading) {
                Theme.tile
                AsyncImage(
                    url: url,
                    transaction: Transaction(animation: ShellMotion.contentIn.animation)
                ) { phase in
                    switch phase {
                    case .success(let image):
                        image
                            .resizable()
                            .scaledToFill()
                            .transition(.opacity)
                    case .failure:
                        ZStack {
                            Theme.tile
                            Image(systemName: "photo.badge.exclamationmark")
                                .font(.system(size: ShellIcon.header, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.muted)
                        }
                        .transition(.opacity)
                    default:
                        ZStack {
                            Theme.tile
                            ProgressView().controlSize(.small).tint(Theme.accent)
                        }
                        .transition(.opacity)
                    }
                }
                .frame(width: imageSize.width, height: imageSize.height)
                .offset(imageOffset)
                .gesture(
                    DragGesture(minimumDistance: 2)
                        .updating($dragTranslation) { value, state, _ in
                            state = value.translation
                        }
                        .onEnded { value in
                            let nextX = travelX > 0.5
                                ? selection.x - Double(value.translation.width / imageSize.width)
                                : selection.x
                            let nextY = travelY > 0.5
                                ? selection.y - Double(value.translation.height / imageSize.height)
                                : selection.y
                            selection = MacPlusPlusWallpaperCropSelection(x: nextX, y: nextY)
                        }
                )
            }
            .background {
                MacPlusPlusWallpaperCropScrollMonitor { deltaX, deltaY in
                    let hasHorizontalTravel = travelX > 0.5 && abs(deltaX) > 0.01
                    let hasVerticalTravel = travelY > 0.5 && abs(deltaY) > 0.01
                    guard hasHorizontalTravel || hasVerticalTravel else { return false }
                    let nextX = hasHorizontalTravel
                        ? selection.x - Double(deltaX / imageSize.width)
                        : selection.x
                    let nextY = hasVerticalTravel
                        ? selection.y - Double(deltaY / imageSize.height)
                        : selection.y
                    selection = MacPlusPlusWallpaperCropSelection(x: nextX, y: nextY)
                    return true
                }
            }
            .clipped()
            .overlay {
                RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                    .stroke(Theme.accent.opacity(0.62), lineWidth: 0.8)
            }
            .overlay(alignment: .topLeading) {
                Text("DISPLAY FRAME")
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                    .foregroundStyle(Theme.onAccent)
                    .padding(.horizontal, Spacing.snug)
                    .frame(height: 22)
                    .background(Theme.accent.opacity(0.86), in: Capsule())
                    .padding(Spacing.base)
            }
            .overlay(alignment: .bottomTrailing) {
                Image(systemName: "arrow.up.and.down.and.arrow.left.and.right")
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .padding(Spacing.snug)
                    .background(Theme.surface.opacity(0.72), in: Circle())
                    .padding(Spacing.base)
            }
        }
        .contentShape(Rectangle())
    }
}

private final class MacPlusPlusWallpaperCropScrollMonitorNSView: NSView {
    var onScroll: (CGFloat, CGFloat) -> Bool = { _, _ in false }
    private var eventMonitor: Any?

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        removeEventMonitor()
        guard let window else { return }
        eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { [weak self] event in
            guard let self, event.window === window else { return event }
            let location = self.convert(event.locationInWindow, from: nil)
            guard self.bounds.contains(location) else { return event }
            var deltaX = CGFloat(event.scrollingDeltaX)
            var deltaY = CGFloat(event.scrollingDeltaY)
            if !event.hasPreciseScrollingDeltas {
                deltaX *= 12
                deltaY *= 12
            }
            guard abs(deltaX) > 0.01 || abs(deltaY) > 0.01 else { return event }
            return self.onScroll(deltaX, deltaY) ? nil : event
        }
    }

    private func removeEventMonitor() {
        if let eventMonitor {
            NSEvent.removeMonitor(eventMonitor)
            self.eventMonitor = nil
        }
    }

    deinit {
        removeEventMonitor()
    }
}

private struct MacPlusPlusWallpaperCropScrollMonitor: NSViewRepresentable {
    let onScroll: (CGFloat, CGFloat) -> Bool

    func makeNSView(context: Context) -> MacPlusPlusWallpaperCropScrollMonitorNSView {
        let view = MacPlusPlusWallpaperCropScrollMonitorNSView()
        view.onScroll = onScroll
        return view
    }

    func updateNSView(
        _ nsView: MacPlusPlusWallpaperCropScrollMonitorNSView,
        context: Context
    ) {
        nsView.onScroll = onScroll
    }
}

private func macppWallpaperDisplayAspect() -> CGFloat {
    let fallback = CGFloat(MacPlusPlusWallpaperCropSelection.targetAspect)
    let screen = NSApp.keyWindow?.screen ?? NSScreen.main
    guard let screen, screen.frame.width > 1, screen.frame.height > 1 else {
        return fallback
    }
    return max(0.25, screen.frame.width / screen.frame.height)
}

/// A larger, reusable editor for media that is already in the wallpaper
/// carousel. It deliberately stores only a focal point; images and videos are
/// never re-encoded just to change what the 21:9 desktop window shows.
private struct MacPlusPlusWallpaperFramingEditorView: View {
    let sourceURL: URL
    let poster: NSImage?
    let onSave: (MacPlusPlusWallpaperCropSelection) -> Bool
    let onCancel: () -> Void
    @State private var selection = MacPlusPlusWallpaperCropSelection()
    @State private var previewImage: NSImage?
    @State private var previewLoading = false
    @State private var saveError = false

    private var viewportAspect: CGFloat { macppWallpaperDisplayAspect() }

    private var sourceAspect: CGFloat {
        guard let previewImage, previewImage.size.height > 0 else { return viewportAspect }
        return max(0.25, previewImage.size.width / previewImage.size.height)
    }

    private var frameLabel: String {
        abs(viewportAspect - CGFloat(MacPlusPlusWallpaperCropSelection.targetAspect)) < 0.02
            ? "21:9 FRAME"
            : "DISPLAY FRAME"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: Spacing.base) {
            HStack(spacing: Spacing.base) {
                Button { onCancel() } label: {
                    Image(systemName: "chevron.left")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 32, height: 32)
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .background(Theme.tile, in: Circle())

                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text("EDIT WALLPAPER FRAME")
                        .font(.system(size: ShellTypography.title, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                }
                Spacer(minLength: 8)
                Image(systemName: "crop")
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
            }

            MacPlusPlusWallpaperImageCropPreview(
                image: previewImage,
                sourceAspect: sourceAspect,
                selection: $selection,
                loading: previewLoading,
                frameLabel: frameLabel
            )
            .aspectRatio(viewportAspect, contentMode: .fit)
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))

            HStack(spacing: Spacing.snug) {
                Spacer(minLength: 0)
                if saveError {
                    Text("SAVE FAILED")
                        .font(.system(size: ShellTypography.nano, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                        .foregroundStyle(Color.red)
                }
                Button {
                    selection = MacPlusPlusWallpaperCropSelection()
                } label: {
                    Image(systemName: "arrow.counterclockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 29, height: 29)
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .background(Theme.tile, in: Circle())
                .help("Center frame")
            }

            HStack(spacing: Spacing.base) {
                Button { onCancel() } label: {
                    Text("Cancel")
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                        .frame(maxWidth: .infinity)
                        .frame(height: 34)
                        .background(Theme.tile, in: Capsule())
                        .foregroundStyle(Theme.bright)
                        .contentShape(Capsule())
                }
                .buttonStyle(MicroButtonStyle())

                Button {
                    saveError = !onSave(selection)
                } label: {
                    Text("SAVE FRAME")
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                        .frame(maxWidth: .infinity)
                        .frame(height: 34)
                        .background(Theme.accent, in: Capsule())
                        .foregroundStyle(Theme.onAccent)
                        .contentShape(Capsule())
                }
                .buttonStyle(MicroButtonStyle())
            }
        }
        .padding(Spacing.roomy)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .onAppear {
            selection = MacPlusPlusWallpaperFramingStore.load(for: sourceURL.path)
            previewImage = poster
            // Cached carousel posters can predate the editor and may already
            // be cropped to the desktop aspect. Always refresh from the real
            // source so the visible crop and drag axis reflect the media that
            // the renderer will actually sample.
            loadPreview()
        }
    }

    private func loadPreview() {
        previewLoading = true
        let sourceURL = self.sourceURL
        Task { @MainActor in
            let data = await Self.previewData(for: sourceURL)
            if let data, let image = NSImage(data: data) {
                previewImage = image
            }
            previewLoading = false
        }
    }

    private nonisolated static func previewData(for url: URL) async -> Data? {
        if !macppWallpaperVideoExtensions.contains(url.pathExtension.lowercased()) {
            guard let image = NSImage(contentsOf: url),
                  let tiff = image.tiffRepresentation,
                  let bitmap = NSBitmapImageRep(data: tiff) else { return nil }
            return bitmap.representation(using: .jpeg, properties: [.compressionFactor: 0.90])
        }
        let generator = AVAssetImageGenerator(asset: AVURLAsset(url: url))
        generator.appliesPreferredTrackTransform = true
        generator.maximumSize = CGSize(width: 1600, height: 1000)
        // macpp:silent-ok video thumbnail failure simply leaves the preview unavailable.
        guard let image = try? await generator.image(
            at: CMTime(seconds: 0.5, preferredTimescale: 600)
        ).image else { return nil }
        return NSBitmapImageRep(cgImage: image).representation(using: .jpeg, properties: [:])
    }
}

private struct MacPlusPlusWallpaperImageCropPreview: View {
    let image: NSImage?
    let sourceAspect: CGFloat
    @Binding var selection: MacPlusPlusWallpaperCropSelection
    let loading: Bool
    let frameLabel: String
    @GestureState private var dragTranslation = CGSize.zero

    var body: some View {
        GeometryReader { geometry in
            let viewportWidth = max(geometry.size.width, 1)
            let viewportHeight = max(geometry.size.height, 1)
            let cropGeometry = MacPlusPlusWallpaperCropGeometry(
                sourceAspect: Double(max(sourceAspect, 0.25)),
                viewportAspect: Double(viewportWidth / viewportHeight)
            )
            let imageSize = CGSize(
                width: viewportWidth / CGFloat(cropGeometry.visibleSourceWidth),
                height: viewportHeight / CGFloat(cropGeometry.visibleSourceHeight)
            )
            let travelX = max(0, imageSize.width - viewportWidth)
            let travelY = max(0, imageSize.height - viewportHeight)
            let cropOrigin = cropGeometry.cropOrigin(for: selection)
            let baseOffset = CGSize(
                width: -CGFloat(cropOrigin.x) * imageSize.width,
                height: -CGFloat(cropOrigin.y) * imageSize.height
            )
            let offset = CGSize(
                width: min(
                    max(baseOffset.width + dragTranslation.width, -travelX),
                    0
                ),
                height: min(
                    max(baseOffset.height + dragTranslation.height, -travelY),
                    0
                )
            )

            ZStack(alignment: .topLeading) {
                Theme.tile
                if let image {
                    Image(nsImage: image)
                        .resizable()
                        .scaledToFill()
                        .frame(width: imageSize.width, height: imageSize.height)
                        .offset(offset)
                } else if loading {
                    ProgressView().controlSize(.small).tint(Theme.accent)
                } else {
                    VStack(spacing: Spacing.snug) {
                        Image(systemName: "photo.badge.exclamationmark")
                            .font(.system(size: ShellIcon.feature, weight: .semibold, design: .rounded))
                    }
                    .foregroundStyle(Theme.muted)
                }
            }
            .background {
                MacPlusPlusWallpaperCropScrollMonitor { deltaX, deltaY in
                    let horizontal = travelX > 0.5 && abs(deltaX) > 0.01
                    let vertical = travelY > 0.5 && abs(deltaY) > 0.01
                    guard horizontal || vertical else { return false }
                    selection = MacPlusPlusWallpaperCropSelection(
                        x: horizontal ? selection.x - Double(deltaX / imageSize.width) : selection.x,
                        y: vertical ? selection.y - Double(deltaY / imageSize.height) : selection.y
                    )
                    return true
                }
                .allowsHitTesting(false)
            }
            .clipped()
            // The image is intentionally larger than the visible 21:9
            // viewport. Attaching the drag only to that overflowing child
            // left parts of the visible frame without a reliable hit target,
            // especially while the native scroll monitor was present in the
            // background. Make the entire preview the interaction surface.
            .contentShape(Rectangle())
            .highPriorityGesture(
                DragGesture(minimumDistance: 2)
                    .updating($dragTranslation) { value, state, _ in
                        state = value.translation
                    }
                    .onEnded { value in
                        let nextX = travelX > 0.5
                            ? selection.x - Double(value.translation.width / imageSize.width)
                            : selection.x
                        let nextY = travelY > 0.5
                            ? selection.y - Double(value.translation.height / imageSize.height)
                            : selection.y
                        selection = MacPlusPlusWallpaperCropSelection(
                            x: nextX,
                            y: nextY
                        )
                    }
            )
            .overlay {
                RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                    .stroke(Theme.accent.opacity(0.68), lineWidth: 0.8)
            }
            .overlay(alignment: .topLeading) {
                Text(frameLabel)
                    .font(.system(size: ShellTypography.nano, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                    .foregroundStyle(Theme.onAccent)
                    .padding(.horizontal, Spacing.snug)
                    .frame(height: 22)
                    .background(Theme.accent.opacity(0.86), in: Capsule())
                    .padding(Spacing.base)
            }
        }
        .contentShape(Rectangle())
    }
}

private struct MacPlusPlusWallpaperCarouselItem: Identifiable, Equatable {
    let id: String
    let palette: ShellPalette?
    let title: String
    let mediaURL: URL?

    init(
        id: String,
        palette: ShellPalette?,
        title: String,
        mediaURL: URL?
    ) {
        self.id = id
        self.palette = palette
        self.title = title
        self.mediaURL = mediaURL
    }
}

private struct MacPlusPlusWallpaperCarouselView: View {
    @ObservedObject var shell: ShellModel
    @ObservedObject var launcherModel: LauncherModel
    @State private var editingItem: MacPlusPlusWallpaperCarouselItem?
    @State private var focusedItemID: String = "palette:midnight"
    // Keep two duplicate cards at each end. One duplicate is enough to animate
    // across the boundary, but it leaves the focused card with an empty space
    // beside it while the strip is parked on that duplicate. Two duplicates
    // keep both immediate neighbours painted through the whole wrap; the
    // visual index is then silently re-homed to the middle copy.
    @State private var carouselIndex: Int = 2
    @State private var livePreviewItemID: String?
    @State private var livePreviewTask: Task<Void, Never>?
    @GestureState private var dragOffset: CGFloat = 0
    // Poster images and wallpaper URLs were being resolved from inside the
    // view body, once per card, on every single render -- so a slide was
    // doing roughly thirty file-attribute syscalls per frame, plus a full
    // read-and-JSON-parse of Presets.json for the focused card. Neither of
    // those inputs can change while the switcher is open, so they are
    // resolved once here and read from memory thereafter. This is the bulk
    // of the switcher's lag.
    @State private var items: [MacPlusPlusWallpaperCarouselItem] = []
    @State private var posters: [String: NSImage] = [:]
    @State private var wallpaperURLs: [String: URL] = [:]
    @State private var wallpaperFramings: [String: MacPlusPlusWallpaperCropSelection] = [:]
    // Posters for imported videos are generated off the main thread. Keep a
    // small in-flight set so the focused card and its immediate neighbour can
    // be prioritised without starting duplicate decoders while the background
    // queue is filling the rest of the carousel.
    @State private var posterLoadingIDs: Set<String> = []
    @State private var posterLoadTask: Task<Void, Never>?
    @State private var posterGeneration = 0
    // setPalette is genuinely expensive: an atomic file write, a blocking
    // UserDefaults.synchronize(), and two spawned shell processes
    // (optional palette helpers). Running helpers synchronously on every
    // step meant holding the main thread mid-animation, once per card
    // crossed. Stepping now only schedules it, so a fast scroll through six
    // wallpapers pays the cost once instead of six times.
    @State private var applyTask: Task<Void, Never>?
    @State private var lastAppliedItemID: String?
    @State private var selectionNeedsCommit = false
    @State private var hoveredItemID: String?

    private let cardWidth: CGFloat = 300
    private let cardHeight: CGFloat = 169
    private let spacing: CGFloat = 16
    private let loopPadding = 2
    private static let posterCache = NSCache<NSString, NSImage>()
    private var palettes: [ShellPalette] {
        ShellPalette.dedicatedPalettes
    }
    private var carouselItems: [MacPlusPlusWallpaperCarouselItem] {
        MacPlusPlusPureLogic.loopPaddedCarousel(items, padding: loopPadding)
    }
    private var focusedItem: MacPlusPlusWallpaperCarouselItem? {
        items.first { $0.id == focusedItemID }
    }

    private var carouselBody: some View {
        VStack(spacing: Spacing.base) {
            GeometryReader { geometry in
                HStack(spacing: spacing) {
                    ForEach(Array(carouselItems.enumerated()), id: \.offset) { index, item in
                        ZStack(alignment: .topTrailing) {
                            Button {
                                select(item)
                            } label: {
                                wallpaperCard(item, active: index == carouselIndex)
                            }
                            .buttonStyle(.plain)
                            .frame(width: cardWidth, height: cardHeight)

                            if item.mediaURL != nil, hoveredItemID == item.id {
                                HStack(spacing: Spacing.tight) {
                                    Button {
                                        guard item.mediaURL != nil else { return }
                                        editingItem = item
                                        launcherModel.presentWallpaperEditor()
                                    } label: {
                                        HStack(spacing: Spacing.tight) {
                                            Image(systemName: "crop")
                                            Text("EDIT FRAME")
                                        }
                                        .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                                        .foregroundStyle(Theme.bright)
                                        .padding(.horizontal, Spacing.base)
                                        .frame(height: 25)
                                        .background(Theme.surface.opacity(0.90), in: Capsule())
                                        .overlay { Capsule().stroke(Theme.seam.opacity(0.82), lineWidth: 0.8) }
                                        .contentShape(Capsule())
                                    }
                                    .buttonStyle(MicroButtonStyle())
                                    .help("Edit wallpaper framing")
                                    .accessibilityLabel("Edit \(item.title) frame")

                                    if canDelete(item), hoveredItemID == item.id {
                                        Button {
                                            delete(item)
                                        } label: {
                                            Image(systemName: "xmark")
                                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                                .foregroundStyle(Theme.bright)
                                                .frame(width: 25, height: 25)
                                                .background(Theme.surface.opacity(0.90), in: Circle())
                                                .overlay { Circle().stroke(Theme.seam.opacity(0.82), lineWidth: 0.8) }
                                                .contentShape(Circle())
                                        }
                                        .buttonStyle(MicroButtonStyle())
                                        .help("Delete wallpaper")
                                        .accessibilityLabel("Delete \(item.title) wallpaper")
                                    }
                                }
                                .padding(Spacing.base)
                                .transition(.opacity.combined(with: .scale(scale: 0.88)))
                            }
                        }
                        .frame(width: cardWidth, height: cardHeight)
                        .onHover { inside in
                            hoveredItemID = inside ? item.id : (hoveredItemID == item.id ? nil : hoveredItemID)
                        }
                        // Inactive cards keep the same item/active inputs
                        // when the selection changes, so SwiftUI can reuse
                        // their subtree with the old Theme colours. The
                        // selected card refreshed by coincidence because its
                        // active flag changed. Include the shared palette
                        // revision in the outer identity so every card
                        // repaints together.
                        .id("wallpaper-card-\(item.id)-palette-\(shell.companionRevision)")
                        .scaleEffect(index == carouselIndex ? 1 : 0.88)
                        .opacity(index == carouselIndex ? 1 : 0.48)
                    }
                }
                .offset(
                    x: geometry.size.width / 2
                        - cardWidth / 2
                        - CGFloat(carouselIndex) * (cardWidth + spacing)
                        + dragOffset
                )
                // Deliberately NOT an implicit `.animation(_:value: carouselIndex)`.
                // The wrap-around re-home (see move(_:)) has to reposition the
                // strip by the entire width of the carousel in one assignment,
                // and an implicit animation animated that reposition too --
                // which is exactly the "acceleration boost" felt when passing
                // the last wallpaper: the visible step played at its normal
                // speed, then the invisible bookkeeping jump played as a
                // second, much longer slide immediately after it. Every real
                // step below wraps itself in `withAnimation`, so the re-home
                // is simply left unwrapped and lands instantly and invisibly.
            }
            .frame(height: cardHeight)
            // The strip is wider than the panel and slid horizontally, so the
            // off-centre cards hang outside it. A card hosting an AVPlayerLayer
            // is a real AppKit layer, and an ancestor's `.clipped()` does not
            // reliably mask one -- which is how a neighbouring wallpaper's video
            // ended up drawn over another card's spot. Clipping at the strip
            // itself, plus a compositing group to force rasterisation, keeps
            // that layer inside the window it belongs to.
            .compositingGroup()
            .clipped()
            .contentShape(Rectangle())
            .gesture(
                DragGesture(minimumDistance: 10)
                    .updating($dragOffset) { value, state, _ in
                        state = value.translation.width
                    }
                    .onEnded { value in
                        guard abs(value.translation.width) > CaelestiaParityTokens.Interaction.launcherDragThreshold else { return }
                        move(value.translation.width < 0 ? 1 : -1)
                    }
            )
            .background {
                MacPlusPlusWallpaperScrollMonitor { step in
                    move(step)
                }
            }

            ZStack {
                // Keep the page indicator in the geometric centre of the
                // carousel. Wallpaper importing is owned by Nexus; every dot
                // here represents a wallpaper that can be selected.
                HStack(spacing: Spacing.snug) {
                    ForEach(items) { item in
                        Circle()
                            .fill(item.id == focusedItemID ? Theme.accent : Theme.muted.opacity(0.34))
                            .frame(
                                width: item.id == focusedItemID ? 7 : 5,
                                height: item.id == focusedItemID ? 7 : 5
                            )
                    }
                }
            }
            .padding(.horizontal, Spacing.loose)
            .frame(height: 14)
        }
        .padding(.top, Spacing.base)
        .padding(.bottom, Spacing.snug)
        .offset(y: bottomCarouselOutsideShift)
        .onAppear {
            selectionNeedsCommit = false
            loadCarouselAssets()
            // State writes made by loadCarouselAssets are committed on the
            // next main-loop turn. Re-home after that commit so an extra video
            // selected in a previous session can be focused immediately.
            DispatchQueue.main.async {
                rehomeToCurrentSelection()
                preloadNeighborPosters()
                scheduleLivePreview()
            }
        }
        .onDisappear {
            posterGeneration &+= 1
            posterLoadTask?.cancel()
            posterLoadTask = nil
            posterLoadingIDs.removeAll()
            livePreviewTask?.cancel()
            livePreviewTask = nil
            livePreviewItemID = nil
            // Flush any pending palette application immediately rather than
            // dropping it, so closing the switcher right after a step still
            // commits the wallpaper the user landed on.
            applyTask?.cancel()
            applyTask = nil
            if selectionNeedsCommit, let item = focusedItem { apply(item) }
        }
        .onReceive(NotificationCenter.default.publisher(for: macppWallpaperCatalogChangedNotification)) { note in
            guard let preferredPath = note.userInfo?["path"] as? String else { return }
            reloadCarouselAssets(preferredURL: URL(fileURLWithPath: preferredPath))
        }
        .onReceive(NotificationCenter.default.publisher(for: macppWallpaperFramingChangedNotification)) { note in
            guard let path = note.userInfo?["path"] as? String,
                  let item = items.first(where: {
                      $0.mediaURL?.standardizedFileURL.path == URL(fileURLWithPath: path).standardizedFileURL.path
                  }) else { return }
            wallpaperFramings[item.id] = MacPlusPlusWallpaperFramingStore.load(for: path)
        }
        .onChange(of: focusedItemID) { _, _ in
            preloadNeighborPosters()
            scheduleLivePreview()
        }
        .onChange(of: carouselIndex) { _, _ in preloadNeighborPosters() }
        .onChange(of: shell.selectedPalette) { _, palette in
            guard palette != .custom else { return }
            guard selectedWallpaperOverrideURL() == nil else { return }
            let id = "palette:\(palette.rawValue)"
            guard items.contains(where: { $0.id == id }) else { return }
            focusedItemID = id
            // An external palette change (e.g. the rail's own picker) should
            // just re-home the carousel to the right card directly -- it
            // isn't a step gesture, so there's no adjacent-slide illusion to
            // preserve here.
            carouselIndex = (items.firstIndex(where: { $0.id == id }) ?? 0) + loopPadding
        }
        .onChange(of: launcherModel.overlayArrowRevision) { _, _ in
            guard launcherModel.wallpapersPresented,
                  !launcherModel.wallpaperEditorPresented else { return }
            move(launcherModel.overlayArrowDelta)
        }
    }

    var body: some View {
        Group {
            if let editingItem, let sourceURL = editingItem.mediaURL {
                let editingID = editingItem.id
                MacPlusPlusWallpaperFramingEditorView(
                    sourceURL: sourceURL,
                    poster: posters[editingItem.id],
                    onSave: { selection in
                        let saved = shell.saveWallpaperFraming(selection, for: sourceURL)
                        if saved {
                            wallpaperFramings[editingID] = selection
                            self.editingItem = nil
                            launcherModel.dismissWallpaperEditor()
                        }
                        return saved
                    },
                    onCancel: {
                        self.editingItem = nil
                        launcherModel.dismissWallpaperEditor()
                    }
                )
                .padding(.horizontal, launcherSurfaceShoulder)
            } else {
                carouselBody
            }
        }
        .frame(
            width: wallpaperCarouselSurfaceWidth,
            height: launcherModel.wallpaperEditorPresented
                ? LauncherModel.wallpaperEditorHeight
                : LauncherModel.wallpaperCarouselHeight,
            alignment: .topLeading
        )
        .background(Theme.frame.opacity(shellMaterialOpacity))
        // The parent LauncherView applies BottomMorphShape to this entire
        // surface. Keep the editor's background unmasked here so the carousel
        // can grow into the adjuster without introducing a second rectangular
        // panel or straight outer corners.
        .onChange(of: launcherModel.wallpaperEditorPresented) { _, presented in
            if !presented { editingItem = nil }
        }
        .onDisappear {
            editingItem = nil
            launcherModel.dismissWallpaperEditor()
        }
    }

    @ViewBuilder
    private func wallpaperCard(_ item: MacPlusPlusWallpaperCarouselItem, active: Bool) -> some View {
        ZStack {
            if let image = posters[item.id] {
                // Both of these read from the caches populated in onAppear.
                // They used to hit the filesystem from inside the body -- see
                // the `posters` / `wallpaperURLs` declarations for why that
                // mattered.
                MacPlusPlusWallpaperFramedImage(
                    image: image,
                    selection: wallpaperFramings[item.id] ?? MacPlusPlusWallpaperCropSelection()
                )
            } else {
                // Do not create paused AVPlayers as thumbnail stand-ins. A
                // paused player still consumes a decoder, and three nearby
                // custom cards plus the active live preview were enough to
                // contend with the desktop's outgoing/incoming pair. The small
                // poster worker replaces this placeholder off-main.
                LinearGradient(
                    colors: [Theme.tile, Theme.surface.opacity(0.86)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
                VStack(spacing: Spacing.snug) {
                    Image(systemName: posterLoadingIDs.contains(item.id)
                          ? "hourglass"
                          : "photo")
                        .font(.system(size: ShellIcon.feature, weight: .semibold, design: .rounded))
                    Text(item.title)
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                        .foregroundStyle(Theme.muted)
                        .multilineTextAlignment(.center)
                        .lineLimit(2)
                        .frame(maxWidth: 190)
                }
                .foregroundStyle(Theme.muted)
            }
            if active,
               livePreviewItemID == item.id,
               let url = wallpaperURLs[item.id],
               macppWallpaperVideoExtensions.contains(url.pathExtension.lowercased()) {
                MacPlusPlusWallpaperPreview(
                    url: url,
                    active: true,
                    framing: wallpaperFramings[item.id] ?? MacPlusPlusWallpaperCropSelection(),
                    sourceAspect: posters[item.id].flatMap { image in
                        guard image.size.width > 0, image.size.height > 0 else { return nil }
                        return image.size.width / image.size.height
                    }
                )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .clipped()
            }
        }
        // contentIn/contentOut share the same defaultEffects token (0.20s,
        // expressiveDefaultEffects), so this single non-directional preview
        // crossfade can safely use either name -- what matters is that it's
        // the shared content-fade curve instead of a one-off 0.14s ease-out.
        .animation(ShellMotion.contentIn.animation, value: livePreviewItemID)
        .frame(width: cardWidth, height: cardHeight)
        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                .stroke(active ? Theme.accent.opacity(0.72) : Theme.seam.opacity(0.34), lineWidth: 1)
        }
    }

    private func select(_ item: MacPlusPlusWallpaperCarouselItem) {
        // Tapping a visible card (rather than stepping past an end) can just
        // jump straight to its real index -- there's no boundary-wraparound
        // illusion to preserve for a direct tap.
        guard let index = items.firstIndex(where: { $0.id == item.id }) else { return }
        withAnimation(ShellMotion.carousel.animation) {
            focusedItemID = item.id
            carouselIndex = index + loopPadding
        }
        selectionNeedsCommit = true
        scheduleApply(item)
    }

    private func move(_ step: Int) {
        guard !items.isEmpty else { return }
        // If the previous step parked the strip on a duplicate end-cap, re-home
        // now, before this step is animated.
        //
        // This used to happen on a timer scheduled for the end of the slide,
        // guarded on `carouselIndex` not having changed since. A second step
        // arriving before that timer fired therefore cancelled its own
        // clean-up: the guard failed, the re-home was dropped, and the index
        // kept incrementing past the end of the strip. Scrolling quickly
        // through the wallpapers walked it into slots that do not exist, which
        // is why the switcher would show blank space or the wrong card. Doing
        // it here instead makes the correction deterministic -- there is no
        // window in which a second step can race the first one's clean-up.
        normalizeCarouselIndex()
        let current = items.firstIndex(where: { $0.id == focusedItemID }) ?? 0
        guard let next = MacPlusPlusPureLogic.advancedCarouselIndex(
            current: current,
            step: step,
            itemCount: items.count
        ) else { return }
        let nextItem = items[next]
        // Step to the immediately adjacent visual slot, which may be one of
        // the duplicate end-cap cards rather than the real card's own index
        // -- that's what makes stepping off either end continue sliding in
        // the same direction instead of snapping back across the whole
        // carousel to reach the real first/last item.
        withAnimation(ShellMotion.carousel.animation) {
            carouselIndex += step
            focusedItemID = nextItem.id
        }
        selectionNeedsCommit = true
        scheduleApply(nextItem)
    }

    /// Maps a duplicate end-cap slot back onto the real card showing the same
    /// wallpaper. Both slots render identically, so the correction is invisible
    /// -- it exists purely to keep `carouselIndex` inside the strip.
    ///
    /// Deliberately outside any `withAnimation`: this is bookkeeping, not
    /// motion. Animating it slides the strip back across the whole carousel,
    /// which is what made wrapping past the last wallpaper feel like it
    /// accelerated away.
    private func normalizeCarouselIndex() {
        let count = items.count
        let firstRealIndex = loopPadding
        let lastRealIndex = loopPadding + count - 1
        guard count > 0,
              carouselIndex < firstRealIndex || carouselIndex > lastRealIndex else { return }
        guard let normalized = MacPlusPlusPureLogic.normalizedCarouselVisualIndex(
            carouselIndex,
            itemCount: count,
            padding: loopPadding
        ) else { return }
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { carouselIndex = normalized }
    }

    // Resolved once when the switcher opens. Imported media is added through
    // the shared ShellModel importer and then causes this list to reload from
    // the same managed folder.
    private func loadCarouselAssets() {
        guard items.isEmpty else { return }
        var loadedItems: [MacPlusPlusWallpaperCarouselItem] = []
        var loadedPosters: [String: NSImage] = [:]
        var loadedURLs: [String: URL] = [:]
        var loadedFramings: [String: MacPlusPlusWallpaperCropSelection] = [:]
        for palette in palettes {
            let id = "palette:\(palette.rawValue)"
            let url = wallpaperURL(for: palette)
            loadedItems.append(
                MacPlusPlusWallpaperCarouselItem(
                    id: id,
                    palette: palette,
                    title: palette.title,
                    mediaURL: url
                )
            )
            if let image = wallpaperPoster(for: palette) { loadedPosters[id] = image }
            if let url {
                loadedURLs[id] = url
                loadedFramings[id] = MacPlusPlusWallpaperFramingStore.load(for: url.path)
            }
        }
        var referenced = Set(loadedURLs.values.map { $0.standardizedFileURL.path })
        let folder = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Wallpapers", isDirectory: true)
        var extraURLs = (try? FileManager.default.contentsOfDirectory( // macpp:silent-ok an unreadable wallpaper directory contributes no extra media
            at: folder,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ))?
            .filter { macppWallpaperMediaExtensions.contains($0.pathExtension.lowercased()) }
            .filter { !referenced.contains($0.standardizedFileURL.path) } ?? []
        for url in extraURLs { referenced.insert(url.standardizedFileURL.path) }
        var legacyTitles: [String: String] = [:]
        // Legacy palette profiles are deliberately no longer dedicated cards,
        // but their videos still belong to the shared library. Surface them as
        // ordinary extras so moving to the two-core-palette model never hides
        // a wallpaper that was already installed.
        for legacy in ShellPalette.allCases where legacy != .custom && !ShellPalette.dedicatedPalettes.contains(legacy) {
            guard let url = wallpaperURL(for: legacy) else { continue }
            let normalized = url.standardizedFileURL
            guard referenced.insert(normalized.path).inserted else { continue }
            extraURLs.append(normalized)
            legacyTitles[normalized.path] = legacy.title
        }
        for normalized in extraURLs.sorted(by: {
            $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending
        }) {
            let id = "extra:\(normalized.path)"
            loadedItems.append(MacPlusPlusWallpaperCarouselItem(
                id: id,
                palette: nil,
                title: legacyTitles[normalized.path] ?? extraDisplayName(for: normalized),
                mediaURL: normalized
            ))
            loadedURLs[id] = normalized
            loadedFramings[id] = MacPlusPlusWallpaperFramingStore.load(for: normalized.path)
            if let image = cachedWallpaperPoster(for: normalized) { loadedPosters[id] = image }
        }
        items = loadedItems
        posters = loadedPosters
        wallpaperURLs = loadedURLs
        wallpaperFramings = loadedFramings

    }

    private func reloadCarouselAssets(preferredURL: URL?) {
        applyTask?.cancel()
        applyTask = nil
        livePreviewTask?.cancel()
        livePreviewTask = nil
        posterGeneration &+= 1
        posterLoadTask?.cancel()
        posterLoadTask = nil
        posterLoadingIDs.removeAll()
        items = []
        posters = [:]
        wallpaperURLs = [:]
        wallpaperFramings = [:]
        carouselIndex = loopPadding
        posterLoadingIDs = []
        lastAppliedItemID = nil
        selectionNeedsCommit = false
        loadCarouselAssets()
        DispatchQueue.main.async {
            if let preferredURL,
               let item = items.first(where: { $0.mediaURL?.standardizedFileURL == preferredURL.standardizedFileURL }) {
                focusedItemID = item.id
                carouselIndex = (items.firstIndex(of: item) ?? 0) + loopPadding
            } else {
                rehomeToCurrentSelection()
            }
            preloadNeighborPosters()
            scheduleLivePreview()
        }
    }

    private func rehomeToCurrentSelection() {
        guard !items.isEmpty else { return }
        let id: String
        if let override = selectedWallpaperOverrideURL(),
           let extra = items.first(where: { $0.mediaURL?.standardizedFileURL.path == override.path }) {
            id = extra.id
        } else {
            let palette = shell.selectedPalette == .custom ? .midnight : shell.selectedPalette
            let dedicatedID = "palette:\(palette.rawValue)"
            if items.contains(where: { $0.id == dedicatedID }) {
                id = dedicatedID
            } else if let legacyURL = wallpaperURL(for: palette),
                      let legacy = items.first(where: { $0.mediaURL?.standardizedFileURL == legacyURL.standardizedFileURL }) {
                id = legacy.id
            } else {
                id = "palette:midnight"
            }
        }
        guard let index = items.firstIndex(where: { $0.id == id }) else { return }
        focusedItemID = id
        carouselIndex = index + loopPadding
    }

    /// Put the focused card and the next card on the decode queue first. The
    /// carousel still fills the rest in the background, but navigation should
    /// never land on an unpainted adjacent slot merely because a large 4K
    /// video happened to be earlier in the sequential queue.
    private func preloadNeighborPosters() {
        guard !items.isEmpty else { return }
        let priorityIDs = [carouselIndex - 1, carouselIndex, carouselIndex + 1]
            .compactMap { carouselItems.indices.contains($0) ? carouselItems[$0].id : nil }
        let priority = Set(priorityIDs)
        let pending = items.compactMap { item -> (String, URL)? in
            guard posters[item.id] == nil, let url = wallpaperURLs[item.id] else { return nil }
            return (item.id, url)
        }.sorted { left, right in
            let leftPriority = priority.contains(left.0)
            let rightPriority = priority.contains(right.0)
            return leftPriority != rightPriority ? leftPriority : left.0 < right.0
        }
        guard !pending.isEmpty else { return }
        posterGeneration &+= 1
        let generation = posterGeneration
        posterLoadTask?.cancel()
        posterLoadingIDs.removeAll()
        posterLoadTask = Task { @MainActor in
            for (id, url) in pending {
                guard !Task.isCancelled, generation == posterGeneration else { return }
                posterLoadingIDs.insert(id)
                let data = await Self.wallpaperPosterData(for: url)
                guard !Task.isCancelled, generation == posterGeneration else { return }
                if let data, let image = NSImage(data: data) { posters[id] = image }
                posterLoadingIDs.remove(id)
            }
            posterLoadTask = nil
        }
    }

    private func selectedWallpaperOverrideURL() -> URL? {
        let url = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/selected-wallpaper")
        guard let raw = try? String(contentsOf: url, encoding: .utf8) else { return nil } // macpp:silent-ok absent override state means no selected wallpaper
        let path = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !path.isEmpty, FileManager.default.fileExists(atPath: path) else { return nil }
        return URL(fileURLWithPath: path).standardizedFileURL
    }

    private func apply(_ item: MacPlusPlusWallpaperCarouselItem) {
        if lastAppliedItemID == item.id, itemMatchesCurrentSelection(item) {
            selectionNeedsCommit = false
            return
        }
        lastAppliedItemID = item.id
        selectionNeedsCommit = false
        if let palette = item.palette {
            if shell.selectedPalette != palette || selectedWallpaperOverrideURL() != nil {
                shell.setPalette(palette)
            }
        } else if let url = item.mediaURL {
            shell.applyWallpaperOverride(url)
        }
    }

    private func itemMatchesCurrentSelection(_ item: MacPlusPlusWallpaperCarouselItem) -> Bool {
        if let palette = item.palette {
            return shell.selectedPalette == palette && selectedWallpaperOverrideURL() == nil
        }
        guard let expected = item.mediaURL?.standardizedFileURL.path else { return false }
        return selectedWallpaperOverrideURL()?.path == expected
    }

    private func canDelete(_ item: MacPlusPlusWallpaperCarouselItem) -> Bool {
        guard item.palette == nil, let url = item.mediaURL else { return false }
        let folder = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent(
                "Library/Application Support/MacPlusPlus/Wallpapers",
                isDirectory: true
            )
            .standardizedFileURL
        guard url.standardizedFileURL.deletingLastPathComponent() == folder,
              // macpp:silent-ok a disappeared wallpaper is not deletable.
              let values = try? url.resourceValues(forKeys: [.isRegularFileKey]) else { return false }
        return values.isRegularFile == true
    }

    private func delete(_ item: MacPlusPlusWallpaperCarouselItem) {
        guard let url = item.mediaURL, canDelete(item) else { return }
        if shell.deleteMacPlusPlusWallpaper(url) {
            hoveredItemID = nil
        }
    }

    // A step should feel instant, so `focusedItemID` (and therefore the highlight
    // and the live preview) moves immediately; only the expensive shell-wide
    // retheme is deferred until the user stops moving.
    private func scheduleApply(_ item: MacPlusPlusWallpaperCarouselItem) {
        applyTask?.cancel()
        applyTask = Task { @MainActor in
            // Let the 280ms carousel step settle before a palette-wide redraw
            // and video load begin. Custom videos used to apply at 190ms, while
            // the strip was still moving, which made only the new slots hitch.
            let delay = UInt64((ShellMotion.carousel.duration + 0.04) * 1_000_000_000)
            try? await Task.sleep(nanoseconds: delay) // macpp:silent-ok cancellation aborts the delayed wallpaper apply
            guard !Task.isCancelled, focusedItemID == item.id else { return }
            apply(item)
            applyTask = nil
        }
    }

    private func scheduleLivePreview() {
        livePreviewTask?.cancel()
        livePreviewItemID = nil
        let id = focusedItemID
        livePreviewTask = Task { @MainActor in
            // Let the attached shell and its cached poster land first. Starting
            // AVPlayer in the opening frame made the whole morph wait on media.
            try? await Task.sleep(nanoseconds: 220_000_000) // macpp:silent-ok cancellation aborts the delayed live preview
            guard !Task.isCancelled, focusedItemID == id else { return }
            livePreviewItemID = id
            livePreviewTask = nil
        }
    }

    private nonisolated static func wallpaperPosterData(for url: URL) async -> Data? {
        if !macppWallpaperVideoExtensions.contains(url.pathExtension.lowercased()) {
            guard let image = NSImage(contentsOf: url),
                  let tiff = image.tiffRepresentation,
                  let bitmap = NSBitmapImageRep(data: tiff) else { return nil }
            return bitmap.representation(using: .jpeg, properties: [.compressionFactor: 0.86])
        }
        let asset = AVURLAsset(url: url)
        let generator = AVAssetImageGenerator(asset: asset)
        generator.appliesPreferredTrackTransform = true
        generator.requestedTimeToleranceBefore = CMTime(seconds: 0.25, preferredTimescale: 600)
        generator.requestedTimeToleranceAfter = CMTime(seconds: 0.25, preferredTimescale: 600)
        // These land in a 270x152 card. Decoding a full 4K frame for each one
        // -- now that this runs over every slot when the carousel opens, not
        // just the imported extras -- is a lot of work to then throw away.
        // 640x360 is comfortably above the card's backing size on Retina.
        generator.maximumSize = CGSize(width: 640, height: 360)
        guard let image = try? await generator.image( // macpp:silent-ok unavailable preview frame leaves the poster unavailable
            at: CMTime(seconds: 0.35, preferredTimescale: 600)
        ).image else { return nil }
        return NSBitmapImageRep(cgImage: image).representation(using: .jpeg, properties: [:])
    }

    private func extraDisplayName(for url: URL) -> String {
        let stem = url.deletingPathExtension().lastPathComponent
            .replacingOccurrences(of: "-", with: " ")
            .replacingOccurrences(of: "_", with: " ")
        return String(stem.uppercased().prefix(28))
    }

    private func wallpaperPoster(for palette: ShellPalette) -> NSImage? {
        let root = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Posters", isDirectory: true)
        let original = root.appendingPathComponent("\(palette.rawValue).png")
        let picker = root.deletingLastPathComponent()
            .appendingPathComponent("PickerPosters", isDirectory: true)
            .appendingPathComponent("\(palette.rawValue).jpg")
        let originalDate = (try? original.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast // macpp:silent-ok missing poster metadata sorts the source as old
        let pickerDate = (try? picker.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast // macpp:silent-ok missing picker metadata sorts the source as old
        let source = (FileManager.default.fileExists(atPath: picker.path) && pickerDate >= originalDate) ? picker : original
        let cacheKey = "\(source.path)|\(source == picker ? pickerDate.timeIntervalSince1970 : originalDate.timeIntervalSince1970)" as NSString
        if let cached = Self.posterCache.object(forKey: cacheKey) { return cached }
        guard let image = NSImage(contentsOf: source) else { return nil }
        Self.posterCache.setObject(image, forKey: cacheKey)
        return image
    }

    /// Mac++ Wallpaper Engine names a poster after the palette (for example
    /// `custom.png`) and records the actual video path in its adjacent
    /// `.source` file. Extra carousel items are keyed by their full path, so
    /// the old palette-only lookup could not see a perfectly good poster that
    /// already existed on disk. Reuse that poster before starting another
    /// decoder for the same video.
    private func cachedWallpaperPoster(for url: URL) -> NSImage? {
        let root = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Posters", isDirectory: true)
        guard let files = try? FileManager.default.contentsOfDirectory( // macpp:silent-ok an unreadable poster cache has no cached fallback
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        ) else { return nil }
        let wanted = url.standardizedFileURL.path
        for source in files where source.pathExtension.lowercased() == "source" {
            guard let raw = try? String(contentsOf: source, encoding: .utf8), // macpp:silent-ok an unreadable poster metadata file is skipped
                  raw.split(separator: "|", maxSplits: 1, omittingEmptySubsequences: false).first
                    .map(String.init) == wanted else { continue }
            let poster = source.deletingPathExtension().appendingPathExtension("png")
            guard let image = NSImage(contentsOf: poster) else { continue }
            Self.posterCache.setObject(image, forKey: poster.path as NSString)
            return image
        }
        return nil
    }

    private func wallpaperURL(for palette: ShellPalette) -> URL? {
        let root = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus", isDirectory: true)
        let presetsURL = root.appendingPathComponent("Presets.json")
        guard let data = try? Data(contentsOf: presetsURL), // macpp:silent-ok missing wallpaper presets leave the URL unavailable
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any], // macpp:silent-ok malformed wallpaper presets leave the URL unavailable
              let profiles = json["profiles"] as? [String: Any],
              let profile = profiles[palette.rawValue] as? [String: Any],
              let raw = profile["wallpaper"] as? String,
              !raw.isEmpty else { return nil }
        let path: String
        if raw.hasPrefix("bundle://") {
            path = FileManager.default.homeDirectoryForCurrentUser
                .appendingPathComponent("Applications/Mac++ Wallpaper.app/Contents/Resources", isDirectory: true)
                .appendingPathComponent(String(raw.dropFirst("bundle://".count))).path
        } else {
            path = (raw as NSString).expandingTildeInPath
        }
        guard FileManager.default.fileExists(atPath: path) else { return nil }
        return URL(fileURLWithPath: path)
    }
}

/// The Visualiser switcher mirrors the wallpaper switcher's infinite geometry,
/// but its cards are authored scenes instead of media. Clock state is
/// deliberately outside this carousel; each scene owns the independent clock
/// overlay so changing a visualiser never unexpectedly turns a clock on.
private struct MacPlusPlusDesktopCarouselView: View {
    // Do not observe ShellModel here. Its audio level array is published
    // about eighteen times per second; subscribing the whole carousel made
    // every inactive Canvas card rebuild for every audio frame. The focused
    // card owns the narrow live subscription below instead.
    let shell: ShellModel
    @ObservedObject var palette: ShellPalettePresentation
    @ObservedObject var nexus: MacPlusPlusNexusModel
    @ObservedObject var launcherModel: LauncherModel
    @State private var focusedSceneID = MacPlusPlusDesktopScene.all[0].id
    @State private var carouselIndex = 2
    @GestureState private var dragOffset: CGFloat = 0

    // Keep Visualiser on the same broad three-card rhythm as Wallpapers. The
    // old 270x152/208pt geometry left it looking like a separate, older picker
    // even though both surfaces use the same bottom-attached shell contour.
    private let cardWidth: CGFloat = 300
    private let cardHeight: CGFloat = 169
    private let spacing: CGFloat = 16
    private let loopPadding = 2

    private var scenes: [MacPlusPlusDesktopScene] { MacPlusPlusDesktopScene.all }
    private var carouselItems: [MacPlusPlusDesktopScene] {
        MacPlusPlusPureLogic.loopPaddedCarousel(scenes, padding: loopPadding)
    }
    var body: some View {
        VStack(spacing: Spacing.base) {
            GeometryReader { geometry in
                HStack(spacing: spacing) {
                    ForEach(Array(carouselItems.enumerated()), id: \.offset) { index, scene in
                        Button { select(scene) } label: {
                            desktopSceneCard(scene, active: index == carouselIndex)
                        }
                        .buttonStyle(.plain)
                        .frame(width: cardWidth, height: cardHeight)
                        .id("desktop-scene-\(scene.id)-palette-\(palette.palette.rawValue)")
                        .scaleEffect(index == carouselIndex ? 1 : 0.88)
                        .opacity(index == carouselIndex ? 1 : 0.48)
                    }
                }
                .offset(
                    x: geometry.size.width / 2
                        - cardWidth / 2
                        - CGFloat(carouselIndex) * (cardWidth + spacing)
                        + dragOffset
                )
            }
            .frame(height: cardHeight)
            .compositingGroup()
            .clipped()
            .contentShape(Rectangle())
            .gesture(
                DragGesture(minimumDistance: 10)
                    .updating($dragOffset) { value, state, _ in
                        state = value.translation.width
                    }
                    .onEnded { value in
                        guard abs(value.translation.width) > CaelestiaParityTokens.Interaction.launcherDragThreshold else { return }
                        move(value.translation.width < 0 ? 1 : -1)
                    }
            )
            .background {
                MacPlusPlusWallpaperScrollMonitor { step in move(step) }
            }

            HStack(spacing: Spacing.snug) {
                ForEach(scenes) { scene in
                    Circle()
                        .fill(
                            scene.id == focusedSceneID
                                ? Theme.accent
                                : Theme.muted.opacity(0.34)
                        )
                        .frame(
                            width: scene.id == focusedSceneID ? 7 : 5,
                            height: scene.id == focusedSceneID ? 7 : 5
                        )
                }
            }
            .padding(.horizontal, Spacing.loose)
            .frame(height: 14)
        }
        .padding(.top, Spacing.base)
        .padding(.bottom, Spacing.snug)
        .offset(y: bottomCarouselOutsideShift)
        .frame(
            width: wallpaperCarouselSurfaceWidth,
            height: LauncherModel.wallpaperCarouselHeight,
            alignment: .topLeading
        )
        .background(Theme.frame.opacity(shellMaterialOpacity))
        .clipped()
        .onAppear {
            rehomeToCurrentSelection()
        }
        .onChange(of: launcherModel.overlayArrowRevision) { _, _ in
            guard launcherModel.desktopPresented else { return }
            move(launcherModel.overlayArrowDelta)
        }
        .onDisappear { }
    }

    @ViewBuilder
    private func desktopSceneCard(_ scene: MacPlusPlusDesktopScene, active: Bool) -> some View {
        ZStack(alignment: .bottomLeading) {
            if active {
                MacPlusPlusLiveVisualizerPreview(
                    style: scene.visualizerStyle,
                    shell: shell
                )
            } else {
                MacPlusPlusVisualizerPreview(
                    style: scene.visualizerStyle,
                    active: false
                )
            }
            HStack(spacing: Spacing.snug) {
                VStack(alignment: .leading, spacing: Spacing.none) {
                    Text(scene.title)
                        .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                }
                Spacer(minLength: 4)
            }
            .foregroundStyle(active ? Theme.bright : Theme.muted)
            .padding(.horizontal, Spacing.snug)
            .padding(.vertical, Spacing.hairline)
            .frame(height: 30)
            .background(Theme.frame.opacity(0.62), in: Capsule())
            .padding(Spacing.base)
        }
        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                .stroke(
                    active ? Theme.accent.opacity(0.78) : Theme.seam.opacity(0.34),
                    lineWidth: 1
                )
        }
    }

    private func rehomeToCurrentSelection() {
        let match = scenes.first {
            $0.visualizerStyle == nexus.desktopVisualizerStyle
                && $0.mode == nexus.desktopLayerMode
        }
        let scene = match ?? scenes[0]
        focusedSceneID = scene.id
        carouselIndex = (scenes.firstIndex(of: scene) ?? 0) + loopPadding
    }

    private func select(_ scene: MacPlusPlusDesktopScene) {
        guard let index = scenes.firstIndex(of: scene) else { return }
        withAnimation(ShellMotion.carousel.animation) {
            focusedSceneID = scene.id
            carouselIndex = index + loopPadding
        }
        nexus.setDesktopVisualizerScene(scene)
    }

    private func move(_ step: Int) {
        guard !scenes.isEmpty else { return }
        normalizeCarouselIndex()
        let current = scenes.firstIndex(where: { $0.id == focusedSceneID }) ?? 0
        guard let next = MacPlusPlusPureLogic.advancedCarouselIndex(
            current: current,
            step: step,
            itemCount: scenes.count
        ) else { return }
        let nextScene = scenes[next]
        withAnimation(ShellMotion.carousel.animation) {
            carouselIndex += step
            focusedSceneID = nextScene.id
        }
        nexus.setDesktopVisualizerScene(nextScene)
    }

    private func normalizeCarouselIndex() {
        guard carouselIndex < loopPadding
                || carouselIndex > loopPadding + scenes.count - 1,
              let normalized = MacPlusPlusPureLogic.normalizedCarouselVisualIndex(
                carouselIndex,
                itemCount: scenes.count,
                padding: loopPadding
              ) else { return }
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { carouselIndex = normalized }
    }

}

/// The screen-saver picker deliberately previews scenes as still artwork. The
/// The public profile keeps this picker preview-only. It persists the chosen
/// scene without starting a process or waking an animation timeline.
private struct MacPlusPlusScreensaverCarouselView: View {
    @ObservedObject var shell: ShellModel
    @ObservedObject var launcherModel: LauncherModel
    @State private var focusedSelection: String
    @State private var carouselIndex: Int
    @GestureState private var dragOffset: CGFloat = 0

    // Screensavers use the exact authored card rhythm as Wallpapers and
    // Visualiser. Keep these as fixed authored values: the surrounding
    // LauncherView already applies the display-local scale to the complete
    // surface once, so scaling these children again makes the vertical budget
    // drift and leaves a larger top gutter on some displays.
    private let cardWidth: CGFloat = 300
    private let cardHeight: CGFloat = 169
    private let spacing: CGFloat = 16
    private let loopPadding = 2

    private let stackSpacing: CGFloat = Spacing.base
    private let surfaceWidth: CGFloat = wallpaperCarouselSurfaceWidth
    private let surfaceHeight: CGFloat = LauncherModel.wallpaperCarouselHeight

    init(shell: ShellModel, launcherModel: LauncherModel) {
        self.shell = shell
        self.launcherModel = launcherModel
        let selected = macppScreensaverChoices.first {
            $0.selection == shell.selectedScreensaver
        } ?? macppScreensaverChoices[0]
        let index = macppScreensaverChoices.firstIndex(of: selected) ?? 0
        _focusedSelection = State(initialValue: selected.selection)
        _carouselIndex = State(initialValue: index + 2)
    }

    private var choices: [MacPlusPlusScreensaverChoice] { macppScreensaverChoices }
    private var carouselItems: [MacPlusPlusScreensaverChoice] {
        MacPlusPlusPureLogic.loopPaddedCarousel(choices, padding: loopPadding)
    }

    var body: some View {
        VStack(spacing: stackSpacing) {
            GeometryReader { geometry in
                HStack(spacing: spacing) {
                    ForEach(Array(carouselItems.enumerated()), id: \.offset) { index, choice in
                        Button { select(choice) } label: {
                            screensaverCard(choice, active: index == carouselIndex)
                        }
                        .buttonStyle(.plain)
                        .frame(width: cardWidth, height: cardHeight)
                        .id("screensaver-card-\(choice.id)-palette-\(shell.companionRevision)")
                        .scaleEffect(index == carouselIndex ? 1 : 0.88)
                        .opacity(index == carouselIndex ? 1 : 0.48)
                    }
                }
                .offset(
                    x: geometry.size.width / 2
                        - cardWidth / 2
                        - CGFloat(carouselIndex) * (cardWidth + spacing)
                        + dragOffset
                )
            }
            .frame(height: cardHeight)
            .compositingGroup()
            .clipped()
            .contentShape(Rectangle())
            .gesture(
                DragGesture(minimumDistance: 10)
                    .updating($dragOffset) { value, state, _ in
                        state = value.translation.width
                    }
                    .onEnded { value in
                        guard abs(value.translation.width) > CaelestiaParityTokens.Interaction.launcherDragThreshold else { return }
                        move(value.translation.width < 0 ? 1 : -1)
                    }
            )
            .background {
                MacPlusPlusWallpaperScrollMonitor { step in move(step) }
            }

            HStack(spacing: Spacing.snug) {
                ForEach(choices) { choice in
                    Circle()
                        .fill(
                            choice.selection == focusedSelection
                                ? Theme.accent
                                : Theme.muted.opacity(0.34)
                        )
                        .frame(
                            width: choice.selection == focusedSelection ? 7 : 5,
                            height: choice.selection == focusedSelection ? 7 : 5
                        )
                }
            }
            .padding(.horizontal, Spacing.loose)
            .frame(height: 14)
        }
        .padding(.top, Spacing.base)
        .padding(.bottom, Spacing.snug)
        // Match the wallpaper and visualiser carousels' bottom attachment
        // exactly. The screen-saver panel must not add its own top headroom.
        .offset(y: bottomCarouselOutsideShift)
        // Keep this surface on the same authored width/height as Wallpapers
        // and Visualiser. The outer Cast host still animates its live width
        // during the Search -> carousel morph; this inner surface must not
        // invent a second, narrower card geometry.
        .frame(
            width: surfaceWidth,
            height: surfaceHeight,
            alignment: .topLeading
        )
        .background(Theme.frame.opacity(shellMaterialOpacity))
        .clipped()
        .onAppear { rehomeToCurrentSelection() }
        .onChange(of: launcherModel.overlayArrowRevision) { _, _ in
            guard launcherModel.screensaversPresented else { return }
            move(launcherModel.overlayArrowDelta)
        }
        .onChange(of: launcherModel.overlayConfirmRevision) { _, _ in
            guard launcherModel.screensaversPresented else { return }
            shell.startScreensaver(focusedSelection)
        }
    }

    @ViewBuilder
    private func screensaverCard(
        _ choice: MacPlusPlusScreensaverChoice,
        active: Bool
    ) -> some View {
        ZStack(alignment: .bottomLeading) {
            MacPlusPlusScreensaverPreview(choice: choice, active: active)
            HStack(spacing: Spacing.snug) {
                VStack(alignment: .leading, spacing: Spacing.none) {
                    Text(choice.title)
                        .font(.system(
                            size: ShellTypography.nano,
                            weight: .semibold,
                            design: ShellTypography.preferredDesign(for: ShellTypography.nano)
                        ))
                }
                Spacer(minLength: 4)
            }
            .foregroundStyle(active ? Theme.bright : Theme.muted)
            .padding(.horizontal, Spacing.snug)
            .padding(.vertical, Spacing.hairline)
            .frame(height: 30)
            .background(Theme.frame.opacity(0.62), in: Capsule())
            .padding(Spacing.base)
        }
        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                .stroke(
                    active ? Theme.accent.opacity(0.78) : Theme.seam.opacity(0.34),
                    lineWidth: 1
                )
        }
    }

    private func rehomeToCurrentSelection() {
        let choice = choices.first { $0.selection == shell.selectedScreensaver } ?? choices[0]
        focusedSelection = choice.selection
        carouselIndex = (choices.firstIndex(where: { $0.selection == choice.selection }) ?? 0) + loopPadding
    }

    private func select(_ choice: MacPlusPlusScreensaverChoice) {
        guard let index = choices.firstIndex(where: { $0.selection == choice.selection }) else { return }
        withAnimation(ShellMotion.carousel.animation) {
            focusedSelection = choice.selection
            carouselIndex = index + loopPadding
        }
        shell.setScreensaver(choice.selection)
    }

    private func move(_ step: Int) {
        guard !choices.isEmpty, step != 0 else { return }
        normalizeCarouselIndex()
        let current = choices.firstIndex(where: { $0.selection == focusedSelection }) ?? 0
        guard let next = MacPlusPlusPureLogic.advancedCarouselIndex(
            current: current,
            step: step,
            itemCount: choices.count
        ) else { return }
        let nextChoice = choices[next]
        withAnimation(ShellMotion.carousel.animation) {
            carouselIndex += step
            focusedSelection = nextChoice.selection
        }
        shell.setScreensaver(nextChoice.selection)
    }

    private func normalizeCarouselIndex() {
        guard carouselIndex < loopPadding
                || carouselIndex > loopPadding + choices.count - 1,
              let normalized = MacPlusPlusPureLogic.normalizedCarouselVisualIndex(
                carouselIndex,
                itemCount: choices.count,
                padding: loopPadding
              ) else { return }
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { carouselIndex = normalized }
    }
}

/// Static terminal captures for the screensaver carousel. The images are made
/// by launching the real Mac++/CMatrix saver in a bounded preview window, so
/// the picker shows the same glyphs and palette as the saver without starting
/// a live PTY or rebuilding a large SwiftUI drawing tree for every card.
private struct MacPlusPlusScreensaverPreview: View {
    let choice: MacPlusPlusScreensaverChoice
    let active: Bool

    private static let imageCache: NSCache<NSString, NSImage> = {
        let cache = NSCache<NSString, NSImage>()
        cache.countLimit = macppScreensaverChoices.count
        return cache
    }()

    private var assetName: String {
        if choice.selection == "cmatrix" { return "cmatrix" }
        return choice.selection.replacingOccurrences(of: "macpp-preview:", with: "macpp-preview-")
    }

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .fill(Theme.surface.opacity(0.34))
            if let image = Self.loadImage(named: assetName) {
                GeometryReader { geometry in
                    Image(nsImage: image)
                        .resizable()
                        .interpolation(.high)
                        .aspectRatio(contentMode: .fit)
                        .frame(width: geometry.size.width, height: geometry.size.height)
                        .opacity(active ? 1 : 0.82)
                }
            } else {
                // Keep a source-only fallback for an unbuilt checkout or a
                // developer preview that has not copied the PNG resources.
                MacPlusPlusScreensaverArtwork(scene: choice.selection, active: active)
            }
        }
        .overlay(
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(Theme.bright.opacity(0.08), lineWidth: 1)
        )
        .clipped()
    }

    private static func loadImage(named name: String) -> NSImage? {
        let key = name as NSString
        if let cached = imageCache.object(forKey: key) { return cached }
        guard let url = Bundle.main.url(
            forResource: name,
            withExtension: "png",
            subdirectory: "screensaver-previews"
        ), let image = NSImage(contentsOf: url) else { return nil }
        imageCache.setObject(image, forKey: key)
        return image
    }
}

/// A still, palette-aware approximation of each terminal scene. These are
/// intentionally scene-specific rather than generic SF Symbol cards: Mac++'s
/// real output is terminal geometry (braille waves, glyph rain, pipes, cells,
/// and so on), so the picker should communicate that shape before anything is
/// launched. No TimelineView or saver process is used here.
private struct MacPlusPlusScreensaverArtwork: View {
    let scene: String
    let active: Bool

    private var seed: Int {
        scene.utf8.reduce(17) { ($0 &* 31) &+ Int($1) }
    }

    private var palette: [Color] {
        [Theme.accent, Theme.ice, Theme.mint, Theme.bright]
    }

    var body: some View {
        // Keep the old vector helpers below as a reference for the scene
        // vocabulary, but render the picker with a bounded terminal snapshot.
        // Mac++ itself is an ANSI terminal program; the previous free-form
        // Canvas approximation looked like unrelated illustrations and was
        // also the source of intermittent clipped/aliased preview artifacts.
        MacPlusPlusScreensaverTerminalArtwork(scene: scene, active: active)
    }

    @ViewBuilder
    private var sceneOverlay: some View {
        switch scene {
        case "cmatrix":
            Text(matrixGlyphs)
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(Theme.accent.opacity(active ? 0.82 : 0.56))
                .lineSpacing(-2)
                .kerning(1.1)
                .padding(10)
        case "macpp-preview:rain":
            Text(rainGlyphs)
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(Theme.accent.opacity(active ? 0.84 : 0.58))
                .lineSpacing(-2)
                .kerning(0.7)
                .padding(10)
        case "macpp-preview:clock":
            VStack(spacing: 1) {
                Text("12:34")
                    .font(.system(size: 28, weight: .semibold, design: .monospaced))
                Text("09.14  •  MAC++")
                    .font(.system(size: 8, weight: .medium, design: .monospaced))
                    .opacity(0.72)
            }
            .foregroundStyle(Theme.bright.opacity(active ? 0.92 : 0.62))
        case "macpp-preview:dvd":
            Text("mac++")
                .font(.system(size: 13, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.bright.opacity(active ? 0.94 : 0.62))
                .padding(.horizontal, 10)
                .padding(.vertical, 5)
                .background(Theme.accent.opacity(active ? 0.32 : 0.20), in: RoundedRectangle(cornerRadius: 5, style: .continuous))
                .overlay {
                    RoundedRectangle(cornerRadius: 5, style: .continuous)
                        .stroke(Theme.bright.opacity(0.42), lineWidth: 0.8)
                }
        default:
            EmptyView()
        }
    }

    private var matrixGlyphs: String {
        let glyphs = Array("01[]{}<>+*/")
        return (0..<8).map { row in
            (0..<22).map { column in
                let index = macppPositiveModulo(
                    seed &+ row &* 19 &+ column &* 7,
                    glyphs.count
                )
                return String(glyphs[index])
            }.joined(separator: " ")
        }.joined(separator: "\n")
    }

    private var rainGlyphs: String {
        let glyphs = Array("ｱｲｳｴｵｶｷｸｹｺ0123456789")
        return (0..<8).map { row in
            (0..<22).map { column in
                let index = macppPositiveModulo(
                    seed &+ row &* 11 &+ column &* 5,
                    glyphs.count
                )
                return String(glyphs[index])
            }.joined(separator: " ")
        }.joined(separator: "\n")
    }

    private func drawScene(in context: inout GraphicsContext, size: CGSize) {
        switch scene {
        case "cmatrix": drawMatrix(in: &context, size: size)
        case "macpp-preview:waveform": drawWaveform(in: &context, size: size)
        case "macpp-preview:constellation": drawConstellation(in: &context, size: size)
        case "macpp-preview:rain": drawRain(in: &context, size: size)
        case "macpp-preview:particles": drawParticles(in: &context, size: size)
        case "macpp-preview:pipes": drawPipes(in: &context, size: size)
        case "macpp-preview:maze": drawMaze(in: &context, size: size)
        case "macpp-preview:life": drawLife(in: &context, size: size)
        case "macpp-preview:clock": drawClock(in: &context, size: size)
        case "macpp-preview:orrery": drawOrrery(in: &context, size: size)
        case "macpp-preview:starfield": drawStarfield(in: &context, size: size)
        case "macpp-preview:dvd": drawDVD(in: &context, size: size)
        case "macpp-preview:boids": drawBoids(in: &context, size: size)
        case "macpp-preview:plasma": drawPlasma(in: &context, size: size)
        case "macpp-preview:bonsai": drawBonsai(in: &context, size: size)
        default: drawConstellation(in: &context, size: size)
        }
    }

    private func color(_ index: Int, opacity: Double = 1) -> Color {
        let normalized = ((index % palette.count) + palette.count) % palette.count
        return palette[normalized].opacity(opacity)
    }

    private func value(_ index: Int, salt: Int = 0) -> CGFloat {
        let raw = macppPositiveModulo(seed &+ index &* 37 &+ salt &* 17, 1000)
        return CGFloat(raw) / 1000
    }

    private func drawMatrix(in context: inout GraphicsContext, size: CGSize) {
        let columns = max(18, Int(size.width / 8))
        let rows = max(10, Int(size.height / 8))
        for column in 0..<columns {
            let x = (CGFloat(column) + 0.5) * size.width / CGFloat(columns)
            let head = (seed &+ column &* 13) % rows
            var trail = Path()
            trail.move(to: CGPoint(x: x, y: 0))
            trail.addLine(to: CGPoint(x: x, y: size.height))
            context.stroke(trail, with: .color(Theme.accent.opacity(0.05)), lineWidth: 0.7)
            for row in 0..<rows {
                guard (row + column + seed) % 3 != 1 else { continue }
                let y = (CGFloat(row) + 0.5) * size.height / CGFloat(rows)
                let distance = (row - head + rows) % rows
                let opacity = max(0.10, 0.72 - Double(distance) * 0.065)
                let rect = CGRect(x: x, y: y, width: 2.2, height: 4.8)
                context.fill(Path(roundedRect: rect, cornerRadius: 1), with: .color(Theme.accent.opacity(opacity)))
            }
        }
    }

    private func drawWaveform(in context: inout GraphicsContext, size: CGSize) {
        for layer in 0..<3 {
            var path = Path()
            let amplitude = size.height * (0.12 + CGFloat(layer) * 0.025)
            let center = size.height * (0.38 + CGFloat(layer) * 0.11)
            for step in 0...54 {
                let fraction = CGFloat(step) / 54
                let x = fraction * size.width
                let angle = fraction * 2 * .pi * (1.25 + CGFloat(layer) * 0.22)
                    + CGFloat(seed % 23) * 0.04
                let y = center + sin(angle) * amplitude
                if step == 0 { path.move(to: CGPoint(x: x, y: y)) }
                else { path.addLine(to: CGPoint(x: x, y: y)) }
            }
            context.stroke(
                path,
                with: .color(color(layer, opacity: active ? 0.84 : 0.54)),
                style: StrokeStyle(lineWidth: 1.5, lineCap: .round, lineJoin: .round)
            )
        }
    }

    private func constellationPoints(size: CGSize) -> [CGPoint] {
        (0..<28).map { index in
            CGPoint(x: value(index, salt: 3) * size.width, y: value(index, salt: 9) * size.height)
        }
    }

    private func drawConstellation(in context: inout GraphicsContext, size: CGSize) {
        let points = constellationPoints(size: size)
        let threshold = min(size.width, size.height) * 0.34
        for first in points.indices {
            for second in (first + 1)..<points.count {
                let distance = hypot(points[first].x - points[second].x, points[first].y - points[second].y)
                guard distance < threshold else { continue }
                var path = Path()
                path.move(to: points[first])
                path.addLine(to: points[second])
                context.stroke(path, with: .color(Theme.ice.opacity(0.16)), lineWidth: 0.8)
            }
        }
        for (index, point) in points.enumerated() {
            let radius: CGFloat = index % 5 == 0 ? 3.2 : 2.0
            context.fill(
                Path(ellipseIn: CGRect(x: point.x - radius, y: point.y - radius, width: radius * 2, height: radius * 2)),
                with: .color(color(index, opacity: index % 5 == 0 ? 0.94 : 0.65))
            )
        }
    }

    private func drawRain(in context: inout GraphicsContext, size: CGSize) {
        let columns = max(18, Int(size.width / 9))
        for column in 0..<columns {
            let x = (CGFloat(column) + 0.5) * size.width / CGFloat(columns)
            let head = value(column, salt: 4) * size.height
            let length = size.height * (0.20 + value(column, salt: 7) * 0.55)
            var trail = Path()
            trail.move(to: CGPoint(x: x, y: head - length))
            trail.addLine(to: CGPoint(x: x, y: head))
            context.stroke(trail, with: .color(color(column, opacity: 0.22)), lineWidth: 1.1)
            context.fill(
                Path(ellipseIn: CGRect(x: x - 1.7, y: head - 1.7, width: 3.4, height: 3.4)),
                with: .color(Theme.bright.opacity(0.84))
            )
        }
    }

    private func drawParticles(in context: inout GraphicsContext, size: CGSize) {
        for index in 0..<72 {
            let point = CGPoint(x: value(index, salt: 5) * size.width, y: value(index, salt: 8) * size.height)
            let angle = sin(Double(index + seed) * 0.71) * .pi
            let length = 3 + value(index, salt: 11) * 10
            var path = Path()
            path.move(to: point)
            path.addLine(to: CGPoint(x: point.x + cos(angle) * length, y: point.y + sin(angle) * length))
            context.stroke(path, with: .color(color(index, opacity: 0.32 + Double(index % 4) * 0.10)), lineWidth: 1.1)
        }
    }

    private func drawPipes(in context: inout GraphicsContext, size: CGSize) {
        let rows = 5
        for index in 0..<rows {
            var path = Path()
            let y = size.height * (0.18 + CGFloat(index) * 0.16)
            path.move(to: CGPoint(x: size.width * 0.04, y: y))
            for turn in 0..<5 {
                let x = size.width * (0.16 + CGFloat(turn) * 0.18 + value(index * 7 + turn, salt: 2) * 0.05)
                let nextY = y + (turn.isMultiple(of: 2) ? -1 : 1) * size.height * 0.09
                path.addLine(to: CGPoint(x: x, y: y))
                path.addLine(to: CGPoint(x: x, y: nextY))
            }
            path.addLine(to: CGPoint(x: size.width * 0.96, y: y))
            context.stroke(path, with: .color(color(index, opacity: 0.72)), style: StrokeStyle(lineWidth: 2.3, lineCap: .round, lineJoin: .round))
        }
    }

    private func drawMaze(in context: inout GraphicsContext, size: CGSize) {
        let columns = 13
        let rows = 7
        let cellWidth = size.width / CGFloat(columns)
        let cellHeight = size.height / CGFloat(rows)
        for row in 0..<rows {
            for column in 0..<columns {
                let x = CGFloat(column) * cellWidth
                let y = CGFloat(row) * cellHeight
                if column < columns - 1 && (seed + row * 13 + column * 7) % 3 != 0 {
                    var path = Path()
                    path.move(to: CGPoint(x: x + cellWidth, y: y))
                    path.addLine(to: CGPoint(x: x + cellWidth, y: y + cellHeight * 0.58))
                    context.stroke(path, with: .color(Theme.ice.opacity(0.45)), lineWidth: 1)
                }
                if row < rows - 1 && (seed + row * 5 + column * 17) % 4 != 1 {
                    var path = Path()
                    path.move(to: CGPoint(x: x, y: y + cellHeight))
                    path.addLine(to: CGPoint(x: x + cellWidth * 0.63, y: y + cellHeight))
                    context.stroke(path, with: .color(Theme.accent.opacity(0.50)), lineWidth: 1)
                }
            }
        }
    }

    private func drawLife(in context: inout GraphicsContext, size: CGSize) {
        let columns = 19
        let rows = 9
        let cellWidth = size.width / CGFloat(columns)
        let cellHeight = size.height / CGFloat(rows)
        for row in 0..<rows {
            for column in 0..<columns {
                let alive = (seed + row * 19 + column * 11 + row * column) % 7 < 3
                guard alive else { continue }
                let rect = CGRect(
                    x: CGFloat(column) * cellWidth + 1,
                    y: CGFloat(row) * cellHeight + 1,
                    width: max(2, cellWidth - 2),
                    height: max(2, cellHeight - 2)
                )
                context.fill(Path(roundedRect: rect, cornerRadius: 1.5), with: .color(color(row + column, opacity: 0.72)))
            }
        }
    }

    private func drawClock(in context: inout GraphicsContext, size: CGSize) {
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        let radius = min(size.width, size.height) * 0.28
        context.stroke(Path(ellipseIn: CGRect(x: center.x - radius, y: center.y - radius, width: radius * 2, height: radius * 2)), with: .color(Theme.ice.opacity(0.38)), lineWidth: 1)
        for tick in 0..<12 {
            let angle = CGFloat(tick) / 12 * 2 * .pi
            let inner = radius * 0.82
            let outer = radius * 0.98
            var path = Path()
            path.move(to: CGPoint(x: center.x + cos(angle) * inner, y: center.y + sin(angle) * inner))
            path.addLine(to: CGPoint(x: center.x + cos(angle) * outer, y: center.y + sin(angle) * outer))
            context.stroke(path, with: .color(Theme.bright.opacity(0.60)), lineWidth: tick.isMultiple(of: 3) ? 1.5 : 0.8)
        }
    }

    private func drawOrrery(in context: inout GraphicsContext, size: CGSize) {
        let center = CGPoint(x: size.width * 0.50, y: size.height * 0.52)
        let radii: [CGFloat] = [0.15, 0.25, 0.35, 0.45].map { min(size.width, size.height) * $0 }
        for (index, radius) in radii.enumerated() {
            context.stroke(Path(ellipseIn: CGRect(x: center.x - radius, y: center.y - radius * 0.58, width: radius * 2, height: radius * 1.16)), with: .color(Theme.ice.opacity(0.24)), lineWidth: 0.8)
            let angle = CGFloat(value(index, salt: 14)) * 2 * .pi
            let point = CGPoint(x: center.x + cos(angle) * radius, y: center.y + sin(angle) * radius * 0.58)
            let planetRadius = 2.5 + CGFloat(index % 2)
            context.fill(Path(ellipseIn: CGRect(x: point.x - planetRadius, y: point.y - planetRadius, width: planetRadius * 2, height: planetRadius * 2)), with: .color(color(index + 1, opacity: 0.82)))
        }
        let sunRadius = min(size.width, size.height) * 0.07
        context.fill(Path(ellipseIn: CGRect(x: center.x - sunRadius, y: center.y - sunRadius, width: sunRadius * 2, height: sunRadius * 2)), with: .color(Theme.bright.opacity(0.92)))
    }

    private func drawStarfield(in context: inout GraphicsContext, size: CGSize) {
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        for index in 0..<48 {
            let angle = CGFloat(value(index, salt: 16)) * 2 * .pi
            let distance = min(size.width, size.height) * (0.08 + value(index, salt: 21) * 0.47)
            let point = CGPoint(x: center.x + cos(angle) * distance, y: center.y + sin(angle) * distance)
            let tail = distance * 0.18
            var path = Path()
            path.move(to: CGPoint(x: center.x + cos(angle) * max(0, distance - tail), y: center.y + sin(angle) * max(0, distance - tail)))
            path.addLine(to: point)
            context.stroke(path, with: .color(color(index, opacity: 0.28 + Double(index % 4) * 0.13)), lineWidth: index % 5 == 0 ? 1.7 : 0.9)
        }
        context.fill(Path(ellipseIn: CGRect(x: center.x - 2, y: center.y - 2, width: 4, height: 4)), with: .color(Theme.bright.opacity(0.84)))
    }

    private func drawDVD(in context: inout GraphicsContext, size: CGSize) {
        let x = size.width * 0.28
        let y = size.height * 0.25
        let width = size.width * 0.36
        let height = size.height * 0.24
        let rect = CGRect(x: x, y: y, width: width, height: height)
        context.stroke(Path(roundedRect: rect, cornerRadius: 6), with: .color(Theme.accent.opacity(0.36)), lineWidth: 1)
        var trail = Path()
        trail.move(to: CGPoint(x: x - size.width * 0.15, y: y + height * 0.62))
        trail.addLine(to: CGPoint(x: x + width * 0.15, y: y + height * 0.62))
        context.stroke(trail, with: .color(Theme.ice.opacity(0.20)), lineWidth: 1)
    }

    private func drawBoids(in context: inout GraphicsContext, size: CGSize) {
        for index in 0..<22 {
            let point = CGPoint(x: value(index, salt: 23) * size.width, y: value(index, salt: 29) * size.height)
            let angle = CGFloat(value(index, salt: 31)) * 2 * .pi
            let length: CGFloat = 8
            let left = CGPoint(x: point.x + cos(angle + 2.55) * length, y: point.y + sin(angle + 2.55) * length)
            let right = CGPoint(x: point.x + cos(angle - 2.55) * length, y: point.y + sin(angle - 2.55) * length)
            var triangle = Path()
            triangle.move(to: point)
            triangle.addLine(to: left)
            triangle.addLine(to: right)
            triangle.closeSubpath()
            context.fill(triangle, with: .color(color(index, opacity: 0.72)))
            var trail = Path()
            trail.move(to: CGPoint(x: point.x - cos(angle) * 18, y: point.y - sin(angle) * 18))
            trail.addLine(to: point)
            context.stroke(trail, with: .color(Theme.ice.opacity(0.15)), lineWidth: 0.8)
        }
    }

    private func drawPlasma(in context: inout GraphicsContext, size: CGSize) {
        for index in 0..<9 {
            let width = size.width * (0.24 + value(index, salt: 37) * 0.30)
            let height = size.height * (0.26 + value(index, salt: 41) * 0.25)
            let x = value(index, salt: 43) * (size.width - width)
            let y = value(index, salt: 47) * (size.height - height)
            let rect = CGRect(x: x, y: y, width: width, height: height)
            context.fill(Path(ellipseIn: rect), with: .color(color(index, opacity: 0.14 + Double(index % 3) * 0.04)))
        }
        for index in 0..<4 {
            var path = Path()
            for step in 0...32 {
                let fraction = CGFloat(step) / 32
                let x = fraction * size.width
                let y = size.height * (0.20 + CGFloat(index) * 0.20)
                    + sin(fraction * 2 * .pi * 1.7 + CGFloat(index)) * size.height * 0.12
                if step == 0 { path.move(to: CGPoint(x: x, y: y)) }
                else { path.addLine(to: CGPoint(x: x, y: y)) }
            }
            context.stroke(path, with: .color(color(index + 1, opacity: 0.30)), lineWidth: 1.2)
        }
    }

    private func drawBonsai(in context: inout GraphicsContext, size: CGSize) {
        let base = CGPoint(x: size.width * 0.51, y: size.height * 0.83)
        var pot = Path()
        pot.move(to: CGPoint(x: size.width * 0.34, y: size.height * 0.82))
        pot.addLine(to: CGPoint(x: size.width * 0.68, y: size.height * 0.82))
        pot.addLine(to: CGPoint(x: size.width * 0.62, y: size.height * 0.96))
        pot.addLine(to: CGPoint(x: size.width * 0.40, y: size.height * 0.96))
        pot.closeSubpath()
        context.fill(pot, with: .color(Theme.accent.opacity(0.42)))

        var trunk = Path()
        trunk.move(to: base)
        trunk.addCurve(to: CGPoint(x: size.width * 0.48, y: size.height * 0.28), control1: CGPoint(x: size.width * 0.40, y: size.height * 0.66), control2: CGPoint(x: size.width * 0.57, y: size.height * 0.49))
        context.stroke(trunk, with: .color(Theme.ice.opacity(0.82)), lineWidth: 3)
        for index in 0..<7 {
            let start = CGPoint(x: size.width * (0.46 + CGFloat(index % 3) * 0.025), y: size.height * (0.32 + CGFloat(index) * 0.065))
            let end = CGPoint(x: size.width * (0.22 + CGFloat(index % 4) * 0.17), y: start.y - size.height * (0.11 + CGFloat(index % 2) * 0.05))
            var branch = Path()
            branch.move(to: start)
            branch.addCurve(to: end, control1: CGPoint(x: start.x - 10, y: start.y - 12), control2: CGPoint(x: end.x + 12, y: end.y + 10))
            context.stroke(branch, with: .color(Theme.ice.opacity(0.62)), lineWidth: 1.5)
            context.fill(Path(ellipseIn: CGRect(x: end.x - 13, y: end.y - 5, width: 26, height: 10)), with: .color(color(index + 2, opacity: 0.55)))
        }
    }
}

/// A bounded, terminal-shaped still frame for the screen-saver picker.
///
/// Mac++ is rendered as ANSI text in the real saver, so a fixed ASCII grid is
/// a closer preview than a set of unrelated vector illustrations. It also
/// avoids asking SwiftUI's Canvas/text stack to lay out a large collection of
/// animated paths while the carousel is being resized. All preview glyphs are
/// deliberately plain ASCII: a missing font glyph must never turn into a
/// replacement-character artifact in the picker.
private struct MacPlusPlusScreensaverTerminalArtwork: View {
    let scene: String
    let active: Bool

    private let columns = 48
    private let rows = 14

    private var seed: Int {
        scene.utf8.reduce(17) { ($0 &* 31) &+ Int($1) }
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            LinearGradient(
                colors: [
                    Theme.frame.opacity(0.56),
                    Theme.surface.opacity(0.20),
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )

            VStack(alignment: .leading, spacing: 0) {
                ForEach(Array(lines.enumerated()), id: \.offset) { entry in
                    Text(entry.element)
                        .font(.system(
                            size: 8,
                            weight: entry.offset == 0 ? .semibold : .regular,
                            design: .monospaced
                        ))
                        .foregroundStyle(
                            entry.offset == 0
                                ? Theme.bright.opacity(active ? 0.86 : 0.54)
                                : Theme.accent.opacity(active ? 0.82 : 0.50)
                        )
                        .lineLimit(1)
                        .minimumScaleFactor(0.55)
                        .allowsTightening(true)
                }
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 12)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .opacity(active ? 1 : 0.78)
        .clipped()
    }

    private var lines: [String] {
        var grid = Array(
            repeating: Array(repeating: Character(" "), count: columns),
            count: rows
        )

        switch scene {
        case "cmatrix":
            drawStreams(
                in: &grid,
                glyphs: Array("01[]{}<>+*/"),
                stride: 2,
                length: 8
            )
        case "macpp-preview:waveform":
            drawWaveform(in: &grid)
        case "macpp-preview:constellation":
            drawConstellation(in: &grid)
        case "macpp-preview:rain":
            drawStreams(
                in: &grid,
                glyphs: Array("|:/\\"),
                stride: 3,
                length: 7
            )
        case "macpp-preview:particles":
            drawParticles(in: &grid)
        case "macpp-preview:pipes":
            drawPipes(in: &grid)
        case "macpp-preview:maze":
            drawMaze(in: &grid)
        case "macpp-preview:life":
            drawLife(in: &grid)
        case "macpp-preview:clock":
            drawClock(in: &grid)
        case "macpp-preview:orrery":
            drawOrrery(in: &grid)
        case "macpp-preview:starfield":
            drawStarfield(in: &grid)
        case "macpp-preview:dvd":
            drawDVD(in: &grid)
        case "macpp-preview:boids":
            drawBoids(in: &grid)
        case "macpp-preview:plasma":
            drawPlasma(in: &grid)
        case "macpp-preview:bonsai":
            drawBonsai(in: &grid)
        case "macpp-preview:aurora":
            drawAurora(in: &grid)
        case "macpp-preview:skyline":
            drawSkyline(in: &grid)
        case "macpp-preview:netpulse":
            drawNetpulse(in: &grid)
        case "macpp-preview:warp":
            drawWarp(in: &grid)
        case "macpp-preview:aquarium":
            drawAquarium(in: &grid)
        case "macpp-preview:fireflies":
            drawFireflies(in: &grid)
        case "macpp-preview:terrain":
            drawTerrain(in: &grid)
        case "macpp-preview:kaleidoscope":
            drawKaleidoscope(in: &grid)
        case "macpp-preview:solar":
            drawSolar(in: &grid)
        case "macpp-preview:observatory":
            drawObservatory(in: &grid)
        case "macpp-preview:campfire":
            drawCampfire(in: &grid)
        case "macpp-preview:synthwave":
            drawSynthwave(in: &grid)
        case "macpp-preview:music":
            drawMusic(in: &grid)
        case "macpp-preview:voidstorm":
            drawVoidstorm(in: &grid)
        case "macpp-preview:orbitalforge":
            drawOrbitalForge(in: &grid)
        case "macpp-preview:abyssalrelay":
            drawAbyssalRelay(in: &grid)
        case "macpp-preview:datacathedral":
            drawDataCathedral(in: &grid)
        case "macpp-preview:odyssey":
            drawOdyssey(in: &grid)
        case "macpp-preview:crimsonorbit":
            drawCrimsonOrbit(in: &grid)
        case "macpp-preview:glassreef":
            drawAbyssalRelay(in: &grid)
        case "macpp-preview:clockwork":
            drawEventHorizon(in: &grid)
        case "macpp-preview:velvetvortex":
            drawVelvetVortex(in: &grid)
        case "macpp-preview:eventhorizon":
            drawEventHorizon(in: &grid)
        case "macpp-preview:signalcollapse":
            drawSignalCollapse(in: &grid)
        default:
            drawConstellation(in: &grid)
        }

        return grid.map { String($0) }
    }

    private func sample(_ index: Int) -> Double {
        let value = (seed &+ index &* 1_103_515_245 &+ 12_345) & 0x7fffffff
        return Double(value % 997) / 997.0
    }

    private func sampleInt(_ index: Int, below limit: Int) -> Int {
        guard limit > 0 else { return 0 }
        return min(limit - 1, Int(sample(index) * Double(limit)))
    }

    private func put(
        _ glyph: Character,
        x: Int,
        y: Int,
        in grid: inout [[Character]]
    ) {
        guard grid.indices.contains(y), grid[y].indices.contains(x) else { return }
        grid[y][x] = glyph
    }

    private func putText(
        _ text: String,
        centeredAtY y: Int,
        in grid: inout [[Character]]
    ) {
        let glyphs = Array(text)
        let start = max(0, (columns - glyphs.count) / 2)
        for (offset, glyph) in glyphs.enumerated() {
            put(glyph, x: start + offset, y: y, in: &grid)
        }
    }

    private func drawStreams(
        in grid: inout [[Character]],
        glyphs: [Character],
        stride: Int,
        length: Int
    ) {
        guard !glyphs.isEmpty else { return }
        for column in Swift.stride(from: 1, to: columns, by: max(1, stride)) {
            let head = sampleInt(column * 13 + 3, below: rows)
            let streamLength = max(3, length + sampleInt(column * 7, below: 5) - 2)
            for offset in 0..<streamLength {
                let row = (head - offset + rows * 2) % rows
                let glyph = glyphs[macppPositiveModulo(column + offset + seed, glyphs.count)]
                put(glyph, x: column, y: row, in: &grid)
            }
        }
    }

    private func drawWaveform(in grid: inout [[Character]]) {
        for x in 0..<columns {
            let phase = Double(x) * 0.34 + Double(seed % 19) * 0.18
            let center = rows / 2
            let first = center + Int((sin(phase) * 3.4).rounded())
            let second = center + Int((sin(phase * 0.63 + 1.1) * 2.0).rounded())
            put("~", x: x, y: first, in: &grid)
            put("-", x: x, y: second, in: &grid)
            if x % 5 == 0 { put(".", x: x, y: center, in: &grid) }
        }
    }

    private func drawConstellation(in grid: inout [[Character]]) {
        let points = (0..<18).map { index in
            (
                sampleInt(index * 3 + 2, below: columns),
                sampleInt(index * 3 + 5, below: rows)
            )
        }

        for index in points.indices {
            let next = (index + 1) % points.count
            drawLine(from: points[index], to: points[next], glyph: ".", in: &grid)
            if index.isMultiple(of: 4) {
                let jump = (index + 5) % points.count
                drawLine(from: points[index], to: points[jump], glyph: "-", in: &grid)
            }
        }
        for (index, point) in points.enumerated() {
            put(index.isMultiple(of: 4) ? "*" : "+", x: point.0, y: point.1, in: &grid)
        }
    }

    private func drawLine(
        from start: (Int, Int),
        to end: (Int, Int),
        glyph: Character,
        in grid: inout [[Character]]
    ) {
        let dx = end.0 - start.0
        let dy = end.1 - start.1
        let steps = max(abs(dx), abs(dy))
        guard steps > 0 else {
            put(glyph, x: start.0, y: start.1, in: &grid)
            return
        }
        for step in 0...steps {
            let fraction = Double(step) / Double(steps)
            let x = Int((Double(start.0) + Double(dx) * fraction).rounded())
            let y = Int((Double(start.1) + Double(dy) * fraction).rounded())
            put(glyph, x: x, y: y, in: &grid)
        }
    }

    private func drawParticles(in grid: inout [[Character]]) {
        for index in 0..<64 {
            let x = sampleInt(index * 5 + 1, below: columns)
            let y = sampleInt(index * 5 + 2, below: rows)
            let glyph: Character = index.isMultiple(of: 7) ? "*" : "."
            put(glyph, x: x, y: y, in: &grid)
            if index.isMultiple(of: 5) {
                put("-", x: min(columns - 1, x + 1), y: y, in: &grid)
            }
        }
    }

    private func drawPipes(in grid: inout [[Character]]) {
        for pipe in 0..<4 {
            var currentY = 1 + pipe * 3
            for x in 0..<columns {
                put("-", x: x, y: currentY, in: &grid)
                guard x > 2, x.isMultiple(of: 8) else { continue }
                let nextY = max(1, min(rows - 2, currentY + (pipe.isMultiple(of: 2) ? 2 : -2)))
                let low = min(currentY, nextY)
                let high = max(currentY, nextY)
                put("+", x: x, y: currentY, in: &grid)
                for y in low...high { put("|", x: x, y: y, in: &grid) }
                currentY = nextY
            }
        }
    }

    private func drawMaze(in grid: inout [[Character]]) {
        for y in Swift.stride(from: 1, to: rows - 1, by: 3) {
            for x in Swift.stride(from: 0, to: columns, by: 4) {
                put("+", x: x, y: y, in: &grid)
                if x + 1 < columns {
                    for fillX in (x + 1)..<min(columns, x + 4) {
                        if (fillX + y + seed) % 5 != 0 { put("-", x: fillX, y: y, in: &grid) }
                    }
                }
                if y + 1 < rows, (x + y + seed) % 4 != 1 {
                    put("|", x: x, y: y + 1, in: &grid)
                }
            }
        }
    }

    private func drawLife(in grid: inout [[Character]]) {
        for y in Swift.stride(from: 1, to: rows - 1, by: 2) {
            for x in Swift.stride(from: 1, to: columns - 1, by: 2) {
                if sample(x * 17 + y * 11) > 0.42 { put("#", x: x, y: y, in: &grid) }
            }
        }
    }

    private func drawClock(in grid: inout [[Character]]) {
        putText("+----------+", centeredAtY: 5, in: &grid)
        putText("|  12:34   |", centeredAtY: 6, in: &grid)
        putText("|  MAC++   |", centeredAtY: 7, in: &grid)
        putText("+----------+", centeredAtY: 8, in: &grid)
    }

    private func drawOrrery(in grid: inout [[Character]]) {
        let center = (columns / 2, rows / 2)
        for radius in [5, 10, 16] {
            for degree in Swift.stride(from: 0, to: 360, by: 18) {
                let angle = Double(degree) * Double.pi / 180
                let x = center.0 + Int((cos(angle) * Double(radius)).rounded())
                let y = center.1 + Int((sin(angle) * Double(radius) * 0.45).rounded())
                put(".", x: x, y: y, in: &grid)
            }
        }
        put("O", x: center.0, y: center.1, in: &grid)
        put("o", x: center.0 + 5, y: center.1, in: &grid)
        put("o", x: center.0 - 10, y: center.1 - 2, in: &grid)
        put("o", x: center.0 + 16, y: center.1 + 3, in: &grid)
    }

    private func drawStarfield(in grid: inout [[Character]]) {
        for index in 0..<70 {
            let x = sampleInt(index * 7 + 9, below: columns)
            let y = sampleInt(index * 7 + 13, below: rows)
            put(index.isMultiple(of: 9) ? "*" : ".", x: x, y: y, in: &grid)
        }
        put("+", x: columns / 2, y: rows / 2, in: &grid)
    }

    private func drawDVD(in grid: inout [[Character]]) {
        putText("[ PREVIEW ]", centeredAtY: 6, in: &grid)
        drawLine(from: (10, 10), to: (columns / 2 - 5, 7), glyph: ".", in: &grid)
        put("+", x: columns / 2 + 8, y: 6, in: &grid)
    }

    private func drawBoids(in grid: inout [[Character]]) {
        for index in 0..<24 {
            let x = sampleInt(index * 9 + 3, below: columns)
            let y = sampleInt(index * 9 + 4, below: rows)
            put(index.isMultiple(of: 3) ? ">" : "<", x: x, y: y, in: &grid)
            if x > 1 { put(".", x: x - 1, y: y, in: &grid) }
        }
    }

    private func drawPlasma(in grid: inout [[Character]]) {
        let glyphs = Array("~-=+")
        for x in 0..<columns {
            for band in 0..<4 {
                let phase = Double(x) * 0.28 + Double(band) * 0.9 + Double(seed % 17) * 0.1
                let y = rows / 2 + band - 2 + Int((sin(phase) * 2.0).rounded())
                put(
                    glyphs[macppPositiveModulo(x + band + seed, glyphs.count)],
                    x: x,
                    y: y,
                    in: &grid
                )
            }
        }
    }

    private func drawBonsai(in grid: inout [[Character]]) {
        let art = [
            "          /\\          ",
            "     /\\  /  \\  /\\     ",
            "    /  \\/    \\/  \\    ",
            "        \\  /          ",
            "         \\/           ",
            "         ||            ",
            "        /||\\           ",
            "      __||||__          ",
        ]
        for (row, line) in art.enumerated() {
            guard row + 2 < rows else { continue }
            putText(line, centeredAtY: row + 2, in: &grid)
        }
    }

    private func drawAurora(in grid: inout [[Character]]) {
        let glyphs = Array(" .:-=+*#%@")
        for x in 0..<columns {
            for layer in 0..<3 {
                let center = Double(rows) * (0.27 + Double(layer) * 0.12)
                    + sin(Double(x) * (0.22 + Double(layer) * 0.05) + Double(seed % 17)) * 1.8
                let y = Int(center.rounded())
                for offset in -1...1 {
                    let index = macppPositiveModulo(x * 3 + layer * 5 + seed + offset, glyphs.count)
                    put(glyphs[index], x: x, y: y + offset, in: &grid)
                }
            }
        }
        for index in 0..<28 {
            put(".", x: sampleInt(index * 7 + 4, below: columns), y: sampleInt(index * 5 + 2, below: max(1, rows - 4)), in: &grid)
        }
        putText("AURORA FIELD // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawSkyline(in grid: inout [[Character]]) {
        let horizon = max(3, rows - 4)
        var x = -1
        var building = 0
        while x < columns {
            let width = 4 + sampleInt(building * 7 + 2, below: 7)
            let top = max(1, horizon - 4 - sampleInt(building * 11 + 1, below: max(2, rows / 2)))
            for y in top..<horizon {
                put("#", x: x, y: y, in: &grid)
                if width > 2 {
                    for offset in 1..<(width - 1) where (offset + y + building) % 3 != 0 {
                        put(".", x: x + offset, y: y, in: &grid)
                    }
                }
            }
            if building.isMultiple(of: 3) { put("|", x: x + width / 2, y: max(0, top - 2), in: &grid) }
            building += 1
            x += width + 2
        }
        putText("o", centeredAtY: 2, in: &grid)
        putText("NIGHT GRID // MAC++", centeredAtY: rows - 2, in: &grid)
        for column in 0..<columns { put("=", x: column, y: horizon, in: &grid) }
    }

    private func drawNetpulse(in grid: inout [[Character]]) {
        let points = [
            (4, 4), (13, 2), (22, 4), (32, 2), (42, 4),
            (8, 8), (18, 7), (29, 8), (39, 7), (45, 9),
        ]
        let edges = [(0, 1), (1, 2), (2, 3), (3, 4), (0, 5), (1, 6), (2, 6), (2, 7), (3, 7), (4, 8), (7, 8), (8, 9), (5, 6), (6, 7)]
        for (start, end) in edges where points.indices.contains(start) && points.indices.contains(end) {
            drawLine(from: points[start], to: points[end], glyph: ".", in: &grid)
        }
        for (index, point) in points.enumerated() {
            put(index.isMultiple(of: 4) ? "@" : "o", x: point.0, y: point.1, in: &grid)
            if index.isMultiple(of: 4) { put("[", x: point.0 - 1, y: point.1, in: &grid); put("]", x: point.0 + 1, y: point.1, in: &grid) }
        }
        putText("NETPULSE // LIVE ROUTES", centeredAtY: rows - 3, in: &grid)
        putText("PACKETS FIND THEIR WAY", centeredAtY: rows - 2, in: &grid)
    }

    private func drawWarp(in grid: inout [[Character]]) {
        let center = (columns / 2, rows / 2)
        for index in 0..<42 {
            let angle = sample(index * 3 + 1) * Double.pi * 2
            let radius = 4 + sampleInt(index * 5 + 2, below: max(4, columns / 2))
            let x = center.0 + Int((cos(angle) * Double(radius)).rounded())
            let y = center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded())
            put(index.isMultiple(of: 7) ? "*" : ".", x: x, y: y, in: &grid)
        }
        put("@", x: center.0, y: center.1, in: &grid)
        putText("WARP TUNNEL // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawAquarium(in grid: inout [[Character]]) {
        let floor = max(5, rows - 4)
        for x in 0..<columns { put("~", x: x, y: 2 + (x % 3 == 0 ? 1 : 0), in: &grid) }
        for index in 0..<6 {
            let x = sampleInt(index * 9 + 2, below: columns)
            let y = 4 + sampleInt(index * 13 + 5, below: max(2, floor - 6))
            putText(index.isMultiple(of: 2) ? "><>" : "<><", centeredAtY: y, in: &grid)
            put("o", x: x, y: max(3, y - 2), in: &grid)
        }
        for x in Swift.stride(from: 3, to: columns, by: 8) {
            put("|", x: x, y: floor - 2, in: &grid)
            put("/", x: x + 1, y: floor - 3, in: &grid)
            put("\\", x: x - 1, y: floor - 4, in: &grid)
        }
        putText("TERMINAL AQUARIUM // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawFireflies(in grid: inout [[Character]]) {
        let ground = max(5, rows - 4)
        for index in 0..<32 {
            let x = sampleInt(index * 7 + 4, below: columns)
            let y = 2 + sampleInt(index * 11 + 8, below: max(2, ground - 3))
            put(index.isMultiple(of: 5) ? "*" : "+", x: x, y: y, in: &grid)
            put(".", x: x - 1, y: y, in: &grid)
        }
        for x in Swift.stride(from: 1, to: columns, by: 5) { put("|", x: x, y: ground - 1, in: &grid) }
        putText("FIREFLY GARDEN // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawTerrain(in grid: inout [[Character]]) {
        let horizon = max(4, rows / 2)
        for row in Swift.stride(from: horizon + 2, to: rows - 3, by: 2) {
            for x in 0..<columns where (x + row + seed) % 3 != 0 { put("-", x: x, y: row, in: &grid) }
        }
        for x in Swift.stride(from: 0, to: columns, by: 5) {
            drawLine(from: (columns / 2, horizon), to: (x, rows - 3), glyph: ".", in: &grid)
        }
        for layer in 0..<3 {
            var previous = (0, horizon - layer)
            for x in 1..<columns {
                let y = horizon - layer - Int((sin(Double(x) * 0.25 + Double(seed % 13)) * 2.4).rounded())
                drawLine(from: previous, to: (x, y), glyph: y < previous.1 ? "/" : y > previous.1 ? "\\" : "_", in: &grid)
                previous = (x, y)
            }
        }
        putText("TOPOGRAPHIC TERRAIN // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawKaleidoscope(in grid: inout [[Character]]) {
        let center = (columns / 2, rows / 2)
        for radius in [3, 6, 9, 12] where radius < columns / 2 {
            for degree in Swift.stride(from: 0, to: 360, by: 15) {
                let angle = Double(degree) * Double.pi / 180
                put(".", x: center.0 + Int((cos(angle) * Double(radius)).rounded()), y: center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded()), in: &grid)
            }
        }
        for index in 0..<12 {
            let angle = Double(index) * Double.pi / 6
            drawLine(from: center, to: (center.0 + Int((cos(angle) * 15).rounded()), center.1 + Int((sin(angle) * 15 * 0.42).rounded())), glyph: index.isMultiple(of: 2) ? "*" : ".", in: &grid)
        }
        put("@", x: center.0, y: center.1, in: &grid)
        putText("KALEIDOSCOPE // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawSolar(in grid: inout [[Character]]) {
        let center = (columns / 2, rows / 2)
        for radius in [3, 6, 9] where radius < columns / 2 {
            for degree in Swift.stride(from: 0, to: 360, by: 15) {
                let angle = Double(degree) * Double.pi / 180
                put("o", x: center.0 + Int((cos(angle) * Double(radius)).rounded()), y: center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded()), in: &grid)
            }
        }
        for index in 0..<20 {
            let angle = Double(index) * Double.pi / 10
            drawLine(from: center, to: (center.0 + Int((cos(angle) * 18).rounded()), center.1 + Int((sin(angle) * 18 * 0.42).rounded())), glyph: index.isMultiple(of: 3) ? "+" : ".", in: &grid)
        }
        put("@", x: center.0, y: center.1, in: &grid)
        putText("SOLAR FLARE // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawObservatory(in grid: inout [[Character]]) {
        let center = (columns * 2 / 5, rows / 2)
        for radius in [5, 9, 13] where radius < columns / 2 {
            for degree in Swift.stride(from: 0, to: 360, by: 15) {
                let angle = Double(degree) * Double.pi / 180
                put(".", x: center.0 + Int((cos(angle) * Double(radius)).rounded()), y: center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded()), in: &grid)
            }
        }
        drawLine(from: (center.0, center.1), to: (center.0 + 13, center.1 - 4), glyph: ".", in: &grid)
        put("+", x: center.0, y: center.1, in: &grid)
        putText("[OBSERVATORY]", centeredAtY: 2, in: &grid)
        putText("AZ 180  LOCK SCAN", centeredAtY: rows - 2, in: &grid)
    }

    private func drawCampfire(in grid: inout [[Character]]) {
        let ground = max(5, rows - 4)
        let art = [
            "        .        ",
            "       .:.       ",
            "      :*#:.      ",
            "     .#%@#:.     ",
            "       /\\        ",
            "      /  \\       ",
        ]
        for (offset, line) in art.enumerated() {
            putText(line, centeredAtY: ground - art.count + offset, in: &grid)
        }
        putText("DIGITAL CAMPFIRE // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawSynthwave(in grid: inout [[Character]]) {
        let horizon = max(4, rows / 2)
        for row in Swift.stride(from: horizon + 2, to: rows - 3, by: 2) {
            for x in 0..<columns { put("_", x: x, y: row, in: &grid) }
        }
        for x in Swift.stride(from: -columns, to: columns * 2, by: 7) {
            drawLine(from: (columns / 2, horizon), to: (x, rows - 3), glyph: x < columns / 2 ? "/" : "\\", in: &grid)
        }
        putText("====", centeredAtY: max(2, horizon - 4), in: &grid)
        putText("SYNTHWAVE GRID // MAC++", centeredAtY: rows - 2, in: &grid)
    }

    private func drawMusic(in grid: inout [[Character]]) {
        let floor = max(5, rows - 4)
        for index in 0..<24 {
            let height = 2 + sampleInt(index * 7 + 3, below: max(3, rows - 7))
            let x = min(columns - 1, index * max(1, columns / 24))
            for offset in 0..<height { put(offset == height - 1 ? "#" : "|", x: x, y: floor - offset, in: &grid) }
        }
        putText("MUSIC VISUALIZER // MAC++", centeredAtY: rows - 3, in: &grid)
        putText("LIVE AUDIO / BPM --", centeredAtY: rows - 2, in: &grid)
    }

    private func drawVoidstorm(in grid: inout [[Character]]) {
        let center = (columns / 2, rows / 2)
        let glyphs = Array(".:+*#%@")
        let radius = max(5, min(columns / 2 - 2, rows - 4))
        for ring in 0..<4 {
            let ringRadius = max(3, radius * (ring + 2) / 7)
            for degree in Swift.stride(from: 0, to: 360, by: 12) {
                let angle = Double(degree) * Double.pi / 180
                let x = center.0 + Int((cos(angle) * Double(ringRadius)).rounded())
                let y = center.1 + Int((sin(angle) * Double(ringRadius) * 0.42).rounded())
                put(glyphs[(degree / 12 + ring) % glyphs.count], x: x, y: y, in: &grid)
            }
        }
        for arm in 0..<6 {
            let angle = Double(arm) * Double.pi / 3
            drawLine(
                from: center,
                to: (
                    center.0 + Int((cos(angle) * Double(radius)).rounded()),
                    center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded())
                ),
                glyph: arm.isMultiple(of: 2) ? "*" : ".",
                in: &grid
            )
        }
        for index in 0..<26 {
            let angle = sample(index * 9 + 3) * Double.pi * 2
            let orbit = 4 + sampleInt(index * 13 + 7, below: max(5, radius - 2))
            put(
                index.isMultiple(of: 5) ? "#" : ".",
                x: center.0 + Int((cos(angle) * Double(orbit)).rounded()),
                y: center.1 + Int((sin(angle) * Double(orbit) * 0.42).rounded()),
                in: &grid
            )
        }
        put("<", x: center.0 - 1, y: center.1, in: &grid)
        put("@", x: center.0, y: center.1, in: &grid)
        put(">", x: center.0 + 1, y: center.1, in: &grid)
    }

    private func drawOdyssey(in grid: inout [[Character]]) {
        guard rows > 5, columns > 12 else { return }
        let planet = (columns * 3 / 4, rows / 2)
        for orbit in 0..<3 {
            let radiusX = max(5, columns / 7 + orbit * 3)
            let radiusY = max(2, rows / 5 + orbit)
            for degree in Swift.stride(from: 0, to: 360, by: 12) {
                let angle = Double(degree + orbit * 8) * Double.pi / 180
                let point = (
                    planet.0 + Int((cos(angle) * Double(radiusX)).rounded()),
                    planet.1 + Int((sin(angle) * Double(radiusY)).rounded())
                )
                put(orbit == 1 && degree.isMultiple(of: 48) ? "*" : ".", x: point.0, y: point.1, in: &grid)
            }
        }
        for index in 0..<30 {
            let x = sampleInt(index * 17 + 5, below: columns)
            let y = sampleInt(index * 23 + 7, below: rows)
            put(index.isMultiple(of: 7) ? "+" : ".", x: x, y: y, in: &grid)
        }
        drawLine(from: (2, rows - 3), to: (columns / 3, rows / 2), glyph: "-", in: &grid)
        put("<", x: max(0, columns / 3 - 1), y: rows / 2, in: &grid)
        put("O", x: planet.0, y: planet.1, in: &grid)
        putText("ODYSSEY // DEEP SPACE", centeredAtY: rows - 1, in: &grid)
    }

    private func drawCrimsonOrbit(in grid: inout [[Character]]) {
        guard rows > 5, columns > 12 else { return }
        let planet = (columns * 2 / 3, rows / 2)
        for orbit in 0..<4 {
            let radiusX = max(6, columns / 5 + orbit * 2)
            let radiusY = max(2, rows / 6 + orbit)
            for degree in Swift.stride(from: 0, to: 360, by: 10) {
                let angle = Double(degree) * Double.pi / 180
                let x = planet.0 + Int((cos(angle) * Double(radiusX)).rounded())
                let y = planet.1 + Int((sin(angle) * Double(radiusY)).rounded())
                put(orbit.isMultiple(of: 2) ? ":" : ".", x: x, y: y, in: &grid)
            }
        }
        for band in -2...2 {
            let width = max(2, 5 - abs(band))
            drawLine(
                from: (planet.0 - width, planet.1 + band),
                to: (planet.0 + width, planet.1 + band),
                glyph: band == 0 ? "=" : "-",
                in: &grid
            )
        }
        put("@", x: planet.0, y: planet.1, in: &grid)
        put("o", x: max(1, planet.0 - columns / 3), y: max(1, planet.1 - 3), in: &grid)
        putText("CRIMSON ORBIT", centeredAtY: rows - 1, in: &grid)
    }

    private func drawVelvetVortex(in grid: inout [[Character]]) {
        guard rows > 5, columns > 12 else { return }
        let center = (columns / 2, rows / 2)
        let arms = 3
        for arm in 0..<arms {
            for step in 0..<90 {
                let fraction = Double(step) / 89
                let radius = (1 - fraction) * Double(max(columns / 2 - 2, rows - 3))
                let angle = fraction * Double.pi * 5 + Double(arm) * Double.pi * 2 / Double(arms)
                let x = center.0 + Int((cos(angle) * radius).rounded())
                let y = center.1 + Int((sin(angle) * radius * 0.40).rounded())
                let glyph: Character = step.isMultiple(of: 9) ? "#" : (step.isMultiple(of: 3) ? "+" : ".")
                put(glyph, x: x, y: y, in: &grid)
            }
        }
        put("@", x: center.0, y: center.1, in: &grid)
        putText("VELVET VORTEX", centeredAtY: rows - 1, in: &grid)
    }

    private func drawEventHorizon(in grid: inout [[Character]]) {
        guard rows > 5, columns > 12 else { return }
        let center = (columns / 2, rows / 2 - 1)
        for ring in 0..<4 {
            let radiusX = max(5, columns / 8 + ring * 3)
            let radiusY = max(2, rows / 7 + ring)
            for degree in Swift.stride(from: 0, to: 360, by: 8) {
                let angle = Double(degree) * Double.pi / 180
                let x = center.0 + Int((cos(angle) * Double(radiusX)).rounded())
                let y = center.1 + Int((sin(angle) * Double(radiusY)).rounded())
                put(ring.isMultiple(of: 2) ? "." : ":", x: x, y: y, in: &grid)
            }
        }
        for band in -2...2 {
            drawLine(
                from: (0, center.1 + band),
                to: (columns - 1, center.1 + band),
                glyph: band == 0 ? "=" : "-",
                in: &grid
            )
        }
        put("@", x: center.0, y: center.1, in: &grid)
        putText("EVENT HORIZON", centeredAtY: rows - 1, in: &grid)
    }

    private func drawOrbitalForge(in grid: inout [[Character]]) {
        guard rows > 6, columns > 16 else { return }
        let centerX = columns / 2
        let centerY = max(5, rows * 2 / 5)
        let horizon = max(centerY + 4, rows * 11 / 20)
        let floor = rows - 2

        for index in 0..<max(36, columns / 3) {
            let x = sampleInt(index * 11 + 7, below: columns)
            let y = 1 + sampleInt(index * 13 + 9, below: max(1, horizon - 1))
            put(index.isMultiple(of: 13) ? "*" : ".", x: x, y: y, in: &grid)
        }
        for lane in -8...8 {
            drawLine(
                from: (centerX, horizon),
                to: (centerX + lane * max(3, columns / 8), floor),
                glyph: lane < 0 ? "╱" : "╲",
                in: &grid
            )
        }
        for band in 0..<8 {
            let y = horizon + (band + 1) * max(1, (floor - horizon) / 9)
            let halfWidth = max(3, band * max(2, columns / 12))
            drawLine(from: (centerX - halfWidth, y), to: (centerX + halfWidth, y), glyph: band.isMultiple(of: 3) ? "─" : "·", in: &grid)
        }

        let planetX = max(10, columns / 7)
        let planetY = min(floor - 1, rows * 3 / 4)
        let planetRadius = max(7, min(columns / 8, rows / 4))
        for degree in Swift.stride(from: 0, to: 360, by: 12) {
            let angle = Double(degree) * Double.pi / 180
            put("·", x: planetX + Int((cos(angle) * Double(planetRadius)).rounded()), y: planetY + Int((sin(angle) * Double(planetRadius) * 0.42).rounded()), in: &grid)
        }
        for band in -2...2 {
            let y = planetY + band
            let width = max(2, planetRadius - abs(band) * 2)
            drawLine(from: (planetX - width, y), to: (planetX + width, y), glyph: "·", in: &grid)
        }

        let ringRadius = max(7, min(columns / 4, rows / 2))
        for ring in 0..<3 {
            for degree in Swift.stride(from: 0, to: 360, by: 15) {
                let angle = Double(degree + ring * 9) * Double.pi / 180
                let radius = ringRadius - ring * 3
                let x = centerX + Int((cos(angle) * Double(radius)).rounded())
                let y = centerY + Int((sin(angle) * Double(radius) * 0.42).rounded())
                put(ring == 1 && degree.isMultiple(of: 45) ? "◆" : ".", x: x, y: y, in: &grid)
            }
        }

        let halfWidth = max(7, min(columns / 7, rows / 3))
        let halfHeight = max(3, rows / 9)
        let skew = max(2, columns / 24)
        let frontTopLeft = (centerX - halfWidth / 2, centerY - halfHeight)
        let frontTopRight = (centerX + halfWidth / 2, centerY - halfHeight)
        let frontBottomLeft = (centerX - halfWidth / 2, centerY + halfHeight)
        let frontBottomRight = (centerX + halfWidth / 2, centerY + halfHeight)
        let backTopLeft = (frontTopLeft.0 + skew, frontTopLeft.1 - 2)
        let backTopRight = (frontTopRight.0 + skew, frontTopRight.1 - 2)
        let backBottomLeft = (frontBottomLeft.0 + skew, frontBottomLeft.1 - 2)
        let backBottomRight = (frontBottomRight.0 + skew, frontBottomRight.1 - 2)
        for edge in [
            (frontTopLeft, frontTopRight), (frontTopRight, frontBottomRight),
            (frontBottomRight, frontBottomLeft), (frontBottomLeft, frontTopLeft),
            (backTopLeft, backTopRight), (backTopRight, backBottomRight),
            (backBottomRight, backBottomLeft), (backBottomLeft, backTopLeft),
            (frontTopLeft, backTopLeft), (frontTopRight, backTopRight),
            (frontBottomLeft, backBottomLeft), (frontBottomRight, backBottomRight)
        ] {
            drawLine(from: edge.0, to: edge.1, glyph: "─", in: &grid)
        }
        for row in 1...2 {
            let y = frontTopLeft.1 + row * max(1, (frontBottomLeft.1 - frontTopLeft.1) / 3)
            drawLine(from: (frontTopLeft.0 + 1, y), to: (frontTopRight.0 - 1, y), glyph: "·", in: &grid)
        }
        for column in 1...3 {
            let x = frontTopLeft.0 + column * max(1, (frontTopRight.0 - frontTopLeft.0) / 4)
            drawLine(from: (x, frontTopLeft.1 + 1), to: (x, frontBottomLeft.1 - 1), glyph: "·", in: &grid)
        }
        put("●", x: centerX - 2, y: centerY, in: &grid)
        put("●", x: centerX + 2, y: centerY, in: &grid)
        drawLine(from: (centerX, frontTopLeft.1), to: (centerX, max(1, frontTopLeft.1 - 5)), glyph: "│", in: &grid)
        put("*", x: centerX, y: max(1, frontTopLeft.1 - 5), in: &grid)

        drawLine(from: (frontTopLeft.0, centerY - 1), to: (frontTopLeft.0 - max(7, columns / 12), centerY - 3), glyph: "═", in: &grid)
        drawLine(from: (frontTopRight.0, centerY - 1), to: (frontTopRight.0 + max(7, columns / 12), centerY - 3), glyph: "═", in: &grid)
        for packet in 0..<5 {
            let x = centerX + (packet - 2) * max(2, columns / 16)
            put(packet.isMultiple(of: 2) ? "+" : ".", x: x, y: max(1, centerY - 1), in: &grid)
        }

        let miniX = min(columns - 8, max(centerX + 18, columns * 4 / 5))
        let miniY = max(3, rows / 5)
        drawLine(from: (miniX - 4, miniY - 2), to: (miniX + 4, miniY - 2), glyph: "─", in: &grid)
        drawLine(from: (miniX + 4, miniY - 2), to: (miniX + 4, miniY + 2), glyph: "│", in: &grid)
        drawLine(from: (miniX + 4, miniY + 2), to: (miniX - 4, miniY + 2), glyph: "─", in: &grid)
        drawLine(from: (miniX - 4, miniY + 2), to: (miniX - 4, miniY - 2), glyph: "│", in: &grid)
        put("+", x: miniX, y: miniY, in: &grid)
    }

    private func drawAbyssalRelay(in grid: inout [[Character]]) {
        guard rows > 6, columns > 16 else { return }
        let centerX = columns / 2
        let waterline = max(3, rows / 5)
        let horizon = max(waterline + 3, rows * 2 / 5)
        let seabed = max(horizon + 4, rows - 3)
        let stationRadius = max(7, min(columns / 6, rows / 2))
        let left = max(2, centerX - stationRadius)
        let right = min(columns - 3, centerX + stationRadius)
        let domeBase = max(horizon + 2, rows * 3 / 5)
        let domeHeight = max(2, rows / 8)
        let hullBottom = min(seabed - 1, domeBase + 5)

        for row in Swift.stride(from: waterline, to: horizon, by: 2) {
            for x in Swift.stride(from: row % 3, to: columns, by: 5) {
                put(x % 4 == 0 ? "~" : ".", x: x, y: row, in: &grid)
            }
        }

        putText("..---<==o==>---..", centeredAtY: max(2, waterline + 2), in: &grid)
        for school in 0..<4 {
            let y = waterline + 4 + (school * 3) % max(3, horizon - waterline - 1)
            let start = (school * 23 + seed * 3) % max(1, columns)
            for member in 0..<5 {
                put(school.isMultiple(of: 2) ? ">" : "<", x: start + member * 3, y: y, in: &grid)
            }
        }

        for x in 0..<columns {
            if x % 4 != 0 { put("_", x: x, y: seabed, in: &grid) }
        }
        for plant in 0..<max(5, columns / 24) {
            let baseX = min(columns - 1, (plant * columns) / max(1, columns / 24 + 1) + 2)
            if baseX > left - 3, baseX < right + 3 { continue }
            let height = 3 + sampleInt(plant * 13 + 5, below: max(3, rows / 5))
            for segment in 0..<height {
                let y = seabed - 1 - segment
                guard y > 0 else { continue }
                let sway = ((segment + plant + seed) % 3) - 1
                put("│", x: baseX + sway, y: y, in: &grid)
                if segment.isMultiple(of: 2) { put(segment.isMultiple(of: 4) ? ")" : "(", x: baseX + sway + (segment.isMultiple(of: 4) ? 1 : -1), y: y, in: &grid) }
            }
        }

        for step in 0...36 {
            let angle = Double.pi - Double(step) * Double.pi / 36.0
            let x = centerX + Int((cos(angle) * Double(right - left) * 0.5).rounded())
            let y = domeBase - Int((sin(angle) * Double(domeHeight)).rounded())
            put(step < 18 ? "/" : "\\", x: x, y: y, in: &grid)
        }
        for rib in 1...3 {
            let x = left + (right - left) * rib / 4
            drawLine(from: (x, domeBase - domeHeight / 2), to: (x, domeBase), glyph: "│", in: &grid)
        }
        drawLine(from: (left, domeBase), to: (right, domeBase), glyph: "─", in: &grid)
        drawLine(from: (left, hullBottom), to: (right, hullBottom), glyph: "═", in: &grid)
        for row in (domeBase + 1)..<hullBottom {
            put("│", x: left, y: row, in: &grid)
            put("│", x: right, y: row, in: &grid)
        }
        put("╭", x: left, y: domeBase, in: &grid)
        put("╮", x: right, y: domeBase, in: &grid)
        put("╰", x: left, y: hullBottom, in: &grid)
        put("╯", x: right, y: hullBottom, in: &grid)
        if right - left > 24 {
            putText("RELAY", centeredAtY: domeBase + 1, in: &grid)
        }
        for port in 0..<5 {
            let x = left + 4 + port * max(1, (right - left - 8) / 4)
            put(port.isMultiple(of: 2) ? "◉" : "○", x: x, y: min(hullBottom - 1, domeBase + 3), in: &grid)
        }
        drawLine(from: (centerX, domeBase - domeHeight), to: (centerX, max(1, domeBase - domeHeight - 4)), glyph: "│", in: &grid)
        put("✦", x: centerX, y: max(1, domeBase - domeHeight - 4), in: &grid)
        drawLine(from: (left, domeBase + 2), to: (max(1, left - 8), domeBase + 2), glyph: "═", in: &grid)
        drawLine(from: (right, domeBase + 2), to: (min(columns - 1, right + 8), domeBase + 2), glyph: "═", in: &grid)

        let scopeX = min(columns - 7, max(7, right + 7))
        let scopeY = max(horizon + 2, rows * 2 / 5)
        let scopeRadius = max(3, min(7, columns / 18))
        for degree in Swift.stride(from: 0, to: 360, by: 24) {
            let angle = Double(degree) * Double.pi / 180
            put("·", x: scopeX + Int((cos(angle) * Double(scopeRadius)).rounded()), y: scopeY + Int((sin(angle) * Double(scopeRadius) * 0.42).rounded()), in: &grid)
        }
        put("+", x: scopeX, y: scopeY, in: &grid)
        if scopeX + 4 < columns { putText("SONAR", centeredAtY: max(1, scopeY - 4), in: &grid) }
    }

    private func drawDataCathedral(in grid: inout [[Character]]) {
        guard rows > 4, columns > 8 else { return }
        let center = (columns / 2, max(3, rows / 2 - 1))
        let floor = rows - 2
        let horizon = max(4, rows / 2)
        let glyphs = Array(".:+*#%@")

        for side in [-1, 1] {
            for pillar in 0..<5 {
                let fraction = 0.10 + Double(pillar) * 0.085
                let x = side < 0
                    ? Int(Double(columns) * fraction)
                    : columns - 1 - Int(Double(columns) * fraction)
                let top = max(1, horizon - 3 - sampleInt(pillar * 11 + 4, below: 5))
                put("│", x: x, y: top, in: &grid)
                for row in (top + 1)...floor {
                    put("│", x: x, y: row, in: &grid)
                }
                let inner = x + (side < 0 ? 2 : -2)
                for row in (top + 2)...floor {
                    put("·", x: inner, y: row, in: &grid)
                }
                put("╥", x: x, y: top, in: &grid)
                for light in 0..<4 {
                    let row = top + 4 + light * 2
                    if row < floor {
                        put(light.isMultiple(of: 2) ? "◇" : "·", x: inner, y: row, in: &grid)
                    }
                }
            }
        }

        for lane in -5...5 {
            let endpoint = center.0 + lane * max(3, columns / 8)
            drawLine(
                from: (center.0, horizon),
                to: (endpoint, floor),
                glyph: lane < 0 ? "╱" : "╲",
                in: &grid
            )
        }
        for band in 0..<7 {
            let y = horizon + (band + 1) * max(1, (floor - horizon) / 8)
            drawLine(from: (center.0 - band * 3, y), to: (center.0 + band * 3, y), glyph: "_", in: &grid)
        }

        let roseRadius = max(4, min(columns / 4, rows - 5))
        for ring in 0..<3 {
            let radius = max(3, roseRadius * (ring + 2) / 7)
            for degree in Swift.stride(from: 0, to: 360, by: 15) {
                let angle = Double(degree) * Double.pi / 180
                let x = center.0 + Int((cos(angle) * Double(radius)).rounded())
                let y = center.1 + Int((sin(angle) * Double(radius) * 0.42).rounded())
                put(glyphs[(degree / 15 + ring) % glyphs.count], x: x, y: y, in: &grid)
            }
        }
        for spoke in 0..<8 {
            let angle = Double(spoke) * Double.pi / 4
            drawLine(
                from: center,
                to: (
                    center.0 + Int((cos(angle) * Double(roseRadius)).rounded()),
                    center.1 + Int((sin(angle) * Double(roseRadius) * 0.42).rounded())
                ),
                glyph: spoke.isMultiple(of: 2) ? "+" : ".",
                in: &grid
            )
        }
        for index in 0..<18 {
            let angle = sample(index * 7 + 3) * Double.pi * 2
            let orbit = 3 + sampleInt(index * 13 + 7, below: max(4, roseRadius - 1))
            put(
                index.isMultiple(of: 5) ? "#" : ".",
                x: center.0 + Int((cos(angle) * Double(orbit)).rounded()),
                y: center.1 + Int((sin(angle) * Double(orbit) * 0.42).rounded()),
                in: &grid
            )
        }
        put("<", x: center.0 - 1, y: center.1, in: &grid)
        put("◈", x: center.0, y: center.1, in: &grid)
        put(">", x: center.0 + 1, y: center.1, in: &grid)
        put("═", x: 0, y: floor, in: &grid)
        for x in 1..<columns {
            put("═", x: x, y: floor, in: &grid)
        }
    }

    private func drawSignalCollapse(in grid: inout [[Character]]) {
        guard rows > 1, columns > 0 else { return }
        let glyphs = Array("|/\\<>[]{}()=~:+*#%@")

        // Fill the complete card with distributed activity. Unlike the
        // reactor preview above, this intentionally has no centre coordinate
        // or focal radius: both side edges receive the same density.
        for y in 1..<rows {
            for x in 0..<columns {
                let signal = sample(x * 17 + y * 29 + 7)
                let interference = sample(x * 7 + y * 43 + 19)
                guard signal + interference * 0.46 > 0.68 else { continue }
                let index = sampleInt(x * 31 + y * 13 + 5, below: glyphs.count)
                put(glyphs[index], x: x, y: y, in: &grid)
            }
        }

        for column in Swift.stride(from: 0, to: columns, by: 2) {
            let head = sampleInt(column * 13 + 3, below: rows + 10) - 5
            let length = 4 + sampleInt(column * 7 + 11, below: 9)
            for offset in 0..<length {
                let y = head - offset
                guard y >= 1, y < rows else { continue }
                let index = sampleInt(column * 19 + y * 11 + offset, below: glyphs.count)
                put(glyphs[index], x: column, y: y, in: &grid)
            }
        }

        for band in 0..<max(5, rows / 9) {
            let y = 1 + sampleInt(band * 23 + 9, below: max(1, rows - 1))
            for x in 0..<columns where (x + band) % 3 != 0 {
                put(band.isMultiple(of: 3) ? "=" : "-", x: x, y: y, in: &grid)
            }
        }

        for burst in 0..<max(8, columns / 36) {
            let length = 7 + sampleInt(burst * 29 + 3, below: 14)
            let start = sampleInt(burst * 31 + 7, below: max(1, columns + length)) - length / 2
            let row = 1 + sampleInt(burst * 37 + 5, below: max(1, rows - 1))
            let slope = burst.isMultiple(of: 2) ? 1 : -1
            for offset in 0..<length {
                let x = start + offset
                let y = row + slope * offset
                guard x >= 0, x < columns, y >= 1, y < rows else { continue }
                put(offset.isMultiple(of: 4) ? "#" : "/", x: x, y: y, in: &grid)
            }
        }

        let railY = max(1, rows - 2)
        for x in 0..<columns where x % 4 != 0 {
            put(x % 3 == 0 ? "." : "_", x: x, y: railY, in: &grid)
        }
    }
}

private struct MacPlusPlusMetricsTrendView: View {
    let points: [MacPlusPlusMetricsTrendPoint]

    private func trendPath(_ values: [Double], size: CGSize) -> Path {
        var path = Path()
        guard values.count > 1, size.width > 0, size.height > 0 else { return path }
        for (index, value) in values.enumerated() {
            let x = size.width * CGFloat(index) / CGFloat(values.count - 1)
            let y = size.height * (1 - CGFloat(min(100, max(0, value))) / 100)
            if index == 0 { path.move(to: CGPoint(x: x, y: y)) }
            else { path.addLine(to: CGPoint(x: x, y: y)) }
        }
        return path
    }

    // The three history traces were once near-identical faint lines with no
    // key. Keep a compact legend so CPU, memory, and GPU remain readable in
    // the small plot without relying on color inference.
    private static let legendEntries: [(String, Color)] = [
        ("CPU", Theme.accent), ("MEM", Theme.ice), ("GPU", Theme.mint),
    ]

    var body: some View {
        GeometryReader { geometry in
            let axisWidth: CGFloat = 22
            let legendHeight: CGFloat = 13
            let plotSize = CGSize(
                width: max(1, geometry.size.width - axisWidth - 2),
                height: max(1, geometry.size.height - legendHeight - 2)
            )

            ZStack(alignment: .topLeading) {
                // Keep the scale outside the plot so no trace can run beneath
                // an axis label. The chart remains normalized to 0–100%, so
                // these labels stay correct as the live values change.
                VStack(spacing: Spacing.none) {
                    Text("100%")
                    Spacer(minLength: 0)
                    Text("50%")
                    Spacer(minLength: 0)
                    Text("0%")
                }
                .font(.system(size: ShellTypography.nano, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                .foregroundStyle(Theme.muted)
                .frame(width: axisWidth, height: plotSize.height, alignment: .leading)
                .offset(y: legendHeight)

                ZStack {
                    VStack(spacing: Spacing.none) {
                        ForEach(0..<3, id: \.self) { index in
                            Capsule(style: .continuous)
                                .fill(Theme.seam.opacity(index == 2 ? 0 : 0.18))
                                .frame(height: index == 2 ? 0 : 0.5)
                            if index < 2 { Spacer() }
                        }
                    }
                    trendPath(points.map(\.memory), size: plotSize)
                        .stroke(Theme.ice.opacity(0.85), style: StrokeStyle(lineWidth: 1.4, lineCap: .round, lineJoin: .round))
                    trendPath(points.map { $0.gpu ?? 0 }, size: plotSize)
                        .stroke(Theme.mint.opacity(0.85), style: StrokeStyle(lineWidth: 1.4, lineCap: .round, lineJoin: .round))
                    trendPath(points.map(\.cpu), size: plotSize)
                        .stroke(Theme.accent, style: StrokeStyle(lineWidth: 1.6, lineCap: .round, lineJoin: .round))
                }
                .frame(width: plotSize.width, height: plotSize.height)
                .offset(x: axisWidth, y: legendHeight)

                // The legend now owns its own band above the plot rather than
                // competing with the first few samples for the same pixels.
                HStack(spacing: Spacing.snug) {
                    ForEach(Self.legendEntries, id: \.0) { label, color in
                        HStack(spacing: Spacing.hairline) {
                            Circle().fill(color).frame(width: 4, height: 4)
                            Text(label)
                                .font(.system(size: ShellTypography.nano, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                                .foregroundStyle(Theme.muted)
                        }
                    }
                }
                .padding(.horizontal, Spacing.tight).padding(.vertical, Spacing.hairline)
                .background(Theme.frame.opacity(0.55), in: Capsule())
                .frame(maxWidth: .infinity, alignment: .trailing)
            }
        }
        .accessibilityLabel("Six hour CPU, memory, and GPU history")
    }
}

private struct MacPlusPlusVisualizerOption: Identifiable, Equatable {
    let id: String
    let title: String
    let detail: String
    let symbol: String

    static let all: [MacPlusPlusVisualizerOption] = [
        MacPlusPlusVisualizerOption(
            id: "bars-compact",
