/// Keeps the high-frequency audio subscription on the focused card only.
/// Inactive carousel thumbnails use `MacPlusPlusVisualizerPreview` directly,
/// so changing the spectrum cannot invalidate all of their Canvas trees.
private struct MacPlusPlusLiveVisualizerPreview: View {
    let style: String
    @ObservedObject var shell: ShellModel

    var body: some View {
        MacPlusPlusVisualizerPreview(
            style: style,
            active: true,
            levels: shell.levels
        )
    }
}

private struct MacPlusPlusVisualizerPreview: View {
    let style: String
    let active: Bool
    // The focused card follows the same normalized spectrum that feeds the
    // desktop Metal layer. Inactive neighbours intentionally receive no
    // live feed so browsing remains cheap; their deterministic fallback still
    // communicates the authored geometry without starting another renderer.
    var levels: [Double] = []

    var body: some View {
        Group {
            if active {
                TimelineView(.animation(minimumInterval: 1.0 / 30.0)) { timeline in
                    previewSurface(time: timeline.date.timeIntervalSinceReferenceDate)
                }
            } else {
                // Offscreen carousel cards keep their authored geometry but do
                // not own a display-linked timeline. Only the focused card
                // needs to animate while the user is browsing.
                previewSurface(time: 0)
            }
        }
        .clipped()
    }

    @ViewBuilder
    private func previewSurface(time: Double) -> some View {
        ZStack {
            LinearGradient(
                colors: [
                    Theme.surface.opacity(0.82),
                    Theme.frame.opacity(0.50),
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            previewGraphic(time: time)
        }
        .overlay(
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(Theme.bright.opacity(0.08), lineWidth: 1)
        )
    }

    @ViewBuilder
    private func previewGraphic(time: Double) -> some View {
        switch style {
        case "ring", "ring-color":
            Canvas { context, size in
                let colorRing = style == "ring-color"
                // Match the full-desktop shader's centered ring and safe
                // reach budget. The old preview used a low center and a much
                // larger radius, so its spokes were clipped differently from
                // the visualizer actually painted over the wallpaper.
                let center = CGPoint(x: size.width / 2, y: size.height / 2)
                let safeRadius = min(size.width, size.height) * 0.48 / 1.57
                let ringRadius = min(safeRadius, safeRadius / 1.36)
                let innerRadius = ringRadius * 0.42
                // Only the focused card needs the full renderer. Neighbours
                // still retain the same ring geometry, but fewer spokes keep
                // the carousel's initial layout cheap while they are offscreen.
                let spokeCount = active ? 72 : 24
                for index in 0..<spokeCount {
                    let fraction = Double(index) / Double(spokeCount)
                    let angle = fraction * 2 * Double.pi + time * 0.12
                    let energy = spectrumEnergy(at: 1.0 - abs(fraction * 2.0 - 1.0))
                        ?? (0.25 + 0.7 * abs(sin(fraction * 9.0 + time * 0.6)))
                    let spokeLength = ringRadius * (0.20 + energy * 0.95)
                    let length = innerRadius + spokeLength
                    let start = CGPoint(
                        x: center.x + CGFloat(cos(angle)) * innerRadius,
                        y: center.y + CGFloat(sin(angle)) * innerRadius
                    )
                    let end = CGPoint(
                        x: center.x + CGFloat(cos(angle)) * length,
                        y: center.y + CGFloat(sin(angle)) * length
                    )
                    var spoke = Path()
                    spoke.move(to: start)
                    spoke.addLine(to: end)
                    let volume = max(0, min(1, (energy - 0.25) / 0.7))
                    let shading: GraphicsContext.Shading = .linearGradient(
                        Gradient(colors: colorRing
                            ? [
                                Theme.accent.opacity(0.38 + volume * 0.24),
                                Theme.bright.opacity(0.70 + volume * 0.22),
                            ]
                            : [
                                Theme.bright.opacity(0.55 + volume * 0.12),
                                Theme.bright.opacity(0.82 + volume * 0.10),
                            ]),
                        startPoint: start,
                        endPoint: end
                    )
                    context.stroke(
                        spoke,
                        with: shading,
                        style: StrokeStyle(lineWidth: 1.5, lineCap: .round)
                    )
                }
                let trackRadius = innerRadius + ringRadius * 0.20
                context.stroke(
                    Path(ellipseIn: CGRect(
                        x: center.x - trackRadius, y: center.y - trackRadius,
                        width: trackRadius * 2, height: trackRadius * 2
                    )),
                    with: .color((colorRing ? Theme.accent : Theme.bright).opacity(0.30)),
                    lineWidth: 1
                )
                context.stroke(
                    Path(ellipseIn: CGRect(
                        x: center.x - innerRadius, y: center.y - innerRadius,
                        width: innerRadius * 2, height: innerRadius * 2
                    )),
                    with: .color((colorRing ? Theme.accent : Theme.bright).opacity(0.30)),
                    lineWidth: 1
                )
                context.fill(
                    Path(ellipseIn: CGRect(
                        x: center.x - innerRadius * 0.78,
                        y: center.y - innerRadius * 0.78,
                        width: innerRadius * 1.56,
                        height: innerRadius * 1.56
                    )),
                    with: .color((colorRing ? Theme.accent : Theme.bright).opacity(0.13))
                )
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        case "grid":
            Canvas { context, size in
                // The renderer uses 48+ columns and 20 segments in full
                // desktop mode. Keep the same dense ladder in the card so the
                // preview does not look like the old six-rung widget.
                // Hidden carousel duplicates are thumbnails, not the desktop
                // layer itself. Keep their proportions and colour ramp while
                // using a small static ladder; otherwise ten Canvas cards all
                // build hundreds of paths during the initial morph.
                let columnCount = active ? 48 : 20
                let segmentCount = active ? 20 : 8
                // Full-desktop shader geometry leaves a nine-point bottom
                // reserve before the transparent layer meets the wallpaper.
                let groundY = size.height - 9
                // Match desktopLayerFragment's full-desktop reserve. Using a
                // taller preview stack made the thumbnail look like a
                // different visualiser and could paint into the footer.
                let availableHeight = max(60, size.height - 60)
                let segmentGap = max(1.4, availableHeight * 0.01)
                let segmentHeight = max(
                    2.6,
                    (availableHeight - CGFloat(segmentCount - 1) * segmentGap)
                        / CGFloat(segmentCount)
                )
                let segmentStride = segmentHeight + segmentGap
                let maximumHeight = CGFloat(segmentCount) * segmentStride
                let columnSlot = size.width / CGFloat(columnCount)
                let columnGap = min(2.0, columnSlot * 0.22)
                let columnWidth = max(2.0, columnSlot - columnGap)

                for column in 0..<columnCount {
                    let energy = spectrumEnergy(at: (Double(column) + 0.5) / Double(columnCount))
                        ?? (0.18 + 0.76 * abs(
                            sin(Double(column) * 0.43 + time * 0.9)
                        ))
                    let litHeight = CGFloat(energy) * maximumHeight
                    let peakEnergy = 0.28 + 0.68 * abs(
                        sin(Double(column) * 0.51 + time * 0.35 + 1.2)
                    )
                    let peakSegment = min(
                        segmentCount - 1,
                        max(0, Int(peakEnergy * Double(segmentCount)))
                    )
                    let x = CGFloat(column) * columnSlot + columnGap * 0.5

                    for segment in 0..<segmentCount {
                        let y = groundY
                            - CGFloat(segment + 1) * segmentStride
                            + segmentGap
                        let lit = CGFloat(segment) * segmentStride + segmentHeight * 0.5 <= litHeight
                        let rect = CGRect(x: x, y: y, width: columnWidth, height: segmentHeight)
                        let shape = Path(roundedRect: rect, cornerRadius: 1, style: .continuous)
                        if segment == peakSegment && lit {
                            context.fill(shape, with: .color(Theme.bright.opacity(0.92)))
                        } else if lit {
                            context.fill(shape, with: .color(gridPreviewColor(for: segment, count: segmentCount)))
                        } else {
                            // The shader keeps a dim accent-tinted ghost
                            // segment visible even when that band is quiet;
                            // using the generic muted gray here made the
                            // thumbnail read like a different widget.
                            context.fill(shape, with: .color(Theme.accent.opacity(0.12)))
                        }
                    }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        case "bars", "bars-compact", "bars-tall":
            Canvas { context, size in
                // Full-desktop bars use at least 96 display columns made of
                // small modular blocks. Render that same rhythm instead of the
                // old 20 wide towers and visible baseline.
                // The active card mirrors the full-desktop block rhythm. The
                // inactive loop-padding cards only need a recognizable,
                // proportionally correct thumbnail and should not make the
                // Search -> Visualiser transition pay for ten full canvases.
                let columnCount = active ? 96 : 32
                let groundY = size.height - 9
                let sizeScale = previewSizeScale
                // Match the full-desktop shader's reserve and module rhythm.
                // The previous thumbnail stack was much taller than the real
                // layer, which made the card look clipped and "corrupted" at
                // the bottom edge.
                let maximumHeight = max(8, (size.height - 78) * sizeScale)
                let blockHeight: CGFloat = 6.4
                let blockGap: CGFloat = 2.4
                let blockStride = blockHeight + blockGap
                let slot = size.width / CGFloat(columnCount)
                let barGap = min(1.5, slot * 0.24)
                let barWidth = max(1.5, slot - barGap)

                for column in 0..<columnCount {
                    let value = spectrumEnergy(at: (Double(column) + 0.5) / Double(columnCount))
                        ?? (0.18 + 0.72 * abs(
                            sin(Double(column) * 0.19 + time * 0.7)
                        ))
                    let count = max(
                        1,
                        Int((CGFloat(value) * maximumHeight / blockStride).rounded(.down))
                    )
                    let x = CGFloat(column) * slot + barGap * 0.5
                    for block in 0..<count {
                        let y = groundY - CGFloat(block + 1) * blockStride + blockGap
                        guard y + blockHeight >= 0 else { continue }
                        let rect = CGRect(x: x, y: y, width: barWidth, height: blockHeight)
                        let shape = Path(roundedRect: rect, cornerRadius: 1, style: .continuous)
                        let color = block == count - 1
                            ? Theme.bright.opacity(0.92)
                            : Theme.accent.opacity(0.82)
                        context.fill(shape, with: .color(color))
                    }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        default:
            EmptyView()
        }
    }

    private var previewSizeScale: CGFloat {
        switch style {
        case "bars-compact": return 0.72
        case "bars-tall": return 1.10
        default: return 1.0
        }
    }

    /// Match the desktop shader's direct/smoothed source response closely
    /// enough that a focused thumbnail has the same low/mid/high balance as
    /// the full-desktop layer. `levels` already contains the producer's
    /// normalized spectrum; the small response curve is the shader's shared
    /// dB reference and prevents quiet bands from turning into false towers.
    private func spectrumEnergy(at normalized: Double) -> Double? {
        // The shell deliberately does not own a second audio sampler just for
        // a closed carousel. Its initial/cache floor is therefore a uniform
        // 0.05 array, which is not a meaningful signal and would make the
        // focused card look blank while its neighbours show their authored
        // fallback geometry. Use the live feed only once it contains a real
        // peak; an actual quiet track still gets the stable scene preview.
        guard levels.count >= 4, (levels.max() ?? 0) > 0.08 else { return nil }
        let coordinate = min(0.999, max(0, normalized)) * Double(levels.count - 1)
        let lower = max(0, min(levels.count - 1, Int(floor(coordinate))))
        let upper = min(levels.count - 1, lower + 1)
        let fraction = coordinate - Double(lower)
        let eased = fraction * fraction * (3 - 2 * fraction)
        let raw = min(1, max(0, levels[lower])) * (1 - eased)
            + min(1, max(0, levels[upper])) * eased
        return pow(max(0, min(1, (raw - 0.016) * 1.42)), 0.94)
    }

    private func gridPreviewColor(for segment: Int, count: Int) -> Color {
        let position = Double(segment) / Double(max(1, count - 1))
        if position < 0.32 {
            return Color(red: 0.25, green: 0.95, blue: 0.55).opacity(0.88)
        } else if position < 0.60 {
            return Theme.accent.opacity(0.88)
        } else if position < 0.82 {
            return Color(red: 1.0, green: 0.65, blue: 0.22).opacity(0.88)
        } else {
            return Color(red: 1.0, green: 0.30, blue: 0.28).opacity(0.88)
        }
    }
}

private enum MacPlusPlusNexusUpdateTone: Sendable {
    case neutral
    case current
    case available
}

private struct MacPlusPlusNexusUpdateSummary: Equatable, Sendable {
    let title: String
    let detail: String
    let symbol: String
    let tone: MacPlusPlusNexusUpdateTone

    static let notChecked = MacPlusPlusNexusUpdateSummary(
        title: "NOT CHECKED",
        detail: "",
        symbol: "clock",
        tone: .neutral
    )
}

private struct MacPlusPlusNexusUpdateSnapshot: Sendable {
    let software: MacPlusPlusNexusUpdateSummary
    let brew: MacPlusPlusNexusUpdateSummary
}

/// Read-only maintenance probes for Nexus. They run away from the main actor,
/// have a hard deadline, and only return short display summaries. In
/// particular, this page never installs anything or mutates a package manager.
private enum MacPlusPlusNexusUpdateProbe {
    private struct CommandResult {
        let status: Int32
        let output: String
    }

    static func snapshot() async -> MacPlusPlusNexusUpdateSnapshot {
        // Keep the two read-only services independent. `softwareupdate` can
        // spend several seconds waking its daemon while Homebrew is already
        // able to answer, so serialising them made both cards look empty
        // behind one slow system check.
        async let software = softwareUpdateSummary()
        async let brew = brewSummary()
        return await MacPlusPlusNexusUpdateSnapshot(software: software, brew: brew)
    }

    static func softwareSnapshot() -> MacPlusPlusNexusUpdateSummary {
        softwareUpdateSummary()
    }

    static func brewSnapshot() -> MacPlusPlusNexusUpdateSummary {
        brewSummary()
    }

    private static func softwareUpdateSummary() -> MacPlusPlusNexusUpdateSummary {
        let executable = "/usr/sbin/softwareupdate"
        guard FileManager.default.isExecutableFile(atPath: executable) else {
            return MacPlusPlusNexusUpdateSummary(
                title: "UNAVAILABLE",
                detail: "macOS Software Update is not available on this host.",
                symbol: "questionmark.circle",
                tone: .neutral
            )
        }

        // Software Update may spend several seconds waking its daemon before
        // it prints the first label. Keep this bounded, but do not turn a
        // normal slow check into a misleading status-15 failure.
        let result = run(executable: executable, arguments: ["--list"], timeout: 30)
        let lines = meaningfulLines(result.output)
        let labels = lines
            .filter { $0.lowercased().hasPrefix("* label:") }
            .map { line in
                line.replacingOccurrences(of: "* Label:", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
            .filter { !$0.isEmpty }

        if !labels.isEmpty {
            let visible = labels.prefix(3).joined(separator: "  •  ")
            let remainder = labels.count > 3 ? "  •  +\(labels.count - 3) more" : ""
            return MacPlusPlusNexusUpdateSummary(
                title: "\(labels.count) AVAILABLE",
                detail: String((visible + remainder).prefix(150)),
                symbol: "arrow.down.circle",
                tone: .available
            )
        }

        if result.status == 0 {
            let lower = result.output.lowercased()
            let detail = lower.contains("no new software")
                ? "No new macOS updates were reported."
                : "The macOS update service completed its check."
            return MacPlusPlusNexusUpdateSummary(
                title: "UP TO DATE",
                detail: detail,
                symbol: "checkmark.circle",
                tone: .current
            )
        }

        return MacPlusPlusNexusUpdateSummary(
            title: "CHECK FAILED",
            detail: "macOS returned status \(result.status). Open Software Update for details.",
            symbol: "exclamationmark.triangle",
            tone: .available
        )
    }

    private static func brewSummary() -> MacPlusPlusNexusUpdateSummary {
        let candidates = ["/opt/homebrew/bin/brew", "/usr/local/bin/brew"]
        guard let executable = candidates.first(where: {
            FileManager.default.isExecutableFile(atPath: $0)
        }) else {
            return MacPlusPlusNexusUpdateSummary(
                title: "NOT INSTALLED",
                detail: "Homebrew was not found in the standard Apple Silicon or Intel path.",
                symbol: "shippingbox",
                tone: .neutral
            )
        }

        let formulaResult = run(
            executable: executable,
            arguments: ["outdated", "--formula", "--json=v2"],
            timeout: 15
        )
        let caskResult = run(
            executable: executable,
            arguments: ["outdated", "--cask", "--json=v2"],
            timeout: 15
        )
        let packages = brewPackageNames(from: formulaResult.output, key: "formulae")
            + brewPackageNames(from: caskResult.output, key: "casks")

        if formulaResult.status == 0 && caskResult.status == 0 {
            guard !packages.isEmpty else {
                return MacPlusPlusNexusUpdateSummary(
                    title: "UP TO DATE",
                    detail: "All Homebrew formulae and casks are current.",
                    symbol: "checkmark.circle",
                    tone: .current
                )
            }

            let names = packages.prefix(4).map { line in
                line.split(whereSeparator: { $0 == " " || $0 == "\t" }).first.map(String.init) ?? line
            }
            let visible = names.joined(separator: "  •  ")
            let remainder = packages.count > names.count ? "  •  +\(packages.count - names.count) more" : ""
            return MacPlusPlusNexusUpdateSummary(
                title: "\(packages.count) AVAILABLE",
                detail: String((visible + remainder).prefix(150)),
                symbol: "arrow.down.circle",
                tone: .available
            )
        }

        return MacPlusPlusNexusUpdateSummary(
            title: "CHECK FAILED",
            detail: "Homebrew returned status \(formulaResult.status == 0 ? caskResult.status : formulaResult.status). Check the brew installation in Terminal.",
            symbol: "exclamationmark.triangle",
            tone: .available
        )
    }

    private static func brewPackageNames(from output: String, key: String) -> [String] {
        guard let data = output.data(using: .utf8),
              // macpp:silent-ok malformed Homebrew JSON uses the line-parser compatibility fallback
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let entries = object[key] as? [[String: Any]] else {
            // Older Homebrew versions may not support v2 JSON. Keep the
            // terminal parser as a compatibility fallback, but never parse
            // the JSON wrapper itself as if it were a package name.
            return brewPackageLines(output)
        }

        return entries.compactMap { entry in
            guard let name = entry["name"] as? String else { return nil }
            let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }
    }

    private static func brewPackageLines(_ output: String) -> [String] {
        meaningfulLines(output).compactMap { rawLine in
            let line = stripTerminalFormatting(rawLine)
                .replacingOccurrences(of: "✓", with: " ")
                .replacingOccurrences(of: "✔", with: " ")
                .replacingOccurrences(of: "•", with: " ")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            let lower = line.lowercased()
            guard !lower.hasPrefix("==>")
                    && !lower.hasPrefix("warning:")
                    && !lower.hasPrefix("error:")
                    && !lower.contains("homebrew") else {
                return nil
            }

            // `brew` can interleave a completion glyph from stderr with the
            // actual inventory line when both streams share a pipe. Select the
            // first package-shaped token instead of treating that status mark
            // as a second package (or showing `✓ • name` in the card).
            let tokens = line.split(whereSeparator: { $0 == " " || $0 == "\t" })
            guard let packageIndex = tokens.firstIndex(where: { token in
                token.range(of: #"^[A-Za-z0-9@._+/-]+$"#, options: .regularExpression) != nil
            }) else {
                return nil
            }
            return tokens[packageIndex...].joined(separator: " ")
        }
    }

    private static func stripTerminalFormatting(_ value: String) -> String {
        var result = ""
        var inEscape = false
        for scalar in value.unicodeScalars {
            if scalar.value == 0x1B {
                inEscape = true
                continue
            }
            if inEscape {
                // CSI/ANSI sequences end at a final byte in the @–~ range.
                if (0x40...0x7E).contains(scalar.value) {
                    inEscape = false
                }
                continue
            }
            result.unicodeScalars.append(scalar)
        }
        return result
    }

    private static func meaningfulLines(_ output: String) -> [String] {
        output
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private static func run(
        executable: String,
        arguments: [String],
        timeout: TimeInterval
    ) -> CommandResult {
        let process = Process()
        let outputPipe = Pipe()
        let errorPipe = Pipe()
        process.executableURL = URL(fileURLWithPath: executable)
        process.arguments = arguments
        // Keep machine-readable stdout clean. Homebrew can write warnings or
        // progress text to stderr; merging that stream made JSON v2 appear
        // malformed and the compatibility parser then displayed tokens such
        // as `null` as if they were package names.
        process.standardOutput = outputPipe
        process.standardError = errorPipe

        do {
            try process.run()
        } catch {
            return CommandResult(status: -1, output: "")
        }

        // Drain output concurrently so an unusually verbose brew invocation
        // cannot fill the pipe and hold the shell in a wait loop.
        let outputLock = NSLock()
        var outputData = Data()
        let reader = DispatchGroup()
        reader.enter()
        DispatchQueue.global(qos: .utility).async {
            let data = outputPipe.fileHandleForReading.readDataToEndOfFile()
            outputLock.lock()
            outputData = data
            outputLock.unlock()
            reader.leave()
        }
        reader.enter()
        DispatchQueue.global(qos: .utility).async {
            // Drain stderr independently so diagnostics can never fill a
            // second pipe and hold a failed probe in the wait loop. The
            // status code is enough for the user-facing failure state.
            _ = errorPipe.fileHandleForReading.readDataToEndOfFile()
            reader.leave()
        }

        let deadline = Date().addingTimeInterval(max(0.5, timeout))
        while process.isRunning && Date() < deadline {
            Thread.sleep(forTimeInterval: 0.025)
        }
        if process.isRunning {
            process.terminate()
            Thread.sleep(forTimeInterval: 0.10)
            if process.isRunning {
                _ = Darwin.kill(process.processIdentifier, SIGKILL)
            }
        }
        process.waitUntilExit()
        reader.wait()

        outputLock.lock()
        let bounded = outputData.prefix(32_768)
        let output = String(data: bounded, encoding: .utf8) ?? ""
        outputLock.unlock()
        return CommandResult(status: process.terminationStatus, output: output)
    }
}

@MainActor
private final class MacPlusPlusNexusUpdateModel: ObservableObject {
    @Published private(set) var software = MacPlusPlusNexusUpdateSummary.notChecked
    @Published private(set) var brew = MacPlusPlusNexusUpdateSummary.notChecked
    @Published private(set) var isRefreshing = false
    @Published private(set) var lastChecked = "NOT CHECKED"
    private var softwareTask: Task<Void, Never>?
    private var brewTask: Task<Void, Never>?
    private var refreshGeneration = 0
    private var pendingProbes = 0

    func refresh() {
        softwareTask?.cancel()
        brewTask?.cancel()
        refreshGeneration &+= 1
        let generation = refreshGeneration
        pendingProbes = 2
        isRefreshing = true
        software = MacPlusPlusNexusUpdateSummary(
            title: "CHECKING…",
            detail: "Asking macOS for a read-only update list.",
            symbol: "arrow.triangle.2.circlepath",
            tone: .neutral
        )
        brew = MacPlusPlusNexusUpdateSummary(
            title: "CHECKING…",
            detail: "Reading Homebrew's available package list.",
            symbol: "arrow.triangle.2.circlepath",
            tone: .neutral
        )

        softwareTask = Task { @MainActor [weak self] in
            let summary = await Task.detached(priority: .utility) {
                MacPlusPlusNexusUpdateProbe.softwareSnapshot()
            }.value
            guard !Task.isCancelled, let self, self.refreshGeneration == generation else { return }
            self.software = summary
            self.probeFinished(generation: generation)
        }

        brewTask = Task { @MainActor [weak self] in
            let summary = await Task.detached(priority: .utility) {
                MacPlusPlusNexusUpdateProbe.brewSnapshot()
            }.value
            guard !Task.isCancelled, let self, self.refreshGeneration == generation else { return }
            self.brew = summary
            self.probeFinished(generation: generation)
        }
    }

    func stop() {
        softwareTask?.cancel()
        brewTask?.cancel()
        softwareTask = nil
        brewTask = nil
        pendingProbes = 0
        isRefreshing = false
    }

    private func probeFinished(generation: Int) {
        guard generation == refreshGeneration else { return }
        pendingProbes = max(0, pendingProbes - 1)
        guard pendingProbes == 0 else { return }
        isRefreshing = false
        let formatter = DateFormatter()
        formatter.dateFormat = "h:mm a"
        lastChecked = "CHECKED \(formatter.string(from: Date()))"
        softwareTask = nil
        brewTask = nil
    }
}

private struct NexusNavigationItem: Identifiable {
    let page: MacPlusPlusNexusModel.Page
    let category: String
    let title: String
    let description: String
    let symbol: String

    var id: String { page.rawValue }
}

private struct NexusSearchControl: Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let symbol: String
    let isOn: Bool
    let aliases: [String]
    let action: () -> Void
    let isMomentary: Bool
    let stateLabel: String?

    init(
        id: String,
        title: String,
        subtitle: String,
        symbol: String,
        isOn: Bool,
        aliases: [String],
        isMomentary: Bool = false,
        stateLabel: String? = nil,
        action: @escaping () -> Void
    ) {
        self.id = id
        self.title = title
        self.subtitle = subtitle
        self.symbol = symbol
        self.isOn = isOn
        self.aliases = aliases
        self.isMomentary = isMomentary
        self.stateLabel = stateLabel
        self.action = action
    }

    var searchableText: String {
        ([title, subtitle] + aliases).joined(separator: " ")
    }
}

private struct MacPlusPlusNexusView: View {
    @ObservedObject var shell: ShellModel
    @ObservedObject var nexus: MacPlusPlusNexusModel
    @ObservedObject var launcher: LauncherModel
    // Theme is backed by UserDefaults for compatibility with the standalone
    // Cast target, so an explicit observation is needed here. Without it the
    // embedded Nexus could retain the launch-time frame colour until another
    // state change happened to invalidate the hosting tree.
    @ObservedObject var palette: ShellPalettePresentation
    @StateObject private var wallpaperSource = MacPlusPlusWallpaperSourceModel()
    let close: () -> Void
    let toggleMenuMask: () -> Void
    let openLauncher: () -> Void
    var embedded = false
    @State private var wallpaperDirection = 1
    @State private var visualizerDirection = 1
    @State private var wallpaperDiscoveryExpanded = false
    @State private var wallpaperCropResult: MacPlusPlusWallpaperSourceResult?
    @State private var wallpaperCropSelection = MacPlusPlusWallpaperCropSelection()
    @State private var softLockResetConfirmationPresented = false
    @State private var navigationSearch = ""
    @State private var wallpaperFramingRevision = 0
    @State private var nonworkWallpaperTarget: MacPlusPlusNonworkWallpaperTarget = .both
    @StateObject private var updateStatus = MacPlusPlusNexusUpdateModel()

    @ViewBuilder
    var body: some View {
        if embedded {
            // LauncherView owns the one bottom LivingSurface contour for the
            // embedded Nexus. Keep this body rectangular so its page layers
            // cannot introduce a second, ordinary rounded rectangle that
            // clips the shell's reverse bottom shoulders.
            nexusBody
                .frame(width: nexusSurfaceWidth, height: nexusSurfaceHeight)
                .background(NexusStudioStyle.background)
                .shadow(color: .clear, radius: 0)
        } else {
            // Standalone Nexus is still a floating card and keeps its original
            // rounded envelope and seam. This branch is intentionally separate
            // from the shell-owned Search/Nexus contour.
            nexusBody
                .frame(width: nexusSurfaceWidth, height: nexusSurfaceHeight)
                .background(
                    NexusStudioStyle.background,
                    in: RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                )
                .clipShape(RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous))
                .overlay {
                    RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                        .strokeBorder(
                            Theme.seam.opacity(0.38),
                            lineWidth: CaelestiaParityTokens.Border.minimumThickness
                        )
                }
                .shadow(
                    color: Theme.isLight ? .clear : Theme.shadow.opacity(0.42),
                    radius: 20,
                    y: 10
                )
        }
    }

    private var nexusBody: some View {
        ZStack(alignment: .topTrailing) {
            HStack(spacing: 0) {
                navigation
                nexusPageHost
            }

            // Caelestia's Nexus has one small tonal window control in the
            // upper-right corner. Keep the existing minimize/close actions,
            // but let them live in that compact control island instead of
            // spending an entire horizontal header row on them.
            nexusWindowControls
        }
        .frame(width: nexusSurfaceWidth, height: nexusSurfaceHeight, alignment: .topLeading)
        .onChange(of: shell.media) { _, media in nexus.refreshLyrics(for: media) }
        .onAppear {
            nexus.setPage(nexus.page)
            nexus.setVisible(true)
            shell.refreshScreensaverSelection()
            // Dashboard values remain live, but their external system probes
            // do not need a one-second cadence while a full-screen control
            // center is animating. Rail/top surfaces keep the default 1s rate.
            shell.setSurfaceVisible(
                Self.liveDashboardPages.contains(nexus.page),
                refreshInterval: 2.0
            )
            nexus.refreshLyrics(for: shell.media)
            shell.setReactive(Self.reactiveAudioPages.contains(nexus.page))
        }
        // One owner for audio sampling, driven by which page is showing. The
        // Media page draws a ReactiveAlbumDisc but never asked for sampling at
        // all, so its spectrum only animated by luck -- if the Audio page had
        // been visited first and happened to leave it on. Everywhere else it
        // rendered a flat, motionless disc.
        .onChange(of: nexus.page) { _, page in
            nexus.setPage(page)
            shell.setSurfaceVisible(Self.liveDashboardPages.contains(page), refreshInterval: 2.0)
            shell.setReactive(Self.reactiveAudioPages.contains(page))
        }
        .onReceive(NotificationCenter.default.publisher(for: macppWallpaperFramingChangedNotification)) { _ in
            wallpaperFramingRevision &+= 1
        }
        .task(id: nexus.page) {
            if nexus.page == .updates {
                updateStatus.refresh()
            } else {
                updateStatus.stop()
            }
            guard nexus.page == .network || nexus.page == .devices else { return }
            shell.refreshWiFiNetworks()
            shell.refreshBluetoothDevices()
            // Keep the Nexus inventory live after the opening scan. The
            // interval is deliberately longer than a page transition so a
            // controller inquiry cannot compete with the SwiftUI handoff.
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(12)) // macpp:silent-ok cancellation ends the bounded Nexus refresh loop
                guard !Task.isCancelled else { return }
                shell.refreshConnectivity(force: true, includeNearbyInventory: true)
                shell.refreshBluetoothDevices()
            }
        }
        .onDisappear {
            wallpaperSource.stop()
            updateStatus.stop()
            nexus.setVisible(false)
            shell.setSurfaceVisible(false)
            shell.setReactive(false)
        }
        // Keep any system controls or future labels that do not specify a
        // design explicitly on the same rounded SF Pro face as the authored
        // shell copy. Nexus also keeps its small status text on this same
        // rounded face; the general shell's tiny-caption legibility exception
        // must not leak into the control centre as a random font change.
        .fontDesign(.rounded)
        .alert("Reset Mac++ passcode?", isPresented: $softLockResetConfirmationPresented) {
            Button("Reset passcode", role: .destructive) {
                nexus.resetSoftLockPasscode()
            }
            Button("Cancel", role: .cancel) {}
        }
    }

    private var nexusPageHost: some View {
        VStack(alignment: .leading, spacing: nexusPageHeaderSpacing) {
            Text(nexus.page.displayTitle)
                .font(.system(size: CaelestiaParityTokens.Font.extraLarge, weight: .medium, design: .rounded))
                .foregroundStyle(NexusStudioStyle.bright)
                .lineLimit(1)
                .minimumScaleFactor(0.72)
                .frame(height: nexusPageHeaderHeight, alignment: .leading)

            content
                .id(nexus.page)
                .transition(nexusPageTransition)
                // Every page keeps a stable, clipped viewport. The QML page
                // stack animates the page item inside its parent rather than
                // resizing the surrounding Nexus shell.
                .frame(
                    width: nexusMainInnerWidth,
                    height: nexusMainInnerHeight,
                    alignment: .topLeading
                )
                // The page host is itself a rounded viewport. A rectangular
                // clip here can expose a square slice of a card while a page
                // is scrolling or changing height, even though the card
                // owns a continuous radius internally.
                .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                // The navigation column already fades its final rows into
                // the Nexus surface. Apply the same bottom treatment to the
                // page viewport so neither side ends in a hard crop.
                .mask {
                    VStack(spacing: 0) {
                        Color.white
                        LinearGradient(
                            colors: [.white, .clear],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                        .frame(height: nexusContentFadeHeight)
                    }
                }
        }
        .padding(.top, nexusPageTopGutter)
        .padding(.bottom, nexusPageBottomGutter)
        .padding(.leading, nexusPageLeadingGutter)
        .padding(.trailing, nexusPageTrailingGutter)
        .frame(width: nexusMainRegionWidth, height: nexusSurfaceHeight, alignment: .topLeading)
    }

    /// Pages that render a live spectrum and therefore need readAudio to keep
