    private var nexusWindowControls: some View {
        Button(action: close) {
            ZStack {
                Image(systemName: "xmark")
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                    .frame(width: 30, height: 30)
            }
            // The background belongs to the Button label, not to a sibling
            // HStack outside it. That makes the entire rounded control island
            // the native hit target instead of only the 30pt glyph frame.
            .frame(width: 38, height: 38)
            .background(
                NexusStudioStyle.field.opacity(0.94),
                in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
            )
            .overlay {
                RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                    .stroke(NexusStudioStyle.seam.opacity(0.55), lineWidth: 0.6)
            }
            .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
            .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(NexusStudioStyle.bright)
        .accessibilityLabel("Close Nexus")
        // Reserve the gutter in the control island's layout box, rather than
        // relying on the outer surface clip to make room after the fact. The
        // embedded launcher uses the same 38pt edge inset as the Search field
        // on the opposite side (16pt NavPane margin + 22pt shell shoulder).
        // Keeping both edges on this shared value makes the Nexus envelope
        // read as one centered surface, rather than leaving the X stranded
        // closer to the rim than Search is to its rim.
        .padding(.top, embedded ? nexusNavigationTopGutter : 12)
        .padding(.trailing, embedded ? nexusSharedOuterGutter : 16)
    }

    private var visibleNavigationItems: [NexusNavigationItem] {
        let query = navigationSearch.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !query.isEmpty else { return Self.nexusNavigationItems }
        return Self.nexusNavigationItems.filter {
            nexusSearchMatches(
                query: query,
                searchableText: [$0.title, $0.description, $0.category].joined(separator: " ")
            )
        }
    }

    private var visibleNexusSearchControls: [NexusSearchControl] {
        let query = navigationSearch.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !query.isEmpty else { return [] }
        return nexusSearchControls.filter {
            nexusSearchMatches(query: query, searchableText: $0.searchableText)
        }
    }

    private func normalizedNexusSearchText(_ value: String) -> String {
        value
            .lowercased()
            .folding(options: .diacriticInsensitive, locale: .current)
            .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// Match both natural phrases and token combinations. The token pass is
    /// what makes "toggle shell border" find the Shell border control even
    /// though those words are split across its title and aliases.
    private func nexusSearchMatches(query: String, searchableText: String) -> Bool {
        let normalizedQuery = normalizedNexusSearchText(query)
        guard !normalizedQuery.isEmpty else { return false }
        let haystack = normalizedNexusSearchText(searchableText)
        if haystack.contains(normalizedQuery) { return true }

        return normalizedQuery.split(separator: " ").allSatisfy { token in
            let term = String(token)
            if haystack.contains(term) { return true }
            // A plural query such as "borders" should still find the
            // singular setting label "Shell border".
            return term.count > 2
                && term.hasSuffix("s")
                && haystack.contains(String(term.dropLast()))
        }
    }

    private var navigation: some View {
        ZStack(alignment: .topLeading) {
            ZStack(alignment: .topLeading) {
                    ScrollViewReader { proxy in
                        ScrollView(.vertical, showsIndicators: false) {
                            let items = visibleNavigationItems
                            let controls = visibleNexusSearchControls
                            VStack(spacing: Spacing.extraSmall) {
                                if !controls.isEmpty {
                                    ForEach(controls) { control in
                                        nexusSearchControlButton(control)
                                            .id("nexus-search-control-\(control.id)")
                                    }
                                }

                                ForEach(Array(items.enumerated()), id: \.element.id) { index, item in
                                    let categoryStart = index == 0 || items[index - 1].category != item.category
                                    nexusNavigationButton(
                                    item,
                                    categoryGap: categoryStart && index > 0
                                )
                                // Page changes can arrive from the global arrow
                                // handler while the row is below the viewport. A
                                // stable target lets the same scroll reader reveal
                                // the item that is actually being selected.
                                .id(item.id)
                            }

                            if controls.isEmpty && items.isEmpty {
                                VStack(spacing: Spacing.tight) {
                                    Image(systemName: "magnifyingglass")
                                        .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                                        .foregroundStyle(NexusStudioStyle.muted)
                                }
                                .frame(maxWidth: .infinity)
                                .padding(.horizontal, Spacing.large)
                                .padding(.vertical, CaelestiaParityTokens.Spacing.extraLarge)
                            }
                        }
                        .padding(.top, Spacing.large)
                        // Keep a small real tail after the last rounded row. The
                        // selection helper uses a bottom anchor for the final
                        // destinations, so their complete shape remains visible
                        // without a clipped edge masquerading as a rectangle.
                        .padding(.bottom, Spacing.large)
                        .id("nexus-navigation-top")
                    }
                    // Give the scroll viewport the exact space left below the
                    // search field. An unconstrained macOS ScrollView can
                    // temporarily claim the whole VStack while its content
                    // offset changes, painting over the search field on the
                    // middle navigation destinations.
                    .frame(width: nexusNavigationWidth, height: nexusNavigationScrollHeight, alignment: .topLeading)
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                    .scrollIndicators(.never)
                    .scrollBounceBehavior(.basedOnSize)
                    .defaultScrollAnchor(.top)
                    .onAppear {
                        DispatchQueue.main.async {
                            revealNavigationSelection(nexus.page, using: proxy, animated: false)
                        }
                    }
                    .onChange(of: nexus.page) { _, page in
                        // The page transition and the list reveal share the same
                        // short handoff curve, so the selected pill and its page
                        // content settle together instead of the row arriving late.
                        revealNavigationSelection(page, using: proxy, animated: true)
                    }
                    .onChange(of: navigationSearch) { _, _ in
                        DispatchQueue.main.async {
                            revealNavigationSelection(nexus.page, using: proxy, animated: false)
                        }
                    }
                }
            }
            .frame(width: nexusNavigationWidth, height: nexusNavigationScrollHeight, alignment: .topLeading)
            // NavLocations.qml uses VerticalFadeFlickable rather than a
            // native shadow at the viewport edge. Fade clipped rows to
            // transparency, then let the shell-aware background show through;
            // reserving the fade band keeps a pill from ending exactly on the
            // Nexus/shell connection.
            .mask {
                VStack(spacing: 0) {
                    Color.white
                    LinearGradient(
                        colors: [.white, .clear],
                        startPoint: .top,
                        endPoint: .bottom
                    )
                    .frame(height: nexusNavigationFadeHeight)
                }
            }
            // The list owns only the space below the search field. Keeping it
            // in a separate fixed overlay prevents AppKit's native scroll
            // layer from briefly painting across the search control during a
            // programmatic page reveal.
            .offset(y: nexusNavigationScrollOffset)

            HStack(spacing: 7) {
                Image(systemName: "magnifyingglass")
                    .font(.system(size: ShellIcon.small, weight: .medium, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.muted)
                TextField("", text: $navigationSearch)
                    .textFieldStyle(.plain)
                    .font(.system(size: CaelestiaParityTokens.Font.larger, weight: .regular, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.bright)
                    .disableAutocorrection(true)
                    .accessibilityLabel("Search")
            }
            .padding(.horizontal, Spacing.large)
            .frame(height: 44)
            .background(NexusStudioStyle.field, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                    .stroke(NexusStudioStyle.seam.opacity(0.42), lineWidth: 0.6)
            }
            .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
            .zIndex(1)
        }
        .frame(width: nexusNavigationWidth, height: nexusSurfaceHeight - nexusNavigationTopGutter - nexusNavigationBottomGutter, alignment: .topLeading)
        // Keep the QML NavPane margin inside the fixed 316pt column. A
        // dedicated container makes the left gutter part of the layout,
        // so the embedded Cast host cannot collapse it during the morph.
        .padding(.leading, nexusNavigationOuterGutter)
        // The embedded launcher is still clipped by the attached-shell
        // contour at rest. Its vertical side begins 22pt into the host,
        // so account for that reserve after the QML 16pt NavPane margin;
        // otherwise the first row is painted directly against the cyan
        // edge even though its nominal layout margin is correct.
        .offset(x: launcherSurfaceShoulder)
        .padding(.top, nexusNavigationTopGutter)
        .padding(.bottom, nexusNavigationBottomGutter)
        .frame(width: nexusNavigationFrameWidth, height: nexusSurfaceHeight, alignment: .topLeading)
    }

    private func revealNavigationSelection(
        _ page: MacPlusPlusNexusModel.Page,
        using proxy: ScrollViewProxy,
        animated: Bool
    ) {
        guard visibleNavigationItems.contains(where: { $0.page == page }) else {
            // A filtered query may hide the current page. Keep the list at its
            // leading edge until the query produces a visible selection rather
            // than scrolling toward an item that is not in the tree.
            guard navigationSearch.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) {
                    proxy.scrollTo("nexus-navigation-top", anchor: .top)
                }
                return
            }
            return
        }

        let items = visibleNavigationItems
        let index = items.firstIndex(where: { $0.page == page }) ?? 0
        // A top anchor is stable for the normal list and prevents an earlier
        // row from being sliced under the search field. The final two rows
        // use the bottom landing zone so the list does not leave a large dead
        // void under the active selection.
        let anchor: UnitPoint = index >= max(0, items.count - 2) ? .bottom : .top

        if animated {
            withAnimation(ShellMotion.nexusPageSwitch.animation) {
                proxy.scrollTo(page.rawValue, anchor: anchor)
            }
        } else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                proxy.scrollTo(page.rawValue, anchor: anchor)
            }
        }
    }

    private func nexusNavigationButton(
        _ item: NexusNavigationItem,
        categoryGap: Bool
    ) -> some View {
        let selected = nexus.page == item.page
        let cornerRadius: CGFloat = selected
            ? Rounding.extraLargeIncreased
            : Rounding.extraLarge
        return Button {
            withAnimation(ShellMotion.nexusPageSwitch.animation) { nexus.page = item.page }
        } label: {
            HStack(spacing: Spacing.medium) {
                ZStack {
                    Circle()
                        .fill(selected ? NexusStudioStyle.accent : NexusStudioStyle.selection)
                    Image(systemName: item.symbol)
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        // Hierarchical rendering makes the thinnest parts of
                        // a tiny symbol inherit another opacity tier. On a
                        // wallpaper-derived light tile that compounds the
                        // contrast problem, so navigation symbols stay solid.
                        .symbolRenderingMode(.monochrome)
                        .foregroundStyle(selected ? NexusStudioStyle.iconOnAccent : NexusStudioStyle.iconOnSelection)
                }
                .frame(width: 34, height: 34)

                VStack(alignment: .leading, spacing: 0) {
                    Text(item.title)
                        .font(.system(size: CaelestiaParityTokens.Font.larger, weight: .medium, design: .rounded))
                        .foregroundStyle(selected ? NexusStudioStyle.bright : NexusStudioStyle.bright.opacity(0.92))
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .layoutPriority(1)
            }
            .padding(.horizontal, Spacing.large)
            .padding(.vertical, Spacing.small)
            .frame(maxWidth: .infinity, minHeight: 58, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .accessibilityHint(item.description)
        .background(
            selected ? NexusStudioStyle.selection : NexusStudioStyle.card.opacity(0.54),
            in: RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
        )
        .overlay {
            if selected {
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .stroke(NexusStudioStyle.accent.opacity(0.42), lineWidth: 0.7)
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
        .padding(.top, categoryGap ? Spacing.medium : 0)
        .contentShape(Rectangle())
    }

    private func nexusSearchControlButton(_ control: NexusSearchControl) -> some View {
        let shape = RoundedRectangle(cornerRadius: Rounding.extraLarge, style: .continuous)
        return Button {
            withAnimation(ShellMotion.contentIn.animation) {
                control.action()
            }
        } label: {
            HStack(spacing: Spacing.medium) {
                ZStack {
                    Circle()
                        .fill(control.isOn ? NexusStudioStyle.accent : NexusStudioStyle.selection)
                    Image(systemName: control.symbol)
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .symbolRenderingMode(.monochrome)
                        .foregroundStyle(control.isOn ? NexusStudioStyle.iconOnAccent : NexusStudioStyle.iconOnSelection)
                }
                .frame(width: 34, height: 34)

                VStack(alignment: .leading, spacing: 0) {
                    Text(control.title)
                        .font(.system(size: CaelestiaParityTokens.Font.larger, weight: .medium, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.bright)
                        .lineLimit(1)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .layoutPriority(1)

                Text(control.stateLabel ?? (control.isOn ? "ON" : "OFF"))
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                    .foregroundStyle(control.isOn ? NexusStudioStyle.accent : NexusStudioStyle.muted)
            }
            .padding(.horizontal, Spacing.large)
            .padding(.vertical, Spacing.small)
            .frame(maxWidth: .infinity, minHeight: 58, alignment: .leading)
            .background(
                control.isOn ? NexusStudioStyle.selection : NexusStudioStyle.card.opacity(0.54),
                in: shape
            )
            .overlay {
                if control.isOn {
                    shape.stroke(NexusStudioStyle.accent.opacity(0.42), lineWidth: 0.7)
                }
            }
            .contentShape(shape)
        }
        .buttonStyle(MicroButtonStyle())
        .accessibilityLabel(control.isMomentary ? control.title : "Toggle \(control.title)")
        .accessibilityValue(control.isMomentary ? "Action" : (control.isOn ? "On" : "Off"))
        .accessibilityHint(control.subtitle)
    }

    @ViewBuilder private var content: some View {
        switch nexus.page {
        case .setup: setupManager
        case .settings: settings
        case .network: network
        case .devices: devices
        case .audio: audio
        case .updates: updates
        case .capture: capture
        case .apps: apps
        case .observatory: observatory
        case .language: language
        case .about: about
        case .overview: overview
        case .media: media
        case .system: system
        }
    }

    private var setupManager: some View {
        MacPlusPlusPublicSetupManager(onChange: {
            shell.refreshConnectivity(force: true)
        })
    }

    private var nexusPageTransition: AnyTransition {
        // Page changes are an explicit selection, not a surface relocation.
        // Removing the automatic horizontal translation also prevents a page
        // from travelling underneath the sidebar gutter during the resize.
        return .opacity
    }

    private var devices: some View {
        let devices = shell.bluetoothDevices.sorted { lhs, rhs in
            if lhs.connected != rhs.connected { return lhs.connected && !rhs.connected }
            if lhs.nearby != rhs.nearby { return lhs.nearby && !rhs.nearby }
            if lhs.paired != rhs.paired { return lhs.paired && !rhs.paired }
            return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
        }
        return ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.small) {
                bluetoothNexusCard(devices)
                bluetoothDetailsCard(devices)
            }
            .frame(width: nexusMainInnerWidth, alignment: .leading)
            .padding(.bottom, Spacing.large)
            .contentShape(Rectangle())
            .id("nexus-devices-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-devices-top")
    }

    private var updates: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.small) {
                HStack(spacing: Spacing.medium) {
                    ZStack {
                        Circle().fill(NexusStudioStyle.selection)
                        Image(systemName: "arrow.triangle.2.circlepath")
                            .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.accent)
                    }
                    .frame(width: 44, height: 44)
                    VStack(alignment: .leading, spacing: Spacing.hairline) {
                        Text("Maintenance")
                            .font(.system(size: CaelestiaParityTokens.Font.large, weight: .medium, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.bright)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    if updateStatus.isRefreshing {
                        ProgressView()
                            .controlSize(.small)
                            .tint(NexusStudioStyle.accent)
                    }
                    Button { updateStatus.refresh() } label: {
                        Image(systemName: updateStatus.isRefreshing ? "arrow.triangle.2.circlepath" : "arrow.clockwise")
                            .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                            .frame(width: 30, height: 30)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .foregroundStyle(NexusStudioStyle.muted)
                    .background(NexusStudioStyle.raised, in: Circle())
                    .disabled(updateStatus.isRefreshing)
                }
                .padding(.horizontal, Spacing.largeIncreased)
                .padding(.vertical, Spacing.large)
                .frame(maxWidth: .infinity, alignment: .leading)
                .nexusLayer(cornerRadius: Rounding.large, depth: .card)

                nexusUpdateCard("macOS software update", updateStatus.software)
                nexusUpdateCard("Homebrew packages", updateStatus.brew)

                HStack(spacing: Spacing.base) {
                    nexusActionButton("Open Software Update", "gearshape", primary: false) {
                        openSoftwareUpdate()
                    }
                    .frame(maxWidth: .infinity)
                    nexusActionButton("Copy brew check", "doc.on.doc", primary: false) {
                        copyHomebrewCheckCommand()
                    }
                    .frame(maxWidth: .infinity)
                }

                Text(updateStatus.lastChecked)
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.muted)
                    .frame(maxWidth: .infinity, alignment: .trailing)
                    .padding(.top, Spacing.hairline)
            }
            .frame(width: nexusMainInnerWidth, alignment: .leading)
            .padding(.bottom, Spacing.large)
            .contentShape(Rectangle())
            .id("nexus-updates-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-updates-top")
    }

    private func nexusUpdateCard(
        _ title: String,
        _ summary: MacPlusPlusNexusUpdateSummary
    ) -> some View {
        let tint = nexusUpdateColor(summary.tone)
        return HStack(spacing: Spacing.medium) {
            ZStack {
                Circle().fill(tint.opacity(0.16))
                Image(systemName: summary.symbol)
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(tint)
            }
            .frame(width: 36, height: 36)
            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(title)
                    .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.bright)
                    .lineLimit(1)
                if !summary.detail.isEmpty {
                    Text(summary.detail)
                        .font(.system(size: ShellTypography.micro, weight: .medium, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                        .lineLimit(2)
                        .minimumScaleFactor(0.72)
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            Text(summary.title)
                .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                .foregroundStyle(tint)
                .lineLimit(1)
                .minimumScaleFactor(0.68)
        }
        .padding(.horizontal, Spacing.largeIncreased)
        .padding(.vertical, Spacing.medium)
        .frame(maxWidth: .infinity, minHeight: 72, alignment: .leading)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func nexusUpdateColor(_ tone: MacPlusPlusNexusUpdateTone) -> Color {
        switch tone {
        case .neutral: return NexusStudioStyle.muted
        case .current: return Theme.mint
        case .available: return NexusStudioStyle.accent
        }
    }

    private var apps: some View {
        let appItems = Array(launcher.baseItems.filter { $0.kind == .app }.prefix(6))
        let runningNames = Set(
            NSWorkspace.shared.runningApplications.compactMap { application in
                application.localizedName?.lowercased()
            }
        )
        return ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.small) {
                HStack(spacing: Spacing.medium) {
                    ZStack {
                        Circle().fill(NexusStudioStyle.selection)
                        Image(systemName: "square.grid.2x2")
                            .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.accent)
                    }
                    .frame(width: 44, height: 44)
                    VStack(alignment: .leading, spacing: Spacing.hairline) {
                        Text("Launcher catalog")
                            .font(.system(size: CaelestiaParityTokens.Font.large, weight: .medium, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.bright)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    Button { launcher.reload() } label: {
                        Image(systemName: "arrow.clockwise")
                            .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                            .frame(width: 30, height: 30)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .foregroundStyle(NexusStudioStyle.muted)
                    .background(NexusStudioStyle.raised, in: Circle())
                }
                .padding(.horizontal, Spacing.largeIncreased)
                .padding(.vertical, Spacing.large)
                .frame(maxWidth: .infinity, alignment: .leading)
                .nexusLayer(cornerRadius: Rounding.large, depth: .card)

                HStack(spacing: Spacing.base) {
                    nexusActionButton("Open launcher", "magnifyingglass", primary: true) {
                        openLauncher()
                    }
                    .frame(maxWidth: .infinity)
                }

                if appItems.isEmpty {
                    nexusInfoRow(
                        "App catalog",
                        "The launcher will refresh its application list when opened.",
                        "app.dashed",
                        value: "READY",
                        first: true,
                        last: true
                    )
                } else {
                    VStack(spacing: 2) {
                        ForEach(Array(appItems.enumerated()), id: \.element.id) { index, item in
                            nexusAppRow(
                                item,
                                running: runningNames.contains(item.title.lowercased()),
                                first: index == 0,
                                last: index == appItems.count - 1
