    private func nexusAppRow(
        _ item: CommandItem,
        running: Bool,
        first: Bool,
        last: Bool
    ) -> some View {
        Button {
            guard let url = item.url else { return }
            NSWorkspace.shared.open(url)
        } label: {
            HStack(spacing: Spacing.medium) {
                if let url = item.url {
                    Image(nsImage: NSWorkspace.shared.icon(forFile: url.path))
                        .resizable()
                        .interpolation(.high)
                        .scaledToFit()
                        .frame(width: 28, height: 28)
                } else {
                    Image(systemName: item.icon)
                        .foregroundStyle(NexusStudioStyle.muted)
                        .frame(width: 28, height: 28)
                }
                VStack(alignment: .leading, spacing: 0) {
                    Text(item.title)
                        .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.bright)
                        .lineLimit(1)
                    Text(running ? "RUNNING" : "INDEXED")
                        .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                        .foregroundStyle(running ? Theme.mint : NexusStudioStyle.muted)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                Image(systemName: "arrow.up.forward.app")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.muted)
            }
            .padding(.horizontal, Spacing.largeIncreased)
            .padding(.vertical, Spacing.medium)
            .frame(maxWidth: .infinity, minHeight: 58, alignment: .leading)
            .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .background(
            NexusStudioStyle.card,
            in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
        )
        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
    }

    private var language: some View {
        let locale = Locale.current
        let languageName = locale.localizedString(forLanguageCode: locale.language.languageCode?.identifier ?? "") ?? "System default"
        let regionName = locale.localizedString(forRegionCode: locale.region?.identifier ?? "") ?? "System default"
        return nexusInfoPage(
            rows: [
                ("Interface language", languageName, "character"),
                ("Region", regionName, "mappin.and.ellipse"),
                ("Display units", locale.measurementSystem == .metric ? "Metric" : "Imperial", "ruler"),
                ("Calendar", String(describing: locale.calendar.identifier).capitalized, "calendar"),
                ("Time zone", TimeZone.current.identifier, "clock")
            ],
            actionTitle: "Open Language & Region",
            actionSymbol: "arrow.up.forward.app",
            action: openLanguageRegion
        )
    }

    private var about: some View {
        let version = (Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String) ?? "Development build"
        let macOSVersion = ProcessInfo.processInfo.operatingSystemVersionString
        let activeApp = shell.frontApp.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "Desktop"
            : shell.frontApp
        return nexusInfoPage(
            rows: [
                ("Version", version, "number"),
                ("macOS", macOSVersion, "apple.logo"),
                ("Active app", activeApp, "macwindow"),
                ("Workspace", "SPACE \(shell.currentWorkspace)", "square.grid.2x2"),
                ("Palette", shell.selectedPalette.title.capitalized, "paintpalette"),
                ("Maintenance", "Read-only update checks", "arrow.triangle.2.circlepath"),
                ("Reference", "Caelestia Nexus QML", "link")
            ],
            actionTitle: "Open Caelestia source",
            actionSymbol: "arrow.up.forward.app",
            action: openCaelestiaReference
        )
    }

    private func nexusInfoPage(
        rows: [(String, String, String)],
        actionTitle: String? = nil,
        actionSymbol: String = "arrow.up.forward.app",
        action: (() -> Void)? = nil
    ) -> some View {
        let anchorID = "nexus-info-\(rows.first?.0 ?? "page")"
        return ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.small) {
                VStack(spacing: 2) {
                    ForEach(Array(rows.enumerated()), id: \.offset) { index, row in
                        nexusInfoRow(
                            row.0,
                            row.1,
                            row.2,
                            value: "",
                            first: index == 0,
                            last: index == rows.count - 1
                        )
                    }
                }
                if let actionTitle, let action {
                    nexusActionButton(actionTitle, actionSymbol, primary: false, action: action)
                        .frame(maxWidth: .infinity)
                }
            }
            .frame(width: nexusMainInnerWidth, alignment: .leading)
            .padding(.bottom, Spacing.large)
            .contentShape(Rectangle())
            .id(anchorID)
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: anchorID)
    }

    private func nexusInfoRow(
        _ title: String,
        _ subtitle: String,
        _ symbol: String,
        value: String,
        first: Bool = false,
        last: Bool = false
    ) -> some View {
        HStack(spacing: Spacing.medium) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                .foregroundStyle(NexusStudioStyle.muted)
                .frame(width: 20)
            nexusRowCopy(title: title, subtitle: subtitle)
            .frame(maxWidth: .infinity, alignment: .leading)
            if !value.isEmpty {
                Text(value)
                    .font(.system(size: CaelestiaParityTokens.Font.normal, weight: .regular, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.muted)
                    .lineLimit(1)
            }
        }
        .padding(.horizontal, Spacing.largeIncreased)
        .padding(.vertical, Spacing.medium)
        // Keep informational rows on the same 58pt baseline box as setting
        // toggles. A one-point height difference changes the rasterisation
        // phase and makes an otherwise identical title look like a different
        // font when the rows are stacked.
        .frame(maxWidth: .infinity, minHeight: 58, alignment: .leading)
        .background(
            NexusStudioStyle.card,
            in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
        )
        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
    }

    private var network: some View {
        let nearbyNetworks = railWiFiNetworks(
            from: shell.knownNetworks,
            connected: shell.connectedNetwork,
            limit: nil
        )
        return ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 7) {
                    Spacer(minLength: 0)
                    Text(networkScanSummary)
                        .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                        .lineLimit(1)
                }
                wifiNexusCard(nearbyNetworks)
                networkDetailsCard(nearbyNetworks)
            }
            .frame(width: nexusMainInnerWidth, alignment: .leading)
            .padding(.bottom, 16)
            .contentShape(Rectangle())
            .id("nexus-network-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-network-top")
    }

    private var networkScanSummary: String {
        shell.wifiScanning ? "WI-FI SCANNING" : shell.wifiScanStatus
    }

    private func wifiNexusCard(_ networks: [KnownWiFiNetwork]) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Image(systemName: shell.wifiOn ? "wifi" : "wifi.slash")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.accent)
                Text("NEARBY WI-FI")
                    .font(.system(size: ShellTypography.label, weight: .bold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.bright)
                Spacer(minLength: 0)
                Toggle("", isOn: Binding(get: { shell.wifiOn }, set: { _ in shell.toggleWiFi() }))
                    .disabled(shell.wifiActionPending)
                    .accessibilityLabel("Wi-Fi")
                    .labelsHidden()
                    .toggleStyle(ShellSwitchToggleStyle(compact: true))
                Button { shell.refreshWiFiNetworks() } label: {
                    Image(systemName: shell.wifiScanning ? "dot.radiowaves.left.and.right" : "arrow.clockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 24, height: 24)
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(NexusStudioStyle.muted)
                .disabled(!shell.wifiOn || shell.wifiScanning)
            }
            if !shell.wifiOn {
                networkEmptyRow(symbol: "wifi.slash")
            } else {
                if shell.wifiConnected && shell.connectedNetwork.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    wifiNexusConnectedHiddenRow()
                }
                if networks.isEmpty {
                    networkEmptyRow(symbol: shell.wifiScanning ? "dot.radiowaves.left.and.right" : "wifi.exclamationmark")
                } else {
                    ForEach(networks) { network in
                        wifiNexusRow(network)
                    }
                }
            }
        }
        .padding(12)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func networkDetailsCard(_ networks: [KnownWiFiNetwork]) -> some View {
        let current = shell.connectedNetwork.trimmingCharacters(in: .whitespacesAndNewlines)
        let currentLabel = current.isEmpty
            ? (shell.wifiConnected ? "CONNECTED · SSID HIDDEN" : "NOT CONNECTED")
            : current
        let vpn = shell.vpnName.trimmingCharacters(in: .whitespacesAndNewlines)
        return VStack(alignment: .leading, spacing: Spacing.base) {
            HStack {
                Text("CONNECTION DETAILS").nexusLabel()
                Spacer(minLength: 8)
                Text(shell.wifiOn ? "ACTIVE" : "OFF")
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                    .foregroundStyle(shell.wifiOn ? Theme.mint : Theme.muted)
            }
            HStack(spacing: Spacing.base) {
                nexusDetailTile("NETWORK", currentLabel, "wifi")
                nexusDetailTile("DISCOVERED", String(networks.count), "dot.radiowaves.left.and.right")
            }
            if !vpn.isEmpty {
                nexusDetailTile(
                    "VPN",
                    shell.vpnConnected ? vpn + " · CONNECTED" : vpn + " · DISCONNECTED",
                    "network.badge.shield.half.filled"
                )
            }
            HStack(spacing: Spacing.base) {
                nexusActionButton("Network settings", "gearshape", primary: false) {
                    openSystemSettings("com.apple.wifi-settings-extension")
                }
                .frame(maxWidth: .infinity)
                nexusActionButton("Refresh", "arrow.clockwise", primary: false) {
                    shell.refreshWiFiNetworks()
                }
                .frame(maxWidth: .infinity)
            }
        }
        .padding(Spacing.roomy)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func nexusDetailTile(_ title: String, _ value: String, _ symbol: String) -> some View {
        HStack(spacing: Spacing.snug) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(title).nexusLabel()
                Text(value)
                    .nexusValue()
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, Spacing.base)
        .frame(maxWidth: .infinity, minHeight: 52, alignment: .leading)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .tile)
    }

    private func wifiNexusRow(_ network: KnownWiFiNetwork) -> some View {
        let active = shell.wifiConnected && wifiNamesEqual(network.name, shell.connectedNetwork)
        return Button {
            if active { shell.disconnectWiFi() } else { shell.connectWiFi(network) }
        } label: {
            HStack(spacing: 9) {
                Image(systemName: wifiSymbol(for: network.signalStrength, active: active))
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(active ? NexusStudioStyle.accent : NexusStudioStyle.muted)
                    .frame(width: 18)
                VStack(alignment: .leading, spacing: 1) {
                    Text(network.name)
                        .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.bright)
                        .lineLimit(1)
                    if let strength = network.signalStrength {
                        Text("SIGNAL \(strength) dBm")
                            .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                            .foregroundStyle(active ? NexusStudioStyle.accent : NexusStudioStyle.muted)
                    }
                }
                Spacer(minLength: 4)
                if network.secure == true {
                    Image(systemName: "lock.fill")
                        .font(.system(size: ShellTypography.nano, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                }
                Image(systemName: active ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(active ? NexusStudioStyle.accent : NexusStudioStyle.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, 10)
            .frame(maxWidth: .infinity)
            .frame(height: 38, alignment: .leading)
            .background(
                active ? NexusStudioStyle.selection : NexusStudioStyle.field,
                in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
            )
            .overlay {
                if active {
                    RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                        .stroke(NexusStudioStyle.accent.opacity(0.62), lineWidth: 0.8)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .disabled(!shell.wifiOn || shell.wifiActionPending)
        .accessibilityValue(active ? "Connected" : "Available")
        .accessibilityHint(active ? "Tap to disconnect" : "Tap to connect")
    }

    private func wifiNexusConnectedHiddenRow() -> some View {
        HStack(spacing: 9) {
            Image(systemName: "wifi")
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(NexusStudioStyle.accent)
                .frame(width: 18)
            VStack(alignment: .leading, spacing: 1) {
                Text("CONNECTED NETWORK")
                    .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.bright)
                    .lineLimit(1)
                Text("SSID HIDDEN BY macOS")
                    .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.accent)
            }
            Spacer(minLength: 4)
            Image(systemName: "checkmark.circle.fill")
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(NexusStudioStyle.accent)
                .frame(width: 18)
        }
        .padding(.horizontal, 10)
        .frame(maxWidth: .infinity)
        .frame(height: 38, alignment: .leading)
        .background(NexusStudioStyle.selection, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(NexusStudioStyle.accent.opacity(0.62), lineWidth: 0.8)
        }
        .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .accessibilityElement(children: .combine)
        .accessibilityLabel("Connected Wi-Fi network")
        .accessibilityValue("SSID hidden by macOS")
    }

    private func bluetoothNexusCard(_ devices: [BluetoothDeviceInfo]) -> some View {
        VStack(alignment: .leading, spacing: 8) {
                HStack(spacing: 8) {
                    Image(systemName: "bluetooth")
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.accent)
                Text("BLUETOOTH & DEVICES")
                    .font(.system(size: ShellTypography.label, weight: .bold, design: .rounded))
                    .foregroundStyle(NexusStudioStyle.bright)
                Spacer(minLength: 0)
                if !devices.isEmpty {
                    Text(bluetoothCountSummary(devices))
                        .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                }
                Button { shell.refreshBluetoothDevices(force: true) } label: {
                    Image(systemName: shell.bluetoothScanning ? "dot.radiowaves.left.and.right" : "arrow.clockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 24, height: 24)
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(NexusStudioStyle.muted)
                .disabled(shell.bluetoothScanning)
            }
            if devices.isEmpty {
                networkEmptyRow(symbol: shell.bluetoothScanning ? "dot.radiowaves.left.and.right" : "bluetooth")
            } else {
                ForEach(devices) { device in
                    bluetoothNexusRow(device)
                }
            }
        }
        .padding(12)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func bluetoothDetailsCard(_ devices: [BluetoothDeviceInfo]) -> some View {
        let nearby = devices.filter(\.nearby).count
        let paired = devices.filter(\.paired).count
        let connected = devices.filter(\.connected).count
        return VStack(alignment: .leading, spacing: Spacing.base) {
            HStack {
                Text("DEVICE MANAGEMENT").nexusLabel()
                Spacer(minLength: 8)
                Text(connected == 0 ? "READY" : "ACTIVE")
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                    .foregroundStyle(connected == 0 ? Theme.muted : Theme.mint)
            }
            HStack(spacing: Spacing.base) {
                nexusDetailTile("PAIRED", String(paired), "link")
                nexusDetailTile("NEARBY", String(nearby), "dot.radiowaves.left.and.right")
                nexusDetailTile("CONNECTED", String(connected), "checkmark.circle")
            }
            HStack(spacing: Spacing.base) {
                nexusActionButton("Bluetooth settings", "gearshape", primary: false) {
                    openSystemSettings("com.apple.BluetoothSettings")
                }
                .frame(maxWidth: .infinity)
                nexusActionButton("Scan again", "arrow.clockwise", primary: false) {
                    shell.refreshBluetoothDevices(force: true)
                }
                .frame(maxWidth: .infinity)
            }
        }
        .padding(Spacing.roomy)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func bluetoothNexusRow(_ device: BluetoothDeviceInfo) -> some View {
        Button { shell.toggleBluetooth(device) } label: {
            HStack(spacing: 9) {
                Circle()
                    .fill(device.connected ? NexusStudioStyle.accent : NexusStudioStyle.muted.opacity(0.45))
                    .frame(width: 6, height: 6)
                Image(systemName: device.connected ? "link" : "bolt.horizontal")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(device.nearby ? NexusStudioStyle.accent : NexusStudioStyle.muted)
                    .frame(width: 16)
                VStack(alignment: .leading, spacing: 1) {
                    Text(device.name)
                        .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.bright)
                        .lineLimit(1)
                    Text(device.connected ? "CONNECTED" : (device.nearby ? "NEARBY" : "PAIRED"))
                        .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                        .foregroundStyle(device.connected ? NexusStudioStyle.accent : NexusStudioStyle.muted)
                }
                Spacer(minLength: 4)
                Image(systemName: device.connected ? "checkmark.circle.fill" : (device.paired ? "circle" : "link.badge.plus"))
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(device.connected ? NexusStudioStyle.accent : NexusStudioStyle.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, 10)
            .frame(maxWidth: .infinity)
            .frame(height: 38, alignment: .leading)
            .background(
                device.connected ? NexusStudioStyle.selection : NexusStudioStyle.field,
                in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
            )
            .overlay {
                if device.connected {
                    RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                        .stroke(NexusStudioStyle.accent.opacity(0.62), lineWidth: 0.8)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .disabled(shell.bluetoothActionsPending.contains(device.address))
        .accessibilityValue(device.connected ? "Connected" : (device.nearby ? "Nearby" : "Paired"))
        .accessibilityHint(device.connected ? "Tap to disconnect" : (device.paired ? "Tap to connect" : "Tap to pair"))
    }

    private func networkEmptyRow(symbol: String) -> some View {
        HStack(spacing: 8) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(NexusStudioStyle.muted)
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 10)
        .frame(maxWidth: .infinity)
        .frame(height: 38, alignment: .leading)
        .background(NexusStudioStyle.field, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
    }

    private func wifiSymbol(for strength: Int?, active: Bool) -> String {
        if active { return "wifi" }
        guard let strength else { return "wifi" }
        if strength >= -55 { return "wifi" }
        if strength >= -70 { return "wifi" }
        return "wifi.exclamationmark"
    }

    private func bluetoothCountSummary(_ devices: [BluetoothDeviceInfo]) -> String {
        let nearby = devices.filter(\.nearby).count
        let connected = devices.filter(\.connected).count
        if nearby == 0 && connected == 0 { return "" }
        if nearby == 0 { return "\(connected) CONNECTED" }
        if connected == 0 { return "\(nearby) NEARBY" }
        return "\(nearby) NEARBY • \(connected) CONNECTED"
    }

    private var overview: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.base) {
                sectionTitle("SYSTEM OVERVIEW")
                HStack(spacing: Spacing.base) {
                    metricPill("CPU", performancePercent(shell.performance.cpuUse), "cpu")
                    metricPill("GPU", performancePercent(shell.performance.gpuUse), "square.stack.3d.up")
                    metricPill("RAM", performancePercent(shell.performance.ramUse), "memorychip")
                    metricPill("DISK", performancePercent(shell.performance.diskUse), "internaldrive")
                }
                // Both cards share one rail. The process list and the three
                // network rows have different intrinsic heights, so constrain
                // their outer shells together rather than letting one side
                // stop short of the other.
                HStack(alignment: .top, spacing: Spacing.base) {
                    VStack(alignment: .leading, spacing: Spacing.snug) {
                        Text("TOP PROCESSES").nexusLabel()
                        if nexus.topProcesses.isEmpty {
                            Text("SAMPLING…")
                                .nexusLabel()
                                .transition(.opacity)
                        } else {
                            ForEach(Array(nexus.topProcesses.prefix(5).enumerated()), id: \.offset) { _, process in
                                Label(process, systemImage: "app.fill")
                                    .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                                    .foregroundStyle(Theme.bright)
                                    .lineLimit(1)
                                    .frame(maxWidth: .infinity, alignment: .leading)
                            }
                            .transition(.opacity)
                        }
                    }
                    .padding(Spacing.roomy)
                    .frame(maxWidth: .infinity, minHeight: 150, maxHeight: 150, alignment: .topLeading)
                    .nexusLayer(cornerRadius: Rounding.large, depth: .card)
                    .animation(ShellMotion.contentIn.animation, value: nexus.topProcesses.isEmpty)

                    VStack(spacing: Spacing.snug) {
                        compactStatus("NETWORK", nexus.networkName, "wifi")
                        compactStatus("LIVE TRAFFIC", "↓ \(nexus.networkDown)  ·  ↑ \(nexus.networkUp)", "arrow.down.arrow.up")
                        compactStatus("LATENCY", nexus.networkLatency, "speedometer")
                    }
                    .padding(Spacing.snug)
                    .frame(maxWidth: .infinity, minHeight: 150, maxHeight: 150, alignment: .center)
                    .nexusLayer(cornerRadius: Rounding.large, depth: .group)
                }
                // Caelestia keeps the calendar in its Dashboard rather than as
                // a bar popout; this used to be a standalone rail popover
                // before moving here to match.
                MiniCalendarCard(model: shell)
                HStack(spacing: Spacing.base) {
                    overviewCard("PALETTE", shell.selectedPalette.title, "paintpalette", destination: .settings)
                    overviewCard("WORKSPACE", "SPACE \(shell.currentWorkspace)", "square.grid.2x2", destination: nil)
                    overviewCard("BATTERY", "\(shell.batteryPercent)%", shell.batterySymbol, destination: nil)
                }
            }
            .padding(.bottom, Spacing.loose)
            .nexusScrollBody()
            .id("nexus-overview-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        // Every Nexus page is its own fresh ScrollView, but SwiftUI does not
        // reliably lay the first one out at content offset zero on the very
        // first appear -- the panel could open with the page already
        // scrolled down a little, clipping "SYSTEM OVERVIEW" (and every
        // page's own title) under the top edge with no way to tell why. Pin
        // every page's default position, not just its initial one.
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-overview-top")
    }

    /// Observatory deliberately lives inside Nexus rather than opening a
    /// second window. It therefore inherits the same ratio, gutters, rounded
    /// surface, page transition, and input model as every other Nexus page.
    /// The cards are read-only by design. Hardware controls live in Audio Lab
    /// so this page stays a quiet diagnostic map rather than another settings
    /// surface.
    private var observatory: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.base) {
                HStack(spacing: Spacing.base) {
                    // Was `("SHELL", "RUNNING", "cpu", true)` -- all four
                    // arguments constant, so the tile could only ever report
                    // RUNNING, which you already knew because you were looking
                    // at it. Uptime is the live figure that tile was pretending
                    // to be, and it is already published for the status bar.
                    observatoryStatusTile("UPTIME", shell.uptime.isEmpty ? macppSystemUptimeText() : shell.uptime, "clock", true)
                    observatoryStatusTile("MODE", currentMacPlusPlusMode, "rectangle.3.group", true)
                    observatoryStatusTile("PALETTE", shell.selectedPalette.title, "paintpalette", true)
                }

                // Keep paired cards on one shared rail. Performance combines
                // snapshots with a history plot while Transports contains two
                // meters, so a shared height preserves the Nexus rhythm as
                // their live values change.
                HStack(alignment: .top, spacing: Spacing.base) {
                    VStack(alignment: .leading, spacing: Spacing.base) {
                        Text("LIVE TRANSPORTS").nexusLabel()
                        transportMeter("AUDIO", shell.bpmLive ? "LIVE  •  \(shell.bpm) BPM" : "IDLE", "waveform.path.ecg", shell.bpmLive)
                        transportMeter("NOTIFICATIONS", "\(shell.notificationCount) QUEUED", "bell.badge", shell.notificationCount > 0)
                    }
                    .padding(Spacing.roomy)
                    .frame(maxWidth: .infinity, minHeight: 176, maxHeight: 176, alignment: .topLeading)
                    .nexusLayer(cornerRadius: Rounding.large, depth: .group)

                    VStack(alignment: .leading, spacing: Spacing.base) {
                        HStack {
                            Text("PERFORMANCE").nexusLabel()
                            Spacer()
                            Text(nexus.metricsHistoryStatus)
                                .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                                .foregroundStyle(Theme.muted)
                        }
                        HStack(spacing: Spacing.tight) {
                            compactMetric("CPU", "\(performancePercent(shell.performance.cpuUse))%", Theme.accent)
                            compactMetric("RAM", "\(performancePercent(shell.performance.ramUse))%", Theme.ice)
                        }
                        if nexus.metricsTrend.count > 1 {
                            MacPlusPlusMetricsTrendView(points: nexus.metricsTrend)
                                .frame(height: 52)
                                .transition(.opacity)
                        } else {
                            Image(systemName: "chart.xyaxis.line")
                            .font(.system(size: ShellIcon.small, weight: .medium, design: .rounded))
                            .foregroundStyle(Theme.muted)
                            .frame(maxWidth: .infinity, minHeight: 52, alignment: .center)
                            .transition(.opacity)
                        }
                    }
                    .padding(Spacing.roomy)
                    .frame(maxWidth: .infinity, minHeight: 176, maxHeight: 176, alignment: .topLeading)
                    .nexusLayer(cornerRadius: Rounding.large, depth: .group)
                    .animation(ShellMotion.contentIn.animation, value: nexus.metricsTrend.count > 1)
                }

                VStack(alignment: .leading, spacing: Spacing.base) {
                    HStack {
                        Text("SCREEN TIME · 7D").nexusLabel()
                        Spacer()
                        Text(nexus.screenTimeStatus)
                            .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                            .foregroundStyle(Theme.muted)
                    }
                    ForEach(nexus.screenTimeEntries) { entry in
                        HStack(spacing: Spacing.base) {
                            Image(systemName: "app.fill")
                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.accent)
                                .frame(width: 18)
                            Text(entry.appName).nexusValue().lineLimit(1)
                            Spacer(minLength: 4)
                            Text(String(format: "%.1fh  %d%%", entry.hours, Int(entry.percent.rounded())))
                                .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.muted)
                        }
                        .frame(height: 24)
                    }
                }
                .padding(Spacing.roomy)
                .nexusLayer(cornerRadius: Rounding.large, depth: .group)

                VStack(alignment: .leading, spacing: Spacing.base) {
                    HStack {
                        Text("RUNTIME OWNERS").nexusLabel()
                        Spacer()
                        if nexus.runtimeRows.contains(where: { !$0.healthy }) {
                            Button { nexus.repairRuntimeOwners() } label: {
                                // "REPAIR SAFE" read as an assurance ("repair
                                // is safe") rather than the action it performs,
                                // which is restarting the helpers this list
                                // shows as unowned.
                                Text(nexus.repairingRuntime ? "Repairing…" : "Repair")
                                    .font(.system(size: ShellTypography.nano, weight: .semibold, design: .rounded))
                                    .frame(height: 24)
                                    .padding(.horizontal, Spacing.base)
                                    .contentShape(Capsule())
                            }
                            .buttonStyle(MicroButtonStyle())
                            .disabled(nexus.repairingRuntime)
                            .foregroundStyle(Theme.onAccent)
                            .background(Theme.accent, in: Capsule())
                        } else {
                            Text("ALL RUNNING").nexusLabel()
                        }
                    }
                    ForEach(nexus.runtimeRows) { row in
                        HStack(spacing: Spacing.base) {
                            Image(systemName: row.symbol)
                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                .foregroundStyle(row.healthy ? Theme.accent : Theme.muted)
                                .frame(width: 18)
                            Text(row.title).nexusValue().lineLimit(1)
                            Spacer(minLength: 4)
                            Text(row.detail)
                                .font(.system(size: ShellTypography.micro, weight: .medium, design: .rounded))
                                .foregroundStyle(row.healthy ? Theme.mint : Theme.muted)
                        }
                        .frame(height: 28)
                    }
                    if nexus.runtimeRows.isEmpty {
                        Text("CHECKING…").nexusLabel().frame(height: 28)
                    }
                }
                .padding(Spacing.roomy)
                .nexusLayer(cornerRadius: Rounding.large, depth: .group)

                VStack(alignment: .leading, spacing: Spacing.base) {
                    HStack {
                        Text("CAPABILITIES & PERMISSIONS").nexusLabel()
                        Spacer()
                        Text(nexus.capabilityStatus)
                            .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                            .foregroundStyle(nexus.capabilitiesHealthy ? Theme.mint : Theme.muted)
                    }
                    ForEach(nexus.capabilityRows) { row in
                        HStack(spacing: Spacing.base) {
                            Image(systemName: row.symbol)
                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                .foregroundStyle(row.healthy ? Theme.accent : Theme.muted)
                                .frame(width: 18)
                            VStack(alignment: .leading, spacing: Spacing.none) {
                                HStack(spacing: Spacing.tight) {
                                    Text(row.title).nexusValue().lineLimit(1)
                                    if row.required {
                                        Circle().fill(Theme.accent.opacity(0.65)).frame(width: 3, height: 3)
                                    }
                                }
                                Text(row.evidence)
                                    .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                                    .foregroundStyle(Theme.muted)
                                    .lineLimit(1)
                            }
                            Spacer(minLength: 5)
                            Text(row.status)
                                .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                                .foregroundStyle(row.healthy ? Theme.mint : Theme.muted)
                        }
                        .frame(height: 34)
                    }
                    if nexus.capabilityRows.isEmpty {
                        Text("CHECKING…").nexusLabel().frame(height: 34)
                    }
                }
                .padding(Spacing.roomy)
                .nexusLayer(cornerRadius: Rounding.large, depth: .group)

            }
            .padding(.bottom, Spacing.loose)
            .nexusScrollBody()
            .id("nexus-observatory-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-observatory-top")
    }

    private var currentMacPlusPlusMode: String {
        if let raw = try? String(contentsOfFile: NSHomeDirectory() + "/.local/state/macpp/nonwork-mode", encoding: .utf8) { // macpp:silent-ok absent mode state uses WORK
            let value = raw.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
            if value == "GAME" || value == "PERFORMANCE" { return value }
        }
        return "WORK"
    }

