    // Scrolls, like overview/capture/settings already do. This page stacks to
    // roughly 420pt (routing card, output route, input route, EQ header,
    // presets, and the 94pt band strip) against a 364pt viewport, and the
    // Nexus content region hard-clips at that height -- so without a
    // ScrollView the bottom of the EQ was cut off with no way to reach it.
    private var audio: some View {
        ScrollView(.vertical, showsIndicators: false) {
        VStack(alignment: .leading, spacing: Spacing.base) {
            sectionTitle("AUDIO LAB")

            VStack(spacing: Spacing.base) {
                HStack(spacing: Spacing.base) {
                    HStack(spacing: Spacing.base) {
                        Button { shell.toggleMute() } label: {
                            Image(systemName: shell.muted ? "speaker.slash.fill" : "speaker.wave.2.fill")
                                .font(.system(size: ShellIcon.medium, weight: .bold, design: .rounded))
                                .frame(width: 44, height: 44)
                                .contentShape(Rectangle())
                        }
                        .buttonStyle(MicroButtonStyle())
                        .foregroundStyle(shell.muted ? Theme.muted : Theme.accent)
                        VStack(alignment: .leading, spacing: Spacing.none) {
                            Text("OUTPUT").nexusLabel()
                            Text(shell.muted ? "MUTED" : "\(Int(shell.volume * 100))%").nexusValue()
                        }
                        Slider(value: Binding(get: { shell.volume }, set: { shell.setVolume($0) }), in: 0...1)
                            .tint(Theme.accent)
                    }
                    .frame(maxWidth: .infinity)

                    VStack(alignment: .leading, spacing: Spacing.tight) {
                        HStack {
                            Text("BALANCE").nexusLabel()
                            Spacer()
                            Text(balanceLabel).nexusValue()
                        }
                        Slider(value: Binding(get: { nexus.outputBalance }, set: { nexus.setOutputBalance($0) }), in: 0...1)
                            .tint(Theme.accent)
                            .disabled(!nexus.balanceAvailable)
                    }
                    .frame(width: 148)
                }

                CaelestiaDivider()

                HStack(spacing: Spacing.base) {
                    audioStateControl(
                        title: "FOCUS",
                        detail: !shell.focusControlAvailable
                            ? "SETUP REQUIRED"
                            : (shell.focusStateAvailable
                                ? (shell.focusEnabled ? shell.focusName : "OFF")
                                : "STATE UNAVAILABLE"),
                        symbol: shell.focusEnabled ? "moon.fill" : "moon",
                        active: shell.focusEnabled,
                        available: !shell.focusMutationInFlight,
                        action: shell.toggleFocus
                    )
                    audioStateControl(
                        title: "MICROPHONE",
                        detail: shell.microphoneMuteAvailable
                            ? (shell.microphoneMuted ? "MUTED" : "LIVE")
                            : "MUTE UNAVAILABLE",
                        symbol: shell.microphoneMuted ? "mic.slash.fill" : "mic.fill",
                        active: shell.microphoneMuted,
                        available: shell.microphoneMuteAvailable,
                        action: shell.toggleMicrophoneMute
                    )
                }
            }
            .nexusCard()

            audioRoutingCard

        }
        // The trailing Spacer that used to sit here is gone: inside a
        // ScrollView a Spacer has infinite ideal height, which would make the
        // scrollable content grow without bound.
        .nexusScrollBody()
        .id("nexus-audio-top")
        }
        // The audio page has several fixed-height cards separated by gaps and
        // also contains a horizontal route strip. Make the vertical page
        // viewport itself a hit target so a wheel/trackpad gesture begun in a
        // gap or beside that strip still belongs to this ScrollView instead
        // of falling through to the desktop below the fixed Nexus surface.
        .contentShape(Rectangle())
        .scrollIndicators(.never)
        // Likewise for the page itself: when the content happens to fit there
        // is nothing to scroll, and rubber-banding an already-complete page
        // reads as the surface being loose rather than responsive.
        .scrollBounceBehavior(.basedOnSize)
        // Audio sampling is no longer requested here. Two pages need it (this
        // one and Media), and having each toggle it in onAppear/onDisappear
        // meant the result depended on an ordering SwiftUI does not guarantee:
        // when the outgoing page's onDisappear ran *after* the incoming page's
        // onAppear, the incoming page had its sampling switched off underneath
        // it. MacPlusPlusNexusView now owns the decision -- see reactiveAudioPages.
        .onAppear { nexus.refreshAudio() }
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-audio-top")
    }

    private func audioStateControl(
        title: String,
        detail: String,
        symbol: String,
        active: Bool,
        available: Bool,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: Spacing.base) {
                ZStack {
                    Circle().fill(active ? Theme.accent.opacity(0.20) : Theme.layerTile)
                    Image(systemName: symbol)
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(active ? Theme.accent : Theme.muted)
                }
                .frame(width: 28, height: 28)
                VStack(alignment: .leading, spacing: Spacing.none) {
                    Text(title).nexusLabel()
                    Text(detail)
                        .font(.system(size: ShellTypography.micro, weight: .medium, design: .rounded))
                        .foregroundStyle(active ? Theme.accent : Theme.bright)
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                }
                Spacer(minLength: 3)
                Circle()
                    .fill(active ? Theme.accent : Theme.muted.opacity(0.35))
                    .frame(width: 6, height: 6)
            }
            .padding(.horizontal, Spacing.base)
            .frame(maxWidth: .infinity, minHeight: 40, maxHeight: 40)
            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .disabled(!available)
        // This opacity dim was a real, correctly-computed "this control has
        // no hardware to act on" signal (e.g. a Bluetooth mic input with no
        // settable CoreAudio mute property), not a race -- but revealed by
        // the popout's own open animation, it read the same as the depth
        // flicker above. `.disabled` above still blocks the tap; the card
        // no longer visually announces the unavailability in advance.
        // `nexusLayer`'s fill *and* border both key off `depth`, so an
        // active-driven depth here was the same whole-card wash bug as the
        // system audio routes card above -- just reached through a different
        // helper, which is why fixing that card didn't touch this one. The
        // icon circle, detail text, and dot already carry the
        // state at a size too small to read as a flicker; the card itself
        // now holds one fixed tone.
        .nexusLayer(cornerRadius: Rounding.normal, depth: .tile)
        .animation(ShellMotion.contentIn.animation, value: active)
    }

    /// This is the single canonical system audio route selector. Every live
    /// output (including named AirPlay/HomePod routes) and every input is a
    /// concrete source button; selecting a row immediately asks macOS to make
    /// that source current.
    private var audioRoutingCard: some View {
        VStack(alignment: .leading, spacing: Spacing.base) {
            HStack(spacing: Spacing.base) {
                Image(systemName: "point.3.connected.trianglepath.dotted")
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
                Text("SYSTEM AUDIO ROUTES").nexusValue()
                Spacer()
                Button { nexus.refreshAudio() } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 30, height: 30)
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(Theme.muted)
            }

            Text("OUTPUT ROUTES").nexusLabel()
            if nexus.outputDevices.isEmpty {
                audioSourceEmpty("No live output routes", symbol: "speaker.slash")
            } else {
                VStack(spacing: Spacing.tight) {
                    ForEach(nexus.outputDevices, id: \.identity) { device in
                        audioSourceButton(
                            title: device.name,
                            detail: audioOutputDetail(device),
                            symbol: device.isAirPlayRoute ? "airplayaudio" : "hifispeaker.fill",
                            selected: nexus.isSelectedOutputDevice(device)
                        ) {
                            nexus.selectOutputDevice(device)
                        }
                    }
                }
            }

            CaelestiaDivider()
                .padding(.vertical, Spacing.hairline)

            Text("INPUT ROUTES").nexusLabel()
            if nexus.inputDevices.isEmpty {
                audioSourceEmpty("No live input routes", symbol: "mic.slash")
            } else {
                VStack(spacing: Spacing.tight) {
                    ForEach(nexus.inputDevices) { device in
                        audioSourceButton(
                            title: device.name,
                            detail: audioInputDetail(device),
                            symbol: "mic.fill",
                            selected: device.id == nexus.selectedInputDeviceID
                        ) {
                            nexus.selectInputDevice(device)
                        }
                    }
                }
            }
        }
        .padding(Spacing.roomy)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func audioSourceButton(
        title: String,
        detail: String,
        symbol: String,
        selected: Bool,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: Spacing.base) {
                ZStack {
                    Circle().fill(selected ? Theme.accent.opacity(0.18) : Theme.layerTile)
                    Image(systemName: symbol)
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(selected ? Theme.accent : Theme.muted)
                }
                .frame(width: 28, height: 28)
                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text(title)
                        .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(2)
                        .minimumScaleFactor(0.82)
                        .allowsTightening(true)
                    if !detail.isEmpty {
                        Text(detail)
                            .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                            .foregroundStyle(Theme.muted)
                            .lineLimit(1)
                    }
                }
                Spacer(minLength: 6)
                Image(systemName: selected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(selected ? Theme.accent : Theme.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, Spacing.base)
            .padding(.vertical, Spacing.snug)
            .frame(minHeight: 40)
            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        // The card fill and border used to key off `selected`, which is
        // exactly the value `refreshAudio`'s AirPlay merge race (see its own
        // comment) and the fresh-vs-stale device list yank around during a
        // refresh -- so a route's card visibly swapped between grey and dark
        // independent of anything the user did. The whole row is the route
        // selector now; selection tint and a checkmark carry the state while
        // making the click target feel like one card.
        .background(selected ? NexusStudioStyle.selection : Theme.layerTile, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            if selected {
                RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                    .stroke(Theme.accent.opacity(0.62), lineWidth: 0.8)
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .accessibilityValue(selected ? "Current" : "Available")
        .accessibilityHint("Tap to route audio here")
    }

