    private func audioOutputDetail(_ device: SystemOutputAudio.Device) -> String {
        if device.isAirPlayRoute { return "AIRPLAY" }
        guard device.sampleRate > 0 else { return "" }
        return String(format: "%.1f KHZ", device.sampleRate / 1000)
    }

    private func audioInputDetail(_ device: SystemInputAudio.Device) -> String {
        guard device.sampleRate > 0 else { return "" }
        return String(format: "%.1f KHZ", device.sampleRate / 1000)
    }

    private var balanceLabel: String {
        guard nexus.balanceAvailable else { return "N/A" }
        if abs(nexus.outputBalance - 0.5) < 0.015 { return "CENTER" }
        return nexus.outputBalance < 0.5
            ? "L \(Int((0.5 - nexus.outputBalance) * 200))"
            : "R \(Int((nexus.outputBalance - 0.5) * 200))"
    }

    private var eqFrequencies: [String] { ["31", "62", "125", "250", "500", "1K", "2K", "4K", "8K", "16K"] }

    private func eqBand(index: Int, label: String) -> some View {
        let gain = nexus.eqBands.indices.contains(index) ? nexus.eqBands[index] : 0
        let spectrumIndex = min(shell.levels.count - 1, Int(Double(index) * Double(max(1, shell.levels.count - 1)) / 9.0))
        let energy = shell.levels.indices.contains(spectrumIndex) ? shell.levels[spectrumIndex] : 0
        return VStack(spacing: Spacing.hairline) {
            Text(String(format: "%+.0f", gain))
                .font(.system(size: ShellTypography.nano, weight: .heavy, design: .rounded))
                .foregroundStyle(abs(gain) > 0.1 ? Theme.bright : Theme.muted)
            GeometryReader { geometry in
                    let normalized = (gain + 12) / 24
                let track = RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous)
                ZStack {
                    track.fill(Theme.tile)
                    // Keep the live meter on the same continuous path as its
                    // track. A bare Rectangle here was clipped to the track,
                    // but its square source edges could still show through
                    // during a height animation on some compositor frames.
                    track
                        .fill(Theme.accent.opacity(0.16 + energy * 0.6))
                        .frame(height: geometry.size.height * energy)
                        .frame(maxHeight: .infinity, alignment: .bottom)
                    Circle()
                        .fill(Theme.accent)
                        .frame(width: 5, height: 5)
                        .position(
                            x: geometry.size.width / 2,
                            y: min(geometry.size.height - 2.5, max(2.5, geometry.size.height * (1 - normalized)))
                        )
                }
                .contentShape(Rectangle())
                .gesture(
                    DragGesture(minimumDistance: 0)
                        .onChanged { value in
                            let position = 1 - min(1, max(0, value.location.y / max(1, geometry.size.height)))
                            nexus.previewEQBand(index, gain: position * 24 - 12)
                        }
                        .onEnded { value in
                            let position = 1 - min(1, max(0, value.location.y / max(1, geometry.size.height)))
                            nexus.setEQBand(index, gain: position * 24 - 12)
                        }
                )
            }
            .frame(height: 62)
            Text(label)
                .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.muted)
        }
        .frame(maxWidth: .infinity)
        .frame(height: 94)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("\(label) hertz equalizer band")
        .accessibilityValue(String(format: "%+.0f decibels", gain))
        .accessibilityAdjustableAction { direction in
            switch direction {
            case .increment: nexus.setEQBand(index, gain: gain + 1)
            case .decrement: nexus.setEQBand(index, gain: gain - 1)
            @unknown default: break
            }
        }
        .help("\(label) Hz · \(String(format: "%+.0f", gain)) dB")
    }

    private var eqPreampControl: some View {
        let gain = nexus.eqPreamp
        return VStack(spacing: Spacing.hairline) {
            Text(String(format: "%+.0f", gain))
                .font(.system(size: ShellTypography.nano, weight: .heavy, design: .rounded))
                .foregroundStyle(abs(gain) > 0.1 ? Theme.bright : Theme.muted)
            GeometryReader { geometry in
                let normalized = (gain + 12) / 18
                let track = RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous)
                ZStack {
                    track.fill(Theme.tile)
                    // Match the fill to the continuous EQ track instead of
                    // relying on a rectangular child plus a second clip.
                    track
                        .fill(Theme.mint.opacity(0.20))
                        .frame(height: geometry.size.height * max(0, normalized))
                        .frame(maxHeight: .infinity, alignment: .bottom)
                    Circle()
                        .fill(Theme.mint)
                        .frame(width: 5, height: 5)
                        .position(
                            x: geometry.size.width / 2,
                            y: min(geometry.size.height - 2.5, max(2.5, geometry.size.height * (1 - normalized)))
                        )
                }
                .contentShape(Rectangle())
                .gesture(
                    DragGesture(minimumDistance: 0)
                        .onChanged { value in
                            let position = 1 - min(1, max(0, value.location.y / max(1, geometry.size.height)))
                            nexus.previewEQPreamp(position * 18 - 12)
                        }
                        .onEnded { value in
                            let position = 1 - min(1, max(0, value.location.y / max(1, geometry.size.height)))
                            nexus.setEQPreamp(position * 18 - 12)
                        }
                )
            }
            .frame(height: 62)
            Text("PREAMP")
                .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                .foregroundStyle(Theme.muted)
        }
        .frame(width: 36, height: 94)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("Equalizer preamp")
        .accessibilityValue(String(format: "%+.0f decibels", gain))
        .accessibilityAdjustableAction { direction in
            switch direction {
            case .increment: nexus.setEQPreamp(gain + 1)
            case .decrement: nexus.setEQPreamp(gain - 1)
            @unknown default: break
            }
        }
        .help("Preamp · \(String(format: "%+.0f", gain)) dB")
    }

    private var system: some View {
        GeometryReader { geometry in
            VStack(alignment: .leading, spacing: Spacing.loose) {
                sectionTitle("SYSTEM SETTINGS")
                LazyVGrid(columns: nexusColumns, spacing: Spacing.roomy) {
                    settingsCard("WI-FI", "wifi", "com.apple.wifi-settings-extension")
                    settingsCard("BLUETOOTH", "point.3.connected.trianglepath.dotted", "com.apple.BluetoothSettings")
                    settingsCard("DISPLAYS", "display", "com.apple.Displays-Settings.extension")
                    settingsCard("BATTERY", "battery.75percent", "com.apple.Battery-Settings.extension")
                    settingsCard("APPEARANCE", "circle.lefthalf.filled", "com.apple.Appearance-Settings.extension")
                    settingsCard("PRIVACY", "hand.raised", "com.apple.settings.PrivacySecurity.extension")
                    settingsCard("KEYBOARD", "keyboard", "com.apple.Keyboard-Settings.extension")
                    settingsCard("TRACKPAD", "rectangle.and.hand.point.up.left", "com.apple.Trackpad-Settings.extension")
                }
                systemStatusCard
                HStack(spacing: Spacing.base) {
                    nexusActionButton("Check updates", "arrow.triangle.2.circlepath", primary: false) {
                        withAnimation(ShellMotion.nexusPageSwitch.animation) { nexus.page = .updates }
                    }
                    .frame(maxWidth: .infinity)
                    nexusActionButton("System Settings", "gearshape", primary: false) {
                        openSystemSettings(nil)
                    }
                    .frame(maxWidth: .infinity)
                }
                Spacer()
            }
        }
    }

    private var systemStatusCard: some View {
        let version = ProcessInfo.processInfo.operatingSystemVersionString
        let workspace = "SPACE " + String(shell.currentWorkspace)
        let palette = shell.selectedPalette.title.capitalized
        return VStack(alignment: .leading, spacing: Spacing.base) {
            HStack {
                Text("SHELL STATUS").nexusLabel()
                Spacer(minLength: 8)
                Text(shell.shellBorderEnabled ? "CONTOUR ON" : "CONTOUR OFF")
                    .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                    .foregroundStyle(shell.shellBorderEnabled ? Theme.mint : Theme.muted)
            }
            HStack(spacing: Spacing.base) {
                nexusDetailTile("MACOS", version, "apple.logo")
                nexusDetailTile("WORKSPACE", workspace, "square.grid.2x2")
                nexusDetailTile("PALETTE", palette, "paintpalette")
            }
        }
        .padding(Spacing.roomy)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private var capture: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.loose) {
                sectionTitle("UTILITIES")
                LazyVGrid(columns: nexusColumns, spacing: Spacing.roomy) {
                    actionCard("FULL DISPLAY", "display", { runCapture("screen") })
                    actionCard("SELECT AREA", "viewfinder", { runCapture("area") })
                    actionCard("SELECT WINDOW", "macwindow", { runCapture("window") })
                    actionCard("RECORD", "record.circle", { runCapture("record") })
                }
                networkSpeedTool
                HStack(spacing: Spacing.base) {
                    nexusToggle("CURSOR", "cursorarrow", isOn: binding(\.includeCursor))
                    nexusToggle("MICROPHONE", "mic", isOn: binding(\.recordMicrophone))
                }
                HStack(spacing: Spacing.roomy) {
                    Image(systemName: "folder").foregroundStyle(Theme.accent)
                    VStack(alignment: .leading, spacing: Spacing.hairline) {
                        Text("SAVE LOCATION").nexusLabel()
                        Text(nexus.configuration.captureDirectory).nexusValue().lineLimit(1)
                    }
                    Spacer()
                    nexusActionButton("Open", "arrow.up.forward.app", primary: false) { nexus.revealCaptureDirectory() }
                }.nexusCard()
            }
            .padding(.bottom, Spacing.loose)
            .nexusScrollBody()
            .id("nexus-capture-top")
        }
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-capture-top")
    }

    private var networkSpeedTool: some View {
        VStack(spacing: Spacing.base) {
            HStack(spacing: Spacing.base) {
                Image(systemName: "speedometer")
                    .font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
                    .frame(width: 22)

                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text("NETWORK SPEED").nexusValue()
                    Text(nexus.speedTestRunning ? "MEASURING CONNECTION…" : nexus.speedTestLastRun)
                        .nexusLabel()
                        .lineLimit(1)
                }

                Spacer(minLength: 4)

                ZStack {
                    if nexus.speedTestRunning {
                        ProgressView()
                            .controlSize(.small)
                            .tint(Theme.accent)
                            .frame(width: 54, height: 44)
                            .transition(.opacity)
                    } else {
                        nexusActionButton(
                            nexus.speedTestLastRun == "NOT TESTED" ? "RUN" : "AGAIN",
                            "play.fill",
                            primary: true
                        ) {
                            nexus.runNetworkSpeedTest()
                        }
                        .transition(.opacity)
                    }
                }
                .frame(minWidth: 54, minHeight: 44)
                .animation(ShellMotion.contentIn.animation, value: nexus.speedTestRunning)
            }

            HStack(spacing: Spacing.base) {
                speedResult("DOWNLOAD", nexus.speedTestDownload)
                speedResult("UPLOAD", nexus.speedTestUpload)
                speedResult("LATENCY", nexus.speedTestLatency)
            }
        }
        .padding(.horizontal, Spacing.roomy)
        .padding(.vertical, Spacing.base)
        .frame(maxWidth: .infinity)
        .frame(height: 104)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func speedResult(_ title: String, _ value: String) -> some View {
        VStack(alignment: .leading, spacing: Spacing.hairline) {
            Text(title).nexusLabel()
            Text(value)
                .nexusValue()
                .lineLimit(1)
                .minimumScaleFactor(0.72)
                .contentTransition(.numericText())
        }
        .padding(.horizontal, Spacing.base)
        .frame(maxWidth: .infinity, minHeight: 38, alignment: .leading)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .tile)
        .animation(ShellMotion.valueChange.animation, value: value)
    }

    /// Cycles automatic -> spotify -> active app, mirroring the top bar's chip.
    private var nexusMediaSourceChip: some View {
        let title: String = {
            switch shell.preferredMediaSource {
            case "spotify": return "Spotify"
            case "system": return "ACTIVE APP"
            default: return "Auto"
            }
        }()
        let next: String = {
            switch shell.preferredMediaSource {
            case "automatic": return "spotify"
            case "spotify": return "system"
            default: return "automatic"
            }
        }()
        return Button { shell.selectMediaSource(next) } label: {
            HStack(spacing: Spacing.tight) {
                Image(systemName: "arrow.triangle.2.circlepath")
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                Text(title)
                    .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                    .lineLimit(1)
            }
            .foregroundStyle(Theme.muted)
            .padding(.horizontal, Spacing.snug)
            .frame(height: 24)
            .background(Theme.layerTile.opacity(0.55), in: Capsule())
            .overlay(Capsule().stroke(Theme.seam.opacity(0.22), lineWidth: 0.5))
            .contentShape(Capsule())
        }
        .buttonStyle(.plain)
        .help("Choose what the media card displays")
    }

    private var media: some View {
        VStack(alignment: .leading, spacing: Spacing.roomy) {
            sectionTitle("ADVANCED MEDIA")
            // The disc scales from the same authored geometry as the compact
            // media surfaces. 128pt gives the artwork enough visual weight
            // without stealing the lower half of the page from lyrics and the
            // queue tile.
            HStack(spacing: Spacing.large) {
                ReactiveAlbumDisc(
                    media: shell.media,
                    levels: shell.levels,
                    active: shell.media.playing,
                    diameter: Self.advancedMediaDiscDiameter
                )
                .frame(width: Self.advancedMediaDiscDiameter, height: Self.advancedMediaDiscDiameter)

                VStack(alignment: .leading, spacing: Spacing.small) {
                    SeamlessMarquee(
                        text: shell.media.title.isEmpty
                            ? ""
                            : loopingMediaText(shell.media.title, viewport: 280),
                        fontSize: 15,
                        speed: 20,
                        active: !shell.media.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                        wrapGap: false
                    )
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .frame(height: 24)

                    HStack(spacing: Spacing.base) {
                        if !shell.media.artist.isEmpty {
                            // The artist is the flexible member of this row;
                            // source and tempo remain readable instead of
                            // forcing the card wider than its page gutter.
                            Text(shell.media.artist)
                                .font(.system(size: ShellTypography.value, weight: .medium, design: .rounded))
                                .foregroundStyle(Theme.muted)
                                .lineLimit(1)
                                .minimumScaleFactor(0.78)
                                .layoutPriority(-1)
                        }
                        Spacer(minLength: 0)
                        // Same source control the top bar carries, so the two
                        // media surfaces stay in step.
                        nexusMediaSourceChip
                        tempoBadge
                    }

                    // Keep the transport cluster centred in the metadata
                    // column while leaving the title and artist left-aligned.
                    // The five controls work for both seek-capable and
                    // track-based sources through the shared media action path.
                    HStack(spacing: Spacing.small) {
                        mediaControl("gobackward.15") { shell.mediaAction("backward") }
                        mediaControl("backward.fill") { shell.mediaAction("previous") }
                        mediaControl(shell.media.playing ? "pause.fill" : "play.fill", primary: true) { shell.mediaAction("playpause") }
                        mediaControl("forward.fill") { shell.mediaAction("next") }
                        mediaControl("goforward.15") { shell.mediaAction("forward") }
                    }
                    .frame(maxWidth: .infinity, alignment: .center)

                    if shell.media.durationKnown || shell.media.isLive {
                        HStack(spacing: Spacing.base) {
                            Text(nexusMediaTime(shell.media.position))
                            GeometryReader { geo in
                                ZStack(alignment: .leading) {
                                    Capsule().fill(Theme.sliderTrack)
                                    if shell.media.durationKnown {
                                        Capsule().fill(Theme.accent)
                                            .frame(width: max(2, geo.size.width * min(1, max(0, shell.media.progress))))
                                    } else {
                                        // A live stream has elapsed time but no
                                        // meaningful fractional progress. Keep
                                        // the rail alive without pretending its
                                        // short accent segment is seekable.
                                        Capsule().fill(Theme.accent)
                                            .frame(width: 28)
                                    }
                                }
                            }
                            .frame(height: 4)
                            Text(shell.media.isLive ? "LIVE" : nexusMediaTime(shell.media.duration))
                        }
                        .font(.system(size: ShellTypography.label, weight: .medium, design: .rounded))
                        .monospacedDigit()
                        .foregroundStyle(Theme.muted)
                        .animation(ShellMotion.valueChange.animation, value: shell.media.progress)
                    }
                }
                .frame(maxWidth: .infinity, minHeight: Self.advancedMediaDiscDiameter, alignment: .leading)
            }
            .frame(maxWidth: .infinity)
            .nexusCard()
            HStack(alignment: .top, spacing: Spacing.base) {
                ZStack {
                    if nexus.lyricsLoading {
                        ProgressView()
                            .tint(Theme.accent)
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                            .transition(.opacity)
                    } else if !nexus.syncedLyrics.isEmpty {
                        synchronizedLyrics
                            .transition(.opacity)
                    } else if nexus.lyrics.isEmpty {
                        VStack(spacing: Spacing.base) {
                            Image(systemName: "quote.bubble").font(.system(size: ShellIcon.hero)).foregroundStyle(Theme.muted)
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                        .transition(.opacity)
                    } else {
                        ScrollView(.vertical, showsIndicators: false) {
                            Text(nexus.lyrics).font(.system(size: ShellTypography.title, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.bright).lineSpacing(7).frame(maxWidth: .infinity, alignment: .leading)
                                // Short lines leave the right-hand side of this block
                                // undrawn; the hit shape makes the whole column
                                // scrollable rather than only the text itself.
                                .contentShape(Rectangle())
                        }
                        .scrollIndicators(.never)
                        .padding(Spacing.loose)
                        .transition(.opacity)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .nexusCard()

                // Keep the queue face visible on Advanced Media instead of
                // making it available only through the compact media flip card.
                // This reads the same published queue state as regular Media;
                // the coordinator remains the single owner of queue polling.
                SpotifyNextTrackView(
                    track: advancedMediaNextTrack,
                    status: advancedMediaNextStatus,
                    providerLabel: advancedMediaProvider.label,
                    transcriptAvailable: !shell.media.transcriptURL.isEmpty,
                    onConnect: shell.connectSpotifyQueue,
                    compact: true
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                .nexusLayer(cornerRadius: Rounding.large, depth: .card)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .animation(ShellMotion.contentIn.animation, value: lyricsContentPhase)
            HStack(spacing: Spacing.tight) {
                mediaChip("Refresh", symbol: "arrow.clockwise") {
                    nexus.forceRefreshLyrics(for: shell.media)
                }
                mediaOpenButton(
                    "Open \(shell.mediaOwnerApplication?.uppercased() ?? "SOURCE")",
                    action: {
                        guard let application = shell.mediaOwnerApplication else {
                            shell.onStateToast?(MacPlusPlusStateToast(
                                title: "Media Source Unavailable",
                                detail: "The current system media session does not expose an owning app",
                                symbol: "questionmark.app"
                            ))
                            return
                        }
                        shell.open(application)
                    }
                )
                .disabled(shell.mediaOwnerApplication == nil)
                mediaSourceButton("Auto", source: "automatic", symbol: "sparkles")
                mediaSourceButton("Spotify", source: "spotify", symbol: "music.note")
                mediaSourceButton("System", source: "system", symbol: "macwindow")
            }
            .frame(maxWidth: .infinity)
        }
    }

    private var advancedMediaProvider: MediaProvider {
        MediaProvider.resolve(shell.media)
    }

    private var advancedMediaNextTrack: MediaNextItem? {
        advancedMediaProvider == .spotify ? shell.spotifyNextTrack : shell.media.upNext
    }

    private var advancedMediaNextStatus: SpotifyQueueStatus {
        advancedMediaProvider == .spotify
            ? shell.spotifyQueueStatus
            : (shell.media.upNext == nil ? .unavailable : .ready)
    }

    private var synchronizedLyrics: some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(spacing: Spacing.roomy) {
                    ForEach(nexus.syncedLyrics) { line in
                        let active = line.id == activeLyricID
                        Text(line.text)
                            .font(.system(size: active ? 15 : 12.5, weight: active ? .heavy : .semibold, design: .rounded))
                            .foregroundStyle(active ? Theme.accent : Theme.muted)
                            .frame(maxWidth: .infinity, alignment: .center)
                            .multilineTextAlignment(.center)
                            .id(line.id)
                    }
                }
                .padding(.vertical, Spacing.loose).padding(.horizontal, Spacing.roomy)
                // Lyric lines are spaced text with nothing drawn between them,
                // so the gaps swallowed the scroll gesture the same way the
                // card lists did.
                .frame(maxWidth: .infinity)
                .contentShape(Rectangle())
            }
            .scrollIndicators(.never)
            .onChange(of: activeLyricID) { _, lyricID in
                guard let lyricID else { return }
                withAnimation(ShellMotion.panelSwitch.animation) { proxy.scrollTo(lyricID, anchor: .center) }
            }
        }
    }

    private var activeLyricID: UUID? {
        nexus.syncedLyrics.last(where: { $0.time <= shell.media.position + 0.08 })?.id
    }

    /// A coarse content phase, deliberately separate from lyric timing. Only
    /// loading/source availability changes crossfade; active-line scrolling
    /// keeps its existing page-switch animation and live cadence.
    private var lyricsContentPhase: Int {
        if nexus.lyricsLoading { return 0 }
        if !nexus.syncedLyrics.isEmpty { return 1 }
        if nexus.lyrics.isEmpty { return 2 }
        return 3
    }

    // Keep the transport cluster visually substantial without letting five
    // fixed controls dictate the card's width. The metadata column is
    // intentionally flexible, so this row must fit inside it on the authored
    // Nexus canvas and then scale as one unit on a short display.
    private func mediaControl(_ symbol: String, primary: Bool = false, action: @escaping () -> Void) -> some View {
        let size: CGFloat = primary ? 38 : 32
        return Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: 12 * mediaGlyphScale(symbol), weight: .bold, design: .rounded))
                .frame(width: size, height: size)
                .contentShape(Circle())
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(primary ? Theme.surface : Theme.bright)
        .background(primary ? Theme.accent : Theme.tile, in: Circle())
    }

    // Shown only once the helper has actually locked on, and dimmed rather
    // than blanked when it loses lock -- a tempo readout that flickers in and
    // out between phrases is worse than one that visibly goes stale. The dot
    // pulses on the helper's own beat flag, so it reads as a metronome rather
    // than a static label.
    // The lowest spectrum band is the kick region, so the dot swells on each
    // beat instead of needing its own timer synchronised to the helper's.
    private var tempoDotScale: CGFloat {
        guard shell.bpmLive, shell.media.playing, let bass = shell.levels.first else { return 1 }
        return 1 + min(0.55, max(0, CGFloat(bass)) * 0.55)
    }

    @ViewBuilder
    private var tempoBadge: some View {
        if shell.bpm > 0 {
            HStack(spacing: Spacing.tight) {
                Circle()
                    .fill(shell.bpmLive ? Theme.mint : Theme.muted)
                    .frame(width: 5, height: 5)
                    .scaleEffect(tempoDotScale)
                Text("\(shell.bpm)")
                    .font(.system(size: ShellTypography.cardTitle, weight: .heavy, design: .rounded))
                    .monospacedDigit()
                    .contentTransition(.numericText())
                    Text("BPM")
                    .font(.system(size: ShellTypography.micro, weight: .bold, design: .rounded))
                    .foregroundStyle(Theme.muted)
            }
            .foregroundStyle(shell.bpmLive ? Theme.bright : Theme.muted)
            .padding(.horizontal, Spacing.base)
            .padding(.vertical, Spacing.tight)
            .background(
                Theme.layerTile.opacity(shell.bpmLive ? 1 : 0.5),
                in: Capsule()
            )
            .overlay(Capsule().stroke(Theme.seam.opacity(0.25), lineWidth: 0.6))
            .opacity(shell.bpmLive ? 1 : 0.55)
            .animation(ShellMotion.contentIn.animation, value: shell.bpmLive)
            .animation(ShellMotion.valueChange.animation, value: shell.bpm)
            .help(shell.bpmLive ? "Detected tempo" : "Last detected tempo (no current lock)")
        }
    }

    // NotchPopout has its own mediaTime for the same job, but it is private
    // to that type; duplicating three lines is preferable to widening either
    // type's surface just to share them.
    private func nexusMediaTime(_ seconds: Double) -> String {
        guard seconds.isFinite, seconds > 0, seconds <= 30 * 24 * 60 * 60 else { return "0:00" }
        let value = Int(seconds.rounded(.down))
        return "\(value / 60):\(String(format: "%02d", value % 60))"
    }

    private func mediaSourceButton(_ title: String, source: String, symbol: String) -> some View {
        let selected = shell.preferredMediaSource == source
        return mediaChip(title, symbol: symbol, selected: selected) {
            withAnimation(ShellMotion.contentIn.animation) { shell.selectMediaSource(source) }
        }
    }

    private func mediaOpenButton(_ title: String, action: @escaping () -> Void) -> some View {
        mediaChip(title, symbol: "arrow.up.forward.app", action: action)
    }

    private func mediaChip(
        _ title: String,
        symbol: String,
        selected: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: Spacing.snug) {
                Image(systemName: symbol)
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                Text(title)
                    .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
            }
            .frame(maxWidth: .infinity)
            .padding(.horizontal, Spacing.tight)
            .frame(height: 40)
            .contentShape(Capsule())
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(selected ? Theme.onAccent : Theme.bright)
        .background(selected ? Theme.accent : Theme.tile, in: Capsule())
    }

    private var settings: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: Spacing.small) {
                nexusWallpaperPreview

                // Keep the three wallpaper actions together directly under
                // the preview: Wallhaven opens the network browser, Colours
                // cycles the built-in palettes, and Add wallpaper imports a
                // local image/video into the same shared library.
                HStack(spacing: Spacing.small) {
                    nexusActionButton("Wallhaven", "sparkle.magnifyingglass", primary: false) {
                        toggleWallpaperDiscovery()
                    }
                    .frame(maxWidth: .infinity)

                    nexusActionButton("Colours", "paintpalette", primary: false) {
                        switchWallpaper(step: 1)
                    }
                    .frame(maxWidth: .infinity)

                    nexusWallpaperImportButton()
                        .frame(maxWidth: .infinity)
                }

                nexusNonworkWallpaperCard

                VStack(spacing: 2) {
                    nexusSettingToggle(
                        "Display wallpaper",
                        "Show the active wallpaper layer",
                        isOn: Binding(
                            get: { nexus.desktopLayerEnabled },
                            set: { nexus.setDesktopLayerEnabled($0) }
                        ),
                        first: true
                    )
                    // Material opacity follows the active palette internally;
                    // it is not an independent setting. Do not expose that
                    // implementation detail as an unexplained AUTO card next
                    // to the actual user-facing toggles.
                    nexusSettingToggle(
                        "Dark theme",
                        shell.selectedPalette == .white ? "Light palette" : "Dark palette",
                        isOn: Binding(
                            get: { !Theme.isLight },
                            set: { value in
                                shell.setPalette(value ? .midnight : .white)
                            }
                        ),
                        last: true
                    )
                }

                if wallpaperDiscoveryExpanded {
                    wallpaperSourceBrowser
                        .transition(.opacity.combined(with: .move(edge: .top)))
                }

                sectionTitle("Mac++ shell")
                VStack(spacing: 2) {
                    // The center clock renders as its own overlay, mouse-transparent and
                    // behind every application window, independent of the wallpaper
                    // layer/visualizer -- Nexus is its only toggle.
                    nexusSettingToggle(
                        "Desktop clock",
                        "Show the center clock behind windows",
                        isOn: Binding(
                            get: { nexus.desktopCenterClockEnabled },
                            set: { nexus.setDesktopCenterClockEnabled($0) }
                        ),
                        first: true
                    )
                    nexusSettingToggle(
                        "Wallpaper visualizer",
                        "React to the active audio spectrum",
                        isOn: Binding(
                            get: { nexus.desktopVisualizerEnabled },
                            set: { nexus.setDesktopVisualizerEnabled($0) }
                        )
                    )
                    nexusSettingToggle(
                        "Menu + dock",
                        "Keep the native desktop chrome visible",
                        isOn: Binding(
                            get: { !shell.menuMaskEnabled },
                            set: { value in if value == shell.menuMaskEnabled { toggleMenuMask() } }
                        )
                    )
                    nexusSettingToggle(
                        "Shell border",
                        "Draw the persistent display contour",
                        isOn: Binding(
                            get: { shell.shellBorderEnabled },
                            set: { shell.setShellBorderEnabled($0) }
                        )
                    )
                    nexusSettingToggle(
                        "Battery saver",
                        "Reduce background polling while on battery",
                        isOn: Binding(
                            get: { shell.batterySaverEnabled },
                            set: { shell.setBatterySaver($0) }
                        )
                    )
                    nexusSettingToggle(
                        "Lyrics",
                        "Show synced lyrics on the media surface",
                        isOn: Binding(
                            get: { nexus.configuration.lyricsEnabled },
                            set: { nexus.setLyricsEnabled($0, for: shell.media) }
                        )
                    )
                    nexusSettingToggle(
                        "Record microphone",
                        "Include microphone input in recordings",
                        isOn: binding(\.recordMicrophone)
                    )
                    nexusSettingToggle(
                        "Suspend after idle",
                        "Allow the idle policy to suspend the display",
                        isOn: binding(\.idleSuspendEnabled)
                    )
                    nexusSettingToggle(
                        "Pause screensaver",
                        "Keep the screensaver paused",
                        isOn: Binding(
                            get: { shell.cmatrixScreensaverPaused },
                            set: { shell.setCMatrixScreensaverPaused($0) }
                        ),
                        last: true
                    )
                }

                sectionTitle("Soft lock")
                VStack(spacing: 2) {
                    nexusSettingToggle(
                        "Auto lock after screensaver",
                        "Use the Mac++ soft lock at the idle lock stage",
                        isOn: binding(\.softLockAfterScreensaverEnabled),
                        first: true
                    )
                    nexusSettingToggle(
                        "Weather",
                        "Show the weather card on the soft lock",
                        isOn: Binding(
                            get: { nexus.softLockConfiguration.showWeather },
                            set: { value in
                                nexus.updateSoftLockConfiguration { configuration in
                                    configuration.showWeather = value
                                }
                            }
                        )
                    )
                    nexusSettingToggle(
                        "Media",
                        "Show artwork and playback controls",
                        isOn: Binding(
                            get: { nexus.softLockConfiguration.showMedia },
                            set: { value in
                                nexus.updateSoftLockConfiguration { configuration in
                                    configuration.showMedia = value
                                }
                            }
                        )
                    )
                    nexusSettingToggle(
                        "Performance",
                        "Show CPU, memory, battery, and temperature",
                        isOn: Binding(
                            get: { nexus.softLockConfiguration.showPerformance },
                            set: { value in
                                nexus.updateSoftLockConfiguration { configuration in
                                    configuration.showPerformance = value
                                }
                            }
                        )
                    )
                    nexusSettingToggle(
                        "Notifications",
                        "Show recent captured notifications",
                        isOn: Binding(
                            get: { nexus.softLockConfiguration.showNotifications },
                            set: { value in
                                nexus.updateSoftLockConfiguration { configuration in
                                    configuration.showNotifications = value
                                }
                            }
                        ),
                        last: true
                    )
                }

                HStack(spacing: Spacing.medium) {
                    Image(systemName: "key.fill")
                        .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                        .frame(width: 20)
                    VStack(alignment: .leading, spacing: 0) {
                        Text("Mac++ passcode")
                            .font(.system(size: CaelestiaParityTokens.Font.larger, weight: .medium, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.bright)
                        if !nexus.softLockResetStatus.isEmpty {
                            Text(nexus.softLockResetStatus)
                                .font(.system(size: CaelestiaParityTokens.Font.small, weight: .regular, design: .rounded))
                                .foregroundStyle(NexusStudioStyle.muted)
                                .lineLimit(1)
                        }
                    }
                    Spacer(minLength: 8)
                    nexusActionButton("Reset", "key.slash", primary: false) {
                        softLockResetConfirmationPresented = true
                    }
                }
                .padding(.horizontal, Spacing.largeIncreased)
                .padding(.vertical, Spacing.medium)
                .background(NexusStudioStyle.card, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))

                HStack(spacing: Spacing.medium) {
                    Image(systemName: "photo.badge.arrow.down")
                        .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                        .foregroundStyle(NexusStudioStyle.muted)
                        .frame(width: 20)
                    VStack(alignment: .leading, spacing: 0) {
                        Text("Capture format")
                            .font(.system(size: CaelestiaParityTokens.Font.larger, weight: .medium, design: .rounded))
                            .foregroundStyle(NexusStudioStyle.bright)
                    }
                    Spacer(minLength: 8)
                    ForEach(["png", "jpg"], id: \.self) { format in
                        Button {
                            nexus.configuration.screenshotFormat = format
                            nexus.save()
                        } label: {
                            Text(format.uppercased())
                                .font(.system(size: ShellTypography.micro, weight: .medium, design: .rounded))
                                .frame(width: 48, height: 34)
                                .contentShape(Capsule())
                        }
                        .buttonStyle(MicroButtonStyle())
                        .foregroundStyle(nexus.configuration.screenshotFormat == format ? Theme.onAccent : NexusStudioStyle.muted)
                        .background(
                            nexus.configuration.screenshotFormat == format ? NexusStudioStyle.accent : NexusStudioStyle.raised,
                            in: Capsule()
                        )
                    }
                }
                .padding(.horizontal, Spacing.largeIncreased)
                .padding(.vertical, Spacing.medium)
                .background(NexusStudioStyle.card, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
            }
            // Theme reads are intentionally lightweight static tokens. Keying
            // the complete Settings content to the committed palette revision
            // makes every row and preview repaint together when the palette
            // changes from inside Nexus.
            .id("nexus-settings-top-\(shell.companionRevision)")
            .frame(width: nexusMainInnerWidth, alignment: .leading)
            .padding(.bottom, Spacing.section)
            .contentShape(Rectangle())
        }
        .frame(width: nexusMainInnerWidth, alignment: .leading)
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .defaultScrollAnchor(.top)
        .nexusResetScroll(anchorID: "nexus-settings-top-\(shell.companionRevision)")
    }

