    private var nexusColumns: [GridItem] {
        [
            GridItem(.flexible(minimum: 0), spacing: Spacing.roomy),
            GridItem(.flexible(minimum: 0))
        ]
    }

    // Search starts at the 600pt launcher envelope. Nexus uses the larger
    // control-centre canvas and the embedded Cast wrapper interpolates to it
    // during the same display-linked resize.
    private var nexusSurfaceWidth: CGFloat { CaelestiaParityTokens.Sizes.launcherNexusWidth }
    private var nexusSurfaceHeight: CGFloat { CaelestiaParityTokens.Nexus.surfaceHeight }
    private var nexusNavigationWidth: CGFloat { CaelestiaParityTokens.Nexus.navigationWidth }
    private var nexusNavigationOuterGutter: CGFloat { CaelestiaParityTokens.Nexus.navigationGutter }
    private var nexusNavigationTopGutter: CGFloat { CaelestiaParityTokens.Nexus.navigationTopGutter }
    private var nexusNavigationBottomGutter: CGFloat { CaelestiaParityTokens.Nexus.navigationBottomGutter }
    private var nexusNavigationFrameWidth: CGFloat {
        nexusNavigationWidth + nexusNavigationOuterGutter
    }
    /// Search starts after the NavPane margin and the embedded launcher's
    /// shell shoulder. Nexus's close island mirrors that exact edge inset on
    /// the opposite side.
    private var nexusSharedOuterGutter: CGFloat {
        nexusNavigationOuterGutter + launcherSurfaceShoulder
    }
    // Keep the search-field reserve in one token so the fixed scroll viewport
    // and its visual offset cannot drift apart and bleed into the shell seam.
    private var nexusNavigationScrollOffset: CGFloat {
        44 + Spacing.large
    }
    private var nexusNavigationFadeHeight: CGFloat {
        CaelestiaParityTokens.Spacing.largeIncreased
    }
    private var nexusContentFadeHeight: CGFloat {
        // Navigation and page content must terminate with the same optical
        // fade band at the bottom of the shared Nexus viewport.
        nexusNavigationFadeHeight
    }
    private var nexusNavigationScrollHeight: CGFloat {
        max(
            1,
            nexusSurfaceHeight
            - nexusNavigationTopGutter
            - nexusNavigationBottomGutter
            - nexusNavigationScrollOffset
            - nexusNavigationFadeHeight
        )
    }
    private var nexusMainRegionWidth: CGFloat {
        nexusSurfaceWidth - nexusNavigationFrameWidth
    }
    private var nexusPageLeadingGutter: CGFloat {
        nexusNavigationOuterGutter + CaelestiaParityTokens.Nexus.contentHorizontalGutter
    }
    private var nexusPageTrailingGutter: CGFloat {
        // BottomMorphShape keeps the settled Nexus inside the attached shell
        // contour by 22pt on the free edge. Reserve that space in addition to
        // the upstream 28pt Pages margin so cards do not touch the cyan rim.
        launcherSurfaceShoulder + CaelestiaParityTokens.Nexus.contentHorizontalGutter
    }
    private var nexusPageTopGutter: CGFloat {
        CaelestiaParityTokens.Nexus.contentVerticalGutter
    }
    private var nexusPageBottomGutter: CGFloat {
        CaelestiaParityTokens.Nexus.contentVerticalGutter
    }
    private var nexusPageHeaderHeight: CGFloat { CaelestiaParityTokens.Font.extraLarge }
    private var nexusPageHeaderSpacing: CGFloat { CaelestiaParityTokens.Spacing.extraLargeIncreased }
    private var nexusMainInnerWidth: CGFloat {
        nexusMainRegionWidth - nexusPageLeadingGutter - nexusPageTrailingGutter
    }
    private var nexusMainInnerHeight: CGFloat {
        nexusSurfaceHeight
            - nexusPageTopGutter
            - nexusPageBottomGutter
            - nexusPageHeaderHeight
            - nexusPageHeaderSpacing
    }

    private func binding<T>(_ keyPath: WritableKeyPath<MacPlusPlusNexusConfiguration, T>) -> Binding<T> {
        Binding(get: { nexus.configuration[keyPath: keyPath] }, set: {
            nexus.configuration[keyPath: keyPath] = $0
            nexus.save()
        })
    }
    private func runCapture(_ mode: String) {
        close()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.22) { nexus.capture(mode) }
    }
    private func openSystemSettings(_ pane: String?) {
        let value = pane.map { "x-apple.systempreferences:\($0)" } ?? "x-apple.systempreferences:"
        guard let url = URL(string: value) else { return }
        NSWorkspace.shared.open(url)
    }

    private func openSoftwareUpdate() {
        guard let url = URL(string: "x-apple.systempreferences:com.apple.Software-Update") else { return }
        NSWorkspace.shared.open(url)
    }

    private func openLanguageRegion() {
        let value = "x-apple.systempreferences:com.apple.Localization-Settings.extension"
        if let url = URL(string: value), NSWorkspace.shared.open(url) { return }
        // The pane identifier has changed across macOS releases. A generic
        // System Settings fallback is more useful than leaving this read-only
        // page with no route to the actual control.
        openSystemSettings(nil)
    }

    private func openCaelestiaReference() {
        guard let url = URL(string: CaelestiaParityTokens.referenceRepository) else { return }
        NSWorkspace.shared.open(url)
    }

    private func copyHomebrewCheckCommand() {
        let command = "brew outdated --formula && brew outdated --cask"
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(command, forType: .string)
    }

    private func sectionTitle(_ title: String) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: Spacing.base) {
            Text(title)
                .font(.system(size: ShellTypography.section, weight: .bold, design: .rounded))
                .foregroundStyle(Theme.bright)
            Spacer(minLength: 0)
        }
        .lineLimit(1)
        .minimumScaleFactor(0.72)
        .padding(.top, Spacing.snug)
        .accessibilityElement(children: .combine)
    }

    private var wallpaperBrowser: some View {
        HStack(spacing: Spacing.roomy) {
            ZStack {
                RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                    .fill(Theme.tile)
                if let image = wallpaperPoster(for: shell.selectedPalette) {
                    MacPlusPlusWallpaperFramedImage(
                        image: image,
                        selection: currentWallpaperFraming
                    )
                        .id("\(currentWallpaperPreviewIdentity)-\(wallpaperFramingRevision)")
                        .transition(
                            .asymmetric(
                                insertion: .move(edge: wallpaperDirection > 0 ? .trailing : .leading).combined(with: .opacity),
                                removal: .move(edge: wallpaperDirection > 0 ? .leading : .trailing).combined(with: .opacity)
                            )
                        )
                } else {
                    Image(systemName: "photo")
                        .font(.system(size: ShellIcon.feature, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                }
            }
            .frame(width: 210, height: 116)
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .gesture(
                DragGesture(minimumDistance: 12)
                    .onEnded { value in
                        guard abs(value.translation.width) > CaelestiaParityTokens.Interaction.launcherDragThreshold else { return }
                        switchWallpaper(step: value.translation.width < 0 ? 1 : -1)
                    }
            )

            // Chevrons, title, dots, and the DISCOVER/ADD pair used to be four
            // independently-sized elements (42pt circles, a lone centered
            // title, a dot row, two unevenly-sized pills) with no shared
            // rhythm between them -- correct individually but not
            // obviously one panel. Chevrons come down to the same 36pt used
            // for a two-line header card elsewhere in the shell, and
            // DISCOVER/ADD now split the row evenly instead of sizing to
            // their own text ("DISCOVER" being longer than "ADD" left them
            // visibly mismatched).
            VStack(alignment: .leading, spacing: Spacing.base) {
                HStack {
                    Button { switchWallpaper(step: -1) } label: {
                        Image(systemName: "chevron.left")
                            .frame(width: 36, height: 36)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(Theme.tile, in: Circle())
                    Spacer()
                    Button { switchWallpaper(step: 1) } label: {
                        Image(systemName: "chevron.right")
                            .frame(width: 36, height: 36)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(Theme.tile, in: Circle())
                }
                // The chevron row above is naturally centered (a Spacer
                // between two symmetric circular buttons); this title used
                // to sit at the leading edge underneath it instead, off
                // center relative to its own row.
                Text(shell.selectedPalette.title)
                    .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .lineLimit(1)
                    .frame(maxWidth: .infinity, alignment: .center)
                // These dots' own touch target used to be 30pt tall for a
                // 6-8pt circle -- most of that row was dead space, which is
                // what read as a big empty gap between the title and the
                // buttons below it.
                HStack(spacing: Spacing.hairline) {
                    ForEach(wallpaperPalettes) { palette in
                        Button { switchWallpaper(to: palette) } label: {
                            Circle()
                                .fill(palette == shell.selectedPalette ? Theme.accent : Theme.muted.opacity(0.42))
                                .frame(
                                    width: palette == shell.selectedPalette ? 8 : 6,
                                    height: palette == shell.selectedPalette ? 8 : 6
                                )
                                .frame(width: 18, height: 18)
                                .contentShape(Circle())
                        }
                        .buttonStyle(.plain)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .center)
                HStack(spacing: Spacing.snug) {
                    Button {
                        toggleWallpaperDiscovery()
                    } label: {
                        HStack(spacing: Spacing.snug) {
                            Image(systemName: wallpaperDiscoveryExpanded ? "chevron.up" : "sparkle.magnifyingglass")
                            Text("DISCOVER")
                        }
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                        .frame(maxWidth: .infinity)
                        .frame(height: 34)
                        .contentShape(Capsule())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(wallpaperDiscoveryExpanded ? Theme.accent : Theme.tile, in: Capsule())
                    .foregroundStyle(wallpaperDiscoveryExpanded ? Theme.surface : Theme.bright)

                    Button { shell.chooseMacPlusPlusWallpaperMedia() } label: {
                        HStack(spacing: Spacing.snug) {
                            Image(systemName: "plus")
                            Text("ADD")
                        }
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                        .frame(maxWidth: .infinity)
                        .frame(height: 34)
                        .contentShape(Capsule())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(Theme.tile, in: Capsule())
                }
                .frame(maxWidth: .infinity)
            }
            .foregroundStyle(Theme.bright)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(Spacing.base)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
        // Theme tokens are read through lightweight static accessors. Keying
        // this complete card to the committed palette revision guarantees the
        // focused poster, title, dots, and card chrome all recolour together
        // when White/Midnight changes from inside Nexus.
        .id("nexus-wallpaper-browser-\(shell.companionRevision)")
    }

    private var visualizerBrowser: some View {
        let selected = selectedVisualizerOption
        return HStack(spacing: Spacing.roomy) {
            MacPlusPlusVisualizerPreview(style: selected.id, active: true)
                .id("nexus-visualizer-preview-\(selected.id)")
                .frame(width: 210, height: 116)
                .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                .transition(
                    .asymmetric(
                        insertion: .move(edge: visualizerDirection > 0 ? .trailing : .leading)
                            .combined(with: .opacity),
                        removal: .move(edge: visualizerDirection > 0 ? .leading : .trailing)
                            .combined(with: .opacity)
                    )
                )
                .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                .gesture(
                    DragGesture(minimumDistance: 12)
                        .onEnded { value in
                            guard abs(value.translation.width) > CaelestiaParityTokens.Interaction.launcherDragThreshold else { return }
                            switchVisualizer(step: value.translation.width < 0 ? 1 : -1)
                        }
                )

            VStack(alignment: .leading, spacing: Spacing.base) {
                HStack {
                    Button { switchVisualizer(step: -1) } label: {
                        Image(systemName: "chevron.left")
                            .frame(width: 36, height: 36)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(Theme.tile, in: Circle())
                    Spacer()
                    Button { switchVisualizer(step: 1) } label: {
                        Image(systemName: "chevron.right")
                            .frame(width: 36, height: 36)
                            .contentShape(Circle())
                    }
                    .buttonStyle(MicroButtonStyle())
                    .background(Theme.tile, in: Circle())
                }
                HStack(spacing: Spacing.snug) {
                    Image(systemName: selected.symbol)
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .foregroundStyle(Theme.accent)
                Text(selected.title)
                        .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(1)
                        .minimumScaleFactor(0.78)
                }
                HStack(spacing: Spacing.hairline) {
                    ForEach(MacPlusPlusVisualizerOption.all) { option in
                        Button { selectVisualizer(to: option) } label: {
                            Circle()
                                .fill(option == selected ? Theme.accent : Theme.muted.opacity(0.42))
                                .frame(
                                    width: option == selected ? 8 : 6,
                                    height: option == selected ? 8 : 6
                                )
                                .frame(width: 18, height: 18)
                                .contentShape(Circle())
                        }
                        .buttonStyle(.plain)
                        .accessibilityLabel(option.title)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .center)
            }
            .foregroundStyle(Theme.bright)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(Spacing.base)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
        .id("nexus-visualizer-browser-\(shell.companionRevision)")
    }

    private var wallpaperSourceBrowser: some View {
        VStack(alignment: .leading, spacing: Spacing.base) {
            if let cropResult = wallpaperCropResult {
                wallpaperCropPreview(result: cropResult)
            } else {
                HStack(spacing: Spacing.base) {
                Image(systemName: "sparkle.magnifyingglass")
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
                TextField("SEARCH WALLHAVEN", text: $wallpaperSource.query)
                    .textFieldStyle(.plain)
                    .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .onSubmit { wallpaperSource.search() }
                Button {
                    wallpaperSource.search(force: true)
                } label: {
                    ZStack {
                        if wallpaperSource.isSearching {
                            ProgressView()
                                .controlSize(.small)
                                .transition(.opacity)
                        } else {
                            Image(systemName: "arrow.right")
                                .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                                .transition(.opacity)
                        }
                    }
                    .frame(width: 34, height: 34)
                    .contentShape(Circle())
                    .animation(ShellMotion.contentIn.animation, value: wallpaperSource.isSearching)
                }
                .buttonStyle(MicroButtonStyle())
                .background(Theme.accent, in: Circle())
                .foregroundStyle(Theme.onAccent)
                .disabled(wallpaperSource.isSearching)
                }
                .padding(.leading, Spacing.roomy)
                .padding(.trailing, Spacing.tight)
                .frame(height: 44)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .tile)

                HStack(spacing: Spacing.base) {
                Text(wallpaperSource.errorMessage.isEmpty
                     ? wallpaperSource.status
                     : wallpaperSource.errorMessage)
                    .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                    .foregroundStyle(wallpaperSource.errorMessage.isEmpty ? Theme.muted : Color.red)
                    .lineLimit(2)
                Spacer(minLength: 8)
                if !wallpaperSource.results.isEmpty {
                    Button { wallpaperSource.previousPage() } label: {
                        Image(systemName: "chevron.left").frame(width: 30, height: 30)
                    }
                    .buttonStyle(MicroButtonStyle())
                    .disabled(wallpaperSource.page <= 1 || wallpaperSource.isSearching)
                    Text("\(wallpaperSource.page) / \(wallpaperSource.lastPage)")
                        .font(.system(size: ShellTypography.micro, weight: .medium, design: .rounded))
                        .monospacedDigit()
                        .foregroundStyle(Theme.muted)
                    Button { wallpaperSource.nextPage() } label: {
                        Image(systemName: "chevron.right").frame(width: 30, height: 30)
                    }
                    .buttonStyle(MicroButtonStyle())
                    .disabled(wallpaperSource.page >= wallpaperSource.lastPage || wallpaperSource.isSearching)
                }
                }
                .frame(minHeight: 30)

                if !wallpaperSource.results.isEmpty {
                    LazyVGrid(columns: nexusColumns, spacing: Spacing.base) {
                        ForEach(wallpaperSource.results) { result in
                            wallpaperSourceResultCard(result)
                        }
                    }
                }
            }
        }
        .padding(Spacing.roomy)
        .nexusLayer(cornerRadius: Rounding.large, depth: .group)
    }

    private func wallpaperSourceResultCard(_ result: MacPlusPlusWallpaperSourceResult) -> some View {
        VStack(alignment: .leading, spacing: Spacing.snug) {
            AsyncImage(
                url: URL(string: result.thumbnailLarge),
                transaction: Transaction(animation: ShellMotion.contentIn.animation)
            ) { phase in
                switch phase {
                case .success(let image):
                    image.resizable().scaledToFill().transition(.opacity)
                case .failure:
                    ZStack {
                        Theme.tile
                        Image(systemName: "photo.badge.exclamationmark")
                            .foregroundStyle(Theme.muted)
                    }
                    .transition(.opacity)
                default:
                    ZStack {
                        Theme.tile
                        ProgressView().controlSize(.small).tint(Theme.accent)
                    }
                    .transition(.opacity)
                }
            }
            .frame(maxWidth: .infinity)
            .aspectRatio(21.0 / 9.0, contentMode: .fit)
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))

            HStack(spacing: Spacing.snug) {
                Text(result.resolution)
                    .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                Spacer(minLength: 4)
                Button {
                    guard let url = URL(string: result.pageURL) else { return }
                    NSWorkspace.shared.open(url)
                } label: {
                    Image(systemName: "arrow.up.right")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 26, height: 26)
                }
                .buttonStyle(MicroButtonStyle())
                .help("Open the source on Wallhaven")
            }

            Button {
                openWallpaperCrop(result)
            } label: {
                HStack(spacing: Spacing.snug) {
                    Image(systemName: "crop")
                    Text("PREVIEW CROP")
                }
                .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                .frame(maxWidth: .infinity)
                .frame(height: 34)
                .contentShape(Capsule())
            }
            .buttonStyle(MicroButtonStyle())
            .background(Theme.accent, in: Capsule())
            .foregroundStyle(Theme.onAccent)
            .disabled(wallpaperSource.importingID != nil)
        }
        .padding(Spacing.base)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
    }

    private func openWallpaperCrop(_ result: MacPlusPlusWallpaperSourceResult) {
        wallpaperCropSelection = MacPlusPlusWallpaperCropSelection()
        withAnimation(ShellMotion.contentIn.animation) {
            wallpaperCropResult = result
        }
    }

    private func closeWallpaperCrop() {
        withAnimation(ShellMotion.contentIn.animation) {
            wallpaperCropResult = nil
        }
    }

    private func importCroppedWallpaper(_ result: MacPlusPlusWallpaperSourceResult) {
        let crop = wallpaperCropSelection
        wallpaperSource.importAndUse(result) { imported in
            guard case .success(let url) = imported else { return }
            wallpaperCropResult = nil
            shell.applyWallpaperOverride(url, crop: crop)
        }
    }

    private func wallpaperCropPreview(result: MacPlusPlusWallpaperSourceResult) -> some View {
        let sourceAspect = Double(result.width) / Double(max(result.height, 1))
        let targetAspect = Double(macppWallpaperDisplayAspect())
        let isHorizontalCrop = sourceAspect > targetAspect + 0.001
        let removedFraction = isHorizontalCrop
            ? 1 - targetAspect / sourceAspect
            : 1 - sourceAspect / targetAspect
        let removedPercent = Int(max(0, removedFraction * 100).rounded())
        let cropDetail: String
        if removedPercent == 0 {
            cropDetail = "FULL IMAGE FITS THE DISPLAY FRAME"
        } else if isHorizontalCrop {
            cropDetail = "HORIZONTAL CROP • \(removedPercent)% OF WIDTH IS REMOVED"
        } else {
            cropDetail = "VERTICAL CROP • \(removedPercent)% OF HEIGHT IS REMOVED"
        }

        return VStack(alignment: .leading, spacing: Spacing.base) {
            HStack(spacing: Spacing.base) {
                Button { closeWallpaperCrop() } label: {
                    Image(systemName: "chevron.left")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 30, height: 30)
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .background(Theme.tile, in: Circle())
                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text("CROP PREVIEW")
                        .font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                    Text(result.resolution)
                        .font(.system(size: ShellTypography.nano, weight: .bold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                }
                Spacer(minLength: 8)
                Image(systemName: "crop")
                    .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
            }

            if wallpaperSource.importingID == result.id || !wallpaperSource.errorMessage.isEmpty {
                Text(wallpaperSource.errorMessage.isEmpty
                     ? wallpaperSource.status
                     : wallpaperSource.errorMessage)
                    .font(.system(size: ShellTypography.nano, weight: .semibold, design: .rounded))
                    .foregroundStyle(wallpaperSource.errorMessage.isEmpty ? Theme.muted : Color.red)
                    .lineLimit(2)
            }

            MacPlusPlusWallpaperCropPreview(
                url: URL(string: result.thumbnailLarge),
                sourceSize: CGSize(width: CGFloat(result.width), height: CGFloat(result.height)),
                selection: $wallpaperCropSelection
            )
            .aspectRatio(CGFloat(targetAspect), contentMode: .fit)
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))

            HStack(spacing: Spacing.snug) {
                Spacer(minLength: 4)
                Button {
                    wallpaperCropSelection = MacPlusPlusWallpaperCropSelection()
                } label: {
                    Image(systemName: "arrow.counterclockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 28, height: 28)
                        .contentShape(Circle())
                }
                .buttonStyle(MicroButtonStyle())
                .background(Theme.tile, in: Circle())
                .help("Center crop")
            }

            Text(cropDetail)
                .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.bright)
                .lineLimit(1)
                .minimumScaleFactor(0.72)

            HStack(spacing: Spacing.snug) {
                Button { closeWallpaperCrop() } label: {
                    Text("Cancel")
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                        .frame(maxWidth: .infinity)
                        .frame(height: 34)
                        .background(Theme.tile, in: Capsule())
                        .foregroundStyle(Theme.bright)
                        .contentShape(Capsule())
                }
                .buttonStyle(MicroButtonStyle())

                Button {
                    importCroppedWallpaper(result)
                } label: {
                    HStack(spacing: Spacing.snug) {
                        if wallpaperSource.importingID == result.id {
                            ProgressView().controlSize(.small)
                        } else {
                            Image(systemName: "plus")
                        }
                        Text("CROP & ADD")
                    }
                    .font(.system(size: ShellTypography.micro, weight: .semibold, design: .rounded))
                    .frame(maxWidth: .infinity)
                    .frame(height: 34)
                    .background(Theme.accent, in: Capsule())
                    .foregroundStyle(Theme.onAccent)
                    .contentShape(Capsule())
                }
                .buttonStyle(MicroButtonStyle())
                .disabled(wallpaperSource.importingID != nil)
            }
        }
        .padding(Spacing.none)
    }

    private var wallpaperPalettes: [ShellPalette] {
        ShellPalette.dedicatedPalettes
    }

    private var selectedVisualizerOption: MacPlusPlusVisualizerOption {
        MacPlusPlusVisualizerOption.all.first {
            $0.id == nexus.desktopVisualizerStyle
        } ?? MacPlusPlusVisualizerOption.all[0]
    }

    private func switchVisualizer(step: Int) {
        let options = MacPlusPlusVisualizerOption.all
        guard !options.isEmpty else { return }
        let current = options.firstIndex(of: selectedVisualizerOption) ?? 0
        let next = (current + step + options.count) % options.count
        selectVisualizer(to: options[next], direction: step >= 0 ? 1 : -1)
    }

    private func selectVisualizer(
        to option: MacPlusPlusVisualizerOption,
        direction: Int? = nil
    ) {
        let options = MacPlusPlusVisualizerOption.all
        if let direction {
            visualizerDirection = direction
        } else if let current = options.firstIndex(of: selectedVisualizerOption),
                  let next = options.firstIndex(of: option) {
            visualizerDirection = next >= current ? 1 : -1
        }
        withAnimation(ShellMotion.carousel.animation) {
            nexus.setDesktopVisualizerStyle(option.id)
        }
    }

    /// A custom wallpaper keeps the palette id `custom` for every imported
    /// source. Keying only by that id left the Nexus poster and crop renderer
    /// alive when the selected file changed, so the preview could show the old
    /// focal point until another palette was visited.
    private var currentWallpaperPreviewIdentity: String {
        shell.currentWallpaperURL()?.standardizedFileURL.path
            ?? "palette:\(shell.selectedPalette.id)"
    }

    private var currentWallpaperFraming: MacPlusPlusWallpaperCropSelection {
        guard let sourceURL = shell.currentWallpaperURL() else {
            return MacPlusPlusWallpaperCropSelection()
        }
        return MacPlusPlusWallpaperFramingStore.load(for: sourceURL.path)
    }

    private func wallpaperPoster(for palette: ShellPalette) -> NSImage? {
        let root = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/MacPlusPlus/Posters", isDirectory: true)
        let normalizedCurrentSource = palette == shell.selectedPalette
            ? shell.currentWallpaperURL()?.standardizedFileURL.path
            : nil

        // Imported stills do not necessarily have a generated palette poster.
        // Use the actual selected source when it is an image so the Nexus crop
        // is calculated from the same pixels as the desktop renderer.
        if let currentSource = shell.currentWallpaperURL(),
           palette == shell.selectedPalette,
           !macppWallpaperVideoExtensions.contains(currentSource.pathExtension.lowercased()),
           let image = NSImage(contentsOf: currentSource) {
            return image
        }

        // Video posters are indexed by a sidecar containing the exact source
        // path. Prefer that match over `custom.png`: the latter is a mutable
        // cache slot and may still contain a frame from a previous import.
        if let normalizedCurrentSource,
           // macpp:silent-ok an unavailable poster directory leaves the normal palette fallback intact
           let files = try? FileManager.default.contentsOfDirectory(
               at: root,
               includingPropertiesForKeys: [.isRegularFileKey],
               options: [.skipsHiddenFiles]
            ) {
            for source in files where source.pathExtension.lowercased() == "source" {
                // macpp:silent-ok a missing source sidecar means this candidate cannot identify the poster
                guard let raw = try? String(contentsOf: source, encoding: .utf8),
                      let rawPath = raw.split(
                          separator: "|",
                          maxSplits: 1,
                          omittingEmptySubsequences: false
                      ).first,
                      URL(fileURLWithPath: String(rawPath)).standardizedFileURL.path == normalizedCurrentSource
                else { continue }
                let poster = source.deletingPathExtension().appendingPathExtension("png")
                if let image = NSImage(contentsOf: poster) { return image }
            }
        }

        let original = root.appendingPathComponent("\(palette.rawValue).png")
        let picker = root.deletingLastPathComponent()
            .appendingPathComponent("PickerPosters", isDirectory: true)
            .appendingPathComponent("\(palette.rawValue).jpg")
        // macpp:silent-ok unavailable modification dates only affect which optional poster wins
        let originalDate = (try? original.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
        // macpp:silent-ok unavailable modification dates only affect which optional poster wins
        let pickerDate = (try? picker.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
        let source = (FileManager.default.fileExists(atPath: picker.path) && pickerDate >= originalDate)
            ? picker
            : original
        return NSImage(contentsOf: source)
    }

    private func switchWallpaper(step: Int) {
        guard !wallpaperPalettes.isEmpty else { return }
        let current = wallpaperPalettes.firstIndex(of: shell.selectedPalette) ?? 0
        let next = (current + step + wallpaperPalettes.count) % wallpaperPalettes.count
        switchWallpaper(to: wallpaperPalettes[next], direction: step >= 0 ? 1 : -1)
    }

    private func toggleWallpaperDiscovery() {
        let expanding = !wallpaperDiscoveryExpanded
        withAnimation(ShellMotion.contentIn.animation) {
            wallpaperDiscoveryExpanded = expanding
        }
        guard expanding,
              wallpaperSource.results.isEmpty,
              !wallpaperSource.isSearching else { return }
        // Opening Wallhaven should produce a usable browser immediately. The
        // old toggle only revealed an empty card and required a second search
        // action, which made the wallpaper surface look broken on first use.
        wallpaperSource.search()
    }

    private func switchWallpaper(to palette: ShellPalette, direction: Int? = nil) {
        if let direction {
            wallpaperDirection = direction
        } else if let current = wallpaperPalettes.firstIndex(of: shell.selectedPalette),
                  let next = wallpaperPalettes.firstIndex(of: palette) {
            wallpaperDirection = next >= current ? 1 : -1
        }
        // The carousel's own arrow-driven switch and select(_:)'s click-driven
        // switch are the same action (change the active palette) but used to
        // run on two different curves -- a one-off hand-tuned bezier here vs
        // ShellMotion.palette everywhere else. Same action, same curve now.
        withAnimation(ShellMotion.palette.animation) {
            shell.setPalette(palette)
        }
    }

    private func infoCard(_ title: String, _ value: String, _ symbol: String) -> some View {
        HStack(spacing: Spacing.roomy) {
            Image(systemName: symbol).font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent).frame(width: 24)
            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(title).nexusLabel().lineLimit(1)
                Text(value).nexusValue().lineLimit(1).minimumScaleFactor(0.72)
            }
            .frame(minWidth: 0, maxWidth: .infinity, alignment: .leading)
        }
        .padding(Spacing.roomy)
        .frame(minWidth: 0, maxWidth: .infinity)
        .frame(height: 62)
        .nexusLayer(cornerRadius: Rounding.large, depth: .card)
    }

    private func metricPill(_ title: String, _ percent: Int, _ symbol: String) -> some View {
        VStack(spacing: Spacing.tight) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
            Text("\(min(100, max(0, percent)))%")
                .font(.system(size: ShellDisplay.small, weight: .heavy, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(Theme.bright)
                .contentTransition(.numericText())
            Text(title).nexusLabel()
        }
        // Same omission as the dashboard clock: a numericText transition with
        // nothing animating the value it reacts to.
        .animation(ShellMotion.valueChange.animation, value: percent)
        .frame(maxWidth: .infinity)
        .frame(height: 82)
        .nexusLayer(cornerRadius: Rounding.large, depth: .card)
    }

    private func compactStatus(_ title: String, _ value: String, _ symbol: String) -> some View {
        HStack(spacing: Spacing.base) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
                .frame(width: 17)
            VStack(alignment: .leading, spacing: Spacing.none) {
                Text(title).nexusLabel()
                Text(value)
                    .nexusValue()
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)
                    .contentTransition(.opacity)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, Spacing.roomy)
        .frame(height: 38)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .tile)
        .animation(ShellMotion.contentIn.animation, value: value)
    }

    // Snapshot labels stack over their values so the two tiles stay compact
    // beside the history graph without squeezing either value.
    private func compactMetric(_ title: String, _ value: String, _ color: Color) -> some View {
        VStack(spacing: Spacing.hairline) {
            HStack(spacing: Spacing.hairline) {
                Circle().fill(color).frame(width: 4, height: 4)
                    Text(title)
                    .font(.system(size: ShellTypography.nano, weight: .medium, design: .rounded))
                    .foregroundStyle(Theme.muted)
                    .lineLimit(1)
            }
            Text(value)
                .font(.system(size: ShellTypography.label, weight: .heavy, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(Theme.bright)
                .lineLimit(1)
                .contentTransition(.numericText())
        }
        .padding(.horizontal, Spacing.tight)
        .frame(maxWidth: .infinity)
        .frame(height: 32)
        .background(Theme.layerTile, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .animation(ShellMotion.valueChange.animation, value: value)
    }

    private func overviewCard(
        _ title: String,
        _ value: String,
        _ symbol: String,
        destination: MacPlusPlusNexusModel.Page?
    ) -> some View {
        NexusOverviewCard(title: title, value: value, symbol: symbol, isInteractive: destination != nil) {
            guard let destination else { return }
            withAnimation(ShellMotion.nexusPageSwitch.animation) { nexus.page = destination }
        }
    }
    private func actionCard(_ title: String, _ symbol: String, _ action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack(spacing: Spacing.roomy) {
                Image(systemName: symbol).font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent).frame(width: 22)
                Text(title).nexusValue()
                Spacer()
            }
            .padding(.horizontal, Spacing.loose)
            .frame(maxWidth: .infinity, minHeight: 58, maxHeight: 58)
            .nexusLayer(cornerRadius: Rounding.large, depth: .card)
            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright)
    }
    private func settingsCard(_ title: String, _ symbol: String, _ pane: String) -> some View {
        actionCard(title, symbol) { openSystemSettings(pane) }
    }
}

private struct NexusOverviewCard: View {
    let title: String
    let value: String
    let symbol: String
    let isInteractive: Bool
    let action: () -> Void
    @State private var hovered = false

    private var cardContent: some View {
        HStack(spacing: Spacing.roomy) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
                .frame(width: 24)
            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(title).nexusLabel().lineLimit(1)
                Text(value).nexusValue().lineLimit(1).minimumScaleFactor(0.72)
            }
            .frame(minWidth: 0, maxWidth: .infinity, alignment: .leading)
            if isInteractive {
                Image(systemName: "chevron.right")
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                    .foregroundStyle(Theme.muted)
                    .opacity(hovered ? 1 : 0.34)
                    .offset(x: hovered ? 1 : 0)
            }
        }
        .padding(Spacing.roomy)
        .frame(minWidth: 0, maxWidth: .infinity)
        .frame(height: 62)
        .nexusLayer(cornerRadius: Rounding.large, depth: hovered ? .selected : .card)
        .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
        .scaleEffect(hovered ? 1.006 : 1)
    }

    @ViewBuilder
    var body: some View {
        if isInteractive {
            Button(action: action) {
                cardContent
            }
            .buttonStyle(MicroButtonStyle())
            .onHover { inside in
                withAnimation(ShellMotion.hover.animation) { hovered = inside }
            }
            .accessibilityLabel(title)
            .accessibilityValue(value)
        } else {
            cardContent
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(title)
                .accessibilityValue(value)
        }
    }
}

private struct NexusButtonStyle: ButtonStyle {
    let primary: Bool
    @Environment(\.isEnabled) private var isEnabled

    func makeBody(configuration: Configuration) -> some View {
        let shape = RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
        configuration.label
            .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
            .foregroundStyle(primary ? Theme.onAccent : Theme.bright)
            .padding(.horizontal, Spacing.roomy)
            .frame(maxWidth: .infinity, minHeight: 46)
            .background(primary ? NexusStudioStyle.accent : NexusStudioStyle.raised, in: shape)
            .overlay(
                shape.stroke(
                    primary ? NexusStudioStyle.accent.opacity(0.24) : NexusStudioStyle.seam,
                    lineWidth: 0.7
                )
            )
            .scaleEffect(isEnabled && configuration.isPressed ? 0.96 : 1)
            .brightness(isEnabled && configuration.isPressed ? 0.06 : 0)
            .saturation(isEnabled ? 1 : 0.35)
            .opacity(isEnabled ? (configuration.isPressed ? 0.72 : 1) : 0.38)
            .contentShape(shape)
            .animation(ShellMotion.press.animation, value: configuration.isPressed)
            .animation(ShellMotion.contentIn.animation, value: isEnabled)
    }
}

private enum NexusLayerDepth: Equatable {
    // `group` and `card` are both ordinary sibling cards. Keep both spellings
    // because the pages use them for different content groupings, but do not
    // let that implementation detail create a second visible card colour.
    case group
    case card
    // A tile is reserved for content nested inside a card or for a control that
    // needs the one elevated step above the ordinary card surface.
    case tile
    // Selection is semantic state, not another structural depth.
    case selected
}

/// Nexus has a deliberately quieter material language than the rail, but it is
/// still part of the shell's palette system. Keep the mockup's hierarchy
/// local while deriving every surface, copy colour, accent, and selection from
/// the active palette so a switch to Ember, White, or a custom palette never
/// leaves a charcoal/purple island behind.
private enum NexusStudioStyle {
    // Nexus does not own a second palette. Every surface is a shell Theme
    // token, so changing the shell palette updates the dashboard as one
    // continuous material system rather than leaving a fixed-color island.
    static var background: Color { Theme.shellSurface }
    static var sidebar: Color { .clear }
    static var mainHeader: Color { .clear }
    static var field: Color { Theme.layerTile.opacity(0.80) }
    static var card: Color { Theme.layerGroup }
    static var raised: Color { Theme.layerTile }
    static var accent: Color { Theme.accent }
    static var bright: Color { Theme.bright }
    static var muted: Color { Theme.muted }
    // Icon circles are small non-text controls. Their foreground is resolved
    // against the actual selected tile instead of inheriting the page copy
    // colour, which can be too close to a bright wallpaper-derived surface.
    static var iconOnSelection: Color { Theme.nexusIconForeground }
    static var iconOnAccent: Color {
        Theme.readableForeground(
            over: [accent],
            preferred: Theme.bright,
            minimumContrast: 4.5
        )
    }
    static var divider: Color { Theme.seam.opacity(0.42) }
    static var selection: Color { Theme.layerSelected }
    static var seam: Color { Theme.seam.opacity(0.50) }
}

private struct NexusLayerModifier: ViewModifier {
    let cornerRadius: CGFloat
    let depth: NexusLayerDepth

    private var fill: Color {
        switch depth {
        case .group:
            return NexusStudioStyle.card
        case .card:
            return NexusStudioStyle.card
        case .tile:
            return NexusStudioStyle.raised
        case .selected:
            return NexusStudioStyle.selection
        }
    }

    func body(content: Content) -> some View {
        let shape = RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
        content
            .background(fill, in: shape)
            // `background(_:in:)` paints a rounded fill but does not constrain
            // descendants. The explicit clip keeps nested rows and platform
            // content on the same continuous-radius system at every depth.
            .clipShape(shape)
            // Caelestia's ordinary rows are fill-first.  Keep the seam only
            // for the active row so the page does not become a collection of
            // outlined boxes on top of the continuous Nexus surface.
            .overlay {
                if depth == .selected {
                    shape
                        .stroke(NexusStudioStyle.accent.opacity(0.72), lineWidth: 0.8)
                }
            }
    }
}

private extension View {
    func nexusLayer(cornerRadius: CGFloat, depth: NexusLayerDepth) -> some View {
        modifier(NexusLayerModifier(cornerRadius: cornerRadius, depth: depth))
    }
    func nexusCard() -> some View {
        padding(CaelestiaParityTokens.Nexus.cardPadding)
            // Cards in the same Nexus column should share one edge even when
            // their content is intrinsically narrower than the page.
            // The old shrink-to-content behavior made adjacent cards look as
            // though they belonged to different layout systems.
            .frame(maxWidth: .infinity, alignment: .leading)
            .nexusLayer(cornerRadius: Rounding.large, depth: .card)
    }

    /// Makes a scroll view's content hit-testable across its whole area,
    /// including the gaps between rows.
    ///
    /// SwiftUI only hit-tests where something is actually drawn, so the
    /// spacing between cards in a VStack is dead space: a scroll gesture
    /// starting there never reaches the enclosing ScrollView and falls through
    /// to whatever is behind the window. The effect is that scrolling only
    /// works while the pointer happens to be over a row, and stops the moment
    /// it lands between two -- which is not obviously a hit-testing problem
    /// when you hit it, it just feels like the list intermittently jams.
    ///
    /// The full-width frame matters as much as the shape: without it the
    /// content is only as wide as its widest row, leaving the margins dead
    /// for the same reason.
    func nexusScrollBody() -> some View {
        frame(maxWidth: .infinity, alignment: .leading)
            .contentShape(Rectangle())
    }
    func nexusResetScroll(anchorID: String) -> some View {
        modifier(NexusScrollResetModifier(anchorID: anchorID))
    }
    func nexusLabel() -> some View { font(.system(size: ShellTypography.label, weight: .bold, design: .rounded)).foregroundStyle(NexusStudioStyle.muted) }
    func nexusValue() -> some View { font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded)).foregroundStyle(NexusStudioStyle.bright) }

    // The four text roles shared by every bottom-rail hover popout's header
    // card and content cards (activeApp, wifi, bluetooth, battery, audio,
    // calendar, workspace). Each popout used to pick its own nearby size --
    // 11 vs 13 for a title, 8 vs 8.5 vs 9 for a caption -- close enough to
    // pass a glance but different under a ruler. One set of roles here means
    // that drifts back to one call site instead of seven.
    func popoverCardTitle() -> some View { font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded)).foregroundStyle(Theme.bright) }
    func popoverCardSubtitle() -> some View { font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro))).foregroundStyle(Theme.muted) }
    func popoverRowTitle() -> some View { font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded)).foregroundStyle(Theme.bright) }
    func popoverRowCaption() -> some View { font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro))).foregroundStyle(Theme.muted) }
}

private struct RailPopoverView: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var nexus: MacPlusPlusNexusModel
    @ObservedObject var motion: SurfaceMotionState
    @ObservedObject var surface: RailPopoverState
    let hoverChanged: (Bool) -> Void
    let openDashboard: () -> Void
    let openLauncher: () -> Void
    let openNexus: () -> Void
    let toggleMask: () -> Void
    let paletteChanged: () -> Void
    let close: () -> Void
    let floatingShell: Bool
    let shellHeight: CGFloat
    @State private var hoveredPower: PowerCommand?

    private var kind: RailPopoverKind { surface.kind }

    var body: some View {
        Group {
            if kind == .shell {
                if floatingShell {
                    popoverBody
                        .background(Theme.frame.opacity(shellMaterialOpacity))
                        .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                        .overlay {
                            RoundedRectangle(cornerRadius: Rounding.large, style: .continuous)
                                .stroke(
                                    model.shellBorderEnabled
                                        ? Theme.accent.opacity(0.88)
                                        : ShellContourStyle.color,
                                    style: ShellContourStyle.stroke
                                )
                        }
                        .shadow(color: Theme.shadow, radius: Theme.isLight ? 7 : 12, y: Theme.isLight ? 2 : 5)
                        // Reveal the palette radially from the center. Let the
                        // aperture contract all the way to zero on dismissal;
                        // retaining a fixed seed at zero progress made a dot
                        // disappear, flash back, and then disappear again.
                        .mask {
                            GeometryReader { geometry in
                                let progress = max(0, min(1, motion.progress))
                                let fullDiameter = hypot(geometry.size.width, geometry.size.height) + 4
                                let rawDiameter = fullDiameter * progress
                                // Stop resizing before the aperture reaches
                                // unstable sub-pixel geometry. Its final few
                                // points dissolve once, without recreating a
                                // second seed or letting the circle wobble.
                                let stableDiameter = max(12, rawDiameter)
                                let terminalOpacity = min(1, rawDiameter / 12)
                                Circle()
                                    .frame(
                                        width: stableDiameter,
                                        height: stableDiameter
                                    )
                                    .opacity(terminalOpacity)
                                    .position(x: geometry.size.width / 2, y: geometry.size.height / 2)
                            }
                        }
                } else {
                    popoverBody
                        .background(Theme.frame.opacity(shellMaterialOpacity))
                        .clipShape(UnevenRoundedRectangle(
                            topLeadingRadius: 0,
                            bottomLeadingRadius: 0,
                            bottomTrailingRadius: 16,
                            topTrailingRadius: 0,
                            style: .continuous
                        ))
                }
            } else {
                // The shared LivingSurface is the sole animated contour mask.
                // Clipping the content a second time here used to rasterize
                // the same reverse shoulders in local window coordinates,
                // shrinking the visible top/bottom gutters and leaving a
                // false strip beneath Power. Keep the surface rectangular;
                // only the inner information box clips destination rows while
                // AppKit is still growing the panel.
                //
                // Nor may this be wrapped in a flexible frame to clip against
                // the window. `popoverBody` ends in an explicit
                // `.frame(width:height:)`, and that definite size is what the
                // hosting view measures itself from. Wrapping it in
                // `.frame(maxWidth: .infinity, maxHeight: .infinity)` makes the
                // content claim it wants unbounded space instead, so the
                // proposed size goes infinite -- which mis-sizes every popout
                // and reaches the surface path math as NaN, where CoreGraphics
                // crashes outright. The content box now follows the current
                // AppKit frame, with a small inner clip for the growing edge.
                popoverBody
            }
        }
        .onHover(perform: hoverChanged)
    }

    private var popoverBody: some View {
        // `contentSize` is the frozen destination box. Never let the live
        // AppKit frame replace the SwiftUI layout proposal while the outer
        // surface is extending: the host view below is the clip window.
        let layoutWidth = max(0, surface.contentSize?.width ?? width)
        let layoutHeight = max(0, surface.contentSize?.height ?? height)
        let popoverEnvelope = envelope
        let contentWidth = max(0, layoutWidth - popoverEnvelope.horizontal)
        // Left/right popout silhouettes reserve a 20pt shoulder at their free
        // top and bottom corners. It is geometric surface area, not content
        // space, so the visible gutter starts after it. The floating shell
        // uses a plain rounded rectangle and keeps its small 4pt envelope.
        // The bottom shelf's free edge is already the top edge of the mirrored
        // bottom-attached morph. Keep its compact content close to that edge;
        // the left rail cards still reserve their full perpendicular shoulder.
        let verticalShapeShoulder: CGFloat = (kind == .shell || kind == .appShelf)
            ? 0
            : surfaceMorphShoulder
        let topGutter = verticalShapeShoulder + popoverEnvelope.top
        let groundedAtBottom = surface.attachment == .left
            && motion.mergeBottomFillet > 0.0001
        let fallbackBottomGutter = groundedAtBottom
            ? railPopoverGroundedBottomGutter
            : verticalShapeShoulder + popoverEnvelope.bottom
        let bottomGutter = surface.contentBottomGutter ?? fallbackBottomGutter
        let contentHeight = max(0, layoutHeight - topGutter - bottomGutter)
        let physicalContentProgress = min(
            max(0, min(1, motion.contourProgress)),
            max(0, min(1, motion.surfacePlacementProgress))
        )
        let contentPlacementThreshold = CaelestiaParityTokens.Popout.contentPlacementThreshold
        let canMountRailContent = !motion.strictContentGate
            || (
                motion.contentReady
                    && motion.contentPlacementStable
                    && physicalContentProgress >= contentPlacementThreshold
            )

        // Do not express the vertical envelope as padding around a fixed
        // child. SwiftUI can satisfy that combination by proposing the full
        // height to the child, which makes the first pill touch the top rim
        // while the AppKit panel still reports the gutter in its outer size.
        // Structural spacers are unambiguous: the card stack starts exactly
        // `top` points below the geometric shoulder and ends exactly `bottom`
        // points above the opposite shoulder on every fresh open and every
        // live resize. The whole tree remains at the destination size. The
        // AppKit container, not a second SwiftUI viewport, clips it while the
        // panel travels. Re-proposing a shorter VStack on every display-link
        // tick was the reason only the first and last layered cards could
        // flicker; they were the layers crossing that moving clip boundary.
        return VStack(spacing: 0) {
            Color.clear
                .frame(width: layoutWidth, height: topGutter)
            HStack(spacing: 0) {
                Color.clear.frame(width: popoverEnvelope.leading)
                ZStack(alignment: .topLeading) {
                    // Keep the destination tree mounted in its frozen layout
                    // box from the first frame. Replacing it with Color.clear
                    // and mounting it at the placement threshold caused
                    // AsyncImage, ScrollView, and AppKit-backed controls to
                    // repaint on a different compositor turn than the host
                    // frame, which was the visible card flicker. The tree is
                    // still fully hidden and non-interactive until the
                    // surface is safe; only its opacity changes at that point.
                    Group {
                        switch kind {
                        case .shell: shell
                        case .activeApp: activeApp
                        case .runningApp(let pid): runningApp(pid)
                        case .appShelf: appShelf
                        case .media: media
                        case .power: power
                        case .wifi: wifi
                        case .bluetooth: bluetooth
                        case .audio: RailAudioControls(model: model, nexus: nexus)
                        case .battery: battery
                        case .calendar: MiniCalendarCard(model: model, showsCard: false)
                        case .workspace(let index): workspace(index)
                        }
                    }
                    .id(RailPopoverContentIdentity(kind: kind, revision: surface.contentRevision))
                    // Keep the destination tree in its intrinsic, kind-sized
                    // layout box. The parent AppKit clip reveals it as the
                    // frame moves; it must not be measured against that
                    // intermediate frame.
                    .frame(width: contentWidth, height: contentHeight, alignment: .topLeading)
                    .opacity(canMountRailContent ? 1 : 0)
                    .allowsHitTesting(canMountRailContent)
                    // AppKit and the shell contour already animate the
                    // surface. Suppress nested implicit animations only during
                    // a physical transition; steady-state media progress and
                    // status updates retain their authored effects.
                    .transaction { transaction in
                        let surfaceIsMoving = motion.progress < 0.999
                            || motion.surfacePlacementProgress < 0.999
                            || motion.morphFromAttachment != nil
                            || !motion.contentReady
                        if surfaceIsMoving {
                            transaction.animation = nil
                            transaction.disablesAnimations = true
                        }
                    }
                }
                .motionChild(
                    motion,
                    index: 1,
                    // The shelf is already attached to the display's bottom
                    // edge. Do not make its icons enter from the left rail;
                    // that rail-to-shelf handoff reads like a teleport.
                    offset: kind == .appShelf ? .zero : CGSize(width: -16, height: 0),
                    followsSurface: kind != .appShelf
                )
                Color.clear.frame(width: popoverEnvelope.trailing)
            }
            .frame(width: layoutWidth, height: contentHeight, alignment: .leading)
            Color.clear
                .frame(width: layoutWidth, height: bottomGutter)
        }
        .frame(width: layoutWidth, height: layoutHeight, alignment: .topLeading)
    }

    // The content begins after the same reverse shoulder used by the notch.
    // Keeping controls out of that shoulder makes the surface read as one
    // continuous extrusion from the rail instead of a card laid over it.
    private var width: CGFloat {
        switch kind {
        case .shell: shellStudioWidth
        case .power: sessionDrawerSurfaceWidth
        case .appShelf:
            caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexus)
        // Match the authored component width and let only height vary with
        // the live content.
        case .activeApp, .runningApp, .media, .wifi, .bluetooth, .audio, .battery, .calendar, .workspace:
            caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexus)
        }
    }
    private var height: CGFloat {
        switch kind {
        case .shell: shellHeight
        case .appShelf:
            appShelfContentHeight + appShelfTopGutter + appShelfBottomGutter
        // 36pt identity card + 8pt gap + 30pt icon action row.
        case .activeApp: activeAppPopoverContentHeight + leftPopoverVerticalInset * 2
        case .runningApp(let pid): appRailPopoverHeight(for: model.appRailApplications.first(where: { $0.id == pid }))
        case .media: mediaPopoverContentHeight + leftPopoverVerticalInset * 2
        case .power: sessionDrawerSurfaceHeight
        case .wifi:
            wifiPopoverHeight(
                networkCount: visibleWiFiNetworks.count,
                hasVPN: !model.vpnName.isEmpty,
                hasHiddenConnection: hasHiddenConnectedWiFi
            )
        case .bluetooth: bluetoothHeight
        // Single-line title header (~18) + 10pt gap + the fixed 32pt status
        // tile (now a single icon+text row instead of a two-line stack with
        // a redundant "BATTERY STATUS" caption) + 10pt gap + the fixed 30pt
        // toggle row = 100.
        case .battery: batteryPopoverContentHeight + leftPopoverVerticalInset * 2
        // A static budget here always overshot on 5-row months (most
        // months); this now matches the actual month being shown instead of
        // always budgeting for a worst-case 6-row month. See
        // calendarPopoverHeight's own comment for the row math.
        case .calendar: calendarPopoverHeight(for: model.now)
        case .audio:
            audioPopoverContentHeight(
                outputCount: nexus.outputDevices.count,
                inputCount: nexus.inputDevices.count
            ) + leftPopoverVerticalInset * 2
        case .workspace(let index):
            workspacePopoverHeight(windowCount: workspaceWindowCount(for: index))
        }
    }

    private func workspaceWindowCount(for index: Int) -> Int {
        if let override = surface.workspaceContentOverride, override.id == index {
            return override.windows.count
        }
        return model.workspaces.first(where: { $0.id == index })?.windows.count ?? 0
    }
    /// Use one live list for both the Bluetooth body and its host height. Show
    /// connected devices first, then paired/recent devices, with the same
    /// five-row bound as Bluetooth.qml. This keeps the rail compact while
    /// allowing a real machine with several devices to show more than the old
    /// hand-picked three-device approximation.
    private var visibleWiFiNetworks: [KnownWiFiNetwork] {
        railWiFiNetworks(from: model.knownNetworks, connected: model.connectedNetwork)
    }

    private var visibleBluetoothDevices: [BluetoothDeviceInfo] {
        railBluetoothDevices(from: model.bluetoothDevices)
    }

    private var activeApp: some View {
        VStack(spacing: PopoverCard.stackSpacing) {
            HStack(spacing: 9) {
                Image(nsImage: model.frontAppIcon)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: 28, height: 28)
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.small, style: .continuous))
                Text(model.frontApp.uppercased())
                    .popoverCardTitle()
                    .lineLimit(1)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.headerHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            HStack(spacing: 7) {
                activeAppMetric("CPU", String(format: "%.1f%%", model.frontAppCPUPercent))
                activeAppMetric("RAM", frontAppMemoryText)
            }
        }
    }

    private func activeAppMetric(_ label: String, _ value: String) -> some View {
        HStack(spacing: 6) {
            Text(label)
                .popoverRowCaption()
            Spacer(minLength: 2)
            Text(value)
                .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                .monospacedDigit()
                .foregroundStyle(Theme.bright)
                .lineLimit(1)
        }
        .padding(.horizontal, PopoverCard.horizontalPadding)
        .frame(maxWidth: .infinity)
        .frame(height: PopoverCard.rowHeight)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
    }

    private var frontAppMemoryText: String {
        let formatter = ByteCountFormatter()
        formatter.allowedUnits = [.useMB, .useGB]
        formatter.countStyle = .memory
        formatter.includesActualByteCount = false
        return formatter.string(fromByteCount: Int64(min(UInt64(Int64.max), model.frontAppMemoryBytes)))
    }

    private func compactAppAction(
        _ symbol: String,
        label: String,
        destructive: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .frame(width: 30, height: 30)
                .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(destructive ? Theme.accent : Theme.bright)
        .background(Theme.layerTile, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(Theme.seam.opacity(0.35), lineWidth: 0.55)
        }
        .help(label)
        .accessibilityLabel(label)
    }

    /// Compact now-playing surface for the rail's vertical title lane. The
    /// picture-in-picture block keeps the source visible (Spotify, Safari, or
    /// another active player) while the metadata and transport stay in the
    /// same card rhythm as the top media surface.
    private var media: some View {
        VStack(spacing: PopoverCard.stackSpacing) {
            HStack(spacing: 10) {
                mediaPictureInPicture
                VStack(alignment: .leading, spacing: 4) {
                    Text(model.media.title)
                        .font(.system(size: ShellTypography.value, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(2)
                        .minimumScaleFactor(0.72)
                    Text(model.media.artist.isEmpty ? "—" : model.media.artist)
                        .popoverRowTitle()
                        .lineLimit(1)
                    if let album = distinctMediaAlbum(
                        model.media.album,
                        title: model.media.title,
                        artist: model.media.artist
                    ) {
                        Text(album)
                            .popoverRowCaption()
                            .lineLimit(1)
                    }
                }
                .padding(.horizontal, 9)
                .padding(.vertical, 8)
                .frame(maxWidth: .infinity, alignment: .leading)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            }
            .frame(maxWidth: .infinity)
            .frame(height: mediaArtworkRowHeight)

            if model.media.durationKnown || model.media.isLive {
                HStack(spacing: 7) {
                    Text(mediaTime(model.media.position))
                    GeometryReader { geometry in
                        ZStack(alignment: .leading) {
                            Capsule().fill(Theme.sliderTrack)
                            if model.media.durationKnown {
                                Capsule()
                                    .fill(LinearGradient(
                                        colors: [Theme.accent, Theme.ice],
                                        startPoint: .leading,
                                        endPoint: .trailing
                                    ))
                                    .frame(width: geometry.size.width * min(1, max(0, model.media.progress)))
                            } else {
                                Capsule().fill(Theme.accent)
                                    .frame(width: 24)
                            }
                        }
                    }
                    .frame(height: 4)
                    Text(model.media.isLive ? "LIVE" : mediaTime(model.media.duration))
                }
                .font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                .monospacedDigit()
                .foregroundStyle(Theme.muted)
                .frame(height: 16)
                .animation(ShellMotion.valueChange.animation, value: model.media.progress)
            }

            HStack(spacing: 16) {
                let seeks = model.mediaSeeksInsteadOfSkipping
                mediaTransportButton(seeks ? "gobackward.15" : "backward.fill") {
                    model.mediaAction(seeks ? "backward" : "previous")
                }
                mediaTransportButton(model.media.playing ? "pause.fill" : "play.fill", primary: true) {
                    model.mediaAction("playpause")
                }
                mediaTransportButton(seeks ? "goforward.15" : "forward.fill") {
                    model.mediaAction(seeks ? "forward" : "next")
                }
                if model.cinemaControlAvailable {
                    mediaTransportButton(
                        "rectangle.inset.filled",
                        active: model.cinemaPresentation != nil,
                        busy: model.cinemaMutationInFlight
                    ) {
                        if NSEvent.modifierFlags.contains(.option) { model.cycleCinemaMode() }
                        else { model.toggleCinemaMode() }
                    }
                    .disabled(model.cinemaMutationInFlight)
                    .help(model.cinemaControlHelp)
                    .accessibilityLabel(model.cinemaMutationInFlight ? model.cinemaOperationLabel : "Cinema mode")
                    .accessibilityValue(model.cinemaPresentation?.title ?? "Off")
                }
            }
            .frame(maxWidth: .infinity)
            .frame(height: 38)
        }
    }

    private var mediaPictureInPicture: some View {
        ZStack(alignment: .bottomLeading) {
            Group {
                SharedAlbumArtwork(
                    url: URL(string: model.media.artworkURL),
                    revision: model.media.artworkRevision,
                    fallback: AnyView(mediaPictureFallback),
                    loader: model.topBarArtworkLoader
                )
            }
            .frame(width: mediaArtworkSize, height: mediaArtworkSize)
            LinearGradient(
                colors: [.clear, Theme.surface.opacity(0.86)],
                startPoint: .center,
                endPoint: .bottom
            )
            HStack(spacing: 4) {
                Image(systemName: mediaSourceSymbol)
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                Text(mediaSourceTitle)
                    .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                    .lineLimit(1)
            }
            .foregroundStyle(Theme.bright)
            .padding(.horizontal, 6)
            .padding(.vertical, 5)
        }
        .frame(width: mediaArtworkSize, height: mediaArtworkSize)
        .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(Theme.seam.opacity(0.32), lineWidth: 0.7)
        }
        .shadow(color: Theme.shadow.opacity(0.52), radius: 5, y: 2)
        .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .help("Now playing in \(mediaSourceTitle)")
    }

    private var mediaPictureFallback: some View {
        ZStack {
            Theme.surfaceRaised
            Image(systemName: mediaSourceSymbol)
                .font(.system(size: ShellIcon.hero, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.ice)
        }
    }

    private var mediaSourceTitle: String {
        switch mediaSourceKind {
        case "spotify": return "SPOTIFY"
        case "safari": return "SAFARI"
        case "browser": return "MAC++ BROWSER"
        case "active-media": return "ACTIVE MEDIA"
        default:
            let value = model.media.source.trimmingCharacters(in: .whitespacesAndNewlines)
            return value.isEmpty || value.lowercased() == "none" ? "ACTIVE MEDIA" : value.uppercased()
        }
    }

    private var mediaSourceSymbol: String {
        switch mediaSourceKind {
        case "safari": return "safari"
        case "spotify": return "music.note.list"
        case "browser": return "globe"
        case "active-media": return "play.square.stack"
        default: return "play.square.stack"
        }
    }

    private var mediaSourceKind: String {
        let source = model.media.source.lowercased()
        if source.contains("spotify") || model.preferredMediaSource == "spotify" {
            return "spotify"
        }
        if source.contains("safari") ||
            (model.mediaSeeksInsteadOfSkipping && !source.contains("macpp-browser") && !source.contains("macplusplusbrowser")) {
            return "safari"
        }
        if source.contains("macpp-browser") || source.contains("macplusplusbrowser") {
            return "browser"
        }
        if source.contains("active-media") || model.media.device.lowercased().contains("active-media") {
            return "active-media"
        }
        return "active"
    }

    private func mediaTime(_ seconds: Double) -> String {
        guard seconds.isFinite, seconds > 0, seconds <= 30 * 24 * 60 * 60 else { return "0:00" }
        let value = Int(seconds.rounded(.down))
        return "\(value / 60):\(String(format: "%02d", value % 60))"
    }

    private func mediaTransportButton(
        _ symbol: String,
        primary: Bool = false,
        active: Bool = false,
        busy: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            ZStack {
                if busy {
                    ProgressView()
                        .controlSize(.mini)
                        .tint(active ? Theme.accent : Theme.bright)
                        .transition(.opacity.combined(with: .scale(scale: 0.84)))
                } else {
                    Image(systemName: symbol)
                        .font(.system(
                            size: (primary ? 15 : 13) * mediaGlyphScale(symbol),
                            weight: .bold,
                            design: .rounded
                        ))
                        .contentTransition(.symbolEffect(.replace.downUp))
                        .transition(.opacity.combined(with: .scale(scale: 0.84)))
                }
            }
            .frame(width: primary ? 38 : 30, height: primary ? 38 : 30)
            .contentShape(Circle())
        }
        .buttonStyle(MediaCircleButtonStyle())
        .foregroundStyle(primary ? Theme.frame : (active ? Theme.accent : Theme.bright))
        .background(
            primary ? Theme.ice : (active ? Theme.accent.opacity(0.18) : (Theme.isLight ? Color.clear : Theme.tile.opacity(0.62))),
            in: Circle()
        )
        .overlay {
            Circle().stroke(
                primary && Theme.isLight ? Color.clear :
                    (primary ? Theme.bright.opacity(0.36) : (active ? Theme.accent.opacity(0.52) : Theme.seam.opacity(0.18))),
                lineWidth: 0.6
            )
        }
        .contentShape(Circle())
        .animation(ShellMotion.contentIn.animation, value: symbol)
        .animation(ShellMotion.valueChange.animation, value: active)
        .animation(ShellMotion.contentIn.animation, value: busy)
    }

    private func runningApp(_ pid: Int32) -> some View {
        Group {
            if let application = model.appRailApplications.first(where: { $0.id == pid }) {
                runningAppCard(application)
            } else {
                VStack(spacing: PopoverCard.stackSpacing) {
                    HStack(spacing: 8) {
                        Image(systemName: "app.dashed")
                            .foregroundStyle(Theme.accent)
                        Text("APP CLOSED")
                            .popoverCardTitle()
                        Spacer()
                    }
                    .padding(.horizontal, PopoverCard.horizontalPadding)
                    .frame(height: PopoverCard.headerHeight)
