    private func runningAppCard(_ application: AppRailApplication) -> some View {
        VStack(spacing: PopoverCard.stackSpacing) {
            HStack(spacing: 9) {
                Image(nsImage: appIcon(for: application))
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: 24, height: 24)
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.small, style: .continuous))
                    .saturation(0)
                    .opacity(0.86)
                Text(application.name.uppercased())
                    .popoverCardTitle()
                    .lineLimit(1)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.headerHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)

            HStack(spacing: 6) {
                compactAppAction("arrow.up.right.square", label: "Focus \(application.name)") {
                    model.focusApp(application)
                }
                compactAppAction("plus.square", label: "New window in \(application.name)") {
                    model.openNewWindow(for: application)
                }
                if application.supportsNewTab {
                    compactAppAction("plus.rectangle.on.rectangle", label: "New tab in \(application.name)") {
                        model.openNewTab(for: application)
                    }
                }
                compactAppAction("eye.slash", label: "Hide \(application.name)") {
                    model.hideApp(application)
                    close()
                }
                compactAppAction("xmark", label: "Quit \(application.name)", destructive: true) {
                    model.quitApp(application)
                    close()
                }
            }
            .frame(maxWidth: .infinity, alignment: .center)
        }
    }

    private func appIcon(for application: AppRailApplication) -> NSImage {
        let path = application.bundlePath.isEmpty
            ? "/System/Library/CoreServices/Finder.app"
            : application.bundlePath
        return NSWorkspace.shared.icon(forFile: path)
    }

    private var bluetoothHeight: CGFloat {
        bluetoothPopoverHeight(deviceCount: visibleBluetoothDevices.count)
    }
    private var envelope: RailPopoverEnvelope {
        switch kind {
        case .shell:
            return RailPopoverEnvelope(leading: 4, trailing: 4, top: 4, bottom: 4)
        case .appShelf:
            // A bottom-attached surface is symmetric on its free horizontal
            // edges. The top gets a slightly roomier optical inset while the
            // bottom stays tight; the outer contour still paints the
            // reverse-curve attachment band.
            return RailPopoverEnvelope(
                leading: railPopoverVerticalGutter,
                trailing: railPopoverVerticalGutter,
                top: appShelfTopGutter,
                bottom: appShelfBottomGutter
            )
        case .power:
            return RailPopoverEnvelope(
                leading: railPopoverContentGutter,
                trailing: railPopoverAttachedGutter,
                top: railPopoverVerticalGutter,
                bottom: railPopoverVerticalGutter
            )
        default:
            return RailPopoverEnvelope(
                leading: railPopoverAttachedGutter,
                trailing: railPopoverContentGutter,
                top: railPopoverVerticalGutter,
                bottom: railPopoverVerticalGutter
            )
        }
    }

    private var appShelf: some View {
        let applications = Array(model.appRailApplications.prefix(appShelfMaxApplications))
        return HStack(spacing: appShelfItemSpacing) {
            ForEach(applications) { application in
                appShelfItem(application)
            }
        }
        .padding(.horizontal, appShelfHorizontalPadding)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Theme.frame.opacity(shellMaterialOpacity))
    }

    private func appShelfItem(_ application: AppRailApplication) -> some View {
        let isFrontmost = model.frontAppPID == application.id
        let isDormant = application.isShelfDormant
        return Button {
            model.focusApp(application)
            close()
        } label: {
            Image(nsImage: appIcon(for: application))
                .resizable()
                .interpolation(.high)
                .scaledToFit()
                .frame(width: 24, height: 24)
                .clipShape(Circle())
                .saturation(isDormant ? 0.15 : 1)
                .opacity(
                    application.windows.isEmpty
                        ? 0.55
                        : (application.allWindowsMinimized ? 0.68 : 1)
                )
                .shadow(color: Theme.shadow.opacity(0.28), radius: 2, y: 1)
                .frame(width: appShelfItemWidth, height: appShelfItemHeight)
                .contentShape(Circle())
        }
        // Keep press feedback circular too; MicroButtonStyle's generic
        // rounded-rectangle press layer is the square ring this surface is
        // deliberately avoiding.
        .buttonStyle(MediaCircleButtonStyle())
        .foregroundStyle(Theme.bright)
        .background(
            isFrontmost
                ? Theme.layerSelected
                : (isDormant
                    ? Theme.surfaceRaised.opacity(application.windows.isEmpty ? 0.48 : 0.58)
                    : Theme.surfaceRaised),
            in: Circle()
        )
        .overlay {
            Circle()
                .stroke(
                    isFrontmost ? Theme.accent.opacity(0.72) : Theme.seam.opacity(0.24),
                    lineWidth: isFrontmost ? 0.9 : 0.45
                )
        }
        .contextMenu {
            Button("New Window") { model.openNewWindow(for: application) }
            if application.supportsNewTab {
                Button("New Tab") { model.openNewTab(for: application) }
            }
            Divider()
            Button("Hide") { model.hideApp(application) }
            Button("Quit") { model.quitApp(application) }
        }
        .help("Focus \(application.name) · \(application.shelfStatusDescription)")
        .accessibilityValue(application.shelfStatusDescription)
    }

