                    }
                }
            }
            .padding(3)
            .background(Theme.surfaceRaised, in: Capsule())
            Spacer(minLength: 5)
            HStack(spacing: 4) {
                Button(action: openNexus) {
                    Image(systemName: "square.grid.2x2").font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded)).frame(width: 32, height: 32)
                }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright).help("Open Nexus")
                Button(action: model.chooseMacPlusPlusWallpaper) {
                    Image(systemName: "photo").font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded)).frame(width: 32, height: 32)
                }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright).help("Manage palette wallpapers")
                Button(action: toggleMask) {
                    Image(systemName: model.menuMaskEnabled ? "menubar.rectangle" : "rectangle")
                        .font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded)).frame(width: 32, height: 32)
                }.buttonStyle(MicroButtonStyle()).foregroundStyle(model.menuMaskEnabled ? Theme.ice : Theme.muted).help("Toggle menu bar + Dock")
                Button(action: model.openSoftLockOverlay) {
                    Image(systemName: "lock.fill")
                        .font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded)).frame(width: 32, height: 32)
                }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright).help("Open soft lock overlay (non-native)")
                Button(action: openLauncher) {
