    private var power: some View {
        // Keep the native lock as a separate command, but expose the personal
        // soft overlay here as an explicit fifth action. It is a normal app
        // panel and never enters macOS's secure session.
        // Sleep is macOS's practical stand-in for hibernate. Six tiles with
        // native lock and display-off included felt bloated and duplicated
        // what sleep already does, so only the soft overlay joins the set.
        let actions: [(PowerCommand, String, String)] = [
            (.logout, "LOG OUT", "rectangle.portrait.and.arrow.right"), (.sleep, "SLEEP", "moon.fill"),
            (.shutdown, "Shut down", "power.circle"), (.restart, "Restart", "arrow.counterclockwise.circle"),
            (.softOverlay, "SOFT LOCK", "lock.fill")
        ]
        // Caelestia's session panel is a vertical stack of buttons in a
        // right-edge drawer -- plain drawn symbols, not wide text-heavy
        // rows. The label still carries the name as a tooltip.
        return ZStack {
        // Divide the drawer's actual available height (already
            // margin-correct -- popoverBody hands this view exactly
            // height - topInset - bottomInset) into equal shares
            // instead of a fixed row height + fixed gap. A hardcoded
            // sessionRowHeight/sessionRowGap pair only look even by
            // coincidence; GeometryReader guarantees each icon really gets
            // an even share of the space no matter how the drawer's
            // overall height changes later.
            GeometryReader { geo in
                let rowShare = geo.size.height / CGFloat(actions.count)
                // Buttons fill their row rather than sitting as a fixed 58pt
                // square inside it. At 108pt wide with an 89pt row, a centred
                // square left ~25pt dead either side and ~16pt above and
                // below, so the controls read as small objects adrift in a
                // tall empty drawer -- the proportion problem. Filling the
                // width, with only a hairline gap between rows, makes this a
                // stack of buttons instead of a column of floating icons.
                let gap: CGFloat = 10
                let buttonHeight = max(34, rowShare - gap)
                VStack(spacing: 0) {
                    ForEach(actions, id: \.0.rawValue) { action in
                        let (command, title, symbol) = action
                        Button { choosePower(command) } label: {
                            Image(systemName: symbol)
                                .font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                                .frame(maxWidth: .infinity)
                                .frame(height: buttonHeight)
                                .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                                .scaleEffect(hoveredPower == command ? 1.04 : 1)
                                // Readable regardless of palette: bright text
                                // color against the card fill, same contrast
                                // pairing used for every other rail control.
                        }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright)
                            .background(hoveredPower == command ? Theme.layerSelected : Theme.layerCard, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                            .overlay(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous).stroke(Theme.seam.opacity(0.22), lineWidth: 0.55))
                            .contentShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                            .onHover { inside in hoveredPower = inside ? command : (hoveredPower == command ? nil : hoveredPower) }
                            .animation(ShellMotion.hover.animation, value: hoveredPower)
                            .help(title)
                            .frame(maxWidth: .infinity)
                            .frame(height: rowShare)
                    }
                }
            }
            .zIndex(2)
        }
    }

    // No in-shell confirmation step. Shut down, restart and log out are all
    // issued through System Events' documented verbs, and those verbs raise
    // macOS's own confirmation dialog -- so the drawer's card was a second
    // dialog asking the same question about the same action, in a cramped
    // 88pt-wide panel. (The usual way to suppress the system dialog is to
    // send the raw loginwindow Apple Events instead, but performPower's own
    // comment records that being tried and abandoned: osascript reports
    // success even when loginwindow ignores the event, so the buttons
    // silently did nothing.) Sleep needs no confirmation at all.
    private func choosePower(_ command: PowerCommand) {
        model.performPower(command)
        close()
    }

    private var wifi: some View {
        VStack(alignment: .leading, spacing: PopoverCard.stackSpacing) {
            HStack {
                VStack(alignment: .leading, spacing: 2) {
                    Label("WI-FI", systemImage: model.wifiOn ? "wifi" : "wifi.slash")
                        .popoverCardTitle()
                }
                Spacer()
                Button { model.refreshWiFiNetworks() } label: {
                    Image(systemName: model.wifiScanning ? "dot.radiowaves.left.and.right" : "arrow.clockwise")
                        .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                        .frame(width: 26, height: 26)
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(Theme.muted)
                .disabled(!model.wifiOn || model.wifiScanning)
                .accessibilityLabel("Rescan Wi-Fi networks")
                Toggle("", isOn: Binding(get: { model.wifiOn }, set: { _ in model.toggleWiFi() }))
                    .disabled(model.wifiActionPending)
                    .accessibilityLabel("Wi-Fi")
                    .labelsHidden().toggleStyle(ShellSwitchToggleStyle(compact: true))
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.headerHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            if hasHiddenConnectedWiFi {
                wifiConnectedHiddenRow()
            }
            if visibleWiFiNetworks.isEmpty {
                HStack(spacing: 8) {
                    Image(systemName: model.wifiScanning
                        ? "arrow.triangle.2.circlepath"
                        : (model.wifiOn ? "wifi.exclamationmark" : "wifi.slash"))
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                    Spacer(minLength: 0)
                }
                .padding(.horizontal, PopoverCard.horizontalPadding)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            } else {
                VStack(spacing: wifiPopoverRowSpacing) {
                    ForEach(visibleWiFiNetworks) { network in
                        wifiNetworkRow(network)
                    }
                }
            }
            if !model.vpnName.isEmpty {
                HStack {
                    Label("VPN", systemImage: "network.badge.shield.half.filled")
                        .popoverRowCaption().lineLimit(1)
                    Spacer()
                    Toggle("", isOn: Binding(get: { model.vpnConnected }, set: { _ in model.toggleVPN() }))
                        .labelsHidden().toggleStyle(ShellSwitchToggleStyle(compact: true))
                }
                .padding(.horizontal, PopoverCard.horizontalPadding)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            }
        }
        // The shell/frame animator owns the spatial transition; controls animate locally.
    }

    private var hasHiddenConnectedWiFi: Bool {
        model.wifiConnected
            && model.connectedNetwork.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func wifiNetworkRow(_ network: KnownWiFiNetwork) -> some View {
        let active = model.wifiConnected && wifiNamesEqual(network.name, model.connectedNetwork)
        return Button {
            if active {
                model.disconnectWiFi()
            } else {
                model.connectWiFi(network)
            }
        } label: {
            HStack(spacing: 8) {
                Image(systemName: active ? "wifi" : "wifi.slash")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(active ? Theme.ice : Theme.muted)
                    .frame(width: 16)
                Text(network.name)
                    .popoverRowTitle()
                    .lineLimit(1)
                    .minimumScaleFactor(0.78)
                    .frame(maxWidth: .infinity, alignment: .leading)
                if network.secure == true {
                    Image(systemName: "lock.fill")
                        .font(.system(size: ShellTypography.nano, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                }
                Image(systemName: active ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(active ? Theme.ice : Theme.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.rowHeight)
            .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .disabled(!model.wifiOn || model.wifiActionPending)
        .background(active ? Theme.layerSelected : Theme.layerGroup, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(active ? Theme.accent.opacity(0.62) : Theme.seam.opacity(0.22), lineWidth: active ? 0.75 : 0.55)
        }
        .accessibilityValue(active ? "Connected" : "Available")
        .accessibilityHint(active ? "Tap to disconnect" : "Tap to connect")
        // The AppKit surface owns the only spatial reveal. Scaling each row
        // from 70% made network results arrive on a second, faster timeline
        // and could expose a row before the resized host had caught up.
        // Do not attach a transition to a live scan row. The list can receive
        // its result on the same turn that the host window changes size; the
        // shared popout transition is the only reveal owner.
    }

