    private var bluetooth: some View {
        VStack(alignment: .leading, spacing: PopoverCard.stackSpacing) {
            HStack(spacing: 9) {
                BluetoothMark(color: Theme.accent, size: 15)
                    .frame(width: 13)
                VStack(alignment: .leading, spacing: 2) {
                    Text("BLUETOOTH").popoverCardTitle()
                    Text(model.bluetoothScanning
                        ? "SCANNING NEARBY"
                        : (model.bluetoothDevices.contains(where: \.nearby)
                            ? "NEARBY & PAIRED DEVICES"
                            : "PAIRED DEVICES"))
                        .popoverCardSubtitle()
                }
                Spacer()
                Button { model.openURL("x-apple.systempreferences:com.apple.BluetoothSettings") } label: {
                    Image(systemName: "gearshape")
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .frame(width: 26, height: 26)
                }
                .buttonStyle(MicroButtonStyle())
                .foregroundStyle(Theme.muted)
                .accessibilityLabel("Open Bluetooth settings")
                Button { model.refreshBluetoothDevices(force: true) } label: {
                    Image(systemName: "arrow.clockwise").font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.muted)
                .disabled(model.bluetoothScanning)
                .accessibilityLabel("Rescan Bluetooth devices")
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.headerHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            Text({
                let connected = model.bluetoothDevices.filter(\.connected).count
                let nearby = model.bluetoothDevices.filter(\.nearby).count
                let inventory = nearby > 0 ? "\(nearby) NEARBY • " : ""
                let suffix = connected > 0 ? " • \(connected) CONNECTED" : ""
                return "\(inventory)\(model.bluetoothDevices.count) DEVICES AVAILABLE\(suffix)"
            }())
                .popoverRowCaption()
                .frame(height: 18, alignment: .leading)
            if visibleBluetoothDevices.isEmpty {
                HStack {
                    Image(systemName: "dot.radiowaves.left.and.right")
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.muted)
                    Spacer(minLength: 0)
                }
                .padding(.horizontal, PopoverCard.horizontalPadding)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            } else {
                // Keep the full paired/recent inventory mounted. The old
                // five-row prefix made a valid headset disappear whenever
                // enough phones/controllers sorted ahead of it. The viewport
                // stays compact and keeps the remainder reachable without
                // exposing a native scrollbar inside the popout.
                ScrollView(
                    .vertical,
                    showsIndicators: false
                ) {
                    VStack(spacing: PopoverCard.stackSpacing) {
                        ForEach(visibleBluetoothDevices) { device in
                            Button { model.toggleBluetooth(device) } label: {
                                HStack(spacing: 9) {
                                    Circle().fill(device.connected
                                        ? Theme.ice
                                        : (device.nearby ? Theme.accent : Theme.muted.opacity(0.30)))
                                        .frame(width: 6, height: 6)
                                    Text(compactAudioDeviceName(device.name)).lineLimit(1)
                                        .popoverRowTitle()
                                        .minimumScaleFactor(0.82)
                                        .frame(maxWidth: .infinity, alignment: .leading)
                                    Image(systemName: device.connected ? "checkmark.circle.fill" : (device.paired ? "circle" : "link.badge.plus"))
                                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                        .foregroundStyle(device.connected ? Theme.ice : Theme.muted.opacity(0.58))
                                        .frame(width: 18)
                                }
                                .padding(.horizontal, PopoverCard.horizontalPadding)
                                .frame(height: PopoverCard.rowHeight)
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(MicroButtonStyle())
                            .background(device.connected ? Theme.layerSelected : Theme.layerGroup, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                            .overlay {
                                RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                                    .stroke(device.connected ? Theme.accent.opacity(0.62) : Theme.seam.opacity(0.22), lineWidth: device.connected ? 0.75 : 0.55)
                            }
                            .disabled(model.bluetoothActionsPending.contains(device.address))
                            .accessibilityValue(device.connected ? "Connected" : (device.nearby ? "Nearby" : "Paired"))
                            .accessibilityHint(device.connected ? "Tap to disconnect" : (device.paired ? "Tap to connect" : "Tap to pair"))
                            // The selected tint is the one intentional state change;
                            // keep it transactional rather than attaching a row
                            // transition. blueutil can publish a nearby result
                            // while the host is still settling, and a second
                            // opacity timeline made the whole card flash.
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .contentShape(Rectangle())
                }
                .frame(height: bluetoothDeviceListHeight(deviceCount: visibleBluetoothDevices.count))
                .scrollIndicators(.never)
            }
        }
        // Scanning status is text inside a frame that may also be resizing.
        // Keep it transactional so a late blueutil result cannot leave the
        // outgoing subtitle ghosted behind the settled device list.
    }

    private func batteryTimeRemainingText(_ minutes: Int) -> String {
        let hours = minutes / 60
        let mins = minutes % 60
        return hours > 0 ? "\(hours)H \(mins)M" : "\(mins)M"
    }

    private var battery: some View {
        let chargingLabel = model.batteryPercent >= 100 ? "FULL" : "CHARGING"
        return VStack(alignment: .leading, spacing: PopoverCard.stackSpacing) {
            HStack {
                Label("BATTERY", systemImage: model.batterySymbol)
                    .popoverCardTitle()
                Spacer()
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.rowHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)

            HStack(spacing: 9) {
                ZStack {
                    Circle().fill((model.batteryPercent <= 10 ? Color.red : Theme.ice).opacity(0.15))
                    Image(systemName: model.batterySymbol).font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(model.batteryPercent <= 10 ? Color.red : Theme.ice)
                }.frame(width: 22, height: 22)
                VStack(alignment: .leading, spacing: 1) {
                    Text(model.charging
                        ? "\(model.batteryPercent)% \(chargingLabel)"
                        : "\(model.batteryPercent)% REMAINING")
                        .popoverRowTitle()
                        .lineLimit(1)
                    if let health = model.batteryHealthPercent,
                       let cycles = model.batteryCycleCount {
                        Text("HEALTH \(health)% · \(cycles)C")
                            .popoverRowCaption()
                            .lineLimit(1)
                    }
                }
                Spacer(minLength: 6)
                if let minutes = model.batteryTimeRemainingMinutes {
                    Text(model.charging
                        ? "\(batteryTimeRemainingText(minutes)) TO FULL"
                        : "\(batteryTimeRemainingText(minutes)) LEFT")
                        .popoverRowCaption()
                        .lineLimit(1)
                } else if model.charging {
                    Text("AC POWER")
                        .popoverRowCaption()
                        .lineLimit(1)
                }
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: 36)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)

            HStack(spacing: 7) {
                batteryMetric(
                    title: "SYSTEM DRAW",
                    value: model.batterySystemPowerWatts.map { String(format: "%.1fW", $0) } ?? "—",
                    symbol: "bolt.fill"
                )
                batteryMetric(
                    title: "ADAPTER",
                    value: model.batteryAdapterWatts.map { String(format: "%.0fW", $0) } ?? "—",
                    symbol: "powerplug.fill"
                )
            }

            HStack {
                Label("BATTERY SAVER", systemImage: "leaf")
                    .popoverRowCaption().lineLimit(1)
                Spacer()
                Toggle("", isOn: Binding(get: { model.batterySaverEnabled }, set: { model.setBatterySaver($0) }))
                    .labelsHidden().toggleStyle(ShellSwitchToggleStyle(compact: true))
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.rowHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
        }
    }

    private func batteryMetric(title: String, value: String, symbol: String) -> some View {
        HStack(spacing: 6) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
            VStack(alignment: .leading, spacing: 1) {
                Text(title)
                    .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                    .foregroundStyle(Theme.muted)
                    .lineLimit(1)
                Text(value)
                    .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.bright)
                    .monospacedDigit()
                    .lineLimit(1)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 9)
        .frame(maxWidth: .infinity, minHeight: 34, maxHeight: 34, alignment: .leading)
        .background(Theme.layerGroup, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(Theme.seam.opacity(0.22), lineWidth: 0.55)
        }
    }

    private func workspace(_ index: Int) -> some View {
        let space = surface.workspaceContentOverride.flatMap { $0.id == index ? $0 : nil }
            ?? model.workspaces.first(where: { $0.id == index })
            ?? WorkspaceInfo(id: index, name: "SPACE \(index)", apps: [], available: false)
        return VStack(alignment: .leading, spacing: PopoverCard.stackSpacing) {
            HStack(spacing: 9) {
                ZStack {
                    RoundedRectangle(cornerRadius: Rounding.small, style: .continuous)
                        .fill(Theme.accent.opacity(0.18))
                    Text("\(space.id)")
                        .font(.system(size: ShellTypography.cardTitle, weight: .heavy, design: .rounded))
                        .foregroundStyle(Theme.bright)
                }.frame(width: 30, height: 30)
                VStack(alignment: .leading, spacing: 2) {
                    Text(space.name).popoverCardTitle()
                }
                Spacer()
                Text("\(space.apps.count) \(space.apps.count == 1 ? "APP" : "APPS")")
                    .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .foregroundStyle(Theme.accent)
                    .padding(.horizontal, 8).padding(.vertical, 5)
                    .background(Theme.accent.opacity(0.10), in: Capsule())
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.headerHeight)
            .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            if !space.available {
                Image(systemName: "rectangle.dashed")
                .popoverRowCaption()
                .frame(maxWidth: .infinity)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            } else if space.windows.isEmpty {
                Image(systemName: "rectangle.dashed")
                .popoverRowCaption()
                .frame(maxWidth: .infinity)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            } else {
                VStack(spacing: 5) {
                    ForEach(space.windows.prefix(4)) { window in
                    HStack(spacing: 8) {
                        ZStack {
                            Circle().fill(Theme.accent.opacity(0.13))
                            Circle().fill(model.isNowPlayingApp(window.app) ? Theme.ice : Theme.accent)
                                .frame(width: 5, height: 5)
                        }.frame(width: 20, height: 20)
                        VStack(alignment: .leading, spacing: 1) {
                            Text(window.displayName)
                                .popoverRowTitle().lineLimit(1)
                            if !window.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                                Text(window.app.uppercased())
                                    .popoverRowCaption().lineLimit(1)
                            }
                        }
                        Spacer()
                        // Both indicators can be true at once -- a browser can
                        // play audio while a download runs -- so these stack.
                        if model.isDownloadingApp(window.app) {
                            Image(systemName: "arrow.down.circle")
                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.accent)
                                .symbolEffect(.pulse, isActive: true)
                        }
                        if model.isNowPlayingApp(window.app) {
                            Image(systemName: "waveform")
                                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                                .foregroundStyle(Theme.ice)
                        }
                    }
                    .padding(.horizontal, 8)
                    .frame(height: 31)
                    .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
                    .onDrag {
                        model.beginWindowDrag(window.id)
                        return NSItemProvider(object: NSString(string: "macpp-window:\(window.id)"))
                    }
                    .help("Drag \(window.displayName) to another workspace")
                    }
                }
            }
        }
        .contentShape(Rectangle())
        .onDrop(of: [UTType.text.identifier], isTargeted: nil) { providers in
            guard space.available else { return false }
            return model.acceptWindowDrop(providers, toSpace: index)
        }
        .help(space.available
            ? "Drop a window here to move it to \(space.name)"
            : "\(space.name) is not available")
    }

}

// Shared between two places: Nexus's overview page (the full dashboard
// context) and the rail's own .calendar hover popout (a quick glance
// without leaving the bar). Same card, same data, no duplicated layout.
private struct MiniCalendarCard: View {
    @ObservedObject var model: ShellModel
    // Nexus lays this out among other already-boxed dashboard cards, so it
    // needs its own .nexusCard() background there. The rail's .calendar
    // popout is different: the popout window itself already draws a full
    // card silhouette (the same shouldered surface every other rail popout
    // uses), so adding a second nested card here would double-box it and
    // eat into the small surface with an extra 14pt of padding no sibling
    // popout pays. Default stays true for the existing Nexus call site.
    var showsCard: Bool = true

    var body: some View {
        let calendar = Calendar.current
        let now = model.now
        let range = calendar.range(of: .day, in: .month, for: now) ?? 1..<2
        let first = calendar.date(from: calendar.dateComponents([.year, .month], from: now)) ?? now
        let leading = (calendar.component(.weekday, from: first) - calendar.firstWeekday + 7) % 7
        let today = calendar.component(.day, from: now)
        let header = HStack(spacing: 7) {
            // Every sibling rail popout (wifi/bluetooth/audio/battery)
            // leads its header with an icon; this card had none, which
            // was fine as a Nexus dashboard tile but read as the odd one
            // out once reused as a rail popout too.
            Image(systemName: "calendar").font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent)
            // The Nexus dashboard tile keeps its own larger 13pt title; the
            // rail popout matches every sibling popout's 11pt header title
            // instead.
                Text(now.formatted(.dateTime.month(.wide).year()))
                .font(.system(size: showsCard ? 13 : 11, weight: .semibold, design: .rounded)).foregroundStyle(Theme.bright)
            Spacer()
            Text(now.formatted(date: .omitted, time: .shortened))
                .font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).foregroundStyle(Theme.accent)
        }
        let grid = VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 0) {
                ForEach(rotatedWeekdays(calendar), id: \.self) { symbol in
                    Text(symbol).frame(maxWidth: .infinity)
                }
            }.font(.system(size: ShellTypography.label, weight: .bold, design: .rounded)).foregroundStyle(Theme.muted)
            LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 4), count: 7), spacing: 4) {
                // These leading spacers and the day cells below are siblings
                // in ONE LazyVGrid, so they share a single identity space.
                // Both used `id: \.self` over Int ranges -- spacers 0..<leading
                // and days 1...31 -- so their IDs genuinely collided (spacer
                // 1 vs day 1, spacer 2 vs day 2, ...). SwiftUI keeps only one
                // view per ID, so the first `leading - 1` days were silently
                // dropped: with leading == 3 the month visibly began at 3.
                // Negative IDs can never collide with a real day number.
                ForEach((0..<leading).map { -($0 + 1) }, id: \.self) { _ in
                    Color.clear.frame(height: 19)
                }
                ForEach(Array(range), id: \.self) { day in
                    Text("\(day)").font(.system(size: ShellTypography.body, weight: day == today ? .heavy : .medium, design: .rounded))
                        .foregroundStyle(day == today ? Theme.bright : Theme.muted)
                        .frame(maxWidth: .infinity).frame(height: 19)
                        .background(day == today ? Theme.accent.opacity(0.28) : Color.clear, in: Circle())
                }
            }
        }
        // The rail popout gives its header and its day grid their own cards,
        // matching every sibling popout's header-card-then-content-card
        // shape. Nexus's dashboard tile keeps its original bare layout
        // inside the one outer .nexusCard() below -- adding these inner
        // cards there too would double-box it.
        let content = VStack(alignment: .leading, spacing: 8) {
            if showsCard {
                header
            } else {
                header
                    .padding(.horizontal, PopoverCard.horizontalPadding)
                    .frame(height: PopoverCard.headerHeight)
                    .nexusLayer(cornerRadius: Rounding.normal, depth: .card)
            }
            if showsCard {
                grid
            } else {
                grid
                    .padding(PopoverCard.horizontalPadding)
                    .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
            }
        }
        return Group {
            if showsCard { content.nexusCard() } else { content }
        }
    }

    private func rotatedWeekdays(_ calendar: Calendar) -> [String] {
        let symbols = calendar.veryShortWeekdaySymbols
        guard !symbols.isEmpty else { return [] }
        let start = max(0, min(symbols.count - 1, calendar.firstWeekday - 1))
        return Array(symbols[start...] + symbols[..<start])
    }
}

private struct PowerMenu: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var motion: SurfaceMotionState
    let close: () -> Void
    @State private var pending: PowerCommand?
    @State private var hovered: PowerCommand?
    // Kept in sync with RailPopoverView.power. Native lock remains separate;
    // the personal soft overlay is the only lock-like action in this menu.
    private let actions: [(PowerCommand, String, String)] = [
        (.logout, "LOG OUT", "rectangle.portrait.and.arrow.right"), (.sleep, "SLEEP", "moon.fill"),
        (.shutdown, "Shut down", "power.circle"), (.restart, "Restart", "arrow.counterclockwise.circle"),
        (.softOverlay, "Soft lock", "lock.fill")
    ]
    var body: some View {
        ZStack {
            VStack(spacing: Spacing.base) {
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: Spacing.base), count: 2), spacing: Spacing.base) {
                    ForEach(Array(actions.enumerated()), id: \.element.0.rawValue) { index, action in
                        let (command, title, symbol) = action
                        Button { choose(command) } label: {
                            VStack(spacing: Spacing.snug) {
                                Image(systemName: symbol).font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                                    .contentTransition(.symbolEffect(.replace))
                                    .frame(width: 36, height: 31, alignment: .center)
                                Text(title).font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded))
                                    .frame(height: 14, alignment: .center)
                            }.frame(maxWidth: .infinity).frame(height: powerTileHeight)
                                .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                                .scaleEffect(hovered == command ? 1.02 : 1)
                        }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright)
                            .background(hovered == command ? Theme.accent.opacity(0.14) : Theme.tile.opacity(0.72), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                            .onHover { inside in hovered = inside ? command : (hovered == command ? nil : hovered) }
                            .animation(ShellMotion.hover.animation, value: hovered)
                            .motionChild(motion, index: index + 1, offset: CGSize(width: -8, height: 6))
                    }
                }
            }
            if let pending {
                VStack(spacing: Spacing.roomy) {
                    Image(systemName: pending == .restart ? "arrow.counterclockwise.circle.fill" : "power.circle.fill")
                        .font(.system(size: ShellIcon.feature, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent)
                    Text(pending == .restart ? "RESTART THIS MAC?" : "SHUT DOWN THIS MAC?")
                        .font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).foregroundStyle(Theme.bright)
                    HStack(spacing: Spacing.base) {
                        legacyConfirmationButton("Cancel", primary: false) { self.pending = nil }
                        legacyConfirmationButton(pending == .restart ? "Restart" : "Shut down", primary: true) {
                            model.performPower(pending); close()
                        }
                    }
                }
                .padding(Spacing.loose).frame(width: 286)
                .background(Theme.surfaceRaised, in: RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .clipShape(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: Rounding.large, style: .continuous).stroke(Theme.seam.opacity(0.72), lineWidth: 0.7))
                .shadow(color: Theme.shadow, radius: Theme.isLight ? 6 : 10, y: Theme.isLight ? 2 : 4)
                .transition(.scale(scale: 0.97).combined(with: .opacity))
                .zIndex(3)
            }
        }
        .animation(ShellMotion.popout.animation, value: pending)
        .frame(
            width: powerContentWidth,
            height: powerContentHeight,
            alignment: .center
        )
    }
    private func legacyConfirmationButton(_ title: String, primary: Bool, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Text(title)
                .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                .frame(width: 94, height: 29)
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(primary ? Theme.surface : Theme.bright)
        .background(primary ? Theme.ice : Theme.tile.opacity(0.78), in: Capsule())
        .overlay(Capsule().stroke(primary ? Color.clear : Theme.seam.opacity(0.55), lineWidth: 0.6))
    }
    private func choose(_ command: PowerCommand) {
        if command == .shutdown || command == .restart { pending = command }
        else { model.performPower(command); close() }
    }
}

private struct DrawerView: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var motion: SurfaceMotionState
    let page: Int; let close: () -> Void; let hoverChanged: (Bool) -> Void
    private let names = ["WORKSPACES", "SEARCH", "MEDIA", "PERFORMANCE", "SHORTCUTS", "CONTROL"]
    var body: some View {
        VStack(alignment: .leading, spacing: Spacing.roomy) {
            HStack {
                Text(names[page]).font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).foregroundStyle(Theme.bright)
                Spacer()
            }.motionChild(motion, index: 1, offset: CGSize(width: -9, height: 0))
            CaelestiaDivider(opacity: 0.35)
                .motionChild(motion, index: 2, offset: CGSize(width: -9, height: 0))
            Group {
                if page == 0 { workspaceContent }
                else if page == 2 { mediaContent }
                else if page == 3 { performanceContent }
                else if page == 4 { shortcutsContent }
                else { controlContent }
            }.motionChild(motion, index: 3, offset: CGSize(width: -12, height: 0))
            Spacer(minLength: 0)
        }.padding(Spacing.loose).frame(width: sidebarWidth, height: drawerHeight(page)).attachedLeft(CaelestiaParityTokens.Border.rounding, motion: motion)
            .onHover(perform: hoverChanged)
    }
    private var workspaceContent: some View {
        VStack(spacing: Spacing.base) {
            ForEach(Array([
                ("web", "safari"),
                ("work", "brain.head.profile"),
                ("code", "terminal"),
                ("play", "gamecontroller"),
                ("lab", "flask")
            ].enumerated()), id: \.offset) { index, item in
                let available = model.workspaces.first(where: { $0.id == index + 1 })?.available == true
                Button {
                    guard available else { return }
                    model.focusSpace(index + 1)
                    close()
                } label: {
                    HStack { Image(systemName: item.1); Text(item.0.uppercased()); Spacer(); Image(systemName: "arrow.right") }
                        .font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded)).padding(Spacing.roomy)
                }.buttonStyle(.plain)
                    .foregroundStyle(Theme.bright)
                    .disabled(!available)
                    .opacity(available ? 1 : 0.52)
                    .background(Theme.accent.opacity(0.10), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                    .onDrop(of: [UTType.text.identifier], isTargeted: nil) { providers in
                        guard available else { return false }
                        return model.acceptWindowDrop(providers, toSpace: index + 1)
                    }
                    .help(available
                        ? "Drop a window here to move it to \(item.0.uppercased())"
                        : "\(item.0.uppercased()) is not available")
            }
        }
    }
    private var mediaContent: some View {
        VStack(spacing: Spacing.roomy) {
            SpectrumRing(levels: model.levels, phase: model.phase).scaleEffect(0.82).frame(height: 112)
            MarqueeText(text: model.media.title).frame(height: 20)
            Text(model.media.artist).font(.system(size: ShellTypography.cardTitle, design: .rounded)).foregroundStyle(Theme.muted)
            HStack(spacing: Spacing.section) { Image(systemName: "backward.fill"); Image(systemName: model.media.playing ? "pause.fill" : "play.fill"); Image(systemName: "forward.fill") }.foregroundStyle(Theme.bright)
        }.frame(maxWidth: .infinity)
    }
    private var performanceContent: some View {
        VStack(spacing: Spacing.roomy) {
            metric("UPTIME", model.uptime, "clock.arrow.circlepath")
            metric("STORAGE", model.storage, "internaldrive")
            metric("MODE", "WORK / VISUAL", "bolt.fill")
        }
    }
    private var shortcutsContent: some View {
        VStack(spacing: Spacing.base) {
            shortcut("Search", "command") { model.open("MacPlusPlusCast"); close() }
            shortcut("Terminal", "terminal") { model.open("Terminal"); close() }
            shortcut("Safari", "safari") { model.open("Safari"); close() }
        }
    }
    private var controlContent: some View {
        VStack(spacing: Spacing.base) {
            shortcut("Search", "magnifyingglass") { model.open("MacPlusPlusCast"); close() }
            shortcut("Refresh network", "wifi") { model.refreshConnectivity(force: true) }
            shortcut("Quit shell", "xmark") { NSApp.terminate(nil) }
        }
    }
    private func metric(_ title: String, _ value: String, _ icon: String) -> some View {
        HStack { Image(systemName: icon).foregroundStyle(Theme.accent); VStack(alignment: .leading) { Text(title).font(.system(size: ShellTypography.label, design: .rounded)).foregroundStyle(Theme.muted); Text(value).font(.system(size: ShellTypography.value, weight: .bold, design: .rounded)).foregroundStyle(Theme.bright) }; Spacer() }
            .padding(Spacing.roomy).background(Theme.accent.opacity(0.09), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
    }
    private func shortcut(_ title: String, _ icon: String, action: @escaping () -> Void) -> some View {
        Button(action: action) { HStack { Image(systemName: icon); Text(title); Spacer(); Image(systemName: "arrow.up.right") }.font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded)).padding(Spacing.roomy) }
            .buttonStyle(.plain).foregroundStyle(Theme.bright).background(Theme.accent.opacity(0.09), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
    }
    @discardableResult
    private func run(_ command: String) -> Bool {
        let executable = command.split(whereSeparator: \.isWhitespace).first.map(String.init) ?? "unknown"
        return launchMacPlusPlusShellCommand(
            command, context: "observatory:\((executable as NSString).lastPathComponent)"
        )
    }
}

/// Tiny, bounded drag trace. It is intentionally kept in /tmp and only logs
/// drag lifecycle/payload decisions, never window titles or screen contents.
/// When a drag feels inert this tells us whether the failure happened before
/// AppKit delivered the pasteboard or while decoding the item provider.
private func macppWindowDragLog(_ message: String) {
    let line = "\(Date().timeIntervalSince1970) \(message)\n"
    guard let data = line.data(using: .utf8) else { return }
    let url = URL(fileURLWithPath: "/tmp/macpp-window-drag.log")
    if FileManager.default.fileExists(atPath: url.path),
       let handle = try? FileHandle(forWritingTo: url) { // macpp:silent-ok debug logging is best effort
        let size = (try? handle.seekToEnd()) ?? 0 // macpp:silent-ok failed log sizing uses the zero-size fallback
        if size > 256 * 1024 {
            try? handle.truncate(atOffset: 0) // macpp:silent-ok log rotation is best effort
        }
        _ = try? handle.seekToEnd() // macpp:silent-ok debug log positioning is best effort
        _ = try? handle.write(contentsOf: data) // macpp:silent-ok debug logging is best effort
        _ = try? handle.close() // macpp:silent-ok debug log closing is best effort
    } else {
        try? data.write(to: url, options: .atomic) // macpp:silent-ok debug logging is best effort
    }
}

private func macppWindowID(from pasteboard: NSPasteboard) -> Int? {
    let prefix = "macpp-window:"
    func parse(_ value: Any?) -> Int? {
        let raw: String? = {
            switch value {
            case let text as String: return text
            case let text as NSString: return text as String
            case let data as Data: return String(data: data, encoding: .utf8)
            case let data as NSData: return String(data: data as Data, encoding: .utf8)
            default: return nil
            }
        }()
        guard let raw, raw.hasPrefix(prefix), let id = Int(raw.dropFirst(prefix.count)) else { return nil }
        return id
    }

    // The exact UTI varies by source. Enumerate what the drag actually
    // advertised instead of assuming public.text is present.
    let identifiers = (pasteboard.types ?? []) + [
        .string,
        NSPasteboard.PasteboardType(UTType.utf8PlainText.identifier),
        NSPasteboard.PasteboardType(UTType.plainText.identifier),
        NSPasteboard.PasteboardType(UTType.text.identifier)
    ]
    for type in identifiers {
        if let id = parse(pasteboard.string(forType: type)) { return id }
        if let id = parse(pasteboard.propertyList(forType: type)) { return id }
        if let id = parse(pasteboard.data(forType: type)) { return id }
    }
    for item in pasteboard.pasteboardItems ?? [] {
        for type in identifiers {
            if let id = parse(item.string(forType: type)) { return id }
            if let id = parse(item.propertyList(forType: type)) { return id }
            if let id = parse(item.data(forType: type)) { return id }
        }
    }
    return nil
}

/// A drag destination attached only to the notch's own hosting view.
///
/// The previous experiment placed transparent panels over every display. That
/// made the whole desktop briefly non-interactive and still did not make the
/// notch a reliable destination. Keeping the destination at the panel level
/// lets normal mouse events pass through everywhere else while AppKit handles
/// the same `macpp-window:<id>` payload the working side rail already uses.
@MainActor private final class WorkspaceDropHostingView: NSHostingView<AnyView> {
    private let acceptsDrop: (NSPoint, NSPasteboard) -> Bool
    private let performDrop: (NSPoint, NSPasteboard) -> Bool
    private let updateDropTarget: (NSPoint, NSPasteboard) -> Void
    private let clearDropTarget: () -> Void

    init(
        rootView: AnyView,
        acceptsDrop: @escaping (NSPoint, NSPasteboard) -> Bool,
        performDrop: @escaping (NSPoint, NSPasteboard) -> Bool,
        updateDropTarget: @escaping (NSPoint, NSPasteboard) -> Void = { _, _ in },
        clearDropTarget: @escaping () -> Void = {}
    ) {
        self.acceptsDrop = acceptsDrop
        self.performDrop = performDrop
        self.updateDropTarget = updateDropTarget
        self.clearDropTarget = clearDropTarget
        super.init(rootView: rootView)
        registerForDraggedTypes([
            .string,
            NSPasteboard.PasteboardType(UTType.text.identifier)
        ])
    }

    @MainActor required init(rootView: AnyView) {
        self.acceptsDrop = { _, _ in false }
        self.performDrop = { _, _ in false }
        self.updateDropTarget = { _, _ in }
        self.clearDropTarget = {}
        super.init(rootView: rootView)
        registerForDraggedTypes([
            .string,
            NSPasteboard.PasteboardType(UTType.text.identifier)
        ])
    }

    required init?(coder: NSCoder) { nil }

    private func operation(for sender: NSDraggingInfo) -> NSDragOperation {
        let point = sender.draggingLocation
        let pasteboard = sender.draggingPasteboard
        let accepted = acceptsDrop(point, pasteboard)
        macppWindowDragLog("top-drag \(accepted ? "accept" : "reject") x=\(Int(point.x)) y=\(Int(point.y)) id=\(macppWindowID(from: pasteboard) ?? 0)")
        guard accepted else {
            clearDropTarget()
            return []
        }
        updateDropTarget(point, pasteboard)
        return .move
    }

    override func draggingEntered(_ sender: NSDraggingInfo) -> NSDragOperation {
        operation(for: sender)
    }

    override func draggingUpdated(_ sender: NSDraggingInfo) -> NSDragOperation {
        operation(for: sender)
    }

    override func prepareForDragOperation(_ sender: NSDraggingInfo) -> Bool {
        operation(for: sender) != []
    }

    override func performDragOperation(_ sender: NSDraggingInfo) -> Bool {
        defer { clearDropTarget() }
        let result = performDrop(sender.draggingLocation, sender.draggingPasteboard)
        macppWindowDragLog("top-perform result=\(result)")
        return result
    }

    override func draggingExited(_ sender: NSDraggingInfo?) {
        clearDropTarget()
    }
}

/// Keeps the top-bar page trees alive for the life of the surface. This used
/// to prune down to only the focused page after each slide, but that also
/// destroyed artwork loaders while the strip was still settling: Dashboard's
/// cover would disappear at the focus change and reload only after the next
/// page had finished moving. These are four compact SwiftUI pages, not bitmap
/// surfaces, so keeping their state warm is the more reliable optimization.
private let topBarTabAnimationDuration: TimeInterval = CaelestiaParityTokens.Motion.defaultSpatial

@MainActor private final class TopBarPageCache: ObservableObject {
    @Published private(set) var retainedPages: Set<Int> = []
    private let allPages = Set(0..<4)

    func start(activePage _: Int) {
        guard retainedPages.isEmpty else { return }
        retainedPages = allPages
    }

    func transition(from _: Int, to _: Int) {
        // The page strip owns all visual movement. Do not mount/unmount a
        // destination or its artwork loader as focus changes, including when
        // a fast hover traverses several tabs in one animation window.
        retainedPages = allPages
    }

    func stop() {
        retainedPages.removeAll()
    }
}

/// Draws a bottom-anchored resource fill without changing its layout bounds.
/// The top edge is animatable, but the view itself always occupies the full
/// track, so a telemetry update cannot create a second position animation
/// while the containing top-bar strip is already translating.
private struct VerticalResourceFill: Shape {
    var fraction: CGFloat

    var animatableData: CGFloat {
        get { fraction }
        set { fraction = newValue }
    }

    func path(in rect: CGRect) -> Path {
        let boundedFraction = min(1, max(0, fraction))
        let minimumHeight = min(4, rect.height)
        let height = min(rect.height, max(minimumHeight, rect.height * boundedFraction))
        let fillRect = CGRect(
            x: rect.minX,
            y: rect.maxY - height,
            width: rect.width,
            height: height
        )
        return Path(
            roundedRect: fillRect,
            cornerRadius: min(fillRect.width, fillRect.height) / 2
        )
    }
}

private struct NotchPopout: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var motion: SurfaceMotionState
    @StateObject private var topPageCache = TopBarPageCache()
    @State private var animatedTopTab: CGFloat = 1
    @State private var interactiveTopTab = 1
    @State private var topHitTestGeneration: UInt = 0
    @Namespace private var tabIndicator
    @Namespace private var workspaceHighlight
    let close: () -> Void
    let toggleMask: () -> Void
    /// Rim depth of the display this popout is presented on. Its content has
    /// to start below that display's own rim -- using the primary's pushed
    /// external-display content down by the notch reservation.
    var topDepth: CGFloat = shellTopDepth()
    // Caelestia's own fourth tab is Weather, but weather lives inside the
    // Dashboard tab here (as its SmallWeather card does there too), and the
    // workspace previews are genuinely more useful as a full tab on this
    // setup -- so the fourth slot stays Workspaces.
    private let tabs = [
        ("Dashboard", "square.grid.2x2"), ("Media", "music.note"),
        ("Performance", "gauge.with.dots.needle.50percent"), ("Workspaces", "circle.grid.2x2")
    ]
    var body: some View {
        VStack(spacing: Spacing.none) {
            VStack(spacing: Spacing.base) {
                HStack(spacing: Spacing.none) {
                    ForEach(Array(tabs.enumerated()), id: \.offset) { index, tab in
                        Button {
                            switchTab(index)
                        } label: {
                            VStack(spacing: Spacing.tight) {
                                Image(systemName: tab.1).font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded))
                                Text(tab.0.uppercased()).font(.system(size: ShellTypography.navigation, weight: .bold, design: .rounded))
                                ZStack {
                                    if model.topTab == index {
                                        Capsule().fill(Theme.accent)
                                            .matchedGeometryEffect(id: "top-tab-indicator", in: tabIndicator)
                                    }
                                }.frame(width: 52, height: 2)
                            }
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                            .contentShape(Rectangle())
                        }.buttonStyle(MicroButtonStyle()).foregroundStyle(model.topTab == index ? Theme.bright : Theme.muted)
                            .animation(ShellMotion.panelSwitch.animation, value: model.topTab)
                            .onHover { inside in if inside { switchTab(index) } }
                    }
                }.frame(height: 52).motionChild(motion, index: 1, followsSurface: true)
                GeometryReader { geometry in
                    HStack(spacing: Spacing.none) {
                        // The four pages share one sliding strip.  Clipping the
                        // strip hides the three off-screen pages visually, but
                        // SwiftUI can still leave their gesture/drop regions in
                        // the hit-test tree.  That made a window dragged across
                        // the notch turn into the rejected (grey) cursor even
                        // though the same card works in the side rail.  Only
                        // the page currently under the notch may participate in
                        // hit testing; the visible page then uses the same
                        // `acceptWindowDrop` destination as the rail.
                        Group {
                            if topPageCache.retainedPages.contains(0) || model.topTab == 0 {
                                dashboard
                            } else {
                                Color.clear
                            }
                        }
                            .frame(width: geometry.size.width, height: geometry.size.height)
                            .allowsHitTesting(interactiveTopTab == 0)
                        Group {
                            if topPageCache.retainedPages.contains(1) || model.topTab == 1 {
                                media
                            } else {
                                Color.clear
                            }
                        }
                            .frame(width: geometry.size.width, height: geometry.size.height)
                            .allowsHitTesting(interactiveTopTab == 1)
                        Group {
                            if topPageCache.retainedPages.contains(2) || model.topTab == 2 {
                                performance
                            } else {
                                Color.clear
                            }
                        }
                            .frame(width: geometry.size.width, height: geometry.size.height)
                            .allowsHitTesting(interactiveTopTab == 2)
                        Group {
                            if topPageCache.retainedPages.contains(3) || model.topTab == 3 {
                                workspaces
                            } else {
                                Color.clear
                            }
                        }
                            .frame(width: geometry.size.width, height: geometry.size.height)
                            .allowsHitTesting(interactiveTopTab == 3)
                            .zIndex(model.topTab == 3 ? 1 : 0)
                    }
                    .frame(width: geometry.size.width * 4, alignment: .leading)
                        // The model owns which page is active for live-data
                        // gating; this local fractional position owns the
                        // actual slide. Hit testing stays on the last committed
                        // page until the 320 ms hand-off completes, so the
                        // visible and interactive surfaces cannot disagree.
                    .offset(x: -animatedTopTab * geometry.size.width)
                }
                .frame(height: topContentHeight)
                .clipped()
                .motionChild(motion, index: 2, followsSurface: true)
            }.padding(.horizontal, Spacing.section).padding(.top, topDepth + Spacing.hairline)
            Spacer(minLength: 5)
        }
        .frame(width: 700, height: topSurfaceHeight(for: topDepth))
        .attachedTop(CaelestiaParityTokens.Border.rounding, motion: motion)
        // The top surface can survive a Space/display reattachment while its
        // content gate is still false. In that state the opaque morph is
        // present but every child is at zero opacity, so the bar looks blank
        // until another interaction happens. Repair only the gate after the
        // surface is presented; the existing motion curve and layout remain
        // unchanged.
        .onAppear {
            topPageCache.start(activePage: model.topTab)
            animatedTopTab = CGFloat(model.topTab)
            interactiveTopTab = model.topTab
            if motion.presented { motion.ensureContentReady() }
        }
        .onChange(of: model.topTab) { oldPage, newPage in
            topPageCache.transition(from: oldPage, to: newPage)
            animateTopTab(to: newPage)
            topHitTestGeneration &+= 1
            let generation = topHitTestGeneration
            DispatchQueue.main.asyncAfter(deadline: .now() + topBarTabAnimationDuration) {
                guard generation == topHitTestGeneration else { return }
                interactiveTopTab = newPage
            }
        }
        .onDisappear {
            topHitTestGeneration &+= 1
            topPageCache.stop()
        }
        .onChange(of: motion.presented) { _, presented in
            guard presented else { return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.035) {
                motion.ensureContentReady()
            }
        }
    }
    private func switchTab(_ index: Int) {
        model.selectTopTab(index)
    }

    private func animateTopTab(to page: Int) {
        withAnimation(ShellMotion.panelSwitch.animation) {
            animatedTopTab = CGFloat(page)
        }
    }
    // The dashboard is three deliberate columns rather than a large media
    // card with unrelated cards squeezed around it: weather and time first,
    // identity in the middle, and a narrow system-reading column beside
    // compact media on the right. 150 + 200 + 278 + two 8pt gaps = 644, the
    // exact content width of the 700pt surface after its 28pt side padding.
    private var dashboard: some View {
        HStack(spacing: Spacing.base) {
            VStack(spacing: Spacing.base) {
                weatherCard
                dateCard
            }
            .frame(width: 150)
            .motionChild(motion, index: 3)

            VStack(spacing: Spacing.base) {
                systemCard
                    .frame(height: 92)
                dashboardSessionCard
                    .frame(height: 84)
            }
            .frame(width: 200)
            .motionChild(motion, index: 4)

            VStack(spacing: Spacing.base) {
                HStack(spacing: Spacing.base) {
                    resourceCard
                        .frame(width: 84)
                    mediaCard
                        .frame(width: 186)
                }
            }
                .frame(width: 278)
                .motionChild(motion, index: 5)
        }
        // Match the Media page's page-level composition boundary. The strip
        // should translate one already-composited Dashboard layer; otherwise
        // the artwork overlay can be repainted independently of its card and
        // look as if it vanished when the focused tab changes.
        .compositingGroup()
        // Give Dashboard the same authored content plane as the other top
        // pages. Its child widths already add up to 644pt; making that plane
        // explicit keeps the retained layer centered while the tab strip is
        // being reattached instead of letting a transient proposal bias one
        // side of the surface.
        .frame(width: 644, alignment: .center)
        .frame(maxHeight: .infinity, alignment: .center)
    }

    // Keep the identity block compact and horizontal. The top surface can be
    // temporarily measured at less than its authored height while AppKit
    // reattaches a display; a tall avatar-above-name stack then leaves only
    // the OS/battery row visible. Putting the uptime beside the portrait makes
    // it part of the first block the user sees and keeps the whole card inside
    // that short-lived measurement too.
    private var systemCard: some View {
        VStack(alignment: .leading, spacing: Spacing.tight) {
            HStack(spacing: Spacing.base) {
                Group {
                    if let avatar = model.profilePhoto {
                        Image(nsImage: avatar).resizable().scaledToFill()
                    } else {
                        // Never an empty frame while no photo has been found.
                        ZStack {
                            Theme.layerTile
                            Image(systemName: "person.fill")
                                .font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                                .foregroundStyle(Theme.accent)
                        }
                    }
                }
                .frame(width: 46, height: 46)
                .clipShape(Circle())
                .overlay(Circle().stroke(Theme.seam.opacity(0.35), lineWidth: 1))

                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text(NSFullUserName())
                        .font(.system(size: ShellTypography.title, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright).lineLimit(1).minimumScaleFactor(0.75)
                    // Keep this visible even if a delayed system sampler or a
                    // restored ObservableObject briefly supplies an empty value.
                    // The machine uptime is cheap and deterministic at render
                    // time, so the dashboard never loses this line after reload.
                    Text("UPTIME \(model.uptime.isEmpty ? macppSystemUptimeText() : model.uptime)")
                        .font(.system(size: ShellTypography.body, weight: .medium, design: .rounded))
                        .foregroundStyle(Theme.muted).lineLimit(1).minimumScaleFactor(0.75)
                        .frame(minHeight: 13, alignment: .leading)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }

            CaelestiaDivider(opacity: 0.22)
            // Keep the OS and battery readings side by side. The battery drops
            // its "Battery" prefix -- the icon already says what it is, and
            // both entries have to share the card's usable width.
            HStack(spacing: Spacing.base) {
                systemRow("desktopcomputer", model.osVersion)
                Spacer(minLength: 4)
                systemRow(model.batterySymbol, model.charging ? "Charging" : "\(model.batteryPercent)%")
            }
            Spacer(minLength: 0)
        }
        .frame(maxWidth: .infinity)
        .padding(Spacing.base)
        .frame(maxHeight: .infinity)
        .layeredPanel(radius: Rounding.large)
    }

    /// The profile tile used to stretch to the full dashboard height, leaving
    /// its lower half empty. Keep that tile compact and use the reclaimed
    /// space for the live window context instead of changing the carefully
    /// balanced Performance and Spotify cards beside it.
    private var dashboardSessionCard: some View {
        VStack(alignment: .leading, spacing: Spacing.tight) {
            HStack(spacing: Spacing.tight) {
                Text("ACTIVE WINDOW")
                    .font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .foregroundStyle(Theme.muted)
                Spacer(minLength: 0)
                Circle()
                    .fill(Theme.mint)
                    .frame(width: 5, height: 5)
            }
            HStack(spacing: Spacing.base) {
                Image(nsImage: model.frontAppIcon)
                    .resizable()
                    .interpolation(.high)
                    .frame(width: 32, height: 32)
                    .clipShape(RoundedRectangle(cornerRadius: Rounding.tight, style: .continuous))
                VStack(alignment: .leading, spacing: Spacing.hairline) {
                    Text(model.frontApp)
                        .font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                    Text("SPACE \(model.currentWorkspace)  ·  \(model.focusEnabled ? "FOCUS" : "READY")")
                        .font(.system(size: ShellTypography.nano, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                        .foregroundStyle(Theme.muted)
                        .lineLimit(1)
                        .minimumScaleFactor(0.7)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
            .frame(maxWidth: .infinity, alignment: .leading)

            HStack(spacing: Spacing.snug) {
                dashboardSessionMetric(
                    "CPU",
                    String(format: "%.1f%%", model.frontAppCPUPercent))
                Spacer(minLength: 0)
                dashboardSessionMetric("RAM", dashboardFrontAppMemoryText)
            }
            .frame(maxWidth: .infinity)
            // Keep the small readouts clear of the card's curved sidewalls;
            // the title and app row already have enough breathing room from
            // the shared card padding, but these edge-aligned metrics read
            // better with a slightly narrower optical span.
            .padding(.horizontal, Spacing.tight)
        }
        .padding(Spacing.base)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .layeredPanel(radius: Rounding.large)
        // The page strip keeps Dashboard mounted while it moves, so the
        // controller's tab transition is not a sufficient lifecycle signal
        // for the live active-window sampler. Start it from the card that
        // actually displays the values as well.
        .onAppear { model.setFrontAppResourceSampling(true) }
    }

    private func dashboardSessionMetric(_ label: String, _ value: String) -> some View {
        HStack(spacing: Spacing.hairline) {
            Text(label)
                .font(.system(size: ShellTypography.nano, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                .foregroundStyle(Theme.muted)
            Text(value)
                .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                .monospacedDigit()
                .foregroundStyle(Theme.bright)
                .lineLimit(1)
                .minimumScaleFactor(0.7)
        }
    }

    private var dashboardFrontAppMemoryText: String {
        let formatter = ByteCountFormatter()
        formatter.allowedUnits = [.useMB, .useGB]
        formatter.countStyle = .memory
        formatter.includesActualByteCount = false
        return formatter.string(fromByteCount: Int64(
            min(UInt64(Int64.max), model.frontAppMemoryBytes)))
    }

    private func systemRow(_ symbol: String, _ value: String) -> some View {
        HStack(spacing: Spacing.snug) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
            Text(value)
                .font(.system(size: ShellTypography.cardTitle, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.muted).lineLimit(1).minimumScaleFactor(0.75)
        }
    }

    private var dateCard: some View {
        // Was 40pt, which dwarfed everything around it. At 29 the clock still
        // reads as the card's headline without making the card mostly clock.
        TopBarClockFace(
            date: model.now,
            palette: model.selectedPalette,
            paletteRevision: model.companionRevision
        )
        .equatable()
        // Do not disable this subtree's transaction. Doing so made the clock
        // paint at full opacity while its dashboard siblings were still
        // following MotionChild's content reveal. Minute commits are already
        // made atomically by ShellModel.scheduleTimer; keeping that policy at
        // the value source preserves static digit changes without cancelling
        // the top surface's entrance animation here.
        .frame(maxWidth: .infinity)
        // Keep the 29pt clock exactly as legible as before. Its ~51pt two-line
        // envelope fits a 60pt card with a 4pt vertical gutter.
        .padding(.horizontal, Spacing.snug)
        .padding(.vertical, Spacing.tight)
        .frame(height: 60)
        .layeredPanel(radius: Rounding.large)
    }

    private var weatherCard: some View {
        VStack(alignment: .leading, spacing: Spacing.tight) {
            HStack(alignment: .firstTextBaseline, spacing: Spacing.snug) {
                Text(model.weather.loaded ? "\(Int(model.weather.temperature.rounded()))°" : "—")
                    .font(.system(size: ShellDisplay.xlarge, weight: .medium, design: .rounded))
                    .monospacedDigit()
                    .foregroundStyle(Theme.bright).contentTransition(.numericText())
                Spacer(minLength: 0)
                Image(systemName: model.weather.symbol)
                    .font(.system(size: ShellIcon.header, weight: .medium, design: .rounded)).foregroundStyle(Theme.accent)
                    .contentTransition(.symbolEffect(.replace))
            }
            Text(model.weather.loaded ? model.weather.summary.capitalized : "Loading")
                .font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.bright).lineLimit(1).minimumScaleFactor(0.7)
            if model.weather.loaded {
                Text("H \(Int(model.weather.high.rounded()))°  L \(Int(model.weather.low.rounded()))°")
                    .font(.system(size: ShellTypography.cardTitle, weight: .medium, design: .rounded))
                    .monospacedDigit()
                    .foregroundStyle(Theme.muted).lineLimit(1)
            }
            Spacer(minLength: 0)
        }
        .padding(Spacing.roomy).frame(maxWidth: .infinity, alignment: .topLeading)
        .frame(maxHeight: .infinity)
        .layeredPanel(radius: Rounding.large)
        .animation(ShellMotion.contentIn.animation, value: model.weather)
    }

    // A deliberately narrow vertical companion to the full Performance tab:
    // each resource gets its own upright bar and label, kept beside the
    // reduced-width media card rather than stacked above it.
    private var resourceCard: some View {
        VStack(spacing: Spacing.snug) {
            Text("SYSTEM")
                .font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                .foregroundStyle(Theme.muted)
            HStack(alignment: .bottom, spacing: Spacing.snug) {
                verticalResourceBar("CPU", model.performance.cpuUse, color: Theme.ice)
                verticalResourceBar("RAM", model.performance.ramUse, color: Theme.ice)
                verticalResourceBar("SSD", model.performance.diskUse, color: Theme.mint)
            }
            .frame(height: 144)
        }
        .padding(Spacing.base)
        .frame(maxWidth: .infinity)
        .frame(maxHeight: .infinity)
        .layeredPanel(radius: Rounding.large)
        // Theme.* is intentionally a lightweight read of the selected
        // palette rather than another published object.  Key the complete
        // card to the model's palette revision so a palette change rebuilds
        // CPU, RAM, and SSD together; otherwise a disk sample arriving on a
        // different tick could leave only the SSD fill carrying the new
        // accent while the other two bars retained the previous one.
        .id("resource-card-\(model.companionRevision)")
    }

    private func verticalResourceBar(_ title: String, _ rawValue: Double, color: Color) -> some View {
        let value = min(1, max(0, rawValue))
        return VStack(spacing: Spacing.hairline) {
            Text("\(Int((value * 100).rounded()))%")
                .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                .monospacedDigit()
                .foregroundStyle(Theme.muted)
                // The bar below is deliberately only 14pt wide, but the
                // percentage belongs above the bar as a complete readout.
                // Without an intrinsic-width constraint SwiftUI ellipsized
                // values such as 55% into a wider-looking `55…` label.
                .lineLimit(1)
                .fixedSize(horizontal: true, vertical: false)
                .frame(height: 10)
            GeometryReader { _ in
                ZStack(alignment: .bottom) {
                    Capsule().fill(Theme.sliderTrack)
                    VerticalResourceFill(fraction: value)
                        .fill(color)
                        // Limit the telemetry transaction to the changing
                        // fixed-bounds fill path. Applying it to the whole bar
                        // also animated the bar's page-relative position when
                        // the first sample landed during a Dashboard tab slide,
                        // making the fill appear parked while the card moved.
                        .animation(ShellMotion.valueChange.animation, value: value)
                }
            }
            .frame(width: 14)
            Text(title)
                .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                .foregroundStyle(Theme.muted)
                .frame(height: 10)
        }
        .frame(maxHeight: .infinity)
    }

    // The dashboard media card is intentionally secondary to the information
    // columns, but it keeps the old media reading order: artwork first, then
    // title/artist, progress, and transport. That gives the artwork a proper
    // visual lead even after the card was narrowed beside the system bars.
    private var mediaCard: some View {
        VStack(spacing: Spacing.tight) {
            // Make the cover the tile's primary content and rasterize only this
            // small SwiftUI subtree. The Media disc gets a persistent render
            // layer from its rotation; the square needs an explicit drawing
            // layer to keep its decoded NSImage attached while the page moves.
            // Keeping this boundary below the AppKit-backed marquee avoids
            // flattening or resampling the rest of the card.
            SharedAlbumArtwork(
                url: URL(string: model.media.artworkURL),
                revision: model.media.artworkRevision,
                fallback: AnyView(mediaArtFallback),
                loader: model.topBarArtworkLoader
            )
                .frame(width: 82, height: 82)
                .background(Theme.surface)
                .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous).stroke(Theme.seam.opacity(0.28), lineWidth: 0.7))
                .drawingGroup(opaque: false, colorMode: .nonLinear)

            VStack(spacing: Spacing.none) {
                SeamlessMarquee(
                    text: model.media.title.isEmpty ? "No media" : loopingMediaText(model.media.title, viewport: 170),
                    fontSize: 11.5,
                    speed: 18,
                    active: model.topSurfaceVisible && model.topTab == 0
                        && !model.media.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                    wrapGap: false
                )
                .frame(maxWidth: .infinity, alignment: .leading)
                .frame(height: 14)
                Text(model.media.artist.isEmpty ? "—" : model.media.artist)
                    .font(.system(size: ShellTypography.label, weight: .medium, design: .rounded))
                    .foregroundStyle(Theme.muted).lineLimit(1).minimumScaleFactor(0.7)
            }
            .frame(maxWidth: .infinity, alignment: .center)

            if model.media.durationKnown || model.media.isLive {
                VStack(spacing: Spacing.hairline) {
                    GeometryReader { geo in
                        ZStack(alignment: .leading) {
                            Capsule().fill(Theme.sliderTrack)
                            if model.media.durationKnown {
                                Capsule().fill(Theme.accent)
                                    .frame(width: max(2, geo.size.width * min(1, max(0, model.media.progress))))
                            } else {
                                Capsule().fill(Theme.accent)
                                    .frame(width: 24)
                            }
                        }
                    }
                    .frame(height: 3)
                    HStack {
                        Text(mediaTime(model.media.position))
                        Spacer(minLength: 0)
                        Text(model.media.isLive ? "LIVE" : mediaTime(model.media.duration))
                    }
                    .font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .monospacedDigit()
                    .foregroundStyle(Theme.muted)
                }
                .animation(ShellMotion.valueChange.animation, value: model.media.progress)
            }

            HStack(spacing: Spacing.roomy) {
                // Browser media has no track list, so the side buttons seek --
                // and the glyphs say so rather than promising a skip the page
                // cannot perform.
                let seeks = model.mediaSeeksInsteadOfSkipping
                compactMediaButton(seeks ? "gobackward.15" : "backward.fill") {
                    model.mediaAction(seeks ? "backward" : "previous")
                }
                compactMediaButton(model.media.playing ? "pause.fill" : "play.fill", primary: true) { model.mediaAction("playpause") }
                compactMediaButton(seeks ? "goforward.15" : "forward.fill") {
                    model.mediaAction(seeks ? "forward" : "next")
                }
            }
        }
        .padding(.horizontal, Spacing.base).padding(.vertical, Spacing.base)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
        .layeredPanel(radius: Rounding.large)
    }

    private func compactMediaButton(_ symbol: String, primary: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: primary ? 12 : 11, weight: .semibold, design: .rounded))
                .frame(width: primary ? 25 : 22, height: 22)
                .background(primary ? Theme.bright : Theme.layerTile, in: Circle())
                .foregroundStyle(primary ? Theme.surface : Theme.bright)
        }
        .buttonStyle(MicroButtonStyle())
    }

    private var mediaArtFallback: some View {
        ZStack {
            Theme.surface
            Image(systemName: "music.note")
                .font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                .foregroundStyle(Theme.muted)
        }
    }

    private var workspaces: some View {
        GeometryReader { geometry in
            let workspaceCount = CaelestiaParityTokens.Sizes.workspaceCount
            let workspaceCardWidth = min(
                140,
                max(
                    112,
                    (geometry.size.width - Spacing.base * CGFloat(workspaceCount - 1))
                        / CGFloat(workspaceCount)
                )
            )
            HStack(spacing: Spacing.base) {
                ForEach(Array(model.workspaces.prefix(CaelestiaParityTokens.Sizes.workspaceCount).enumerated()), id: \.element.id) { index, space in
                // A Button around the whole card captures the drag gesture
                // before AppKit can see the drop target.  Keep the card as a
                // normal container: its tap still focuses the workspace, but
                // the same surface can now receive a window drop reliably.
                ZStack {
                    if model.workspaceDropTarget == space.id {
                        RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                            .fill(Theme.accent.opacity(0.18))
                            .overlay {
                                RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                                    .stroke(Theme.accent.opacity(0.92), lineWidth: 1.5)
                            }
                            .allowsHitTesting(false)
                    }
                    VStack(alignment: .leading, spacing: Spacing.base) {
                        HStack {
                            Text("\(space.id)").font(.system(size: ShellDisplay.large, weight: .medium, design: .rounded))
                            Spacer()
                            if space.apps.contains(where: { model.isDownloadingApp($0) }) {
                                Image(systemName: "arrow.down.circle")
                                    .symbolEffect(
                                        .pulse,
                                        isActive: model.topSurfaceVisible && model.topTab == 3
                                    )
                                    .foregroundStyle(Theme.accent)
                                    .compositingGroup()
                            }
                            if space.apps.contains(where: { model.isNowPlayingApp($0) }) {
                                Image(systemName: "waveform")
                                    .symbolEffect(
                                        .variableColor.iterative,
                                        isActive: model.topSurfaceVisible && model.topTab == 3
                                    )
                                    // Keep the animated SF Symbol in the
                                    // workspace card's render layer. A
                                    // separately inserted symbol-effect
                                    // layer could snap to its destination
                                    // before the page strip arrived.
                                    .compositingGroup()
                            }
                        }
                        Text(space.name).font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded))
                        CaelestiaDivider(opacity: 0.22)
                        if !space.available {
                            Spacer(minLength: 0)
                        } else if space.windows.isEmpty {
                            Spacer(minLength: 0)
                        } else {
                            // Keep the card itself fixed while allowing a
                            // busy workspace to expose every window.  The
                            // native indicator is intentionally disabled: the
                            // trackpad/mouse wheel remains the affordance and
                            // the card keeps its clean shell silhouette.
                            ScrollView(.vertical, showsIndicators: false) {
                                LazyVStack(alignment: .leading, spacing: Spacing.base) {
                                    ForEach(space.windows) { window in
                                        HStack(spacing: Spacing.snug) {
                                            Circle().fill(Theme.accent.opacity(0.7)).frame(width: 4, height: 4)
                                            VStack(alignment: .leading, spacing: Spacing.none) {
                                                Text(window.displayName).lineLimit(1)
                                                if !window.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                                                    Text(window.app.uppercased()).font(.system(size: ShellTypography.nano, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.nano))).foregroundStyle(Theme.muted).lineLimit(1)
                                                }
                                            }
                                        }
                                        .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded))
                                        .frame(maxWidth: .infinity, alignment: .leading)
                                        // This title sits optically high against
                                        // the neighbouring two-line rows; keep
                                        // the nudge limited to the active window.
                                        .offset(y: window.displayName.localizedCaseInsensitiveCompare("the active window") == .orderedSame ? 2 : 0)
                                        .onDrag {
                                            model.beginWindowDrag(window.id)
                                            return NSItemProvider(object: NSString(string: "macpp-window:\(window.id)"))
                                        }
                                        .help("Drag \(window.displayName) to another workspace")
                                    }
                                }
                                .frame(maxWidth: .infinity, alignment: .topLeading)
                                .padding(.trailing, Spacing.none)
                            }
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                            .layoutPriority(1)
                        }
                    }
                    .foregroundStyle(space.available && model.currentWorkspace == space.id ? Theme.bright : Theme.muted)
                        .padding(Spacing.loose)
                }
                .frame(width: workspaceCardWidth, height: 176)
                // The active tint belongs to the card's fixed outer geometry,
                // not to the variable-height window-list stack above. Keeping
                // it as a background after the card has been sized prevents
                // the matched shape from inheriting a stale list height while
                // a workspace changes apps or the tab page is being retained.
                .background {
                    if space.available && model.currentWorkspace == space.id {
                        RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                            .fill(Theme.accent.opacity(0.13))
                            .matchedGeometryEffect(id: "workspace-card", in: workspaceHighlight)
                            .allowsHitTesting(false)
                    }
                }
                .contentShape(RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous))
                .layeredPanel(radius: 20)
                // Put the final hit shape after the visual panel modifier as
                // well.  This mirrors the sidebar's full rectangular Button
                // target: the panel background is decorative and must not
                // shrink the drop region to only its text-bearing children.
                .contentShape(Rectangle())
                .onTapGesture {
                    guard space.available else { return }
                    model.focusSpace(space.id)
                }
                .help(space.available
                    ? "Drop a window here to move it to \(space.name)"
                    : "\(space.name) is not available")
                .motionChild(motion, index: index + 3)
            }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .contentShape(Rectangle())
            .animation(ShellMotion.workspaceIndicator.animation, value: model.currentWorkspace)
            .animation(.linear(duration: 0.06), value: model.workspaceDropTarget)
        }
    }
    private var media: some View {
        HStack(spacing: Spacing.roomy) {
            ReactiveAlbumDisc(
                media: model.media,
                levels: model.levels,
                active: model.media.playing && model.topSurfaceVisible && model.topTab == 1,
                artworkLoader: model.topBarArtworkLoader
            )
                .frame(width: 170, height: 170)
                .layeredPanel(radius: 85)
                .motionChild(motion, index: 3)
            ZStack {
                if model.media.title.isEmpty {
                    VStack(spacing: Spacing.tight) {
                        Image(systemName: "music.note").font(.system(size: ShellIcon.hero)).foregroundStyle(Theme.muted)
                    }
                    .transition(.opacity)
                } else {
                    VStack(spacing: Spacing.tight) {
                        SeamlessMarquee(
                        text: loopingMediaText(mediaMarqueeTitle, viewport: 280),
                        fontSize: 12.5,
                        speed: 20,
                        active: model.topSurfaceVisible && model.topTab == 1,
                        wrapGap: false
                        )
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .frame(height: 22)
                        .padding(.horizontal, Spacing.base)
                        .background(Theme.isLight ? Color.clear : Theme.tile.opacity(0.40), in: Capsule())
                        .overlay(Capsule().stroke(Theme.seam.opacity(0.20), lineWidth: 0.55))
                    Text(model.media.artist)
                        .font(.system(size: ShellTypography.label, weight: .semibold, design: .rounded)).foregroundStyle(Theme.muted).lineLimit(1)
                    // Keep the three transport controls on the card's true
                    // centre line. Cinema is a presentation utility, not a
                    // transport step; placing it in the same HStack pulled
                    // the whole playback cluster left whenever that optional
                    // button was available. The trailing utility keeps its
                    // own small inset while the playback trio stays centred
                    // in both the Dashboard and Media top-bar states.
                    ZStack {
                        HStack(spacing: Spacing.loose) {
                            // Same source-dependent transport as the Dashboard
                            // card. The top bar has two independent media
                            // surfaces -- the compact card on the Dashboard
                            // and this full Media tab -- each with its own
                            // button row, so a change to one is invisible in
                            // the other.
                            let seeks = model.mediaSeeksInsteadOfSkipping
                            mediaButton(seeks ? "gobackward.15" : "backward.fill") {
                                model.mediaAction(seeks ? "backward" : "previous")
                            }
                            mediaButton(model.media.playing ? "pause.fill" : "play.fill", primary: true) { model.mediaAction("playpause") }
                            mediaButton(seeks ? "goforward.15" : "forward.fill") {
                                model.mediaAction(seeks ? "forward" : "next")
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .center)
                        if model.cinemaControlAvailable {
                            HStack {
                                Spacer(minLength: 0)
                                mediaButton(
                                    "rectangle.inset.filled",
                                    active: model.cinemaPresentation != nil,
                                    busy: model.cinemaMutationInFlight
                                ) {
                                    if NSEvent.modifierFlags.contains(.option) { model.cycleCinemaMode() }
                                    else { model.toggleCinemaMode() }
                                }
                                .disabled(model.cinemaMutationInFlight)
                                .help(model.cinemaControlHelp)
                                .accessibilityLabel(model.cinemaMutationInFlight ? model.cinemaOperationLabel : "Cinema mode")
                                .accessibilityValue(model.cinemaPresentation?.title ?? "Off")
                            }
                            .padding(.trailing, Spacing.roomy)
                        }
                    }
                    .frame(maxWidth: .infinity)
                    if model.media.durationKnown || model.media.isLive {
                        HStack(spacing: Spacing.snug) {
                            Text(mediaTime(model.media.position))
                            GeometryReader { geo in
                                ZStack(alignment: .leading) {
                                    Capsule().fill(Theme.muted.opacity(0.16))
                                    if model.media.durationKnown {
                                        Capsule().fill(LinearGradient(colors: [Theme.accent, Theme.ice], startPoint: .leading, endPoint: .trailing))
                                            .frame(width: geo.size.width * model.media.progress)
                                        Circle().fill(Theme.isLight ? Theme.accent : Theme.bright)
                                            .frame(width: 5, height: 5)
                                            .offset(x: max(0, geo.size.width * model.media.progress - 2.5))
                                    } else {
                                        Capsule().fill(Theme.accent)
                                            .frame(width: 24)
                                    }
                                }
                            }
                            .frame(height: 4)
                            Text(model.media.isLive ? "LIVE" : mediaTime(model.media.duration))
                        }.font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro))).foregroundStyle(Theme.muted)
                            .frame(height: 12)
                    }
                    HStack(spacing: Spacing.base) {
                        HStack(spacing: Spacing.snug) {
                            let volumeLabel = model.muted ? "MUTED" : "\(Int(model.volume * 100))%"
                            Label(volumeLabel, systemImage: model.volumeSymbol)
                                .font(.system(size: ShellTypography.label, weight: .bold, design: .rounded)).foregroundStyle(Theme.muted)
                            mediaTempoBadge
                        }
                        Spacer(minLength: 0)
                        mediaRouteStack
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .frame(height: 33)
                    .animation(ShellMotion.contentIn.animation, value: model.bpm > 0)
                    }
                    .transition(.opacity)
                }
            }
            .animation(ShellMotion.contentIn.animation, value: model.media.title.isEmpty)
            .padding(.horizontal, Spacing.roomy).padding(.vertical, Spacing.roomy)
            .frame(width: 304, height: 170)
            .layeredPanel(radius: 23)
            .motionChild(motion, index: 4)
            LyricsSlot(model: model)
            .frame(width: 136, height: 170)
            .motionChild(motion, index: 5)
        }
        // Keep media pixels inside the already formed top surface. This gate
        // follows the physical unfold rather than allowing cached artwork or
        // AppKit-backed marquee layers to lead it by a frame.
        .opacity(min(1, max(0, (motion.progress - 0.26) / 0.34)))
        .scaleEffect(0.985 + 0.015 * min(1, max(0, (motion.progress - 0.26) / 0.34)), anchor: .top)
        .compositingGroup()
        // Give the retained page an authored width as well as an authored
        // height. The old flexible proposal let the cached layers settle at
        // slightly different widths during a tab handoff, which made the
        // media page read as left-heavy and exposed one side of the next page.
        .frame(width: 644, alignment: .center)
        .frame(maxHeight: .infinity, alignment: .center)
    }
    private var performance: some View {
        HStack(spacing: Spacing.base) {
            DualPerformanceGauge(title: "CPU", symbol: "cpu", utilization: model.performance.cpuUse, temperature: model.performance.cpuTemp).motionChild(motion, index: 3)
            DualPerformanceGauge(title: "GPU", symbol: "square.stack.3d.up", utilization: model.performance.gpuUse, temperature: model.performance.gpuTemp).motionChild(motion, index: 4)
            DualPerformanceGauge(title: "RAM", symbol: "memorychip", utilization: model.performance.ramUse, temperature: nil).motionChild(motion, index: 5)
            DualPerformanceGauge(title: "DISK", symbol: "internaldrive", utilization: model.performance.diskUse, temperature: nil).motionChild(motion, index: 6)
        }.frame(maxWidth: .infinity, maxHeight: .infinity)
    }
    private func dashboardStat(_ title: String, _ value: String, _ icon: String, bluetoothIcon: Bool = false) -> some View {
        HStack(spacing: Spacing.base) {
            Group {
                if bluetoothIcon {
                    BluetoothMark(color: Theme.accent, size: 15)
                } else {
                    Image(systemName: icon).font(.system(size: ShellIcon.medium, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent)
                }
            }.frame(width: 18)
            VStack(alignment: .leading, spacing: Spacing.hairline) {
                Text(title).font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro))).foregroundStyle(Theme.muted)
                Text(value.isEmpty ? "—" : value).font(.system(size: ShellTypography.body, weight: .semibold, design: .rounded)).foregroundStyle(Theme.bright).lineLimit(1)
            }
            Spacer(minLength: 0)
        }.padding(.horizontal, Spacing.base).frame(height: 52)
            .layeredPanel(radius: 14)
    }
    private func controlButton(_ title: String, _ icon: String, active: Bool, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack { Image(systemName: icon); Text(title); Spacer(); Circle().fill(active ? Theme.mint : Theme.muted).frame(width: 6, height: 6) }
                .font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).padding(Spacing.roomy)
        }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright)
            .background(active ? Theme.tile.opacity(0.96) : Theme.tile.opacity(0.58), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .animation(ShellMotion.panelSwitch.animation, value: active)
    }
    private func actionButton(_ title: String, _ icon: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack { Image(systemName: icon); Text(title); Spacer(); Image(systemName: "chevron.right") }
                .font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).padding(Spacing.roomy)
        }.buttonStyle(MicroButtonStyle()).foregroundStyle(Theme.bright).background(Theme.tile.opacity(0.62), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
    }
    private func stat(_ title: String, _ value: String, _ icon: String) -> some View {
        HStack { Image(systemName: icon).foregroundStyle(Theme.accent).contentTransition(.symbolEffect(.replace)); VStack(alignment: .leading, spacing: Spacing.hairline) { Text(title).font(.system(size: ShellTypography.label, weight: .bold, design: .rounded)).foregroundStyle(Theme.muted); Text(value).font(.system(size: ShellTypography.cardTitle, weight: .bold, design: .rounded)).foregroundStyle(Theme.bright).lineLimit(1).contentTransition(.numericText()) }; Spacer() }
            .padding(Spacing.roomy).background(Theme.tile.opacity(0.64), in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            // valueChange, matching every other numeric readout. panelSwitch
            // is the overshooting surface-swap curve and made these figures
            // wobble past their value on each refresh.
            .animation(ShellMotion.valueChange.animation, value: value)
    }
    private func mediaButton(
        _ symbol: String,
        primary: Bool = false,
        active: Bool = false,
        busy: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            // `design: .rounded` selects SF Symbols' rounded optical variant,
            // which is what every other glyph and label in the shell already
            // uses (and what matches caelestia's Material Symbols Rounded).
            // Without it these transport controls were the only symbols drawn
            // from the default family, so they read as a different typeface
            // sitting inside an otherwise rounded surface. The weight moves
            // from semibold to bold for the same reason -- the shell's
            // typography is consistently heavier than this was.
            ZStack {
                if busy {
                    ProgressView()
                        .controlSize(.mini)
                        .tint(active ? Theme.accent : Theme.bright)
                        .transition(.opacity.combined(with: .scale(scale: 0.84)))
                } else {
                    Image(systemName: symbol)
                        .font(.system(
                            size: (primary ? 15 : 13) * mediaGlyphScale(symbol),
                            weight: .bold,
                            design: .rounded
                        ))
                        .contentTransition(.symbolEffect(.replace.downUp))
                        .transition(.opacity.combined(with: .scale(scale: 0.84)))
                }
            }
            .frame(width: primary ? 38 : 30, height: primary ? 38 : 30)
            .contentShape(Circle())
        }.buttonStyle(MediaCircleButtonStyle()).foregroundStyle(primary ? Theme.frame : (active ? Theme.accent : Theme.bright))
            .background(
                primary ? Theme.ice : (active ? Theme.accent.opacity(0.18) : (Theme.isLight ? Color.clear : Theme.tile.opacity(0.62))),
                in: Circle()
            )
            .overlay(Circle().stroke(
                primary && Theme.isLight ? Color.clear :
                    (primary ? Theme.bright.opacity(0.36) : (active ? Theme.accent.opacity(0.52) : Theme.seam.opacity(0.18))),
                lineWidth: 0.6
            ))
            .contentShape(Circle())
            .animation(ShellMotion.contentIn.animation, value: symbol)
            .animation(ShellMotion.valueChange.animation, value: active)
            .animation(ShellMotion.contentIn.animation, value: busy)
    }
    @ViewBuilder
    private var mediaTempoBadge: some View {
        if model.bpm > 0 {
            HStack(spacing: Spacing.tight) {
                Circle()
                    .fill(model.bpmLive ? Theme.mint : Theme.muted)
                    .frame(width: 4.5, height: 4.5)
                Text("\(model.bpm) BPM")
                    .font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .monospacedDigit()
                    .contentTransition(.numericText())
            }
            .foregroundStyle(model.bpmLive ? Theme.bright : Theme.muted)
            .padding(.horizontal, Spacing.snug)
            .frame(height: 22)
            .background(Theme.layerTile.opacity(model.bpmLive ? 1 : 0.55), in: Capsule())
            .overlay(Capsule().stroke(Theme.seam.opacity(0.22), lineWidth: 0.5))
            .animation(ShellMotion.valueChange.animation, value: model.bpm)
            .transition(.opacity.combined(with: .scale(scale: 0.92)))
        }
    }

    /// The media-source chip and its picker.
    ///
    /// This was a SwiftUI `Menu` with `.menuStyle(.borderlessButton)`. On macOS
    /// that style is rendered by an AppKit `NSPopUpButton` cell, which draws its
    /// own title using the *control's* font and discards the SwiftUI
    /// environment font entirely -- so the `design: .rounded` applied to the
    /// label below had no effect and this one chip rendered in system San
    /// Francisco while everything around it was rounded. No amount of
    /// additional font modifiers fixes that, because the label is not what is
    /// being drawn.
    ///
    /// A plain Button keeps the drawing in SwiftUI, so the chip uses the
    /// shell's own typography.
    ///
    /// It cycles rather than opening a menu or a popover. There are only three
    /// choices and the chip already displays the current one, and both of the
    /// alternatives are worse here: a `Menu` is drawn by AppKit (the original
    /// bug), and a `.popover` introduces an AppKit presentation inside a
    /// borderless screen-saver-level panel whose content is itself clipped --
    /// new machinery in a surface with unusual window semantics, for a
    /// three-item choice.
    private var mediaRouteStack: some View {
        Button {
            model.selectMediaSource(nextMediaSource)
        } label: {
            HStack(spacing: Spacing.snug) {
                Image(systemName: "play.square.stack")
                    .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                Text(mediaRouteTitle)
                    .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .lineLimit(1)
                    .minimumScaleFactor(0.76)
                    .frame(maxWidth: 92, alignment: .leading)
                Image(systemName: "arrow.triangle.2.circlepath")
                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                    .foregroundStyle(Theme.muted)
            }
            .foregroundStyle(Theme.bright)
            .padding(.horizontal, Spacing.base)
            .padding(.vertical, Spacing.tight)
            .background(Theme.isLight ? Theme.layerGroup : Theme.layerCard, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous).stroke(Theme.seam.opacity(0.28), lineWidth: 0.55))
            .clipShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
            .contentShape(RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        }
        .buttonStyle(MicroButtonStyle())
        .fixedSize(horizontal: true, vertical: false)
        .help("Click to change what the media card displays: \(mediaSourceSelectionTitle) → \(mediaSourceTitle(for: nextMediaSource))")
        .accessibilityLabel("Media source: \(mediaSourceSelectionTitle)")
        .accessibilityHint("Choose next source: \(mediaSourceTitle(for: nextMediaSource))")
    }

    private var mediaRouteTitle: String {
        let source = model.media.source.trimmingCharacters(in: .whitespacesAndNewlines)
        let device = model.media.device.trimmingCharacters(in: .whitespacesAndNewlines)
        let identity = "\(source) \(device)".lowercased()
        if identity.contains("spotify") { return "SPOTIFY" }
        if identity.contains("safari") { return "SAFARI" }
        if identity.contains("active-media") { return "LILITH" }
        if identity.contains("macpp") { return "MAC++" }
        if !source.isEmpty && source.lowercased() != "none" { return source.uppercased() }
        if !device.isEmpty && device.lowercased() != "none" { return compactAudioDeviceName(device).uppercased() }
        return mediaSourceSelectionTitle
    }

    /// The next entry in the automatic → spotify → active-app cycle.
    private var nextMediaSource: String {
        switch model.preferredMediaSource {
        case "automatic": return "spotify"
        case "spotify": return "system"
        default: return "automatic"
        }
    }

    private func mediaSourceTitle(for source: String) -> String {
        switch source {
        case "spotify": return "Spotify"
        case "system": return "ACTIVE APP"
        default: return "AUTOMATIC"
        }
    }

    private var mediaSourceSelectionTitle: String {
        switch model.preferredMediaSource {
        case "spotify": return "Spotify"
        case "system": return "ACTIVE APP"
        default: return "AUTOMATIC"
        }
    }

    private func mediaTime(_ seconds: Double) -> String {
        guard seconds.isFinite, seconds > 0, seconds <= 30 * 24 * 60 * 60 else { return "0:00" }
        let value = Int(seconds.rounded(.down))
        return "\(value / 60):\(String(format: "%02d", value % 60))"
    }
    private var mediaMarqueeTitle: String {
        model.media.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? ""
            : model.media.title
    }
    private var mediaTitleScrolls: Bool {
        // The full Media card is 304pt wide with 12pt horizontal padding on
        // each side, leaving a 280pt marquee viewport. Using the enclosing
        // surface width made medium-length titles switch to a ticker too late
        // and then clip at the card's trailing curve.
        mediaTitleNeedsScroll(model.media.title, viewport: 280)
    }
    private func percent(_ text: String) -> Double {
        (Double(text.filter { $0.isNumber || $0 == "." }) ?? 0) / 100
    }
    private func performanceGauge(_ title: String, _ rawValue: Double, _ icon: String) -> some View {
        let value = min(1, max(0, rawValue))
        return ZStack {
            Circle().trim(from: 0.08, to: 0.92).stroke(Theme.muted.opacity(0.15), style: StrokeStyle(lineWidth: 9, lineCap: .round))
            Circle().trim(from: 0.08, to: 0.08 + 0.84 * value)
                .stroke(AngularGradient(colors: [Theme.accent, Theme.mint], center: .center), style: StrokeStyle(lineWidth: 9, lineCap: .round))
                .rotationEffect(.degrees(-90))
                .animation(ShellMotion.panelSwitch.animation, value: value)
            VStack(spacing: Spacing.tight) {
                Image(systemName: icon).font(.system(size: ShellIcon.header, weight: .semibold, design: .rounded)).foregroundStyle(Theme.accent)
                Text("\(Int(value * 100))%").font(.system(size: ShellDisplay.huge, weight: .heavy, design: .rounded))
                    .monospacedDigit().foregroundStyle(Theme.bright)
                    .contentTransition(.numericText())
                    // The arc above animates on panelSwitch, which is a
                    // deliberate spring and reads well on a gauge. The number
                    // had no animation at all, so it snapped to its new value
                    // while the arc was still travelling. It now uses the
                    // numeric token, so both move together.
                    .animation(ShellMotion.valueChange.animation, value: value)
                Text(title).font(.system(size: ShellTypography.body, weight: .bold, design: .rounded)).foregroundStyle(Theme.muted)
            }
        }.frame(width: 146, height: 146)
    }
}

private struct EdgeSliders: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var motion: SurfaceMotionState
    var body: some View {
        VStack(spacing: Spacing.base) {
            VerticalLevelControl(symbol: model.volumeSymbol, value: $model.volume) {
                model.setVolume(model.volume)
            }.motionChild(motion, index: 1, offset: CGSize(width: 8, height: 0))
            CaelestiaDivider(opacity: 0.22).frame(width: 28)
                .motionChild(motion, index: 2, offset: CGSize(width: 8, height: 0))
            VerticalLevelControl(symbol: "sun.max.fill", value: $model.brightness) {
                model.setBrightness(model.brightness)
            }.motionChild(motion, index: 3, offset: CGSize(width: 8, height: 0))
        }
            .offset(x: edgeControlsOutsideShift)
            .padding(.trailing, shellFrame)
            .padding(.leading, Spacing.base)
            // Lay the stack out inside the masked body first, then centre that
            // body in the full panel. The previous vertical padding was added
            // before this fixed body frame, so SwiftUI had to compress the
            // stack and clipped the first/last slider caps. The outer frame now
            // supplies one exact geometric shoulder at both ends.
            .frame(width: edgeControlsWidth, height: edgeControlsBodyHeight, alignment: .center)
            .frame(width: edgeControlsWidth, height: edgeControlsHeight, alignment: .center)
            .attachedRight(18, motion: motion)
            // Same belt-and-suspenders fix as the rail pills: force a full
            // rebuild on palette change instead of trusting that VerticalLevel
            // Control's body re-runs just because its ancestor's did. This is
            // the persistent right-edge window, alive for the whole session,
            // so it's the most likely place for a captured-at-creation color
            // to go stale across a palette switch.
            .id(model.selectedPalette.rawValue)
    }
}

// Was a single volume slider (RailPopoverKind.controls). Scroll already
// covers volume/brightness on the bare rail, so a lone slider here had
// little reason to exist beyond that. The audio popout now reuses the live
// CoreAudio lists from Nexus and gives every output/input its own button.
// When a machine has more routes than fit in the authored viewport, this
// surface scrolls rather than hiding them behind a cycle-only control.
private struct RailAudioControls: View {
    @ObservedObject var model: ShellModel
    @ObservedObject var nexus: MacPlusPlusNexusModel
    var body: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: PopoverCard.stackSpacing) {
                HStack(spacing: 8) {
                    Image(systemName: model.volumeSymbol)
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.accent)
                    Text("AUDIO ROUTING").popoverCardTitle()
                    Spacer()
                }
                .padding(.horizontal, PopoverCard.horizontalPadding)
                .frame(height: PopoverCard.rowHeight)
                .nexusLayer(cornerRadius: Rounding.normal, depth: .card)

                Text("OUTPUTS")
                    .popoverRowCaption()
                    .frame(height: 16, alignment: .leading)
                if nexus.outputDevices.isEmpty {
                    audioRouteEmpty("NO OUTPUT ROUTES", symbol: "speaker.slash")
                } else {
                    VStack(spacing: audioPopoverRowSpacing) {
                        ForEach(nexus.outputDevices, id: \.identity) { device in
                            outputRouteRow(device)
                        }
                    }
                }

                CaelestiaDivider()
                    .padding(.vertical, Spacing.hairline)

                Text("INPUTS")
                    .popoverRowCaption()
                    .frame(height: 16, alignment: .leading)
                if nexus.inputDevices.isEmpty {
                    audioRouteEmpty("NO INPUT ROUTES", symbol: "mic.slash")
                } else {
                    VStack(spacing: audioPopoverRowSpacing) {
                        ForEach(nexus.inputDevices) { device in
                            inputRouteRow(device)
                        }
                    }
                }

                HStack(spacing: 7) {
                    compactStateButton(
                        title: "FOCUS",
                        symbol: model.focusEnabled ? "moon.fill" : "moon",
                        active: model.focusEnabled,
                        enabled: !model.focusMutationInFlight,
                        action: model.toggleFocus
                    )
                    compactStateButton(
                        title: model.microphoneMuted ? "MIC MUTED" : "MIC LIVE",
                        symbol: model.microphoneMuted ? "mic.slash.fill" : "mic.fill",
                        active: model.microphoneMuted,
                        enabled: model.microphoneMuteAvailable,
                        action: model.toggleMicrophoneMute
                    )
                }
            }
        }
        // The parent supplies the finite content viewport. Do not add a
        // flexible max-height proposal here: AppKit-backed ScrollView can
        // otherwise ask for an unbounded height during a kind switch and
        // briefly paint rows outside the settled popout clip.
        .frame(maxWidth: .infinity, alignment: .top)
        .scrollIndicators(.never)
        .scrollBounceBehavior(.basedOnSize)
        .onAppear {
            nexus.refreshAudio()
        }
    }

    private func compactStateButton(
        title: String,
        symbol: String,
        active: Bool,
        enabled: Bool,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: 6) {
                Image(systemName: symbol)
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                Text(title)
                            .font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                Spacer(minLength: 0)
                Circle()
                    .fill(active ? Theme.accent : Theme.muted.opacity(0.35))
                    .frame(width: 5, height: 5)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(maxWidth: .infinity, minHeight: PopoverCard.rowHeight, maxHeight: PopoverCard.rowHeight)
            .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .foregroundStyle(active ? Theme.accent : Theme.muted)
        .disabled(!enabled)
        // Real signal (e.g. a Bluetooth mic input exposing no settable
        // CoreAudio mute property leaves MIC LIVE genuinely unusable), not a
        // race -- but revealed by the popout's own open animation, it read
        // the same as the depth flicker below. `.disabled` still blocks the
        // tap; the card no longer visually announces it in advance.
        // This is the FOCUS/MIC LIVE pair in the compact rail Audio popout --
        // `nexusLayer`'s fill *and* border both key off `depth`, so an
        // active-driven depth here was a whole-card wash flicker, the same
        // bug class as the routing/Bluetooth cards but reached through a
        // different helper (`nexusLayer` vs a raw `Theme.X ? : Theme.Y`
        // background), which is why the earlier pass missed it. The label
        // text and the accent dot already carry the state at a size too
        // small to read as a flicker; the card itself now holds one tone.
        .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
    }

    private func outputRouteRow(_ device: SystemOutputAudio.Device) -> some View {
        let selected = nexus.isSelectedOutputDevice(device)
        return Button { nexus.selectOutputDevice(device) } label: {
            HStack(spacing: 8) {
                ZStack {
                    Circle().fill(selected ? Theme.accent.opacity(0.18) : Theme.layerTile)
                    Image(systemName: device.isAirPlayRoute ? "airplayaudio" : "hifispeaker.fill")
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(selected ? Theme.accent : Theme.muted)
                }.frame(width: 22, height: 22)
                Text(device.name)
                    .popoverRowTitle()
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                    .layoutPriority(1)
                Spacer(minLength: 6)
                Image(systemName: selected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(selected ? Theme.accent : Theme.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.rowHeight)
            .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .background(selected ? Theme.layerSelected : Theme.layerGroup, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(selected ? Theme.accent.opacity(0.62) : Theme.seam.opacity(0.22), lineWidth: selected ? 0.75 : 0.55)
        }
        .accessibilityValue(selected ? "Current" : "Available")
        .accessibilityHint("Tap to route audio here")
    }

    private func inputRouteRow(_ device: SystemInputAudio.Device) -> some View {
        let selected = device.id == nexus.selectedInputDeviceID
        return Button { nexus.selectInputDevice(device) } label: {
            HStack(spacing: 8) {
                ZStack {
                    Circle().fill(selected ? Theme.accent.opacity(0.18) : Theme.layerTile)
                    Image(systemName: "mic.fill")
                        .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                        .foregroundStyle(selected ? Theme.accent : Theme.muted)
                }.frame(width: 22, height: 22)
                Text(device.name)
                    .popoverRowTitle()
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                    .layoutPriority(1)
                Spacer(minLength: 6)
                Image(systemName: selected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(selected ? Theme.accent : Theme.muted.opacity(0.58))
                    .frame(width: 18)
            }
            .padding(.horizontal, PopoverCard.horizontalPadding)
            .frame(height: PopoverCard.rowHeight)
            .contentShape(Rectangle())
        }
        .buttonStyle(MicroButtonStyle())
        .background(selected ? Theme.layerSelected : Theme.layerGroup, in: RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.normal, style: .continuous)
                .stroke(selected ? Theme.accent.opacity(0.62) : Theme.seam.opacity(0.22), lineWidth: selected ? 0.75 : 0.55)
        }
        .accessibilityValue(selected ? "Current" : "Available")
        .accessibilityHint("Tap to route audio here")
    }

    private func audioRouteEmpty(_ title: String, symbol: String) -> some View {
        HStack(spacing: 8) {
            Image(systemName: symbol)
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
            Text(title)
                .popoverRowCaption()
            Spacer(minLength: 0)
        }
        .padding(.horizontal, PopoverCard.horizontalPadding)
        .frame(height: PopoverCard.rowHeight)
        .nexusLayer(cornerRadius: Rounding.normal, depth: .group)
    }
}

// HorizontalVolumeControl (a draggable volume slider) used to live here as
// part of the .audio popout. Caelestia's volume is scroll-only -- the
// screen-edge scroll slider already covers that -- so the popout is
// routing-only now and this control has no remaining caller.

private struct VerticalLevelControl: View {
    let symbol: String
    @Binding var value: Double
    let commit: () -> Void
    @State private var dragging = false
    @State private var showingValue = false
    @State private var glyphScale: CGFloat = 1
    @State private var glyphGeneration = 0
    @State private var releaseWorkItem: DispatchWorkItem?
    @State private var lastCommittedValue: Double?

    // Mouse motion commonly arrives in sub-percent increments. Updating the
    // model for every event is useful for the visual head, but repeatedly
    // writing the CoreAudio/DisplayServices value makes a short mouse drag
    // feel uneven. 0.2% is below the visible resolution of this control and
    // still keeps the hardware response continuous for small adjustments.
    private let commitEpsilon = 0.002

    var body: some View {
        GeometryReader { geo in
            let headHeight: CGFloat = 25
            let travel = max(1, geo.size.height - headHeight)
            let headOffset = travel * (1 - value)
            let fillHeight = max(headHeight / 2, geo.size.height - headOffset)
            ZStack(alignment: .top) {
                Capsule().fill(Theme.edgeSliderTrack).frame(width: 18)
                    .overlay(Capsule().stroke(Theme.seam.opacity(0.4), lineWidth: 0.8))
                Capsule().fill(LinearGradient(colors: Theme.edgeSliderFillColors, startPoint: .top, endPoint: .bottom))
                    .frame(width: 18, height: geo.size.height)
                    .mask(alignment: .bottom) {
                        Capsule()
                            .frame(width: 18, height: fillHeight)
                    }
                Capsule().fill(Theme.edgeSliderHead)
                    .frame(width: 28, height: headHeight)
                    // Always show a real seam here instead of only on light
                    // palettes -- Theme.sliderHead is now a genuine lightness
                    // step above frame on every palette, so a border reads
                    // consistently everywhere rather than dark palettes
                    // getting no edge definition at all.
                    .overlay(Capsule().stroke(Theme.seam.opacity(0.55), lineWidth: 1))
                    .overlay {
                        Group {
                            if showingValue {
                                Text("\(Int(value * 100))")
                                    .font(.system(size: ShellTypography.label, weight: .heavy, design: .rounded))
                                    .monospacedDigit()
                                    .foregroundStyle(Theme.bright)
                                    .contentTransition(.numericText())
                            } else {
                                Image(systemName: symbol)
                                    .font(.system(size: ShellIcon.small, weight: .bold, design: .rounded))
                                    .foregroundStyle(Theme.bright)
                                    .contentTransition(.symbolEffect(.replace))
                            }
                        }
                        .scaleEffect(glyphScale)
                    }
                    .offset(y: headOffset)
            }
            // VerticalSlider.qml uses a 600 ms standard value behaviour for
            // settled/external changes. A drag must be direct: restarting that
            // animation for every mouse event is what made small transitions
            // look like they were lagging behind the pointer.
            .animation(dragging ? nil : ShellMotion.valueChange.animation, value: value)
                .contentShape(Rectangle())
                .gesture(DragGesture(minimumDistance: 0)
                    .onChanged { drag in
                        if !dragging {
                            dragging = true
                            lastCommittedValue = value
                            transitionGlyph(toValue: true)
                        }
                        let nextValue = min(1, max(0, 1 - drag.location.y / geo.size.height))
                        withTransaction(Transaction(animation: nil)) {
                            value = nextValue
                        }
                        commitIfNeeded()
                    }
                    .onEnded { _ in
                        commitIfNeeded(force: true)
                        dragging = false
                        lastCommittedValue = nil
                        scheduleGlyphReset()
                    })
        }
        .frame(height: edgeLevelControlHeight)
        .onChange(of: value) { oldValue, newValue in
            // Scroll gestures arrive as deliberately small fractions (the
            // precise-trackpad path is only 0.16% per point). The old 1%
            // guard made the sidebar keep its icon until a large scroll had
            // already happened, so the value did not acknowledge the gesture
            // when it began. Any real movement should enter the numeric face;
            // the tiny epsilon only filters redundant floating-point writes.
            guard abs(newValue - oldValue) > 0.00001 else { return }
            if !dragging {
                transitionGlyph(toValue: true)
                scheduleGlyphReset()
            }
        }
        .onDisappear { releaseWorkItem?.cancel() }
    }

    private func scheduleGlyphReset() {
        releaseWorkItem?.cancel()
        let work = DispatchWorkItem { transitionGlyph(toValue: false) }
        releaseWorkItem = work
        // Caelestia keeps the numeric value visible for 500 ms after the
        // final adjustment before running the reverse two-stage transition.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.50, execute: work)
    }

    private func transitionGlyph(toValue: Bool) {
        releaseWorkItem?.cancel()
        guard showingValue != toValue || glyphScale < 0.999 else { return }
        glyphGeneration += 1
        let generation = glyphGeneration
        withAnimation(ShellMotion.iconOut.animation) { glyphScale = 0 }
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.iconOut.duration) {
            guard generation == glyphGeneration else { return }
            showingValue = toValue
            withAnimation(ShellMotion.iconIn.animation) { glyphScale = 1 }
        }
    }

    private func commitIfNeeded(force: Bool = false) {
        let previous = lastCommittedValue ?? value
        guard force || abs(value - previous) >= commitEpsilon else { return }
        lastCommittedValue = value
        commit()
    }
}

private struct SpectrumRing: View {
    let levels: [Double]; let phase: Double
    var body: some View {
        ZStack {
            ForEach(0..<36, id: \.self) { i in
                let level = levels.isEmpty ? 0.025 : levels[i % levels.count]
                Capsule().fill(i.isMultiple(of: 6) ? Theme.bright.opacity(0.92) : Theme.accent.opacity(0.74))
                    .frame(width: 1.7, height: 5 + CGFloat(level) * 14)
                    .offset(y: -45).rotationEffect(.degrees(Double(i) * 10))
                    // `levels` is a value array, so SwiftUI cannot
                    // interpolate the array as a whole. Animate each bar's
                    // scalar height at the producer cadence instead; the
                    // render server fills the gaps between shared-memory
                    // frames without adding a timer or a second audio reader.
                    .animation(.easeOut(duration: 0.11), value: level)
            }
            Circle().fill(Theme.surface.opacity(0.94)).frame(width: 76, height: 76)
                .overlay(Circle().stroke(Theme.edge.opacity(0.55)))
            VStack(spacing: Spacing.hairline) {
                Image(systemName: "waveform").foregroundStyle(Theme.mint)
            }
        }.frame(width: 126, height: 126)
            .rotationEffect(.degrees(phase * 0.08))
            // 0.12 rather than 0.25, to match the ~10Hz cadence phase actually
            // advances at. At 0.25 each rotation step was being replaced when
            // it was less than half finished, so the disc turned at a visibly
            // uneven rate instead of a constant one.
            .animation(.linear(duration: 0.12), value: phase)
    }
}

private struct ReactiveAlbumDisc: View {
    let media: MediaState
    let levels: [Double]
    let active: Bool
    /// The top-bar Dashboard and Media pages share one loader so the cover
    /// cannot be lost at the exact moment the strip changes focus. Other
    /// callers keep the disc-local loader through the nil default.
    var artworkLoader: ArtworkLoader? = nil
    /// Drawn size. Defaults to the 170pt presentation every constant in
    /// `disc(angle:)` was originally authored against.
    var diameter: CGFloat = 170
    /// Drives the record's continuous rotation. Toggled once when the view
    /// becomes active rather than recomputed per frame.
    @State private var spinning = false

    var body: some View {
        // The rotation is now declarative rather than a per-frame TimelineView.
        //
        // A TimelineView recomputes this whole view on a CPU schedule, so its
        // smoothness is capped by whatever interval it is given -- 45 Hz
        // originally, then 120 Hz, both of which visibly step on a 240 Hz
        // panel. Raising it again would just move the cap while making the CPU
        // loop more expensive. A single repeating linear animation is
        // interpolated by the render server instead, so it runs at the
        // display's native rate whatever that is, and costs nothing per frame.
        // 360 degrees is congruent with 0, so the repeat seam is invisible.
        disc()
            .onAppear { spinning = active }
            .onChange(of: active) { _, value in spinning = value }
    }

    private func disc() -> some View {
        // Every dimension below was previously a hard-coded point value tuned
        // for one 170pt presentation: bars sitting 58pt out from the centre
        // and growing up to 20pt beyond that, a 108pt record, a 15pt hub.
        // Because none of it referenced the frame, giving this view a smaller
        // frame did not make a smaller disc -- it made the same disc with its
        // outer bars clipped off, which is exactly how it "cut into" whatever
        // card it was placed in. Scaling from an explicit diameter means the
        // disc fits whatever room it is given, and callers size it to their
        // layout instead of the reverse.
        //
        // Deliberately not a GeometryReader: this redraws inside a TimelineView
        // at 45fps, where a GeometryReader costs a layout pass every frame and
        // leaves the size dependent on a proposal that is ambiguous inside the
        // enclosing Group. An explicit parameter is deterministic and cheaper.
        Group {
            // 170 is the size the original constants were authored against,
            // so it stays the reference that keeps the proportions identical
            // wherever the disc is still shown at its full size.
            let scale = diameter / 170
            ZStack {
                ForEach(0..<42, id: \.self) { index in
                    let level = levels.isEmpty ? 0.03 : levels[index % levels.count]
                    let barHeight = (5 + CGFloat(level) * 15) * scale
                    Capsule()
                        // Theme.mint, not Theme.bright: these are illuminated
                        // spectrum bars, and on White `bright` is a near-black
                        // that made every sixth bar render as a dark spike.
                        .fill(index.isMultiple(of: 6) ? Theme.mint.opacity(0.92) : Theme.accent.opacity(0.76))
                        .frame(width: max(1, 1.8 * scale), height: barHeight)
                        // Keep the end nearest the record fixed. Level changes
                        // now extend only outward instead of squeezing both ends.
                        .offset(y: -(58 * scale + barHeight / 2))
                        .rotationEffect(.degrees(Double(index) * (360.0 / 42.0)))
                        .animation(.easeOut(duration: 0.11), value: level)
                }
                Circle().fill(Theme.surface).frame(width: 108 * scale, height: 108 * scale)
                    .overlay {
                        // Read the model value directly. Keeping a second URL in
                        // local @State meant a disc first created with no cover
                        // could remain on its fallback even after the shared
                        // media model published valid artwork. AlbumArtwork's
                        // loader already retains the old decoded image while a
                        // replacement is fetched, so the extra state added no
                        // visual continuity and could only get out of sync.
                        if let artworkLoader {
                            SharedAlbumArtwork(
                                url: URL(string: media.artworkURL),
                                revision: media.artworkRevision,
                                fallback: AnyView(albumFallback),
                                loader: artworkLoader
                            )
                        } else {
                            AlbumArtwork(
                                url: URL(string: media.artworkURL),
                                revision: media.artworkRevision,
                                fallback: AnyView(albumFallback)
                            )
                        }
                    }
                    .clipShape(Circle())
                    .overlay(Circle().stroke(Theme.ice.opacity(0.5), lineWidth: 1))
                    .rotationEffect(.degrees(spinning ? 360 : 0))
                    .animation(
                        spinning
                            ? .linear(duration: 180).repeatForever(autoreverses: false)
                            : .default,
                        value: spinning
                    )
                Circle().fill(Theme.surfaceRaised.opacity(0.94)).frame(width: 15 * scale, height: 15 * scale)
                    .overlay(Circle().stroke(Theme.ice.opacity(0.62), lineWidth: 1))
            }
            .frame(width: diameter, height: diameter)
        }
    }

    private var albumFallback: some View {
        ZStack {
            Theme.surface
            ForEach(1..<5) { ring in Circle().stroke(Theme.muted.opacity(0.16), lineWidth: 1).padding(CGFloat(ring) * Spacing.base) }
            Image(systemName: "music.note").font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded)).foregroundStyle(Theme.ice)
        }
    }
}

private struct AlbumArtwork: View {
    let url: URL?
    let revision: String
    let fallback: AnyView

    @StateObject private var loader = ArtworkLoader()

    var body: some View {
        ArtworkImage(url: url, revision: revision, fallback: fallback, loader: loader)
    }
}

/// Keep using the same renderer as the Media disc, with a parent-owned loader
/// so a surface rebuild never exposes a newly-mounted dark placeholder over
/// the moving card.
private struct SharedAlbumArtwork: View {
    let url: URL?
    let revision: String
    let fallback: AnyView
    @ObservedObject var loader: ArtworkLoader

    var body: some View {
        ArtworkImage(url: url, revision: revision, fallback: fallback, loader: loader)
    }
}

private struct ArtworkImage: View {
    let url: URL?
    let revision: String
    let fallback: AnyView
    @ObservedObject var loader: ArtworkLoader

    private var artworkKey: String {
        "\(url?.absoluteString ?? "<none>")#\(revision)"
    }

    var body: some View {
        // Keep one image node mounted for the lifetime of the artwork slot.
        // Conditional insertion made a successful decode arrive as a new
        // subtree, so an ambient tab transition could animate that insertion
        // independently of the already-moving page. A transparent 1pt image
        // is only a layout placeholder; the visible fallback remains the
        // authored media tile underneath it.
        let decodedImage = loader.image
        let showDecodedImage = url != nil && decodedImage != nil
        ZStack {
            fallback.opacity(showDecodedImage ? 0 : 1)
            Image(nsImage: decodedImage ?? NSImage(size: NSSize(width: 1, height: 1)))
                .resizable()
                .scaledToFill()
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
                .opacity(showDecodedImage ? 1 : 0)
        }
        // Suppress only the fallback/image opacity swap. A blanket transaction
        // override here also disabled the Dashboard page's tab-slide transaction
        // for this subtree, so the square snapped out and back while its card
        // continued moving. The Media disc masked that mistake because its cover
        // sits below a separate, continuously animated rotation transform.
        .animation(nil, value: showDecodedImage)
        .onAppear { loadIfNeeded() }
        // URL and revision are one artwork identity. Watching them separately
        // could cancel a valid fetch and immediately start it again when the
        // media producer published the new file metadata in two fields.
        .onChange(of: artworkKey) { _, _ in loadIfNeeded() }
    }

    private func loadIfNeeded() {
        guard let url else { return }
        loader.load(url, revision: revision)
    }
}

@MainActor private final class ArtworkLoader: ObservableObject {
    private static let cache: NSCache<NSString, NSImage> = {
        let cache = NSCache<NSString, NSImage>()
        cache.countLimit = 64
        return cache
    }()
    @Published private(set) var image: NSImage?
    private var representedKey = ""
    private var task: URLSessionDataTask?
    private var loadInFlight = false
    private var retryWorkItem: DispatchWorkItem?
    private var retryAttempt = 0
    private let retryDelays: [TimeInterval] = [0.35, 0.7, 1.4, 2.8]

    func load(_ url: URL, revision: String) {
        let key = "\(url.absoluteString)#\(revision)"
        if representedKey == key {
            // A failed request must be retryable. An in-flight request or a
            // scheduled retry already owns this key; otherwise this is a new
            // attempt from a surviving artwork view.
            guard image == nil, !loadInFlight, retryWorkItem == nil else { return }
            retryAttempt = 0
            startLoad(url, key: key)
            return
        }
        representedKey = key
        task?.cancel()
        task = nil
        loadInFlight = false
        retryWorkItem?.cancel()
        retryWorkItem = nil
        retryAttempt = 0
        startLoad(url, key: key)
    }

    private func startLoad(_ url: URL, key: String) {
        guard representedKey == key else { return }
        loadInFlight = true
        let cacheKey = key as NSString
        if let cached = Self.cache.object(forKey: cacheKey) {
            image = cached
            loadInFlight = false
            return
        }

        if url.isFileURL {
            // The Spotify bridge writes a local cover file. Reading and
            // decoding that file synchronously on the main actor made the
            // Dashboard feel one beat behind the metadata update, especially
            // while the top surface was also moving.
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                // macpp:silent-ok read/decode failure is handled below via failed(_:key:), not swallowed
                guard let data = try? Data(contentsOf: url, options: [.mappedIfSafe]),
                      let decoded = Self.decode(data) else {
                    DispatchQueue.main.async { self?.failed(url, key: key) }
                    return
                }
                DispatchQueue.main.async {
                    self?.finish(decoded, key: key)
                }
            }
            return
        }
        // Retain the previous artwork while the next image is fetched. The
        // disc therefore never flashes through its placeholder on metadata
        // refreshes or transient Spotify URL changes. Decode the pixels off
        // the main actor; only the tiny NSImage handoff and @Published write
        // return to it.
        var request = URLRequest(url: url)
        request.cachePolicy = .returnCacheDataElseLoad
        request.timeoutInterval = 6
        task = URLSession.shared.dataTask(with: request) { [weak self] data, _, _ in
            guard let data, let decoded = Self.decode(data) else {
                DispatchQueue.main.async { self?.failed(url, key: key) }
                return
            }
            DispatchQueue.main.async {
                self?.finish(decoded, key: key)
            }
        }
        task?.resume()
    }

    private func finish(_ decoded: CGImage, key: String) {
        guard representedKey == key else { return }
        loadInFlight = false
        task = nil
        retryWorkItem?.cancel()
        retryWorkItem = nil
        retryAttempt = 0
        let size = NSSize(width: decoded.width, height: decoded.height)
        let next = NSImage(cgImage: decoded, size: size)
        Self.cache.setObject(next, forKey: key as NSString)
        image = next
    }

    private func failed(_ url: URL, key: String) {
        guard representedKey == key else { return }
        loadInFlight = false
        task = nil
        guard retryAttempt < retryDelays.count else { return }
        let delay = retryDelays[retryAttempt]
        retryAttempt += 1
        let work = DispatchWorkItem { [weak self] in
            guard let self, self.representedKey == key else { return }
            self.retryWorkItem = nil
            self.startLoad(url, key: key)
        }
        retryWorkItem?.cancel()
        retryWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }

    private nonisolated static func decode(_ data: Data) -> CGImage? {
        let options: CFDictionary = [
            kCGImageSourceShouldCacheImmediately: true
        ] as CFDictionary
        guard let source = CGImageSourceCreateWithData(data as CFData, options) else { return nil }
        return CGImageSourceCreateImageAtIndex(source, 0, options)
    }

    deinit {
        task?.cancel()
        retryWorkItem?.cancel()
    }
}

private struct AnimatedCompanionImage: NSViewRepresentable {
    let path: String
    let active: Bool
    final class Coordinator {
        var loadedPath: String?
    }
    func makeCoordinator() -> Coordinator { Coordinator() }
    func makeNSView(context: Context) -> NSImageView {
        let view = NSImageView()
        // The companion accepts arbitrary source dimensions. Always fit the
        // asset into its dedicated canvas instead of allowing the NSImage's
        // intrinsic size to influence the surrounding media layout.
        view.imageScaling = .scaleProportionallyUpOrDown
        view.imageAlignment = .alignCenter
        view.setContentHuggingPriority(.defaultLow, for: .horizontal)
        view.setContentHuggingPriority(.defaultLow, for: .vertical)
        view.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        view.setContentCompressionResistancePriority(.defaultLow, for: .vertical)
        view.animates = true
        view.wantsLayer = true
        view.layer?.masksToBounds = true
        return view
    }
    func updateNSView(_ view: NSImageView, context: Context) {
        // SwiftUI keeps the neighboring top-bar pages alive during the strip
        // slide. An NSImageView animates a GIF independently of visibility,
        // so stop its frame timer whenever Media is not the selected page.
        view.animates = active
        guard context.coordinator.loadedPath != path else { return }
        context.coordinator.loadedPath = path
        view.image = NSImage(contentsOfFile: path)
    }
    func sizeThatFits(_ proposal: ProposedViewSize, nsView: NSImageView, context: Context) -> CGSize? {
        CGSize(width: proposal.width ?? 116, height: proposal.height ?? 116)
    }
}

private struct StaticCompanionImage: NSViewRepresentable {
    let path: String
    let revision: Int
    final class Coordinator {
        var loadedPath: String?
        var loadedRevision = -1
    }
    func makeCoordinator() -> Coordinator { Coordinator() }
    func makeNSView(context: Context) -> NSView {
        let view = NSView()
        view.wantsLayer = true
        view.layer?.masksToBounds = true
        view.layer?.contentsGravity = .resizeAspectFill
        view.layer?.contentsScale = NSScreen.main?.backingScaleFactor ?? 2
        return view
    }
    func updateNSView(_ view: NSView, context: Context) {
        guard context.coordinator.loadedPath != path || context.coordinator.loadedRevision != revision else { return }
        context.coordinator.loadedPath = path
        context.coordinator.loadedRevision = revision
        view.layer?.contents = NSImage(contentsOfFile: path)
    }
    func sizeThatFits(_ proposal: ProposedViewSize, nsView: NSView, context: Context) -> CGSize? {
        CGSize(width: proposal.width ?? 136, height: proposal.height ?? 170)
    }
}

private enum CompanionContentKind: Equatable {
    case lyrics
    case transcript
}

@MainActor private final class CompanionLyricsModel: ObservableObject {
    private struct CacheEntry {
        let lines: [MacPlusPlusTimedLyric]
        let synchronized: Bool
        let kind: CompanionContentKind
    }

    private struct LookupCandidate {
        let track: String
        let artist: String
        let album: String
        let duration: Int
    }

    private struct LoadedContent {
        let lines: [MacPlusPlusTimedLyric]
        let kind: CompanionContentKind
    }

    @Published var lines: [MacPlusPlusTimedLyric] = []
    @Published var synchronized = false
    @Published var loading = false
    @Published var contentKind: CompanionContentKind = .lyrics
    private var representedKey = ""
    private var task: Task<Void, Never>?
    // Deliberately memory-only. Nothing is written to UserDefaults or disk,
    // and the small bound prevents an all-day listening session from growing
    // the shell indefinitely.
    private var cache: [String: CacheEntry] = [:]
    private var cacheOrder: [String] = []
    private var enabled = true

    func setEnabled(_ enabled: Bool) {
        self.enabled = enabled
        guard !enabled else { return }
        task?.cancel()
        loading = false
    }

    func refresh(for media: MediaState, force: Bool = false) {
        guard enabled else { return }
        // Captions are useful for YouTube, but the producer may also obtain a
        // transcript URL from another browser bridge. Do not discard a valid
        // URL merely because MediaRemote called the owner "media".
        let transcriptURL = Self.httpURLString(media.transcriptURL)
        let transcriptMode = !transcriptURL.isEmpty
        let provider = MediaProvider.resolve(media)
        let title = Self.cleanMetadata(media.title)
        let key = transcriptMode
            ? "transcript|\(provider.cacheKey)|\(transcriptURL)"
            : "lyrics|\(provider.cacheKey)|\(title)|\(Self.cleanMetadata(media.artist))|\(Self.cleanMetadata(media.album))|\(Int(media.duration.rounded()))"
        // Safari and YouTube commonly publish a title without an artist. The
        // search fallback below can resolve that shape, so artist is no longer
        // a prerequisite for showing anything.
        guard !title.isEmpty else {
            task?.cancel()
            representedKey = ""
            lines = []
            synchronized = false
            loading = false
            contentKind = .lyrics
            return
        }
        guard force || representedKey != key else { return }
        representedKey = key
        task?.cancel()
        if !force, let cached = cache[key] {
            lines = cached.lines
            synchronized = cached.synchronized
            contentKind = cached.kind
            loading = false
            return
        }
        contentKind = transcriptMode ? .transcript : .lyrics
        loading = true

        task = Task { [weak self] in
            do {
                let result = try await Self.loadContent(for: media, transcriptURL: transcriptURL)
                try Task.checkCancellation()
                guard let self, self.representedKey == key else { return }
                // Plain LRCLIB lyrics use `greatestFiniteMagnitude` as an
                // intentionally unsynchronized timestamp. Treat only real
                // playback-scale timestamps as seekable lines.
                self.synchronized = result.lines.contains {
                    $0.time < Double.greatestFiniteMagnitude / 2
                }
                self.lines = result.lines
                self.contentKind = result.kind
                self.loading = false
                self.store(
                    CacheEntry(
                        lines: self.lines,
                        synchronized: self.synchronized,
                        kind: self.contentKind
                    ),
                    for: key
                )
            } catch {
                guard !Task.isCancelled, let self, self.representedKey == key else { return }
                self.lines = []
                self.synchronized = false
                self.loading = false
            }
        }
    }

    private static func loadContent(
        for media: MediaState,
        transcriptURL: String
    ) async throws -> LoadedContent {
        if !transcriptURL.isEmpty {
            do {
                let lines = try await loadTranscript(from: transcriptURL)
                return LoadedContent(lines: lines, kind: .transcript)
            } catch is CancellationError {
                throw CancellationError()
            } catch {
                // A caption URL can expire, or Safari can return a format the
                // small parser cannot decode. Lyrics search is still useful
                // with the same media metadata, so continue instead of leaving
                // a browser track permanently blank.
            }
        }
        return LoadedContent(lines: try await loadLyrics(for: media), kind: .lyrics)
    }

    private static func loadLyrics(for media: MediaState) async throws -> [MacPlusPlusTimedLyric] {
        let candidates = Self.lookupCandidates(for: media)

        // Keep the precise endpoint first when a real artist is available.
        // This preserves Spotify's accurate matching and handles browser
        // metadata that happens to be complete without a broader search.
        for candidate in candidates where !candidate.artist.isEmpty {
            var query = [
                URLQueryItem(name: "track_name", value: candidate.track),
                URLQueryItem(name: "artist_name", value: candidate.artist)
            ]
            if !candidate.album.isEmpty {
                query.append(URLQueryItem(name: "album_name", value: candidate.album))
            }
            if candidate.duration > 0 {
                query.append(URLQueryItem(name: "duration", value: String(candidate.duration)))
            }
            guard let payload = try await requestJSON(path: "/api/get", query: query)
                    as? [String: Any] else { continue }
            let found = Self.lyricLines(from: payload)
            if !found.isEmpty { return found }
        }

        // LRCLIB's `/api/get` rejects an empty artist_name. Its search endpoint
        // does not, and is the important browser fallback: YouTube/Safari often
        // expose only a page title or a channel name. Rank results locally so a
        // generic title cannot silently paint lyrics from an unrelated track.
        for candidate in candidates where !candidate.track.isEmpty {
            var query = [URLQueryItem(name: "track_name", value: candidate.track)]
            if !candidate.artist.isEmpty {
                query.append(URLQueryItem(name: "artist_name", value: candidate.artist))
            }
            if !candidate.album.isEmpty {
                query.append(URLQueryItem(name: "album_name", value: candidate.album))
            }
            guard let results = try await requestJSON(path: "/api/search", query: query)
                    as? [[String: Any]] else { continue }
            let found = Self.bestSearchLyrics(from: results, for: candidate)
            if !found.isEmpty { return found }
        }
        return []
    }

    private static func requestJSON(path: String, query: [URLQueryItem]) async throws -> Any? {
        var components = URLComponents()
        components.scheme = "https"
        components.host = "lrclib.net"
        components.path = path
        components.queryItems = query.filter { !($0.value ?? "").isEmpty }
        guard let requestURL = components.url else { throw URLError(.badURL) }
        var request = URLRequest(url: requestURL)
        request.cachePolicy = .returnCacheDataElseLoad
        request.timeoutInterval = 8
        request.setValue("MacPlusPlusShell/1.0 (personal macOS shell)", forHTTPHeaderField: "User-Agent")
        let (data, response) = try await URLSession.shared.data(for: request)
        try Task.checkCancellation()
        guard (response as? HTTPURLResponse)?.statusCode == 200 else { return nil }
        // macpp:silent-ok malformed LRCLIB JSON is treated as a miss so the next lyric candidate can retry.
        return try? JSONSerialization.jsonObject(with: data)
    }

    private static func lyricLines(from payload: [String: Any]) -> [MacPlusPlusTimedLyric] {
        let synced = timedLyrics(from: payload["syncedLyrics"] as? String ?? "")
        let plain = (payload["plainLyrics"] as? String ?? "")
            .split(separator: "\n")
            .map { cleanMetadata(String($0)) }
            .filter { !$0.isEmpty }
            .map { MacPlusPlusTimedLyric(time: .greatestFiniteMagnitude, text: $0) }
        return synced.isEmpty ? plain : synced
    }

    private static func lookupCandidates(for media: MediaState) -> [LookupCandidate] {
        let rawTitle = cleanMetadata(media.title)
        let cleanedTitle = stripVideoSuffix(rawTitle)
        let suppliedArtist = cleanMetadata(media.artist)
        let artist = ["youtube", "youtube music", "safari"].contains(suppliedArtist.lowercased())
            ? ""
            : suppliedArtist
        let album = cleanMetadata(media.album)
        let duration = media.duration > 0 ? Int(media.duration.rounded()) : 0
        var candidates: [LookupCandidate] = []
        var seen = Set<String>()

        func append(track: String, artist: String) {
            let track = cleanMetadata(track)
            let artist = cleanMetadata(artist)
            guard !track.isEmpty else { return }
            let key = "\(track.lowercased())|\(artist.lowercased())|\(album.lowercased())|\(duration)"
            guard seen.insert(key).inserted else { return }
            candidates.append(LookupCandidate(track: track, artist: artist, album: album, duration: duration))
        }

        append(track: rawTitle, artist: artist)
        if cleanedTitle != rawTitle { append(track: cleanedTitle, artist: artist) }

        // A common browser title is "Artist - Track (Official Video)". Only
        // infer this when the producer did not already provide an artist; an
        // actual artist field is more trustworthy than punctuation in a title.
        if artist.isEmpty, let split = splitArtistAndTrack(cleanedTitle) {
            append(track: split.track, artist: split.artist)
        }
        if artist.isEmpty, cleanedTitle != rawTitle {
            append(track: cleanedTitle, artist: "")
        }
        return candidates
    }

    private static func cleanMetadata(_ value: String) -> String {
        value
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private static func stripVideoSuffix(_ raw: String) -> String {
        var value = cleanMetadata(raw)
        let lower = value.lowercased()
        for suffix in [" - youtube", " | youtube", " – youtube", " — youtube"] {
            if lower.hasSuffix(suffix) {
                value = cleanMetadata(String(value.dropLast(suffix.count)))
                break
            }
        }
        // These are deliberately only fallback variants. A legitimate title
        // containing one of these words still gets its untouched query first.
        return value.replacingOccurrences(
            of: #"\s*(?:\(|\[)?(?:official\s+(?:music\s+)?video|official\s+audio|lyrics?(?:\s+video)?|music\s+video|audio|visualizer)(?:\)|\])?\s*$"#,
            with: "",
            options: .regularExpression
        ).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func splitArtistAndTrack(_ title: String) -> (artist: String, track: String)? {
        for separator in [" - ", " – ", " — ", " | "] {
            guard let range = title.range(of: separator) else { continue }
            let artist = cleanMetadata(String(title[..<range.lowerBound]))
            let track = cleanMetadata(String(title[range.upperBound...]))
            guard artist.count > 1, track.count > 1,
                  !["official", "music video", "official video"].contains(track.lowercased()) else {
                continue
            }
            return (artist, track)
        }
        return nil
    }

    private static func bestSearchLyrics(
        from results: [[String: Any]],
        for candidate: LookupCandidate
    ) -> [MacPlusPlusTimedLyric] {
        var bestScore = -Double.greatestFiniteMagnitude
        var bestLines: [MacPlusPlusTimedLyric] = []
        for result in results {
            let lines = lyricLines(from: result)
            guard !lines.isEmpty, let score = searchScore(result, for: candidate) else { continue }
            if score > bestScore {
                bestScore = score
                bestLines = lines
            }
        }
        return bestLines
    }

    private static func searchScore(_ result: [String: Any], for candidate: LookupCandidate) -> Double? {
        let resultTitle = cleanMetadata((result["trackName"] as? String) ?? (result["name"] as? String) ?? "")
        let wantedTitle = normalizedMetadata(candidate.track)
        let actualTitle = normalizedMetadata(resultTitle)
        guard !wantedTitle.isEmpty, !actualTitle.isEmpty else { return nil }

        var score: Double
        if actualTitle == wantedTitle {
            score = 100
        } else if actualTitle.contains(wantedTitle) || wantedTitle.contains(actualTitle) {
            score = 72
        } else {
            return nil
        }

        let resultArtist = normalizedMetadata(cleanMetadata(result["artistName"] as? String ?? ""))
        let wantedArtist = normalizedMetadata(candidate.artist)
        if !wantedArtist.isEmpty {
            if resultArtist == wantedArtist { score += 38 }
            else if resultArtist.contains(wantedArtist) || wantedArtist.contains(resultArtist) { score += 20 }
            else { score -= 18 }
        }

        let wantedAlbum = normalizedMetadata(candidate.album)
        let resultAlbum = normalizedMetadata(cleanMetadata(result["albumName"] as? String ?? ""))
        if !wantedAlbum.isEmpty, !resultAlbum.isEmpty {
            if resultAlbum == wantedAlbum { score += 18 }
            else if resultAlbum.contains(wantedAlbum) || wantedAlbum.contains(resultAlbum) { score += 8 }
        }

        if candidate.duration > 0, let resultDuration = numericValue(result["duration"]) {
            let difference = abs(resultDuration - Double(candidate.duration))
            if difference <= 3 { score += 24 }
            else if difference <= 8 { score += 16 }
            else if difference <= 20 { score += 6 }
            else { score -= 20 }
        }
        if result["syncedLyrics"] as? String != nil { score += 4 }
        return score >= 70 ? score : nil
    }

    private static func normalizedMetadata(_ value: String) -> String {
        cleanMetadata(value)
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private static func numericValue(_ value: Any?) -> Double? {
        if let number = value as? NSNumber { return number.doubleValue }
        if let string = value as? String { return Double(string) }
        return nil
    }

    private static func httpURLString(_ raw: String) -> String {
        guard let url = URL(string: raw),
              let scheme = url.scheme?.lowercased(),
              scheme == "http" || scheme == "https" else { return "" }
        return url.absoluteString
    }

    private static func loadTranscript(from rawURL: String) async throws -> [MacPlusPlusTimedLyric] {
        guard let url = URL(string: rawURL),
              let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https" else {
            throw URLError(.badURL)
        }
        var request = URLRequest(url: url)
        request.cachePolicy = .returnCacheDataElseLoad
        request.timeoutInterval = 8
        request.setValue("MacPlusPlusShell/1.0 (personal macOS shell)", forHTTPHeaderField: "User-Agent")
        let (data, response) = try await URLSession.shared.data(for: request)
        try Task.checkCancellation()
        guard (response as? HTTPURLResponse)?.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }
        let lines = Self.transcriptLines(from: data)
        guard !lines.isEmpty else { throw URLError(.cannotDecodeContentData) }
        return lines
    }

    private static func transcriptLines(from data: Data) -> [MacPlusPlusTimedLyric] {
        // macpp:silent-ok a non-JSON transcript falls through to the XML caption parser below
        if let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let events = object["events"] as? [[String: Any]] {
            var result: [MacPlusPlusTimedLyric] = []
            for event in events {
                guard let start = numericValue(event["tStartMs"]) else { continue }
                let text = (event["segs"] as? [[String: Any]] ?? [])
                    .compactMap { $0["utf8"] as? String }
                    .joined()
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !text.isEmpty else { continue }
                if result.last?.text != text {
                    result.append(MacPlusPlusTimedLyric(time: start / 1000, text: text))
                }
            }
            if !result.isEmpty { return result }
        }

        let parser = CaptionXMLParser()
        guard parser.parse(data) else { return [] }
        return parser.lines
    }

    private final class CaptionXMLParser: NSObject, XMLParserDelegate {
        var lines: [MacPlusPlusTimedLyric] = []
        private var start = 0.0
        private var text = ""
        private var insideText = false

        func parse(_ data: Data) -> Bool {
            let parser = XMLParser(data: data)
            parser.delegate = self
            return parser.parse()
        }

        func parser(
            _ parser: XMLParser,
            didStartElement elementName: String,
            namespaceURI: String?,
            qualifiedName qName: String?,
            attributes attributeDict: [String: String] = [:]
        ) {
            guard elementName == "text" else { return }
            start = Double(attributeDict["start"] ?? "0") ?? 0
            text = ""
            insideText = true
        }

        func parser(_ parser: XMLParser, foundCharacters string: String) {
            guard insideText else { return }
            text += string
        }

        func parser(
            _ parser: XMLParser,
            didEndElement elementName: String,
            namespaceURI: String?,
            qualifiedName qName: String?
        ) {
            guard elementName == "text", insideText else { return }
            let value = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if !value.isEmpty, lines.last?.text != value {
                lines.append(MacPlusPlusTimedLyric(time: start, text: value))
            }
            insideText = false
        }
    }

    private func store(_ entry: CacheEntry, for key: String) {
        cache[key] = entry
        cacheOrder.removeAll(where: { $0 == key })
        cacheOrder.append(key)
        while cacheOrder.count > 6 {
            cache.removeValue(forKey: cacheOrder.removeFirst())
        }
    }

    private static func timedLyrics(from raw: String) -> [MacPlusPlusTimedLyric] {
        raw.split(separator: "\n").compactMap { rawLine in
            let line = String(rawLine)
            guard line.first == "[", let close = line.firstIndex(of: "]") else { return nil }
            let stamp = line[line.index(after: line.startIndex)..<close].split(separator: ":")
            guard stamp.count == 2, let minutes = Double(stamp[0]), let seconds = Double(stamp[1]) else { return nil }
            let text = line[line.index(after: close)...].trimmingCharacters(in: .whitespaces)
            return text.isEmpty ? nil : MacPlusPlusTimedLyric(time: minutes * 60 + seconds, text: text)
        }
    }
}

private struct CompanionLyricsView: View {
    @ObservedObject var lyrics: CompanionLyricsModel
    let media: MediaState

    private var hasMedia: Bool {
        !media.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var activeLineID: UUID? {
        guard lyrics.synchronized else { return nil }
        return lyrics.lines.last(where: { $0.time <= media.position + 0.08 })?.id
    }

    var body: some View {
        VStack(alignment: .leading, spacing: Spacing.none) {
            HStack(spacing: Spacing.tight) {
                Image(systemName: "quote.bubble.fill")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
                Spacer(minLength: 0)
                Circle()
                    .fill(lyrics.loading ? Theme.accent.opacity(0.55) : (lyrics.lines.isEmpty ? Theme.muted.opacity(0.55) : Theme.accent))
                    .frame(width: 5, height: 5)
            }
            .frame(height: 16)

            if !hasMedia {
                VStack(spacing: Spacing.snug) {
                    Image(systemName: "music.note.list")
                        .font(.system(size: ShellIcon.feature, weight: .medium, design: .rounded))
                        .foregroundStyle(Theme.accent)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                Group {
                    if lyrics.loading {
                        VStack(spacing: Spacing.snug) {
                            ProgressView()
                                .controlSize(.small)
                                .tint(Theme.accent)
                        }
                    } else if lyrics.lines.isEmpty {
                        VStack(spacing: Spacing.base) {
                            Spacer(minLength: 0)
                            Image(systemName: "rectangle.2.swap")
                                .font(.system(size: ShellIcon.header, weight: .medium, design: .rounded))
                                .foregroundStyle(Theme.accent)
                            Spacer(minLength: 0)
                        }
                    } else {
                        ScrollViewReader { proxy in
                            ScrollView(.vertical, showsIndicators: false) {
                                VStack(alignment: .leading, spacing: Spacing.snug) {
                                    ForEach(lyrics.lines) { line in
                                        let active = line.id == activeLineID
                                        Text(line.text)
                                            .font(.system(
                                                size: active ? 9 : 8,
                                                weight: active ? .heavy : .semibold,
                                                design: .rounded
                                            ))
                                            .foregroundStyle(active ? Theme.accent : Theme.muted)
                                            .multilineTextAlignment(.leading)
                                            .lineLimit(3)
                                            .frame(maxWidth: .infinity, alignment: .leading)
                                            .id(line.id)
                                    }
                                }
                                .padding(.horizontal, Spacing.none)
                                .padding(.vertical, Spacing.snug)
                                .frame(maxWidth: .infinity)
                            }
                            .scrollIndicators(.never)
                            .onChange(of: activeLineID) { _, lineID in
                                guard let lineID else { return }
                                withAnimation(ShellMotion.panelSwitch.animation) {
                                    proxy.scrollTo(lineID, anchor: .center)
                                }
                            }
                            .onAppear {
                                guard let activeLineID else { return }
                                proxy.scrollTo(activeLineID, anchor: .center)
                            }
                        }
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .padding(Spacing.base)
        .frame(width: 136, height: 170, alignment: .topLeading)
    }
}

/// Finds companion art for palettes that do not ship any.
///
/// Only the eight built-in palettes have a `media-companion-<name>.png`. Any
/// wallpaper the user imports lands on the `custom` palette, which has no
/// artwork of its own, so the media tab fell all the way through to the single
/// global companion -- the same picture no matter what the wallpaper looked
/// like. This matches an unclaimed wallpaper to whichever shipped companion is
/// closest in average colour, so the slot always carries art that belongs with
/// what is actually on screen.
///
/// Everything here is MainActor-isolated and cached, because the resolution
/// runs from a `View`'s body: decoding eight multi-megabyte PNGs on each
/// evaluation would be ruinous. Averages are additionally persisted next to the
/// art so a cold launch does not pay for the decode either.
@MainActor
private enum CompanionLibrary {
    static let root = NSHomeDirectory() + "/Library/Application Support/MacPlusPlus/Assets/Companions/"

    private struct Sample: Codable {
        var modified: Double
        var red: Double
        var green: Double
        var blue: Double
    }

    private static var samples: [String: Sample]?
    /// Target colour (as hex) -> chosen file name, so repeated body
    /// evaluations for an unchanged palette are a dictionary lookup.
    private static var resolved: [String: String] = [:]

    private static var cacheURL: URL { URL(fileURLWithPath: root + "average-colors.json") }

    static func companionPath(for palette: ShellPalette) -> String? {
        let themed = root + "media-companion-\(palette.rawValue).png"
        if FileManager.default.fileExists(atPath: themed) { return themed }
        guard let target = targetColor(for: palette) else { return nil }
        let key = "\(Int(target.0 * 255))-\(Int(target.1 * 255))-\(Int(target.2 * 255))"
        if let cached = resolved[key] { return root + cached }
        guard let match = nearestCompanion(to: target) else { return nil }
        resolved[key] = match
        return root + match
    }

    /// The colour an unclaimed wallpaper is matched on.
    ///
    /// The palette's tokens are already derived from the wallpaper, so there is
    /// no need to decode a video frame. `frame` carries the overall value and
    /// `accent` carries the hue; companions are coloured illustrations, so both
    /// are needed -- accent alone sends every dark palette to the white art,
    /// and frame alone sends every dark palette to the obsidian art.
    ///
    /// 0.6 is calibrated, not guessed: the eight built-in palettes already have
    /// hand-picked art, so they are a ground truth. Sweeping this weight, 0.6 is
    /// the value at which all eight palettes independently rediscover their own
    /// companion. It degrades gracefully -- 0.55 and 0.65 still get 5 and 6 of
    /// 8, and their misses are all near-identical dark blue-greys.
    private static func targetColor(for palette: ShellPalette) -> (Double, Double, Double)? {
        let tokens = palette.tokens
        guard let frame = NSColor(tokens.frame).usingColorSpace(.sRGB),
              let accent = NSColor(tokens.accent).usingColorSpace(.sRGB) else { return nil }
        let frameWeight = 0.6
        let accentWeight = 1 - frameWeight
        return (
            Double(frame.redComponent) * frameWeight + Double(accent.redComponent) * accentWeight,
            Double(frame.greenComponent) * frameWeight + Double(accent.greenComponent) * accentWeight,
            Double(frame.blueComponent) * frameWeight + Double(accent.blueComponent) * accentWeight
        )
    }

    private static func nearestCompanion(to target: (Double, Double, Double)) -> String? {
        let library = loadSamples()
        guard !library.isEmpty else { return nil }
        let best = library.min { lhs, rhs in
            distance(target, (lhs.value.red, lhs.value.green, lhs.value.blue))
                < distance(target, (rhs.value.red, rhs.value.green, rhs.value.blue))
        }
        return best?.key
    }

    /// Redmean: a cheap approximation of perceptual distance. Plain RGB
    /// Euclidean would happily call a saturated blue and a saturated green
    /// equally distant from grey, which is not how either one looks.
    private static func distance(_ a: (Double, Double, Double), _ b: (Double, Double, Double)) -> Double {
        let meanRed = (a.0 + b.0) / 2
        let dr = a.0 - b.0, dg = a.1 - b.1, db = a.2 - b.2
        return (2 + meanRed) * dr * dr + 4 * dg * dg + (3 - meanRed) * db * db
    }

    private static func loadSamples() -> [String: Sample] {
        if let alreadyLoaded = samples { return alreadyLoaded }

        var cached: [String: Sample] = [:]
        if let data = try? Data(contentsOf: cacheURL), // macpp:silent-ok absent media sample cache is rebuilt from source images
           let decoded = try? JSONDecoder().decode([String: Sample].self, from: data) { // macpp:silent-ok malformed media sample cache is rebuilt from source images
            cached = decoded
        }

        let manager = FileManager.default
        let names = ((try? manager.contentsOfDirectory(atPath: root)) ?? []) // macpp:silent-ok an unreadable media cache contributes no sample files
            .filter { $0.lowercased().hasSuffix(".png") && $0.hasPrefix("media-companion-") }
            .sorted()

        var result: [String: Sample] = [:]
        var dirty = false
        for name in names {
            let path = root + name
            let modified = ((try? manager.attributesOfItem(atPath: path)[.modificationDate]) as? Date)? // macpp:silent-ok missing media mtime uses the zero cache timestamp
                .timeIntervalSince1970 ?? 0
            // Re-sample only when the file itself has changed.
            if let entry = cached[name], abs(entry.modified - modified) < 1 {
                result[name] = entry
                continue
            }
            guard let average = averageColor(ofImageAt: path) else { continue }
            result[name] = Sample(modified: modified, red: average.0, green: average.1, blue: average.2)
            dirty = true
        }
        if dirty || result.count != cached.count {
            if let data = try? JSONEncoder().encode(result) { try? data.write(to: cacheURL, options: .atomic) } // macpp:silent-ok media sample cache persistence is best effort
        }

        samples = result
        return result
    }

    private static func averageColor(ofImageAt path: String) -> (Double, Double, Double)? {
        guard let image = NSImage(contentsOfFile: path),
              let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else { return nil }
        let side = 16
        var pixels = [UInt8](repeating: 0, count: side * side * 4)
        let drawn: Bool = pixels.withUnsafeMutableBytes { buffer -> Bool in
            guard let base = buffer.baseAddress,
                  let context = CGContext(
                    data: base,
                    width: side,
                    height: side,
                    bitsPerComponent: 8,
                    bytesPerRow: side * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB(),
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
                  ) else { return false }
            context.interpolationQuality = .medium
            context.draw(cgImage, in: CGRect(x: 0, y: 0, width: side, height: side))
            return true
        }
        guard drawn else { return nil }

        // The buffer is alpha-premultiplied, so the stored value already *is*
        // colour x alpha. Summing it and dividing by the summed alpha gives an
        // alpha-weighted average for free -- and keeps the transparent margin
        // these illustrations have from dragging every result toward black.
        var red = 0.0, green = 0.0, blue = 0.0, weight = 0.0
        for index in stride(from: 0, to: pixels.count, by: 4) {
            let alpha = Double(pixels[index + 3]) / 255
            guard alpha > 0.05 else { continue }
            red += Double(pixels[index]) / 255
            green += Double(pixels[index + 1]) / 255
            blue += Double(pixels[index + 2]) / 255
            weight += alpha
        }
        guard weight > 0 else { return nil }
        return (red / weight, green / weight, blue / weight)
    }
}

private struct SpotifyNextTrackView: View {
    let track: SpotifyNextTrack?
    let status: SpotifyQueueStatus
    let providerLabel: String
    let transcriptAvailable: Bool
    let onConnect: () -> Void
    let compact: Bool

    init(
        track: SpotifyNextTrack?,
        status: SpotifyQueueStatus,
        providerLabel: String,
        transcriptAvailable: Bool,
        onConnect: @escaping () -> Void,
        compact: Bool = false
    ) {
        self.track = track
        self.status = status
        self.providerLabel = providerLabel
        self.transcriptAvailable = transcriptAvailable
        self.onConnect = onConnect
        self.compact = compact
    }

    private var isSpotify: Bool { providerLabel == "SPOTIFY" }
    private var isYouTube: Bool { providerLabel == "YOUTUBE" }

    private var statusSymbol: String {
        if isYouTube, status == .unavailable, transcriptAvailable { return "captions.bubble" }
        switch status {
        case .authorizing, .loading: return "arrow.triangle.2.circlepath"
        case .empty: return "music.note.list"
        case .unavailable: return "music.note"
        case .needsClientID, .disconnected, .error: return "link"
        case .ready: return "checkmark.circle"
        }
    }

    private var showsConnectButton: Bool {
        isSpotify && (status == .needsClientID || status == .disconnected || status == .error)
    }

    var body: some View {
        Group {
            if compact {
                compactBody
            } else {
                regularBody
            }
        }
    }

    private var regularBody: some View {
        VStack(alignment: .leading, spacing: Spacing.none) {
            HStack(spacing: Spacing.tight) {
                Image(systemName: "forward.fill")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.accent)
                Spacer(minLength: 0)
                Image(systemName: "rectangle.2.swap")
                    .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                    .foregroundStyle(Theme.muted)
            }
            .frame(height: 16)

            if let track {
                VStack(alignment: .leading, spacing: Spacing.tight) {
                    Text(track.title)
                        .font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(3)
                        .fixedSize(horizontal: false, vertical: true)
                    Text(track.artist)
                        .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                        .foregroundStyle(Theme.muted)
                        .lineLimit(2)
                    Spacer(minLength: 0)
                }
                .padding(.top, Spacing.roomy)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
            } else {
                VStack(spacing: Spacing.snug) {
                    Spacer(minLength: 0)
                    if status == .authorizing || status == .loading {
                        ProgressView()
                            .controlSize(.small)
                            .tint(Theme.accent)
                    } else {
                        Image(systemName: statusSymbol)
                            .font(.system(size: ShellIcon.header, weight: .medium, design: .rounded))
                            .foregroundStyle(Theme.accent)
                    }
                    if showsConnectButton {
                        Button(action: onConnect) {
                            Text(status == .needsClientID ? "ADD CLIENT ID" : "Connect")
                                .font(.system(size: ShellTypography.nano, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.nano)))
                                .foregroundStyle(Theme.onAccent)
                                .frame(maxWidth: .infinity)
                                .frame(height: 22)
                                .background(Theme.accent, in: Capsule())
                        }
                        .buttonStyle(.plain)
                    }
                    Spacer(minLength: 0)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
        .padding(Spacing.base)
        .frame(width: 136, height: 170, alignment: .topLeading)
    }

    private var compactBody: some View {
        HStack(alignment: .top, spacing: Spacing.base) {
            Image(systemName: "forward.fill")
                .font(.system(size: ShellIcon.small, weight: .semibold, design: .rounded))
                .foregroundStyle(Theme.accent)
                .frame(width: 18)

            VStack(alignment: .leading, spacing: Spacing.tight) {
                if let track {
                    Text(track.title)
                        .font(.system(size: ShellTypography.cardTitle, weight: .semibold, design: .rounded))
                        .foregroundStyle(Theme.bright)
                        .lineLimit(2)
                        .minimumScaleFactor(0.78)
                    Text(track.artist.isEmpty ? track.kind : track.artist)
                        .font(.system(size: ShellTypography.micro, weight: .medium, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                        .foregroundStyle(Theme.muted)
                        .lineLimit(1)
                } else {
                    if showsConnectButton {
                        Button(action: onConnect) {
                            Text(status == .needsClientID ? "ADD CLIENT ID" : "CONNECT")
                                .font(.system(size: ShellTypography.micro, weight: .semibold, design: ShellTypography.preferredDesign(for: ShellTypography.micro)))
                                .foregroundStyle(Theme.onAccent)
                                .frame(maxWidth: .infinity)
                                .frame(height: 22)
                                .background(Theme.accent, in: Capsule())
                        }
                        .buttonStyle(.plain)
                    } else if status == .authorizing || status == .loading {
                        ProgressView()
                            .controlSize(.small)
                            .tint(Theme.accent)
                    }
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(Spacing.base)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
}

private struct LyricsSlot: View {
    @ObservedObject var model: ShellModel
    @State private var showsNext = false
    @State private var representedTrackKey = ""
    @State private var manualFaceKey: String?
    @State private var pendingTrackReset = false
    @State private var faceAnimationGeneration = 0
    @State private var faceAnimationActive = false

    private let faceFlipDuration: TimeInterval = 0.52

    private var trackKey: String {
        let provider = MediaProvider.resolve(model.media)
        return "\(provider.cacheKey)|\(model.media.mediaURL)|\(model.media.title)|\(model.media.artist)|\(model.media.album)|\(Int(model.media.duration.rounded()))"
    }

    private var provider: MediaProvider {
        MediaProvider.resolve(model.media)
    }

    private var isSpotifyMedia: Bool {
        provider == .spotify
    }

    private var hasNextFace: Bool {
        isSpotifyMedia || model.media.upNext != nil
    }

    private var nextTrack: MediaNextItem? {
        isSpotifyMedia ? model.spotifyNextTrack : model.media.upNext
    }

    private var nextStatus: SpotifyQueueStatus {
        isSpotifyMedia
            ? model.spotifyQueueStatus
            : (model.media.upNext == nil ? .unavailable : .ready)
    }

    private var nextProviderLabel: String {
        provider.label
    }

    private func synchronizeFace() {
        let key = trackKey
        if representedTrackKey != key {
            representedTrackKey = key
            manualFaceKey = nil
            pendingTrackReset = true
            // A track change owns the face now. Cancel any old flip rather
            // than letting its completion callback land on the new track.
            faceAnimationGeneration &+= 1
            faceAnimationActive = false
        }
        guard !model.companionLyrics.loading else { return }
        guard manualFaceKey != key else { return }
        // Spotify gets the authenticated queue face. A non-Spotify source only
        // gets an up-next face when the producer actually supplied one; it must
        // never inherit Spotify's queue just because Spotify is configured.
        let shouldShowNext = hasNextFace && !key.isEmpty && model.companionLyrics.lines.isEmpty
        let animate = !pendingTrackReset
        pendingTrackReset = false
        setFace(shouldShowNext, animated: animate)
    }

    private func setFace(_ next: Bool, animated: Bool) {
        guard showsNext != next else {
            if !animated { faceAnimationActive = false }
            return
        }
        faceAnimationGeneration &+= 1
        let generation = faceAnimationGeneration
        faceAnimationActive = animated

        var transaction = Transaction()
        transaction.animation = animated ? .easeInOut(duration: faceFlipDuration) : nil
        transaction.disablesAnimations = !animated
        withTransaction(transaction) {
            showsNext = next
        }

        guard animated else { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + faceFlipDuration) {
            guard generation == faceAnimationGeneration else { return }
            faceAnimationActive = false
        }
    }

    private func flipFromTap() {
        // A second click during the same 3D hand-off used to retarget the
        // rotation while the first one was still in flight. SwiftUI then
        // interpolated through both angles, which looked like an accidental
        // extra flip. Let the current hand-off settle; the next deliberate
        // tap starts from a stable face.
        guard hasNextFace, !faceAnimationActive else { return }
        manualFaceKey = trackKey
        setFace(!showsNext, animated: true)
    }

    var body: some View {
        ZStack {
            CompanionLyricsView(
                lyrics: model.companionLyrics,
                media: model.media
            )
            .opacity(showsNext ? 0 : 1)
            .rotation3DEffect(
                .degrees(showsNext ? 180 : 0),
                axis: (x: 0, y: 1, z: 0),
                perspective: 0.65
            )
            .allowsHitTesting(!showsNext)

            SpotifyNextTrackView(
                track: nextTrack,
                status: nextStatus,
                providerLabel: nextProviderLabel,
                transcriptAvailable: !model.media.transcriptURL.isEmpty,
                onConnect: model.connectSpotifyQueue
            )
            .opacity(showsNext ? 1 : 0)
            .rotation3DEffect(
                .degrees(showsNext ? 0 : -180),
                axis: (x: 0, y: 1, z: 0),
                perspective: 0.65
            )
            .allowsHitTesting(showsNext)
        }
        .frame(width: 136, height: 170)
        .contentShape(RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous))
        .onTapGesture(perform: flipFromTap)
        .onAppear { synchronizeFace() }
        .onChange(of: trackKey) { _, _ in synchronizeFace() }
        .onChange(of: model.companionLyrics.loading) { _, _ in synchronizeFace() }
        .onChange(of: model.companionLyrics.lines.isEmpty) { _, _ in synchronizeFace() }
        .onChange(of: hasNextFace) { _, _ in synchronizeFace() }
        .help(hasNextFace ? "Tap to flip between lyrics or transcript and what is queued next" : "Lyrics fallback for this media source")
        .clipShape(RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous)
                .stroke(Theme.seam.opacity(0.58), lineWidth: 0.8)
        }
        .layeredPanel(radius: Rounding.shell)
        .clipShape(RoundedRectangle(cornerRadius: Rounding.shell, style: .continuous))
    }
}

private struct DualPerformanceGauge: View {
    let title: String
    let symbol: String
    let utilization: Double
    let temperature: Double?
    @AppStorage("shellPalette") private var paletteRaw = ShellPalette.midnight.rawValue

    var body: some View {
        // Read the palette through AppStorage here rather than relying on a
        // process-global defaults lookup. Each gauge is its own animated view;
        // without a direct dependency the last gauge could retain White's
        // pale copy after the surrounding surface had already changed theme.
        let tokens = (ShellPalette(rawValue: paletteRaw) ?? .midnight).tokens
        let copy = tokens.text
        let secondary = tokens.text.opacity(0.72)
        let active = tokens.isLight ? tokens.accent : tokens.text
        let use = min(1, max(0, utilization))
        let heat = min(1, max(0, (temperature ?? 0) / 100))
        ZStack {
            if temperature == nil {
                Circle().stroke(secondary.opacity(0.14), lineWidth: 8)
                Circle().trim(from: 0, to: max(0.006, use))
                    // A gradient ending in the text colour placed a pale
                    // sliver inside the rounded leading cap. Keep the entire
                    // utilization arc in the palette accent so its cap and
                    // body render as one continuous stroke.
                    .stroke(tokens.accent, style: StrokeStyle(lineWidth: 8, lineCap: .round))
                    .rotationEffect(.degrees(-90))
                    .animation(.linear(duration: 0.45), value: use)
            } else {
                Group {
                    Circle().trim(from: 0.08, to: 0.42)
                        .stroke(secondary.opacity(0.14), style: StrokeStyle(lineWidth: 8, lineCap: .round))
                    Circle().trim(from: 0.42 - 0.34 * heat, to: 0.42)
                        .stroke(active, style: StrokeStyle(lineWidth: 8, lineCap: .round))
                        .animation(.linear(duration: 0.45), value: heat)
                    Circle().trim(from: 0.58, to: 0.92)
                        .stroke(secondary.opacity(0.14), style: StrokeStyle(lineWidth: 8, lineCap: .round))
                    Circle().trim(from: 0.58, to: 0.58 + 0.34 * use)
                        .stroke(tokens.accent, style: StrokeStyle(lineWidth: 8, lineCap: .round))
                        .animation(.linear(duration: 0.45), value: use)
                }
            }
            VStack(spacing: Spacing.hairline) {
                Image(systemName: symbol).font(.system(size: ShellIcon.large, weight: .semibold, design: .rounded)).foregroundStyle(tokens.accent)
                Text("\(performancePercent(use))%")
                    .font(.system(size: ShellDisplay.large, weight: .heavy, design: .rounded)).foregroundStyle(copy)
                Text(title).font(.system(size: ShellTypography.label, weight: .medium, design: .rounded)).foregroundStyle(secondary)
                if let temperature {
                    Text("\(Int(temperature.rounded()))°C")
                        .font(.system(size: ShellTypography.micro, weight: .bold, design: ShellTypography.preferredDesign(for: ShellTypography.micro))).foregroundStyle(active)
                }
            }
        }
        // Width, not height, is the limiting axis: four 151pt gauges plus
        // their three 10pt gaps already consume 634 of the 644pt viewport.
        // Keep the dials circular; the shorter shared plane removes almost
        // half their former vertical gutter without distorting the arcs.
        .frame(width: 137, height: 137)
        .padding(Spacing.snug)
        .layeredPanel(radius: 73)
    }
}

/// Controls the WindowServer membership of a shell-owned window.
///
/// Keep `.fullScreenAuxiliary` on the registered surface during ordinary
/// Space use. An accessory app can otherwise create a live panel that is only
/// attached to the Space active during launch. While a native fullscreen
/// Space is active, remove that flag so WindowServer excludes the shell from
/// that Space without ordering the shared panels out of every other Space.
private enum ShellFullscreenPolicy {
    case allowsNativeFullscreen
    case suppressesNativeFullscreen

    var collectionBehavior: NSWindow.CollectionBehavior {
        let shared: NSWindow.CollectionBehavior = [
            .canJoinAllSpaces, .stationary, .ignoresCycle
        ]
        switch self {
        case .allowsNativeFullscreen:
            return shared.union(.fullScreenAuxiliary)
        case .suppressesNativeFullscreen:
            return shared
        }
    }
}

private class ShellPanel: NSPanel {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }
}

/// The compact notification is physically attached to the display's top rim.
/// AppKit normally constrains a floating panel below the visible menu-bar
/// frame, which leaves this panel one measured notch depth too low even though
/// its SwiftUI content and contour are correct. Keep the same floating level
/// and shared contour ownership, but allow this one attached host to occupy
/// the physical top rim that its shape already reserves internally.
private final class TopAttachedShellPanel: ShellPanel {
    override func constrainFrameRect(_ frameRect: NSRect, to screen: NSScreen?) -> NSRect {
        frameRect
    }
}

private final class PrimaryLauncherWindow: NSWindow {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }
}

/// Keeps the SwiftUI tree at its destination size while an AppKit panel's
/// outer clip animates. Resizing the same `NSHostingView` on every display-link
/// sample can leave stale backing images; resize the host once per destination
/// and animate only the container.
private protocol DestinationHostingContainerProtocol: AnyObject {
    func setDestinationSize(_ size: CGSize)
}

private enum HostingContentAlignment {
    case topLeading
    case bottomCenter
}

private final class DestinationHostingContainer<Content: View>: NSView, DestinationHostingContainerProtocol {
    private let hostingView: NSHostingView<Content>
    private let contentAlignment: HostingContentAlignment

    init(
        rootView: Content,
        destinationSize: CGSize,
        contentAlignment: HostingContentAlignment = .topLeading
    ) {
        hostingView = NSHostingView(rootView: rootView)
        self.contentAlignment = contentAlignment
        super.init(frame: NSRect(origin: .zero, size: destinationSize))
        wantsLayer = true
        clipsToBounds = true
        layer?.masksToBounds = true
        autoresizingMask = [.width, .height]
        layer?.backgroundColor = NSColor.clear.cgColor
        hostingView.autoresizingMask = []
        // SwiftUI's host normally uses a layer-hosting policy of `.never`.
        // During the one intentional destination resize, ask AppKit to paint
        // the new backing contents instead of scaling the previous snapshot.
        // Subsequent handoff frames resize only this outer clip container.
        hostingView.layerContentsRedrawPolicy = .duringViewResize
        hostingView.layerContentsPlacement = .topLeft
        addSubview(hostingView)
        hostingView.frame = NSRect(origin: .zero, size: destinationSize)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("DestinationHostingContainer does not support NSCoder initialization")
    }

    override func layout() {
        super.layout()
        switch contentAlignment {
        case .topLeading:
            hostingView.setFrameOrigin(CGPoint(x: 0, y: bounds.height - hostingView.bounds.height))
        case .bottomCenter:
            hostingView.setFrameOrigin(CGPoint(
                x: (bounds.width - hostingView.bounds.width) / 2,
                y: 0
            ))
        }
    }

    func setDestinationSize(_ size: CGSize) {
        let safeSize = CGSize(
            width: max(1, size.width),
            height: max(1, size.height)
        )
        guard hostingView.frame.size != safeSize else { return }
        hostingView.setFrameSize(safeSize)
        hostingView.needsLayout = true
        hostingView.layoutSubtreeIfNeeded()
        hostingView.displayIfNeeded()
    }
}

// AppKit accepts only one cubic timing function, but Caelestia's emphasized
// motion is a two-segment Bezier spline. Sample the authoritative curve
// directly so window bounds and the unified frame surface never drift apart.
@MainActor private final class CaelestiaFrameAnimator: NSObject {
    private var displayLink: CADisplayLink?
    private weak var panel: NSWindow?
    private var startFrame = NSRect.zero
    private var targetFrame = NSRect.zero
    private var startedAt: CFTimeInterval = 0
    private var duration: TimeInterval = 0
    private var motion: ShellMotion = .dismiss
    private var frameChanged: ((NSRect) -> Void)?
    private var progressChanged: ((CGFloat) -> Void)?
    private var completion: (() -> Void)?

    func cancel() {
        displayLink?.invalidate()
        displayLink = nil
        panel = nil
        frameChanged = nil
        progressChanged = nil
        completion = nil
    }

    func animate(
        _ panel: NSWindow,
        to target: NSRect,
        motion: ShellMotion,
        frameChanged: ((NSRect) -> Void)? = nil,
        progressChanged: ((CGFloat) -> Void)? = nil,
        completion: (() -> Void)? = nil,
        screen: NSScreen? = nil
    ) {
        cancel()
        self.panel = panel
        startFrame = panel.frame
        targetFrame = target
        startedAt = CACurrentMediaTime()
        duration = max(0.001, motion.duration)
        self.motion = motion
        self.frameChanged = frameChanged
        self.progressChanged = progressChanged
        self.completion = completion

        // A Timer wakes at an elapsed-time target, not at a display boundary;
        // under main-thread load it can land just after a compositor commit
        // and make one geometry frame arrive late. NSWindow's display link is
        // display-synchronised and still respects the shell's 120 Hz ceiling,
        // so the same authored spline is sampled on the frame that will paint.
        // A panel that starts completely outside the display has no `screen`
        // yet, so `panel.displayLink` can fail to produce ticks. The large
        // notification sidebar intentionally begins offscreen; use its
        // owning display's link for that horizontal travel while retaining
        // the panel link for every existing on-screen surface.
        let link = (screen ?? panel.screen)?.displayLink(
            target: self,
            selector: #selector(displayLinkFired(_:))
        ) ?? panel.displayLink(target: self, selector: #selector(displayLinkFired(_:)))
        let refreshRate = shellAnimationRefreshRate(for: screen ?? panel.screen)
        link.preferredFrameRateRange = CAFrameRateRange(
            minimum: min(60, refreshRate),
            maximum: refreshRate,
            preferred: refreshRate
        )
        link.isPaused = false
        link.add(to: .main, forMode: .common)
        displayLink = link
    }

    @objc private func displayLinkFired(_ link: CADisplayLink) {
        guard let panel, displayLink === link else {
            cancel()
            return
        }
        let elapsed = CACurrentMediaTime() - startedAt
        let amount: Double
        if elapsed >= duration {
            amount = 1
        } else {
            amount = motion.curve.value(at: elapsed / duration)
        }
        let frame = NSRect(
            x: startFrame.origin.x + (targetFrame.origin.x - startFrame.origin.x) * CGFloat(amount),
            y: startFrame.origin.y + (targetFrame.origin.y - startFrame.origin.y) * CGFloat(amount),
            width: startFrame.width + (targetFrame.width - startFrame.width) * CGFloat(amount),
            height: startFrame.height + (targetFrame.height - startFrame.height) * CGFloat(amount)
        )
        // Publish the contour and placement state before asking AppKit to
        // commit the new window bounds. The old order resized the panel first,
        // then invalidated SwiftUI; for one compositor turn the clip boundary
        // and the shell border described different frames. Edge cards exposed
        // that mismatch while middle cards stayed clear of both boundaries.
        progressChanged?(CGFloat(amount))
        frameChanged?(frame)
        panel.setFrame(frame, display: true)
        guard elapsed >= duration else { return }
        let finished = completion
        displayLink?.invalidate()
        displayLink = nil
        self.panel = nil
        frameChanged = nil
        progressChanged = nil
        completion = nil
        finished?()
    }
}

/// Global mouse monitors can deliver hundreds of events per second while the
/// pointer crosses another application. Keep only the newest location and
/// schedule one main-run-loop drain, so hover logic cannot build an actor-task
/// backlog behind a fast mouse or trackpad.
private final class MacPlusPlusPointerEventCoalescer: @unchecked Sendable {
    private let lock = NSLock()
    private var pendingPoint = NSPoint.zero
    private var drainScheduled = false

    func submit(_ point: NSPoint, handler: @escaping @MainActor (NSPoint) -> Void) {
        lock.lock()
        pendingPoint = point
        guard !drainScheduled else {
            lock.unlock()
            return
        }
        drainScheduled = true
        lock.unlock()

        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.lock.lock()
            let point = self.pendingPoint
            self.drainScheduled = false
            self.lock.unlock()
            MainActor.assumeIsolated { handler(point) }
        }
    }
}

// CGEventTap callbacks are C function pointers and cannot capture state, so
// this lives at file scope. The context is retained by the event tap until
// `removeScrollEventTap()` invalidates the tap, and it only keeps a weak
// delegate reference. That makes a late callback harmless during teardown.
fileprivate final class MacPlusPlusScrollEventTapContext {
    weak var delegate: ShellDelegate?

    init(delegate: ShellDelegate) {
        self.delegate = delegate
    }
}

private enum MacPlusPlusEdgeSliderScrollTarget {
    case volume
    case brightness
}

private func macppShellScrollEventTapCallback(
    proxy: CGEventTapProxy,
    type: CGEventType,
    event: CGEvent,
    refcon: UnsafeMutableRawPointer?
) -> Unmanaged<CGEvent>? {
    // Core Graphics retains the incoming event for the duration of the
    // callback and releases the returned event after dispatch. Pass-through
    // returns the same object, so it must stay borrowed; passRetained here
    // would add an ownership claim for every unconsumed scroll event.
    guard let refcon else { return Unmanaged.passUnretained(event) }
    let context = Unmanaged<MacPlusPlusScrollEventTapContext>
        .fromOpaque(refcon)
        .takeUnretainedValue()
    guard let delegate = context.delegate else {
        return Unmanaged.passUnretained(event)
    }
    let isTerminating = MainActor.assumeIsolated { delegate.isTerminating }
    guard !isTerminating else {
        return Unmanaged.passUnretained(event)
    }
    if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
        // The system disables a tap that appears too slow or is toggled off by
        // Accessibility settings changing underfoot. Re-arm it immediately so a
        // transient hiccup doesn't permanently silence scroll for the rest of
        // the session.
        MainActor.assumeIsolated { delegate.reenableScrollEventTapIfNeeded() }
        return Unmanaged.passUnretained(event)
    }
    if type == .flagsChanged {
        MainActor.assumeIsolated { delegate.handleFullscreenShellRevealFlags(event.flags) }
        return Unmanaged.passUnretained(event)
    }
    guard type == .scrollWheel, let nsEvent = NSEvent(cgEvent: event) else {
        return Unmanaged.passUnretained(event)
    }
    // The tap's run-loop source is installed on the main run loop
    // (installScrollEventTap adds it to CFRunLoopGetCurrent() during
    // applicationDidFinishLaunching), so this callback already runs on the
    // main thread. Hopping through `Task { @MainActor in ... }` here queued
    // one unstructured task per scroll tick -- a fast trackpad gesture can
    // fire 60-120 of these a second, and the queue drains slightly slower
    // than it fills, so the rail's response visibly lagged behind the
    // gesture and kept lagging further behind for a moment after it ended.
    // Calling straight through removes that queue entirely. The handler also
    // tells us whether the edge slider owns the event; only that case is
    // consumed, while ordinary scrolling keeps its original event.
    let consumed = MainActor.assumeIsolated {
        delegate.handleRailScroll(
            nsEvent,
            // `rightPanel.frame` and NSScreen frames use AppKit's global
            // coordinate system. `CGEvent.location` is in Quartz's flipped
            // global display coordinates, so comparing it directly puts the
            // scroll hit test at the mirrored vertical position (volume and
            // brightness can miss or target the opposite slider).
            at: NSPoint(x: event.unflippedLocation.x, y: event.unflippedLocation.y)
        )
    }
    return consumed ? nil : Unmanaged.passUnretained(event)
}

@MainActor private final class ShellDelegate: NSObject, NSApplicationDelegate {
