    var notificationPreviousSelectedTab: Int?
    var notificationSessionLocked = currentNotificationSessionLockState() ?? false
    var notificationOutsideGlobalMouseMonitor: Any?
    var notificationOutsideLocalMouseMonitor: Any?
    var sidebarWindow: NSPanel?
