    let railFrameAnimator = CaelestiaFrameAnimator()
    var railPopoverTransitionGeneration = 0
    var deferredRailPopoverSwitch: DispatchWorkItem?
    // The requested destination is separate from the display-link's current
    // frame. Observers can publish several samples while a popout is moving;
    // comparing against the transient frame would restart the same animation
    // on every sample.
    var railPopoverTargetFrame: NSRect?
    var topCloseTimer: Timer?
    var rightCloseTimer: Timer?
    var paletteRefreshWorkItem: DispatchWorkItem?
    var paletteRefreshGeneration = 0
    var globalMouseMonitor: Any?
    var localMouseMonitor: Any?
    private let globalPointerCoalescer = MacPlusPlusPointerEventCoalescer()
    private var passiveWorkspaceDragWindowID: Int?
    private var passiveWorkspaceDragExpiryTimer: Timer?
    private var passiveWorkspaceDragPollTimer: Timer?
    private var passiveWorkspaceDragHasMoved = false
    private var passiveWorkspaceDragGlobalMonitor: Any?
    private var passiveWorkspaceDragLocalMonitor: Any?
    fileprivate var scrollEventTap: CFMachPort?
    var scrollEventRunLoopSource: CFRunLoopSource?
    private var scrollEventTapContext: UnsafeMutableRawPointer?
    private var localScrollMonitor: Any?
    private var globalScrollMonitor: Any?
    private var globalInteractionTrustPollTimer: Timer?
    let model = ShellModel(liveData: true)

    /// Test whether the persistent shell surfaces have a WindowServer surface
    /// on the currently active desktop. This is intentionally only a post-
    /// commit check: a panel can look on-screen in the launch Space before
    /// WindowServer has committed its all-Spaces membership.
    private func currentOnscreenWindowNumbers() -> Set<Int> {
        guard let rows = CGWindowListCopyWindowInfo(
            [.optionOnScreenOnly],
            kCGNullWindowID
        ) as? [[String: Any]] else { return [] }
        return Set(rows.compactMap { row in
            (row[kCGWindowNumber as String] as? NSNumber)?.intValue
        })
    }

    private func shellPersistentWindowsAreOnscreen() -> Bool {
        guard !windows.isEmpty else { return false }
        let onscreenWindowNumbers = currentOnscreenWindowNumbers()
        return windows.allSatisfy {
            $0.windowNumber > 0 && onscreenWindowNumbers.contains($0.windowNumber)
        }
    }

    /// Space changes can briefly publish the existing shell windows as
    /// off-screen even though their all-Spaces membership is already correct.
    /// Only re-front a panel when WindowServer actually dropped its surface;
    /// repeatedly calling `orderFrontRegardless()` for an already visible
    /// non-activating panel can make the user's focused app flash during the
    /// handoff.
    private func frontShellPanelIfNeeded(
        _ panel: NSWindow,
        onscreenWindowNumbers: inout Set<Int>
    ) {
        let number = panel.windowNumber
        guard !panel.isVisible || number <= 0 || !onscreenWindowNumbers.contains(number) else { return }
        panel.orderFrontRegardless()
        if panel.windowNumber > 0 {
            onscreenWindowNumbers.insert(panel.windowNumber)
        }
    }

    /// Pause, rather than complete, the registration transaction when startup
    /// or native fullscreen takes ownership of the compositor boundary. The
    /// required flag remains set so the next safe boundary can retry it.
    private func pauseShellSpaceRegistration() {
        guard shellSpaceRegistrationPending else { return }
        shellSpaceRegistrationWorkItem?.cancel()
        shellSpaceRegistrationWorkItem = nil
        shellSpaceRegistrationPending = false
        shellSpaceRegistrationAttempts = 0
        shellSpaceCommitAttempts = 0

        let returnApplication = shellSpaceReturnApplication
        shellSpaceReturnApplication = nil
        let ownPID = ProcessInfo.processInfo.processIdentifier
        guard let returnApplication,
              !returnApplication.isTerminated,
              returnApplication.processIdentifier != ownPID,
              NSWorkspace.shared.frontmostApplication?.processIdentifier == ownPID else { return }
        _ = returnApplication.activate(options: [])
    }

    /// An LSUIElement can create a live borderless panel before AppKit has
    /// committed its `.canJoinAllSpaces` behavior. The panel then remains
    /// attached to the Space that happened to be active during launch even
    /// though `collectionBehavior` reports the right flags. One bounded
    /// activation/ordering transaction makes WindowServer commit the existing
    /// surfaces to every Space. The user's frontmost app is restored when the
    /// transaction is complete, so a shell rebuild never leaves focus behind.
    private func requestShellSpaceRegistration() {
        guard shellSpaceRegistrationRequired,
              !windows.isEmpty,
              !startupSurfaceGateActive,
              !nativeFullscreenShellQuietMode,
              !shellSpaceRegistrationPending else { return }

        shellSpaceRegistrationGeneration &+= 1
        let generation = shellSpaceRegistrationGeneration
        shellSpaceRegistrationPending = true
        shellSpaceRegistrationAttempts = 0
        shellSpaceCommitAttempts = 0
        shellSpaceRegistrationWorkItem?.cancel()

        let ownPID = ProcessInfo.processInfo.processIdentifier
        if let frontmost = NSWorkspace.shared.frontmostApplication,
           frontmost.processIdentifier != ownPID {
            shellSpaceReturnApplication = frontmost
        }
        DispatchQueue.main.async { [weak self] in
            self?.beginShellSpaceRegistration(generation: generation)
        }
    }

    private func beginShellSpaceRegistration(generation: UInt) {
        guard shellSpaceRegistrationPending,
              shellSpaceRegistrationRequired,
              generation == shellSpaceRegistrationGeneration else { return }
        guard !startupSurfaceGateActive,
              !nativeFullscreenShellQuietMode else {
            pauseShellSpaceRegistration()
            return
        }
        guard !NSApp.isActive else {
            commitShellPanelsToSpaces(generation: generation)
            return
        }

        shellSpaceRegistrationAttempts += 1
        guard shellSpaceRegistrationAttempts <= 2 else {
            finishShellSpaceRegistration(generation: generation)
            return
        }

        scheduleShellSpaceRegistration(after: 0.35) { [weak self] in
            guard let self,
                  self.shellSpaceRegistrationPending,
                  generation == self.shellSpaceRegistrationGeneration else { return }
            if self.startupSurfaceGateActive || self.nativeFullscreenShellQuietMode {
                self.pauseShellSpaceRegistration()
                return
            }
            if self.shellSpaceRegistrationAttempts < 2 && !NSApp.isActive {
                self.beginShellSpaceRegistration(generation: generation)
            } else {
                self.commitShellPanelsToSpaces(generation: generation)
            }
        }
        NSApp.activate(ignoringOtherApps: true)
    }

    private func commitShellPanelsToSpaces(generation: UInt) {
        guard shellSpaceRegistrationPending,
              shellSpaceRegistrationRequired,
              generation == shellSpaceRegistrationGeneration else { return }
        guard !startupSurfaceGateActive,
              !nativeFullscreenShellQuietMode else {
            pauseShellSpaceRegistration()
            return
        }
        guard NSApp.isActive else {
            if shellSpaceRegistrationAttempts < 2 {
                beginShellSpaceRegistration(generation: generation)
            }
            return
        }

        shellSpaceRegistrationWorkItem?.cancel()
        shellSpaceCommitAttempts += 1
        let behavior = ShellFullscreenPolicy.allowsNativeFullscreen.collectionBehavior
        windows.forEach { panel in
            panel.orderOut(nil)
            panel.collectionBehavior = behavior
            panel.orderFrontRegardless()
        }
        mediaMarqueeWindows.forEach { item in
            item.panel.collectionBehavior = behavior
            if item.panel.isVisible {
                item.panel.orderFrontRegardless()
            }
        }
        if let menuMaskWindow,
           model.menuMaskEnabled,
           !startupSurfaceGateActive {
            menuMaskWindow.collectionBehavior = behavior
            menuMaskWindow.orderFrontRegardless()
        }
        // The persistent frame is registered before transient panels so the
        // shell can join every Space as one unit. Re-front any surface that
        // was already visible while that transaction was in flight; otherwise
        // a launcher or popout opened during registration remains underneath
        // the newly-fronted opaque frame fill and appears empty. Keep the
        // contour window's existing higher level untouched.
        let transientPanels: [NSWindow] = [
            drawerWindow,
            powerWindow,
            railPopoverWindow,
            notificationMockupWindow,
            sidebarWindow,
            stateToastWindow,
            launcherWindow
        ].compactMap { $0 }
            + Array(topWindowsByDisplay.values)
            + Array(rightWindowsByDisplay.values)
        transientPanels.forEach { panel in
            guard panel.isVisible else { return }
            panel.collectionBehavior = behavior
            panel.orderFrontRegardless()
        }
        NSApp.updateWindows()

        if shellPersistentWindowsAreOnscreen() || shellSpaceCommitAttempts >= 2 {
            finishShellSpaceRegistration(generation: generation)
            return
        }
        scheduleShellSpaceRegistration(after: 0.10) { [weak self] in
            guard let self,
                  self.shellSpaceRegistrationPending,
                  generation == self.shellSpaceRegistrationGeneration else { return }
            self.commitShellPanelsToSpaces(generation: generation)
        }
    }

    private func scheduleShellSpaceRegistration(
        after delay: TimeInterval,
        _ operation: @escaping () -> Void
    ) {
        shellSpaceRegistrationWorkItem?.cancel()
        let workItem = DispatchWorkItem(block: operation)
        shellSpaceRegistrationWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    private func finishShellSpaceRegistration(generation: UInt) {
        guard generation == shellSpaceRegistrationGeneration else { return }
        shellSpaceRegistrationWorkItem?.cancel()
        shellSpaceRegistrationWorkItem = nil
        shellSpaceRegistrationPending = false
        shellSpaceRegistrationRequired = false
        shellSpaceRegistrationAttempts = 0
        shellSpaceCommitAttempts = 0

        let returnApplication = shellSpaceReturnApplication
        shellSpaceReturnApplication = nil
        let ownPID = ProcessInfo.processInfo.processIdentifier
        guard let returnApplication,
              !returnApplication.isTerminated,
              returnApplication.processIdentifier != ownPID,
              NSWorkspace.shared.frontmostApplication?.processIdentifier == ownPID else { return }
        _ = returnApplication.activate(options: [])
    }

    @objc func applicationDidBecomeActive(_ notification: Notification) {
        guard shellSpaceRegistrationPending else { return }
        shellSpaceRegistrationWorkItem?.cancel()
        commitShellPanelsToSpaces(generation: shellSpaceRegistrationGeneration)
    }

    @objc private func workspaceApplicationDidActivate(_ notification: Notification) {
        guard shellSpaceRegistrationPending,
              let application = notification.userInfo?[NSWorkspace.applicationUserInfoKey]
                as? NSRunningApplication,
              application.processIdentifier != ProcessInfo.processInfo.processIdentifier else { return }
        // If the user changes apps while the short activation handoff is in
        // flight, return to that newer choice rather than the app captured at
        // the beginning of the rebuild.
        shellSpaceReturnApplication = application
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        let launchEnvironment = ProcessInfo.processInfo.environment
        // Preview flags are used by visual QA. Requiring an explicit test session
        // keeps inherited/stale preview variables from opening test surfaces in
        // the user's production shell after an ordinary rebuild.
        let visualTestSession = launchEnvironment["MACPP_SHELL_VISUAL_TEST_SESSION"] == "1"
        if UserDefaults.standard.object(forKey: "menuMaskEnabled") != nil {
            model.menuMaskEnabled = UserDefaults.standard.bool(forKey: "menuMaskEnabled")
        }
        model.onWindowDragStart = { [weak self] windowID in
            self?.beginPassiveWorkspaceDrag(windowID)
        }
        model.onWindowDragEnd = { [weak self] in
            self?.clearPassiveWorkspaceDrag()
        }
        NSApp.setActivationPolicy(.accessory)
        if !visualTestSession {
        }
        rebuild()
        if !visualTestSession {
            startNativeFullscreenShellStatePoll()
            // Reconcile immediately as well as on the poll cadence. The shell
            // can be relaunched while the frontmost app already owns a native
            // fullscreen Space; waiting for the first 250 ms tick briefly
            // exposes the rail and its high-level children over that app.
            refreshNativeFullscreenShellPresentation(force: true)
        }
        let accessibilityActionsEnabled = UserDefaults.standard.bool(
            forKey: "org.macplusplus.setup.accessibility"
        )
        if !visualTestSession && accessibilityActionsEnabled {
            checkGlobalInteractionTrustIfNeeded()
            installEdgeMonitor()
            installPassiveWorkspaceDragMonitor()
            installScrollEventTap()
            startGlobalInteractionTrustPoll()
        }
        setSystemChromeHidden(model.menuMaskEnabled, forceDockRefresh: model.menuMaskEnabled)
        configureLauncher()
        DistributedNotificationCenter.default().addObserver(
            self,
            selector: #selector(showObservatoryFromNotification(_:)),
            name: NSNotification.Name("\(macppShellDomain).show-observatory"),
            object: nil,
            suspensionBehavior: .deliverImmediately
        )
        if visualTestSession && launchEnvironment["MACPP_SHELL_PREVIEW_LAUNCHER"] == "1" {
            showLauncher()
            if let query = launchEnvironment["MACPPCAST_INITIAL_QUERY"] { launcherModel.query = query }
        }
        if visualTestSession && launchEnvironment["MACPP_SHELL_PREVIEW_NEXUS"] == "1" {
            if let rawPage = launchEnvironment["MACPP_NEXUS_PREVIEW_PAGE"],
               let page = MacPlusPlusNexusModel.Page(rawValue: rawPage) {
                nexusModel.page = page
            }
            showLauncher()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
                self?.launcherModel.presentNexus()
            }
        }
        if visualTestSession && launchEnvironment["MACPP_SHELL_PREVIEW_WALLPAPERS"] == "1" {
            showLauncher()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
                self?.launcherModel.presentWallpapers()
            }
        }
        if visualTestSession && launchEnvironment["MACPP_SHELL_PREVIEW_DESKTOP"] == "1" {
            showLauncher()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
                self?.launcherModel.presentDesktop()
            }
        }
        if visualTestSession && launchEnvironment["MACPP_SHELL_PREVIEW_SCREENSAVERS"] == "1" {
            showLauncher()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
                self?.launcherModel.presentScreensavers()
            }
        }
        // Every call path through ShellModel.setPalette (the rail's quick
        // switcher, the Nexus wallpaper carousel, custom colors) now
        // reaches this same refresh, instead of only the rail popover's
        // switcher remembering to trigger it. That mismatch is why
        // MacPlusPlusCast's text colors (and anything else driven off
        // launcherModel) used to stay stale after switching palette from
        // Nexus until some unrelated hover forced a redraw.
        model.onPaletteChanged = { [weak self] in self?.schedulePaletteRefresh() }
        model.onStateToast = { [weak self] event in self?.showStateToast(event) }
        if !visualTestSession && accessibilityActionsEnabled {
            installStateToastMonitors()
            installFullscreenShellRevealMonitors()
        }
        mediaMarqueeTimer = Timer.scheduledTimer(withTimeInterval: 3.0, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.updateMediaMarquees() }
        }
        mediaMarqueeTimer?.tolerance = 0.5
        if let mediaMarqueeTimer { RunLoop.main.add(mediaMarqueeTimer, forMode: .common) }
        // Drive the rail title from the published media state immediately.
        // The timer above remains only as a watchdog for window ordering.
        mediaObserver = model.$media
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                Task { @MainActor in self?.updateMediaMarquees() }
            }
        wifiObserver = Publishers.CombineLatest4(
            model.$knownNetworks.removeDuplicates(),
            model.$connectedNetwork.removeDuplicates(),
            model.$vpnName.removeDuplicates(),
            model.$wifiConnected.removeDuplicates()
        )
            .receive(on: RunLoop.main)
            .sink { [weak self] _, _, _, _ in
                Task { @MainActor in
                    self?.resizeRailPopoverIfNeeded(.wifi, force: true)
                }
            }
        bluetoothObserver = model.$bluetoothDevices
            .removeDuplicates()
            .dropFirst()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                Task { @MainActor in
                    self?.resizeRailPopoverIfNeeded(.bluetooth)
                }
            }
        sidebarQueueObserver = notificationMockupQueue.$events
            .map(\.count)
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                Task { @MainActor in self?.resizeSidebarIfNeeded() }
            }
        // Workspace snapshots arrive after the popover has already been
        // built. If a window opens in the space currently being previewed,
        // SwiftUI updates the row stack immediately, but the enclosing
        // borderless AppKit panel otherwise keeps its old height. The result
        // is a squeezed/clipped card until hover leaves and re-enters it --
        // which happens to recalculate the target size on the next open.
        // Reconcile the live panel at the same boundary as the model update
        // so the content and its host always grow together.
        workspaceObserver = model.$workspaces
            .removeDuplicates()
            .dropFirst()
            .receive(on: RunLoop.main)
            .sink { [weak self] spaces in
                Task { @MainActor in
                    guard let self,
                          let popoverKind = self.railPopoverKind,
                          case let .workspace(index) = popoverKind else { return }
                    let workspaceSnapshot = spaces.first(where: { $0.id == index })
                    self.workspacePopoverResizeGeneration &+= 1
                    let generation = self.workspacePopoverResizeGeneration
                    self.resizeRailPopoverIfNeeded(
                        .workspace(index),
                        force: true,
                        workspaceSnapshot: workspaceSnapshot
                    )
                    // The model publication and the SwiftUI layout pass are
                    // separate main-run-loop turns. The first resize handles
                    // the normal case; these two quiet retries cover the
                    // window-open case where the new row has not been
                    // measured yet. This is the same reason hovering away
                    // and back appeared to fix it, except it is now automatic
                    // and does not require a second popover construction.
                    for delay in [0.05, 0.18, 0.40] {
                        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                            guard let self,
                                  generation == self.workspacePopoverResizeGeneration,
                                  self.railPopoverKind == .workspace(index) else { return }
                            self.resizeRailPopoverIfNeeded(
                                .workspace(index),
                                force: true,
                                workspaceSnapshot: workspaceSnapshot
                            )
                        }
                    }
                }
            }
        // App cards and the shelf contain a live window inventory. Opening or
        // closing a window can update it without changing the frontmost
        // application, so keep the shared popover host in step with SwiftUI
        // while either app surface is visible.
        appRailObserver = model.$appRailApplications
            .removeDuplicates()
            .dropFirst()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                Task { @MainActor in
                    guard let self else { return }
                    if self.railPopoverKind == nil,
                       self.railHoverCandidate == .appShelf,
                       let screen = NSScreen.screens.first(where: { NSMouseInRect(NSEvent.mouseLocation, $0.frame, false) }) ?? NSScreen.main,
                       self.appShelfTriggerIsActive(at: NSEvent.mouseLocation, in: screen.frame),
                       !self.model.appRailApplications.isEmpty {
                        self.showRailPopover(.appShelf, on: screen, refreshData: false, requireLiveTrigger: false)
                        return
                    }
                    guard let popoverKind = self.railPopoverKind else { return }
                    let refresh: () -> Void
                    switch popoverKind {
                    case let .runningApp(pid):
                        refresh = { self.resizeRailPopoverIfNeeded(.runningApp(pid), force: true) }
                    case .appShelf:
                        guard !self.model.appRailApplications.isEmpty else {
                            self.closeRailPopover()
                            return
                        }
                        refresh = { self.resizeRailPopoverIfNeeded(.appShelf, force: true) }
                    default:
                        return
                    }
                    refresh()
                    // The model publication and SwiftUI row layout are
                    // separate turns. A quiet retry covers the case where a
                    // newly opened window has not been measured yet, or a
                    // newly appeared app changes the shelf width.
                    for delay in [0.05, 0.18] {
                        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                            guard let self,
                                  let popoverKind = self.railPopoverKind else { return }
                            switch popoverKind {
                            case let .runningApp(pid):
                                self.resizeRailPopoverIfNeeded(.runningApp(pid), force: true)
                            case .appShelf:
                                self.resizeRailPopoverIfNeeded(.appShelf, force: true)
                            default:
                                return
                            }
                        }
                    }
                }
            }
        if let value = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_DRAWER"], let page = Int(value), let screen = NSScreen.main {
            select(page, on: screen)
        }
        if let edge = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_EDGE"] {
            if edge == "top" { showTop(tab: 1) }
            if edge == "performance" { showTop(tab: 2) }
            if edge == "right" { showRight() }
            if edge == "power", let screen = NSScreen.main { showRailPopover(.power, on: screen) }
        }
        if let popover = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_POPOVER"], let screen = NSScreen.main {
            if popover == "shell" { showRailPopover(.shell, on: screen) }
            if popover == "wifi" { showRailPopover(.wifi, on: screen) }
            if popover == "bluetooth" { showRailPopover(.bluetooth, on: screen) }
            if popover == "audio" { showRailPopover(.audio, on: screen) }
            if popover == "battery" { showRailPopover(.battery, on: screen) }
            if popover == "media" { showRailPopover(.media, on: screen) }
            if popover == "calendar" { showRailPopover(.calendar, on: screen) }
            if popover == "active-app" { showRailPopover(.activeApp, on: screen) }
            if popover == "app-shelf" { showRailPopover(.appShelf, on: screen, requireLiveTrigger: false) }
            if popover == "power" { showRailPopover(.power, on: screen) }
            if popover == "workspace" { showRailPopover(.workspace(model.currentWorkspace), on: screen) }
        }
        // Keep the difficult connected-surface handoff inspectable without
        // relying on a second process or a synthetic mouse event. This is
        // intentionally opt-in and visual-session-only: production launches
        // never schedule a surprise popout sequence. Example:
        // `MACPP_SHELL_PREVIEW_POPOVER_SEQUENCE=wifi,power`.
        if visualTestSession,
           let rawSequence = launchEnvironment["MACPP_SHELL_PREVIEW_POPOVER_SEQUENCE"] {
            let sequence = rawSequence
                .split(separator: ",")
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
            // Keep sequence timing configurable for frame capture. A fresh
            // shell can spend several hundred milliseconds warming CoreWLAN
            // and the first SwiftUI hosting tree, so a fixed 320 ms start made
            // a close probe race the first visible card instead of exercising
            // its real dismissal. Production launches never set this hook.
            let sequenceStart = max(
                0,
                Double(launchEnvironment["MACPP_SHELL_PREVIEW_POPOVER_SEQUENCE_START"] ?? "") ?? 0.32
            )
            let sequenceStep = max(
                0.05,
                Double(launchEnvironment["MACPP_SHELL_PREVIEW_POPOVER_SEQUENCE_STEP"] ?? "")
                    ?? ShellMotion.panelSwitch.duration
            )
            for (index, name) in sequence.enumerated() {
                DispatchQueue.main.asyncAfter(deadline: .now() + sequenceStart + Double(index) * sequenceStep) { [weak self] in
                    guard let self, let screen = NSScreen.main else { return }
                    NSLog("Mac++ visual preview: %@", name)
                    switch name {
                    case "wifi": self.showRailPopover(.wifi, on: screen)
                    case "bluetooth": self.showRailPopover(.bluetooth, on: screen)
                    case "audio": self.showRailPopover(.audio, on: screen)
                    case "battery": self.showRailPopover(.battery, on: screen)
                    case "power": self.showRailPopover(.power, on: screen)
                    case "media": self.showRailPopover(.media, on: screen)
                    case "calendar": self.showRailPopover(.calendar, on: screen)
                    case "active-app": self.showRailPopover(.activeApp, on: screen)
                    case "app-shelf": self.showRailPopover(.appShelf, on: screen, requireLiveTrigger: false)
                    case "workspace": self.showRailPopover(.workspace(self.model.currentWorkspace), on: screen)
                    case "search": self.showLauncherSearch()
                    case "nexus": self.showLauncherNexus()
                    // Visual-session-only terminal states. These make the
                    // dismissal frame and the boundary handoff reproducible
                    // without synthesising a pointer event, so the contour
                    // can be inspected while the same AppKit lifecycle used
                    // in production is running.
                    case "close": self.closeRailPopover()
                    case "close-right": self.hideRight(on: screen)
                    case "close-top": self.hideTop(on: screen)
                    case "close-launcher": self.hideLauncher()
                    default: break
                    }
                }
            }
        }
        if visualTestSession,
           launchEnvironment["MACPP_SHELL_PREVIEW_NOTIFICATION"] == "1",
           let screen = NSScreen.main {
            showNotificationCaptureMockup(on: screen, pinned: true, resetQueue: true)
        }
        if visualTestSession,
           launchEnvironment["MACPP_SHELL_PREVIEW_NOTIFICATION_BUBBLE"] == "1",
           let screen = NSScreen.main {
            notificationMockupQueue.reset()
            model.notificationCount = notificationMockupQueue.events.count
            showNotificationCaptureMockup(on: screen, pinned: true)
        }
        if visualTestSession,
           launchEnvironment["MACPP_SHELL_PREVIEW_SIDEBAR"] == "1",
           let screen = NSScreen.main {
            notificationMockupQueue.reset()
            model.notificationCount = notificationMockupQueue.events.count
            showSidebar(on: screen)
        }
        if visualTestSession,
           launchEnvironment["MACPP_SHELL_PREVIEW_TOAST"] == "1" {
            showStateToast(MacPlusPlusStateToast(
                title: "Audio Output",
                detail: "Office",
                symbol: "hifispeaker.fill",
                duration: 30
            ))
        }
        NotificationCenter.default.addObserver(self, selector: #selector(rebuild), name: NSApplication.didChangeScreenParametersNotification, object: nil)
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(applicationDidBecomeActive(_:)),
            name: NSApplication.didBecomeActiveNotification,
            object: NSApp
        )
        NSWorkspace.shared.notificationCenter.addObserver(self, selector: #selector(activeSpaceChanged), name: NSWorkspace.activeSpaceDidChangeNotification, object: nil)
        NSWorkspace.shared.notificationCenter.addObserver(
            self,
            selector: #selector(workspaceApplicationDidActivate(_:)),
            name: NSWorkspace.didActivateApplicationNotification,
            object: nil
        )
        NSWorkspace.shared.notificationCenter.addObserver(
            self,
            selector: #selector(notificationSessionDidLock(_:)),
            name: NSWorkspace.sessionDidResignActiveNotification,
            object: nil
        )
        NSWorkspace.shared.notificationCenter.addObserver(
            self,
            selector: #selector(notificationSessionDidUnlock(_:)),
            name: NSWorkspace.sessionDidBecomeActiveNotification,
            object: nil
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(notificationSessionDidLock(_:)),
            name: NSNotification.Name(notificationSessionLockedNotificationName), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(notificationSessionDidUnlock(_:)),
            name: NSNotification.Name(notificationSessionUnlockedNotificationName), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(dismissSurfaces(_:)),
            name: NSNotification.Name("\(macppShellDomain).dismiss-surfaces"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(resumeEdges(_:)),
            name: NSNotification.Name("\(macppShellDomain).resume-edges"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(showLauncherFromNotification(_:)),
            name: NSNotification.Name("\(macppShellDomain).show-launcher"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(showNexusFromNotification(_:)),
            name: NSNotification.Name("\(macppShellDomain).show-nexus"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(showWallpapersFromNotification(_:)),
            name: NSNotification.Name("\(macppShellDomain).show-wallpapers"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(showStateToastFromNotification(_:)),
            name: NSNotification.Name(stateToastNotificationName), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(wallpaperPaletteChanged(_:)),
            name: NSNotification.Name("org.macplusplus.macpp-wallpaper.palette"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(wallpaperCatalogChanged(_:)),
            name: NSNotification.Name("org.macplusplus.macpp-wallpaper.catalog-changed"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(auditTopToggle(_:)),
            name: NSNotification.Name("\(macppShellDomain).audit-top-toggle"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(auditShellToggle(_:)),
            name: NSNotification.Name("\(macppShellDomain).audit-shell-toggle"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(auditPowerToggle(_:)),
            name: NSNotification.Name("\(macppShellDomain).audit-power-toggle"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(auditRightToggle(_:)),
            name: NSNotification.Name("\(macppShellDomain).audit-right-toggle"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(auditLauncherToggle(_:)),
            name: NSNotification.Name("\(macppShellDomain).audit-launcher-toggle"), object: nil,
            suspensionBehavior: .deliverImmediately
        )
        model.refreshWorkspace()
    }
    func applicationWillTerminate(_ notification: Notification) {
        // A launchd bootout or a forced process cleanup may skip this callback,
        // but graceful termination should still leave the native Dock and menu
        // bar usable for Game/Performance. The mode controller has a matching
        // shell-independent backstop for the force-kill case.
        setSystemChromeHidden(false, forceDockRefresh: true)
        isTerminating = true
        launcherModel.stop()
        if let launcherHotKey { UnregisterEventHotKey(launcherHotKey) }
        if let launcherOutsideClickMonitor { NSEvent.removeMonitor(launcherOutsideClickMonitor) }
        if let launcherOutsideLocalClickMonitor { NSEvent.removeMonitor(launcherOutsideLocalClickMonitor) }
        launcherOutsideClickMonitor = nil
        launcherOutsideLocalClickMonitor = nil
        if let passiveWorkspaceDragGlobalMonitor { NSEvent.removeMonitor(passiveWorkspaceDragGlobalMonitor) }
        if let passiveWorkspaceDragLocalMonitor { NSEvent.removeMonitor(passiveWorkspaceDragLocalMonitor) }
        passiveWorkspaceDragGlobalMonitor = nil
        passiveWorkspaceDragLocalMonitor = nil
        if let globalMouseMonitor { NSEvent.removeMonitor(globalMouseMonitor) }
        if let localMouseMonitor { NSEvent.removeMonitor(localMouseMonitor) }
        globalMouseMonitor = nil
        localMouseMonitor = nil
        passiveWorkspaceDragExpiryTimer?.invalidate()
        passiveWorkspaceDragPollTimer?.invalidate()
        mediaMarqueeTimer?.invalidate()
        mediaMarqueeTimer = nil
        notificationMockupCloseTimer?.invalidate()
        notificationFullscreenBubbleCloseTimer?.invalidate()
        notificationFullscreenStatePollTimer?.invalidate()
        nativeFullscreenShellStatePollTimer?.invalidate()
        nativeFullscreenProbeTask?.cancel()
        nativeFullscreenProbeTask = nil
        nativeFullscreenProbeNeedsRerun = false
        spaceChangeReassertWorkItem?.cancel()
        spaceChangeReassertWorkItem = nil
        stateToastCloseTimer?.invalidate()
        retirePendingShellPopovers()
        if let capsLockGlobalMonitor { NSEvent.removeMonitor(capsLockGlobalMonitor) }
        if let capsLockLocalMonitor { NSEvent.removeMonitor(capsLockLocalMonitor) }
        capsLockGlobalMonitor = nil
        capsLockLocalMonitor = nil
        if let fullscreenShellRevealGlobalMonitor { NSEvent.removeMonitor(fullscreenShellRevealGlobalMonitor) }
        if let fullscreenShellRevealLocalMonitor { NSEvent.removeMonitor(fullscreenShellRevealLocalMonitor) }
        fullscreenShellRevealGlobalMonitor = nil
        fullscreenShellRevealLocalMonitor = nil
        notificationFrameAnimator.cancel()
        sidebarFrameAnimator.cancel()
        removeNotificationOutsideClickMonitors()
        shellSpaceRegistrationWorkItem?.cancel()
        shellSpaceRegistrationWorkItem = nil
        shellSpaceRegistrationPending = false
        shellSpaceReturnApplication = nil
        workspacePopoverRefreshTimer?.invalidate()
        workspacePopoverRefreshTimer = nil
        model.setFrontAppResourceSampling(false)
        DistributedNotificationCenter.default().removeObserver(self)
        NSWorkspace.shared.notificationCenter.removeObserver(self)
        mediaObserver?.cancel()
        wifiObserver?.cancel()
        bluetoothObserver?.cancel()
        workspaceObserver?.cancel()
        appRailObserver?.cancel()
        globalInteractionTrustPollTimer?.invalidate()
        globalInteractionTrustPollTimer = nil
        removeScrollEventTap()
    }
    @objc private func activeSpaceChanged() {
        model.refreshWorkspace(forceRefresh: true)

        // Native fullscreen is implemented as a Space handoff. Start the
        // boundary probe immediately instead of waiting for the polling timer.
        // The probe schedules a delayed panel repair only if fullscreen state
        // actually changed; ordinary desktop switches do not need reordering.
        _ = refreshNativeFullscreenShellPresentation(force: true)
    }

    /// Let WindowServer settle a native-fullscreen boundary before repairing
    /// panel ordering, and coalesce multiple notifications for that handoff.
    private func scheduleSpaceChangeReassert() {
        spaceChangeReassertGeneration &+= 1
        let generation = spaceChangeReassertGeneration
        spaceChangeReassertWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            guard let self,
                  self.spaceChangeReassertGeneration == generation,
                  !self.isTerminating else { return }
            self.spaceChangeReassertWorkItem = nil
            self.reassertShellPanelsForSpaceChange()
        }
        spaceChangeReassertWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12, execute: workItem)
    }

    /// Reattach shell-owned panels after a native-fullscreen Space transition.
    ///
    /// `collectionBehavior` is the source of truth for membership, but a
    /// borderless accessory window can lose its WindowServer ordering during a
    /// normal Space handoff. Reapplying the same behavior and ordering only
    /// panels that are already visible restores the shell without reviving a
    /// dismissed popout. During fullscreen, changing auxiliary membership
    /// keeps these shared windows available in every ordinary Space.
    private func reassertShellPanelsForSpaceChange() {
        let showPersistentChrome = !nativeFullscreenShellQuietMode
        let persistentBehavior = (nativeFullscreenShellQuietMode
            ? ShellFullscreenPolicy.suppressesNativeFullscreen
            : ShellFullscreenPolicy.allowsNativeFullscreen).collectionBehavior
        let transientBehavior = (nativeFullscreenShellQuietMode
            ? ShellFullscreenPolicy.suppressesNativeFullscreen
            : ShellFullscreenPolicy.allowsNativeFullscreen).collectionBehavior
        var onscreenWindowNumbers = currentOnscreenWindowNumbers()

        windows.forEach { panel in
            panel.collectionBehavior = persistentBehavior
            if showPersistentChrome {
                frontShellPanelIfNeeded(panel, onscreenWindowNumbers: &onscreenWindowNumbers)
            }
        }
        mediaMarqueeWindows.forEach { item in
            item.panel.collectionBehavior = persistentBehavior
            if showPersistentChrome {
                frontShellPanelIfNeeded(item.panel, onscreenWindowNumbers: &onscreenWindowNumbers)
            }
        }

        topWindowsByDisplay.values.forEach { panel in
            panel.collectionBehavior = transientBehavior
            if showPersistentChrome {
                if topVisible && panel === activeTopPanel {
                    frontShellPanelIfNeeded(panel, onscreenWindowNumbers: &onscreenWindowNumbers)
                } else {
                    panel.orderOut(nil)
                }
            }
        }
        rightWindowsByDisplay.values.forEach { panel in
            panel.collectionBehavior = transientBehavior
            if showPersistentChrome {
                if rightVisible && panel === activeRightPanel {
                    frontShellPanelIfNeeded(panel, onscreenWindowNumbers: &onscreenWindowNumbers)
                } else {
                    panel.orderOut(nil)
                }
            }
        }

        let transientPanels: [NSWindow] = [
            drawerWindow,
            powerWindow,
            railPopoverWindow,
            notificationMockupWindow,
            sidebarWindow,
            stateToastWindow,
            launcherWindow
        ].compactMap { $0 }
        transientPanels.forEach { panel in
            panel.collectionBehavior = transientBehavior
            guard showPersistentChrome else { return }
            guard panel.isVisible else {
                panel.orderOut(nil)
                return
            }
            frontShellPanelIfNeeded(panel, onscreenWindowNumbers: &onscreenWindowNumbers)
        }

        retiringShellPopovers.forEach { $0.panel.orderOut(nil) }
        notificationFullscreenBubbleWindow?.collectionBehavior = [
            .fullScreenAuxiliary,
            .stationary,
            .ignoresCycle
        ]
        if nativeFullscreenShellState {
            if let bubble = notificationFullscreenBubbleWindow {
                frontShellPanelIfNeeded(bubble, onscreenWindowNumbers: &onscreenWindowNumbers)
            }
        } else {
            notificationFullscreenBubbleWindow?.orderOut(nil)
        }

        menuMaskWindow?.collectionBehavior = persistentBehavior
        if showPersistentChrome && model.menuMaskEnabled && !startupSurfaceGateActive {
            reanchorMenuMask()
        } else if showPersistentChrome || !model.menuMaskEnabled || startupSurfaceGateActive {
            menuMaskWindow?.orderOut(nil)
        }
    }

    /// Native fullscreen is deliberately quiet: shell windows lose auxiliary
    /// membership in the active fullscreen Space while remaining ordered in
    /// ordinary Spaces. This avoids hiding shared panels globally just to keep
    /// them out of one fullscreen Space. The detached notification bubble is
    /// the only auxiliary exception.
    private var nativeFullscreenShellQuietMode: Bool {
        nativeFullscreenShellState && !fullscreenShellRevealed
    }

    /// Surface entry points can race the 250 ms Space poll during the short
    /// transition into a native fullscreen Space. Refresh once at the point of
    /// interaction so a stale shell state cannot let a new popout land over
    /// the fullscreen app.
    private func fullscreenShellSurfaceRequestIsSuppressed() -> Bool {
        _ = refreshNativeFullscreenShellPresentation()
        return nativeFullscreenShellQuietMode
    }

    /// Hold Control+Option to temporarily reveal the shell while a native
    /// fullscreen Space is active. Requiring the chord avoids making ordinary
    /// Option-based text-entry shortcuts flash the shell into view.
    private var fullscreenShellRevealChordIsDown: Bool {
        let flags = NSEvent.modifierFlags
        return flags.contains(.control) && flags.contains(.option)
    }

    private func startNativeFullscreenShellStatePoll() {
        guard nativeFullscreenShellStatePollTimer == nil else { return }
        let timer = Timer(timeInterval: 0.25, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.refreshNativeFullscreenShellPresentation()
            }
        }
        timer.tolerance = 0.05
        RunLoop.main.add(timer, forMode: .common)
        nativeFullscreenShellStatePollTimer = timer
    }

    @discardableResult
    private func refreshNativeFullscreenShellPresentation(
        force: Bool = false
    ) -> Bool {
        // Visual sessions use a synthetic fullscreen response for the detached
        // notification bubble. They still need the bubble, but hiding the
        // fixture shell would make those previews non-deterministic.
        guard ProcessInfo.processInfo.environment["MACPP_SHELL_VISUAL_TEST_SESSION"] != "1" else {
            return nativeFullscreenShellState
        }

        scheduleNativeFullscreenProbe(force: force)
        // Callers that need an immediate answer use the last committed state;
        // the probe above replaces it asynchronously once WindowServer/yabai
        // has answered. Returning cached state keeps interaction paths cheap
        // and, importantly, never waits on a process from the main actor.
        return nativeFullscreenShellState
    }

    /// Reads the native-fullscreen boundary away from the Shell's main actor.
    /// `yabai -m query --spaces --space` is normally quick, but it can block
    /// behind WindowServer while Spaces are changing. Only one read is allowed
    /// at a time; repeated timer/notification requests become one follow-up
    /// probe instead of a process pile-up.
    private func scheduleNativeFullscreenProbe(
        force: Bool
    ) {
        if nativeFullscreenProbeTask != nil {
            nativeFullscreenProbeNeedsRerun = nativeFullscreenProbeNeedsRerun || force
            return
        }

        nativeFullscreenProbeTask = Task { [weak self] in
            let next = await Task.detached(priority: .userInitiated) {
                macppActiveSpaceIsNativeFullscreen(forceRefresh: force)
            }.value
            guard let self, !Task.isCancelled else { return }

            self.nativeFullscreenProbeTask = nil
            let fullscreenStateChanged = next != self.nativeFullscreenShellState
            let reveal = next && self.fullscreenShellRevealChordIsDown
            if fullscreenStateChanged
                || reveal != self.fullscreenShellRevealed {
                self.nativeFullscreenShellState = next
                self.fullscreenShellRevealed = reveal
                self.applyNativeFullscreenShellPresentation()
                self.reconcileNotificationFullscreenPresentation(knownState: next)
            }

            // Only a native-fullscreen boundary changes shared-panel Space
            // membership. Ordinary Work-to-Work switches need no delayed
            // ordering pass; re-fronting already-visible panels there can
            // steal a frame of focus from the front app.
            if fullscreenStateChanged {
                self.scheduleSpaceChangeReassert()
            }

            if self.nativeFullscreenProbeNeedsRerun {
                self.nativeFullscreenProbeNeedsRerun = false
                // The coalesced request can be the Space-change notification
                // that arrived while this probe was already running. Refresh
                // past the short poll cache before committing that destination.
                self.scheduleNativeFullscreenProbe(force: true)
            }
        }
    }

    private func applyNativeFullscreenShellPresentation() {
        if nativeFullscreenShellQuietMode {
            pauseShellSpaceRegistration()
        }
        let showPersistentChrome = !nativeFullscreenShellQuietMode
        let persistentPolicy: ShellFullscreenPolicy = nativeFullscreenShellQuietMode
            ? .suppressesNativeFullscreen
            : .allowsNativeFullscreen
        let persistentBehavior = persistentPolicy.collectionBehavior
        let transientPolicy: ShellFullscreenPolicy = nativeFullscreenShellQuietMode
            ? .suppressesNativeFullscreen
            : .allowsNativeFullscreen
        let transientBehavior = transientPolicy.collectionBehavior

        windows.forEach { panel in
            panel.collectionBehavior = persistentBehavior
            if showPersistentChrome { panel.orderFrontRegardless() }
        }

        mediaMarqueeWindows.forEach { item in
            item.panel.collectionBehavior = persistentBehavior
            if showPersistentChrome { item.panel.orderFrontRegardless() }
        }

        // Keep the desired top/right state and ordering intact while
        // fullscreen is quiet. WindowServer removes these panels from the
        // active fullscreen Space because they no longer have auxiliary
        // membership; they remain available on the ordinary Spaces.
        topWindowsByDisplay.values.forEach { panel in
            panel.collectionBehavior = transientBehavior
            if showPersistentChrome {
                if topVisible && panel === activeTopPanel {
                    panel.orderFrontRegardless()
                } else {
                    panel.orderOut(nil)
                }
            }
        }
        rightWindowsByDisplay.values.forEach { panel in
            panel.collectionBehavior = transientBehavior
            if showPersistentChrome {
                if rightVisible && panel === activeRightPanel {
                    panel.orderFrontRegardless()
                } else {
                    panel.orderOut(nil)
                }
            }
        }

        // All transient shell surfaces share the same fullscreen policy. The
        // detached notification bubble is intentionally excluded: it is the
        // one notification presentation that is allowed to exist in a native
        // fullscreen Space.
        let transientPanels: [NSWindow] = [
            drawerWindow,
            powerWindow,
            railPopoverWindow,
            notificationMockupWindow,
            sidebarWindow,
            stateToastWindow,
            launcherWindow
        ].compactMap { $0 }
        transientPanels.forEach { panel in
            panel.collectionBehavior = transientBehavior
            if showPersistentChrome { panel.orderFrontRegardless() }
        }
        // A close animation may still own an old panel for a few frames. It
        // must never reappear when the fullscreen boundary changes.
        retiringShellPopovers.forEach { $0.panel.orderOut(nil) }

        if !nativeFullscreenShellState {
            notificationFullscreenBubbleWindow?.orderOut(nil)
        } else if let bubble = notificationFullscreenBubbleWindow {
            bubble.collectionBehavior = [.fullScreenAuxiliary, .stationary, .ignoresCycle]
            bubble.orderFrontRegardless()
        }

        menuMaskWindow?.collectionBehavior = persistentBehavior
        if showPersistentChrome && model.menuMaskEnabled && !startupSurfaceGateActive {
            reanchorMenuMask()
        } else if !model.menuMaskEnabled || startupSurfaceGateActive {
            menuMaskWindow?.orderOut(nil)
        }

        if showPersistentChrome {
            updateMediaMarquees()
            if shellSpaceRegistrationRequired {
                requestShellSpaceRegistration()
            }
        }
    }

    @objc nonisolated private func notificationSessionDidLock(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self, !self.isTerminating else { return }
            self.notificationSessionLocked = true
            self.notificationMockupSurface?.redactsContent = true
            // Redaction is defensive for an in-flight render; hiding the panel
            // immediately guarantees its previous frame cannot ride the normal
            // dismissal animation over the secure session transition.
            self.notificationMockupWindow?.orderOut(nil)
            self.closeNotificationFullscreenBubble()
            self.closeNotificationCaptureMockup()
            self.closeStateToast()
        }
    }
    @objc nonisolated private func notificationSessionDidUnlock(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self, !self.isTerminating else { return }
            self.notificationSessionLocked = false
            self.notificationMockupSurface?.redactsContent = false
        }
    }
    @objc nonisolated private func dismissSurfaces(_ notification: Notification) {
        let acknowledgementToken = notification.object as? String
        Task { @MainActor [weak self] in
            guard let self, !self.isTerminating else { return }
            self.macppcastVisible = true
            self.model.setSurfaceVisible(false)
            self.model.setReactive(false)
            // MacPlusPlusCast uses this notification as the hand-off boundary.  The
            // launcher/Nexus surface used to survive that hand-off, leaving a
            // stale window pinned above the newly opened MacPlusPlusCast view after
            // a brief shell restart.  Dismiss it as part of the same atomic
            // boundary, without touching any user apps or workspaces.
            self.closeDrawer(); self.hideTop(); self.hideRight(); self.closePower(); self.closeRailPopover()
            self.closeNotificationCaptureMockup()
            self.hideLauncher {
                if let acknowledgementToken {
                    acknowledgeMacppSurfaceDismissal(acknowledgementToken)
                }
            }
        }
    }

    private func resolvedNotificationBundleID(appName: String) -> String {
        let cleaned = cleanedNotificationText(appName, limit: 80)
        guard !cleaned.isEmpty, cleaned != "Notification" else { return "" }
        if let running = NSWorkspace.shared.runningApplications.first(where: {
            $0.localizedName?.localizedCaseInsensitiveCompare(cleaned) == .orderedSame
        }), let bundleID = running.bundleIdentifier {
            return bundleID
        }
        let commonApplications = [
            "App Store": "com.apple.AppStore",
            "Calendar": "com.apple.iCal",
            "Discord": "com.hnc.discord",
            "Discord Helper": "com.hnc.discord",
            "Discord Canary": "com.hnc.discord",
            "FaceTime": "com.apple.FaceTime",
            "Mail": "com.apple.mail",
            "Messages": "com.apple.MobileSMS",
            "Safari": "com.apple.Safari",
            "Script Editor": "com.apple.ScriptEditor2",
            "System Settings": "com.apple.systempreferences",
        ]
        return commonApplications.first(where: {
            $0.key.localizedCaseInsensitiveCompare(cleaned) == .orderedSame
        })?.value ?? ""
    }

    private func cleanedNotificationText(_ raw: String, limit: Int) -> String {
        let withoutControls = raw.components(separatedBy: .controlCharacters).joined(separator: " ")
        return String(withoutControls.trimmingCharacters(in: .whitespacesAndNewlines).prefix(limit))
    }

    private func notificationComparisonText(_ raw: String) -> String {
        raw
            .replacingOccurrences(of: "…", with: "...")
            .replacingOccurrences(of: "\u{200B}", with: "")
            .replacingOccurrences(of: "\u{FEFF}", with: "")
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private func resolvedNotificationAppName(bundleID: String, suppliedName: String) -> String {
        let cleanedName = cleanedNotificationText(suppliedName, limit: 80)
        if !cleanedName.isEmpty, cleanedName != bundleID { return cleanedName }
        if !bundleID.isEmpty,
           let applicationURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID),
           let bundle = Bundle(url: applicationURL) {
            for key in ["CFBundleDisplayName", "CFBundleName"] {
                if let value = bundle.object(forInfoDictionaryKey: key) as? String {
                    let candidate = cleanedNotificationText(value, limit: 80)
                    if !candidate.isEmpty { return candidate }
                }
            }
        }
        return bundleID.isEmpty ? "Notification" : bundleID
    }

    private func normalizedNotificationCaptureEvent(
        id: String,
        revision: String,
        appBundleID: String,
        appName: String,
        title: String,
        subtitle: String,
        body: String,
        timestamp: Date,
        source: String
    ) -> NotificationCaptureFixture? {
        let eventID = cleanedNotificationText(id, limit: 512)
        let eventRevision = cleanedNotificationText(revision, limit: 128)
        let rawBundleID = cleanedNotificationText(appBundleID, limit: 255)
        let allowedBundleCharacters = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: ".-"))
        let bundleID = rawBundleID.unicodeScalars.allSatisfy(allowedBundleCharacters.contains)
            ? rawBundleID : ""
        let cleanTitle = cleanedNotificationText(title, limit: 160)
        let cleanSubtitle = cleanedNotificationText(subtitle, limit: 160)
        let cleanBody = cleanedNotificationText(body, limit: 1_000)
        guard !cleanTitle.isEmpty || !cleanSubtitle.isEmpty || !cleanBody.isEmpty else { return nil }
        let resolvedName = resolvedNotificationAppName(bundleID: bundleID, suppliedName: appName)
        let acceptedTimestamp = abs(timestamp.timeIntervalSinceNow) <= 7 * 24 * 60 * 60
            ? timestamp : Date()
        return NotificationCaptureFixture(
            id: eventID.isEmpty ? UUID().uuidString : eventID,
            revision: eventRevision,
            appBundleID: bundleID,
            appName: resolvedName,
            icon: "bell.fill",
            title: cleanTitle.isEmpty ? (cleanSubtitle.isEmpty ? resolvedName : cleanSubtitle) : cleanTitle,
            subtitle: cleanSubtitle,
            body: cleanBody,
            timestamp: acceptedTimestamp,
            destination: bundleID,
            actions: bundleID.isEmpty ? [] : ["open"],
            sensitive: false,
            source: source
        )
    }

    @discardableResult
    private func ingestNotificationCaptureEvent(_ event: NotificationCaptureFixture) -> Bool {
        // A transient banner reaches Accessibility several seconds before its
        // usernoted row is committed. When the authoritative DB version later
        // arrives, replace the matching AX card in place instead of stacking a
        // duplicate; the DB event carries the durable ID and launchable bundle.
        if event.source == "usernoted-db" {
            let eventTitle = notificationComparisonText(event.title)
            let eventBody = notificationComparisonText(event.body)
            let eventSubtitle = notificationComparisonText(event.subtitle)
            let accessibilityDuplicate = notificationMockupQueue.events.filter {
                $0.source == "notificationcenter-ax"
                    && notificationComparisonText($0.title) == eventTitle
                    && notificationComparisonText($0.body) == eventBody
                    && (
                        (!$0.appBundleID.isEmpty && !event.appBundleID.isEmpty
                            && $0.appBundleID.localizedCaseInsensitiveCompare(event.appBundleID) == .orderedSame)
                        || $0.appName.localizedCaseInsensitiveCompare(event.appName) == .orderedSame
                    )
                    && abs($0.timestamp.timeIntervalSince(event.timestamp)) <= 30
            }.min(by: { first, second in
                // Identical notifications can legitimately arrive close
                // together. Prefer a matching subtitle, then the nearest AX
                // presentation time, instead of deleting the first candidate.
                let firstSubtitleMismatch = notificationComparisonText(first.subtitle) != eventSubtitle
                let secondSubtitleMismatch = notificationComparisonText(second.subtitle) != eventSubtitle
                if firstSubtitleMismatch != secondSubtitleMismatch {
                    return !firstSubtitleMismatch
                }
                return abs(first.timestamp.timeIntervalSince(event.timestamp))
                    < abs(second.timestamp.timeIntervalSince(event.timestamp))
            })
            if let accessibilityDuplicate {
                notificationMockupQueue.remove(
                    id: accessibilityDuplicate.id,
                    revision: accessibilityDuplicate.revision
                )
            }
        }
        _ = notificationMockupQueue.enqueue(event)
        model.notificationCount = notificationMockupQueue.events.count
        // A new arrival always returns the compact card to its quiet, latest
        // notification state. If the pointer is already over the surface,
        // its hover still explicitly owns the recent-stack preview.
        notificationMockupSurface?.previewExpanded = notificationPanelHovered
        if let locked = currentNotificationSessionLockState() {
            notificationSessionLocked = locked
        }
        if notificationSessionLocked {
            notificationMockupSurface?.redactsContent = true
            notificationMockupWindow?.orderOut(nil)
            closeNotificationCaptureMockup()
            return true
        }
        // Keep the queue and count current during login, but do not create a
        // compact card or expand a sidebar while WindowServer is still
        // publishing the shell's final frame. The user can open the queued
        // notifications after the startup gate releases.
        if startupSurfaceGateActive { return true }
        guard let screen = NSScreen.main ?? primaryDisplay() else { return false }
        // A live delivery is the one notification exception to popout
        // exclusivity: let it appear without dismissing the surface the user
        // is currently reading.
        showNotificationCaptureMockup(
            on: screen,
            pinned: false,
            seedFixtures: false,
            preserveExistingPopouts: true
        )
        return true
    }

    private func clearAllNotificationCaptureQueue() {
        notificationMockupQueue.clear()
        model.notificationCount = 0
        closeNotificationCaptureMockup()
    }

    @objc nonisolated private func wallpaperPaletteChanged(_ notification: Notification) {
        guard let info = notification.userInfo,
              let name = info["name"] as? String else { return }
        if name != "custom", let palette = ShellPalette(rawValue: name), palette != .custom,
           info["wallpaper"] == nil {
            Task { @MainActor [weak self] in
                guard let self, self.model.selectedPalette != palette else { return }
                self.model.setPalette(palette)
            }
            return
        }
        guard name == "custom", let path = info["wallpaper"] as? String else { return }
        let colors = PaletteRole.allCases.reduce(into: [String: String]()) { result, role in
            if let value = info[role.rawValue] as? String { result[role.rawValue] = value }
        }
        guard colors.count == PaletteRole.allCases.count else { return }
        Task { @MainActor [weak self] in
            self?.model.applyGeneratedWallpaperPalette(colors, for: URL(fileURLWithPath: path))
        }
    }
    @objc nonisolated private func wallpaperCatalogChanged(_ notification: Notification) {
        let path = notification.userInfo?["path"] as? String
        Task { @MainActor in
            NotificationCenter.default.post(
                name: macppWallpaperCatalogChangedNotification,
                object: nil,
                userInfo: path.map { ["path": $0] }
            )
        }
    }
    @objc nonisolated private func resumeEdges(_ notification: Notification) {
        Task { @MainActor [weak self] in self?.macppcastVisible = false }
    }
    @objc nonisolated private func showLauncherFromNotification(_ notification: Notification) {
        Task { @MainActor [weak self] in self?.showLauncher() }
    }
    @objc nonisolated private func showNexusFromNotification(_ notification: Notification) {
        Task { @MainActor [weak self] in self?.showLauncherNexus() }
    }

    @objc nonisolated private func showObservatoryFromNotification(_ notification: Notification) {
        Task { @MainActor [weak self] in self?.showLauncherObservatory() }
    }
    @objc nonisolated private func auditTopToggle(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self else { return }
            self.topVisible ? self.hideTop() : self.showTop(tab: self.model.topTab)
        }
    }
    @objc nonisolated private func auditShellToggle(_ notification: Notification) {
        // Keep the legacy toggle notification useful, but route it to the
        // same direct Nexus surface as the rail logo instead of reviving the
        // retired shell-controls popout.
        Task { @MainActor [weak self] in self?.showLauncherNexus() }
    }
    @objc nonisolated private func auditPowerToggle(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self, let screen = NSScreen.main else { return }
            self.railPopoverKind == .power
                ? self.closeRailPopover()
                : self.showRailPopover(.power, on: screen, requireLiveTrigger: false)
        }
    }
    @objc nonisolated private func auditRightToggle(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self else { return }
            self.rightVisible ? self.hideRight() : self.showRight()
        }
    }
    @objc nonisolated private func auditLauncherToggle(_ notification: Notification) {
        Task { @MainActor [weak self] in
            guard let self else { return }
            if self.launcherWindow?.isVisible == true { self.hideLauncher() }
            else { self.showLauncher() }
        }
    }
    @objc func rebuild() {
        shellSpaceRegistrationWorkItem?.cancel()
        shellSpaceRegistrationWorkItem = nil
        shellSpaceRegistrationPending = false
        shellSpaceRegistrationRequired = true
        shellSpaceReturnApplication = nil
        menuMaskReanchorGeneration &+= 1
        topCloseTimer?.invalidate(); topCloseTimer = nil
        rightCloseTimer?.invalidate(); rightCloseTimer = nil
        drawerCloseTimer?.invalidate(); drawerCloseTimer = nil
        powerCloseTimer?.invalidate(); powerCloseTimer = nil
        railPopoverCloseTimer?.invalidate(); railPopoverCloseTimer = nil
        deferredRailPopoverSwitch?.cancel(); deferredRailPopoverSwitch = nil
        notificationMockupCloseTimer?.invalidate(); notificationMockupCloseTimer = nil
        notificationFullscreenBubbleCloseTimer?.invalidate(); notificationFullscreenBubbleCloseTimer = nil
        notificationFullscreenStatePollTimer?.invalidate(); notificationFullscreenStatePollTimer = nil
        sidebarCloseTimer?.invalidate(); sidebarCloseTimer = nil
        stateToastCloseTimer?.invalidate(); stateToastCloseTimer = nil
        retirePendingShellPopovers()
        stateToastGeneration &+= 1
        if let stateToastWindow { retirePanel(stateToastWindow) }
        stateToastWindow = nil
        stateToastMotion = nil
        stateToastPresentation = nil
        notificationFrameAnimator.cancel()
        sidebarFrameAnimator.cancel()
        removeNotificationOutsideClickMonitors()
        notificationMockupGeneration &+= 1
        notificationMockupTargetHeight = nil
        notificationMockupPinned = false
        notificationFreshOverlay = false
        notificationBellHovered = false
        notificationPanelHovered = false
        model.setSurfaceVisible(false)
        model.setReactive(false)
        model.setFrontAppResourceSampling(false)
        frameMotion.reset()
        externalFrameMotions.values.forEach { $0.reset() }
        externalFrameMotions.removeAll()
        topMotion.presented = false; rightMotion.presented = false
        topVisible = false
        rightVisible = false
        drawerMotion = nil; drawerFrameMotion = nil
        powerMotion = nil; powerFrameMotion = nil
        railPopoverMotion = nil; railPopoverFrameMotion = nil; railPopoverSurface = nil
        railPopoverHostingContainer = nil
        clearPresentedRailGlyph()
        railVisualStates.removeAll()
        notificationMockupMotion = nil; notificationMockupFrameMotion = nil; notificationMockupSurface = nil
        notificationFullscreenBubbleMotion = nil; notificationFullscreenBubbleSurface = nil
        notificationFullscreenBubblePinned = false
        notificationFullscreenState = false
        sidebarMotion = nil
        sidebarFrameMotion = nil
        sidebarActiveDisplayID = nil
        sidebarVisible = false
        windows.forEach { retirePanel($0) }; windows.removeAll()
        mediaMarqueeWindows.forEach { retirePanel($0.panel) }; mediaMarqueeWindows.removeAll()
        topWindowsByDisplay.values.forEach { retirePanel($0) }
        rightWindowsByDisplay.values.forEach { retirePanel($0) }
        topWindowsByDisplay.removeAll()
        rightWindowsByDisplay.removeAll()
        topMotionsByDisplay.removeAll()
        rightMotionsByDisplay.removeAll()
        topActiveDisplayID = nil
        rightActiveDisplayID = nil
        self.topWindow = nil
        self.rightWindow = nil
        if let menuMaskWindow { retirePanel(menuMaskWindow) }; self.menuMaskWindow = nil
        if let powerWindow { retirePanel(powerWindow) }; self.powerWindow = nil
        if let railPopoverWindow { retirePanel(railPopoverWindow) }; self.railPopoverWindow = nil; railPopoverTargetFrame = nil; railPopoverKind = nil
        if let notificationMockupWindow { retirePanel(notificationMockupWindow) }; self.notificationMockupWindow = nil
        if let notificationFullscreenBubbleWindow { retirePanel(notificationFullscreenBubbleWindow) }; self.notificationFullscreenBubbleWindow = nil
        if let sidebarWindow { retirePanel(sidebarWindow) }; self.sidebarWindow = nil
        railHoverOpenTimer?.invalidate(); railHoverOpenTimer = nil; railHoverCandidate = nil
        if let launcherWindow { retirePanel(launcherWindow) }; self.launcherWindow = nil
        macppcastVisible = false
        for screen in NSScreen.screens {
            let f = screen.frame
            let railVisualState = RailVisualState()
            railVisualStates[displayIdentifier(screen)] = railVisualState
            let isPrimary = isPrimaryDisplay(screen)
            let owningMotion: ShellFrameMotionState
            if isPrimary {
                owningMotion = frameMotion
                add(
                    ShellFrameFillOverlay(
                        palette: model.palettePresentation,
                        motion: frameMotion,
                        topDepth: shellTopDepth(on: screen),
                        rendersPrimaryAttachments: true
                    ),
                    frame: f,
                    ignoresMouse: true,
                    fullscreenPolicy: .allowsNativeFullscreen
                )
            } else {
                let externalMotion = ShellFrameMotionState()
                externalFrameMotions[displayIdentifier(screen)] = externalMotion
                owningMotion = externalMotion
                add(
                    ShellFrameFillOverlay(
                        palette: model.palettePresentation,
                        motion: externalMotion,
                        topDepth: shellTopDepth(on: screen),
                        rendersPrimaryAttachments: true
                    ),
                    frame: f,
                    ignoresMouse: true,
                    fullscreenPolicy: .allowsNativeFullscreen
                )
            }
            add(SideRail(model: model, visualState: railVisualState, onSelect: { [weak self] page in self?.select(page, on: screen) }, onPower: { [weak self] in self?.openPowerPopoverImmediately(on: screen) }, onOpenNexus: { [weak self] in self?.showLauncherNexus() }, onOpenSearch: { [weak self] in self?.showLauncherSearch() }, onPreviewSearch: { [weak self] in self?.showLauncherSearchPreview() }, onNexusHoverEnd: { [weak self] in self?.beginNexusHoverClose() }, onNotificationHover: { [weak self] inside in
                self?.notificationBellHoverChanged(inside)
            }, onPopover: { [weak self] kind in
                if let kind {
                    if kind == .shell, self?.railPopoverKind == .shell { self?.closeRailPopover() }
                    else { self?.showRailPopover(kind, on: screen) }
                } else { self?.scheduleRailPopoverCloseIfNeeded(on: screen) }
            }).frame(width: railWidth, height: f.height),
                frame: NSRect(x: f.minX, y: f.minY, width: railWidth, height: f.height),
                fullscreenPolicy: .allowsNativeFullscreen)
        addMediaMarquee(on: screen)
            // Contours are painted last in their own transparent, noninteractive
            // panel. This is the only window allowed to draw the physical seam,
            // so rail and popout content can no longer clip half of a stroke.
            add(
                ShellFrameContourOverlay(
                    palette: model.palettePresentation,
                    motion: owningMotion,
                    border: model.borderPresentation,
                    topDepth: shellTopDepth(on: screen),
                    rendersPrimaryAttachments: true
                ),
                frame: f,
                ignoresMouse: true,
                level: shellContourWindowLevel,
                fullscreenPolicy: .allowsNativeFullscreen
            )
        }
        for screen in NSScreen.screens {
            buildEdgePanels(on: screen)
        }
        // The first screen-parameter publication during login can expose a
        // provisional display frame. Re-anchor the independent shield after
        // WindowServer has committed the settled screen geometry as well;
        // otherwise the full-screen shell resizes while this small panel keeps
        // the provisional vertical origin and becomes a floating notch.
        scheduleMenuMaskReanchor()
        updateMediaMarquees()
        warmUpRailPopoverPipeline()
        refreshNativeFullscreenShellPresentation(force: true)
        requestShellSpaceRegistration()
    }
    // The very first rail popout after launch (or after any rebuild) has a
    // brief visible seam between the rail and the new surface that later
    // popouts don't -- ShellFrameFillOverlay's window has been alive and
    // painting since this same rebuild(), but a real popout's own NSPanel is
    // created fresh the moment it's first opened, so its NSHostingView pays
    // a one-time first-layout/first-commit cost while the fill overlay
    // window (already warm) has no such delay. Both react to the same
    // motion.progress value, so that brief lag is what shows up as a
    // momentary gap that closes once the fresh window catches up.
    // Pre-materializing a throwaway, fully transparent panel with the same
    // living-surface content right after building the real windows pays that
    // one-time cost up front, invisibly, before the user ever opens one.
    // This panel is never tracked in railPopoverWindow/railPopoverKind, so
    // it can't collide with real popover state.
    private func warmUpRailPopoverPipeline() {
        let motion = SurfaceMotionState()
        let surface = RailPopoverState(kind: .wifi)
        let panel = makePanel(frame: NSRect(x: -400, y: -400, width: 4, height: 4))
        panel.alphaValue = 0
        panel.ignoresMouseEvents = true
        panel.contentView = NSHostingView(rootView:
            RailPopoverLivingSurface(motion: motion, surface: surface) {
                Color.clear.frame(width: 4, height: 4)
            }
        )
        panel.orderFrontRegardless()
        panel.contentView?.layoutSubtreeIfNeeded()
        panel.displayIfNeeded()
        DispatchQueue.main.async {
            self.retirePanel(panel)
        }
    }
    private func frameMotion(for screen: NSScreen) -> ShellFrameMotionState {
        // Every surface's silhouette needs the rim depth of the display it is
        // actually drawn on. The shape types cannot ask -- a Shape's
        // `path(in:)` has no screen context -- so the per-screen motion state
        // carries it and stamps each descriptor. Without this, the shapes fell
        // back to the *primary* display's depth, so an external monitor beside
        // a notched MacBook was drawn with the MacBook's notch reservation
        // carved out of its top edge.
        let depth = shellTopDepth(on: screen)
        if isPrimaryDisplay(screen) {
            frameMotion.setTopDepth(depth)
            return frameMotion
        }
        let id = displayIdentifier(screen)
        if let existing = externalFrameMotions[id] {
            existing.setTopDepth(depth)
            return existing
        }
        let created = ShellFrameMotionState()
        created.setTopDepth(depth)
        externalFrameMotions[id] = created
        return created
    }

    private func addMediaMarquee(on screen: NSScreen) {
        let size = NSSize(width: 39, height: 230)
        let displayScale = max(1, screen.backingScaleFactor)
        let pixelAlignedX = ((screen.frame.minX + (railWidth - size.width) / 2) * displayScale).rounded() / displayScale
        let pixelAlignedY = ((screen.frame.midY - size.height / 2) * displayScale).rounded() / displayScale
        let frame = NSRect(
            // 60pt rail - 39pt ticker = 21pt, so the old centered origin was
            // 10.5pt. On a 1x panel that put the entire text surface between
            // columns and made the rotated title look bilinearly scaled.
            // Preserve the optical centre at HiDPI, but snap the panel to the
            // target display's device-pixel grid at every scale.
            x: pixelAlignedX,
            y: pixelAlignedY,
            width: size.width,
            height: size.height
        )
        let panel = makePanel(frame: frame, fullscreenPolicy: .allowsNativeFullscreen)
        // Keep the ticker one notch above the rail but below macOS' Dock. It
        // remains independent from sidebar popouts without floating over
        // system UI.
        panel.level = NSWindow.Level(rawValue: NSWindow.Level.floating.rawValue + 1)
        panel.ignoresMouseEvents = true
        let container = MarqueePillView(frame: NSRect(origin: .zero, size: size))
        let view = container.marquee
        panel.contentView = container
        panel.alphaValue = 0
        panel.orderOut(nil)
        mediaMarqueeWindows.append((panel, view))
    }
    private func updateMediaMarquees() {
        let state = model.media
        // A valid title is the durable media state. Spotify remains available
        // while paused, and brief Now Playing handoffs must not tear the rail
        // ticker off either display.
        let visible = !state.title.isEmpty && !nativeFullscreenShellQuietMode
        // Use the same repeated-title construction as the top media surface.
        // Short titles therefore remain continuous and long titles retain the
        // exact same bullet cadence in both orientations.
        let text = loopingMediaText(state.title, viewport: 230)
        mediaMarqueeGeneration += 1
        let generation = mediaMarqueeGeneration
        for item in mediaMarqueeWindows {
            (item.panel.contentView as? MarqueePillView)?.applyTheme()
            if visible {
                let wasVisible = item.panel.isVisible
                item.view.configure(text: text, fontSize: 11, speed: 21, vertical: true, active: true)
                item.panel.alphaValue = 1
                // Keep the independent ticker above the opaque rail window.
                // Re-ordering a nonactivating panel does not steal focus.
                item.panel.orderFrontRegardless()
                if wasVisible {
                    // A second Now Playing refresh can arrive during the
                    // delayed first reveal. Never leave an already-present
                    // ticker at the first pass' temporary zero opacity.
                    item.view.layer?.removeAllAnimations()
                    item.view.alphaValue = 1
                } else {
                    // Present the opaque pill first. Its title then reveals
                    // from the lower edge instead of flashing at mid-rail.
                    item.view.alphaValue = 0
                    item.panel.alphaValue = 1
                    item.panel.orderFrontRegardless()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.10) { [weak self] in
                        guard let self, item.panel.isVisible,
                              !self.nativeFullscreenShellQuietMode,
                              !self.model.media.title.isEmpty else { return }
                        item.view.revealFromEdge(duration: 0.24)
                        NSAnimationContext.runAnimationGroup { context in
                            context.duration = 0.18
                            context.timingFunction = ShellMotion.contentIn.appKitTiming
                            item.view.animator().alphaValue = 1
                        }
                    }
                }
            } else if item.panel.isVisible {
                NSAnimationContext.runAnimationGroup({ context in
                    context.duration = ShellMotion.contentOut.duration
                    context.timingFunction = ShellMotion.contentOut.appKitTiming
                    item.panel.animator().alphaValue = 0
                }, completionHandler: { [weak self] in
                    Task { @MainActor in
                        guard let self, self.mediaMarqueeGeneration == generation,
                              self.model.media.title.isEmpty else { return }
                        item.panel.orderOut(nil)
                    }
                })
            }
        }
    }
    private func select(_ page: Int, on screen: NSScreen) {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        // The MACPP studio is a deliberately click-locked mode. Sidebar tools
        // cannot replace it with the notch surface behind the user's back.
        guard railPopoverKind != .shell else { return }
        // Every other rail tool replaces whatever surface is showing, but the
        // launcher was the one thing nothing here dismissed -- neither this
        // method nor showTop touched it. So hovering Search (which now opens
        // Nexus) and then moving to Media or Performance left Nexus sitting on
        // screen underneath the notch panel, with both visible at once.
        // Page 1 is exempt because it *is* the launcher.
        if page != 1 { hideLauncher() }
        if page == 1 { model.open("MacPlusPlusCast"); closeDrawer(); hideTop(); hideRight(); return }
        if page == 2 { showTop(tab: 1, on: screen); return }
        if page == 3 { showTop(tab: 2, on: screen); return }
        if page == 4 {
            guard UserDefaults.standard.bool(forKey: "org.macplusplus.setup.notification-settings") else {
                model.onStateToast?(MacPlusPlusStateToast(
                    title: "Notification Settings Shortcut Is Off",
                    detail: "Enable it in Setup Manager to open macOS Notification Settings.",
                    symbol: "bell.badge"
                ))
                return
            }
            guard let url = URL(string: "x-apple.systempreferences:com.apple.Notifications-Settings.extension") else { return }
            NSWorkspace.shared.open(url)
            return
        }
        if page == 5 { showTop(tab: 0, on: screen); return }
        if drawerWindow?.identifier?.rawValue == "drawer-\(page)" { return }
        dismissOtherPopouts(
            keeping: .drawer,
            preservingFreshNotification: notificationFreshOverlay
        )
        model.setReactive(page == 2)
        let height = drawerHeight(page)
        let frame = NSRect(x: leftAttachmentOrigin(on: screen), y: screen.frame.midY - height / 2, width: sidebarWidth, height: height)
        let panel = makePanel(
            frame: frame,
            fullscreenPolicy: .allowsNativeFullscreen
        )
        let motion = SurfaceMotionState()
        panel.identifier = NSUserInterfaceItemIdentifier("drawer-\(page)")
        panel.contentView = NSHostingView(rootView:
            LivingSurface(state: motion, attachment: .left) {
                DrawerView(model: self.model, motion: motion, page: page, close: { [weak self] in self?.closeDrawer() }, hoverChanged: { [weak self] inside in
                    if inside { self?.cancelDrawerClose() } else { self?.scheduleDrawerClose(after: 0.45) }
                })
            }
        )
        panel.alphaValue = 1; panel.setFrame(frame, display: true); panel.orderFrontRegardless()
        let owningFrameMotion = frameMotion(for: screen)
        drawerWindow = panel; drawerMotion = motion; drawerFrameMotion = owningFrameMotion
        owningFrameMotion.attach(motion, attachment: .left, frame: shellLocalFrame(frame, on: screen), radius: CaelestiaParityTokens.Border.rounding)
        reveal(motion)
    }

    // MARK: Notification capture UI mockup lifecycle

    private func scheduleNotificationFullscreenStatePoll() {
        guard notificationFullscreenStatePollTimer == nil else { return }
        let timer = Timer(timeInterval: 0.35, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.reconcileNotificationFullscreenPresentation()
            }
        }
        timer.tolerance = 0.08
        RunLoop.main.add(timer, forMode: .common)
        notificationFullscreenStatePollTimer = timer
    }

    private func stopNotificationFullscreenStatePollIfIdle() {
        guard notificationMockupWindow == nil,
              !sidebarVisible,
              notificationFullscreenBubbleWindow == nil else { return }
        notificationFullscreenStatePollTimer?.invalidate()
        notificationFullscreenStatePollTimer = nil
    }

    /// Native fullscreen is a Space-level state rather than a property of the
    /// shell's own windows. Reconcile both directions so a notification that
    /// was already visible is moved into the detached bubble on entry, and the
    /// bubble disappears again when the shell becomes visible after exit.
    private func reconcileNotificationFullscreenPresentation(knownState: Bool? = nil) {
        if knownState == nil {
            // Keep the cached boundary for this pass and let the shared async
            // probe refresh it. Notification polling must never put a blocking
            // yabai read back on the main actor.
            refreshNativeFullscreenShellPresentation()
        }
        let next = knownState ?? nativeFullscreenShellState
        let needsDetachedBubble = next && nativeFullscreenShellQuietMode
        let bubbleVisibilityChanged = (notificationFullscreenBubbleWindow != nil) != needsDetachedBubble
        guard next != notificationFullscreenState || bubbleVisibilityChanged else { return }
        notificationFullscreenState = next
        guard !notificationSessionLocked else { return }

        if needsDetachedBubble {
            if notificationMockupWindow != nil {
                closeNotificationCaptureMockup()
            }
            if sidebarVisible {
                closeSidebar()
            }
            guard !notificationMockupQueue.events.isEmpty,
                  let screen = NSScreen.main ?? primaryDisplay() else { return }
            showNotificationFullscreenBubble(on: screen, pinned: false)
        } else {
            closeNotificationFullscreenBubble()
        }
    }

    private func notificationFullscreenBubbleHeight(on screen: NSScreen) -> CGFloat {
        min(
            notificationFullscreenBubbleMaximumHeight,
            max(
                notificationFullscreenBubbleMinimumHeight,
                screen.frame.height * 0.38
            )
        )
    }

    private func notificationFullscreenBubbleFrame(
        on screen: NSScreen,
        height: CGFloat
    ) -> NSRect {
        let margin = min(
            notificationFullscreenBubbleMargin,
            max(12, min(screen.frame.width, screen.frame.height) * 0.04)
        )
        return NSRect(
            x: screen.frame.maxX - notificationCaptureMockupWidth - margin,
            y: screen.frame.maxY - height - margin,
            width: notificationCaptureMockupWidth,
            height: height
        )
    }

    private func showNotificationFullscreenBubble(on screen: NSScreen, pinned: Bool) {
        guard !notificationSessionLocked, !notificationMockupQueue.events.isEmpty else { return }
        notificationFullscreenBubbleCloseTimer?.invalidate()
        notificationFullscreenBubbleCloseTimer = nil
        notificationFullscreenBubblePinned = notificationFullscreenBubblePinned || pinned

        if let panel = notificationFullscreenBubbleWindow {
            notificationFullscreenBubbleSurface?.redactsContent = notificationSessionLocked
            panel.orderFrontRegardless()
            notificationFullscreenBubbleMotion?.ensureContentReady()
            scheduleNotificationFullscreenStatePoll()
            if !notificationFullscreenBubblePinned {
                scheduleNotificationFullscreenBubbleClose(after: 5)
            }
            return
        }

        notificationFullscreenBubbleGeneration &+= 1
        let height = notificationFullscreenBubbleHeight(on: screen)
        let frame = notificationFullscreenBubbleFrame(on: screen, height: height)
        let motion = SurfaceMotionState()
        motion.presented = true
        motion.progress = 1
        motion.surfacePlacementProgress = 1
        motion.contentReady = true
        motion.contentProgress = 1
        motion.contentPlacementStable = true
        motion.setContourProgress(1)
        let surface = NotificationCaptureSurfaceState(
            frameHeight: height,
            redactsContent: notificationSessionLocked
        )
        let panel = makePanel(frame: frame)
        panel.identifier = NSUserInterfaceItemIdentifier("notification-fullscreen-bubble")
        // Keep the bubble at the same stable shell level as the ordinary
        // notification body. Its fullscreen auxiliary membership is what lets
        // it enter the native fullscreen Space; `.screenSaver` is deliberately
        // not used because that would make this surface outrank the rest of
        // the shell outside fullscreen.
        panel.level = shellWindowLevel
        panel.collectionBehavior = [.fullScreenAuxiliary, .stationary, .ignoresCycle]
        panel.hasShadow = true
        notificationFullscreenBubbleWindow = panel
        notificationFullscreenBubbleMotion = motion
        notificationFullscreenBubbleSurface = surface
        panel.contentView = NSHostingView(rootView:
            NotificationFullscreenBubbleView(
                queue: notificationMockupQueue,
                motion: motion,
                surface: surface,
                openEvent: { [weak self] event in
                    self?.openNotificationCaptureEvent(event)
                },
                clearEvent: { [weak self] event in
                    self?.clearNotificationCaptureEvent(event)
                },
                close: { [weak self] in
                    self?.closeNotificationFullscreenBubble()
                },
                hoverChanged: { [weak self] inside in
                    guard let self else { return }
                    if inside {
                        self.notificationFullscreenBubbleCloseTimer?.invalidate()
                        self.notificationFullscreenBubbleCloseTimer = nil
                    } else if !self.notificationFullscreenBubblePinned {
                        self.scheduleNotificationFullscreenBubbleClose(after: 0.8)
                    }
                }
            )
        )
        panel.orderFrontRegardless()
        scheduleNotificationFullscreenStatePoll()
        if !notificationFullscreenBubblePinned {
            scheduleNotificationFullscreenBubbleClose(after: 5)
        }
    }

    private func scheduleNotificationFullscreenBubbleClose(after delay: TimeInterval) {
        notificationFullscreenBubbleCloseTimer?.invalidate()
        notificationFullscreenBubbleCloseTimer = nil
        guard !notificationFullscreenBubblePinned else { return }
        let generation = notificationFullscreenBubbleGeneration
        notificationFullscreenBubbleCloseTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in
            Task { @MainActor in
                guard let self,
                      self.notificationFullscreenBubbleGeneration == generation,
                      !self.notificationFullscreenBubblePinned else { return }
                self.closeNotificationFullscreenBubble()
            }
        }
    }

    private func closeNotificationFullscreenBubble() {
        notificationFullscreenBubbleCloseTimer?.invalidate()
        notificationFullscreenBubbleCloseTimer = nil
        notificationFullscreenBubbleGeneration &+= 1
        notificationFullscreenBubblePinned = false
        guard let panel = notificationFullscreenBubbleWindow else {
            notificationFullscreenBubbleMotion = nil
            notificationFullscreenBubbleSurface = nil
            stopNotificationFullscreenStatePollIfIdle()
            return
        }
        notificationFullscreenBubbleWindow = nil
        notificationFullscreenBubbleMotion = nil
        notificationFullscreenBubbleSurface = nil
        retirePanel(panel)
        stopNotificationFullscreenStatePollIfIdle()
    }

    private func notificationBellHoverChanged(_ inside: Bool) {
        notificationBellHovered = inside
    }

    /// A bell click may pin the stack long enough for the pointer to travel
    /// into it, but hover remains the lifetime owner. Once neither endpoint
    /// is hovered, release that temporary pin and use the existing dismissal
    /// grace/animation rather than leaving the notification surface behind.
    private func finishNotificationHoverIfNeeded() {
        guard !notificationBellHovered, !notificationPanelHovered else { return }
        if notificationMockupPinned {
            notificationMockupPinned = false
            removeNotificationOutsideClickMonitors()
        }
        scheduleNotificationCaptureMockupClose(after: 0.8)
    }

    private func toggleNotificationCaptureMockup(on screen: NSScreen) {
        if let locked = currentNotificationSessionLockState() {
            notificationSessionLocked = locked
        }
        guard !notificationSessionLocked else {
            closeNotificationCaptureMockup()
            return
        }
        if let panel = notificationMockupWindow {
            if notificationMockupPinned {
                closeNotificationCaptureMockup()
            } else {
                // A fresh notification may have been layered over the card
                // the user was reading. Pinning is an explicit switch to the
                // notification surface, so retire that previous card before
                // making Notifications persistent.
                dismissOtherPopouts(keeping: .notification)
                notificationFreshOverlay = false
                notificationMockupPinned = true
                notificationMockupCloseTimer?.invalidate()
                notificationMockupCloseTimer = nil
                installNotificationOutsideClickMonitors()
                panel.orderFrontRegardless()
                notificationMockupMotion?.ensureContentReady()
                markNotificationTabActive()
            }
            return
        }
        showNotificationCaptureMockup(on: screen, pinned: true)
    }

    private func showNotificationCaptureMockup(
        on screen: NSScreen,
        pinned: Bool,
        resetQueue: Bool = false,
        seedFixtures: Bool = false,
        preserveExistingPopouts: Bool = false
    ) {
        guard !startupSurfaceGateActive else { return }
        notificationMockupCloseTimer?.invalidate(); notificationMockupCloseTimer = nil
        if resetQueue {
            notificationMockupQueue.reset()
            model.notificationCount = 0
        }
        else if seedFixtures { notificationMockupQueue.ensureFixtures() }
        model.notificationCount = notificationMockupQueue.events.count
        if let locked = currentNotificationSessionLockState() {
            notificationSessionLocked = locked
        }
        guard !notificationSessionLocked, !notificationMockupQueue.events.isEmpty else {
            return
        }

        // The shell-owned frame and its attached contour are intentionally
        // absent from native fullscreen Spaces. Move the same queue into the
        // detached auxiliary bubble before applying ordinary popout reuse.
        _ = refreshNativeFullscreenShellPresentation()
        let nativeFullscreenQuiet = nativeFullscreenShellQuietMode
        notificationFullscreenState = nativeFullscreenShellState
        if nativeFullscreenQuiet {
            if notificationMockupWindow != nil { closeNotificationCaptureMockup() }
            if sidebarVisible { closeSidebar() }
            showNotificationFullscreenBubble(on: screen, pinned: pinned)
            return
        }
        if notificationFullscreenBubbleWindow != nil {
            closeNotificationFullscreenBubble()
        }

        if !preserveExistingPopouts {
            dismissOtherPopouts(keeping: .notification)
            notificationFreshOverlay = false
        }

        if let panel = notificationMockupWindow {
            scheduleNotificationFullscreenStatePoll()
            if pinned {
                notificationMockupPinned = true
                installNotificationOutsideClickMonitors()
            }
            panel.orderFrontRegardless()
            notificationMockupMotion?.ensureContentReady()
            if !notificationFreshOverlay { markNotificationTabActive() }
            if !notificationMockupPinned && !notificationBellHovered {
                scheduleNotificationCaptureMockupClose(after: 5)
            }
            return
        }

        notificationMockupGeneration &+= 1
        let generation = notificationMockupGeneration
        let topDepth = shellTopDepth(on: screen)
        // The first frame is deliberately a single-card arrival. The
        // measured stack will grow only after the user hovers the surface.
        let estimatedStackHeight = CGFloat(1)
            * notificationCaptureMockupEstimatedCardHeight
        let estimatedBodyHeight = notificationContentTopGutter
            + estimatedStackHeight
            + notificationContentBottomInset
        let bodyHeight = min(
            notificationMaximumBodyHeight(on: screen, topDepth: topDepth),
            max(notificationCaptureMockupBodyHeight, estimatedBodyHeight)
        )
        let surfaceHeight = bodyHeight + topDepth
        let frame = NSRect(
            x: screen.frame.maxX - notificationCaptureMockupWidth,
            y: screen.frame.maxY - surfaceHeight,
            width: notificationCaptureMockupWidth,
            height: surfaceHeight
        )
        let panel = makePanel(frame: frame, allowsTopRimCoverage: true)
        let motion = SurfaceMotionState()
        let surface = NotificationCaptureSurfaceState(
            frameHeight: surfaceHeight,
            redactsContent: notificationSessionLocked
        )
        let owningFrameMotion = frameMotion(for: screen)
        notificationMockupWindow = panel
        notificationMockupMotion = motion
        notificationMockupFrameMotion = owningFrameMotion
        notificationMockupSurface = surface
        notificationMockupTargetHeight = surfaceHeight
        notificationMockupPinned = pinned
        notificationFreshOverlay = preserveExistingPopouts
        notificationPanelHovered = false
        panel.identifier = NSUserInterfaceItemIdentifier("notification-capture-mockup")
        // Keep the notification body at the ordinary shell popout level. The
        // shared contour window is ordered just above it, so this surface
        // follows the same border ownership and fullscreen policy as every
        // other attached popout.
        panel.level = shellWindowLevel
        panel.contentView = NSHostingView(rootView:
            LivingSurface(
                state: motion,
                attachment: .topRight,
                topDepth: topDepth,
                deformsContent: false
            ) {
                NotificationCaptureMockupView(
                    queue: self.notificationMockupQueue,
                    motion: motion,
                    surface: surface,
                    topDepth: topDepth,
                    openEvent: { [weak self] event in
                        self?.openNotificationCaptureEvent(event)
                    },
                    clearEvent: { [weak self] event in
                        self?.clearNotificationCaptureEvent(event)
                    },
                    stackHeightChanged: { [weak self, weak panel, weak motion] height in
                        guard let self, let panel, let motion else { return }
                        self.resizeNotificationCaptureMockup(
                            toStackHeight: height,
                            panel: panel,
                            motion: motion,
                            generation: generation
                        )
                    },
                    hoverChanged: { [weak self, weak motion] inside in
                        guard let self, let motion,
                              self.notificationMockupMotion === motion else { return }
                        self.notificationPanelHovered = inside
                        if inside {
                            self.notificationMockupCloseTimer?.invalidate()
                            self.notificationMockupCloseTimer = nil
                        } else {
                            self.finishNotificationHoverIfNeeded()
                        }
                    },
                    dragDown: { [weak self, weak panel] in
                        guard let self, let panel,
                              self.notificationMockupWindow === panel else { return }
                        self.expandNotificationCaptureMockupToSidebar(
                            on: panel.screen ?? screen
                        )
                    },
                    // The host now reaches the physical top rim. Keep the
                    // cards below that rim inside the correctly-placed host;
                    // moving the panel itself would put its contour back
                    // below the shell.
                    contentTopInset: topDepth
                )
            }
        )
        panel.alphaValue = 1
        panel.setFrame(frame, display: true)
        owningFrameMotion.attach(
            motion,
            attachment: .topRight,
            frame: shellLocalFrame(frame, on: screen),
            radius: notificationCornerRadius
        )
        panel.orderFrontRegardless()
        scheduleNotificationFullscreenStatePoll()
        if !notificationFreshOverlay { markNotificationTabActive() }
        // Notifications share the same bounded spatial clock as the
        // bottom-left utility. Their top-right silhouette is different, but
        // the presentation must still be contour-owned rather than a second
        // notification-specific timing path.
        reveal(motion, using: .topPopout)
        if pinned {
            installNotificationOutsideClickMonitors()
        } else if !notificationBellHovered {
            scheduleNotificationCaptureMockupClose(after: 5)
        }
    }

    /// Promote the compact notification card into the persistent sidebar in
    /// place. The existing NSPanel, motion state, and frame-motion owner stay
    /// alive; only the attachment and body are handed off on one display-link
    /// timeline. This keeps the card visible while its host grows instead of
    /// exposing the close/reopen gap from the old two-panel path.
    private func expandNotificationCaptureMockupToSidebar(on screen: NSScreen) {
        guard let panel = notificationMockupWindow,
              panel.isVisible,
              let motion = notificationMockupMotion,
              let owningFrameMotion = notificationMockupFrameMotion,
              let compactSurface = notificationMockupSurface else {
            closeNotificationCaptureMockup()
            showSidebar(on: screen)
            return
        }

        dismissOtherPopouts(keeping: .notification)
        notificationMockupCloseTimer?.invalidate()
        notificationMockupCloseTimer = nil
        notificationFrameAnimator.cancel()
        sidebarFrameAnimator.cancel()
        removeNotificationOutsideClickMonitors()

        notificationMockupGeneration &+= 1
        notificationMockupTargetHeight = nil
        notificationMockupPinned = false
        notificationFreshOverlay = false
        notificationBellHovered = false
        notificationPanelHovered = false
        sidebarCloseTimer?.invalidate()
        sidebarCloseTimer = nil

        let currentFrame = panel.frame
        let target = sidebarFrame(on: screen, eventCount: notificationMockupQueue.events.count)
        let topDepth = shellTopDepth(on: screen)
        let initialSidebarTopOffset = max(0, currentFrame.maxY - target.maxY)
        let visualSidebarPreview = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_SIDEBAR"] == "1"

        // Reclassify the same panel before installing the new root. The old
        // compact callbacks captured the previous generation and will now
        // fail their identity checks instead of trying to resize the sidebar.
        notificationMockupWindow = nil
        notificationMockupMotion = nil
        notificationMockupFrameMotion = nil
        notificationMockupSurface = nil
        sidebarWindow = panel
        sidebarMotion = motion
        sidebarFrameMotion = owningFrameMotion
        sidebarActiveDisplayID = displayIdentifier(screen)
        sidebarVisible = true
        panel.identifier = NSUserInterfaceItemIdentifier("caelestia-sidebar-\(displayIdentifier(screen))")
        // Keep the expanded notification body at the same ordinary shell
        // popout level as its compact form and Search/Nexus. The shared
        // contour window is the only layer above it and owns the border.
        panel.level = shellWindowLevel
        // Keep the expanded SwiftUI tree at its final size while AppKit grows
        // the compact window. Resizing a bare NSHostingView on every display
        // link sample makes ScrollView/LazyVStack redo layout during the
        // handoff, which is the visible stutter in the large center. The
        // outer container is the only thing that follows the animated panel;
        // its clipped child is top-aligned and already laid out for the
        // destination frame.
        let expandedRoot = LivingSurface(state: motion, attachment: .rightSidebar, deformsContent: false) {
            NotificationSidebarExpansionView(
                model: self.model,
                queue: self.notificationMockupQueue,
                motion: motion,
                compactSurface: compactSurface,
                topDepth: topDepth,
                close: { [weak self] in self?.closeSidebar() },
                openEvent: { [weak self] event in self?.openNotificationCaptureEvent(event) },
                clearEvent: { [weak self] event in self?.clearNotificationCaptureEvent(event) },
                clearAll: { [weak self] in self?.clearAllNotificationCaptureQueue() },
                hoverChanged: { [weak self] inside in
                    guard let self else { return }
                    if visualSidebarPreview { return }
                    if inside { self.cancelSidebarClose() }
                    else { self.scheduleSidebarClose() }
                }
            )
        }
        let hostingContainer = DestinationHostingContainer(
            rootView: expandedRoot,
            destinationSize: target.size
        )
        panel.contentView = hostingContainer
        hostingContainer.frame = NSRect(origin: .zero, size: currentFrame.size)
        panel.alphaValue = 1
        panel.setFrame(currentFrame, display: true)

        var stateTransaction = Transaction(animation: nil)
        stateTransaction.disablesAnimations = true
        withTransaction(stateTransaction) {
            motion.presented = true
            motion.progress = 1
            motion.surfacePlacementProgress = 1
            motion.contentReady = true
            motion.contentProgress = 1
            motion.contentPlacementStable = true
            motion.notificationHandoffTopOffset = initialSidebarTopOffset
            motion.preservesNotificationTopCurve = true
            motion.notificationTopCurveStartOffset = topDepth
            motion.notificationTopCurveFrame = shellLocalFrame(currentFrame, on: screen)
        }
        motion.setContourProgress(1)
        owningFrameMotion.attach(
            motion,
            attachment: .rightSidebar,
            frame: shellLocalFrame(currentFrame, on: screen),
            radius: shellAttachmentRadius(.rightSidebar)
        )
        let handoffGeneration = motion.beginAttachmentTransition(
            from: .topRight,
            fromTopFillet: 0,
            fromBottomFillet: 0,
            fromFrame: shellLocalFrame(currentFrame, on: screen)
        )
        // The frame animator below is the sole clock for both the host and
        // the shell-wide contour. Cancel the default handoff driver so its
        // independent start time cannot leave a one-frame shoulder behind.
        motion.setAttachmentBlend(0)
        panel.orderFrontRegardless()
        model.setSurfaceVisible(true)

        sidebarFrameAnimator.animate(
            panel,
            to: target,
            // The compact card is promoted with the same bounded spatial
            // family as every grounded shell surface. This handoff is much
            // taller than an ordinary card, so its standard-accel variant
            // gives the first frames room to establish the shoulder before
            // the sidebar takes over; the contour, body, and host still share
            // this one display-linked clock.
            motion: .notificationHandoff,
            frameChanged: { [weak self, weak panel, weak motion] current in
                guard let self, let panel, let motion,
                      self.sidebarWindow === panel,
                      self.sidebarMotion === motion else { return }
                let currentLocalFrame = self.shellLocalFrame(current, on: screen)
                owningFrameMotion.update(motion, frame: currentLocalFrame)
                var transaction = Transaction(animation: nil)
                transaction.disablesAnimations = true
                withTransaction(transaction) {
                    motion.notificationHandoffTopOffset = max(0, current.maxY - target.maxY)
                    motion.notificationTopCurveStartOffset = max(
                        0,
                        topDepth
                            + (motion.notificationTopCurveFrame?.minY ?? 0)
                            - currentLocalFrame.minY
                    )
                }
            },
            progressChanged: { [weak self, weak panel, weak motion] phase in
                guard let self, let panel, let motion,
                      self.sidebarWindow === panel,
                      self.sidebarMotion === motion else { return }
                let phase = max(0, min(1, phase))
                var transaction = Transaction(animation: nil)
                transaction.disablesAnimations = true
                withTransaction(transaction) {
                    // The full sidebar body is already staged. Its external
                    // opacity follows the shared attachment blend; keeping
                    // the content gate at its terminal value prevents a
                    // second, compounded fade.
                    motion.surfacePlacementProgress = 1
                }
                motion.setAttachmentBlend(phase)
            },
            completion: { [weak self, weak panel, weak motion] in
                guard let self, let panel, let motion,
                      self.sidebarWindow === panel,
                      self.sidebarMotion === motion else { return }
                owningFrameMotion.update(
                    motion,
                    frame: self.shellLocalFrame(target, on: screen)
                )
                motion.setAttachmentBlend(1)
                var transaction = Transaction(animation: nil)
                transaction.disablesAnimations = true
                withTransaction(transaction) {
                    motion.notificationHandoffTopOffset = 0
                    motion.notificationTopCurveStartOffset = 0
                }
                motion.finishAttachmentTransition(handoffGeneration)
                panel.contentView?.layoutSubtreeIfNeeded()
            },
            screen: screen
        )
    }

    private func notificationMaximumBodyHeight(on screen: NSScreen, topDepth: CGFloat) -> CGFloat {
        max(
            notificationCaptureMockupBodyHeight,
            min(420, screen.frame.height * 0.45 - topDepth)
        )
    }

    private func resizeNotificationCaptureMockup(
        toStackHeight stackHeight: CGFloat,
        panel: NSPanel,
        motion: SurfaceMotionState,
        generation: Int
    ) {
        guard generation == notificationMockupGeneration,
              notificationMockupWindow === panel,
              notificationMockupMotion === motion,
              let surface = notificationMockupSurface,
              let owningFrameMotion = notificationMockupFrameMotion,
              let screen = panel.screen ?? NSScreen.screens.first(where: { $0.frame.intersects(panel.frame) })
        else { return }

        let topDepth = shellTopDepth(on: screen)
        let bodyHeight = min(
            notificationMaximumBodyHeight(on: screen, topDepth: topDepth),
            max(
                notificationCaptureMockupBodyHeight,
                notificationContentTopGutter + stackHeight + notificationContentBottomInset
            )
        )
        let targetHeight = topDepth + bodyHeight
        if let currentTarget = notificationMockupTargetHeight,
           abs(currentTarget - targetHeight) <= 0.5 {
            return
        }
        notificationMockupTargetHeight = targetHeight
        let target = NSRect(
            x: screen.frame.maxX - notificationCaptureMockupWidth,
            y: screen.frame.maxY - targetHeight,
            width: notificationCaptureMockupWidth,
            height: targetHeight
        )

        // Content can change while an earlier resize is still moving. If the
        // new height matches the panel's instantaneous frame, cancel the old
        // destination and snap here so that stale animation cannot continue.
        if abs(panel.frame.height - targetHeight) <= 0.5 {
            notificationFrameAnimator.cancel()
            var transaction = Transaction(animation: nil)
            transaction.disablesAnimations = true
            withTransaction(transaction) { surface.frameHeight = targetHeight }
            panel.setFrame(target, display: true)
            owningFrameMotion.update(
                motion,
                frame: shellLocalFrame(target, on: screen)
            )
            panel.contentView?.layoutSubtreeIfNeeded()
            return
        }

        // SwiftUI measures the real card stack on the first layout pass. The
        // compact host is still hidden or guarded at that point, so correcting
        // its estimated height with a visible AppKit travel only makes the
        // notification jump and exposes the shell border for a few frames.
        // Commit the measured frame before the reveal becomes visible; later
        // queue changes use the slower notification geometry clock below.
        let isOpening = !motion.presented
            || motion.contourProgress < 0.999
            || !motion.contentPlacementStable
        if isOpening {
            notificationFrameAnimator.cancel()
            var transaction = Transaction(animation: nil)
            transaction.disablesAnimations = true
            withTransaction(transaction) { surface.frameHeight = targetHeight }
            panel.setFrame(target, display: true)
            owningFrameMotion.update(
                motion,
                frame: shellLocalFrame(target, on: screen)
            )
            panel.contentView?.layoutSubtreeIfNeeded()
            return
        }

        notificationFrameAnimator.animate(
            panel,
            to: target,
            motion: .notification,
            frameChanged: { [weak self, weak panel, weak motion, weak surface, weak screen] current in
                guard let self, let panel, let motion, let surface, let screen,
                      generation == self.notificationMockupGeneration,
                      self.notificationMockupWindow === panel,
                      self.notificationMockupMotion === motion,
                      self.notificationMockupSurface === surface else { return }
                var transaction = Transaction(animation: nil)
                transaction.disablesAnimations = true
                withTransaction(transaction) { surface.frameHeight = current.height }
                owningFrameMotion.update(
                    motion,
                    frame: self.shellLocalFrame(current, on: screen)
                )
            },
            completion: { [weak panel] in
                panel?.contentView?.layoutSubtreeIfNeeded()
            }
        )
    }

    private func openNotificationCaptureEvent(_ event: NotificationCaptureFixture) {
        let bundleID = event.destination.isEmpty ? event.appBundleID : event.destination
        guard !bundleID.isEmpty,
              let applicationURL = NSWorkspace.shared.urlForApplication(
                withBundleIdentifier: bundleID
              ) else { return }
        withAnimation(ShellMotion.contentIn.animation) {
            notificationMockupQueue.remove(id: event.id, revision: event.revision)
        }
        model.notificationCount = notificationMockupQueue.events.count
        closeNotificationCaptureMockup()
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        NSWorkspace.shared.openApplication(
            at: applicationURL,
            configuration: configuration,
            completionHandler: nil
        )
    }

    private func clearNotificationCaptureEvent(_ event: NotificationCaptureFixture) {
        withAnimation(ShellMotion.contentOut.animation) {
            notificationMockupQueue.remove(id: event.id, revision: event.revision)
        }
        model.notificationCount = notificationMockupQueue.events.count
        if notificationMockupQueue.events.isEmpty {
            closeNotificationCaptureMockup()
        }
    }

    private func scheduleNotificationCaptureMockupClose(after delay: TimeInterval) {
        notificationMockupCloseTimer?.invalidate(); notificationMockupCloseTimer = nil
        guard !notificationMockupPinned else { return }
        let generation = notificationMockupGeneration
        notificationMockupCloseTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in
            Task { @MainActor in
                guard let self,
                      self.notificationMockupGeneration == generation,
                      !self.notificationMockupPinned else { return }
                self.closeNotificationCaptureMockup()
            }
        }
    }

    private func installNotificationOutsideClickMonitors() {
        removeNotificationOutsideClickMonitors()
        let mask: NSEvent.EventTypeMask = [.leftMouseDown, .rightMouseDown]
        notificationOutsideGlobalMouseMonitor = NSEvent.addGlobalMonitorForEvents(matching: mask) { [weak self] _ in
            let point = NSEvent.mouseLocation
            Task { @MainActor in self?.handleNotificationOutsideClick(at: point) }
        }
        notificationOutsideLocalMouseMonitor = NSEvent.addLocalMonitorForEvents(matching: mask) { [weak self] event in
            let point = NSEvent.mouseLocation
            DispatchQueue.main.async { [weak self] in
                self?.handleNotificationOutsideClick(at: point)
            }
            return event
        }
    }

    private func removeNotificationOutsideClickMonitors() {
        if let notificationOutsideGlobalMouseMonitor {
            NSEvent.removeMonitor(notificationOutsideGlobalMouseMonitor)
        }
        if let notificationOutsideLocalMouseMonitor {
            NSEvent.removeMonitor(notificationOutsideLocalMouseMonitor)
        }
        notificationOutsideGlobalMouseMonitor = nil
        notificationOutsideLocalMouseMonitor = nil
    }

    private func handleNotificationOutsideClick(at point: NSPoint) {
        guard notificationMockupPinned,
              let panel = notificationMockupWindow,
              !panel.frame.contains(point) else { return }
        closeNotificationCaptureMockup()
    }

    private func markNotificationTabActive() {
        if notificationPreviousSelectedTab == nil, model.selectedTab != 4 {
            notificationPreviousSelectedTab = model.selectedTab
        }
        model.selectedTab = 4
    }

    private func restoreNotificationTab() {
        if let previous = notificationPreviousSelectedTab {
            model.selectedTab = previous
        } else if model.selectedTab == 4 {
            // Notifications opened from the bell already had the notification
            // tab selected; retain the historic behavior for that path.
            model.selectedTab = 0
        }
        notificationPreviousSelectedTab = nil
    }

    private func prepareNotificationCaptureMockupClose() -> (
        panel: NSWindow,
        motion: SurfaceMotionState?,
        frameMotion: ShellFrameMotionState?
    )? {
        notificationMockupCloseTimer?.invalidate(); notificationMockupCloseTimer = nil
        notificationFrameAnimator.cancel()
        removeNotificationOutsideClickMonitors()
        notificationMockupGeneration &+= 1
        notificationMockupTargetHeight = nil
        notificationMockupPinned = false
        notificationFreshOverlay = false
        notificationBellHovered = false
        notificationPanelHovered = false
        guard let panel = notificationMockupWindow else {
            notificationMockupSurface = nil
            restoreNotificationTab()
            return nil
        }
        let motion = notificationMockupMotion
        let owningFrameMotion = notificationMockupFrameMotion
        notificationMockupWindow = nil
        notificationMockupMotion = nil
        notificationMockupFrameMotion = nil
        notificationMockupSurface = nil
        restoreNotificationTab()
        return (panel: panel, motion: motion, frameMotion: owningFrameMotion)
    }

    private func closeNotificationCaptureMockup() {
        closeNotificationFullscreenBubble()
        guard let closing = prepareNotificationCaptureMockupClose() else { return }
        let panel = closing.panel
        let motion = closing.motion
        let frameMotion = closing.frameMotion
        conceal(motion, using: .topDismiss)
        scheduleRetiringShellPopover(
            panel: panel,
            motion: motion,
            frameMotion: frameMotion,
            after: ShellMotion.topDismiss.duration
        )
        stopNotificationFullscreenStatePollIfIdle()
    }

    // MARK: Independent state toast lifecycle

    private func installStateToastMonitors() {
        capsLockState = NSEvent.modifierFlags.contains(.capsLock)
        capsLockGlobalMonitor = NSEvent.addGlobalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            Task { @MainActor in self?.handleCapsLockChange(event) }
        }
        capsLockLocalMonitor = NSEvent.addLocalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            self?.handleCapsLockChange(event)
            return event
        }
    }

    private func installFullscreenShellRevealMonitors() {
        fullscreenShellRevealModifierActive = fullscreenShellRevealChordIsDown
        fullscreenShellRevealGlobalMonitor = NSEvent.addGlobalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            Task { @MainActor in self?.handleFullscreenShellRevealModifierChange(event) }
        }
        fullscreenShellRevealLocalMonitor = NSEvent.addLocalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            self?.handleFullscreenShellRevealModifierChange(event)
            return event
        }
    }

    private func setFullscreenShellRevealModifierActive(_ active: Bool) {
        guard fullscreenShellRevealModifierActive != active
                || (nativeFullscreenShellState && fullscreenShellRevealed != active) else { return }
        fullscreenShellRevealModifierActive = active
        // The Cocoa monitor can be delayed or unavailable while another app
        // owns the fullscreen Space. The event-tap path calls this same method
        // synchronously, so a first modifier press can establish the boundary
        // before the user tries a shell surface.
        if !nativeFullscreenShellState {
            _ = refreshNativeFullscreenShellPresentation()
        }
        guard nativeFullscreenShellState else { return }
        fullscreenShellRevealed = active
        applyNativeFullscreenShellPresentation()
        reconcileNotificationFullscreenPresentation(knownState: nativeFullscreenShellState)
    }

    private func handleFullscreenShellRevealModifierChange(_ event: NSEvent) {
        let active = event.modifierFlags.contains(.control) && event.modifierFlags.contains(.option)
        setFullscreenShellRevealModifierActive(active)
    }

    /// Fallback for modifier events delivered by the session event tap while
    /// another application is frontmost. The NSEvent monitors above remain in
    /// place for normal Cocoa delivery; this path makes the reveal chord work
    /// even when the fullscreen app owns keyboard focus.
    fileprivate func handleFullscreenShellRevealFlags(_ flags: CGEventFlags) {
        let active = flags.contains(.maskControl) && flags.contains(.maskAlternate)
        setFullscreenShellRevealModifierActive(active)
    }

    private func handleCapsLockChange(_ event: NSEvent) {
        let enabled = event.modifierFlags.contains(.capsLock)
        guard capsLockState != enabled else { return }
        capsLockState = enabled
        showStateToast(MacPlusPlusStateToast(
            title: "Caps Lock",
            detail: enabled ? "Enabled" : "Disabled",
            symbol: enabled ? "capslock.fill" : "capslock"
        ))
    }

    @objc nonisolated private func showStateToastFromNotification(_ notification: Notification) {
        let info = notification.userInfo ?? [:]
        let title = info["title"] as? String ?? "Mac++"
        let detail = info["detail"] as? String ?? "State updated"
        let symbol = info["symbol"] as? String ?? "info.circle.fill"
        let critical = (info["critical"] as? NSNumber)?.boolValue
            ?? (info["critical"] as? Bool) ?? false
        let duration = (info["duration"] as? NSNumber)?.doubleValue ?? 4.2
        Task { @MainActor [weak self] in
            self?.showStateToast(MacPlusPlusStateToast(
                title: title,
                detail: detail,
                symbol: symbol,
                critical: critical,
                duration: duration
            ))
        }
    }

    private func showStateToast(_ event: MacPlusPlusStateToast) {
        guard !fullscreenShellSurfaceRequestIsSuppressed(),
              !notificationSessionLocked,
              let screen = NSScreen.main ?? NSScreen.screens.first else { return }
        stateToastGeneration &+= 1
        let generation = stateToastGeneration
        stateToastCloseTimer?.invalidate()
        stateToastCloseTimer = nil

        if let panel = stateToastWindow,
           let presentation = stateToastPresentation,
           let motion = stateToastMotion {
            withAnimation(ShellMotion.contentIn.animation) {
                presentation.event = event
            }
            if !motion.presented { reveal(motion, using: .notification) }
            panel.orderFrontRegardless()
        } else {
            let size = NSSize(width: 316, height: 62)
            let frame = NSRect(
                x: screen.frame.midX - size.width / 2,
                y: screen.frame.maxY - shellTopDepth(on: screen) - size.height - 30,
                width: size.width,
                height: size.height
            )
            let panel = makePanel(frame: frame)
            let motion = SurfaceMotionState()
            let presentation = MacPlusPlusStateToastPresentation(event: event)
            panel.identifier = NSUserInterfaceItemIdentifier("macpp-state-toast")
            // Device and Focus changes should visually replace the native
            // Control Center announcement in the same top-center slot. Those
            // announcements sit above the screen-saver level, so use a
            // bounded layer above that system HUD while staying well below
            // the system maximum/security surfaces. This must remain higher
            // than the ordinary shell layer: the toast is meant to cover
            // whatever shell surface triggered it.
            panel.level = NSWindow.Level(rawValue: Int(CGWindowLevelForKey(.screenSaverWindow)) + 1100)
            panel.ignoresMouseEvents = true
            panel.contentView = NSHostingView(rootView:
                MacPlusPlusStateToastView(presentation: presentation, motion: motion)
            )
            panel.alphaValue = 1
            panel.orderFrontRegardless()
            stateToastWindow = panel
            stateToastMotion = motion
            stateToastPresentation = presentation
            reveal(motion, using: .notification)
        }

        let timer = Timer.scheduledTimer(withTimeInterval: event.duration, repeats: false) { [weak self] _ in
            Task { @MainActor in
                guard let self, self.stateToastGeneration == generation else { return }
                self.closeStateToast()
            }
        }
        timer.tolerance = 0.08
        RunLoop.main.add(timer, forMode: .common)
        stateToastCloseTimer = timer
    }

    private func closeStateToast() {
        stateToastCloseTimer?.invalidate()
        stateToastCloseTimer = nil
        stateToastGeneration &+= 1
        let generation = stateToastGeneration
        guard let panel = stateToastWindow else {
            stateToastMotion = nil
            stateToastPresentation = nil
            return
        }
        conceal(stateToastMotion, using: .notification)
        // Hold the panel and its state until the conceal has actually finished
        // rather than clearing them up front. A toast posted during that window
        // used to find no current panel and build a second one at the identical
        // frame, so two toasts briefly overlapped -- one fading out under the
        // other fading in. Keeping the reference lets `showStateToast` revive
        // this panel instead, and the generation check drops this retirement if
        // that happens.
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.notification.duration) { [weak self] in
            guard let self, self.stateToastGeneration == generation else { return }
            self.stateToastWindow = nil
            self.stateToastMotion = nil
            self.stateToastPresentation = nil
            self.retirePanel(panel)
        }
    }

    private func performLauncherQuickAction(
        _ action: MacPlusPlusLauncherQuickAction,
        windowID: Int? = nil
    ) {
        switch action {
        case .toggleMicrophone:
            model.toggleMicrophoneMute()
        case .toggleOutputMute:
            model.toggleMute()
        case .toggleFocus:
            model.toggleFocus()
        case .toggleWiFi:
            model.toggleWiFi()
        case .toggleVPN:
            model.toggleVPN()
        case .toggleDesktopLayer:
            nexusModel.setDesktopLayerEnabled(!nexusModel.desktopLayerEnabled)
        case .toggleCenterClock:
            nexusModel.setDesktopCenterClockEnabled(!nexusModel.desktopCenterClockEnabled)
        case .toggleVisualizer:
            nexusModel.setDesktopVisualizerEnabled(!nexusModel.desktopVisualizerEnabled)
        case .toggleEQ:
            break
        case .toggleShellBorder:
            model.setShellBorderEnabled(!model.shellBorderEnabled)
        case .toggleMenuMask:
            toggleMenuMask()
        case .toggleAppDock:
            toggleAppShelf()
        case .focusWindow:
            guard let windowID else { return }
            guard runMacPlusPlusYabai(["-m", "window", String(windowID), "--focus"]) else {
                model.onStateToast?(MacPlusPlusStateToast(
                    title: "Window Focus Unavailable",
                    detail: "Select a yabai tier in Setup Manager and install yabai separately.",
                    symbol: "macwindow"
                ))
                return
            }
        case .pullWindow:
            guard let windowID,
                  (1...CaelestiaParityTokens.Sizes.workspaceCount).contains(model.currentWorkspace) else { return }
            let label = macppWorkspaceLabels[model.currentWorkspace - 1]
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                let moved = runMacPlusPlusYabai(
                    ["-m", "window", String(windowID), "--space", label],
                    waitUntilExit: true
                )
                let focused = moved && runMacPlusPlusYabai(
                    ["-m", "window", String(windowID), "--focus"],
                    waitUntilExit: true
                )
                DispatchQueue.main.async {
                    guard let self else { return }
                    self.model.refreshWorkspaceApps()
                    if !focused {
                        self.model.onStateToast?(MacPlusPlusStateToast(
                            title: "Window Pull Unavailable",
                            detail: "Select a yabai tier in Setup Manager and install yabai separately.",
                            symbol: "macwindow"
                        ))
                    }
                }
            }
        case .lockScreen:
            model.lockScreen()
        }
    }

    private func configureLauncher() {
        launcherModel.reload()
        launcherModel.onGeometryChange = { [weak self] height, width in
            self?.resizeLauncher(to: height, width: width)
        }
        launcherModel.onOpenNexus = { [weak self] in self?.openNexusFromLauncher() }
        launcherModel.onOpenNexusPage = { [weak self] destination in
            self?.openNexusPageFromLauncher(destination)
        }
        launcherModel.onPerformQuickAction = { [weak self] action, windowID in
            self?.performLauncherQuickAction(action, windowID: windowID)
        }
        launcherModel.onOverlayArrow = { [weak self] delta in
            guard let self else { return }
            if self.launcherModel.nexusPresented {
                self.stepNexusPage(by: delta)
            } else {
                self.launcherModel.publishOverlayArrow(delta)
            }
        }
        let watcher = ApplicationCatalogWatcher()
        watcher.start { [weak self] in self?.launcherModel.reload() }
        launcherCatalogWatcher = watcher
        registerLauncherHotKey()
        let clickMask: NSEvent.EventTypeMask = [.leftMouseDown, .rightMouseDown]
        launcherOutsideClickMonitor = NSEvent.addGlobalMonitorForEvents(matching: clickMask) { [weak self] _ in
            let point = NSEvent.mouseLocation
            Task { @MainActor [weak self] in
                self?.handleLauncherOutsideClick(at: point)
            }
        }
        // Global monitors do not receive events dispatched by Mac++ Shell
        // itself. The shell's full-screen host can therefore swallow a click
        // outside the floating Nexus panel unless the local path participates
        // in the same dismissal contract.
        launcherOutsideLocalClickMonitor = NSEvent.addLocalMonitorForEvents(matching: clickMask) { [weak self] event in
            let point = NSEvent.mouseLocation
            Task { @MainActor [weak self] in
                self?.handleLauncherOutsideClick(at: point)
            }
            return event
        }
    }

    private func handleLauncherOutsideClick(at point: NSPoint) {
        guard let panel = launcherWindow, panel.isVisible,
              !panel.frame.contains(point) else { return }
        hideLauncher()
    }
    private func registerLauncherHotKey() {
        let identifier = EventHotKeyID(signature: OSType(0x4D505050), id: 1)
        _ = RegisterEventHotKey(UInt32(kVK_Space), UInt32(cmdKey), identifier, GetApplicationEventTarget(), 0, &launcherHotKey)
        var specification = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: OSType(kEventHotKeyPressed))
        let pointer = Unmanaged.passUnretained(self).toOpaque()
        InstallEventHandler(GetApplicationEventTarget(), { _, _, userData in
            guard let userData else { return noErr }
            let delegate = Unmanaged<ShellDelegate>.fromOpaque(userData).takeUnretainedValue()
            Task { @MainActor in delegate.toggleLauncher() }
            return noErr
        }, 1, &specification, pointer, nil)
    }
    private func toggleLauncher() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        if launcherModel.wallpaperEditorPresented {
            launcherModel.dismissWallpaperEditor()
            return
        }
        if launcherHoverPreviewActive {
            // The hotkey is an explicit Search request, not a request to pin
            // whichever hover preview happens to be visible.
            showLauncher()
            return
        }
        if launcherWindow?.isVisible == true {
            if launcherModel.overlayPresented {
                launcherWindow?.makeKeyAndOrderFront(nil)
            } else {
                hideLauncher()
            }
        } else {
            showLauncher()
        }
    }
    private func showLauncher(directNexus: Bool = false, hoverPreview: Bool = false) {
        // A display can disappear during a hot-plug transition. Check before
        // dismissing the other surfaces so a headless/reconfiguring session
        // cannot leave the shell marked as occupied by a window it never made.
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        guard let layoutScreen = primaryDisplay() else { return }
        // The launcher is the only shell surface whose authored envelope can be
        // larger than a short built-in display. Configure it before resetting
        // state so Search, Nexus, Wallpapers, and their transitions all report
        // one display-local size to the AppKit host.
        launcherModel.configureResponsiveLayout(for: layoutScreen.frame.size)
        // A resize display link can outlive the previous presentation by a
        // frame when filtering and dismissal happen back-to-back. Cancel it
        // before reusing the panel so an old height cannot land on the new
        // launch transaction.
        launcherFrameAnimator.cancel()
        // Any pending hover dismissal belongs to the previous, hover-opened
        // session. Opening the launcher deliberately -- the hotkey, a rail
        // click -- must not inherit a timer that would close it a moment later
        // just because the pointer happens to be elsewhere.
        cancelNexusHoverClose()
        launcherHoverPreviewActive = hoverPreview
        // A new presentation supersedes a delayed dismissal. The generation
        // guard below prevents that old completion from ordering out the
        // newly reused window.
        launcherDismissalInFlight = false
        launcherTransitionGeneration += 1
        let generation = launcherTransitionGeneration
        dismissOtherPopouts(
            keeping: .launcher,
            preservingFreshNotification: notificationFreshOverlay
        )
        macppcastVisible = true
        model.setSurfaceVisible(false); model.setReactive(false)
        launcherModel.resetNexus()
        if !hoverPreview {
            launcherModel.query = ""
            launcherModel.selected = 0
            launcherModel.refreshMode()
        }
        if directNexus {
            // The sidebar CPU icon is a direct Nexus entry point. Seed the
            // final surface before the panel is shown so this path never
            // flashes through the smaller search launcher first.
            nexusModel.page = .settings
            launcherModel.presentNexus(immediate: true)
        }
        // Setting `selected` to 0 is not enough to return the list to the top:
        // it is usually already 0, so nothing observes a change. See
        // LauncherModel.listResetToken.
        if !hoverPreview {
            launcherModel.resetListPosition()
            if launcherModel.baseItems.isEmpty { launcherModel.reload() }
        }
        guard let screen = primaryDisplay() else {
            launcherHoverPreviewActive = false
            launcherDismissalInFlight = false
            macppcastVisible = false
            model.setSurfaceVisible(true)
            model.setReactive(false)
            launcherModel.resetNexus()
            return
        }
        // Re-read after the state reset as well: a display can be replaced
        // during the synchronous hot-plug window. The metrics setter is
        // idempotent for the ordinary path and corrects the rare screen swap.
        launcherModel.configureResponsiveLayout(for: screen.frame.size)
        let initialWidth = (launcherModel.nexusPresented
            || launcherModel.wallpapersPresented
            || launcherModel.screensaversPresented)
            ? launcherModel.displayMetrics.launcherNexusWidth
            : launcherModel.displayMetrics.launcherSearchWidth
        let size = NSSize(width: initialWidth, height: launcherModel.panelHeight)
        let target = NSRect(x: screen.frame.midX - size.width / 2, y: screen.frame.minY + shellFrame, width: size.width, height: size.height)
        let launcherOwnsSurface = NSScreen.screens.count > 1
        let panel: NSWindow
        if let existing = launcherWindow { panel = existing }
        else {
            panel = PrimaryLauncherWindow(
                contentRect: target,
                styleMask: [.borderless],
                backing: .buffered,
                defer: false,
                screen: screen
            )
            panel.isOpaque = false
            panel.backgroundColor = .clear
            panel.hasShadow = false
            panel.hidesOnDeactivate = false
            panel.level = .floating
            // Search/Nexus is an ordinary shell surface. It only joins a
            // native fullscreen Space while the explicit reveal chord is held;
            // making it auxiliary at creation time lets a stale fullscreen
            // poll expose a newly opened launcher over the app.
            panel.collectionBehavior =
                ShellFullscreenPolicy.suppressesNativeFullscreen.collectionBehavior
            panel.contentView = DestinationHostingContainer(
                rootView: LauncherView(
                    model: launcherModel,
                    motion: launcherMotion,
                    hide: { [weak self] in self?.hideLauncher() },
                    shellBorderPresentation: model.borderPresentation,
                    paintsEmbeddedSurface: launcherOwnsSurface,
                    nexusContent: { [weak self] in
                        guard let self else { return AnyView(EmptyView()) }
                        return AnyView(MacPlusPlusNexusView(
                            shell: self.model,
                            nexus: self.nexusModel,
                            launcher: self.launcherModel,
                            palette: self.model.palettePresentation,
                            close: { [weak self] in self?.hideLauncher() },
                            toggleMenuMask: { [weak self] in
                                self?.performLauncherQuickAction(.toggleMenuMask)
                            },
                            openLauncher: { [weak self] in self?.showLauncherSearch() },
                            embedded: true
                        ))
                    },
                    wallpaperContent: { [weak self] in
                        guard let self else { return AnyView(EmptyView()) }
                        return AnyView(MacPlusPlusWallpaperCarouselView(
                            shell: self.model,
                            launcherModel: self.launcherModel
                        ))
                    },
                    desktopContent: { [weak self] in
                        guard let self else { return AnyView(EmptyView()) }
                        return AnyView(MacPlusPlusDesktopCarouselView(
                            shell: self.model,
                            palette: self.model.palettePresentation,
                            nexus: self.nexusModel,
                            launcherModel: self.launcherModel
                        ))
                    },
                    screensaverContent: { [weak self] in
                        guard let self else { return AnyView(EmptyView()) }
                        return AnyView(MacPlusPlusScreensaverCarouselView(
                            shell: self.model,
                            launcherModel: self.launcherModel
                        ))
                    }
                ),
                destinationSize: size,
                contentAlignment: .bottomCenter
            )
            launcherWindow = panel
        }
        let launcherPolicy: ShellFullscreenPolicy =
            nativeFullscreenShellState && fullscreenShellRevealed
            ? .allowsNativeFullscreen
            : .suppressesNativeFullscreen
        panel.collectionBehavior = launcherPolicy.collectionBehavior
        panel.alphaValue = 1
        (panel.contentView as? DestinationHostingContainerProtocol)?.setDestinationSize(size)
        panel.setFrame(target, display: true)
        // The shared shell contour owns Search/Nexus on every display. A
        // multi-display launcher may still paint its fill locally, but its
        // border follows the same descriptor and Canvas as every other
        // attached popout.
        frameMotion(for: screen).attach(
            launcherMotion,
            attachment: .bottom,
            frame: shellLocalFrame(target, on: screen),
            radius: CaelestiaParityTokens.Border.rounding
        )
        let contentGeneration = launcherMotion.beginContentTransition()
        launcherMotion.progress = 0
        launcherMotion.presented = false
        // Search/Nexus is already at its destination frame before the reveal
        // begins. Unlike a rail handoff, there is no AppKit frame animator
        // that can publish a travelling placement phase for this panel;
        // leaving this at zero strands the shared content gate at its seed
        // value and can present an apparently empty launcher after a rapid
        // selector/carousel transition.
        launcherMotion.surfacePlacementProgress = 1
        launcherMotion.setContourProgress(0)
        if hoverPreview {
            // `orderFrontRegardless` presents the all-Spaces Nexus surface
            // without activating the accessory app or disturbing another
            // application's key window and first responder.
            panel.orderFrontRegardless()
        } else {
            // A borderless window can become key, but AppKit will not reliably
            // transfer keyboard focus to it while Mac++ Shell itself is inactive.
            // Activate first so the SwiftUI FocusState transaction below always
            // reaches the search field on the initial presentation.
            NSApp.activate(ignoringOtherApps: true)
            panel.makeKeyAndOrderFront(nil)
        }
        if !directNexus {
            launcherModel.requestSearchFocus()
        }
        DispatchQueue.main.async { [weak self] in
            guard let self, generation == self.launcherTransitionGeneration else { return }
            if !directNexus {
                self.launcherModel.requestSearchFocus()
            }
            withAnimation(ShellMotion.topPopout.animation) {
                self.launcherMotion.presented = true
                self.launcherMotion.progress = 1
            }
            self.launcherMotion.animateContour(to: 1, using: .topPopout, on: panel.screen)
            self.scheduleContentReady(
                self.launcherMotion,
                generation: contentGeneration,
                panel: panel,
                contentAnimation: ShellMotion.topPopout.animation
            )
            // The first SwiftUI measurement can happen before the attached
            // panel has completed its initial display transaction. Settle the
            // hosting view once the reveal starts so a later arrow key is not
            // responsible for the first real layout pass.
            self.settleLauncherLayout(panel)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) { [weak self, weak panel] in
            guard let self, let panel, panel.isVisible, generation == self.launcherTransitionGeneration else { return }
            if !hoverPreview { panel.makeKey() }
            if !directNexus {
                self.launcherModel.requestSearchFocus()
            }
            self.settleLauncherLayout(panel)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.topPopout.duration) { [weak self, weak panel] in
            guard let self, let panel, panel.isVisible, generation == self.launcherTransitionGeneration else { return }
            self.settleLauncherLayout(panel)
        }
        if ProcessInfo.processInfo.environment["MACPP_SHELL_MOTION_AUDIT_AUTOCLOSE"] == "1" {
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.20) { [weak self] in self?.hideLauncher() }
        }
    }

    private func hideLauncher(completion: (() -> Void)? = nil) {
        // Hiding is also a lifecycle boundary for the resize animator. Its
        // completion must not settle a panel that is being retired or reused
        // by the next hotkey press.
        launcherFrameAnimator.cancel()
        launcherHoverPreviewActive = false
        guard let panel = launcherWindow, panel.isVisible else {
            launcherDismissalInFlight = false
            // A dismissed or externally closed launcher must clear its
            // transient state before the next presentation.
            macppcastVisible = false
            if model.selectedTab == 1 { model.selectedTab = 0 }
            frameMotion.detach(launcherMotion)
            _ = launcherMotion.beginContentTransition()
            launcherMotion.setContourProgress(0)
            launcherModel.resetNexus()
            completion?()
            return
        }
        guard !launcherDismissalInFlight else { return }
        launcherDismissalInFlight = true
        launcherModel.cancelTransitionsForDismissal()
        launcherTransitionGeneration += 1
        // Invalidate any queued reveal/content watchdog before starting the
        // close. A stale callback must not make the next reused Nexus panel
        // inherit the previous session's phases.
        _ = launcherMotion.beginContentTransition()
        // Media/Performance select themselves before asking this method to
        // retire Search. Only clear the launcher-owned selection here, or a
        // Search -> tool handoff briefly leaves the new surface unselected.
        if model.selectedTab == 1 { model.selectedTab = 0 }
        let generation = launcherTransitionGeneration
        withAnimation(ShellMotion.topDismiss.animation) {
            launcherMotion.presented = false
            launcherMotion.progress = 0
        }
        launcherMotion.animateContour(to: 0, using: .topDismiss, on: panel.screen)
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.topDismiss.duration) { [weak self, weak panel] in
            guard let self, let panel, generation == self.launcherTransitionGeneration else { return }
            panel.orderOut(nil)
            self.macppcastVisible = false
            self.frameMotion.detach(self.launcherMotion)
            self.launcherModel.resetNexus()
            self.launcherDismissalInFlight = false
            completion?()
        }
    }
    private func resizeLauncher(to height: CGFloat, width requestedWidth: CGFloat? = nil) {
        guard let panel = launcherWindow else { return }
        let screen = panel.screen ?? primaryDisplay()
        let width = requestedWidth
            ?? ((launcherModel.nexusPresented
                || launcherModel.wallpapersPresented
                || launcherModel.screensaversPresented)
                ? launcherModel.displayMetrics.launcherNexusWidth
                : launcherModel.displayMetrics.launcherSearchWidth)
        let centerX = screen?.frame.midX ?? panel.frame.midX
        let frame = NSRect(
            x: centerX - width / 2,
            y: (screen?.frame.minY ?? panel.frame.minY) + shellFrame,
            width: width,
            height: height
        )
        (panel.contentView as? DestinationHostingContainerProtocol)?.setDestinationSize(
            CGSize(width: frame.width, height: frame.height)
        )
        guard panel.isVisible else {
            panel.setFrame(frame, display: false)
            if let screen { frameMotion.update(launcherMotion, frame: shellLocalFrame(frame, on: screen)) }
            settleLauncherLayout(panel)
            return
        }
        launcherFrameAnimator.animate(
            panel,
            to: frame,
            motion: .launcherResize,
            frameChanged: { [weak self, weak screen] current in
                guard let self, let screen else { return }
                self.frameMotion.update(self.launcherMotion, frame: self.shellLocalFrame(current, on: screen))
            },
            progressChanged: { [weak self, weak panel] phase in
                guard let self, let panel,
                      self.launcherWindow === panel,
                      self.launcherModel.nexusTransitioning else { return }
                self.launcherModel.setOverlayMorphProgress(phase)
            },
            completion: { [weak self, weak panel] in
                guard let self, let panel else { return }
                // AppKit has reached the destination frame, but SwiftUI may
                // still be holding the hosting view's first ideal-size
                // measurement. A single explicit layout pass at the settled
                // frame keeps the bottom attachment deterministic; otherwise
                // the next arrow key can become the first event that causes
                // this pass.
                self.settleLauncherLayout(panel)
                // Complete the incoming layer from the same terminal sample
                // as the host frame. The model's delayed task is only a
                // watchdog if the display link is interrupted.
                self.launcherModel.finishOverlayTransition()
            }
        )
    }

    private func settleLauncherLayout(_ panel: NSWindow) {
        guard let content = panel.contentView else { return }
        content.needsLayout = true
        content.layoutSubtreeIfNeeded()
        content.displayIfNeeded()
    }

    // Arrow keys while Nexus is up walk its menu column. Deliberately clamped
    // rather than wrapped: a menu is a finite list with a real top and
    // bottom, and silently teleporting from Settings back to the extension
    // pages reads as a mis-press. The wallpaper carousel, which genuinely is
    // a loop,
    // keeps its own wrapping handler.
    private func stepNexusPage(by delta: Int) {
        guard launcherModel.nexusPresented else { return }
        let pages = MacPlusPlusNexusModel.Page.allCases
        guard let current = pages.firstIndex(of: nexusModel.page) else { return }
        let next = min(pages.count - 1, max(0, current + delta))
        guard next != current else { return }
        withAnimation(ShellMotion.nexusPageSwitch.animation) { nexusModel.page = pages[next] }
    }

    private func openNexusFromLauncher() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        guard launcherWindow?.isVisible == true else { showLauncherNexus(); return }
        launcherMotion.ensureContentReady()
        withAnimation(ShellMotion.nexusPageSwitch.animation) { nexusModel.page = .settings }
        launcherModel.presentNexus()
    }

    /// Search intents can name a Nexus page directly. Keep this as a Shell
    /// handoff rather than teaching Search about Nexus view state: the Shell
    /// owns the page model and can therefore preserve the same animation,
    /// focus, and overlay lifecycle as rail navigation.
    private func openNexusPageFromLauncher(_ destination: MacPlusPlusNexusDestination) {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        cancelNexusHoverClose()
        launcherHoverPreviewActive = false
        if launcherModel.wallpapersPresented
            || launcherModel.desktopPresented
            || launcherModel.screensaversPresented {
            launcherModel.resetNexus()
        }
        guard let requestedPage = MacPlusPlusNexusModel.Page(rawValue: destination.rawValue) else { return }
        // “Nexus” is the legacy search destination.  The real Caelestia
        // surface opens on its first registered page, Wallpaper & style;
        // keep Overview available as an extension without making it the
        // default entry point.
        let page: MacPlusPlusNexusModel.Page = requestedPage == .overview ? .settings : requestedPage

        if launcherWindow?.isVisible == true {
            launcherMotion.ensureContentReady()
            withAnimation(ShellMotion.nexusPageSwitch.animation) { nexusModel.page = page }
            launcherModel.presentNexus()
            NSApp.activate(ignoringOtherApps: true)
            launcherWindow?.makeKeyAndOrderFront(nil)
            return
        }

        showLauncher()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            guard let self else { return }
            withAnimation(ShellMotion.nexusPageSwitch.animation) { self.nexusModel.page = page }
            self.launcherModel.presentNexus()
        }
    }

    /// Opens the launcher in its search state.
    ///
    /// This path is reserved for an intentional click. It activates Mac++,
    /// resets the previous launch session and requests keyboard focus; rail
    /// hover uses `showLauncherNexusPreview` and cannot enter this routine.
    private func showLauncherSearch() {
        cancelNexusHoverClose()
        showLauncher()
        // showLauncher creates/orders the panel synchronously. Claim the rail
        // selection only when that presentation succeeded so an unavailable
        // display cannot leave Search accented with no matching surface.
        if launcherWindow?.isVisible == true { model.selectedTab = 1 }
    }

    /// Presents the launcher Search state for hover discovery without
    /// activating Mac++, becoming key, or mutating a deliberate Search query.
    private func showLauncherSearchPreview() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        cancelNexusHoverClose()
        // Never replace an already-visible, intentional Search/Nexus session
        // merely because the pointer crossed the rail icon. A preview-owned
        // launcher is safe to retarget, which also recovers cleanly if the
        // pointer re-enters while its previous preview is still on screen.
        guard launcherWindow?.isVisible != true || launcherHoverPreviewActive else { return }
        // A passive preview starts from a predictable empty query. The normal
        // click path still owns and preserves the deliberate Search session.
        launcherModel.query = ""
        launcherModel.selected = 0
        launcherModel.refreshMode()
        launcherModel.resetListPosition()
        showLauncher(hoverPreview: true)
    }

    /// Presents Nexus for its direct, explicit entry point without activating
    /// Mac++ from a rail hover.
    private func showLauncherNexusPreview() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        cancelNexusHoverClose()
        // Never replace an already-visible, intentional Search/Nexus session
        // merely because the pointer crossed the rail icon.
        guard launcherWindow?.isVisible != true else { return }
        showLauncher(directNexus: true, hoverPreview: true)
    }

    // A hover preview cannot disappear the instant the pointer leaves the
    // icon, because Nexus sits at the bottom of the screen and the pointer
    // crosses open space to reach it. The first check allows that trip; the
    // watchdog then keeps the preview alive only while the pointer is near it.
    private func beginNexusHoverClose() {
        guard launcherHoverPreviewActive else { return }
        nexusHoverCloseTimer?.invalidate()
        let timer = Timer(timeInterval: 0.3, repeats: true) { [weak self] tick in
            Task { @MainActor in
                guard let self else { tick.invalidate(); return }
                guard self.launcherHoverPreviewActive else {
                    tick.invalidate()
                    self.nexusHoverCloseTimer = nil
                    return
                }
                guard let panel = self.launcherWindow, panel.isVisible else {
                    tick.invalidate()
                    self.nexusHoverCloseTimer = nil
                    return
                }
                // A generous margin: the pointer only has to be near the
                // surface to count as "still using it", which stops a shaky
                // hand at the edge from dismissing it mid-reach.
                if NSMouseInRect(NSEvent.mouseLocation, panel.frame.insetBy(dx: -24, dy: -24), false) {
                    return
                }
                tick.invalidate()
                self.nexusHoverCloseTimer = nil
                self.hideLauncher()
            }
        }
        // 0.55s before the first check -- enough to travel from the rail to
        // the surface without the dismissal racing the pointer.
        timer.fireDate = Date().addingTimeInterval(0.55)
        nexusHoverCloseTimer = timer
        RunLoop.main.add(timer, forMode: .common)
    }

    private func cancelNexusHoverClose() {
        nexusHoverCloseTimer?.invalidate()
        nexusHoverCloseTimer = nil
    }

    private func showLauncherNexus() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        // Re-entering Search during the grace period should keep it open.
        cancelNexusHoverClose()
        let promotesHoverPreview = launcherHoverPreviewActive
        launcherHoverPreviewActive = false
        if launcherModel.wallpapersPresented
            || launcherModel.desktopPresented
            || launcherModel.screensaversPresented {
            launcherModel.resetNexus()
        }
        if launcherWindow?.isVisible == true {
            if launcherDismissalInFlight {
                // A quick re-entry can arrive while the old panel is still
                // visible during its close curve. Treat that as a new
                // presentation, not as a page update on the outgoing tree;
                // otherwise the dismissal orders out the freshly requested
                // Nexus surface and leaves only the shell's empty envelope.
                showLauncher(directNexus: true)
                return
            }
            launcherMotion.ensureContentReady()
            withAnimation(ShellMotion.panelSwitch.animation) { nexusModel.page = .settings }
            launcherModel.presentNexus()
            if promotesHoverPreview {
                NSApp.activate(ignoringOtherApps: true)
                launcherWindow?.makeKeyAndOrderFront(nil)
            }
            return
        }
        showLauncher(directNexus: true)
    }

    private func showLauncherObservatory() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        cancelNexusHoverClose()
        if launcherModel.wallpapersPresented
            || launcherModel.desktopPresented
            || launcherModel.screensaversPresented {
            launcherModel.resetNexus()
        }
        withAnimation(ShellMotion.nexusPageSwitch.animation) { nexusModel.page = .observatory }
        if launcherWindow?.isVisible == true {
            launcherMotion.ensureContentReady()
            launcherModel.presentNexus()
            return
        }
        showLauncher()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            guard let self else { return }
            withAnimation(ShellMotion.nexusPageSwitch.animation) { self.nexusModel.page = .observatory }
            self.launcherModel.presentNexus()
        }
    }

    @objc private func showWallpapersFromNotification(_ notification: Notification) {
        showLauncherWallpapers()
    }

    private func showLauncherWallpapers() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        if launcherWindow?.isVisible == true {
            launcherMotion.ensureContentReady()
            launcherModel.presentWallpapers()
            return
        }
        showLauncher()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            self?.launcherModel.presentWallpapers()
        }
    }

    private func showLauncherDesktop() {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        if launcherWindow?.isVisible == true {
            launcherMotion.ensureContentReady()
            launcherModel.presentDesktop()
            return
        }
        showLauncher()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) { [weak self] in
            self?.launcherModel.presentDesktop()
        }
    }

    private func closeDrawer() {
        cancelDrawerClose()
        model.setReactive(false)
        guard let panel = drawerWindow else { return }
        let motion = drawerMotion
        let owningFrameMotion = drawerFrameMotion
        drawerWindow = nil; drawerMotion = nil; drawerFrameMotion = nil
        conceal(motion)
        scheduleRetiringShellPopover(
            panel: panel,
            motion: motion,
            frameMotion: owningFrameMotion,
            after: ShellMotion.dismiss.duration
        )
    }
    private func scheduleDrawerClose(after delay: TimeInterval) {
        drawerCloseTimer?.invalidate()
        drawerCloseTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in
            Task { @MainActor in self?.closeDrawer() }
        }
    }
    private func cancelDrawerClose() { drawerCloseTimer?.invalidate(); drawerCloseTimer = nil }

    /// Resolves a point in the top panel's local coordinate space to the
    /// nearest workspace card. The view is local to the notch panel, so this
    /// calculation never claims drops elsewhere on the desktop.
    private func workspaceTarget(in panel: NSPanel?, localPoint point: NSPoint) -> Int? {
        guard let panel,
              model.topTab == 3,
              let contentView = panel.contentView else { return nil }

        let spaces = Array(model.workspaces.prefix(CaelestiaParityTokens.Sizes.workspaceCount))
        guard !spaces.isEmpty else { return nil }
        let contentLeading: CGFloat = 28
        let contentWidth = max(0, contentView.bounds.width - contentLeading * 2)
        let cardWidth: CGFloat = 140
        let cardGap: CGFloat = 10
        let totalWidth = CGFloat(spaces.count) * cardWidth +
            CGFloat(max(0, spaces.count - 1)) * cardGap
        let leading = contentLeading + max(0, (contentWidth - totalWidth) / 2)
        let targetIndex = spaces.indices.min { left, right in
            let leftCenter = leading + cardWidth / 2 + CGFloat(left) * (cardWidth + cardGap)
            let rightCenter = leading + cardWidth / 2 + CGFloat(right) * (cardWidth + cardGap)
            return abs(leftCenter - point.x) < abs(rightCenter - point.x)
        } ?? 0
        let target = spaces[targetIndex].id
        macppWindowDragLog("top-target x=\(Int(point.x)) y=\(Int(point.y)) -> \(target)")
        return target
    }

    private func topPanel(on screen: NSScreen) -> NSPanel? {
        topWindowsByDisplay[displayIdentifier(screen)]
            ?? (isPrimaryDisplay(screen) ? topWindow : nil)
    }

    private func rightPanel(on screen: NSScreen) -> NSPanel? {
        rightWindowsByDisplay[displayIdentifier(screen)]
            ?? (isPrimaryDisplay(screen) ? rightWindow : nil)
    }

    private func topSurfaceMotion(on screen: NSScreen) -> SurfaceMotionState? {
        topMotionsByDisplay[displayIdentifier(screen)]
            ?? (isPrimaryDisplay(screen) ? topMotion : nil)
    }

    private func rightSurfaceMotion(on screen: NSScreen) -> SurfaceMotionState? {
        rightMotionsByDisplay[displayIdentifier(screen)]
            ?? (isPrimaryDisplay(screen) ? rightMotion : nil)
    }

    private var activeTopPanel: NSPanel? {
        if let topActiveDisplayID { return topWindowsByDisplay[topActiveDisplayID] }
        return topWindow
    }

    private var activeRightPanel: NSPanel? {
        if let rightActiveDisplayID { return rightWindowsByDisplay[rightActiveDisplayID] }
        return rightWindow
    }

    private func reanchorMenuMask() {
        guard let screen = primaryDisplay(),
              let mask = menuMaskWindow else { return }

        // Auxiliary-area values can be unavailable for one WindowServer turn
        // while a Space or the login cover is changing. Do not leave the
        // existing high-level panel at that transient origin: its width and
        // height are still valid, so keep those dimensions and force its
        // bottom edge to the display's physical top.
        let measured = DisplayHousing.frame(for: screen)
        let current = mask.frame
        let width = min(max(1, measured?.width ?? current.width), screen.frame.width)
        let height = min(max(1, measured?.height ?? current.height), screen.frame.height)
        let x = measured?.minX
            ?? min(max(current.minX, screen.frame.minX), screen.frame.maxX - width)
        let frame = NSRect(
            x: min(max(x, screen.frame.minX), screen.frame.maxX - width),
            y: screen.frame.maxY - height,
            width: width,
            height: height
        )
        mask.setFrame(frame, display: false)
        guard model.menuMaskEnabled,
              !startupSurfaceGateActive,
              !nativeFullscreenShellQuietMode else {
            mask.orderOut(nil)
            return
        }
        // Re-anchoring is also scheduled around every Space transition. Keep
        // the already-visible shield in place; repeatedly re-fronting this
        // high-level panel is enough to make the app underneath flash focus
        // even though no user-facing shell surface changed.
        let maskIsOnscreen = currentOnscreenWindowNumbers().contains(mask.windowNumber)
        if !mask.isVisible || !maskIsOnscreen {
            mask.orderFrontRegardless()
        }
        // A high-level shielding window can be reordered by WindowServer while
        // menu-bar presentation options settle. Set the frame once more after
        // ordering so the visible panel is always the top-anchored one.
        mask.setFrame(frame, display: true)
    }

    private func scheduleMenuMaskReanchor() {
        menuMaskReanchorGeneration &+= 1
        let generation = menuMaskReanchorGeneration
        // Two short passes cover both the normal async layout turn and the
        // slower login/display-parameter publication without keeping a timer
        // alive for the lifetime of the shell.
        for delay in [0.15, 0.60] {
            DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                guard let self, self.menuMaskReanchorGeneration == generation else { return }
                self.reanchorMenuMask()
            }
        }
    }

    private func buildEdgePanels(on screen: NSScreen) {
        let displayID = displayIdentifier(screen)
        if isPrimaryDisplay(screen) {
            let shield = Int(CGShieldingWindowLevel())
            if let notchFrame = DisplayHousing.frame(for: screen) {
                // Keep the opening's measured horizontal span, but derive its
                // vertical origin from the current display frame at the last
                // possible moment. A stale auxiliary-area y must never become
                // the initial position of the shielding panel.
                let anchoredNotchFrame = NSRect(
                    x: notchFrame.minX,
                    y: screen.frame.maxY - notchFrame.height,
                    width: notchFrame.width,
                    height: notchFrame.height
                )
                let mask = makePanel(frame: anchoredNotchFrame)
                mask.level = NSWindow.Level(rawValue: shield)
                mask.ignoresMouseEvents = true
                mask.contentView = NSHostingView(rootView: Color.black
                    .clipShape(UnevenRoundedRectangle(topLeadingRadius: 0, bottomLeadingRadius: 14, bottomTrailingRadius: 14, topTrailingRadius: 0))
                    .ignoresSafeArea())
                if model.menuMaskEnabled && !startupSurfaceGateActive {
                    mask.orderFrontRegardless()
                } else {
                    mask.orderOut(nil)
                }
                menuMaskWindow = mask
            } else {
                // Flat displays and transient WindowServer reads must not get
                // a guessed center rectangle that looks like a second notch.
                menuMaskWindow = nil
            }
        }

        let topDepth = shellTopDepth(on: screen)
        let displayMetrics = CaelestiaParityGeometry.DisplayMetrics(screenSize: screen.frame.size)
        let authoredTopSize = CGSize(width: 700, height: topSurfaceHeight(for: topDepth))
        let topSize = NSSize(
            width: displayMetrics.topSurfaceWidth,
            height: authoredTopSize.height * displayMetrics.scale
        )
        let topHidden = NSRect(x: screen.frame.midX - topSize.width / 2, y: screen.frame.maxY, width: topSize.width, height: topSize.height)
        let top = makePanel(
            frame: topHidden,
            activating: true,
            fullscreenPolicy: .allowsNativeFullscreen,
            // The top surface owns the display rim in its SwiftUI shape.
            // Letting AppKit constrain this panel below the menu-bar frame
            // adds one more menu-bar/notch-depth offset before the authored
            // `topDepth` padding is applied, which pushes every tab/page down
            // on notched and small displays.
            allowsTopRimCoverage: true
        )
        let topSurfaceMotion = isPrimaryDisplay(screen) ? self.topMotion : SurfaceMotionState()
        topMotionsByDisplay[displayID] = topSurfaceMotion
        top.level = shellWindowLevel
        let topRoot = AnyView(
            LivingSurface(state: topSurfaceMotion, attachment: .top, topDepth: topDepth) {
                CaelestiaResponsiveSurface(scale: displayMetrics.scale, authoredSize: authoredTopSize) {
                    NotchPopout(
                        model: self.model,
                        motion: topSurfaceMotion,
                        close: { [weak self] in self?.hideTop(on: screen) },
                        toggleMask: { [weak self] in self?.toggleMenuMask() },
                        topDepth: topDepth
                    )
                }
            }
        )
        let topHost = WorkspaceDropHostingView(
            rootView: topRoot,
            acceptsDrop: { [weak self] point, pasteboard in
                guard let self,
                      self.model.topTab == 3,
                      (macppWindowID(from: pasteboard) != nil || self.model.activeWindowDragID != nil) else { return false }
                // Accept the complete Workspaces panel while it is visible.
                // The old card-only gate briefly returned a rejected cursor in
                // the gaps as AppKit crossed from a window row to the card,
                // which is why a release needed an extra flick.
                return self.topPanel(on: screen)?.isVisible == true
            },
            performDrop: { [weak self] point, pasteboard in
                guard let self,
                      self.model.topTab == 3,
                      let windowID = macppWindowID(from: pasteboard) ?? self.model.activeWindowDragID,
                      let target = self.workspaceTarget(in: self.topPanel(on: screen), localPoint: point) else {
                    return false
                }
                // Dispatch yabai immediately. The normal workspace refresh
                // follows independently and only updates the cards.
                self.model.workspaceDropTarget = nil
                self.clearPassiveWorkspaceDrag()
                self.model.moveWindow(windowID, toSpace: target)
                return true
            },
            updateDropTarget: { [weak self] point, pasteboard in
                guard let self,
                      self.model.topTab == 3,
                      (macppWindowID(from: pasteboard) != nil || self.model.activeWindowDragID != nil) else {
                    self?.model.workspaceDropTarget = nil
                    return
                }
                self.model.workspaceDropTarget = self.workspaceTarget(
                    in: self.topPanel(on: screen),
                    localPoint: point
                )
            },
            clearDropTarget: { [weak self] in
                self?.model.workspaceDropTarget = nil
            }
        )
        top.contentView = topHost
        top.orderOut(nil)
        topWindowsByDisplay[displayID] = top
        if isPrimaryDisplay(screen) { topWindow = top }

        let authoredRightSize = CGSize(width: edgeControlsWidth, height: edgeControlsHeight)
        let rightSize = NSSize(
            width: displayMetrics.edgeControlsWidth,
            height: displayMetrics.edgeControlsHeight
        )
        let rightHidden = NSRect(x: screen.frame.maxX, y: screen.frame.midY - rightSize.height / 2, width: rightSize.width, height: rightSize.height)
        let right = makePanel(
            frame: rightHidden,
            activating: true,
            fullscreenPolicy: .allowsNativeFullscreen
        )
        let rightSurfaceMotion = isPrimaryDisplay(screen) ? self.rightMotion : SurfaceMotionState()
        rightMotionsByDisplay[displayID] = rightSurfaceMotion
        right.level = shellWindowLevel
        right.contentView = NSHostingView(rootView:
            LivingSurface(state: rightSurfaceMotion, attachment: .right) {
                CaelestiaResponsiveSurface(scale: displayMetrics.scale, authoredSize: authoredRightSize) {
                    EdgeSliders(model: self.model, motion: rightSurfaceMotion)
                }
            }
        )
        right.orderOut(nil)
        rightWindowsByDisplay[displayID] = right
        if isPrimaryDisplay(screen) { rightWindow = right }
    }
    private func installEdgeMonitor() {
        let mask: NSEvent.EventTypeMask = [.mouseMoved, .leftMouseDragged, .rightMouseDragged]
        let coalescer = globalPointerCoalescer
        globalMouseMonitor = NSEvent.addGlobalMonitorForEvents(matching: mask) { [weak self, coalescer] _ in
            coalescer.submit(NSEvent.mouseLocation) { [weak self] point in
                self?.handlePointer(point)
            }
        }
        localMouseMonitor = NSEvent.addLocalMonitorForEvents(matching: mask) { [weak self] event in
            self?.handlePointer(NSEvent.mouseLocation)
            return event
        }
    }

    /// Observes the end of a MacPlusPlus window drag without placing another window
    /// over the desktop. If the release is outside one of MacPlusPlus's own panels,
    /// the selected window is moved to the current yabai space. Local and
    /// global monitors are passive: each returns the original event so normal
    /// mouse interaction is never paused or swallowed.
    private func installPassiveWorkspaceDragMonitor() {
        let mask: NSEvent.EventTypeMask = [.leftMouseDown, .leftMouseDragged, .leftMouseUp]
        passiveWorkspaceDragGlobalMonitor = NSEvent.addGlobalMonitorForEvents(matching: mask) { [weak self] event in
            let point = NSEvent.mouseLocation
            Task { @MainActor [weak self] in
                guard let self else { return }
                if event.type == .leftMouseDown {
                    // If AppKit swallowed the previous drag's mouse-up, the
                    // next ordinary click is a hard session boundary. Clear
                    // it before that click can accidentally move the old
                    // window again.
                    self.clearPassiveWorkspaceDrag()
                } else if event.type == .leftMouseDragged {
                    self.updatePassiveWorkspaceDrag(at: point)
                } else {
                    self.finishPassiveWorkspaceDrag(at: point)
                }
            }
        }
        passiveWorkspaceDragLocalMonitor = NSEvent.addLocalMonitorForEvents(matching: mask) { [weak self] event in
            let point = NSEvent.mouseLocation
            Task { @MainActor [weak self] in
                guard let self else { return }
                if event.type == .leftMouseDown {
                    self.clearPassiveWorkspaceDrag()
                } else if event.type == .leftMouseDragged {
                    self.updatePassiveWorkspaceDrag(at: point)
                } else {
                    self.finishPassiveWorkspaceDrag(at: point)
                }
            }
            return event
        }
    }

    private func beginPassiveWorkspaceDrag(_ windowID: Int) {
        passiveWorkspaceDragExpiryTimer?.invalidate()
        passiveWorkspaceDragPollTimer?.invalidate()
        passiveWorkspaceDragWindowID = windowID
        passiveWorkspaceDragHasMoved = false
        macppWindowDragLog("passive-begin id=\(windowID)")
        // A drag can be cancelled without producing a mouse-up for this
        // process. Keep the state bounded so a later click can never move an
        // old window accidentally.
        passiveWorkspaceDragExpiryTimer = Timer.scheduledTimer(withTimeInterval: 12, repeats: false) { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.clearPassiveWorkspaceDrag()
            }
        }
        // macOS may consume the mouse-up that ends an NSItemProvider drag,
        // especially when the destination is another NSWindow. Polling the
        // button state closes that gap without installing an event tap or
        // intercepting any user input. The same timer keeps the highlight
        // following the pointer when AppKit omits draggingUpdated callbacks.
        passiveWorkspaceDragPollTimer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { [weak self] _ in
            Task { @MainActor [weak self] in
                guard let self, self.passiveWorkspaceDragWindowID != nil else { return }
                let point = NSEvent.mouseLocation
                if NSEvent.pressedMouseButtons & 1 == 0 {
                    if self.passiveWorkspaceDragHasMoved {
                        self.finishPassiveWorkspaceDrag(at: point)
                    }
                } else {
                    self.updatePassiveWorkspaceDrag(at: point)
                }
            }
        }
        passiveWorkspaceDragPollTimer?.tolerance = 0.01
        RunLoop.main.add(passiveWorkspaceDragPollTimer!, forMode: .common)
    }

    /// Keeps the destination accent live even when AppKit's drag session does
    /// not forward every `draggingUpdated` callback through NSHostingView.
    /// This is a passive event monitor: it never consumes or rewrites the
    /// desktop event, it only updates the small workspace target state.
    private func updatePassiveWorkspaceDrag(at point: NSPoint) {
        guard passiveWorkspaceDragWindowID != nil else { return }
        passiveWorkspaceDragHasMoved = true
        guard let top = activeTopPanel,
              model.topTab == 3,
              top.frame.contains(point) else {
            if model.workspaceDropTarget != nil { model.workspaceDropTarget = nil }
            return
        }
        let localPoint = NSPoint(x: point.x - top.frame.minX, y: point.y - top.frame.minY)
        model.workspaceDropTarget = workspaceTarget(in: top, localPoint: localPoint)
    }

    private func clearPassiveWorkspaceDrag() {
        passiveWorkspaceDragExpiryTimer?.invalidate()
        passiveWorkspaceDragExpiryTimer = nil
        passiveWorkspaceDragPollTimer?.invalidate()
        passiveWorkspaceDragPollTimer = nil
        passiveWorkspaceDragHasMoved = false
        passiveWorkspaceDragWindowID = nil
        model.clearWindowDrag()
    }

    private func finishPassiveWorkspaceDrag(at point: NSPoint) {
        guard let windowID = passiveWorkspaceDragWindowID else { return }
        macppWindowDragLog("passive-finish id=\(windowID) x=\(Int(point.x)) y=\(Int(point.y))")
        defer { clearPassiveWorkspaceDrag() }
        // Normally the panel-local AppKit destination handles this before
        // mouse-up. Keep a passive fallback for systems that end the drag
        // session without calling the hosting view's perform method.
        if let top = activeTopPanel, top.frame.contains(point) {
            let localPoint = NSPoint(
                x: point.x - top.frame.minX,
                y: point.y - top.frame.minY
            )
            if let target = workspaceTarget(in: top, localPoint: localPoint) {
                model.moveWindow(windowID, toSpace: target)
            }
            return
        }
        // Drops on MacPlusPlus's own panels are handled by their local destination
        // (the notch host or the proven sidebar onDrop). Let those paths own
        // the target instead of sending a second command to the current space.
        if macppOwnsWorkspaceDrop(at: point) { return }
        model.moveWindow(
            windowID,
            toSpace: min(CaelestiaParityTokens.Sizes.workspaceCount, max(1, model.currentWorkspace))
        )
    }

    private func macppOwnsWorkspaceDrop(at point: NSPoint) -> Bool {
        let panels: [NSWindow] = Array(topWindowsByDisplay.values)
            + Array(rightWindowsByDisplay.values)
            + [drawerWindow, powerWindow, railPopoverWindow, notificationMockupWindow, sidebarWindow, launcherWindow]
                .compactMap { $0 }
        if panels.contains(where: { $0.frame.insetBy(dx: -8, dy: -8).contains(point) }) {
            return true
        }
        guard let screen = NSScreen.screens.first(where: { $0.frame.contains(point) }) else { return false }
        let rail = NSRect(
            x: screen.frame.minX,
            y: screen.frame.minY,
            width: railWidth + 18,
            height: screen.frame.height
        )
        return rail.contains(point)
    }

    private func installScrollEventTap() {
        guard scrollEventTap == nil else { return }
        guard globalInteractionTrustIsGranted else {
            // Do not call CGEvent.tapCreate while TCC is denied. It only
            // produces a noisy failure; the one-second trust poll will retry
            // after the user grants access and relaunches the Shell.
            installScrollMonitorFallbacksIfNeeded()
            return
        }
        installScrollMonitorFallbacksIfNeeded()
        // Two NSEvent-monitor-based attempts at rail scroll both produced zero
        // response, even with Input Monitoring granted. Per Apple's Cocoa Event
        // Handling Guide ("Monitoring Events"), a local monitor only sees events
        // dispatched to this app's own windows, and a global monitor only sees
        // events dispatched to OTHER apps' windows -- and even then only gates
        // KEY events behind accessibility trust, not scroll. Since the rail is a
        // borderless overlay panel that most window servers don't treat as the
        // active scroll target while the user is scrolling over whatever app is
        // actually frontmost, neither monitor is a reliable fit here.
        //
        // CGEventTap is the documented, standard mechanism real system-wide
        // utilities (BetterTouchTool, Rectangle, etc.) use for exactly this: an
        // always-on background listener for input events regardless of which
        // app is frontmost. It requires Accessibility and, on 10.15+, Input
        // Monitoring permission. This is an intercepting tap rather than a
        // listen-only tap so the edge sliders can consume the scroll event;
        // events elsewhere are returned untouched. Important caveat: after
        // granting either permission, macOS caches the trust decision for the
        // running process, so the grant only takes effect after this app is
        // fully quit and relaunched -- not just left running in the background.
        let mask: CGEventMask =
            (1 << CGEventType.scrollWheel.rawValue)
            | (1 << CGEventType.flagsChanged.rawValue)
        let context = MacPlusPlusScrollEventTapContext(delegate: self)
        let contextPointer = Unmanaged.passRetained(context).toOpaque()
        guard let tap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .defaultTap,
            eventsOfInterest: mask,
            callback: macppShellScrollEventTapCallback,
            userInfo: contextPointer
        ) else {
            Unmanaged<MacPlusPlusScrollEventTapContext>.fromOpaque(contextPointer).release()
            NSLog("Mac++ Shell: could not create scroll event tap -- grant Accessibility and Input Monitoring, then fully quit and relaunch Mac++ Shell.")
            return
        }
        scrollEventTap = tap
        scrollEventTapContext = contextPointer
        removeScrollMonitorFallbacks()
        guard let source = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, tap, 0) else {
            CFMachPortInvalidate(tap)
            scrollEventTap = nil
            scrollEventTapContext = nil
            Unmanaged<MacPlusPlusScrollEventTapContext>.fromOpaque(contextPointer).release()
            NSLog("Mac++ Shell: could not create the scroll event run-loop source.")
            installScrollMonitorFallbacksIfNeeded()
            return
        }
        scrollEventRunLoopSource = source
        CFRunLoopAddSource(CFRunLoopGetMain(), source, .commonModes)
        CGEvent.tapEnable(tap: tap, enable: true)
    }

    private func checkGlobalInteractionTrustIfNeeded() {
        guard !globalInteractionTrustIsGranted else { return }
        // A launchd-managed app must not request TCC access on every startup.
        // The prompt-enabled Accessibility probe and input-listener request
        // both turn a normal launch into a repeated deny/prompt cycle when the
        // signed client has changed. Keep startup read-only; the user can grant
        // the stable signed bundle in
        // Privacy & Security, and this process will notice it through the
        // poll below after a full relaunch.
        let accessibility = AXIsProcessTrusted()
        let inputMonitoring: Bool
        if #available(macOS 10.15, *) {
            inputMonitoring = CGPreflightListenEventAccess()
        } else {
            inputMonitoring = true
        }
        var missing: [String] = []
        if !accessibility { missing.append("Accessibility") }
        if !inputMonitoring { missing.append("Input Monitoring") }
        NSLog("Mac++ Shell: %@ access is not granted; continuing without a TCC prompt. Enable the stable Mac++ Shell bundle in Privacy & Security, then relaunch it.", missing.joined(separator: " and "))
    }

    private var globalInteractionTrustIsGranted: Bool {
        guard AXIsProcessTrusted() else { return false }
        if #available(macOS 10.15, *) {
            return CGPreflightListenEventAccess()
        }
        return true
    }

    private func startGlobalInteractionTrustPoll() {
        globalInteractionTrustPollTimer?.invalidate()
        globalInteractionTrustPollTimer = nil
        guard scrollEventTap == nil, !globalInteractionTrustIsGranted else { return }

        let timer = Timer(timeInterval: 1, repeats: true) { [weak self] timer in
            Task { @MainActor [weak self] in
                guard let self, !self.isTerminating else {
                    timer.invalidate()
                    return
                }
                guard self.globalInteractionTrustIsGranted else { return }
                self.installScrollEventTap()
                guard self.scrollEventTap != nil else { return }
                timer.invalidate()
                self.globalInteractionTrustPollTimer = nil
            }
        }
        timer.tolerance = 0.2
        RunLoop.main.add(timer, forMode: .common)
        globalInteractionTrustPollTimer = timer
    }

    private func removeScrollEventTap() {
        if let source = scrollEventRunLoopSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), source, .commonModes)
        }
        scrollEventRunLoopSource = nil
        if let tap = scrollEventTap {
            CGEvent.tapEnable(tap: tap, enable: false)
            CFMachPortInvalidate(tap)
        }
        scrollEventTap = nil
        if let contextPointer = scrollEventTapContext {
            Unmanaged<MacPlusPlusScrollEventTapContext>.fromOpaque(contextPointer).release()
        }
        scrollEventTapContext = nil
        removeScrollMonitorFallbacks()
    }

    /// Keep the edge controls usable when macOS has not yet granted the
    /// session-wide event-tap permission. A local monitor still sees scrolls
    /// delivered directly to one of Shell's own panels; the global monitor is
    /// a best-effort bridge for systems that allow passive mouse monitoring
    /// before Accessibility/Input Monitoring is enabled. Neither monitor is
    /// installed once the CGEventTap is live, so a gesture can never update a
    /// slider twice.
    private func installScrollMonitorFallbacksIfNeeded() {
        guard localScrollMonitor == nil, globalScrollMonitor == nil else { return }

        localScrollMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { [weak self] event in
            guard let self, self.scrollEventTap == nil else { return event }
            let consumed = self.handleRailScroll(event, at: NSEvent.mouseLocation)
            return consumed ? nil : event
        }

        globalScrollMonitor = NSEvent.addGlobalMonitorForEvents(matching: .scrollWheel) { [weak self] event in
            guard let self else { return }
            Task { @MainActor [weak self] in
                guard let self, self.scrollEventTap == nil else { return }
                _ = self.handleRailScroll(event, at: NSEvent.mouseLocation)
            }
        }
    }

    private func removeScrollMonitorFallbacks() {
        if let localScrollMonitor {
            NSEvent.removeMonitor(localScrollMonitor)
            self.localScrollMonitor = nil
        }
        if let globalScrollMonitor {
            NSEvent.removeMonitor(globalScrollMonitor)
            self.globalScrollMonitor = nil
        }
    }
    fileprivate func reenableScrollEventTapIfNeeded() {
        guard let scrollEventTap else { return }
        CGEvent.tapEnable(tap: scrollEventTap, enable: true)
    }
    fileprivate func handleRailScroll(_ event: NSEvent, at eventPoint: NSPoint? = nil) -> Bool {
        guard !macppcastVisible else { return false }
        // NSEvent.mouseLocation can be one pointer sample behind a high-rate
        // trackpad gesture. The CGEvent location is the position attached to
        // this exact scroll tick, so use it when the global tap supplies one.
        let point = eventPoint ?? NSEvent.mouseLocation
        let vertical = CGFloat(event.scrollingDeltaY)
        guard abs(vertical) > 0.1 else { return false }
        // Trackpads report many small precise deltas per gesture; mouse
        // wheels report a handful of large line-based deltas. Scale each so
        // both feel like one deliberate nudge rather than a jump to an
        // extreme.
        let sensitivity: CGFloat = event.hasPreciseScrollingDeltas ? 0.0016 : 0.05
        let deltaFraction = Double(vertical * sensitivity)
        // Power attaches to the right edge, so its surface sits on top of the
        // edge sliders' own hit region. Let Power own scroll entirely while it
        // is open, rather than moving the system volume out from under a
        // pointer that was only reaching for the power menu.
        if railPopoverKind == .power || powerWindow != nil { return false }
        // The right-edge overlay (EdgeSliders) already stacks its own volume
        // (top) and brightness (bottom) controls explicitly. Keep this hit
        // test tied to those two actual slider rectangles: the rest of the
        // shell must never turn an ordinary content scroll into a hardware
        // volume or display-brightness change.
        let pointerScreen = NSScreen.screens.first(where: { NSMouseInRect(point, $0.frame, false) }) ?? NSScreen.main
        if let pointerScreen,
           let panel = rightPanel(on: pointerScreen),
           (rightVisible || rightSurfaceMotion(on: pointerScreen)?.presented == true),
           let target = edgeSliderScrollTarget(at: point, in: panel) {
            switch target {
            case .volume:
                model.setVolume(model.volume + deltaFraction)
            case .brightness:
                model.setBrightness(model.brightness + deltaFraction)
            }
            // The gesture belongs to MacPlusPlus's edge control. Returning true lets
            // the CGEventTap drop the original scroll event so the app under
            // the transparent edge panel does not scroll at the same time.
            return true
        }
        // Caelestia's left bar owns workspace scroll gestures even when no
        // popout is open. Volume and brightness are deliberately right-edge
        // controls only; the left rail must not turn an ordinary scroll over
        // the desktop into a system-volume or display-brightness change.
        // Keep the workspace hit region tied to the same 60pt outer bar
        // boundary used by reveal and the parity geometry helper, so a hidden
        // rail never steals scroll from the desktop outside its own edge.
        guard let screen = NSScreen.screens.first(where: { NSMouseInRect(point, $0.frame, false) }) ?? NSScreen.main else {
            return false
        }
        let screenFrame = screen.frame
        guard point.x >= screenFrame.minX,
              point.x <= screenFrame.minX + CaelestiaParityTokens.barOuterWidth else {
            railWorkspaceScrollRemainder = 0
            return false
        }
        let fromTop = screenFrame.maxY - point.y
        if fromTop <= 150 {
            railWorkspaceScrollRemainder += vertical
            let threshold: CGFloat = event.hasPreciseScrollingDeltas ? 24 : 1
            guard abs(railWorkspaceScrollRemainder) >= threshold else { return true }
            let direction = railWorkspaceScrollRemainder > 0 ? 1 : -1
            railWorkspaceScrollRemainder = 0
            let count = CaelestiaParityTokens.Sizes.workspaceCount
            let zeroBased = (model.currentWorkspace - 1 + direction + count) % count
            model.focusSpace(zeroBased + 1)
            return true
        }
        railWorkspaceScrollRemainder = 0
        // Pass every non-workspace left-rail scroll through unchanged. The
        // right-edge panel above is the sole scroll-to-volume/brightness path.
        return false
    }

    private func edgeSliderScrollTarget(
        at point: NSPoint,
        in panel: NSPanel
    ) -> MacPlusPlusEdgeSliderScrollTarget? {
        guard panel.isVisible, panel.frame.contains(point) else { return nil }

        // The AppKit panel is scaled with the display metrics, while the
        // SwiftUI controls retain their authored 112pt height. Reconstruct
        // the two control bands in screen coordinates instead of splitting
        // the whole panel at its midpoint. That keeps the shoulder, divider,
        // and transparent padding inert to scroll input.
        let scale = max(0.01, panel.frame.height / edgeControlsHeight)
        let shoulder = surfaceMorphShoulder * scale
        let bodyFrame = panel.frame.insetBy(dx: 0, dy: shoulder)
        guard bodyFrame.contains(point) else { return nil }

        let controlHeight = edgeLevelControlHeight * scale
        let gap = Spacing.base * scale
        let dividerHeight = scale
        let stackHeight = controlHeight * 2 + gap * 2 + dividerHeight
        let stackBottom = panel.frame.midY - stackHeight / 2
        let hitSlop = min(4 * scale, gap * 0.45)
        let column = NSRect(
            x: panel.frame.minX,
            y: bodyFrame.minY,
            width: panel.frame.width,
            height: bodyFrame.height
        )
        guard column.contains(point) else { return nil }

        let brightnessBand = NSRect(
            x: column.minX,
            y: stackBottom - hitSlop,
            width: column.width,
            height: controlHeight + hitSlop * 2
        )
        if brightnessBand.contains(point) { return .brightness }

        let volumeY = stackBottom + controlHeight + gap + dividerHeight + gap
        let volumeBand = NSRect(
            x: column.minX,
            y: volumeY - hitSlop,
            width: column.width,
            height: controlHeight + hitSlop * 2
        )
        if volumeBand.contains(point) { return .volume }
        return nil
    }
    private func railPopoverTrigger(at point: NSPoint, in frame: NSRect) -> RailPopoverKind? {
        // Mirror the real bottom control stack rather than depending solely
        // on SwiftUI's per-view hover events. AppKit can occasionally omit an
        // enter event when the pointer leaves and re-enters a borderless panel.
        guard point.x >= frame.minX, point.x <= frame.minX + CaelestiaParityTokens.barOuterWidth else { return nil }
        let y = point.y - frame.minY
        // Workspaces are the upper rail's own hit targets, so include them in
        // the same authoritative pointer map as the lower status controls.
        // Previously this function returned nil for the top stack; after a
        // settled workspace card was open, moving to 3/4/5 therefore left the
        // old card's corridor/close state in charge and could never arm the
        // next workspace reliably.
        let firstWorkspaceCenter = frame.height - SideRailGeometry.firstWorkspaceCenterFromTop
        for workspace in 1...CaelestiaParityTokens.Sizes.workspaceCount {
            let center = firstWorkspaceCenter
                - CGFloat(workspace - 1) * SideRailGeometry.workspacePitch
            if abs(y - center) <= SideRailGeometry.workspaceButtonSize / 2 {
                return .workspace(workspace)
            }
        }
        // The vertical title lane sits around the display midpoint. Keep it
        // separate from the fixed bottom status bands so a media card can
        // share the same hover corridor without stealing Calendar/Audio.
        if !model.media.title.isEmpty,
           !(14..<236).contains(y),
           abs(y - frame.height / 2) <= 120 {
            return .media
        }
        switch y {
        // 171..<236 is the clock button's band -- lingering here now shows a
        // quick calendar preview again, same as before, while a click still
        // opens Nexus directly (see SideRail/onOpenNexus) for the full page.
        case 171..<236: return .calendar
        case 138..<171: return .wifi
        case 108..<138: return .bluetooth
        case 80..<108: return .audio
        // Battery has a popout again (Battery Saver toggle), so this band
        // is back in the hover hit test, matching wifi/bluetooth/audio.
        case 51..<80: return .battery
        case 14..<51: return .power
        default: return nil
        }
    }

    private func appShelfTriggerIsActive(at point: NSPoint, in frame: NSRect) -> Bool {
        // The shelf is intentionally display-wide rather than another left
        // rail target. A small bottom-edge intent band keeps it discoverable
        // without reserving permanent pixels or crowding the narrow rail.
        point.x >= frame.minX
            && point.x <= frame.maxX
            && point.y <= frame.minY + appShelfTriggerHeight
    }

    private var powerOwnsDockReveal: Bool {
        powerPopoverTransitionActive
            || railPopoverKind == .power
            || powerWindow != nil
    }

    /// A delayed SwiftUI hover callback is not authoritative by itself. The
    /// pointer can leave a button during the 110 ms intent window, and an
    /// AppKit borderless panel can deliver that callback after the exit. Check
    /// the live trigger again before constructing a surface so a stale menu
    /// cannot materialize at the last clamped bottom position.
    private func railPopoverTriggerIsActive(
        _ kind: RailPopoverKind,
        on screen: NSScreen
    ) -> Bool {
        let point = NSEvent.mouseLocation
        guard NSMouseInRect(point, screen.frame, false) else { return false }

        if kind == .appShelf {
            return appShelfTriggerIsActive(at: point, in: screen.frame)
        }
        guard point.x >= screen.frame.minX,
              point.x <= screen.frame.minX + railWidth else { return false }

        switch kind {
        case .workspace, .activeApp, .runningApp:
            // These hit targets are laid out by SwiftUI rather than the fixed
            // global band map. Their view-level hover state is the precise
            // trigger, while the screen/rail check above rejects stale state
            // after the pointer has crossed to the desktop.
            return railVisualStates[displayIdentifier(screen)]?.hoveredKind == kind
        default:
            return railPopoverTrigger(at: point, in: screen.frame) == kind
        }
    }

    private func updateRailGlyphHover(_ candidate: RailPopoverKind?, on screen: NSScreen) {
        let displayID = displayIdentifier(screen)
        for (id, state) in railVisualStates {
            guard id == displayID else {
                state.hoveredKind = nil
                continue
            }
            if let candidate {
                state.hoveredKind = candidate
            } else {
                // Workspace/front-app hit regions are owned by SwiftUI and
                // are intentionally absent from railPopoverTrigger's fixed
                // global bands. Let their onHover exits clear them instead of
                // erasing their highlight on every mouse-move callback.
                switch state.hoveredKind {
                case .some(.workspace), .some(.activeApp), .some(.runningApp): break
                default: state.hoveredKind = nil
                }
            }
        }
    }
    private func setPresentedRailGlyph(_ kind: RailPopoverKind, on screen: NSScreen) {
        let next = railVisualStates[displayIdentifier(screen)]
        if railPopoverVisualState !== next {
            railPopoverVisualState?.presentedKind = nil
        }
        next?.presentedKind = kind
        railPopoverVisualState = next
    }
    private func clearPresentedRailGlyph() {
        railPopoverVisualState?.presentedKind = nil
        railPopoverVisualState = nil
    }
    private func armRailPopoverOpen(_ candidate: RailPopoverKind) {
        guard railHoverOpenTimer == nil else { return }
        let timer = Timer(timeInterval: 0.11, repeats: false) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                self.railHoverOpenTimer = nil
                guard self.railHoverCandidate == candidate else { return }
                let point = NSEvent.mouseLocation
                guard let screen = NSScreen.screens.first(where: { NSMouseInRect(point, $0.frame, false) }) ?? NSScreen.main else { return }
                let triggerIsActive = candidate == .appShelf
                    ? self.appShelfTriggerIsActive(at: point, in: screen.frame)
                    : self.railPopoverTrigger(at: point, in: screen.frame) == candidate
                guard triggerIsActive else { return }
                // The pointer monitor just revalidated the live trigger. Do
                // not ask the independently-delivered SwiftUI hover state to
                // validate it a second time; that state is exactly what can
                // arrive out of order while crossing adjacent workspaces.
                self.showRailPopover(candidate, on: screen, requireLiveTrigger: false)
            }
        }
        railHoverOpenTimer = timer
        RunLoop.main.add(timer, forMode: .common)
    }
    private func trackRailPopoverTrigger(_ candidate: RailPopoverKind?) {
        if candidate == .appShelf && powerOwnsDockReveal {
            railHoverOpenTimer?.invalidate(); railHoverOpenTimer = nil
            railHoverCandidate = nil
            return
        }
        if railHoverCandidate != candidate {
            railHoverOpenTimer?.invalidate(); railHoverOpenTimer = nil
            railHoverCandidate = candidate
        }
        guard let candidate else { return }
        cancelRailPopoverClose()
        // If another surface closed this popover while the pointer remained
        // in the same lane, re-arm it. This is the recovery path missing from
        // the old enter/exit-only implementation.
        if railPopoverKind != candidate { armRailPopoverOpen(candidate) }
    }
    private func openPowerPopoverImmediately(on screen: NSScreen) {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        // Claim the display-wide bottom corridor before constructing the
        // right-edge drawer; pointer events can arrive during that handoff.
        powerPopoverTransitionActive = true
        // A click is authoritative: discard any delayed hover request and any
        // pending close left behind by pointer traversal before opening Power.
        railHoverOpenTimer?.invalidate(); railHoverOpenTimer = nil
        railHoverCandidate = .power
        cancelRailPopoverClose()

        // Pressing Power sometimes appeared to do nothing, needing a second
        // press. The cause is that hovering the button already opens the
        // popover on a 0.11s timer, so by the time the click lands Power is
        // usually open -- and showRailPopover is idempotent, so the click did
        // nothing at all. Any pointer drift then tripped the hover-close and
        // retracted it, which reads as the press having been ignored.
        //
        // A click now pins the popover: hover-close cannot retract it, so it
        // stays until dismissed deliberately. That is also what makes it the
        // "permanent" popout rather than a hover preview.
        if railPopoverKind == .power, railPopoverWindow != nil {
            // Already open. If a previous click pinned it, this second press is
            // a deliberate dismissal; otherwise adopt the hover-opened surface.
            if railPopoverPinned {
                railPopoverPinned = false
                closeRailPopover()
            } else {
                railPopoverPinned = true
            }
            return
        }

        railPopoverPinned = true
        showRailPopover(.power, on: screen)
    }

    private func toggleAppShelf(on requestedScreen: NSScreen? = nil) {
        guard !fullscreenShellSurfaceRequestIsSuppressed(), !powerOwnsDockReveal else { return }
        if railPopoverKind == .appShelf, railPopoverWindow != nil {
            // A first explicit toggle adopts an already visible auto-shelf;
            // a second one dismisses it. This keeps the edge reveal gentle
            // while still giving the user a deterministic keyboard/search
            // toggle when they want the shelf to stay put.
            if railPopoverPinned {
                railPopoverPinned = false
                closeRailPopover()
            } else {
                railPopoverPinned = true
                cancelRailPopoverClose()
            }
            return
        }
        guard let screen = requestedScreen ?? NSScreen.main ?? primaryDisplay() ?? NSScreen.screens.first else { return }
        model.refreshAppRailApplications(force: true)
        guard !model.appRailApplications.isEmpty else { return }
        railPopoverPinned = true
        showRailPopover(.appShelf, on: screen, refreshData: false, requireLiveTrigger: false)
    }

    private func handlePointer(_ point: NSPoint) {
        guard !macppcastVisible else { return }
        guard !nativeFullscreenShellQuietMode else { return }
        guard let screen = NSScreen.screens.first(where: { NSMouseInRect(point, $0.frame, false) }) ?? NSScreen.main else { return }
        let frame = screen.frame
        let inRail = point.x >= frame.minX && point.x <= frame.minX + CaelestiaParityTokens.barOuterWidth
        // Power crosses the display from the left rail to the right edge. The
        // app shelf uses the entire bottom edge as its hover trigger, so it
        // must yield that corridor for the complete Power handoff.
        let appShelfTrigger = !powerOwnsDockReveal
            && appShelfTriggerIsActive(at: point, in: frame)
        let railTrigger = appShelfTrigger ? RailPopoverKind.appShelf : railPopoverTrigger(at: point, in: frame)
        // The shelf has no glyph in the left rail. Keep the per-display rail
        // highlight map scoped to actual rail controls while still using the
        // same intent timer for the display-wide bottom trigger.
        updateRailGlyphHover(appShelfTrigger ? nil : railTrigger, on: screen)
        trackRailPopoverTrigger(railTrigger)
        let railOwnsTop = inRail && point.y >= frame.maxY - 340
        if topVisible, let window = topPanel(on: screen), topActiveDisplayID == displayIdentifier(screen) {
            // The tab strip sits below this display's own rim, not the
            // primary's; on a mixed notch/external setup the hit band was
            // offset by the notch reservation on every external screen.
            let headerTop = window.frame.maxY - shellTopDepth(on: screen) - 2
            let headerBottom = headerTop - 52
            let contentX = point.x - window.frame.minX - 28
            let tabWidth = (window.frame.width - 56) / 4
            if point.y >= headerBottom,
               point.y <= headerTop,
               contentX >= 0,
               contentX < tabWidth * 4 {
                let index = min(3, max(0, Int(contentX / tabWidth)))
                if model.topTab != index {
                    model.selectTopTab(index)
                }
            }
        }
        // Use the full physical top-frame depth as the proximity target. The
        // old 7pt-only strip was effectively impossible to hit on a notched
        // display because macOS reports the pointer below that reservation.
        if railPopoverKind == .shell {
            topCloseTimer?.invalidate(); topCloseTimer = nil
            if topVisible { hideTop() }
        }
        else if topPanel(on: screen) != nil,
                point.y >= frame.maxY - shellTopDepth(on: screen) - 3,
                abs(point.x - frame.midX) < 330 {
            topCloseTimer?.invalidate(); topCloseTimer = nil
            if !topVisible { showTop(tab: nil, on: screen) }
        }
        else if topVisible, let window = activeTopPanel {
            if railOwnsTop || NSMouseInRect(point, window.frame.insetBy(dx: -10, dy: -10), false) {
                topCloseTimer?.invalidate(); topCloseTimer = nil
            } else { scheduleTopClose() }
        }
        else { topCloseTimer?.invalidate(); topCloseTimer = nil }

        let rightEdgeTrigger = max(shellFrame, CaelestiaParityTokens.Padding.medium)
        // Power and the notification mockup both attach to the *right* edge,
        // which is also where the volume/brightness sliders are triggered.
        // While either attached surface is open, it owns that edge exclusively
        // so the sliders cannot unfold underneath it.
        let attachedSurfaceOwnsRightEdge = railPopoverKind == .power
            || powerWindow != nil
            || sidebarVisible
            || notificationMockupWindow != nil
        if attachedSurfaceOwnsRightEdge {
            rightCloseTimer?.invalidate(); rightCloseTimer = nil
            if rightVisible { hideRight() }
        }
        else if rightTriggerHovered || (point.x >= frame.maxX - rightEdgeTrigger && abs(point.y - frame.midY) < 205) {
            rightCloseTimer?.invalidate(); rightCloseTimer = nil
            if !rightVisible { showRight(on: screen) }
        }
        else if rightVisible, let window = activeRightPanel, !NSMouseInRect(point, window.frame.insetBy(dx: -18, dy: -18), false) { scheduleRightClose() }
        else { rightCloseTimer?.invalidate(); rightCloseTimer = nil }

        if let sidebar = sidebarWindow, sidebarVisible {
            if NSMouseInRect(point, sidebar.frame.insetBy(dx: -12, dy: -12), false) {
                cancelSidebarClose()
            } else {
                scheduleSidebarClose()
            }
        }

        if let drawer = drawerWindow {
            if inRail || NSMouseInRect(point, drawer.frame.insetBy(dx: -12, dy: -12), false) { cancelDrawerClose() }
            else { scheduleDrawerClose(after: 0.38) }
        }
        if let power = powerWindow {
            let overTrigger = inRail && point.y <= frame.minY + 72
            if overTrigger || NSMouseInRect(point, power.frame.insetBy(dx: -10, dy: -10), false) { cancelPowerClose() }
            else { schedulePowerClose() }
        }
        if let popover = railPopoverWindow {
            let overAnyWorkspaceTrigger: Bool = {
                guard let railTrigger else { return false }
                if case .workspace = railTrigger { return true }
                return false
            }()
            let overTriggerCorridor: Bool = {
                switch railPopoverKind {
                case .appShelf:
                    return appShelfTrigger
                case .shell:
                    guard inRail else { return false }
                    return point.y >= frame.maxY - 120
                case .workspace:
                    guard inRail else { return false }
                    // Keep the old grace band for the small gaps between
                    // buttons, but never schedule the outgoing card's close
                    // while the pointer is over another workspace target.
                    // The live candidate above will arm that next card.
                    return overAnyWorkspaceTrigger
                        || (point.y >= frame.maxY - 172 && point.y <= frame.maxY - 40)
                case .activeApp, .runningApp:
                    guard inRail else { return false }
                    let triggerY = railPopoverTriggerY ?? popover.frame.midY
                    return abs(point.y - triggerY) <= 24
                case .media, .wifi, .bluetooth, .audio, .battery, .calendar, .power:
                    guard inRail else { return false }
                    return railTrigger == railPopoverKind
                case .none:
                    return false
                }
            }()
            // The panel touches the inner rail edge, so only a slim bridge is
            // needed. The old 24pt expansion kept unrelated controls active
            // and made popovers feel sticky after the pointer had left.
            let surfaceHit = popover.frame.insetBy(dx: -11, dy: -11)
            let bridgeMinY = popover.frame.minY - 8
            let bridgeHeight = popover.frame.height + 16
            let bridge: NSRect = {
                if case .appShelf = railPopoverKind {
                    return .zero
                }
                // Workspace popovers get vertically clamped away from their
                // own button when their content is tall enough to hit the
                // bottom rim -- a low workspace icon (like index 4's) can end up with
                // its popover pushed noticeably higher on screen than the
                // icon itself. The old bridge only ever spanned the
                // popover's own height, so moving the pointer diagonally
                // from that low icon toward the shifted-up popover crossed
                // open space neither the trigger corridor nor the bridge
                // covered, closing the popover mid-hover. Union the bridge
                // with the full workspace trigger band so the connecting
                // strip always reaches from the rail down to wherever the
                // popover actually landed, however far that is from the
                // icon that opened it.
                guard case .workspace = railPopoverKind else {
                    return NSRect(
                        x: frame.minX + railWidth - 4,
                        y: bridgeMinY,
                        width: max(18, popover.frame.minX - (frame.minX + railWidth) + 18),
                        height: bridgeHeight
                    )
                }
                let corridorMinY = frame.maxY - 158
                let corridorMaxY = frame.maxY - 42
                let minY = min(bridgeMinY, corridorMinY)
                let maxY = max(bridgeMinY + bridgeHeight, corridorMaxY)
                return NSRect(
                    x: frame.minX + railWidth - 4,
                    y: minY,
                    width: max(18, popover.frame.minX - (frame.minX + railWidth) + 18),
                    height: maxY - minY
                )
            }()
            let overSurfaceOrBridge = NSMouseInRect(point, surfaceHit, false) || NSMouseInRect(point, bridge, false)
            if overTriggerCorridor || overSurfaceOrBridge { cancelRailPopoverClose() }
            else { scheduleRailPopoverClose() }
        }
    }
    private func scheduleRetiringShellPopover(
        panel: NSWindow,
        motion: SurfaceMotionState?,
        frameMotion: ShellFrameMotionState?,
        after delay: TimeInterval
    ) {
        retiringShellPopovers.append(
            RetiringShellPopover(panel: panel, motion: motion, frameMotion: frameMotion)
        )
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self, weak panel] in
            guard let self, let panel,
                  let index = self.retiringShellPopovers.firstIndex(where: { $0.panel === panel }) else {
                return
            }
            let retiring = self.retiringShellPopovers.remove(at: index)
            self.retirePanel(retiring.panel)
            retiring.frameMotion?.detach(retiring.motion)
        }
    }

    private func retirePendingShellPopovers() {
        let pending = retiringShellPopovers
        retiringShellPopovers.removeAll()
        for retiring in pending {
            retirePanel(retiring.panel)
            retiring.frameMotion?.detach(retiring.motion)
        }
    }

    /// Begin the normal dismissal of every other shell surface before opening
    /// a new popout. The outgoing card keeps its authored close animation;
    /// its panel is retired by the same deferred path used for pointer-out.
    private func dismissOtherPopouts(
        keeping surface: ShellPopoverSurface,
        preservingFreshNotification: Bool = false
    ) {
        // A rail hover opens after a short intent delay. If the pointer has
        // already moved to another surface, that delayed callback must not
        // resurrect the old rail card after this handoff has retired it.
        if surface != .rail {
            railHoverOpenTimer?.invalidate()
            railHoverOpenTimer = nil
            railHoverCandidate = nil
        }
        if surface != .drawer { closeDrawer() }
        if surface != .top { hideTop() }
        if surface != .right { hideRight() }
        if surface != .power { closePower() }
        if surface != .rail { closeRailPopover() }
        if surface != .sidebar { closeSidebar() }
        if surface != .launcher { hideLauncher() }

        let keepFreshNotification = preservingFreshNotification
            && notificationFreshOverlay
            && notificationMockupWindow != nil
        if surface != .notification && !keepFreshNotification {
            closeNotificationCaptureMockup()
        }
    }

    private func showTop(tab: Int?, on requestedScreen: NSScreen? = nil) {
        guard !fullscreenShellSurfaceRequestIsSuppressed(), railPopoverKind != .shell else { return }
        guard let screen = requestedScreen ?? primaryDisplay() ?? NSScreen.main,
              let panel = topPanel(on: screen),
              let motion = topSurfaceMotion(on: screen) else { return }
        dismissOtherPopouts(
            keeping: .top,
            preservingFreshNotification: notificationFreshOverlay
        )
        let displayID = displayIdentifier(screen)
        if topVisible, topActiveDisplayID != displayID {
            hideTop()
        }
        if let tab, model.topTab != tab { withAnimation(ShellMotion.panelSwitch.animation) { model.topTab = tab } }
        // The top bar is a glance surface, not a monitoring dashboard. Its
        // old one-second probe cadence repeatedly launched the canonical
        // performance window while the bar was open, so the bar could keep sampling
        // its own opening/compositing burst and display a stale 95–100% GPU
        // reading. Two seconds matches Nexus' live dashboard cadence and
        // leaves the 10 Hz audio path independent for the Media tab.
        model.setSurfaceVisible(true, refreshInterval: 2.0)
        model.setReactive(model.topTab == 1)
        model.topSurfaceVisible = true
        if model.topTab == 1 { model.refreshCinemaStatus() }
        // The dashboard's ACTIVE WINDOW tile uses the same app sampler as the
        // dedicated rail popout. Keep it live only while that top surface is
        // visible so the rest state remains cheap.
        model.setFrontAppResourceSampling(model.topTab == 0)
        topCloseTimer?.invalidate(); topCloseTimer = nil
        if model.menuMaskEnabled { reanchorMenuMask() }
        if topVisible {
            // Already open, so the reveal below is skipped -- which is also
            // the path that would restart a content transition. Repair one
            // that never landed instead of leaving the surface blank until
            // the shell restarts.
            if motion.presented {
                motion.ensureContentReady()
            } else {
                // `topVisible` is the lifecycle owner. If a queued reveal was
                // superseded before it could present, restart it here rather
                // than keeping a visible panel with its seed contour forever.
                reveal(motion, using: .topPopout)
            }
            return
        }
        let target = NSRect(x: screen.frame.midX - panel.frame.width / 2, y: screen.frame.maxY - panel.frame.height, width: panel.frame.width, height: panel.frame.height)
        topVisible = true
        topActiveDisplayID = displayID
        // Through the accessor, not the bare property: it is what stamps this
        // display's rim depth onto the descriptor the fill and contour layers
        // read. Attaching directly left them on the initial flat-rim depth, so
        // the top popout's shoulder was drawn at the rim instead of below it and
        // its reverse curves vanished -- until some other surface happened to
        // call the accessor and set the depth as a side effect, which is why it
        // came and went.
        let owningFrameMotion = frameMotion(for: screen)
        owningFrameMotion.attach(motion, attachment: .top, frame: shellLocalFrame(target, on: screen), radius: CaelestiaParityTokens.Border.rounding)
        panel.orderFrontRegardless()
        panel.alphaValue = 1; panel.setFrame(target, display: true)
        reveal(motion, using: .topPopout)
        if ProcessInfo.processInfo.environment["MACPP_SHELL_MOTION_AUDIT_AUTOCLOSE"] == "1" {
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.20) { [weak self] in self?.hideTop(on: screen) }
        }
    }
    private func hideTop(on requestedScreen: NSScreen? = nil) {
        guard topVisible else { return }
        let screen: NSScreen? = requestedScreen
            ?? topActiveDisplayID.flatMap { id in
                NSScreen.screens.first(where: { displayIdentifier($0) == id })
            }
            ?? primaryDisplay()
            ?? NSScreen.main
        guard let screen,
              let panel = topPanel(on: screen),
              let motion = topSurfaceMotion(on: screen) else { return }
        let displayID = displayIdentifier(screen)
        guard requestedScreen == nil || topActiveDisplayID == displayID else { return }
        topCloseTimer?.invalidate(); topCloseTimer = nil; topVisible = false; model.setReactive(false); model.topSurfaceVisible = false
        topActiveDisplayID = nil
        model.setFrontAppResourceSampling(false)
        model.selectedTab = 0
        if !rightVisible { model.setSurfaceVisible(false) }
        let target = NSRect(x: screen.frame.midX - panel.frame.width / 2, y: screen.frame.maxY, width: panel.frame.width, height: panel.frame.height)
        let owningFrameMotion = frameMotion(for: screen)
        conceal(motion, using: .topDismiss)
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.topDismiss.duration) { [weak self, weak panel] in
            guard let self, let panel,
                  !self.topVisible || self.topActiveDisplayID != displayID else { return }
            panel.setFrame(target, display: false)
            panel.orderOut(nil)
            owningFrameMotion.detach(motion)
        }
    }
    private func scheduleTopClose() {
        guard topCloseTimer == nil else { return }
        topCloseTimer = Timer.scheduledTimer(withTimeInterval: 0.42, repeats: false) { [weak self] _ in Task { @MainActor in self?.hideTop() } }
    }
    private func showRight(on requestedScreen: NSScreen? = nil) {
        guard !fullscreenShellSurfaceRequestIsSuppressed(), railPopoverKind != .shell else { return }
        guard let screen = requestedScreen ?? primaryDisplay() ?? NSScreen.main,
              let panel = rightPanel(on: screen),
              let motion = rightSurfaceMotion(on: screen) else { return }
        dismissOtherPopouts(
            keeping: .right,
            preservingFreshNotification: notificationFreshOverlay
        )
        let displayID = displayIdentifier(screen)
        if rightVisible, rightActiveDisplayID != displayID {
            hideRight()
        }
        model.setSurfaceVisible(true); rightCloseTimer?.invalidate(); rightCloseTimer = nil; rightVisible = true
        rightActiveDisplayID = displayID
        if motion.presented {
            motion.ensureContentReady()
            return
        }
        let target = NSRect(x: screen.frame.maxX - panel.frame.width, y: screen.frame.midY - panel.frame.height / 2, width: panel.frame.width, height: panel.frame.height)
        let owningFrameMotion = frameMotion(for: screen)
        owningFrameMotion.attach(motion, attachment: .right, frame: shellLocalFrame(target, on: screen), radius: CaelestiaParityTokens.Border.rounding)
        panel.orderFrontRegardless()
        panel.alphaValue = 1; panel.setFrame(target, display: true)
        reveal(motion, using: .sidePopout)
    }
    private func hideRight(on requestedScreen: NSScreen? = nil) {
        guard rightVisible else { return }
        let screen: NSScreen? = requestedScreen
            ?? rightActiveDisplayID.flatMap { id in
                NSScreen.screens.first(where: { displayIdentifier($0) == id })
            }
            ?? primaryDisplay()
            ?? NSScreen.main
        guard let screen,
              let panel = rightPanel(on: screen),
              let motion = rightSurfaceMotion(on: screen) else { return }
        let displayID = displayIdentifier(screen)
        guard requestedScreen == nil || rightActiveDisplayID == displayID else { return }
        rightCloseTimer?.invalidate(); rightCloseTimer = nil; rightVisible = false
        rightActiveDisplayID = nil
        if !topVisible { model.setSurfaceVisible(false) }
        let target = NSRect(x: screen.frame.maxX, y: screen.frame.midY - panel.frame.height / 2, width: panel.frame.width, height: panel.frame.height)
        let owningFrameMotion = frameMotion(for: screen)
        conceal(motion, using: .sideDismiss)
        DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.sideDismiss.duration) { [weak self, weak panel] in
            guard let self, let panel,
                  !self.rightVisible || self.rightActiveDisplayID != displayID else { return }
            panel.setFrame(target, display: false)
            panel.orderOut(nil)
            owningFrameMotion.detach(motion)
        }
    }

    private func toggleSidebar(on screen: NSScreen) {
        if sidebarVisible, sidebarActiveDisplayID == displayIdentifier(screen) {
            closeSidebar()
        } else {
            showSidebar(on: screen)
        }
    }

    private func sidebarHeight(on screen: NSScreen) -> CGFloat {
        // The clicked notification center is a shell-height drawer, not a
        // content-sized card. Leave the top and bottom rim bands to the
        // persistent shell frame; the right-attached surface owns the inner
        // vertical contour between those two bands.
        max(
            1,
            screen.frame.height - shellTopDepth(on: screen) - shellFrame
        )
    }

    private func sidebarFrame(on screen: NSScreen, eventCount: Int) -> NSRect {
        let width = CaelestiaParityTokens.sidebarWidth
        _ = eventCount
        let height = sidebarHeight(on: screen)
        return NSRect(
            x: screen.frame.maxX - width,
            y: screen.frame.minY + shellFrame,
            width: width,
            height: height
        )
    }

    private func resizeSidebarIfNeeded() {
        guard sidebarVisible,
              let panel = sidebarWindow,
              let displayID = sidebarActiveDisplayID,
              let screen = NSScreen.screens.first(where: { displayIdentifier($0) == displayID })
        else { return }
        let target = sidebarFrame(on: screen, eventCount: notificationMockupQueue.events.count)
        guard abs(panel.frame.height - target.height) > 0.5 else { return }
        NSAnimationContext.runAnimationGroup { context in
            context.duration = ShellMotion.contentIn.duration
            context.timingFunction = ShellMotion.contentIn.appKitTiming
            panel.animator().setFrame(target, display: true)
        }
    }

    private func showSidebar(on screen: NSScreen) {
        guard !startupSurfaceGateActive else { return }
        _ = refreshNativeFullscreenShellPresentation()
        if nativeFullscreenShellQuietMode {
            notificationFullscreenState = true
            showNotificationFullscreenBubble(on: screen, pinned: true)
            return
        }
        guard railPopoverKind != .shell else { return }
        dismissOtherPopouts(
            keeping: .sidebar,
            preservingFreshNotification: notificationFreshOverlay
        )
        let displayID = displayIdentifier(screen)
        if sidebarVisible, sidebarActiveDisplayID != displayID {
            closeSidebar()
        }
        if let panel = sidebarWindow,
           sidebarActiveDisplayID == displayID,
           let motion = sidebarMotion {
            sidebarCloseTimer?.invalidate()
            sidebarCloseTimer = nil
            panel.orderFrontRegardless()
            motion.ensureContentReady()
            return
        }

        sidebarFrameAnimator.cancel()
        let frame = sidebarFrame(on: screen, eventCount: notificationMockupQueue.events.count)
        // Match the bottom-left utility's presentation model: the AppKit
        // host is placed at its final destination immediately and the
        // display-linked contour reveals it from the attached edge. Keeping
        // the panel offscreen and translating a finished silhouette in made
        // the notification center use a separate animation type, with both
        // reverse curves visible before the body reached the shell.
        let panel = makePanel(
            frame: frame,
            activating: true,
            fullscreenPolicy: .allowsNativeFullscreen
        )
        let motion = SurfaceMotionState()
        let visualSidebarPreview = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_SIDEBAR"] == "1"
        sidebarWindow = panel
        sidebarMotion = motion
        let owningFrameMotion = frameMotion(for: screen)
        sidebarFrameMotion = owningFrameMotion
        sidebarActiveDisplayID = displayID
        sidebarVisible = true
        panel.identifier = NSUserInterfaceItemIdentifier("caelestia-sidebar-\(displayID)")
        // The shared contour owns this edge too; keep the body below that
        // transparent shell layer instead of painting a second local seam.
        panel.level = shellWindowLevel
        panel.contentView = NSHostingView(rootView:
            LivingSurface(state: motion, attachment: .rightSidebar, deformsContent: false) {
                CaelestiaSidebarView(
                    model: self.model,
                    queue: self.notificationMockupQueue,
                    motion: motion,
                    close: { [weak self] in self?.closeSidebar() },
                    openEvent: { [weak self] event in self?.openNotificationCaptureEvent(event) },
                    clearEvent: { [weak self] event in self?.clearNotificationCaptureEvent(event) },
                    clearAll: { [weak self] in self?.clearAllNotificationCaptureQueue() },
                    hoverChanged: { [weak self] inside in
                        guard let self else { return }
                        if visualSidebarPreview { return }
                        if inside { self.cancelSidebarClose() }
                        else { self.scheduleSidebarClose() }
                    }
                )
            }
        )
        panel.alphaValue = 1
        panel.setFrame(frame, display: true)
        owningFrameMotion.attach(
            motion,
            attachment: .rightSidebar,
            frame: shellLocalFrame(frame, on: screen),
            radius: shellAttachmentRadius(.rightSidebar)
        )
        panel.orderFrontRegardless()
        model.setSurfaceVisible(true)
        scheduleNotificationFullscreenStatePoll()
        reveal(motion, using: .topPopout)
    }

    private func closeSidebar() {
        sidebarCloseTimer?.invalidate()
        sidebarCloseTimer = nil
        guard sidebarVisible, let panel = sidebarWindow else { return }
        let motion = sidebarMotion
        let owningFrameMotion = sidebarFrameMotion
        sidebarVisible = false
        sidebarActiveDisplayID = nil
        sidebarWindow = nil
        sidebarMotion = nil
        sidebarFrameMotion = nil
        // Use the same contour-owned dismissal as the bottom-left utility.
        // The panel remains at its final frame while its right-attached
        // envelope contracts, so the reverse shoulders are filled and
        // removed on the same sampled frame as the closing body.
        conceal(motion, using: .topDismiss)
        scheduleRetiringShellPopover(
            panel: panel,
            motion: motion,
            frameMotion: owningFrameMotion,
            after: ShellMotion.topDismiss.duration
        )
        if !self.sidebarVisible && self.sidebarWindow == nil
            && !self.topVisible && !self.rightVisible {
            model.setSurfaceVisible(false)
        }
        stopNotificationFullscreenStatePollIfIdle()
    }

    private func scheduleSidebarClose() {
        guard sidebarCloseTimer == nil else { return }
        sidebarCloseTimer = Timer.scheduledTimer(withTimeInterval: 0.40, repeats: false) { [weak self] _ in
            Task { @MainActor in self?.closeSidebar() }
        }
    }

    private func cancelSidebarClose() {
        sidebarCloseTimer?.invalidate()
        sidebarCloseTimer = nil
    }

    private func scheduleRightClose(after delay: TimeInterval = 0.40) {
        guard rightCloseTimer == nil else { return }
        rightCloseTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in Task { @MainActor in self?.hideRight() } }
    }
    private func toggleMenuMask() {
        model.menuMaskEnabled.toggle()
        UserDefaults.standard.set(model.menuMaskEnabled, forKey: "menuMaskEnabled")
        setSystemChromeHidden(model.menuMaskEnabled, forceDockRefresh: model.menuMaskEnabled)
        if model.menuMaskEnabled {
            reanchorMenuMask()
            scheduleMenuMaskReanchor()
        } else {
            menuMaskWindow?.orderOut(nil)
        }
    }
    private func schedulePaletteRefresh() {
        paletteRefreshWorkItem?.cancel()
        paletteRefreshGeneration &+= 1
        let generation = paletteRefreshGeneration
        let work = DispatchWorkItem { [weak self] in
            guard let self else { return }
            guard self.paletteRefreshGeneration == generation else { return }
            self.paletteRefreshWorkItem = nil
            withAnimation(ShellMotion.palette.animation) {
                self.refreshPaletteInPlace()
            }
        }
        paletteRefreshWorkItem = work
        // A palette is presentation state, not display topology. Rebuilding
        // every AppKit window here left delayed close/reveal work retaining
        // hosting objects that had already been replaced, which could crash
        // in objc_release. Invalidate the live observable roots instead.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.04, execute: work)
    }
    private func refreshPaletteInPlace() {
        // Views backed by ShellModel update through selectedPalette. Static
        // frame/launcher roots use their motion object as the invalidation
        // source, so explicitly refresh those without touching geometry.
        model.objectWillChange.send()
        // A bare objectWillChange re-runs LauncherView's body but changes no
        // value its extracted children receive, so SwiftUI's diffing skips
        // them and they keep stale palette colours (see
        // LauncherModel.paletteRevision). Bumping a real published value is
        // what actually invalidates those rows.
        launcherModel.paletteRevision &+= 1
        launcherModel.objectWillChange.send()
        frameMotion.objectWillChange.send()
        externalFrameMotions.values.forEach { $0.objectWillChange.send() }
        topMotion.objectWillChange.send()
        rightMotion.objectWillChange.send()
        topMotionsByDisplay.values.forEach { $0.objectWillChange.send() }
        rightMotionsByDisplay.values.forEach { $0.objectWillChange.send() }
        launcherMotion.objectWillChange.send()
        drawerMotion?.objectWillChange.send()
        powerMotion?.objectWillChange.send()
        railPopoverMotion?.objectWillChange.send()
        notificationMockupMotion?.objectWillChange.send()
        sidebarMotion?.objectWillChange.send()

        mediaMarqueeWindows.forEach { item in
            (item.panel.contentView as? MarqueePillView)?.applyTheme()
        }
        updateMediaMarquees()
    }
    private func setMenuBarHidden(_ hidden: Bool) {
        guard let yabaiExecutable = macppYabaiExecutableURL() else { return }
        let process = Process(); process.executableURL = yabaiExecutable
        process.arguments = ["-m", "config", "menubar_opacity", hidden ? "0.0" : "1.0"]
        try? process.run() // macpp:silent-ok optional yabai menu-bar update is best effort
    }
    private func readDockPreference(_ key: String) -> String? {
        let process = Process()
        let output = Pipe()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/defaults")
        process.arguments = ["read", "com.apple.dock", key]
        process.standardOutput = output
        process.standardError = FileHandle.nullDevice
        do {
            try process.run()
            process.waitUntilExit()
        } catch {
            return nil
        }
        guard process.terminationStatus == 0 else { return nil }
        return String(
            data: output.fileHandleForReading.readDataToEndOfFile(),
            encoding: .utf8
        )?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    }
    private func readDockAutohidePreference() -> Bool? {
        guard let value = readDockPreference("autohide") else { return nil }
        switch value {
        case "1", "true": return true
        case "0", "false": return false
        default: return nil
        }
    }
    @discardableResult
    private func runDockDefaults(_ arguments: [String]) -> Bool {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/defaults")
        process.arguments = arguments
        process.standardOutput = FileHandle.nullDevice
        process.standardError = FileHandle.nullDevice
        do {
            try process.run()
            process.waitUntilExit()
        } catch {
            return false
        }
        return process.terminationStatus == 0
    }
    private func setDockAutohide(_ hidden: Bool, forceRefresh: Bool = false) {
        let autohideChanged = readDockAutohidePreference() != hidden
        let currentDelay = readDockPreference("autohide-delay")
        let delayChanged = hidden ? currentDelay != dockLockedAutohideDelay : currentDelay != nil
        guard autohideChanged || delayChanged || forceRefresh else { return }

        if autohideChanged {
            guard runDockDefaults([
                "write", "com.apple.dock", "autohide", "-bool", hidden ? "true" : "false"
            ]) else { return }
        }
        if hidden && delayChanged {
            guard runDockDefaults([
                "write", "com.apple.dock", "autohide-delay", "-float", dockLockedAutohideDelay
            ]) else { return }
        } else if !hidden && delayChanged {
            guard runDockDefaults(["delete", "com.apple.dock", "autohide-delay"]) else { return }
        }

        // Dock reads these preferences at launch. A user-triggered enable also
        // refreshes an already auto-hidden Dock so a currently revealed Dock
        // closes immediately instead of waiting for the pointer to leave its
        // edge. The long delay makes that edge reveal effectively disabled
        // until the shared control explicitly unlocks the Dock.
        let dock = Process()
        dock.executableURL = URL(fileURLWithPath: "/usr/bin/killall")
        dock.arguments = ["Dock"]
        dock.standardOutput = FileHandle.nullDevice
        dock.standardError = FileHandle.nullDevice
        // macpp:silent-ok Dock refresh is best-effort; the preference writes above remain authoritative.
        try? dock.run()
    }
    private func setSystemChromeHidden(_ hidden: Bool, forceDockRefresh: Bool = false) {
        setMenuBarHidden(hidden)
        setDockAutohide(hidden, forceRefresh: forceDockRefresh && hidden)
        var presentationOptions = NSApp.presentationOptions
        if hidden {
            presentationOptions.insert(.hideDock)
        } else {
            presentationOptions.remove(.hideDock)
        }
        NSApp.presentationOptions = presentationOptions
    }
    private func showPower(on screen: NSScreen) {
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        dismissOtherPopouts(
            keeping: .power,
            preservingFreshNotification: notificationFreshOverlay
        )
        model.selectedTab = 0
        let size = NSSize(width: powerSurfaceWidth, height: powerSurfaceHeight)
        let frame = NSRect(x: leftAttachmentOrigin(on: screen), y: screen.frame.minY + shellFrame, width: size.width, height: size.height)
        let panel = makePanel(frame: frame, activating: true)
        let motion = SurfaceMotionState()
        panel.level = shellWindowLevel
        panel.contentView = NSHostingView(rootView:
            LivingSurface(state: motion, attachment: .bottomLeft) {
                // Match the exact same shoulder-clearing gutter the rail
                // popover's own .power case applies (railPopoverContentGutter
                // leading, powerTrailingInset trailing, powerContentTopInset
                // top, powerContentBottomInset bottom). PowerMenu previously
                // had no outer padding here, so it fell back to SwiftUI's
                // implicit centering and sat visibly higher/off-gutter than
                // the real rail-triggered Power popover it's meant to mirror.
                PowerMenu(model: self.model, motion: motion, close: { [weak self] in self?.closePower() })
                    .padding(.leading, railPopoverContentGutter)
                    .padding(.trailing, powerTrailingInset)
                    .padding(.top, powerContentTopInset)
                    .padding(.bottom, powerContentBottomInset)
                    .frame(width: size.width, height: size.height)
            }
        )
        panel.alphaValue = 1; panel.setFrameOrigin(frame.origin); panel.orderFrontRegardless(); panel.makeKey()
        let owningFrameMotion = frameMotion(for: screen)
        powerWindow = panel; powerMotion = motion; powerFrameMotion = owningFrameMotion
        owningFrameMotion.attach(motion, attachment: .bottomLeft, frame: shellLocalFrame(frame, on: screen), radius: CaelestiaParityTokens.Border.rounding)
        cancelPowerClose()
        // Caelestia's utility wrapper grows vertically from the bottom rim
        // with the same 500 ms expressive spatial curve as its dashboard and
        // launcher—not with the 400 ms horizontal OSD curve.
        reveal(motion, using: .topPopout)
    }
    private func closePower() {
        cancelPowerClose()
        guard let panel = powerWindow else { return }
        let motion = powerMotion
        let owningFrameMotion = powerFrameMotion
        powerWindow = nil; powerMotion = nil; powerFrameMotion = nil
        conceal(motion, using: .topDismiss)
        scheduleRetiringShellPopover(
            panel: panel,
            motion: motion,
            frameMotion: owningFrameMotion,
            // The bottom-left utility uses the bounded top-dismiss profile;
            // retire only after that same sampled contour clock has finished.
            // A shorter retirement left the panel's final reverse shoulder
            // racing the shell rim by one visible frame.
            after: ShellMotion.topDismiss.duration
        )
    }
    private func schedulePowerClose() {
        guard powerCloseTimer == nil else { return }
        powerCloseTimer = Timer.scheduledTimer(withTimeInterval: 0.38, repeats: false) { [weak self] _ in
            Task { @MainActor in self?.closePower() }
        }
    }
    private func cancelPowerClose() { powerCloseTimer?.invalidate(); powerCloseTimer = nil }
    private func resizeRailPopoverIfNeeded(
        _ kind: RailPopoverKind,
        force: Bool = false,
        workspaceSnapshot: WorkspaceInfo? = nil
    ) {
        guard railPopoverKind == kind,
              let panel = railPopoverWindow,
              let screen = panel.screen ?? NSScreen.main else { return }
        let desired = railPopoverSize(
            for: kind,
            on: screen,
            workspaceSnapshot: workspaceSnapshot
        )
        let geometryReference = railPopoverTargetFrame?.size ?? panel.frame.size
        let geometryChanged = abs(desired.width - geometryReference.width) > 0.5
            || abs(desired.height - geometryReference.height) > 0.5
        let workspaceContentChanged: Bool = {
            guard case let .workspace(index) = kind else { return false }
            let current = railPopoverSurface?.workspaceContentOverride
                .flatMap { $0.id == index ? $0 : nil }
            return current != workspaceSnapshot
        }()
        // An empty workspace becoming a one-window workspace keeps the
        // bounded one-row height, but it still replaces the entire content
        // tree. Force the host through the same reconciliation that a hover
        // close/reopen used to provide, even when the outer frame is equal.
        guard geometryChanged || (force && workspaceContentChanged) else { return }
        showRailPopover(
            kind,
            on: screen,
            refreshData: false,
            forceLayout: true,
            workspaceSnapshot: workspaceSnapshot
        )
    }
    private func showRailPopover(
        _ kind: RailPopoverKind,
        on screen: NSScreen,
        refreshData: Bool = true,
        forceLayout: Bool = false,
        workspaceSnapshot: WorkspaceInfo? = nil,
        requireLiveTrigger: Bool = true
    ) {
        cancelDeferredRailPopoverSwitch()
        if kind == .appShelf && powerOwnsDockReveal {
            // A stale bottom-edge hover callback must not reopen the shelf
            // after Power has claimed the handoff corridor.
            return
        }
        powerPopoverTransitionActive = kind == .power
        // Shell controls used to be a separate wide popout. Keep the enum
        // and preview plumbing for compatibility, but never expose that
        // intermediate surface in the live shell: the same entry point now
        // opens Nexus directly.
        if kind == .shell {
            guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
            if railPopoverKind == .shell { retireRailPopoverForSwitch() }
            showLauncherNexus()
            return
        }
        if kind == .appShelf {
            // A shelf with no live windows is not useful and should not leave
            // an empty connected surface at the bottom of the display.
            guard !model.appRailApplications.isEmpty else { return }
        }
        guard !fullscreenShellSurfaceRequestIsSuppressed() else { return }
        let visualTestSession = ProcessInfo.processInfo.environment["MACPP_SHELL_VISUAL_TEST_SESSION"] == "1"
        if requireLiveTrigger,
           refreshData,
           !forceLayout,
           !railPopoverPinned,
           !visualTestSession,
           !railPopoverTriggerIsActive(kind, on: screen) {
            // This is normally a late SwiftUI hover callback. Dropping it is
            // preferable to opening a valid-looking card with no live trigger;
            // the next real enter will arm a fresh intent timer.
            return
        }
        // A late hover-enter can arrive after the same popout is already
        // visible. Treat it as idempotent before any provider refresh so
        // Bluetooth does not rescan merely because the pointer re-entered the
        // card's hit region.
        if railPopoverKind == kind, railPopoverWindow != nil, !forceLayout {
            cancelRailPopoverClose()
            return
        }
        // Validate before cancelling the existing close timer. A late hover
        // callback for a trigger the pointer has already left must not make
        // the old card sticky while it is trying to dismiss.
        cancelRailPopoverClose()
        dismissOtherPopouts(
            keeping: .rail,
            preservingFreshNotification: notificationFreshOverlay
        )
        if let existingWindow = railPopoverWindow {
            let existingDisplay = existingWindow.screen.map(displayIdentifier)
            if existingDisplay != displayIdentifier(screen) {
                // A surface cannot share one local contour coordinate space
                // across two monitors. Retire it on the source display and
                // create it already attached on the destination instead of
                // dragging an orphaned contour between frame overlays.
                retireRailPopoverForSwitch()
            }
        }
        if case .workspace = kind {
            startWorkspacePopoverRefreshTimer()
        } else {
            stopWorkspacePopoverRefreshTimer()
        }
        let resizingCurrentPopover = railPopoverKind == kind
            && railPopoverWindow != nil
            && forceLayout
        let requestedWorkspaceSnapshot: WorkspaceInfo? = {
            guard case let .workspace(index) = kind else { return nil }
            return workspaceSnapshot
                ?? model.workspaces.first(where: { $0.id == index })
        }()
        model.setFrontAppResourceSampling(kind == .activeApp)
        railPopoverTransitionGeneration += 1
        if railPopoverKind == .shell, kind != .shell {
            retireRailPopoverForSwitch()
        }
        if railPopoverWindow != nil, (railPopoverKind == .shell) != (kind == .shell) {
            retireRailPopoverForSwitch()
        }
        // Media is a geometry island in the tall centre lane. Every other
        // trigger lives in the upper workspace/tools cluster or the fixed
        // bottom status cluster, so reusing one panel into or out of Media
        // needs a boundary-aware transition rather than an unconditional
        // shared-panel handoff.
        let crossesMediaBoundary = (railPopoverKind == .media) != (kind == .media)
        // App popouts are a small related family of their own. Keep the
        // handoff animation when moving between two real applications, but
        // retire the surface at the boundary to ordinary status/media cards so
        // an app action card never flies into an unrelated control card.
        let currentIsAppRailPopover: Bool = {
            guard let railPopoverKind else { return false }
            if case .runningApp = railPopoverKind { return true }
            return false
        }()
        let nextIsAppRailPopover: Bool = {
            if case .runningApp = kind { return true }
            return false
        }()
        if railPopoverWindow != nil, currentIsAppRailPopover != nextIsAppRailPopover {
            retireRailPopoverForSwitch()
        }
        if kind == .shell, topVisible { hideTop() }
        if refreshData, kind == .wifi { model.refreshWiFiNetworks() }
        if refreshData,
           kind == .bluetooth,
           ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_NO_BLUETOOTH"] != "1" {
            model.refreshBluetoothDevices()
            // A device that is mid-negotiation right as the panel opens --
            // for example, an audio device reconnecting or another device
            // pairing -- reads back as disconnected on this first
            // query and only settles a moment later, same as the toggle
            // case `bluetoothSettleSchedule` exists for below. One quiet
            // reconcile shortly after catches that without the popout
            // needing to be re-toggled to pick up the real state; skip it
            // if the user has already moved off Bluetooth by then.
            DispatchQueue.main.asyncAfter(deadline: .now() + bluetoothSettleSchedule[0]) { [weak self] in
                guard let self, self.railPopoverKind == .bluetooth else { return }
                self.model.refreshBluetoothDevices(force: true)
            }
        }
        if refreshData, case .workspace = kind {
            // A workspace popover can be opened while its model still holds
            // the previous window list. Start the cheap two-query refresh at
            // the same boundary as the popover construction so the first
            // live window is not dependent on the five-second idle poll.
            model.refreshWorkspaceApps()
        }
        // Keep MacPlusPlus Studio consistent across every display. The centered
        // radial surface tested substantially cleaner in clamshell mode than
        // embedding these controls into the MacBook's camera-housing rail.
        let floatingShell = kind == .shell
        let measuredSize = railPopoverSize(
            for: kind,
            on: screen,
            workspaceSnapshot: requestedWorkspaceSnapshot
        )
        // Caelestia's session/power panel is a drawer that slides in from
        // the right edge of the screen, not a corner card bottom-attached
        // to the rail. `.right` is the same attachment already used by the
        // screen-edge volume/brightness surface, just on this separate
        // window.
        let attachment: SurfaceAttachment = floatingShell
            ? .top
            : (kind == .power
                ? .right
                : (kind == .appShelf ? .bottom : SpaceViewerDirection.attachment))
        // Caelestia keeps the bar popouts and the session drawer in separate
        // wrapper trees. A battery hover therefore must not reuse the same
        // NSPanel when the pointer reaches Power: the destination changes
        // from the left rail's local coordinate space to the right edge. The
        // old reuse path interpolated those two screen-wide origins, making a
        // short Battery card visibly drag across the desktop. Retire the
        // outgoing surface in place and let the new edge surface reveal from
        // its own boundary; both remain alive during their short dismissal /
        // reveal overlap, but neither is translated across the screen.
        if railPopoverWindow != nil,
           let currentAttachment = railPopoverSurface?.attachment,
           currentAttachment != attachment {
            retireRailPopoverForSwitch()
        }
        let pointerY = ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_LOW_POPOVER"] == "1"
            ? screen.frame.minY
            : NSEvent.mouseLocation.y
        // App surfaces follow the icon the pointer entered. The media surface
        // is a display-level glance card, so its anchor is fixed to the
        // display center below rather than inheriting the exact point at
        // which the ticker happened to be entered.
        switch kind {
        case .activeApp, .runningApp:
            railPopoverTriggerY = pointerY
        default:
            railPopoverTriggerY = nil
        }
        // The Bluetooth panel belongs to a fixed rail slot. Anchoring it to
        // the pointer made its height depend on whether the icon was entered
        // from above or below, so always use the icon's actual vertical center.
        let attachmentAnchorY: CGFloat = {
            switch kind {
            // Recomputed against the pill's actual current layout (icon
            // rows grew from 22pt to 24pt tall and the pill gained a
            // battery row below audio), which had drifted out of sync with
            // these constants across several rounds of rail-icon edits --
            // the real source of the pinch/gap misalignment against the
            // wifi/bluetooth/audio icons.
            case .wifi: return screen.frame.minY + 154
            case .bluetooth: return screen.frame.minY + 123
            case .audio: return screen.frame.minY + 94
            // Battery is the pill's bottom-most row, sitting right above
            // Power -- lower than audio by roughly one icon row + the
            // tightened gap to Power. Its low anchor naturally reaches the
            // bottom rim for a tall body instead of leaving a clearance gap.
            case .battery: return screen.frame.minY + 65
            // The clock button's own vertical center -- roughly the middle
            // of its 171..<236 hover band above.
            case .calendar: return screen.frame.minY + 204
            case .media:
                // Keep the preview harness' low-popover mode useful while
                // the normal media surface remains centered on the display.
                return ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_LOW_POPOVER"] == "1"
                    ? screen.frame.minY
                    : screen.frame.midY
            case .workspace(let index):
                // Anchor to the actual workspace button's vertical center
                // instead of the live pointer position. The four buttons sit
                // in a tight stack directly under the shell button, so each
                // index maps to a distinct, fixed row rather than whatever Y
                // the mouse happened to enter from.
                //
                // Both the first center and row pitch come from the same rail
                // metrics that lay these buttons out. This prevents compacting
                // the upper cluster from silently desynchronizing the popover
                // bridge, which historically only broke on workspace 4 after
                // the small per-row error had compounded three times.
                return screen.frame.maxY
                    - SideRailGeometry.firstWorkspaceCenterFromTop
                    - CGFloat(max(0, index - 1)) * SideRailGeometry.workspacePitch
            default: return pointerY
            }
        }()
        // Workspace triggers live directly beneath the top-left shell corner.
        // Clamping their surface to the ordinary 7pt frame allowance made the
        // left extrusion merge into the top rim, producing a large accidental
        // concave cutout above the Apple button. Preserve a full shoulder of
        // vertical clearance so this remains a left-attached surface only.
        let topClearance: CGFloat = {
            switch kind {
            case .workspace:
                // Let each workspace popover sit at its natural, per-icon
                // anchored position (see attachmentAnchorY above) instead of
                // forcing a fixed 76pt gap under the top frame. Bare
                // shellFrame still let spaces 1/2 (closest to the top)
                // clamp flush against the frame with no breathing room at
                // all -- the same contact rule used at the bottom rim is
                // applied here against the top, so it stops that closely without a fixed
                // gap being forced on every workspace regardless of index.
                return shellFrame + 20
            default:
                return shellFrame
            }
        }()
        func placement(for size: NSSize) -> (frame: NSRect, mergeTop: CGFloat, mergeBottom: CGFloat) {
            if kind == .shell {
                if floatingShell {
                    let topInset = displayHasCameraHousing(screen)
                        ? shellTopDepth(on: screen)
                        : shellFrame
                    return (NSRect(
                        x: screen.frame.midX - size.width / 2,
                        y: screen.frame.maxY - topInset - 14 - size.height,
                        width: size.width,
                        height: size.height
                    ), 0, 0)
                }
                return (NSRect(x: screen.frame.minX, y: screen.frame.maxY - size.height, width: size.width, height: size.height), 0, 0)
            }
            if kind == .power {
                // A right-edge drawer, vertically centered, matching
                // caelestia's actual session panel -- a slide-in tab, not a
                // card wedged into the shell's bottom-left corner.
                return (NSRect(
                    x: screen.frame.maxX - size.width,
                    y: screen.frame.midY - size.height / 2,
                    width: size.width,
                    height: size.height
                ), 0, 0)
            }
            if kind == .appShelf {
                // The shelf owns the bottom rim across the active display and
                // grows upward from the same shell frame used by the launcher.
                return (NSRect(
                    x: screen.frame.midX - size.width / 2,
                    y: screen.frame.minY + shellFrame,
                    width: size.width,
                    height: size.height
                ), 0, 0)
            }
            // This is the direct translation of BarPopouts.ClipWrapper: the
            // free position is centered on the trigger, then clamped only by
            // the parent's actual top/bottom edges. There is no artificial
            // bottom floor. When a tall list runs out of room, retain its
            // desired height and carry its lower edge flush to the shell rim;
            // the shared surface shape supplies the reverse fillet there.
            let mergeFillet = CaelestiaParityTokens.Border.smoothing
            let topRim = screen.frame.maxY - shellTopDepth(on: screen)
            let bottomRim = screen.frame.minY + shellFrame
            // Workspace popouts retain their authored top breathing room.
            // Only a card whose own centered/clamped frame actually reaches
            // the lower smoothing band shares the bottom rim; cards with
            // plenty of room keep their trigger position and no reverse
            // fillet is enabled. This avoids inventing a bottom-left landing
            // point for the upper and center rail triggers.
            let topBoundary = topRim - topClearance
            let height = size.height
            let idealY = attachmentAnchorY - height / 2
            let upperY = topBoundary - height
            var y = upperY >= bottomRim
                ? min(upperY, max(bottomRim, idealY))
                : bottomRim
            var mergeTop: CGFloat = 0
            var mergeBottom: CGFloat = 0
            // The smoothing band is a threshold for connection, not a
            // clearance. If the ordinary placement would enter that band,
            // snap the edge to the exact rim and turn on the concave fillet.
            if y - bottomRim <= mergeFillet {
                y = bottomRim
                mergeBottom = mergeFillet
            }
            if topRim - (y + height) <= mergeFillet {
                mergeTop = mergeFillet
                if mergeBottom == 0 {
                    y = topRim - height
                }
            }
            return (
                NSRect(x: leftAttachmentOrigin(on: screen), y: y, width: size.width, height: height),
                mergeTop,
                mergeBottom
            )
        }
        let initialPlacement = placement(for: measuredSize)
        // Grounded popouts already have their lower reverse shoulder painted
        // by the shared shell contour. Remove that geometric shoulder from
        // the *content* envelope only after placement has proven that this
        // particular card is actually on the lower rim. A card near the
        // bottom but still free-standing keeps the full vertical contract.
        let groundedBottomReduction = initialPlacement.mergeBottom > 0.0001
            ? max(
                0,
                surfaceMorphShoulder + railPopoverVerticalGutter
                    - railPopoverGroundedBottomGutter
            )
            : 0
        let groundedSize = groundedBottomReduction > 0.0001
            ? NSSize(
                width: measuredSize.width,
                height: max(1, measuredSize.height - groundedBottomReduction)
            )
            : measuredSize
        let groundedPlacement = placement(for: groundedSize)
        let usesGroundedEnvelope = groundedBottomReduction > 0.0001
            && groundedPlacement.mergeBottom > 0.0001
        let size = usesGroundedEnvelope ? groundedSize : measuredSize
        let placement = usesGroundedEnvelope ? groundedPlacement : initialPlacement
        let target = placement.frame
        let currentRailPopoverKind = railPopoverKind
        let currentRailPopoverFrame = railPopoverWindow?.frame
        let isAppRailKind: (RailPopoverKind) -> Bool = { value in
            switch value {
            case .activeApp, .runningApp: return true
            default: return false
            }
        }
        let crowdedMediaAppBoundary: Bool = {
            guard crossesMediaBoundary,
                  requireLiveTrigger,
                  let currentKind = currentRailPopoverKind,
                  let currentFrame = currentRailPopoverFrame else { return false }
            let isMediaAppBoundary = (currentKind == .media && isAppRailKind(kind))
                || (kind == .media && isAppRailKind(currentKind))
            guard isMediaAppBoundary else { return false }
            return currentFrame
                .insetBy(dx: 0, dy: -railPopoverCrowdedHandoffClearance)
                .intersects(target)
        }()
        if crossesMediaBoundary, railPopoverWindow != nil {
            if crowdedMediaAppBoundary {
                // On a compact display the active-app card can still occupy
                // the media card's vertical neighborhood while its dismissal
                // is painting. Finish that outgoing contour first, then
                // revalidate the live trigger before opening the destination.
                retireRailPopoverForSwitch()
                deferCrowdedRailPopoverSwitch(to: kind, on: screen)
                return
            }
            // On roomier layouts the two target frames are safely separated;
            // keep the existing media-boundary retirement without adding a
            // visible pause to the normal handoff.
            retireRailPopoverForSwitch()
        }
        // Freeze the destination's lower content envelope before any live
        // frame samples arrive. The contour may still interpolate its reverse
        // shoulder, but the card stack must not remeasure around that shoulder
        // on every display-link tick.
        let destinationBottomGutter: CGFloat = kind == .shell
            ? 4
            : (kind == .appShelf
                ? appShelfBottomGutter
                : (placement.mergeBottom > 0.0001
                    ? railPopoverGroundedBottomGutter
                    : surfaceMorphShoulder + railPopoverVerticalGutter))
        if let currentPanel = railPopoverWindow,
           railPopoverKind != nil {
            let travel = hypot(
                target.midX - currentPanel.frame.midX,
                target.midY - currentPanel.frame.midY
            )
            // A shared panel is useful for adjacent rail cards, but it is not
            // a teleporting window. Beyond this local handoff radius, retire
            // the old surface and reveal a new one at its own trigger. This
            // prevents a bottom-left card from visibly crossing the desktop
            // when a delayed hover lands on a distant menu.
            let reuseLimit = min(
                460,
                max(320, screen.frame.height * 0.32)
            )
            if travel > reuseLimit {
                retireRailPopoverForSwitch()
            }
        }
        // Keep the prior destination separate from the panel's instantaneous
        // frame. The expressive panel-switch spline overshoots in both
        // directions: during a shrink its undershoot clips the fixed tree's
        // edge cards, while during a grow its overshoot leaves a transparent
        // tail below the last card. Both are the same clip/host mismatch; the
        // middle cards remain away from the moving boundary. A reused panel
        // whose size changes must use the bounded handoff profile, even if the
        // live frame is currently in the spline's overshoot valley.
        let previousTargetSize = railPopoverTargetFrame?.size
        railPopoverTargetFrame = target
        if let panel = railPopoverWindow, let surface = railPopoverSurface, let motion = railPopoverMotion {
            motion.setSuppressBottomBlobDeformation(kind == .appShelf)
            let owningFrameMotion = frameMotion(for: screen)
            if let previousFrameMotion = railPopoverFrameMotion,
               previousFrameMotion !== owningFrameMotion {
                previousFrameMotion.detach(motion)
            }
            railPopoverFrameMotion = owningFrameMotion
            setPresentedRailGlyph(kind, on: screen)
            railPopoverKind = kind
            // Power used to be the one bottom-attached surface whose
            // controls reached the compositor boundary, which needed a
            // level boost above the frame contour. Now that it's a
            // right-edge drawer like everything else here, it doesn't need
            // that anymore.
            panel.level = shellWindowLevel
            panel.orderFrontRegardless()
            // Keep the surface's two edge topologies in sync. The content
            // view and the shell-wide overlay both crossfade the old
            // silhouette into the new one while the AppKit frame travels;
            // this is the reverse-gutter handoff that makes a bottom/left
            // utility become a side drawer without snapping between cards.
            let previousAttachment = surface.attachment
            let previousSize = previousTargetSize ?? panel.frame.size
            let destinationSizeChanged = abs(target.width - previousSize.width) > 0.5
                || abs(target.height - previousSize.height) > 0.5
                || abs(target.width - panel.frame.width) > 0.5
                || abs(target.height - panel.frame.height) > 0.5
            let transitionMotion: ShellMotion = kind == .appShelf
                ? .sidePopout
                : (previousAttachment != attachment
                    ? .handoff
                    : (destinationSizeChanged ? .handoff : .panelSwitch))
            if kind == .appShelf {
                // App-shelf updates are ordinary bottom-edge resizing. Clear
                // any stale topology state instead of crossfading a rail
                // silhouette into the shelf.
                motion.cancelAttachmentTransition()
            } else if previousAttachment != attachment {
                let liveFrame = shellLocalFrame(panel.frame, on: screen)
                let outgoingFillets = rimMergeFillets(
                    for: liveFrame,
                    on: screen,
                    attachment: previousAttachment
                )
                surface.transitionAttachment(to: attachment)
                let handoffGeneration = motion.beginAttachmentTransition(
                    from: previousAttachment,
                    fromTopFillet: outgoingFillets.top,
                    fromBottomFillet: outgoingFillets.bottom
                )
                DispatchQueue.main.asyncAfter(deadline: .now() + ShellMotion.handoff.duration) { [weak motion] in
                    motion?.finishAttachmentTransition(handoffGeneration)
                }
            } else if motion.morphFromAttachment == nil {
                // A same-kind resize must not interrupt a topology handoff
                // already in flight. With no handoff, explicitly clear any
                // stale delayed cleanup from an earlier transition.
                motion.cancelAttachmentTransition()
            }
            // Keep the reverse shoulder tied to the panel's actual position.
            // The old implementation changed the merge flags inside a
            // disabled transaction to the destination target, so a
            // bottom-connected surface lost its fillet on the first handoff
            // frame even though its window had not cleared the rim. Sampling
            // the live frame is both interruptible and faithful to the
            // BlobGroup smoothing band.
            self.setRimMergeFillets(
                motion,
                for: shellLocalFrame(panel.frame, on: screen),
                on: screen,
                attachment: attachment,
                outgoingAttachment: motion.morphFromAttachment
                    ?? (previousAttachment != attachment ? previousAttachment : nil)
            )
            owningFrameMotion.attach(
                motion,
                attachment: attachment,
                frame: shellLocalFrame(panel.frame, on: screen),
                radius: shellAttachmentRadius(attachment)
            )
            // A reused popover window can change its content while the
            // AppKit frame is still travelling to the next target. Give the
            // replacement one compositor lead frame, then let it animate in
            // alongside the frame. Waiting for the geometry completion made
            // calendar and workspace content visibly arrive late, even
            // though the panel was already in place. This keeps the first
            // frame ordered without changing the panel-switch curve.
            //
            // Keep the destination as the intrinsic layout size. This is the
            // QML split between nonAnimHeight and the animated wrapper height:
            // rows keep their final layout while the outer AppKit clip follows
            // the same display-link frame as the shell contour.
            if !resizingCurrentPopover {
                var layoutTransaction = Transaction(animation: nil)
                layoutTransaction.disablesAnimations = true
                withTransaction(layoutTransaction) {
                    surface.contentSize = CGSize(width: target.width, height: target.height)
                    surface.contentBottomGutter = destinationBottomGutter
                }
                let contentGeneration = motion.beginContentTransition()
                surface.contentDirection = {
                    if case .workspace = kind { return SpaceViewerDirection.content }
                    return popoverContentDirection(from: panel.frame, to: target)
                }()
                if case .workspace = kind {
                    // A kind switch has no old workspace layout to preserve;
                    // seed the incoming content with the snapshot that
                    // determined this destination frame before changing the
                    // visible kind.
                    surface.workspaceContentOverride = requestedWorkspaceSnapshot
                } else {
                    surface.workspaceContentOverride = nil
                }
                // The panel/frame animator owns the physical size and
                // position. Updating the destination kind in a disabled
                // transaction keeps the new content layout from performing a
                // second implicit height/width animation inside that moving
                // viewport; MotionChild reveals it once placement is ready.
                var contentTransaction = Transaction()
                contentTransaction.disablesAnimations = true
                withTransaction(contentTransaction) {
                    surface.kind = kind
                    surface.contentRevision &+= 1
                }
                // The incoming tree is still hidden by the generation gate,
                // so resize the child only after its kind, destination box,
                // and staged data have all been committed and SwiftUI has
                // consumed them on the next run-loop turn. Otherwise the
                // forced host display can paint the outgoing top/bottom cards
                // into the incoming host bounds for one compositor turn.
                scheduleRailPopoverHostResize(
                    panel: panel,
                    motion: motion,
                    size: target.size,
                    generation: railPopoverTransitionGeneration
                )
                if !motion.presented || motion.progress < 0.99 {
                    reveal(motion, using: transitionMotion)
                } else {
                    // Same reuse/kind-switch context as the reveal() branch
                    // above -- the frame below still animates on
                    // .panelSwitch even though the surface was already
                    // presented, so the content fade has to match it here
                    // too. See finishContentTransition's comment.
                    scheduleContentReady(
                        motion,
                        generation: contentGeneration,
                        panel: panel,
                        contentAnimation: transitionMotion.animation
                    )
                }
            }
            if resizingCurrentPopover {
                // This is a live data-size correction, not a card handoff:
                // Bluetooth can settle after opening and workspace/app rows
                // can change while their preview is already visible. Do not
                // reset the content gate or animate a visible card through a
                // moving clip. The small geometry delta is applied in one
                // frame, while the existing destination tree stays mounted.
                railFrameAnimator.cancel()
                panel.setFrame(target, display: true)
                var resizeTransaction = Transaction(animation: nil)
                resizeTransaction.disablesAnimations = true
                withTransaction(resizeTransaction) {
                    // Cancelling the frame driver also cancels its terminal
                    // phase callback. The panel is already at its final frame;
                    // publish that placement or a mid-handoff radio refresh
                    // can leave every row hidden behind the strict gate.
                    motion.surfacePlacementProgress = 1
                    surface.contentSize = CGSize(width: target.width, height: target.height)
                    surface.contentBottomGutter = destinationBottomGutter
                    if case .workspace = kind {
                        surface.workspaceContentOverride = requestedWorkspaceSnapshot
                        surface.contentRevision &+= 1
                    } else {
                        surface.workspaceContentOverride = nil
                    }
                }
                owningFrameMotion.attach(
                    motion,
                    attachment: attachment,
                    frame: shellLocalFrame(target, on: screen),
                    radius: shellAttachmentRadius(attachment)
                )
                self.setRimMergeFillets(
                    motion,
                    for: shellLocalFrame(target, on: screen),
                    on: screen,
                    attachment: attachment,
                    outgoingAttachment: motion.morphFromAttachment
                )
                // SwiftUI consumes the new state on the next main-loop pass;
                // only then resize the fixed host so an old edge layer cannot
                // be displayed into the new, shorter bounds.
                scheduleRailPopoverHostResize(
                    panel: panel,
                    motion: motion,
                    size: target.size,
                    generation: railPopoverTransitionGeneration
                )
                // A model publication can land between creation of a fresh
                // panel and the queued reveal on the next run-loop turn. In
                // that interval the resize branch above is still correct for
                // the frame, but cancelling the animator alone would leave
                // `contentReady` gated forever. Re-arm the same fresh-popout
                // handshake; the generation fence in reveal() invalidates
                // the earlier queued callback.
                motion.noteContentPlacementProgress()
                if !motion.presented {
                    reveal(
                        motion,
                        using: kind == .appShelf ? .sidePopout : .popout,
                        contentLeadDelay: 0
                    )
                }
                return
            }
            // A reused panel can already be fully revealed logically while
            // AppKit is still moving or resizing its physical host. Reset the
            // placement phase for that travel; the display link below advances
            // it on the exact frames that also update the shell contour.
            let startingFrame = panel.frame
            let placementTravel = max(
                hypot(
                    target.midX - startingFrame.midX,
                    target.midY - startingFrame.midY
                ),
                hypot(
                    target.width - startingFrame.width,
                    target.height - startingFrame.height
                )
            )
            var placementTransaction = Transaction()
            placementTransaction.disablesAnimations = true
            withTransaction(placementTransaction) {
                motion.surfacePlacementProgress = placementTravel > 0.5 ? 0 : 1
            }
            railFrameAnimator.animate(
                panel,
                to: target,
                // Keep window geometry and its replacing content on the same
                // curve so reverse shoulders do not appear to lead the card.
                motion: transitionMotion,
                frameChanged: { [weak self, weak screen] current in
                guard let self, let screen else { return }
                // Keep the intrinsic content size stable; only the separate
                // presentation viewport follows the live frame. This avoids
                // both a stretched destination layout and a host/contour
                // mismatch while the panel grows or shrinks.
                owningFrameMotion.update(
                    motion,
                    frame: self.shellLocalFrame(current, on: screen)
                )
                self.setRimMergeFillets(
                    motion,
                    for: self.shellLocalFrame(current, on: screen),
                    on: screen,
                    attachment: attachment,
                    outgoingAttachment: motion.morphFromAttachment
                )
                    let localFrame = self.shellLocalFrame(current, on: screen)
                    motion.sampleBlob(position: CGPoint(x: localFrame.midX, y: localFrame.midY))
                },
                progressChanged: { [weak self, weak panel, weak motion] phase in
                    guard let self, let panel, let motion,
                          self.railPopoverWindow === panel,
                          self.railPopoverMotion === motion else { return }
                    var transaction = Transaction()
                    transaction.disablesAnimations = true
                    withTransaction(transaction) {
                        motion.surfacePlacementProgress = max(0, min(1, phase))
                    }
                    motion.noteContentPlacementProgress()
                },
                completion: { [weak self, weak panel, weak motion] in
                    guard let self, let panel, let motion,
                          self.railPopoverWindow === panel,
                          self.railPopoverMotion === motion else { return }
                    // AppKit has just committed the terminal frame. Let that
                    // frame reach the compositor before the nested card tree
                    // is mounted, avoiding a one-frame measure/paint race at
                    // the end of a reused popout handoff.
                    DispatchQueue.main.async { [weak self, weak panel, weak motion] in
                        guard let self, let panel, let motion,
                              self.railPopoverWindow === panel,
                              self.railPopoverMotion === motion,
                              panel.isVisible else { return }
                        motion.noteContentPlacementProgress()
                    }
                }
            )
            return
        }
        let panel = makePanel(
            frame: target,
            fullscreenPolicy: .allowsNativeFullscreen
        )
        let motion = SurfaceMotionState()
        motion.setSuppressBottomBlobDeformation(kind == .appShelf)
        // Seed the merge state before the surface is ever laid out, so a
        // popout that opens already merged draws its rim fillet on its very
        // first painted frame rather than acquiring it a frame later.
        motion.mergeTopFillet = placement.mergeTop
        motion.mergeBottomFillet = placement.mergeBottom
        // Let the fresh rail surface establish its full morph before rows
        // become visible. Without this, the first narrow seed frame exposes
        // compressed card content at the rail edge.
        motion.strictContentGate = !floatingShell
        let surface = RailPopoverState(kind: kind, attachment: attachment)
        surface.contentSize = CGSize(width: target.width, height: target.height)
        surface.contentBottomGutter = destinationBottomGutter
        surface.workspaceContentOverride = requestedWorkspaceSnapshot
        panel.level = shellWindowLevel
        let popover = RailPopoverView(model: self.model, nexus: self.nexusModel, motion: motion, surface: surface, hoverChanged: { [weak self] inside in
            guard let self else { return }
            if kind == .shell { self.cancelRailPopoverClose() }
            else if inside { self.cancelRailPopoverClose() }
            else { self.scheduleRailPopoverClose() }
        }, openDashboard: { [weak self] in
            guard let self else { return }
            self.retireRailPopoverForSwitch(); self.showTop(tab: 0)
        }, openLauncher: { [weak self] in
            guard let self else { return }
            self.retireRailPopoverForSwitch(); self.showLauncher()
        }, openNexus: { [weak self] in
            guard let self else { return }
            self.retireRailPopoverForSwitch(); self.showLauncherNexus()
        }, toggleMask: { [weak self] in self?.toggleMenuMask() }, paletteChanged: { [weak self] in
            self?.schedulePaletteRefresh()
        }, close: { [weak self] in
            self?.closeRailPopover()
        }, floatingShell: floatingShell, shellHeight: size.height)
        let popoverRoot = Group {
            if floatingShell {
                popover
            } else {
                // This window is reused while the pointer moves through
                // the rail. Its local contour must follow the active
                // panel instead of retaining the attachment with which
                // the window was first created.
                RailPopoverLivingSurface(motion: motion, surface: surface) {
                    popover
                }
            }
        }
        let hostingContainer = DestinationHostingContainer(
            rootView: popoverRoot,
            destinationSize: target.size
        )
        panel.contentView = hostingContainer
        railPopoverHostingContainer = hostingContainer
        panel.alphaValue = 1
        panel.setFrame(target, display: true)
        panel.orderFrontRegardless()
        let owningFrameMotion = frameMotion(for: screen)
        railPopoverWindow = panel; railPopoverMotion = motion; railPopoverFrameMotion = owningFrameMotion
        railPopoverSurface = surface
        setPresentedRailGlyph(kind, on: screen)
        railPopoverKind = kind
        // The shell studio lives inside the existing top frame. It owns its
        // own opaque strip and therefore must not create a second morph in the
        // full-screen frame overlay.
        if kind != .shell {
            owningFrameMotion.attach(motion, attachment: attachment, frame: shellLocalFrame(target, on: screen), radius: shellAttachmentRadius(attachment))
            // The initial placement already knows whether the card is flush
            // with the top/bottom rim. Stamp that same live-frame result after
            // the descriptor is registered so the first rendered border, fill,
            // and clip all receive the reverse curve together instead of
            // acquiring it one frame later.
            setRimMergeFillets(
                motion,
                for: shellLocalFrame(target, on: screen),
                on: screen,
                attachment: attachment
            )
        }
        reveal(
            motion,
            using: floatingShell
                ? .topPopout
                : (kind == .appShelf ? .sidePopout : .popout),
            contentLeadDelay: 0
        )
    }

    private func cancelDeferredRailPopoverSwitch() {
        deferredRailPopoverSwitch?.cancel()
        deferredRailPopoverSwitch = nil
    }

    private func deferCrowdedRailPopoverSwitch(to kind: RailPopoverKind, on screen: NSScreen) {
        cancelDeferredRailPopoverSwitch()
        let generation = railPopoverTransitionGeneration
        let workItem = DispatchWorkItem { [weak self] in
            guard let self,
                  self.railPopoverTransitionGeneration == generation else { return }
            self.deferredRailPopoverSwitch = nil
            guard self.railHoverCandidate == kind,
                  self.railPopoverTriggerIsActive(kind, on: screen) else { return }
            self.showRailPopover(
                kind,
                on: screen,
                refreshData: true,
                requireLiveTrigger: false
            )
        }
        deferredRailPopoverSwitch = workItem
        DispatchQueue.main.asyncAfter(
            deadline: .now() + ShellMotion.dismiss.duration + 0.04,
            execute: workItem
        )
    }

    private func closeRailPopover() {
        cancelDeferredRailPopoverSwitch()
        cancelRailPopoverClose()
        stopWorkspacePopoverRefreshTimer()
        model.setFrontAppResourceSampling(false)
        railPopoverTriggerY = nil
        railPopoverPinned = false
        railPopoverTransitionGeneration += 1
        railFrameAnimator.cancel()
        clearPresentedRailGlyph()
        let closingPower = powerPopoverTransitionActive || railPopoverKind == .power
        guard let panel = railPopoverWindow else {
            if closingPower { powerPopoverTransitionActive = false }
            return
        }
        let motion = railPopoverMotion
        let owningFrameMotion = railPopoverFrameMotion
        // Pair the close profile with whichever reveal profile actually
        // opened this popover. The shelf intentionally shares the exact
        // right-edge slider motion, even though its attachment is at bottom.
        let profile: ShellMotion = {
            guard let railPopoverKind else { return .dismiss }
            switch railPopoverKind {
            case .shell: return .topDismiss
            case .appShelf: return .sideDismiss
            default: return .dismiss
            }
        }()
        railPopoverWindow = nil; railPopoverMotion = nil; railPopoverFrameMotion = nil; railPopoverTargetFrame = nil
        railPopoverSurface = nil; railPopoverKind = nil
        railPopoverHostingContainer = nil
        conceal(motion, using: profile)
        scheduleRetiringShellPopover(
            panel: panel,
            motion: motion,
            frameMotion: owningFrameMotion,
            after: profile.duration
        )
        if closingPower {
            // Keep the lock through the dismissal curve so the shelf cannot
            // appear in the same bottom-edge corridor while Power is leaving.
            DispatchQueue.main.asyncAfter(deadline: .now() + profile.duration) { [weak self] in
                guard let self, self.railPopoverKind != .power else { return }
                self.powerPopoverTransitionActive = false
            }
        }
    }
    private func retireRailPopoverForSwitch() {
        // Geometry-breaking switches still use the ordinary close animation;
        // the deferred retirement prevents the outgoing panel from being
        // torn down while SwiftUI is animating its dismissal.
        closeRailPopover()
    }
    private func scheduleRailPopoverClose() {
        if ProcessInfo.processInfo.environment["MACPP_SHELL_PREVIEW_POPOVER"] != nil { return }
        guard railPopoverKind != .shell else { return }
        // A popover the user deliberately clicked open stays open. Pointer
        // traversal is not a dismissal request.
        guard !railPopoverPinned else { return }
        guard railPopoverCloseTimer == nil else { return }
        railPopoverCloseTimer = Timer.scheduledTimer(withTimeInterval: 0.36, repeats: false) { [weak self] _ in
            Task { @MainActor in self?.closeRailPopover() }
        }
    }
    private func scheduleRailPopoverCloseIfNeeded(on screen: NSScreen) {
        guard let current = railPopoverKind else {
            scheduleRailPopoverClose()
            return
        }
        // A late SwiftUI exit is not authoritative if the pointer is still
        // over the live trigger. This check is especially important when a
        // workspace's view reports exit after its neighbour already entered:
        // otherwise the 0.36s close timer wins while the pointer is stationary
        // and the card appears to stop responding until a full off/on pass.
        if railPopoverTriggerIsActive(current, on: screen)
            || railPopoverTrigger(at: NSEvent.mouseLocation, in: screen.frame) == current {
            cancelRailPopoverClose()
        } else {
            scheduleRailPopoverClose()
        }
    }
    private func cancelRailPopoverClose() { railPopoverCloseTimer?.invalidate(); railPopoverCloseTimer = nil }

    private func startWorkspacePopoverRefreshTimer() {
        guard workspacePopoverRefreshTimer == nil else { return }
        let timer = Timer(timeInterval: 0.75, repeats: true) { [weak self] _ in
            Task { @MainActor [weak self] in
                guard let self,
                      let kind = self.railPopoverKind,
                      case .workspace = kind else {
                    self?.stopWorkspacePopoverRefreshTimer()
                    return
                }
                self.model.refreshWorkspaceApps()
            }
        }
        timer.tolerance = 0.10
        RunLoop.main.add(timer, forMode: .common)
        workspacePopoverRefreshTimer = timer
    }

    private func stopWorkspacePopoverRefreshTimer() {
        workspacePopoverRefreshTimer?.invalidate()
        workspacePopoverRefreshTimer = nil
    }

    private func settleRailPopoverLayout(_ panel: NSPanel) {
        guard let content = panel.contentView else { return }
        content.needsLayout = true
        content.layoutSubtreeIfNeeded()
        content.displayIfNeeded()
    }

    private func scheduleRailPopoverHostResize(
        panel: NSWindow,
        motion: SurfaceMotionState,
        size: CGSize,
        generation: Int
    ) {
        // `@Published` invalidates the SwiftUI tree synchronously but its
        // hosting layout is committed on the next main-loop pass. Defer the
        // one intentional host resize until that pass, and invalidate it if a
        // newer hover retargets the same panel first. This keeps an old card
        // tree from being displayed into a new, shorter host.
        DispatchQueue.main.async { [weak self, weak panel, weak motion] in
            guard let self, let panel, let motion,
                  self.railPopoverWindow === panel,
                  self.railPopoverMotion === motion,
                  self.railPopoverTransitionGeneration == generation else {
                return
            }
            self.railPopoverHostingContainer?.setDestinationSize(size)
            if let panel = panel as? NSPanel {
                self.settleRailPopoverLayout(panel)
            }
        }
    }

    private func railPopoverSize(
        for kind: RailPopoverKind,
        on screen: NSScreen,
        workspaceSnapshot: WorkspaceInfo? = nil
    ) -> NSSize {
        switch kind {
        case .shell:
            return NSSize(
                width: shellStudioWidth,
                height: 72
            )
        case .activeApp:
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: activeAppPopoverContentHeight + leftPopoverVerticalInset * 2
            )
        case .runningApp(let pid):
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: appRailPopoverHeight(
                    for: model.appRailApplications.first(where: { $0.id == pid })
                )
            )
        case .appShelf:
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: appShelfContentHeight + appShelfTopGutter + appShelfBottomGutter
            )
        case .media:
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: mediaPopoverContentHeight + leftPopoverVerticalInset * 2
            )
        case .power: return NSSize(width: sessionDrawerSurfaceWidth, height: sessionDrawerSurfaceHeight)
        case .wifi:
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: wifiPopoverHeight(
                    networkCount: railWiFiNetworks(
                        from: model.knownNetworks,
                        connected: model.connectedNetwork
                    ).count,
                    hasVPN: !model.vpnName.isEmpty,
                    hasHiddenConnection: model.wifiConnected
                        && model.connectedNetwork.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                )
            )
        case .bluetooth:
            // Derived from the same helpers the view uses. This used to repeat
            // an older, narrower name list of its own, so the window and its
            // contents disagreed about how many rows existed.
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: bluetoothPopoverHeight(
                    deviceCount: railBluetoothDevices(from: model.bluetoothDevices).count
                )
            )
        case .audio:
            // This is the actual AppKit window size -- it must track the
            // RailPopoverView.width/height case above or the panel keeps
            // rendering at its old dimensions no matter what the SwiftUI
            // content asks for. The visible route budget is shared by both
            // paths; extra devices scroll inside the fixed viewport.
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: audioPopoverContentHeight(
                    outputCount: nexusModel.outputDevices.count,
                    inputCount: nexusModel.inputDevices.count
                ) + leftPopoverVerticalInset * 2
            )
        case .battery:
            // Must track RailPopoverView.width/height's .battery case above,
            // same reason as audio's comment: this is the real AppKit window
            // size, not just the SwiftUI content box.
            return NSSize(width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel), height: batteryPopoverContentHeight + leftPopoverVerticalInset * 2)
        case .calendar:
            // Must track RailPopoverView.width/height's .calendar case above
            // for the same reason as audio/battery's comments -- this is the
            // real AppKit window size, and it now varies with the actual
            // month being shown instead of a fixed worst-case guess.
            return NSSize(width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel), height: calendarPopoverHeight(for: model.now))
        case .workspace(let index):
            let space = workspaceSnapshot.flatMap { $0.id == index ? $0 : nil }
                ?? model.workspaces.first(where: { $0.id == index })
            return NSSize(
                width: caelestiaRailPopoverSurfaceWidth(for: kind, model: model, nexus: nexusModel),
                height: workspacePopoverHeight(windowCount: space?.windows.count ?? 0)
            )
        }
    }
    private func shellLocalFrame(_ panelFrame: NSRect, on screen: NSScreen) -> CGRect {
        CGRect(
            x: panelFrame.minX - screen.frame.minX,
            y: screen.frame.maxY - panelFrame.maxY,
            width: panelFrame.width,
            height: panelFrame.height
        )
    }

    /// Returns the amount of reverse fillet the shared left surface should
    /// have at the current frame position. This is the Swift equivalent of
    /// the BlobGroup's smoothing band: contact is full at the rim and falls
    /// smoothly to zero across 20pt of separation. Sampling the live frame on
    /// every display tick keeps an interrupted handoff attached to the shell
    /// instead of replaying a stale logical target.
    private func rimMergeFillets(
        for localFrame: CGRect,
        on screen: NSScreen,
        attachment: SurfaceAttachment
    ) -> (top: CGFloat, bottom: CGFloat) {
        guard attachment == .left else { return (0, 0) }
        let smoothing = CaelestiaParityTokens.Border.smoothing
        func contact(distance: CGFloat) -> CGFloat {
            let t = min(1, max(0, distance / max(0.001, smoothing)))
            let eased = t * t * (3 - 2 * t)
            return smoothing * (1 - eased)
        }
        let topDistance = localFrame.minY - shellTopDepth(on: screen)
        let bottomDistance = (screen.frame.height - shellFrame) - localFrame.maxY
        return (contact(distance: topDistance), contact(distance: bottomDistance))
    }

    private func setRimMergeFillets(
        _ motion: SurfaceMotionState,
        for localFrame: CGRect,
        on screen: NSScreen,
        attachment: SurfaceAttachment,
        outgoingAttachment: SurfaceAttachment? = nil
    ) {
        let fillets = rimMergeFillets(for: localFrame, on: screen, attachment: attachment)
        let outgoingFillets = outgoingAttachment.map {
            rimMergeFillets(for: localFrame, on: screen, attachment: $0)
        }
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            motion.mergeTopFillet = fillets.top
            motion.mergeBottomFillet = fillets.bottom
            motion.morphFromTopFillet = outgoingFillets?.top ?? 0
            motion.morphFromBottomFillet = outgoingFillets?.bottom ?? 0
        }
    }

    private func popoverContentDirection(from current: NSRect, to target: NSRect) -> PopoverContentDirection {
        let dx = target.midX - current.midX
        let dy = target.midY - current.midY
        guard abs(dx) > 0.5 || abs(dy) > 0.5 else { return .none }

        // AppKit's y-axis grows upward. When the panel travels upward, the
        // incoming card should rise from the bottom; when it travels down,
        // it should descend from the top. Use the dominant axis for mixed
        // moves so a resize-induced nudge cannot fight the real direction.
        if abs(dx) > abs(dy) {
            return dx > 0 ? .trailing : .leading
        }
        return dy > 0 ? .bottom : .top
    }

    private func reveal(
        _ motion: SurfaceMotionState,
        using profile: ShellMotion = .popout,
        contentLeadDelay: TimeInterval = 0
    ) {
        let contentGeneration = motion.beginContentTransition()
        motion.presented = false
        motion.progress = 0
        motion.surfacePlacementProgress = 0
        motion.setContourProgress(0)
        DispatchQueue.main.async { [weak motion] in
            guard let motion,
                  motion.isCurrentContentTransition(contentGeneration) else { return }
            withAnimation(profile.animation) {
                motion.presented = true
                motion.progress = 1
                motion.surfacePlacementProgress = 1
            }
            motion.animateContour(to: 1, using: profile)
        }
        // Let the already-warmed contour/background commit for one short
        // compositor lead frame, then run the information tree on the same
        // authored spatial profile as the panel. The old 200 ms effects fade
        // finished halfway through a 500 ms wrapper reveal, so tall network
        // cards could be fully painted while their window was still growing.
        scheduleContentReady(
            motion,
            generation: contentGeneration,
            contentAnimation: profile.animation,
            leadDelay: contentLeadDelay
        )
    }

    private func scheduleContentReady(
        _ motion: SurfaceMotionState,
        generation: Int,
        panel: NSWindow? = nil,
        contentAnimation: SwiftUI.Animation = ShellMotion.contentIn.animation,
        leadDelay: TimeInterval = 0
    ) {
        let refreshRate = max(
            60,
            panel?.screen?.maximumFramesPerSecond
                ?? NSScreen.main?.maximumFramesPerSecond
                ?? 60
        )
        // Two frames at the active display rate (capped at 20 ms on slower
        // panels) are enough for the warmed contour to commit without making
        // the replacement card visibly lag behind its surface.
        let compositorLead = min(0.020, max(1.0 / 120.0, 2.0 / Double(refreshRate)))
        let delay = max(0, leadDelay) + compositorLead
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
            motion.finishContentTransition(generation, animation: contentAnimation)
        }
        // Watchdog. Keep the repair generation-bound too; an old reveal must
        // never make a newer handoff's content visible while its replacement
        // frame is still moving.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.72) {
            motion.ensurePresentationReady(generation)
        }
    }
    private func conceal(_ motion: SurfaceMotionState?, using profile: ShellMotion = .dismiss) {
        guard let motion else { return }
        _ = motion.beginContentTransition()
        withAnimation(profile.animation) {
            motion.presented = false
            motion.progress = 0
            motion.surfacePlacementProgress = 0
        }
        motion.animateContour(to: 0, using: profile)
    }
    private func add<V: View>(
        _ view: V,
        frame: NSRect,
        ignoresMouse: Bool = false,
        level: NSWindow.Level = shellWindowLevel,
        fullscreenPolicy: ShellFullscreenPolicy = .allowsNativeFullscreen
    ) {
        let window = makePanel(frame: frame, fullscreenPolicy: fullscreenPolicy)
        window.level = level
        window.ignoresMouseEvents = ignoresMouse
        window.contentView = NSHostingView(rootView: view)
        if nativeFullscreenShellQuietMode {
            window.orderOut(nil)
        } else {
            window.orderFrontRegardless()
        }
        windows.append(window)
    }

    /// Tear down a SwiftUI-backed panel in two phases.  Closing an AppKit
    /// window while its NSHostingView is still participating in the current
    /// display-cycle constraint pass can leave a deferred objc_release behind
    /// (the crash signature seen in the recent Mac++ Shell reports).  Removing
    /// the hosting view after ordering the panel out gives SwiftUI no live view
    /// tree to update while AppKit releases the window; the panel itself is
    /// non-released-on-close, so this remains safe for every managed surface.
    private func retirePanel(_ panel: NSWindow) {
        panel.orderOut(nil)
        panel.contentView = nil
        panel.delegate = nil
        panel.close()
    }

    private func makePanel(
        frame: NSRect,
        activating: Bool = false,
        fullscreenPolicy: ShellFullscreenPolicy = .allowsNativeFullscreen,
        allowsTopRimCoverage: Bool = false
    ) -> NSPanel {
        let style: NSWindow.StyleMask = activating ? [.borderless] : [.borderless, .nonactivatingPanel]
        let panel: ShellPanel
        if allowsTopRimCoverage {
            panel = TopAttachedShellPanel(contentRect: frame, styleMask: style, backing: .buffered, defer: false)
        } else {
            panel = ShellPanel(contentRect: frame, styleMask: style, backing: .buffered, defer: false)
        }
        // ShellDelegate owns every panel and releases it through ARC.  AppKit
        // must not also release a managed panel from -close; doing both can
        // surface later as objc_release crashing in the main autorelease pool.
        panel.isReleasedWhenClosed = false
        panel.isOpaque = false; panel.backgroundColor = .clear; panel.hasShadow = false
        panel.level = shellWindowLevel
        panel.collectionBehavior = fullscreenPolicy.collectionBehavior
        panel.hidesOnDeactivate = false; panel.becomesKeyOnlyIfNeeded = !activating
        return panel
    }
}

@main private struct MacPlusPlusShellApp: App {
    @NSApplicationDelegateAdaptor(ShellDelegate.self) var delegate
    var body: some Scene { Settings { EmptyView() } }
}
